-- 和合本全文数据（文件序号见文件名 bible_cuv_data_NN.sql）。先运行 bible_cuv_schema.sql 建表，再按序号依次运行各数据文件。可重复运行（冲突自动跳过）。
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约书亚记', 6, 16, 1, '约瑟的子孙拈阄所得之地是从靠近耶利哥的约但河起，以耶利哥东边的水为界：从耶利哥上去，通过山地的旷野，到伯特利；'),
('CUV', '约书亚记', 6, 16, 2, '又从伯特利到路斯，接连到亚基人的境界，至亚他绿；'),
('CUV', '约书亚记', 6, 16, 3, '又往西下到押利提人的境界，到下伯和仑的境界，直到基色，通到海为止。'),
('CUV', '约书亚记', 6, 16, 4, '约瑟的儿子玛拿西、以法莲就得了他们的地业。'),
('CUV', '约书亚记', 6, 16, 5, '以法莲子孙的境界，按著宗族所得的，记在下面：他们地业的东界是亚他绿亚达到上伯和仑；'),
('CUV', '约书亚记', 6, 16, 6, '往西通到北边的密米他，又向东绕到他纳示罗，又接连到雅挪哈的东边；'),
('CUV', '约书亚记', 6, 16, 7, '从雅挪哈下到亚他绿，又到拿拉，达到耶利哥，通到约但河为止；'),
('CUV', '约书亚记', 6, 16, 8, '从他普亚往西，到加拿河，直通到海为止。这就是以法莲支派按著宗族所得的地业。'),
('CUV', '约书亚记', 6, 16, 9, '另外在玛拿西人地业中得了些城邑和属城的村庄。这都是分给以法莲子孙的。'),
('CUV', '约书亚记', 6, 16, 10, '他们没有赶出住基色的迦南人；迦南人却住在以法莲人中间，成为作苦工的仆人，直到今日。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约书亚记', 6, 17, 1, '玛拿西是约瑟的长子，他的支派拈阄所得之地记在下面。至于玛拿西的长子基列之父（父或作：主）玛吉，因为是勇士就得了基列和巴珊。'),
('CUV', '约书亚记', 6, 17, 2, '玛拿西其余的子孙，按著宗族拈阄分地，就是亚比以谢子孙，希勒子孙，亚斯列子孙，示剑子孙，希弗子孙，示米大子孙；这些按著宗族，都是约瑟儿子玛拿西子孙的男丁。'),
('CUV', '约书亚记', 6, 17, 3, '玛拿西的元孙，玛吉的曾孙，基列的孙子，希弗的儿子西罗非哈没有儿子，只有女儿。他的女儿名叫玛拉、挪阿、曷拉、密迦、得撒；'),
('CUV', '约书亚记', 6, 17, 4, '他们来到祭司以利亚撒和嫩的儿子约书亚并众首领面前，说：耶和华曾吩咐摩西在我们弟兄中分给我们产业。于是约书亚照耶和华所吩咐的，在他们伯叔中，把产业分给他们。'),
('CUV', '约书亚记', 6, 17, 5, '除了约但河东的基列和巴珊地之外，还有十分地归玛拿西，'),
('CUV', '约书亚记', 6, 17, 6, '因为玛拿西的孙女们在玛拿西的孙子中得了产业。基列地是属玛拿西其余的子孙。'),
('CUV', '约书亚记', 6, 17, 7, '玛拿西的境界：从亚设起，到示剑前的密米他，往北到隐他普亚居民之地。'),
('CUV', '约书亚记', 6, 17, 8, '他普亚地归玛拿西，只是玛拿西境界上的他普亚城归以法莲子孙。'),
('CUV', '约书亚记', 6, 17, 9, '其界下到加拿河的南边。在玛拿西城邑中的这些城邑都归以法莲。玛拿西的地界是在河北直通到海为止；'),
('CUV', '约书亚记', 6, 17, 10, '南归以法莲，北归玛拿西，以海为界；北边到亚设，东边到以萨迦。'),
('CUV', '约书亚记', 6, 17, 11, '玛拿西在以萨迦和亚设境内，有伯善和属伯善的镇市，以伯莲和属以伯莲的镇市，多珥的居民和属多珥的镇市；又有三处山冈，就是隐多珥和属隐多珥的镇市；他纳的居民和属他纳的镇市，米吉多的居民和属米吉多的镇市。'),
('CUV', '约书亚记', 6, 17, 12, '只是玛拿西子孙不能赶出这些城的居民，迦南人偏要住在那地。'),
('CUV', '约书亚记', 6, 17, 13, '及至以色列人强盛了，就使迦南人做苦工，没有把他们全然赶出。'),
('CUV', '约书亚记', 6, 17, 14, '约瑟的子孙对约书亚说：耶和华到如今既然赐福与我们，我们也族大人多，你为甚么仅将一阄一段之地分给我们为业呢？'),
('CUV', '约书亚记', 6, 17, 15, '约书亚说：你们如果族大人多，嫌以法莲山地窄小，就可以上比利洗人、利乏音人之地，在树林中砍伐树木。'),
('CUV', '约书亚记', 6, 17, 16, '约瑟的子孙说：那山地容不下我们，并且住平原的迦南人，就是住伯善和属伯善的镇市，并住耶斯列平原的人，都有铁车。'),
('CUV', '约书亚记', 6, 17, 17, '约书亚对约瑟家，就是以法莲和玛拿西人，说：你是族大人多，并且强盛，不可仅有一阄之地，'),
('CUV', '约书亚记', 6, 17, 18, '山地也要归你，虽是树林，你也可以砍伐；靠近之地必归你。迦南人虽有铁车，虽是强盛，你也能把他们赶出去。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约书亚记', 6, 18, 1, '以色列的全会众都聚集在示罗，把会幕设立在那里，那地已经被他们制伏了。'),
('CUV', '约书亚记', 6, 18, 2, '以色列人中其余的七个支派还没有分给他们地业。'),
('CUV', '约书亚记', 6, 18, 3, '约书亚对以色列人说：耶和华─你们列祖的神所赐给你们的地，你们耽延不去得，要到几时呢？'),
('CUV', '约书亚记', 6, 18, 4, '你们每支派当选举三个人，我要打发他们去，他们就要起身走遍那地，按著各支派应得的地业写明（或作：画图），就回到我这里来。'),
('CUV', '约书亚记', 6, 18, 5, '他们要将地分做七分；犹大仍在南方，住在他的境内。约瑟家仍在北方，住在他的境内。'),
('CUV', '约书亚记', 6, 18, 6, '你们要将地分做七分，写明了拿到我这里来。我要在耶和华─我们神面前，为你们拈阄。'),
('CUV', '约书亚记', 6, 18, 7, '利未人在你们中间没有分，因为供耶和华祭司的职任就是他们的产业。迦得支派、流便支派，和玛拿西半支派已经在约但河东得了地业，就是耶和华仆人摩西所给他们的。'),
('CUV', '约书亚记', 6, 18, 8, '划地势的人起身去的时候，约书亚嘱咐他们说：你们去走遍那地，划明地势，就回到我这里来。我要在示罗这里，耶和华面前，为你们拈阄。'),
('CUV', '约书亚记', 6, 18, 9, '他们就去了，走遍那地，按著城邑分做七分，写在册子上，回到示罗营中见约书亚。'),
('CUV', '约书亚记', 6, 18, 10, '约书亚就在示罗，耶和华面前，为他们拈阄。约书亚在那里，按著以色列人的支派，将地分给他们。'),
('CUV', '约书亚记', 6, 18, 11, '便雅悯支派，按著宗族拈阄所得之地，是在犹大、约瑟子孙中间。'),
('CUV', '约书亚记', 6, 18, 12, '他们的北界是从约但河起，往上贴近耶利哥的北边；又往西通过山地，直到伯亚文的旷野；'),
('CUV', '约书亚记', 6, 18, 13, '从那里往南接连到路斯，贴近路斯（路斯就是伯特利），又下到亚他绿亚达，靠近下伯和仑南边的山；'),
('CUV', '约书亚记', 6, 18, 14, '从那里往西，又转向南，从伯和仑南对面的山，直达到犹大人的城基列巴力（基列巴力就是基列耶琳）；这是西界。'),
('CUV', '约书亚记', 6, 18, 15, '南界是从基列耶琳的尽边起，往西达到尼弗多亚的水源；'),
('CUV', '约书亚记', 6, 18, 16, '又下到欣嫩子谷对面山的尽边，就是利乏音谷北边的山；又下到欣嫩谷，贴近耶布斯的南边；又下到隐罗结；'),
('CUV', '约书亚记', 6, 18, 17, '又往北通到隐示麦，达到亚都冥坡对面的基利绿；又下到流便之子波罕的磐石；'),
('CUV', '约书亚记', 6, 18, 18, '又接连到亚拉巴对面，往北下到亚拉巴；'),
('CUV', '约书亚记', 6, 18, 19, '又接连到伯曷拉的北边，直通到盐海的北汊，就是约但河的南头；这是南界。'),
('CUV', '约书亚记', 6, 18, 20, '东界是约但河。这是便雅悯人按著宗族，照他们四围的交界所得的地业。'),
('CUV', '约书亚记', 6, 18, 21, '便雅悯支派按著宗族所得的城邑就是：耶利哥、伯曷拉、伊麦基悉、'),
('CUV', '约书亚记', 6, 18, 22, '伯亚拉巴、洗玛脸、伯特利、'),
('CUV', '约书亚记', 6, 18, 23, '亚文、巴拉、俄弗拉、'),
('CUV', '约书亚记', 6, 18, 24, '基法阿摩尼、俄弗尼、迦巴，共十二座城，还有属城的村庄；'),
('CUV', '约书亚记', 6, 18, 25, '又有基遍、拉玛、比录、'),
('CUV', '约书亚记', 6, 18, 26, '米斯巴、基非拉、摩撒、'),
('CUV', '约书亚记', 6, 18, 27, '利坚、伊利毘勒、他拉拉、'),
('CUV', '约书亚记', 6, 18, 28, '洗拉、以利弗、耶布斯（耶布斯就是耶路撒冷）、基比亚、基列，共十四座城，还有属城的村庄。这是便雅悯人按著宗族所得的地业。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约书亚记', 6, 19, 1, '为西缅支派的人，按著宗族，拈出第二阄。他们所得的地业是在犹大人地业中间。'),
('CUV', '约书亚记', 6, 19, 2, '他们所得为业之地就是：别是巴（或名示巴）、摩拉大、'),
('CUV', '约书亚记', 6, 19, 3, '哈萨书亚、巴拉、以森、'),
('CUV', '约书亚记', 6, 19, 4, '伊利多拉、比土力、何珥玛、'),
('CUV', '约书亚记', 6, 19, 5, '洗革拉、伯玛加博、哈萨苏撒、'),
('CUV', '约书亚记', 6, 19, 6, '伯利巴勿、沙鲁险，共十三座城，还有属城的村庄；'),
('CUV', '约书亚记', 6, 19, 7, '又有亚因、利门、以帖、亚珊，共四座城，还有属城的村庄；'),
('CUV', '约书亚记', 6, 19, 8, '并有这些城邑四围一切的村庄，直到巴拉比珥，就是南地的拉玛。这是西缅支派按著宗族所得的地业。'),
('CUV', '约书亚记', 6, 19, 9, '西缅人的地业是从犹大人地业中得来的；因为犹大人的分过多，所以西缅人在他们的地业中得了地业。'),
('CUV', '约书亚记', 6, 19, 10, '为西布伦人，按著宗族，拈出第三阄。他们地业的境界是到撒立；'),
('CUV', '约书亚记', 6, 19, 11, '往西上到玛拉拉，达到大巴设，又达到约念前的河；'),
('CUV', '约书亚记', 6, 19, 12, '又从撒立往东转向日出之地，到吉斯绿他泊的境界，又通到大比拉，上到雅非亚；'),
('CUV', '约书亚记', 6, 19, 13, '从那里往东，接连到迦特希弗，至以特加汛，通到临门，临门延到尼亚；'),
('CUV', '约书亚记', 6, 19, 14, '又绕过尼亚的北边，转到哈拿顿，通到伊弗他伊勒谷。'),
('CUV', '约书亚记', 6, 19, 15, '还有加他、拿哈拉、伸仑、以大拉、伯利恒，共十二座城，还有属城的村庄。'),
('CUV', '约书亚记', 6, 19, 16, '这些城并属城的村庄就是西布伦人按著宗族所得的地业。'),
('CUV', '约书亚记', 6, 19, 17, '为以萨迦人，按著宗族，拈出第四阄。'),
('CUV', '约书亚记', 6, 19, 18, '他们的境界是到耶斯列、基苏律、书念、'),
('CUV', '约书亚记', 6, 19, 19, '哈弗连、示按、亚拿哈拉、'),
('CUV', '约书亚记', 6, 19, 20, '拉璧、基善、亚别、'),
('CUV', '约书亚记', 6, 19, 21, '利篾、隐干宁、隐哈大、伯帕薛；'),
('CUV', '约书亚记', 6, 19, 22, '又达到他泊、沙哈洗玛、伯示麦，直通到约但河为止，共十六座城，还有属城的村庄。'),
('CUV', '约书亚记', 6, 19, 23, '这些城并属城的村庄就是以萨迦支派按著宗族所得的地业。'),
('CUV', '约书亚记', 6, 19, 24, '为亚设支派，按著宗族，拈出第五阄。'),
('CUV', '约书亚记', 6, 19, 25, '他们的境界是黑甲、哈利、比田、押煞、'),
('CUV', '约书亚记', 6, 19, 26, '亚拉米勒、亚末、米沙勒；往西达到迦密，又到希曷立纳，'),
('CUV', '约书亚记', 6, 19, 27, '转向日出之地，到伯大衮，达到细步纶往北到伊弗他伊勒谷，到伯以墨和尼业，也通到迦步勒的左边；'),
('CUV', '约书亚记', 6, 19, 28, '又到义伯仑、利合、哈们、加拿，直到西顿大城；'),
('CUV', '约书亚记', 6, 19, 29, '转到拉玛和坚固城推罗；又转到何萨，靠近亚革悉一带地方，直通到海；'),
('CUV', '约书亚记', 6, 19, 30, '又有乌玛、亚弗、利合，共二十二座城，还有属城的村庄。'),
('CUV', '约书亚记', 6, 19, 31, '这些城并属城的村庄就是亚设支派按著宗族所得的地业。'),
('CUV', '约书亚记', 6, 19, 32, '为拿弗他利人，按著宗族，拈出第六阄。'),
('CUV', '约书亚记', 6, 19, 33, '他们的境界是从希利弗从撒拿音的橡树，从亚大米尼吉和雅比聂，直到拉共，通到约但河；'),
('CUV', '约书亚记', 6, 19, 34, '又转向西到亚斯纳他泊，从那里通到户割，南边到西布伦，西边到亚设，又向日出之地，达到约但河那里的犹大。'),
('CUV', '约书亚记', 6, 19, 35, '坚固的城就是：西丁、侧耳、哈末、拉甲、基尼烈、'),
('CUV', '约书亚记', 6, 19, 36, '亚大玛、拉玛、夏琐、'),
('CUV', '约书亚记', 6, 19, 37, '基低斯、以得来、隐夏琐、'),
('CUV', '约书亚记', 6, 19, 38, '以利稳、密大伊勒、和琏、伯亚纳、伯示麦，共十九座城，还有属城的村庄。'),
('CUV', '约书亚记', 6, 19, 39, '这些城并属城的村庄就是拿弗他利支派按著宗族所得的地业。'),
('CUV', '约书亚记', 6, 19, 40, '为但支派，按著宗族，拈出第七阄。'),
('CUV', '约书亚记', 6, 19, 41, '他们地业的境界是琐拉、以实陶、伊珥示麦、'),
('CUV', '约书亚记', 6, 19, 42, '沙拉宾、亚雅仑、伊提拉、'),
('CUV', '约书亚记', 6, 19, 43, '以伦、亭拿他、以革伦、'),
('CUV', '约书亚记', 6, 19, 44, '伊利提基、基比顿、巴拉、'),
('CUV', '约书亚记', 6, 19, 45, '伊胡得、比尼比拉、迦特临门、'),
('CUV', '约书亚记', 6, 19, 46, '美耶昆、拉昆，并约帕对面的地界。'),
('CUV', '约书亚记', 6, 19, 47, '但人的地界越过原得的地界；因为但人上去攻取利善，用刀击杀城中的人，得了那城，住在其中，以他们先祖但的名将利善改名为但。'),
('CUV', '约书亚记', 6, 19, 48, '这些城并属城的村庄就是但支派按著宗族所得的地业。'),
('CUV', '约书亚记', 6, 19, 49, '以色列人按著境界分完了地业，就在他们中间将地给嫩的儿子约书亚为业，'),
('CUV', '约书亚记', 6, 19, 50, '是照耶和华的吩咐，将约书亚所求的城，就是以法莲山地的亭拿西拉城，给了他。他就修那城，住在其中。'),
('CUV', '约书亚记', 6, 19, 51, '这就是祭司以利亚撒和嫩的儿子约书亚，并以色列各支派的族长，在示罗会幕门口，耶和华面前，拈阄所分的地业。这样，他们把地分完了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约书亚记', 6, 20, 1, '耶和华晓谕约书亚说：'),
('CUV', '约书亚记', 6, 20, 2, '你吩咐以色列人说：你们要照著我藉摩西所晓谕你们的，为自己设立逃城，'),
('CUV', '约书亚记', 6, 20, 3, '使那无心而误杀人的，可以逃到那里。这些城可以作你们逃避报血仇人的地方。'),
('CUV', '约书亚记', 6, 20, 4, '那杀人的要逃到这些城中的一座城，站在城门口，将他的事情说给城内的长老们听。他们就把他收进城里，给他地方，使他住在他们中间。'),
('CUV', '约书亚记', 6, 20, 5, '若是报血仇的追了他来，长老不可将他交在报血仇的手里；因为他是素无仇恨，无心杀了人的。'),
('CUV', '约书亚记', 6, 20, 6, '他要住在那城里，站在会众面前听审判，等到那时的大祭司死了，杀人的才可以回到本城本家，就是他所逃出来的那城。'),
('CUV', '约书亚记', 6, 20, 7, '于是，以色列人在拿弗他利山地分定加利利的基低斯；在以法莲山地分定示剑；在犹大山地分定基列亚巴（基列亚巴就是希伯仑）；'),
('CUV', '约书亚记', 6, 20, 8, '又在约但河外耶利哥东，从流便支派中，在旷野的平原，设立比悉；从迦得支派中设立基列的拉末；从玛拿西支派中设立巴珊的哥兰。'),
('CUV', '约书亚记', 6, 20, 9, '这都是为以色列众人和在他们中间寄居的外人所分定的地邑，使误杀人的都可以逃到那里，不死在报血仇人的手中，等他站在会众面前听审判。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约书亚记', 6, 21, 1, '那时，利未人的众族长来到祭司以利亚撒和嫩的儿子约书亚，并以色列各支派的族长面前，'),
('CUV', '约书亚记', 6, 21, 2, '在迦南地的示罗对他们说：从前耶和华藉著摩西吩咐给我们城邑居住，并城邑的郊野可以牧养我们的牲畜。'),
('CUV', '约书亚记', 6, 21, 3, '于是以色列人照耶和华所吩咐的，从自己的地业中，将以下所记的城邑和城邑的郊野给了利未人。'),
('CUV', '约书亚记', 6, 21, 4, '为哥辖族拈阄：利未人的祭司、亚伦的子孙，从犹大支派、西缅支派、便雅悯支派的地业中，按阄得了十三座城。'),
('CUV', '约书亚记', 6, 21, 5, '哥辖其余的子孙，从以法莲支派、但支派、玛拿西半支派的地业中，按阄得了十座城。'),
('CUV', '约书亚记', 6, 21, 6, '革顺的子孙，从以萨迦支派、亚设支派、拿弗他利支派、住巴珊的玛拿西半支派的地业中，按阄得了十三座城。'),
('CUV', '约书亚记', 6, 21, 7, '米拉利的子孙，按著宗族，从流便支派、迦得支派、西布伦支派的地业中，按阄得了十二座城。'),
('CUV', '约书亚记', 6, 21, 8, '以色列人照著耶和华藉摩西所吩咐的，将这些城邑和城邑的郊野，按阄分给利未人。'),
('CUV', '约书亚记', 6, 21, 9, '从犹大支派、西缅支派的地业中，将以下所记的城给了利未支派哥辖宗族亚伦的子孙；因为给他们拈出头一阄，'),
('CUV', '约书亚记', 6, 21, 10, 'a'),
('CUV', '约书亚记', 6, 21, 11, '将犹大山地的基列亚巴和四围的郊野给了他们。亚巴是亚衲族的始祖。（基列亚巴就是希伯仑）。'),
('CUV', '约书亚记', 6, 21, 12, '惟将属城的田地和村庄给了耶孚尼的儿子迦勒为业。'),
('CUV', '约书亚记', 6, 21, 13, '以色列人将希伯仑，就是误杀人的逃城和属城的郊野，给了祭司亚伦的子孙；又给他们立拿和属城的郊野，'),
('CUV', '约书亚记', 6, 21, 14, '雅提珥和属城的郊野，以实提莫和属城的郊野，'),
('CUV', '约书亚记', 6, 21, 15, '何仑和属城的郊野，底璧和属城的郊野，'),
('CUV', '约书亚记', 6, 21, 16, '亚因和属城的郊野，淤他和属城的郊野，伯示麦和属城的郊野，共九座城，都是从这二支派中分出来的。'),
('CUV', '约书亚记', 6, 21, 17, '又从便雅悯支派的地业中给了他们基遍和属城的郊野，迦巴和属城的郊野，'),
('CUV', '约书亚记', 6, 21, 18, '亚拿突和属城的郊野，亚勒们和属城的郊野，共四座城。'),
('CUV', '约书亚记', 6, 21, 19, '亚伦子孙作祭司的共有十三座城，还有属城的郊野。'),
('CUV', '约书亚记', 6, 21, 20, '利未支派中哥辖的宗族，就是哥辖其余的子孙，拈阄所得的城有从以法莲支派中分出来的。'),
('CUV', '约书亚记', 6, 21, 21, '以色列人将以法莲山地的示剑，就是误杀人的逃城和属城的郊野，给了他们；又给他们基色和属城的郊野，'),
('CUV', '约书亚记', 6, 21, 22, '基伯先和属城的郊野，伯和仑和属城的郊野，共四座城；'),
('CUV', '约书亚记', 6, 21, 23, '又从但支派的地业中给了他们伊利提基和属城的郊野，基比顿和属城的郊野，'),
('CUV', '约书亚记', 6, 21, 24, '亚雅仑和属城的郊野，迦特临门和属城的郊野，共四座城；'),
('CUV', '约书亚记', 6, 21, 25, '又从玛拿西半支派的地业中给了他们他纳和属城的郊野，迦特临门和属城的郊野，共两座城。'),
('CUV', '约书亚记', 6, 21, 26, '哥辖其余的子孙共有十座城，还有属城的郊野。'),
('CUV', '约书亚记', 6, 21, 27, '以色列人又从玛拿西半支派的地业中将巴珊的哥兰，就是误杀人的逃城和属城的郊野，给了利未支派革顺的子孙；又给他们比施提拉和属城的郊野，共两座城；'),
('CUV', '约书亚记', 6, 21, 28, '又从以萨迦支派的地业中给了他们基善和属城的郊野，大比拉和属城的郊野，'),
('CUV', '约书亚记', 6, 21, 29, '耶末和属城的郊野，隐干宁和属城的郊野，共四座城；'),
('CUV', '约书亚记', 6, 21, 30, '又从亚设支派的地业中给了他们米沙勒和属城的郊野，押顿和属城的郊野，'),
('CUV', '约书亚记', 6, 21, 31, '黑甲和属城的郊野，利合和属城的郊野，共四座城；'),
('CUV', '约书亚记', 6, 21, 32, '又从拿弗他利支派的地业中将加利利的基低斯，就是误杀人的逃城和属城的郊野，给了他们；又给他们哈末多珥和属城的郊野，加珥坦和属城的郊野，共三座城。'),
('CUV', '约书亚记', 6, 21, 33, '革顺人按著宗族所得的城，共十三座，还有属城的郊野。'),
('CUV', '约书亚记', 6, 21, 34, '其余利未支派米拉利子孙，从西布伦支派的地业中所得的，就是约念和属城的郊野，加珥他和属城的郊野，'),
('CUV', '约书亚记', 6, 21, 35, '丁拿和属城的郊野，拿哈拉和属城的郊野，共四座城；'),
('CUV', '约书亚记', 6, 21, 36, '又从流便支派的地业中给了他们比悉和属城的郊野，雅杂和属城的郊野，'),
('CUV', '约书亚记', 6, 21, 37, '基底莫和属城的郊野，米法押和属城的郊野，共四座城；'),
('CUV', '约书亚记', 6, 21, 38, '又从迦得支派的地业中，将基列的拉末，就是误杀人的逃城和属城的郊野，给了他们；又给他们玛哈念和属城的郊野，'),
('CUV', '约书亚记', 6, 21, 39, '希实本和属城的郊野，雅谢和属城的郊野，共四座城。'),
('CUV', '约书亚记', 6, 21, 40, '其余利未支派的人，就是米拉利的子孙，按著宗族拈阄所得的，共十二座城。'),
('CUV', '约书亚记', 6, 21, 41, '利未人在以色列人的地业中所得的城，共四十八座，并有属城的郊野。'),
('CUV', '约书亚记', 6, 21, 42, '这些城四围都有属城的郊野，城城都是如此。'),
('CUV', '约书亚记', 6, 21, 43, '这样，耶和华将从前向他们列祖起誓所应许的全地赐给以色列人，他们就得了为业，住在其中。'),
('CUV', '约书亚记', 6, 21, 44, '耶和华照著向他们列祖起誓所应许的一切话，使他们四境平安；他们一切仇敌中，没有一人在他们面前站立得住。耶和华把一切仇敌都交在他们手中。'),
('CUV', '约书亚记', 6, 21, 45, '耶和华应许赐福给以色列家的话一句也没有落空，都应验了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约书亚记', 6, 22, 1, '当时，约书亚召了流便人、迦得人，和玛拿西半支派的人来，'),
('CUV', '约书亚记', 6, 22, 2, '对他们说：耶和华仆人摩西所吩咐你们的，你们都遵守了；我所吩咐你们的，你们也都听从了。'),
('CUV', '约书亚记', 6, 22, 3, '你们这许多日子，总没有撇离你们的弟兄，直到今日，并守了耶和华─你们神所吩咐你们当守的。'),
('CUV', '约书亚记', 6, 22, 4, '如今耶和华─你们神照著他所应许的，使你们弟兄得享平安，现在可以转回你们的帐棚，到耶和华的仆人摩西在约但河东所赐你们为业之地。'),
('CUV', '约书亚记', 6, 22, 5, '只要切切的谨慎遵行耶和华仆人摩西所吩咐你们的诫命律法，爱耶和华─你们的神，行他一切的道，守他的诫命，专靠他，尽心尽性事奉他。'),
('CUV', '约书亚记', 6, 22, 6, '于是约书亚为他们祝福，打发他们去，他们就回自己的帐棚去了。'),
('CUV', '约书亚记', 6, 22, 7, '玛拿西那半支派，摩西早已在巴珊分给他们地业。这半支派，约书亚在约但河西，在他们弟兄中，分给他们地业。约书亚打发他们回帐棚的时候为他们祝福，'),
('CUV', '约书亚记', 6, 22, 8, '对他们说：你们带许多财物，许多牲畜和金、银、铜、铁，并许多衣服，回你们的帐棚去，要将你们从仇敌夺来的物，与你们众弟兄同分。'),
('CUV', '约书亚记', 6, 22, 9, '于是流便人、迦得人、玛拿西半支派的人从迦南地的示罗起行，离开以色列人，回往他们得为业的基列地，就是照耶和华藉摩西所吩咐的得了为业之地。'),
('CUV', '约书亚记', 6, 22, 10, '流便人、迦得人，和玛拿西半支派的人到了靠近约但河的一带迦南地，就在约但河那里筑了一座坛；那坛看著高大。'),
('CUV', '约书亚记', 6, 22, 11, '以色列人听说流便人、迦得人、玛拿西半支派的人靠近约但河边，在迦南地属以色列人的那边筑了一座坛。'),
('CUV', '约书亚记', 6, 22, 12, '全会众一听见，就聚集在示罗，要上去攻打他们。'),
('CUV', '约书亚记', 6, 22, 13, '以色列人打发祭司以利亚撒的儿子非尼哈，往基列地去见流便人、迦得人、玛拿西半支派的人；'),
('CUV', '约书亚记', 6, 22, 14, '又打发十个首领与非尼哈同去，就是以色列每支派的一个首领，都是以色列军中的统领。'),
('CUV', '约书亚记', 6, 22, 15, '他们到了基列地，见流便人、迦得人，和玛拿西半支派的人，对他们说：'),
('CUV', '约书亚记', 6, 22, 16, '耶和华全会众这样说，你们今日转去不跟从耶和华，干犯以色列的神，为自己筑一座坛，悖逆了耶和华，这犯的是甚么罪呢？'),
('CUV', '约书亚记', 6, 22, 17, '从前拜毘珥的罪孽还算小么？虽然瘟疫临到耶和华的会众，到今日我们还没有洗净这罪。'),
('CUV', '约书亚记', 6, 22, 18, '你们今日竟转去不跟从耶和华么？你们今日既悖逆耶和华，明日他必向以色列全会众发怒。'),
('CUV', '约书亚记', 6, 22, 19, '你们所得为业之地，若嫌不洁净，就可以过到耶和华之地，就是耶和华的帐幕所住之地，在我们中间得地业。只是不可悖逆耶和华，也不可得罪我们，在耶和华─我们神的坛以外为自己筑坛。'),
('CUV', '约书亚记', 6, 22, 20, '从前谢拉的曾孙亚干岂不是在那当灭的物上犯了罪，就有忿怒临到以色列全会众么？那人在所犯的罪中不独一人死亡。'),
('CUV', '约书亚记', 6, 22, 21, '于是流便人、迦得人、玛拿西半支派的人回答以色列军中的统领说：'),
('CUV', '约书亚记', 6, 22, 22, '大能者神耶和华！大能者神耶和华！他是知道的！以色列人也必知道！我们若有悖逆的意思，或是干犯耶和华（愿你今日不保佑我们），'),
('CUV', '约书亚记', 6, 22, 23, '为自己筑坛，要转去不跟从耶和华，或是要将燔祭、素祭、平安祭献在坛上，愿耶和华亲自讨我们的罪。'),
('CUV', '约书亚记', 6, 22, 24, '我们行这事并非无故，是特意做的，说：恐怕日后你们的子孙对我们的子孙说：你们与耶和华─以色列的神有何关涉呢？'),
('CUV', '约书亚记', 6, 22, 25, '因为耶和华把约但河定为我们和你们这流便人、迦得人的交界，你们与耶和华无分了。这样，你们的子孙就使我们的子孙不再敬畏耶和华了。'),
('CUV', '约书亚记', 6, 22, 26, '因此我们说：不如为自己筑一座坛，不是为献燔祭，也不是为献别的祭，'),
('CUV', '约书亚记', 6, 22, 27, '乃是为你我中间和你我后人中间作证据，好叫我们也在耶和华面前献燔祭、平安祭，和别的祭事奉他，免得你们的子孙日后对我们的子孙说，你们与耶和华无分了。'),
('CUV', '约书亚记', 6, 22, 28, '所以我们说：日后你们对我们，或对我们的后人这样说，我们就可以回答说，你们看我们列祖所筑的坛是耶和华坛的样式；这并不是为献燔祭，也不是为献别的祭，乃是为作你我中间的证据。'),
('CUV', '约书亚记', 6, 22, 29, '我们在耶和华─我们神帐幕前的坛以外，另筑一座坛，为献燔祭、素祭，和别的祭，悖逆耶和华，今日转去不跟从他，我们断没有这个意思。'),
('CUV', '约书亚记', 6, 22, 30, '祭司非尼哈与会中的首领，就是与他同来以色列军中的统领，听见流便人、迦得人、玛拿西人所说的话，就都以为美。'),
('CUV', '约书亚记', 6, 22, 31, '祭司以利亚撒的儿子非尼哈对流便人、迦得人、玛拿西人说：今日我们知道耶和华在我们中间，因为你们没有向他犯了这罪。现在你们救以色列人脱离耶和华的手了。'),
('CUV', '约书亚记', 6, 22, 32, '祭司以利亚撒的儿子非尼哈与众首领离了流便人、迦得人，从基列地回往迦南地，到了以色列人那里，便将这事回报他们。'),
('CUV', '约书亚记', 6, 22, 33, '以色列人以这事为美，就称颂神，不再提上去攻打流便人、迦得人、毁坏他们所住的地了。'),
('CUV', '约书亚记', 6, 22, 34, '流便人、迦得人给坛起名叫证坛，意思说：这坛在我们中间证明耶和华是神。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约书亚记', 6, 23, 1, '耶和华使以色列人安静，不与四围的一切仇敌争战，已经多日。约书亚年纪老迈，'),
('CUV', '约书亚记', 6, 23, 2, '就把以色列众人的长老、族长、审判官，并官长都召了来，对他们说：我年纪已经老迈。'),
('CUV', '约书亚记', 6, 23, 3, '耶和华─你们的神因你们的缘故向那些国所行的一切事，你们亲眼看见了，因那为你们争战的是耶和华─你们的神。'),
('CUV', '约书亚记', 6, 23, 4, '我所剪除和所剩下的各国，从约但河起到日落之处的大海，我已经拈阄分给你们各支派为业。'),
('CUV', '约书亚记', 6, 23, 5, '耶和华─你们的神必将他们从你们面前赶出去，使他们离开你们，你们就必得他们的地为业，正如耶和华─你们的神所应许的。'),
('CUV', '约书亚记', 6, 23, 6, '所以，你们要大大壮胆，谨守遵行写在摩西律法书上的一切话，不可偏离左右。'),
('CUV', '约书亚记', 6, 23, 7, '不可与你们中间所剩下的这些国民搀杂。他们的神，你们不可提他的名，不可指著他起誓，也不可事奉、叩拜；'),
('CUV', '约书亚记', 6, 23, 8, '只要照著你们到今日所行的，专靠耶和华─你们的神。'),
('CUV', '约书亚记', 6, 23, 9, '因为耶和华已经把又大又强的国民从你们面前赶出；直到今日，没有一人在你们面前站立得住。'),
('CUV', '约书亚记', 6, 23, 10, '你们一人必追赶千人，因耶和华─你们的神照他所应许的，为你们争战。'),
('CUV', '约书亚记', 6, 23, 11, '你们要分外谨慎，爱耶和华─你们的神。'),
('CUV', '约书亚记', 6, 23, 12, '你们若稍微转去，与你们中间所剩下的这些国民联络，彼此结亲，互相往来，'),
('CUV', '约书亚记', 6, 23, 13, '你们要确实知道，耶和华─你们的神必不再将他们从你们眼前赶出；他们却要成为你们的网罗、机槛、肋上的鞭、眼中的刺，直到你们在耶和华─你们神所赐的这美地上灭亡。'),
('CUV', '约书亚记', 6, 23, 14, '我现在要走世人必走的路。你们是一心一意的知道，耶和华─你们神所应许赐福与你们的话没有一句落空，都应验在你们身上了。'),
('CUV', '约书亚记', 6, 23, 15, '耶和华─你们神所应许的一切福气怎样临到你们身上，耶和华也必照样使各样祸患临到你们身上，直到把你们从耶和华─你们神所赐的这美地上除灭。'),
('CUV', '约书亚记', 6, 23, 16, '你们若违背耶和华─你们神吩咐你们所守的约，去事奉别神，叩拜他，耶和华的怒气必向你们发作，使你们在他所赐的美地上速速灭亡。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约书亚记', 6, 24, 1, '约书亚将以色列的众支派聚集在示剑，召了以色列的长老、族长、审判官，并官长来，他们就站在神面前。'),
('CUV', '约书亚记', 6, 24, 2, '约书亚对众民说：耶和华─以色列的神如此说：古时你们的列祖，就是亚伯拉罕和拿鹤的父亲他拉，住在大河那边事奉别神，'),
('CUV', '约书亚记', 6, 24, 3, '我将你们的祖宗亚伯拉罕从大河那边带来，领他走遍迦南全地，又使他的子孙众多，把以撒赐给他；'),
('CUV', '约书亚记', 6, 24, 4, '又把雅各和以扫赐给以撒，将西珥山赐给以扫为业；后来雅各和他的子孙下到埃及去了。'),
('CUV', '约书亚记', 6, 24, 5, '我差遣摩西、亚伦，并照我在埃及中所行的降灾与埃及，然后把你们领出来。'),
('CUV', '约书亚记', 6, 24, 6, '我领你们列祖出埃及，他们就到了红海；埃及人带领车辆马兵追赶你们列祖到红海。'),
('CUV', '约书亚记', 6, 24, 7, '你们列祖哀求耶和华，他就使你们和埃及人中间黑暗了，又使海水淹没埃及人。我在埃及所行的事，你们亲眼见过。你们在旷野也住了许多年日。'),
('CUV', '约书亚记', 6, 24, 8, '我领你们到约但河东亚摩利人所住之地。他们与你们争战，我将他们交在你们手中，你们便得了他们的地为业；我也在你们面前将他们灭绝。'),
('CUV', '约书亚记', 6, 24, 9, '那时，摩押王西拨的儿子巴勒起来攻击以色列人，打发人召了比珥的儿子巴兰来咒诅你们。'),
('CUV', '约书亚记', 6, 24, 10, '我不肯听巴兰的话，所以他倒为你们连连祝福。这样，我便救你们脱离巴勒的手。'),
('CUV', '约书亚记', 6, 24, 11, '你们过了约但河，到了耶利哥；耶利哥人、亚摩利人、比利洗人、迦南人、赫人、革迦撒人、希未人、耶布斯人都与你们争战；我把他们交在你们手里。'),
('CUV', '约书亚记', 6, 24, 12, '我打发黄蜂飞在你们前面，将亚摩利人的二王从你们面前撵出，并不是用你的刀，也不是用你的弓。'),
('CUV', '约书亚记', 6, 24, 13, '我赐给你们地土，非你们所修治的；我赐给你们城邑，非你们所建造的。你们就住在其中，又得吃非你们所栽种的葡萄园、橄榄园的果子。'),
('CUV', '约书亚记', 6, 24, 14, '现在你们要敬畏耶和华，诚心实意的事奉他，将你们列祖在大河那边和在埃及所事奉的神除掉，去事奉耶和华。'),
('CUV', '约书亚记', 6, 24, 15, '若是你们以事奉耶和华为不好，今日就可以选择所要事奉的：是你们列祖在大河那边所事奉的神呢？是你们所住这地的亚摩利人的神呢？至于我和我家，我们必定事奉耶和华。'),
('CUV', '约书亚记', 6, 24, 16, '百姓回答说：我们断不敢离弃耶和华去事奉别神；'),
('CUV', '约书亚记', 6, 24, 17, '因耶和华─我们的神曾将我们和我们列祖从埃及地的为奴之家领出来，在我们眼前行了那些大神迹，在我们所行的道上，所经过的诸国，都保护了我们。'),
('CUV', '约书亚记', 6, 24, 18, '耶和华又把住此地的亚摩利人都从我们面前赶出去。所以，我们必事奉耶和华，因为他是我们的神。'),
('CUV', '约书亚记', 6, 24, 19, '约书亚对百姓说：你们不能事奉耶和华；因为他是圣洁的神，是忌邪的神，必不赦免你们的过犯罪恶。'),
('CUV', '约书亚记', 6, 24, 20, '你们若离弃耶和华去事奉外邦神，耶和华在降福之后，必转而降祸与你们，把你们灭绝。'),
('CUV', '约书亚记', 6, 24, 21, '百姓回答约书亚说：不然，我们定要事奉耶和华。'),
('CUV', '约书亚记', 6, 24, 22, '约书亚对百姓说：你们选定耶和华，要事奉他，你们自己作见证罢！他们说：我们愿意作见证。'),
('CUV', '约书亚记', 6, 24, 23, '约书亚说：你们现在要除掉你们中间的外邦神，专心归向耶和华─以色列的神。'),
('CUV', '约书亚记', 6, 24, 24, '百姓回答约书亚说：我们必事奉耶和华─我们的神，听从他的话。'),
('CUV', '约书亚记', 6, 24, 25, '当日，约书亚就与百姓立约，在示剑为他们立定律例典章。'),
('CUV', '约书亚记', 6, 24, 26, '约书亚将这些话都写在神的律法书上，又将一块大石头立在橡树下耶和华的圣所旁边。'),
('CUV', '约书亚记', 6, 24, 27, '约书亚对百姓说：看哪，这石头可以向我们作见证；因为是听见了耶和华所吩咐我们的一切话，倘或你们背弃你们的神，这石头就可以向你们作见证（倘或云云：或作所以要向你们作见证，免得你们背弃耶和华─你们的神）。'),
('CUV', '约书亚记', 6, 24, 28, '于是约书亚打发百姓各归自己的地业去了。'),
('CUV', '约书亚记', 6, 24, 29, '这些事以后，耶和华的仆人嫩的儿子约书亚，正一百一十岁，就死了。'),
('CUV', '约书亚记', 6, 24, 30, '以色列人将他葬在他地业的境内，就是在以法莲山地的亭拿西拉，在迦实山的北边。'),
('CUV', '约书亚记', 6, 24, 31, '约书亚在世和约书亚死后，那些知道耶和华为以色列人所行诸事的长老还在的时候，以色列人事奉耶和华。'),
('CUV', '约书亚记', 6, 24, 32, '以色列人从埃及所带来约瑟的骸骨，葬埋在示剑，就是在雅各从前用一百块银子向示剑的父亲、哈抹的子孙所买的那块地里；这就作了约瑟子孙的产业。'),
('CUV', '约书亚记', 6, 24, 33, '亚伦的儿子以利亚撒也死了，就把他葬在他儿子非尼哈所得、以法莲山地的小山上。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '士师记', 7, 1, 1, '约书亚死后，以色列人求问耶和华说：我们中间谁当首先上去攻击迦南人，与他们争战？'),
('CUV', '士师记', 7, 1, 2, '耶和华说：犹大当先上去，我已将那地交在他手中。'),
('CUV', '士师记', 7, 1, 3, '犹大对他哥哥西缅说：请你同我到拈阄所得之地去，好与迦南人争战；以后我也同你到你拈阄所得之地去。于是西缅与他同去。'),
('CUV', '士师记', 7, 1, 4, '犹大就上去；耶和华将迦南人和比利洗人交在他们手中。他们在比色击杀了一万人，'),
('CUV', '士师记', 7, 1, 5, '又在那里遇见亚多尼比色，与他争战，杀败迦南人和比利洗人。'),
('CUV', '士师记', 7, 1, 6, '亚多尼比色逃跑；他们追赶，拿住他，砍断他手脚的大姆指。'),
('CUV', '士师记', 7, 1, 7, '亚多尼比色说：从前有七十个王，手脚的大姆指都被我砍断，在我桌子底下拾取零碎食物。现在神按著我所行的报应我了。于是他们将亚多尼比色带到耶路撒冷，他就死在那里。'),
('CUV', '士师记', 7, 1, 8, '犹大人攻打耶路撒冷，将城攻取，用刀杀了城内的人，并且放火烧城。'),
('CUV', '士师记', 7, 1, 9, '后来犹大人下去，与住山地、南地，和高原的迦南人争战。'),
('CUV', '士师记', 7, 1, 10, '犹大人去攻击住希伯仑的迦南人，杀了示筛、亚希幔、挞买。希伯仑从前名叫基列亚巴。'),
('CUV', '士师记', 7, 1, 11, '他们从那里去攻击底壁的居民；底壁从前名叫基列西弗。'),
('CUV', '士师记', 7, 1, 12, '迦勒说：谁能攻打基列西弗，将城夺取，我就把我女儿押撒给他为妻。'),
('CUV', '士师记', 7, 1, 13, '迦勒兄弟基纳斯的儿子俄陀聂夺取了那城，迦勒就把女儿押撒给他为妻。'),
('CUV', '士师记', 7, 1, 14, '押撒过门的时候，劝丈夫向他父亲求一块田。押撒一下驴，迦勒问他说：你要甚么？'),
('CUV', '士师记', 7, 1, 15, '他说：求你赐福给我，你既将我安置在南地，求你也给我水泉。迦勒就把上泉下泉赐给他。'),
('CUV', '士师记', 7, 1, 16, '摩西的内兄（或译：岳父）是基尼人，他的子孙与犹大人一同离了棕树城，往亚拉得以南的犹大旷野去，就住在民中。'),
('CUV', '士师记', 7, 1, 17, '犹大和他哥哥西缅同去，击杀了住洗法的迦南人，将城尽行毁灭，那城的名便叫何珥玛。'),
('CUV', '士师记', 7, 1, 18, '犹大又取了迦萨和迦萨的四境，亚实基伦和亚实基伦的四境，以革伦和以革伦的四境。'),
('CUV', '士师记', 7, 1, 19, '耶和华与犹大同在，犹大就赶出山地的居民，只是不能赶出平原的居民，因为他们有铁车。'),
('CUV', '士师记', 7, 1, 20, '以色列人照摩西所说的，将希伯仑给了迦勒；迦勒就从那里赶出亚衲族的三个族长。'),
('CUV', '士师记', 7, 1, 21, '便雅悯人没有赶出住耶路撒冷的耶布斯人。耶布斯人仍在耶路撒冷与便雅悯人同住，直到今日。'),
('CUV', '士师记', 7, 1, 22, '约瑟家也上去攻打伯特利；耶和华与他们同在。'),
('CUV', '士师记', 7, 1, 23, '约瑟家打发人去窥探伯特利（那城起先名叫路斯）。'),
('CUV', '士师记', 7, 1, 24, '窥探的人看见一个人从城里出来，就对他说：求你将进城的路指示我们，我们必恩待你。'),
('CUV', '士师记', 7, 1, 25, '那人将进城的路指示他们，他们就用刀击杀了城中的居民，但将那人和他全家放去。'),
('CUV', '士师记', 7, 1, 26, '那人往赫人之地去，筑了一座城，起名叫路斯。那城到如今还叫这名。'),
('CUV', '士师记', 7, 1, 27, '玛拿西没有赶出伯善和属伯善乡村的居民，他纳和属他纳乡村的居民，多珥和属多珥乡村的居民，以伯莲和属以伯莲乡村的居民，米吉多和属米吉多乡村的居民；迦南人却执意住在那些地方。'),
('CUV', '士师记', 7, 1, 28, '及至以色列强盛了，就使迦南人作苦工，没有把他们全然赶出。'),
('CUV', '士师记', 7, 1, 29, '以法莲没有赶出住基色的迦南人。于是迦南人仍住在基色，在以法莲中间。'),
('CUV', '士师记', 7, 1, 30, '西布伦没有赶出基伦的居民和拿哈拉的居民。于是迦南人仍住在西布伦中间，成了服苦的人。'),
('CUV', '士师记', 7, 1, 31, '亚设没有赶出亚柯和西顿的居民，亚黑拉和亚革悉的居民，黑巴、亚弗革与利合的居民。'),
('CUV', '士师记', 7, 1, 32, '于是，亚设因为没有赶出那地的迦南人，就住在他们中间。'),
('CUV', '士师记', 7, 1, 33, '拿弗他利没有赶出伯示麦和伯亚纳的居民，于是拿弗他利就住在那地的迦南人中间；然而伯示麦和伯亚纳的居民成了服苦的人。'),
('CUV', '士师记', 7, 1, 34, '亚摩利人强逼但人住在山地，不容他们下到平原；'),
('CUV', '士师记', 7, 1, 35, '亚摩利人却执意住在希烈山和亚雅伦并沙宾。然而约瑟家胜了他们，使他们成了服苦的人。'),
('CUV', '士师记', 7, 1, 36, '亚摩利人的境界，是从亚克拉滨坡，从西拉而上。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '士师记', 7, 2, 1, '耶和华的使者从吉甲上到波金，对以色列人说：我使你们从埃及上来，领你们到我向你们列祖起誓应许之地。我又说：我永不废弃与你们所立的约。'),
('CUV', '士师记', 7, 2, 2, '你们也不可与这地的居民立约，要拆毁他们的祭坛。你们竟没有听从我的话！为何这样行呢？'),
('CUV', '士师记', 7, 2, 3, '因此我又说：我必不将他们从你们面前赶出；他们必作你们肋下的荆棘。他们的神必作你们的网罗。'),
('CUV', '士师记', 7, 2, 4, '耶和华的使者向以色列众人说这话的时候，百姓就放声而哭。'),
('CUV', '士师记', 7, 2, 5, '于是给那地方起名叫波金（就是哭的意思）。众人在那里向耶和华献祭。'),
('CUV', '士师记', 7, 2, 6, '从前约书亚打发以色列百姓去的时候，他们各归自己的地业，占据地土。'),
('CUV', '士师记', 7, 2, 7, '约书亚在世和约书亚死后，那些见耶和华为以色列人所行大事的长老还在的时候，百姓都事奉耶和华。'),
('CUV', '士师记', 7, 2, 8, '耶和华的仆人、嫩的儿子约书亚，正一百一十岁就死了。'),
('CUV', '士师记', 7, 2, 9, '以色列人将他葬在他地业的境内，就是在以法莲山地的亭拿希烈，在迦实山的北边。'),
('CUV', '士师记', 7, 2, 10, '那世代的人也都归了自己的列祖。后来有别的世代兴起，不知道耶和华，也不知道耶和华为以色列人所行的事。'),
('CUV', '士师记', 7, 2, 11, '以色列人行耶和华眼中看为恶的事，去事奉诸巴力，'),
('CUV', '士师记', 7, 2, 12, '离弃了领他们出埃及地的耶和华─他们列祖的神，去叩拜别神，就是四围列国的神，惹耶和华发怒；'),
('CUV', '士师记', 7, 2, 13, '并离弃耶和华，去事奉巴力和亚斯他录。'),
('CUV', '士师记', 7, 2, 14, '耶和华的怒气向以色列人发作，就把他们交在抢夺他们的人手中，又将他们付与四围仇敌的手中，甚至他们在仇敌面前再不能站立得住。'),
('CUV', '士师记', 7, 2, 15, '他们无论往何处去，耶和华都以灾祸攻击他们，正如耶和华所说的话，又如耶和华向他们所起的誓；他们便极其困苦。'),
('CUV', '士师记', 7, 2, 16, '耶和华兴起士师，士师就拯救他们脱离抢夺他们人的手。'),
('CUV', '士师记', 7, 2, 17, '他们却不听从士师，竟随从叩拜别神，行了邪淫，速速地偏离他们列祖所行的道，不如他们列祖顺从耶和华的命令。'),
('CUV', '士师记', 7, 2, 18, '耶和华为他们兴起士师，就与那士师同在。士师在世的一切日子，耶和华拯救他们脱离仇敌的手。他们因受欺压扰害，就哀声叹气，所以耶和华后悔了。'),
('CUV', '士师记', 7, 2, 19, '及至士师死后，他们就转去行恶，比他们列祖更甚，去事奉叩拜别神，总不断绝顽梗的恶行。'),
('CUV', '士师记', 7, 2, 20, '于是耶和华的怒气向以色列人发作。他说：因这民违背我吩咐他们列祖所守的约，不听从我的话，'),
('CUV', '士师记', 7, 2, 21, '所以约书亚死的时候所剩下的各族，我必不再从他们面前赶出，'),
('CUV', '士师记', 7, 2, 22, '为要借此试验以色列人，看他们肯照他们列祖谨守遵行我的道不肯。'),
('CUV', '士师记', 7, 2, 23, '这样耶和华留下各族，不将他们速速赶出，也没有交付约书亚的手。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '士师记', 7, 3, 1, '耶和华留下这几族，为要试验那不曾知道与迦南争战之事的以色列人，'),
('CUV', '士师记', 7, 3, 2, '好叫以色列的后代又知道又学习未曾晓得的战事。'),
('CUV', '士师记', 7, 3, 3, '所留下的就是非利士的五个首领和一切迦南人、西顿人，并住利巴嫩山的希未人，从巴力黑们山直到哈马口。'),
('CUV', '士师记', 7, 3, 4, '留下这几族，为要试验以色列人，知道他们肯听从耶和华藉摩西吩咐他们列祖的诫命不肯。'),
('CUV', '士师记', 7, 3, 5, '以色列人竟住在迦南人、赫人、亚摩利人、比利洗人、希未人、耶布斯人中间，'),
('CUV', '士师记', 7, 3, 6, '娶他们的女儿为妻，将自己的女儿嫁给他们的儿子，并事奉他们的神。'),
('CUV', '士师记', 7, 3, 7, '以色列人行耶和华眼中看为恶的事，忘记耶和华─他们的神，去事奉诸巴力和亚舍拉，'),
('CUV', '士师记', 7, 3, 8, '所以耶和华的怒气向以色列人发作，就把他们交在米所波大米王古珊利萨田的手中。以色列人服事古珊利萨田八年。'),
('CUV', '士师记', 7, 3, 9, '以色列人呼求耶和华的时候，耶和华就为他们兴起一位拯救者救他们，就是迦勒兄弟基纳斯的儿子俄陀聂。'),
('CUV', '士师记', 7, 3, 10, '耶和华的灵降在他身上，他就作了以色列的士师，出去争战。耶和华将米所波大米王古珊利萨田交在他手中，他便胜了古珊利萨田。'),
('CUV', '士师记', 7, 3, 11, '于是国中太平四十年。基纳斯的儿子俄陀聂死了。'),
('CUV', '士师记', 7, 3, 12, '以色列人又行耶和华眼中看为恶的事，耶和华就使摩押王伊矶伦强盛，攻击以色列人。'),
('CUV', '士师记', 7, 3, 13, '伊矶伦招聚亚扪人和亚玛力人，去攻打以色列人，占据棕树城。'),
('CUV', '士师记', 7, 3, 14, '于是以色列人服事摩押王伊矶伦十八年。'),
('CUV', '士师记', 7, 3, 15, '以色列人呼求耶和华的时候，耶和华就为他们兴起一位拯救者，就是便雅悯人基拉的儿子以笏；他是左手便利的。以色列人托他送礼物给摩押王伊矶伦。'),
('CUV', '士师记', 7, 3, 16, '以笏打了一把两刃的剑，长一肘，带在右腿衣服里面。'),
('CUV', '士师记', 7, 3, 17, '他将礼物献给摩押王伊矶伦（原来伊矶伦极其肥胖）；'),
('CUV', '士师记', 7, 3, 18, '以笏献完礼物，便将抬礼物的人打发走了，'),
('CUV', '士师记', 7, 3, 19, '自己却从靠近吉甲凿石之地回来，说：王啊，我有一件机密事奏告你。王说：回避罢！于是左右侍立的人都退去了。'),
('CUV', '士师记', 7, 3, 20, '以笏来到王面前；王独自一人坐在凉楼上。以笏说：我奉神的命报告你一件事。王就从座位上站起来。'),
('CUV', '士师记', 7, 3, 21, '以笏便伸左手，从右腿上拔出剑来，刺入王的肚腹，'),
('CUV', '士师记', 7, 3, 22, '连剑把都刺进去了。剑被肥肉夹住，他没有从王的肚腹拔出来，且穿通了后身。'),
('CUV', '士师记', 7, 3, 23, '以笏就出到游廊，将楼门尽都关锁。'),
('CUV', '士师记', 7, 3, 24, '以笏出来之后，王的仆人到了，看见楼门关锁，就说：他必是在楼上大解。'),
('CUV', '士师记', 7, 3, 25, '他们等烦了，见仍不开楼门，就拿钥匙开了，不料，他们的主人已死，倒在地上。'),
('CUV', '士师记', 7, 3, 26, '他们耽延的时候，以笏就逃跑了，经过凿石之地，逃到西伊拉；'),
('CUV', '士师记', 7, 3, 27, '到了，就在以法莲山地吹角。以色列人随著他下了山地，他在前头引路，'),
('CUV', '士师记', 7, 3, 28, '对他们说：你们随我来，因为耶和华已经把你们的仇敌摩押人交在你们手中。于是他们跟著他下去，把守约但河的渡口，不容摩押一人过去。'),
('CUV', '士师记', 7, 3, 29, '那时击杀了摩押人约有一万，都是强壮的勇士，没有一人逃脱。'),
('CUV', '士师记', 7, 3, 30, '这样，摩押就被以色列人制伏了。国中太平八十年。'),
('CUV', '士师记', 7, 3, 31, '以笏之后，有亚拿的儿子珊迦，他用赶牛的棍子打死六百非利士人。他也救了以色列人。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '士师记', 7, 4, 1, '以笏死后，以色列人又行耶和华眼中看为恶的事，'),
('CUV', '士师记', 7, 4, 2, '耶和华就把他们付与在夏琐作王的迦南王耶宾手中；他的将军是西西拉，住在外邦人的夏罗设。'),
('CUV', '士师记', 7, 4, 3, '耶宾王有铁车九百辆。他大大欺压以色列人二十年，以色列人就呼求耶和华。'),
('CUV', '士师记', 7, 4, 4, '有一位女先知名叫底波拉，是拉比多的妻，当时作以色列的士师。'),
('CUV', '士师记', 7, 4, 5, '他住在以法莲山地拉玛和伯特利中间，在底波拉的棕树下。以色列人都上他那里去听判断。'),
('CUV', '士师记', 7, 4, 6, '他打发人从拿弗他利的基低斯将亚比挪庵的儿子巴拉召了来，对他说：耶和华─以色列的神吩咐你说：你率领一万拿弗他利和西布伦人上他泊山去。'),
('CUV', '士师记', 7, 4, 7, '我必使耶宾的将军西西拉率领他的车辆和全军往基顺河，到你那里去；我必将他交在你手中。'),
('CUV', '士师记', 7, 4, 8, '巴拉说：你若同我去，我就去；你若不同我去，我就不去。'),
('CUV', '士师记', 7, 4, 9, '底波拉说：我必与你同去，只是你在所行的路上得不著荣耀，因为耶和华要将西西拉交在一个妇人手里。于是底波拉起来，与巴拉一同往基低斯去了。'),
('CUV', '士师记', 7, 4, 10, '巴拉就招聚西布伦人和拿弗他利人到基低斯，跟他上去的有一万人。底波拉也同他上去。'),
('CUV', '士师记', 7, 4, 11, '摩西岳父（或译：内兄）何巴的后裔，基尼人希百曾离开基尼族，到靠近基低斯撒拿音的橡树旁支搭帐棚。'),
('CUV', '士师记', 7, 4, 12, '有人告诉西西拉说：亚比挪庵的儿子巴拉已经上他泊山了。'),
('CUV', '士师记', 7, 4, 13, '西西拉就聚集所有的铁车九百辆，和跟随他的全军，从外邦人的夏罗设出来，到了基顺河。'),
('CUV', '士师记', 7, 4, 14, '底波拉对巴拉说：你起来，今日就是耶和华将西西拉交在你手的日子。耶和华岂不在你前头行么？于是巴拉下了他泊山，跟随他有一万人。'),
('CUV', '士师记', 7, 4, 15, '耶和华使西西拉和他一切车辆全军溃乱，在巴拉面前被刀杀败；西西拉下车步行逃跑。'),
('CUV', '士师记', 7, 4, 16, '巴拉追赶车辆、军队，直到外邦人的夏罗设。西西拉的全军都倒在刀下，没有留下一人。'),
('CUV', '士师记', 7, 4, 17, '只有西西拉步行逃跑，到了基尼人希百之妻雅亿的帐棚，因为夏琐王耶宾与基尼人希百家和好。'),
('CUV', '士师记', 7, 4, 18, '雅亿出来迎接西西拉，对他说：请我主进来，不要惧怕；西西拉就进了他的帐棚。雅忆用被将他遮盖。'),
('CUV', '士师记', 7, 4, 19, '西西拉对雅亿说：我渴了，求你给我一点水喝。雅亿就打开皮袋，给他奶子喝，仍旧把他遮盖。'),
('CUV', '士师记', 7, 4, 20, '西西拉又对雅亿说：请你站在帐棚门口，若有人来问你说：有人在这里没有？你就说：没有。'),
('CUV', '士师记', 7, 4, 21, '西西拉疲乏沉睡。希百的妻雅亿取了帐棚的橛子，手里拿著锤子，轻悄悄地到他旁边，将橛子从他鬓边钉进去，钉入地里。西西拉就死了。'),
('CUV', '士师记', 7, 4, 22, '巴拉追赶西西拉的时候，雅亿出来迎接他说：来罢，我将你所寻找的人给你看。他就进入帐棚，看见西西拉已经死了，倒在地上，橛子还在他鬓中。'),
('CUV', '士师记', 7, 4, 23, '这样，神使迦南王耶宾被以色列人制伏了。'),
('CUV', '士师记', 7, 4, 24, '从此以色列人的手越发有力，胜了迦南王耶宾，直到将他灭绝了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '士师记', 7, 5, 1, '那时，底波拉和亚比挪庵的儿子巴拉作歌，说：'),
('CUV', '士师记', 7, 5, 2, '因为以色列中有军长率领，百姓也甘心牺牲自己，你们应当颂赞耶和华！'),
('CUV', '士师记', 7, 5, 3, '君王啊，要听！王子啊，要侧耳而听！我要向耶和华歌唱；我要歌颂耶和华─以色列的神。'),
('CUV', '士师记', 7, 5, 4, '耶和华啊，你从西珥出来，由以东地行走。那时地震天漏，云也落雨。'),
('CUV', '士师记', 7, 5, 5, '山见耶和华的面就震动，西乃山见耶和华─以色列神的面也是如此。'),
('CUV', '士师记', 7, 5, 6, '在亚拿之子珊迦的时候，又在雅亿的日子，大道无人行走，都是绕道而行。'),
('CUV', '士师记', 7, 5, 7, '以色列中的官长停职，直到我底波拉兴起，等我兴起作以色列的母。'),
('CUV', '士师记', 7, 5, 8, '以色列人选择新神，争战的事就临到城门。那时，以色列四万人中岂能见盾牌枪矛呢？'),
('CUV', '士师记', 7, 5, 9, '我心倾向以色列的首领，他们在民中甘心牺牲自己。你们应当颂赞耶和华！'),
('CUV', '士师记', 7, 5, 10, '骑白驴的、坐绣花毯子的、行路的，你们都当传扬！'),
('CUV', '士师记', 7, 5, 11, '在远离弓箭响声打水之处，人必述说耶和华公义的作为，就是他治理以色列公义的作为。那时耶和华的民下到城门。'),
('CUV', '士师记', 7, 5, 12, '底波拉啊，兴起！兴起！你当兴起，兴起，唱歌。亚比挪庵的儿子巴拉啊，你当奋兴，掳掠你的敌人。'),
('CUV', '士师记', 7, 5, 13, '那时有余剩的贵胄和百姓一同下来；耶和华降临，为我攻击勇士。'),
('CUV', '士师记', 7, 5, 14, '有根本在亚玛力人的地，从以法莲下来的；便雅悯在民中跟随。有掌权的从玛吉下来；有持杖检点民数的从西布伦下来；'),
('CUV', '士师记', 7, 5, 15, '以萨迦的首领与底波拉同来；以萨迦怎样，巴拉也怎样。众人都跟随巴拉冲下平原；在流便的溪水旁有心中定大志的。'),
('CUV', '士师记', 7, 5, 16, '你为何坐在羊圈内听群中吹笛的声音呢？在流便的溪水旁有心中设大谋的。'),
('CUV', '士师记', 7, 5, 17, '基列人安居在约但河外。但人为何等在船上？亚设人在海口静坐，在港口安居。'),
('CUV', '士师记', 7, 5, 18, '西布伦人是拚命敢死的；拿弗他利人在田野的高处也是如此。'),
('CUV', '士师记', 7, 5, 19, '君王都来争战。那时迦南诸王在米吉多水旁的他纳争战，却未得掳掠银钱。'),
('CUV', '士师记', 7, 5, 20, '星宿从天上争战，从其轨道攻击西西拉。'),
('CUV', '士师记', 7, 5, 21, '基顺古河把敌人冲没；我的灵啊，应当努力前行。'),
('CUV', '士师记', 7, 5, 22, '那时壮马驰驱，踢跳，奔腾。'),
('CUV', '士师记', 7, 5, 23, '耶和华的使者说：应当咒诅米罗斯，大大咒诅其中的居民；因为他们不来帮助耶和华，不来帮助耶和华攻击勇士。'),
('CUV', '士师记', 7, 5, 24, '愿基尼人希百的妻雅亿比众妇人多得福气，比住帐棚的妇人更蒙福祉。'),
('CUV', '士师记', 7, 5, 25, '西西拉求水，雅亿给他奶子，用宝贵的盘子给他奶油。'),
('CUV', '士师记', 7, 5, 26, '雅亿左手拿著帐棚的橛子，右手拿著匠人的锤子，击打西西拉，打伤他的头，把他的鬓角打破穿通。'),
('CUV', '士师记', 7, 5, 27, '西西拉在他脚前曲身仆倒，在他脚前曲身倒卧；在那里曲身，就在那里死亡。'),
('CUV', '士师记', 7, 5, 28, '西西拉的母亲从窗户里往外观看，从窗櫺中呼叫说：他的战车为何耽延不来呢？他的车轮为何行得慢呢？'),
('CUV', '士师记', 7, 5, 29, '聪明的宫女安慰他（原文是回答他），他也自言自语地说：'),
('CUV', '士师记', 7, 5, 30, '他们莫非得财而分？每人得了一两个女子？西西拉得了彩衣为掳物，得绣花的彩衣为掠物。这彩衣两面绣花，乃是披在被掳之人颈项上的。'),
('CUV', '士师记', 7, 5, 31, '耶和华啊，愿你的仇敌都这样灭亡！愿爱你的人如日头出现，光辉烈烈！这样，国中太平四十年。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '士师记', 7, 6, 1, '以色列人又行耶和华眼中看为恶的事，耶和华就把他们交在米甸人手里七年。'),
('CUV', '士师记', 7, 6, 2, '米甸人压制以色列人；以色列人因为米甸人，就在山中挖穴、挖洞、建造营寨。'),
('CUV', '士师记', 7, 6, 3, '以色列人每逢撒种之后，米甸人、亚玛力人，和东方人都上来攻打他们，'),
('CUV', '士师记', 7, 6, 4, '对著他们安营，毁坏土产，直到迦萨，没有给以色列人留下食物，牛、羊、驴也没有留下；'),
('CUV', '士师记', 7, 6, 5, '因为那些人带著牲畜帐棚来，像蝗虫那样多，人和骆驼无数，都进入国内，毁坏全地。'),
('CUV', '士师记', 7, 6, 6, '以色列人因米甸人的缘故，极其穷乏，就呼求耶和华。'),
('CUV', '士师记', 7, 6, 7, '以色列人因米甸人的缘故，呼求耶和华，'),
('CUV', '士师记', 7, 6, 8, '耶和华就差遣先知到以色列人那里，对他们说：耶和华─以色列的神如此说：我曾领你们从埃及上来，出了为奴之家，'),
('CUV', '士师记', 7, 6, 9, '救你们脱离埃及人的手，并脱离一切欺压你们之人的手，把他们从你们面前赶出，将他们的地赐给你们；'),
('CUV', '士师记', 7, 6, 10, '又对你们说：我是耶和华─你们的神。你们住在亚摩利人的地，不可敬畏他们的神。你们竟不听从我的话。'),
('CUV', '士师记', 7, 6, 11, '耶和华的使者到了俄弗拉，坐在亚比以谢族人约阿施的橡树下。约阿施的儿子基甸正在酒醡那里打麦子，为要防备米甸人。'),
('CUV', '士师记', 7, 6, 12, '耶和华的使者向基甸显现，对他说：大能的勇士啊，耶和华与你同在！'),
('CUV', '士师记', 7, 6, 13, '基甸说：主啊，耶和华若与我们同在，我们何至遭遇这一切事呢？我们的列祖不是向我们说耶和华领我们从埃及上来么？他那样奇妙的作为在哪里呢？现在他却丢弃我们，将我们交在米甸人手里。'),
('CUV', '士师记', 7, 6, 14, '耶和华观看基甸，说：你靠著你这能力去从米甸人手里拯救以色列人，不是我差遣你去的么？'),
('CUV', '士师记', 7, 6, 15, '基甸说：主啊，我有何能拯救以色列人呢？我家在玛拿西支派中是至贫穷的。我在我父家是至微小的。'),
('CUV', '士师记', 7, 6, 16, '耶和华对他说：我与你同在，你就必击打米甸人，如击打一人一样。'),
('CUV', '士师记', 7, 6, 17, '基甸说：我若在你眼前蒙恩，求你给我一个证据，使我知道与我说话的就是主。'),
('CUV', '士师记', 7, 6, 18, '求你不要离开这里，等我归回将礼物带来供在你面前。主说：我必等你回来。'),
('CUV', '士师记', 7, 6, 19, '基甸去预备了一只山羊羔，用一伊法细面做了无酵饼，将肉放在筐内，把汤盛在壶中，带到橡树下，献在使者面前。'),
('CUV', '士师记', 7, 6, 20, '神的使者吩咐基甸说：将肉和无酵饼放在这磐石上，把汤倒出来。他就这样行了。'),
('CUV', '士师记', 7, 6, 21, '耶和华的使者伸出手内的杖，杖头挨了肉和无酵饼，就有火从磐石中出来，烧尽了肉和无酵饼。耶和华的使者也就不见了。'),
('CUV', '士师记', 7, 6, 22, '基甸见他是耶和华的使者，就说：哀哉！主耶和华啊，我不好了，因为我觌面看见耶和华的使者。'),
('CUV', '士师记', 7, 6, 23, '耶和华对他说：你放心，不要惧怕，你必不至死。'),
('CUV', '士师记', 7, 6, 24, '于是基甸在那里为耶和华筑了一座坛，起名叫耶和华沙龙（就是耶和华赐平安的意思）。（这坛在亚比以谢族的俄弗拉直到如今。）'),
('CUV', '士师记', 7, 6, 25, '当那夜，耶和华吩咐基甸说：你取你父亲的牛来，就是（或译：和）那七岁的第二只牛，并拆毁你父亲为巴力所筑的坛，砍下坛旁的木偶，'),
('CUV', '士师记', 7, 6, 26, '在这磐石（原文是保障）上整整齐齐地为耶和华─你的神筑一座坛，将第二只牛献为燔祭，用你所砍下的木偶作柴。'),
('CUV', '士师记', 7, 6, 27, '基甸就从他仆人中挑了十个人，照著耶和华吩咐他的行了。他因怕父家和本城的人，不敢在白昼行这事，就在夜间行了。'),
('CUV', '士师记', 7, 6, 28, '城里的人清早起来，见巴力的坛拆毁，坛旁的木偶砍下，第二只牛献在新筑的坛上，'),
('CUV', '士师记', 7, 6, 29, '就彼此说：这事是谁做的呢？他们访查之后，就说：这是约阿施的儿子基甸做的。'),
('CUV', '士师记', 7, 6, 30, '城里的人对约阿施说：将你儿子交出来，好治死他；因为他拆毁了巴力的坛，砍下坛旁的木偶。'),
('CUV', '士师记', 7, 6, 31, '约阿施回答站著攻击他的众人说：你们是为巴力争论么？你们要救他么？谁为他争论，趁早将谁治死！巴力若果是神，有人拆毁他的坛，让他为自己争论罢！'),
('CUV', '士师记', 7, 6, 32, '所以当日人称基甸为耶路巴力，意思说：他拆毁巴力的坛，让巴力与他争论。'),
('CUV', '士师记', 7, 6, 33, '那时，米甸人、亚玛力人，和东方人都聚集过河，在耶斯列平原安营。'),
('CUV', '士师记', 7, 6, 34, '耶和华的灵降在基甸身上，他就吹角；亚比以谢族都聚集跟随他。'),
('CUV', '士师记', 7, 6, 35, '他打发人走遍玛拿西地，玛拿西人也聚集跟随他；又打发人去见亚设人、西布伦人、拿弗他利人，他们也都出来与他们会合。'),
('CUV', '士师记', 7, 6, 36, '基甸对神说：你若果照著所说的话，藉我手拯救以色列人，'),
('CUV', '士师记', 7, 6, 37, '我就把一团羊毛放在禾场上：若单是羊毛上有露水，别的地方都是干的，我就知道你必照著所说的话，藉我手拯救以色列人。'),
('CUV', '士师记', 7, 6, 38, '次日早晨基甸起来，见果然是这样；将羊毛挤一挤，从羊毛中拧出满盆的露水来。'),
('CUV', '士师记', 7, 6, 39, '基甸又对神说：求你不要向我发怒，我再说这一次：让我将羊毛再试一次。但愿羊毛是干的，别的地方都有露水。'),
('CUV', '士师记', 7, 6, 40, '这夜神也如此行：独羊毛上是干的，别的地方都有露水。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '士师记', 7, 7, 1, '耶路巴力就是基甸，他和一切跟随的人早晨起来，在哈律泉旁安营。米甸营在他们北边的平原，靠近摩利冈。'),
('CUV', '士师记', 7, 7, 2, '耶和华对基甸说：跟随你的人过多，我不能将米甸人交在他们手中，免得以色列人向我夸大，说：是我们自己的手救了我们。'),
('CUV', '士师记', 7, 7, 3, '现在你要向这些人宣告说：凡惧怕胆怯的，可以离开基列山回去。于是有二万二千人回去，只剩下一万。'),
('CUV', '士师记', 7, 7, 4, '耶和华对基甸说：人还是过多；你要带他们下到水旁，我好在那里为你试试他们。我指点谁说：这人可以同你去，他就可以同你去；我指点谁说：这人不可同你去，他就不可同你去。'),
('CUV', '士师记', 7, 7, 5, '基甸就带他们下到水旁。耶和华对基甸说：凡用舌头舔水，像狗舔的，要使他单站在一处；凡跪下喝水的，也要使他单站在一处。'),
('CUV', '士师记', 7, 7, 6, '于是用手捧著舔水的有三百人，其余的都跪下喝水。'),
('CUV', '士师记', 7, 7, 7, '耶和华对基甸说：我要用这舔水的三百人拯救你们，将米甸人交在你手中；其余的人都可以各归各处去。'),
('CUV', '士师记', 7, 7, 8, '这三百人就带著食物和角；其余的以色列人，基甸都打发他们各归各的帐棚，只留下这三百人。米甸营在他下边的平原里。'),
('CUV', '士师记', 7, 7, 9, '当那夜，耶和华吩咐基甸说：起来，下到米甸营里去，因我已将他们交在你手中。'),
('CUV', '士师记', 7, 7, 10, '倘若你怕下去，就带你的仆人普拉下到那营里去。'),
('CUV', '士师记', 7, 7, 11, '你必听见他们所说的，然后你就有胆量下去攻营。于是基甸带著仆人普拉下到营旁。'),
('CUV', '士师记', 7, 7, 12, '米甸人、亚玛力人，和一切东方人都布散在平原，如同蝗虫那样多。他们的骆驼无数，多如海边的沙。'),
('CUV', '士师记', 7, 7, 13, '基甸到了，就听见一人将梦告诉同伴说：我做了一梦，梦见一个大麦饼滚入米甸营中，到了帐幕，将帐幕撞倒，帐幕就翻转倾覆了。'),
('CUV', '士师记', 7, 7, 14, '那同伴说：这不是别的，乃是以色列人约阿施的儿子基甸的刀；神已将米甸和全军都交在他的手中。'),
('CUV', '士师记', 7, 7, 15, '基甸听见这梦和梦的讲解，就敬拜神，回到以色列营中，说：起来罢！耶和华已将米甸的军队交在你们手中了。'),
('CUV', '士师记', 7, 7, 16, '于是基甸将三百人分作三队，把角和空瓶交在各人手里（瓶内都藏著火把），'),
('CUV', '士师记', 7, 7, 17, '吩咐他们说：你们要看我行事：我到了营的旁边怎样行，你们也要怎样行。'),
('CUV', '士师记', 7, 7, 18, '我和一切跟随我的人吹角的时候，你们也要在营的四围吹角，喊叫说：耶和华和基甸的刀！'),
('CUV', '士师记', 7, 7, 19, '基甸和跟随他的一百人，在三更之初才换更的时候，来到营旁，就吹角，打破手中的瓶。'),
('CUV', '士师记', 7, 7, 20, '三队的人就都吹角，打破瓶子，左手拿著火把，右手拿著角，喊叫说：耶和华和基甸的刀！'),
('CUV', '士师记', 7, 7, 21, '他们在营的四围各站各的地方；全营的人都乱窜。三百人呐喊，使他们逃跑。'),
('CUV', '士师记', 7, 7, 22, '三百人就吹角，耶和华使全营的人用刀互相击杀，逃到西利拉的伯哈示他，直逃到靠近他巴的亚伯米何拉。'),
('CUV', '士师记', 7, 7, 23, '以色列人就从拿弗他利、亚设，和玛拿西全地聚集来追赶米甸人。'),
('CUV', '士师记', 7, 7, 24, '基甸打发人走遍以法莲山地，说：你们下来攻击米甸人，争先把守约但河的渡口，直到伯巴拉。于是以法莲的众人聚集，把守约但河的渡口，直到伯巴拉，'),
('CUV', '士师记', 7, 7, 25, '捉住了米甸人的两个首领：一名俄立，一名西伊伯；将俄立杀在俄立磐石上，将西伊伯杀在西伊伯酒醡那里；又追赶米甸人，将俄立和西伊伯的首级带过约但河，到基甸那里。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '士师记', 7, 8, 1, '以法莲人对基甸说：你去与米甸人争战，没有招我们同去，为甚么这样待我们呢？他们就与基甸大大地争吵。'),
('CUV', '士师记', 7, 8, 2, '基甸对他们说：我所行的岂能比你们所行的呢？以法莲拾取剩下的葡萄不强过亚比以谢所摘的葡萄么？'),
('CUV', '士师记', 7, 8, 3, '神已将米甸人的两个首领俄立和西伊伯交在你们手中；我所行的岂能比你们所行的呢？基甸说了这话，以法莲人的怒气就消了。'),
('CUV', '士师记', 7, 8, 4, '基甸和跟随他的三百人到约但河过渡，虽然疲乏，还是追赶。'),
('CUV', '士师记', 7, 8, 5, '基甸对疏割人说：求你们拿饼来给跟随我的人吃，因为他们疲乏了；我们追赶米甸人的两个王西巴和撒慕拿。'),
('CUV', '士师记', 7, 8, 6, '疏割人的首领回答说：西巴和撒慕拿已经在你手里，你使我们将饼给你的军兵么？'),
('CUV', '士师记', 7, 8, 7, '基甸说：耶和华将西巴和撒慕拿交在我手之后，我就用野地的荆条和枳棘打伤你们。'),
('CUV', '士师记', 7, 8, 8, '基甸从那里上到毗努伊勒，对那里的人也是这样说；毗努伊勒人也与疏割人回答他的话一样。'),
('CUV', '士师记', 7, 8, 9, '他向毗努伊勒人说：我平平安安回来的时候，我必拆毁这楼。'),
('CUV', '士师记', 7, 8, 10, '那时西巴和撒慕拿，并跟随他们的军队都在加各，约有一万五千人，就是东方人全军所剩下的；已经被杀约有十二万拿刀的。'),
('CUV', '士师记', 7, 8, 11, '基甸就由挪巴和约比哈东边，从住帐棚人的路上去，杀败了米甸人的军兵，因为他们坦然无惧。'),
('CUV', '士师记', 7, 8, 12, '西巴和撒慕拿逃跑；基甸追赶他们，捉住米甸的二王西巴和撒慕拿，惊散全军。'),
('CUV', '士师记', 7, 8, 13, '约阿施的儿子基甸由希列斯坡从阵上回来，'),
('CUV', '士师记', 7, 8, 14, '捉住疏割的一个少年人，问他：疏割的首领长老是谁？他就将首领长老七十七个人的名字写出来。'),
('CUV', '士师记', 7, 8, 15, '基甸到了疏割，对那里的人说：你们从前讥诮我说：西巴和撒慕拿已经在你手里，你使我们将饼给跟随你的疲乏人么？ㄤ萑在西巴和撒慕拿在这里。'),
('CUV', '士师记', 7, 8, 16, '于是捉住那城内的长老，用野地的荆条和枳棘责打（原文是指教）疏割人；'),
('CUV', '士师记', 7, 8, 17, '又拆了毗努伊勒的楼，杀了那城里的人。'),
('CUV', '士师记', 7, 8, 18, '基甸问西巴和撒慕拿说：你们在他泊山所杀的人是甚么样式？回答说：他们好像你，各人都有王子的样式。'),
('CUV', '士师记', 7, 8, 19, '基甸说：他们是我同母的弟兄，我指著永生的耶和华起誓，你们从前若存留他们的性命，我如今就不杀你们了。'),
('CUV', '士师记', 7, 8, 20, '于是对他的长子益帖说：你起来杀他们。但益帖因为是童子，害怕，不敢拔刀。'),
('CUV', '士师记', 7, 8, 21, '西巴和撒慕拿说：你自己起来杀我们罢！因为人如何，力量也是如何。基甸就起来，杀了西巴和撒慕拿，夺获他们骆驼项上戴的月牙圈。'),
('CUV', '士师记', 7, 8, 22, '以色列人对基甸说：你既救我们脱离米甸人的手，愿你和你的儿孙管理我们。'),
('CUV', '士师记', 7, 8, 23, '基甸说：我不管理你们，我的儿子也不管理你们，惟有耶和华管理你们。'),
('CUV', '士师记', 7, 8, 24, '基甸又对他们说：我有一件事求你们：请你们各人将所夺的耳环给我。原来仇敌是以实玛利人，都是戴金耳环的。）'),
('CUV', '士师记', 7, 8, 25, '他们说：我们情愿给你。就铺开一件外衣，各人将所夺的耳环丢在其上。'),
('CUV', '士师记', 7, 8, 26, '基甸所要出来的金耳环重一千七百舍客勒金子。此外还有米甸王所戴的月环、耳坠，和所穿的紫色衣服，并骆驼项上的金链子。'),
('CUV', '士师记', 7, 8, 27, '基甸以此制造了一个以弗得，设立在本城俄弗拉。后来以色列人拜那以弗得行了邪淫；这就作了基甸和他全家的网罗。'),
('CUV', '士师记', 7, 8, 28, '这样，米甸人被以色列人制伏了，不敢再抬头。基甸还在的日子，国中太平四十年。'),
('CUV', '士师记', 7, 8, 29, '约阿施的儿子耶路巴力回去，住在自己家里。'),
('CUV', '士师记', 7, 8, 30, '基甸有七十个亲生的儿子，因为他有许多的妻。'),
('CUV', '士师记', 7, 8, 31, '他的妾住在示剑，也给他生了一个儿子。基甸与他起名叫亚比米勒。'),
('CUV', '士师记', 7, 8, 32, '约阿施的儿子基甸，年纪老迈而死，葬在亚比以谢族的俄弗拉，在他父亲约阿施的坟墓里。'),
('CUV', '士师记', 7, 8, 33, '基甸死后，以色列人又去随从诸巴力行邪淫，以巴力比利土为他们的神。'),
('CUV', '士师记', 7, 8, 34, '以色列人不记念耶和华─他们的神，就是拯救他们脱离四围仇敌之手的，'),
('CUV', '士师记', 7, 8, 35, '也不照著耶路巴力，就是基甸向他们所施的恩惠厚待他的家。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '士师记', 7, 9, 1, '耶路巴力的儿子亚比米勒到了示剑见他的众母舅，对他们和他外祖全家的人说：'),
('CUV', '士师记', 7, 9, 2, '请你们问示剑的众人说，是耶路巴力的众子七十人都管理你们好呢？还是一人管理你们好呢？你们又要记念我是你们的骨肉。'),
('CUV', '士师记', 7, 9, 3, '他的众母舅便将这一切话为他说给示剑人听，示剑人的心就归向亚比米勒。他们说：他原是我们的弟兄；'),
('CUV', '士师记', 7, 9, 4, '就从巴力比利土的庙中取了七十舍客勒银子给亚比米勒；亚比米勒用以雇了些匪徒跟随他。'),
('CUV', '士师记', 7, 9, 5, '他往俄弗拉到他父亲的家，将他弟兄、耶路巴力的众子七十人都杀在一块磐石上；只剩下耶路巴力的小儿子约坦，因为他躲藏了。'),
('CUV', '士师记', 7, 9, 6, '示剑人和米罗人都一同聚集，往示剑橡树旁的柱子那里，立亚比米勒为王。'),
('CUV', '士师记', 7, 9, 7, '有人将这事告诉约坦，他就去站在基利心山顶上，向众人大声喊叫说：示剑人哪，你们要听我的话，神也就听你们的话。'),
('CUV', '士师记', 7, 9, 8, '有一时树木要膏一树为王，管理他们，就去对橄榄树说：请你作我们的王。'),
('CUV', '士师记', 7, 9, 9, '橄榄树回答说：我岂肯止住供奉神和尊重人的油，飘飖在众树之上呢？'),
('CUV', '士师记', 7, 9, 10, '树木对无花果树说：请你来作我们的王。'),
('CUV', '士师记', 7, 9, 11, '无花果树回答说：我岂肯止住所结甜美的果子，飘飖在众树之上呢？'),
('CUV', '士师记', 7, 9, 12, '树木对葡萄树说：请你来作我们的王。'),
('CUV', '士师记', 7, 9, 13, '葡萄树回答说：我岂肯止住使神和人喜乐的新酒，飘飖在众树之上呢。'),
('CUV', '士师记', 7, 9, 14, '众树对荆棘说：请你来作我们的王。'),
('CUV', '士师记', 7, 9, 15, '荆棘回答说：你们若诚诚实实地膏我为王，就要投在我的荫下；不然，愿火从荆棘里出来，烧灭利巴嫩的香柏树。'),
('CUV', '士师记', 7, 9, 16, '现在你们立亚比米勒为王，若按诚实正直善待耶路巴力和他的全家，这就是酬他的劳。'),
('CUV', '士师记', 7, 9, 17, '从前我父冒死为你们争战，救了你们脱离米甸人的手。'),
('CUV', '士师记', 7, 9, 18, '你们如今起来攻击我的父家，将他众子七十人杀在一块磐石上，又立他婢女所生的儿子亚比米勒为示剑人的王；他原是你们的弟兄。'),
('CUV', '士师记', 7, 9, 19, '你们如今若按诚实正直待耶路巴力和他的家，就可因亚比米勒得欢乐，他也可因你们得欢乐；'),
('CUV', '士师记', 7, 9, 20, '不然，愿火从亚比米勒发出，烧灭示剑人和米罗众人，又愿火从示剑人和米罗人中出来，烧灭亚比米勒。'),
('CUV', '士师记', 7, 9, 21, '约坦因怕他弟兄亚比米勒，就逃跑，来到比珥，住在那里。'),
('CUV', '士师记', 7, 9, 22, '亚比米勒管理以色列人三年。'),
('CUV', '士师记', 7, 9, 23, '神使恶魔降在亚比米勒和示剑人中间，示剑人就以诡诈待亚比米勒。'),
('CUV', '士师记', 7, 9, 24, '这是要叫耶路巴力七十个儿子所受的残害归与他们的哥哥亚比米勒，又叫那流他们血的罪归与帮助他杀弟兄的示剑人。'),
('CUV', '士师记', 7, 9, 25, '示剑人在山顶上设埋伏，等候亚比米勒。凡从他们那里经过的人，他们就抢夺。有人将这事告诉亚比米勒。'),
('CUV', '士师记', 7, 9, 26, '以别的儿子迦勒和他的弟兄来到示剑，示剑人都信靠他。'),
('CUV', '士师记', 7, 9, 27, '示剑人出城到田间去，摘下葡萄，踹酒，设摆筵宴，进他们神的庙中吃喝，咒诅亚比米勒。'),
('CUV', '士师记', 7, 9, 28, '以别的儿子迦勒说：亚比米勒是谁？示剑是谁？使我们服事他呢？他不是耶路巴力的儿子么？他的帮手不是西布勒么？你们可以服事示剑的父亲哈抹的后裔。我们为何服事亚比米勒呢？'),
('CUV', '士师记', 7, 9, 29, '惟愿这民归我的手下，我就除掉亚比米勒。迦勒又对亚比米勒说：增添你的军兵出来罢。'),
('CUV', '士师记', 7, 9, 30, '邑宰西布勒听见以别的儿子迦勒的话，就发怒，'),
('CUV', '士师记', 7, 9, 31, '悄悄地打发人去见亚比米勒，说：以别的儿子迦勒和他的弟兄到了示剑，煽惑城中的民攻击你。'),
('CUV', '士师记', 7, 9, 32, '现在你和跟随你的人今夜起来，在田间埋伏。'),
('CUV', '士师记', 7, 9, 33, '到早晨太阳一出，你就起来闯城。迦勒和跟随他的人出来攻击你的时候，你便向他们见机而做。'),
('CUV', '士师记', 7, 9, 34, '于是，亚比米勒和跟随他的众人夜间起来，分作四队，埋伏等候示剑人。'),
('CUV', '士师记', 7, 9, 35, '以别的儿子迦勒出去，站在城门口。亚比米勒和跟随他的人从埋伏之处起来。'),
('CUV', '士师记', 7, 9, 36, '迦勒看见那些人，就对西布勒说：看哪，有人从山顶上下来了。西布勒说：你看见山的影子，以为是人。'),
('CUV', '士师记', 7, 9, 37, '迦勒又说：看哪，有人从高处下来，又有一队从米恶尼尼橡树的路上而来。'),
('CUV', '士师记', 7, 9, 38, '西布勒对他说：你曾说，亚比米勒是谁，叫我们服事他？你所夸的口在哪里呢？这不是你所藐视的民么？你现在出去，与他们交战罢！'),
('CUV', '士师记', 7, 9, 39, '于是迦勒率领示剑人出去，与亚比米勒交战。'),
('CUV', '士师记', 7, 9, 40, '亚比米勒追赶迦勒；迦勒在他面前逃跑，有许多受伤仆倒的，直到城门。'),
('CUV', '士师记', 7, 9, 41, '亚比米勒住在亚鲁玛。西布勒赶出迦勒和他弟兄，不准他们住在示剑。'),
('CUV', '士师记', 7, 9, 42, '次日，民出到田间，有人告诉亚比米勒；'),
('CUV', '士师记', 7, 9, 43, '他就把他的人分作三队，埋伏在田间，看见示剑人从城里出来，就起来击杀他们。'),
('CUV', '士师记', 7, 9, 44, '亚比米勒和跟随他的一队向前闯去，站在城门口；那两队直闯到田间，击杀了众人。'),
('CUV', '士师记', 7, 9, 45, '亚比米勒整天攻打城，将城夺取，杀了其中的居民，将城拆毁，撒上了盐。'),
('CUV', '士师记', 7, 9, 46, '示剑楼的人听见了，就躲入巴力比利土庙的卫所。'),
('CUV', '士师记', 7, 9, 47, '有人告诉亚比米勒说：示剑楼的人都聚在一处。'),
('CUV', '士师记', 7, 9, 48, '亚比米勒和跟随他的人就都上撒们山。亚比米勒手拿斧子，砍下一根树枝，扛在肩上，对跟随他的人说：你们看我所行的，也当赶紧照样行。'),
('CUV', '士师记', 7, 9, 49, '众人就各砍一枝，跟随亚比米勒，把树枝堆在卫所的四围，放火烧了卫所，以致示剑楼的人都死了，男女约有一千。'),
('CUV', '士师记', 7, 9, 50, '亚比米勒到提备斯，向提备斯安营，就攻取了那城。'),
('CUV', '士师记', 7, 9, 51, '城中有一座坚固的楼；城里的众人，无论男女，都逃进楼去，关上门，上了楼顶。'),
('CUV', '士师记', 7, 9, 52, '亚比米勒到了楼前攻打，挨近楼门，要用火焚烧。'),
('CUV', '士师记', 7, 9, 53, '有一个妇人把一块上磨石抛在亚比米勒的头上，打破了他的脑骨。'),
('CUV', '士师记', 7, 9, 54, '他就急忙喊叫拿他兵器的少年人，对他说：拔出你的刀来，杀了我罢！免得人议论我说，他为一个妇人所杀。于是少年人把他刺透，他就死了。'),
('CUV', '士师记', 7, 9, 55, '以色列人见亚比米勒死了，便各回自己的地方去了。'),
('CUV', '士师记', 7, 9, 56, '这样，神报应亚比米勒向他父亲所行的恶，就是杀了弟兄七十个人的恶。'),
('CUV', '士师记', 7, 9, 57, '示剑人的一切恶，神也都报应在他们头上；耶路巴力的儿子约坦的咒诅归到们身上了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '士师记', 7, 10, 1, '亚比米勒以后，有以萨迦人朵多的孙子、普瓦的儿子陀拉兴起，拯救以色列人。他住在以法莲山地的沙密。'),
('CUV', '士师记', 7, 10, 2, '陀拉作以色列的士师二十三年，就死了，葬在沙密。'),
('CUV', '士师记', 7, 10, 3, '在他以后有基列人睚珥兴起，作以色列的士师二十二年。'),
('CUV', '士师记', 7, 10, 4, '他有三十个儿子，骑著三十匹驴驹。他们有三十座城邑，叫作哈倭特睚珥，直到如今，都是在基列地。'),
('CUV', '士师记', 7, 10, 5, '睚珥死了，就葬在加们。'),
('CUV', '士师记', 7, 10, 6, '以色列人又行耶和华眼中看为恶的事，去事奉诸巴力和亚斯他录，并亚兰的神、西顿的神、摩押的神、亚扪人的神、非利士人的神，离弃耶和华，不事奉他。'),
('CUV', '士师记', 7, 10, 7, '耶和华的怒气向以色列人发作，就把他们交在非利士人和亚扪人的手中。'),
('CUV', '士师记', 7, 10, 8, '从那年起，他们扰害欺压约但河那边、住亚摩利人之基列地的以色列人，共有十八年。'),
('CUV', '士师记', 7, 10, 9, '亚扪人又渡过约但河去攻打犹大和便雅悯，并以法莲族。以色列人就甚觉窘迫。'),
('CUV', '士师记', 7, 10, 10, '以色列人哀求耶和华说：我们得罪了你；因为离弃了我们神，去事奉诸巴力。'),
('CUV', '士师记', 7, 10, 11, '耶和华对以色列人说：我岂没有救过你们脱离埃及人、亚摩利人、亚扪人，和非利士人么？'),
('CUV', '士师记', 7, 10, 12, '西顿人、亚玛力人、马云人也都欺压你们；你们哀求我，我也拯救你们脱离他们的手。'),
('CUV', '士师记', 7, 10, 13, '你们竟离弃我，事奉别神！所以我不再救你们了。'),
('CUV', '士师记', 7, 10, 14, '你们去哀求所选择的神；你们遭遇急难的时候，让他救你们罢！'),
('CUV', '士师记', 7, 10, 15, '以色列人对耶和华说：我们犯罪了，任凭你随意待我们罢！只求你今日拯救我们。'),
('CUV', '士师记', 7, 10, 16, '以色列人就除掉他们中间的外邦神，事奉耶和华。耶和华因以色列人受的苦难，就心中担忧。'),
('CUV', '士师记', 7, 10, 17, '当时亚扪人聚集，安营在基列。以色列人也聚集，安营在米斯巴。'),
('CUV', '士师记', 7, 10, 18, '基列的民和众首领彼此商议说：谁能先去攻打亚扪人，谁必作基列一切居民的领袖。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '士师记', 7, 11, 1, '基列人耶弗他是个大能的勇士，是妓女的儿子。耶弗他是基列所生的。'),
('CUV', '士师记', 7, 11, 2, '基列的妻也生了几个儿子：他妻所生的儿子长大了，就赶逐耶弗他，说：你不可在我们父家承受产业，因为你是妓女的儿子。'),
('CUV', '士师记', 7, 11, 3, '耶弗他就逃避他的弟兄，去住在陀伯地，有些匪徒到他那里聚集，与他一同出入。'),
('CUV', '士师记', 7, 11, 4, '过了些日子，亚扪人攻打以色列。'),
('CUV', '士师记', 7, 11, 5, '亚扪人攻打以色列的时候，基列的长老到陀伯地去，要叫耶弗他回来；'),
('CUV', '士师记', 7, 11, 6, '对耶弗他说：请你来作我们的元帅，我们好与亚扪人争战。'),
('CUV', '士师记', 7, 11, 7, '耶弗他回答基列的长老说：从前你们不是恨我、赶逐我出离父家么？现在你们遭遇急难为何到我这里来呢？'),
('CUV', '士师记', 7, 11, 8, '基列的长老回答耶弗他说：现在我们到你这里来，是要你同我们去，与亚扪人争战；你可以作基列一切居民的领袖。'),
('CUV', '士师记', 7, 11, 9, '耶弗他对基列的长老说：你们叫我回去，与亚扪人争战，耶和华把他交给我，我可以作你们的领袖么？'),
('CUV', '士师记', 7, 11, 10, '基列的长老回答耶弗他说：有耶和华在你我中间作见证，我们必定照你的话行。'),
('CUV', '士师记', 7, 11, 11, '于是耶弗他同基列的长老回去，百姓就立耶弗他作领袖、作元帅。耶弗他在米斯巴将自己的一切话陈明在耶和华面前。'),
('CUV', '士师记', 7, 11, 12, '耶弗他打发使者去见亚扪人的王，说：你与我有甚么相干，竟来到我国中攻打我呢？'),
('CUV', '士师记', 7, 11, 13, '亚扪人的王回答耶弗他的使者说：因为以色列从埃及上来的时候占据我的地，从亚嫩河到雅博河，直到约但河。现在你要好好地将这地归还罢！'),
('CUV', '士师记', 7, 11, 14, '耶弗他又打发使者去见亚扪人的王，'),
('CUV', '士师记', 7, 11, 15, '对他说：耶弗他如此说，以色列人并没有占据摩押地和亚扪人的地。'),
('CUV', '士师记', 7, 11, 16, '以色列人从埃及上来乃是经过旷野到红海，来到加低斯，'),
('CUV', '士师记', 7, 11, 17, '就打发使者去见以东王，说：求你容我从你的地经过。以东王却不应允。又照样打发使者去见摩押王，他也不允准。以色列人就住在加低斯。'),
('CUV', '士师记', 7, 11, 18, '他们又经过旷野，绕著以东和摩押地，从摩押地的东边过来，在亚嫩河边安营，并没有入摩押的境内，因为亚嫩河是摩押的边界。'),
('CUV', '士师记', 7, 11, 19, '以色列人打发使者去见亚摩利王西宏，就是希实本的王，对他说：求你容我们从你的地经过，往我们自己的地方去。'),
('CUV', '士师记', 7, 11, 20, '西宏却不信服以色列人，不容他们经过他的境界，乃招聚他的众民在雅杂安营，与以色列人争战。'),
('CUV', '士师记', 7, 11, 21, '耶和华─以色列的神将西宏和他的众民都交在以色列人手中，以色列人就击杀他们，得了亚摩利人的全地：'),
('CUV', '士师记', 7, 11, 22, '从亚嫩河到雅博河，从旷野直到约但河。'),
('CUV', '士师记', 7, 11, 23, '耶和华─以色列的神在他百姓以色列面前赶出亚摩利人，你竟要得他们的地么？'),
('CUV', '士师记', 7, 11, 24, '你的神基抹所赐你的地你不是得为业么？耶和华─我们的神在我们面前所赶出的人，我们就得他的地。'),
('CUV', '士师记', 7, 11, 25, '难道你比摩押王西拨的儿子巴勒还强么？他曾与以色列人争竞，或是与他们争战么？'),
('CUV', '士师记', 7, 11, 26, '以色列人住希实本和属希实本的乡村，亚罗珥和属亚罗珥的乡村，并沿亚嫩河的一切城邑，已经有三百年了；在这三百年之内，你们为甚么没有取回这些地方呢？'),
('CUV', '士师记', 7, 11, 27, '原来我没有得罪你，你却攻打我，恶待我。愿审判人的耶和华今日在以色列人和亚扪人中间判断是非。'),
('CUV', '士师记', 7, 11, 28, '但亚扪人的王不肯听耶弗他打发人说的话。'),
('CUV', '士师记', 7, 11, 29, '耶和华的灵降在耶弗他身上，他就经过基列和玛拿西，来到基列的米斯巴，又从米斯巴来到亚扪人那里。'),
('CUV', '士师记', 7, 11, 30, '耶弗他就向耶和华许愿，说：你若将亚扪人交在我手中，'),
('CUV', '士师记', 7, 11, 31, '我从亚扪人那里平平安安回来的时候，无论甚么人，先从我家门出来迎接我，就必归你，我也必将他献上为燔祭。'),
('CUV', '士师记', 7, 11, 32, '于是耶弗他往亚扪人那里去，与他们争战；耶和华将他们交在他手中，'),
('CUV', '士师记', 7, 11, 33, '他就大大杀败他们，从亚罗珥到米匿，直到亚备勒基拉明，攻取了二十座城。这样亚扪人就被以色列人制伏了。'),
('CUV', '士师记', 7, 11, 34, '耶弗他回米斯巴到了自己的家，不料，他女儿拿著鼓跳舞出来迎接他，是他独生的，此外无儿无女。'),
('CUV', '士师记', 7, 11, 35, '耶弗他看见他，就撕裂衣服，说：哀哉！我的女儿啊，你使我甚是愁苦，叫我作难了；因为我已经向耶和华开口许愿，不能挽回。'),
('CUV', '士师记', 7, 11, 36, '他女儿回答说：父啊，你既向耶和华开口，就当照你口中所说的向我行，因耶和华已经在仇敌亚扪人身上为你报仇；'),
('CUV', '士师记', 7, 11, 37, '又对父亲说：有一件事求你允准：容我去两个月，与同伴在山上，好哀哭我终为处女。'),
('CUV', '士师记', 7, 11, 38, '耶弗他说：你去罢！就容他去两个月。他便和同伴去了，在山上为他终为处女哀哭。'),
('CUV', '士师记', 7, 11, 39, '两月已满，他回到父亲那里，父亲就照所许的愿向他行了。女儿终身没有亲近男子。'),
('CUV', '士师记', 7, 11, 40, '此后以色列中有个规矩，每年以色列的女子去为基列人耶弗他的女儿哀哭四天。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '士师记', 7, 12, 1, '以法莲人聚集，到了北方，对耶弗他说：你去与亚扪人争战，为甚么没有招我们同去呢？我们必用火烧你和你的房屋。'),
('CUV', '士师记', 7, 12, 2, '耶弗他对他们说：我和我的民与亚扪；人大大争战；我招你们来，你们竟没有来救我脱离他们的手。'),
('CUV', '士师记', 7, 12, 3, '我见你们不来救我，我就拚命前去攻击亚扪人，耶和华将他们交在我手中。你们今日为甚么上我这里来攻打我呢？'),
('CUV', '士师记', 7, 12, 4, '于是耶弗他招聚基列人，与以法莲人争战。基列人击杀以法莲，是因他们说：你们基列人在以法莲、玛拿西中间，不过是以法莲逃亡的人。'),
('CUV', '士师记', 7, 12, 5, '基列人把守约但河的渡口，不容以法莲人过去。以法莲逃走的人若说：容我过去。基列人就问他说：你是以法莲人不是？他若说：不是，'),
('CUV', '士师记', 7, 12, 6, '就对他说：你说示播列；以法莲人因为咬不真字音，便说西播列。基列人就将他拿住，杀在约但河的渡口。那时以法莲人被杀的有四万二千人。'),
('CUV', '士师记', 7, 12, 7, '耶弗他作以色列的士师年。基列人耶弗他死了，葬在基列的一座城里。'),
('CUV', '士师记', 7, 12, 8, '耶弗他以后，有伯利恒人以比赞作以色列士师。'),
('CUV', '士师记', 7, 12, 9, '他有三十个儿子，三十女儿；女儿都嫁出去了。他给众子从外乡娶了三十媳妇。他作以色列的士师七年。'),
('CUV', '士师记', 7, 12, 10, '以比赞死了，葬在伯利恒。'),
('CUV', '士师记', 7, 12, 11, '以比赞之后，有西布伦人以伦，作以色列的士师十年。'),
('CUV', '士师记', 7, 12, 12, '西布伦人以伦死了，葬在西布伦地的亚雅仑。'),
('CUV', '士师记', 7, 12, 13, '以伦之后，有比拉顿人希列的儿子押顿作以色的士师。'),
('CUV', '士师记', 7, 12, 14, '他有四十个儿子，三十个孙子，骑著七十匹驴驹。押顿作以色列的士师八年。'),
('CUV', '士师记', 7, 12, 15, '比拉顿人希列的儿子押顿死了，葬在以法莲地的比拉顿，在亚玛力人的山地。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '士师记', 7, 13, 1, '以色列人又行耶和华眼中看为恶的事，耶和华将他们交在非利士人手中四十年。'),
('CUV', '士师记', 7, 13, 2, '那时，有一个琐拉人，是属但族的，名叫玛挪亚。他的妻不怀孕，不生育。'),
('CUV', '士师记', 7, 13, 3, '耶和华的使者向那妇人显现，对他说：向来你不怀孕，不生育，如今你必怀孕生一个儿子。'),
('CUV', '士师记', 7, 13, 4, '所以你当谨慎，清酒浓酒都不可喝，一切不洁之物也不可吃。'),
('CUV', '士师记', 7, 13, 5, '你必怀孕生一个儿子，不可用剃头刀剃他的头，因为这孩子一出胎就归神作拿细耳人。他必起首拯救以色列人脱离非利士人的手。'),
('CUV', '士师记', 7, 13, 6, '妇人就回去对丈夫说：有一个神人到我面前来，他的相貌如神使者的相貌，甚是可畏。我没有问他从哪里来，他也没有将他的名告诉我，'),
('CUV', '士师记', 7, 13, 7, '却对我说：你要怀孕生一个儿子，所以清酒浓酒都不可喝，一切不洁之物也不可吃；因为这孩子从出胎一直到死，必归□神作拿细耳人。'),
('CUV', '士师记', 7, 13, 8, '玛挪亚就祈求耶和华说：主啊，求你再差遣那神人到我们这里来，好指教我们怎样待这将要生的孩子。'),
('CUV', '士师记', 7, 13, 9, '神应允玛挪亚的话；妇人正坐在田间的时候，神的使者又到他那里，他丈夫玛挪亚却没有同他在一处。'),
('CUV', '士师记', 7, 13, 10, '妇人急忙跑去告诉丈夫说：那日到我面前来的人，又向我显现。'),
('CUV', '士师记', 7, 13, 11, '玛挪亚起来跟随他的妻来到那人面前，对他说：与这妇人说话的就是你么？他说：是我。'),
('CUV', '士师记', 7, 13, 12, '玛挪亚说：愿你的话应验！我们当怎样待这孩子，他后来当怎样呢？'),
('CUV', '士师记', 7, 13, 13, '耶和华的使者对玛挪亚说：我告诉妇人的一切事，他都当谨慎。'),
('CUV', '士师记', 7, 13, 14, '葡萄树所结的都不可吃，清酒浓酒都不可喝，一切不洁之物也不可吃。凡我所吩咐的，他都当遵守。'),
('CUV', '士师记', 7, 13, 15, '玛挪亚对耶和华的使者说：求你容我们款留你，好为你预备一只山羊羔。'),
('CUV', '士师记', 7, 13, 16, '耶和华的使者对玛挪亚说：你虽然款留我，我却不吃你的食物，你若预备燔祭就当献与耶和华。原来玛挪亚不知道他是耶和华的使者。'),
('CUV', '士师记', 7, 13, 17, '玛挪亚对耶和华的使者说：请将你的名告诉我，到你话应验的时候，我们好尊敬你。'),
('CUV', '士师记', 7, 13, 18, '耶和华的使者对他说：你何必问我的名，我名是奇妙的。'),
('CUV', '士师记', 7, 13, 19, '玛挪亚将一只山羊羔和素祭在磐石上献与耶和华，使者行奇妙的事；玛挪亚和他的妻观看，'),
('CUV', '士师记', 7, 13, 20, '见火燄从坛上往上升，耶和华的使者在坛上的火燄中也升上去了。玛挪亚和他的妻看见，就俯伏于地。'),
('CUV', '士师记', 7, 13, 21, '耶和华的使者不再向玛挪亚和他的妻显现，玛挪亚才知道他是耶和华的使者。'),
('CUV', '士师记', 7, 13, 22, '玛挪亚对他的妻说：我们必要死，因为看见了神。'),
('CUV', '士师记', 7, 13, 23, '他的妻却对他说：耶和华若要杀我们，必不从我们手里收纳燔祭和素祭，并不将这一切事指示我们，今日也不将这些话告诉我们。'),
('CUV', '士师记', 7, 13, 24, '后来妇人生了一个儿子，给他起名叫参孙。孩子长大，耶和华赐福与他。'),
('CUV', '士师记', 7, 13, 25, '在玛哈尼但，就是琐拉和以实陶中间，耶和华的灵才感动他。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '士师记', 7, 14, 1, '参孙下到亭拿，在那里看见一个女子，是非利士人的女儿。'),
('CUV', '士师记', 7, 14, 2, '参孙上来禀告他父母说：我在亭拿看见一个女子，是非利士人的女儿，愿你们给我娶来为妻。'),
('CUV', '士师记', 7, 14, 3, '他父母说：在你弟兄的女儿中，或在本国的民中，岂没有一个女子，何至你去在未受割礼的非利士人中娶妻呢？参孙对他父亲说：愿你给我娶那女子，因我喜悦他。'),
('CUV', '士师记', 7, 14, 4, '他的父母却不知道这事是出于耶和华，因为他找机会攻击非利士人。那时，非利士人辖制以色列人。'),
('CUV', '士师记', 7, 14, 5, '参孙跟他父母下亭拿去，到了亭拿的葡萄园，见有一只少壮狮子向他吼叫。'),
('CUV', '士师记', 7, 14, 6, '耶和华的灵大大感动参孙，他虽然手无器械，却将狮子撕裂，如同撕裂山羊羔一样。他行这事并没有告诉父母。'),
('CUV', '士师记', 7, 14, 7, '参孙下去与女子说话，就喜悦他；'),
('CUV', '士师记', 7, 14, 8, '过了些日子，再下去要娶那女子，转向道旁要看死狮，见有一群蜂子和蜜在死狮之内，'),
('CUV', '士师记', 7, 14, 9, '就用手取蜜，且吃且走；到了父母那里，给他父母，他们也吃了；只是没有告诉这蜜是从死狮之内取来的。'),
('CUV', '士师记', 7, 14, 10, '他父亲下去见女子。参孙在那里设摆筵宴，因为向来少年人都有这个规矩。'),
('CUV', '士师记', 7, 14, 11, '众人看见参孙，就请了三十个人陪伴他。'),
('CUV', '士师记', 7, 14, 12, '参孙对他们说：我给你们出一个谜语，你们在七日筵宴之内，若能猜出意思告诉我，我就给你们三十件里衣，三十套衣裳；'),
('CUV', '士师记', 7, 14, 13, '你们若不能猜出意思告诉我，你们就给我三十件里衣，三十套衣裳。他们说：请将谜语说给我们听。'),
('CUV', '士师记', 7, 14, 14, '参孙对他们说：吃的从吃者出来；甜的从强者出来。他们三日不能猜出谜语的意思。'),
('CUV', '士师记', 7, 14, 15, '到第七天，他们对参孙的妻说：你诓哄你丈夫，探出谜语的意思告诉我们，免得我们用火烧你和你父家。你们请了我们来，是要夺我们所有的么？'),
('CUV', '士师记', 7, 14, 16, '参孙的妻在丈夫面前啼哭说：你是恨我，不是爱我，你给我本国的人出谜语，却没有将意思告诉我。参孙回答说：连我父母我都没有告诉，岂可告诉你呢？'),
('CUV', '士师记', 7, 14, 17, '七日筵宴之内，他在丈夫面前啼哭，到第七天逼著他，他才将谜语的意思告诉他妻，他妻就告诉本国的人。'),
('CUV', '士师记', 7, 14, 18, '到第七天，日头未落以前，那城里的人对参孙说：有甚么比蜜还甜呢？有甚么比狮子还强呢？参孙对他们说：你们若非用我的母牛犊耕地，就猜不出我谜语的意思来。'),
('CUV', '士师记', 7, 14, 19, '耶和华的灵大大感动参孙，他就下到亚实基伦，击杀了三十个人，夺了他们的衣裳，将衣裳给了猜出谜语的人。参孙发怒，就上父家去了。'),
('CUV', '士师记', 7, 14, 20, '参孙的妻便归了参孙的陪伴，就是作过他朋友的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '士师记', 7, 15, 1, '过了些日子，到割麦子的时候，参孙带著一只山羊羔去看他的妻，说：我要进内室见我的妻。他岳父不容他进去，'),
('CUV', '士师记', 7, 15, 2, '说：我估定你是极其恨他，因此我将他给了你的陪伴。他的妹子不是比他还美丽么？你可以娶来代替他罢！'),
('CUV', '士师记', 7, 15, 3, '参孙说：这回我加害于非利士人不算有罪。'),
('CUV', '士师记', 7, 15, 4, '于是参孙去捉了三百只狐狸（或译：野狗），将狐狸尾巴一对一对地捆上，将火把捆在两条尾巴中间，'),
('CUV', '士师记', 7, 15, 5, '点著火把，就放狐狸进入非利士人站著的禾稼，将堆集的禾捆和未割的禾稼，并橄榄园尽都烧了。'),
('CUV', '士师记', 7, 15, 6, '非利士人说：这事是谁做的呢？有人说：是亭拿人的女婿参孙，因为他岳父将他的妻给了他的陪伴。于是非利士人上去，用火烧了妇人和他的父亲。'),
('CUV', '士师记', 7, 15, 7, '参孙对非利士人说：你们既然这样行，我必向你们报仇才肯罢休。'),
('CUV', '士师记', 7, 15, 8, '参孙就大大击杀他们，连腿带腰都砍断了。他便下去，住在以坦磐的穴内。'),
('CUV', '士师记', 7, 15, 9, '非利士人上去安营在犹大，布散在利希。'),
('CUV', '士师记', 7, 15, 10, '犹大人说：你们为何上来攻击我们呢？他们说：我们上来是要捆绑参孙；他向我们怎样行，我们也要向他怎样行。'),
('CUV', '士师记', 7, 15, 11, '于是有三千犹大人下到以坦磐的穴内，对参孙说：非利士人辖制我们，你不知道么？你向我们行的是甚么事呢？他回答说：他们向我怎样行，我也要向他们怎样行。'),
('CUV', '士师记', 7, 15, 12, '犹大人对他说：我们下来是要捆绑你，将你交在非利士人手中。参孙说：你们要向我起誓，应承你们自己不害死我。'),
('CUV', '士师记', 7, 15, 13, '他们说：我们断不杀你，只要将你捆绑交在非利士人手中。于是用两条新绳捆绑参孙，将他从以坦磐带上去。'),
('CUV', '士师记', 7, 15, 14, '参孙到了利希，非利士人都迎著喧嚷。耶和华的灵大大感动参孙，他臂上的绳就像火烧的麻一样，他的绑绳都从他手上脱落下来。'),
('CUV', '士师记', 7, 15, 15, '他见一块未干的驴腮骨，就伸手拾起来，用以击杀一千人。'),
('CUV', '士师记', 7, 15, 16, '参孙说：我用驴恉骨杀人成堆，用驴腮骨杀了一千人。'),
('CUV', '士师记', 7, 15, 17, '说完这话，就把那恉骨从手里抛出去了。那地便叫拉末利希。'),
('CUV', '士师记', 7, 15, 18, '参孙甚觉口渴，就求告耶和华说：你既藉仆人的手施行这么大的拯救，岂可任我渴死、落在未受割礼的人手中呢？'),
('CUV', '士师记', 7, 15, 19, '神就使利希的洼处裂开，有水从其中涌出来。参孙喝了，精神复原；因此那泉名叫隐哈歌利，那泉直到今日还在利希。'),
('CUV', '士师记', 7, 15, 20, '当非利士人辖制以色列人的时候，参孙作以色列的士师二十年。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '士师记', 7, 16, 1, '参孙到了迦萨，在那里看见一个妓女，就与他亲近。'),
('CUV', '士师记', 7, 16, 2, '有人告诉迦萨人说：参孙到这里来了！他们就把他团团围住，终夜在城门悄悄埋伏，说：等到天亮我们便杀他。'),
('CUV', '士师记', 7, 16, 3, '参孙睡到半夜，起来，将城门的门扇、门框、门闩，一齐拆下来，扛在肩上，扛到希伯仑前的山顶上。'),
('CUV', '士师记', 7, 16, 4, '后来，参孙在梭烈谷喜爱一个妇人，名叫大利拉。'),
('CUV', '士师记', 7, 16, 5, '非利士人的首领上去见那妇人，对他说：求你诓哄参孙，探探他因何有这么大的力气，我们用何法能胜他，捆绑克制他。我们就每人给你一千一百舍客勒银子。'),
('CUV', '士师记', 7, 16, 6, '大利拉对参孙说：求你告诉我，你因何有这么大的力气，当用何法捆绑克制你。'),
('CUV', '士师记', 7, 16, 7, '参孙回答说：人若用七条未干的青绳子捆绑我，我就软弱像别人一样。'),
('CUV', '士师记', 7, 16, 8, '于是非利士人的首领拿了七条未干的青绳子来，交给妇人，他就用绳子捆绑参孙。'),
('CUV', '士师记', 7, 16, 9, '有人预先埋伏在妇人的内室里。妇人说：参孙哪，非利士人拿你来了！参孙就挣断绳子，如挣断经火的麻线一般。这样，他力气的根由人还是不知道。'),
('CUV', '士师记', 7, 16, 10, '大利拉对参孙说：你欺哄我，向我说谎言。现在求你告诉我当用何法捆绑你。'),
('CUV', '士师记', 7, 16, 11, '参孙回答说：人若用没有使过的新绳捆绑我，我就软弱像别人一样。'),
('CUV', '士师记', 7, 16, 12, '大利拉就用新绳捆绑他，对他说：参孙哪，非利士人拿你来了！有人预先埋伏在内室里。参孙将臂上的绳挣断了，如挣断一条线一样。'),
('CUV', '士师记', 7, 16, 13, '大利拉对参孙说：你到如今还是欺哄我，向我说谎言。求你告诉我，当用何法捆绑你。参孙回答说：你若将我头上的七条发绺，与纬线同织就可以了。'),
('CUV', '士师记', 7, 16, 14, '于是大利拉将他的发绺与纬线同织，用橛子钉住，对他说：参孙哪，非利士人拿你来了！参孙从睡中醒来，将机上的橛子和纬线一齐都拔出来了。'),
('CUV', '士师记', 7, 16, 15, '大利拉对参孙说：你既不与我同心，怎么说你爱我呢？你这三次欺哄我，没有告诉我，你因何有这么大的力气。'),
('CUV', '士师记', 7, 16, 16, '大利拉天天用话催逼他，甚至他心里烦闷要死。'),
('CUV', '士师记', 7, 16, 17, '参孙就把心中所藏的都告诉了他，对他说：向来人没有用剃头刀剃我的头，因为我自出母胎就归神作拿细耳人；若剃了我的头发，我的力气就离开我，我便软弱像别人一样。'),
('CUV', '士师记', 7, 16, 18, '大利拉见他把心中所藏的都告诉了他，就打发人到非利士人的首领那里，对他们说：他已经把心中所藏的都告诉了我，请你们再上来一次。于是非利士人的首领手里拿著银子，上到妇人那里。'),
('CUV', '士师记', 7, 16, 19, '大利拉使参孙枕著他的膝睡觉，叫了一个人来剃除他头上的七条发绺。于是大利拉克制他，他的力气就离开他了。'),
('CUV', '士师记', 7, 16, 20, '大利拉说：参孙哪，非利士人拿你来了！参孙从睡中醒来，心里说：我要像前几次出去活动身体；他却不知道耶和华已经离开他了。'),
('CUV', '士师记', 7, 16, 21, '非利士人将他拿住，剜了他的眼睛，带他下到迦萨，用铜炼拘索他；他就在监里推磨。'),
('CUV', '士师记', 7, 16, 22, '然而他的头发被剃之后，又渐渐长起来了。'),
('CUV', '士师记', 7, 16, 23, '非利士人的首领聚集，要给他们的神大衮献大祭，并且欢乐，因为他们说：我们的神将我们的仇敌参孙交在我们手中了。'),
('CUV', '士师记', 7, 16, 24, '众人看见参孙，就赞美他们的神说：我们的神将毁坏我们地、杀害我们许多人的仇敌交在我们手中了。'),
('CUV', '士师记', 7, 16, 25, '他们正宴乐的时候，就说：叫参孙来，在我们面前戏耍戏耍。于是将参孙从监里提出来，他就在众人面前戏耍。他们使他站在两柱中间。'),
('CUV', '士师记', 7, 16, 26, '参孙向拉他手的童子说：求你让我摸著托房的柱子，我要靠一靠。'),
('CUV', '士师记', 7, 16, 27, '那时房内充满男女，非利士人的众首领也都在那里。房的平顶上约有三千男女观看参孙戏耍。'),
('CUV', '士师记', 7, 16, 28, '参孙求告耶和华说：主耶和华啊，求你眷念我。神啊，求你赐我这一次的力量，使我在非利士人身上报那剜我双眼的仇。'),
('CUV', '士师记', 7, 16, 29, '参孙就抱住托房的那两根柱子：左手抱一根，右手抱一根，'),
('CUV', '士师记', 7, 16, 30, '说：我情愿与非利士人同死！就尽力屈身，房子倒塌，压住首领和房内的众人。这样，参孙死时所杀的人比活著所杀的还多。'),
('CUV', '士师记', 7, 16, 31, '参孙的弟兄和他父的全家都下去取他的尸首，抬上来葬在琐拉和以实陶中间，在他父玛挪亚的坟墓里。参孙作以色列的士师二十年。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '士师记', 7, 17, 1, '以法莲山地有一个人名叫米迦。'),
('CUV', '士师记', 7, 17, 2, '他对母亲说：你那一千一百舍客勒银子被人拿去，你因此咒诅，并且告诉了我。看哪，这银子在我这里，是我拿去了。他母亲说：我儿啊，愿耶和华赐福与你！'),
('CUV', '士师记', 7, 17, 3, '米迦就把这一千一百舍客勒银子还他母亲。他母亲说：我分出这银子来为你献给耶和华，好雕刻一个像，铸成一个像。现在我还是交给你。'),
('CUV', '士师记', 7, 17, 4, '米迦将银子还他母亲，他母亲将二百舍客勒银子交给银匠，雕刻一个像，铸成一个像，安置在米迦的屋内。'),
('CUV', '士师记', 7, 17, 5, '这米迦有了神堂，又制造以弗得和家中的神像，分派他一个儿子作祭司。'),
('CUV', '士师记', 7, 17, 6, '那时以色列中没有王，各人任意而行。'),
('CUV', '士师记', 7, 17, 7, '犹大的伯利恒有一个少年人，是犹大族的利未人，他在那里寄居。'),
('CUV', '士师记', 7, 17, 8, '这人离开犹大的伯利恒城，要找一个可住的地方。行路的时候，到了以法莲山地，走到米迦的家。'),
('CUV', '士师记', 7, 17, 9, '米迦问他说：你从哪里来？他回答说：从犹大的伯利恒来。我是利未人，要找一个可住的地方。'),
('CUV', '士师记', 7, 17, 10, '米迦说：你可以住在我这里，我以你为父、为祭司。我每年给你十舍客勒银子，一套衣服和度日的食物。利未人就进了他的家。'),
('CUV', '士师记', 7, 17, 11, '利未人情愿与那人同住；那人看这少年人如自己的儿子一样。'),
('CUV', '士师记', 7, 17, 12, '米迦分派这少年的利未人作祭司，他就住在米迦的家里。'),
('CUV', '士师记', 7, 17, 13, '米迦说：现在我知道耶和华必赐福与我，因我有一个利未人作祭司。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '士师记', 7, 18, 1, '那时，以色列中没有王。但支派的人仍是寻地居住；因为到那日子，他们还没有在以色列支派中得地为业。'),
('CUV', '士师记', 7, 18, 2, '但人从琐拉和以实陶打发本族中的五个勇士，去仔细窥探那地，吩咐他们说：你们去窥探那地。他们来到以法莲山地，进了米迦的住宅，就在那里住宿。'),
('CUV', '士师记', 7, 18, 3, '他们临近米迦的住宅，听出那少年利未人的口音来，就进去问他说：谁领你到这里来？你在这里做甚么？你在这里得甚么？'),
('CUV', '士师记', 7, 18, 4, '他回答说：米迦待我如此如此，请我作祭司。'),
('CUV', '士师记', 7, 18, 5, '他们对他说：请你求问神，使我们知道所行的道路通达不通达。'),
('CUV', '士师记', 7, 18, 6, '祭司对他们说：你们可以平平安安地去，你们所行的道路是在耶和华面前的。'),
('CUV', '士师记', 7, 18, 7, '五人就走了，来到拉亿，见那里的民安居无虑，如同西顿人安居一样。在那地没有人掌权扰乱他们；他们离西顿人也远，与别人没有来往。'),
('CUV', '士师记', 7, 18, 8, '五人回到琐拉和以实陶，见他们的弟兄；弟兄问他们说：你们有甚么话？'),
('CUV', '士师记', 7, 18, 9, '他们回答说：起来，我们上去攻击他们罢！我们已经窥探那地，见那地甚好。你们为何静坐不动呢？要急速前往得那地为业，不可迟延。'),
('CUV', '士师记', 7, 18, 10, '你们到了那里，必看见安居无虑的民，地也宽阔。□神已将那地交在你们手中；那地百物俱全，一无所缺。'),
('CUV', '士师记', 7, 18, 11, '于是但族中的六百人，各带兵器，从琐拉和以实陶前往，'),
('CUV', '士师记', 7, 18, 12, '上到犹大的基列耶琳，在基列耶琳后边安营。因此那地方名叫玛哈尼但，直到今日。'),
('CUV', '士师记', 7, 18, 13, '他们从那里往以法莲山地去，来到米迦的住宅。'),
('CUV', '士师记', 7, 18, 14, '从前窥探拉亿地的五个人对他们的弟兄说：这宅子里有以弗得和家中的神像，并雕刻的像与铸成的像，你们知道么？现在你们要想一想当怎样行。'),
('CUV', '士师记', 7, 18, 15, '五人就进入米迦的住宅，到了那少年利未人的房内问他好。'),
('CUV', '士师记', 7, 18, 16, '那六百但人各带兵器，站在门口。'),
('CUV', '士师记', 7, 18, 17, '窥探地的五个人走进去，将雕刻的像、以弗得、家中的神像，并铸成的像，都拿了去。祭司和带兵器的六百人，一同站在门口。'),
('CUV', '士师记', 7, 18, 18, '那五个人进入米迦的住宅，拿出雕刻的像、以弗得、家中的神像，并铸成的像，祭司就问他们说：你们做甚么呢？'),
('CUV', '士师记', 7, 18, 19, '他们回答说：不要作声，用手摀口，跟我们去罢！我们必以你为父、为祭司。你作一家的祭司好呢？还是作以色列一族一支派的祭司好呢？'),
('CUV', '士师记', 7, 18, 20, '祭司心里喜悦，便拿著以弗得和家中的神像，并雕刻的像，进入他们中间。'),
('CUV', '士师记', 7, 18, 21, '他们就转身离开那里，妻子、儿女、牲畜、财物都在前头。'),
('CUV', '士师记', 7, 18, 22, '离米迦的住宅已远，米迦的近邻都聚集来，追赶但人，'),
('CUV', '士师记', 7, 18, 23, '呼叫但人。但人回头问米迦说：你聚集这许多人来做甚么呢？'),
('CUV', '士师记', 7, 18, 24, '米迦说：你们将我所做的神像和祭司都带了去，我还有所剩的么？怎么还问我说做甚么呢？'),
('CUV', '士师记', 7, 18, 25, '但人对米迦说：你不要使我们听见你的声音，恐怕有性暴的人攻击你，以致你和你的全家尽都丧命。'),
('CUV', '士师记', 7, 18, 26, '但人还是走他们的路。米迦见他们的势力比自己强盛，就转身回家去了。'),
('CUV', '士师记', 7, 18, 27, '但人将米迦所做的神像和他的祭司都带到拉亿，见安居无虑的民，就用刀杀了那民，又放火烧了那城，'),
('CUV', '士师记', 7, 18, 28, '并无人搭救；因为离西顿远，他们又与别人没有来往。城在平原，那平原靠近伯利合。但人又在那里修城居住，'),
('CUV', '士师记', 7, 18, 29, '照著他们始祖以色列之子但的名字，给那城起名叫但；原先那城名叫拉亿。'),
('CUV', '士师记', 7, 18, 30, '但人就为自己设立那雕刻的像。摩西的孙子、革舜的儿子约拿单，和他的子孙作但支派的祭司，直到那地遭掳掠的日子。'),
('CUV', '士师记', 7, 18, 31, '神的殿在示罗多少日子，但人为自己设立米迦所雕刻的像也在但多少日子。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '士师记', 7, 19, 1, '当以色列中没有王的时候，有住以法莲山地那边的一个利未人，娶了一个犹大伯利恒的女子为妾。'),
('CUV', '士师记', 7, 19, 2, '妾行淫离开丈夫，回犹大的伯利恒，到了父家，在那里住了四个月。'),
('CUV', '士师记', 7, 19, 3, '他丈夫起来，带著一个仆人、两匹驴去见他，用好话劝他回来。女子就引丈夫进入父家。他父见了那人，便欢欢喜喜地迎接。'),
('CUV', '士师记', 7, 19, 4, '那人的岳父，就是女子的父亲，将那人留下住了三天。于是二人一同吃喝、住宿。'),
('CUV', '士师记', 7, 19, 5, '到第四天，利未人清早起来要走，女子的父亲对女婿说：请你吃点饭，加添心力，然后可以行路。'),
('CUV', '士师记', 7, 19, 6, '于是二人坐下一同吃喝。女子的父亲对那人说：请你再住一夜，畅快你的心。'),
('CUV', '士师记', 7, 19, 7, '那人起来要走，他岳父强留他，他又住了一宿。'),
('CUV', '士师记', 7, 19, 8, '到第五天，他清早起来要走，女子的父亲说：请你吃点饭，加添心力，等到日头偏西再走。于是二人一同吃饭。'),
('CUV', '士师记', 7, 19, 9, '那人同他的妾和仆人起来要走，他岳父，就是女子的父亲，对他说：看哪，日头偏西了，请你再住一夜；天快晚了，可以在这里住宿，畅快你的心。明天早早起行回家去。'),
('CUV', '士师记', 7, 19, 10, '那人不愿再住一夜，就备上那两匹驴，带著妾起身走了，来到耶布斯的对面（耶布斯就是耶路撒冷。）'),
('CUV', '士师记', 7, 19, 11, '临近耶布斯的时候，日头快要落了，仆人对主人说：我们不如进这耶布斯人的城里住宿。'),
('CUV', '士师记', 7, 19, 12, '主人回答说：我们不可进不是以色列人住的外邦城，不如过到基比亚去；'),
('CUV', '士师记', 7, 19, 13, '又对仆人说：我们可以到一个地方，或住在基比亚，或住在拉玛。'),
('CUV', '士师记', 7, 19, 14, '他们就往前走。将到便雅悯的基比亚，日头已经落了；'),
('CUV', '士师记', 7, 19, 15, '他们进入基比亚要在那里住宿，就坐在城里的街上，因为无人接他们进家住宿。'),
('CUV', '士师记', 7, 19, 16, '晚上，有一个老年人从田间做工回来。他原是以法莲山地的人，住在基比亚；那地方的人却是便雅悯人。'),
('CUV', '士师记', 7, 19, 17, '老年人举目看见客人坐在城里的街上，就问他说：你从哪里来？要往哪里去？'),
('CUV', '士师记', 7, 19, 18, '他回答说：我们从犹大的伯利恒来，要往以法莲山地那边去。我原是那里的人，到过犹大的伯利恒，现在我往耶和华的殿去，在这里无人接我进他的家。'),
('CUV', '士师记', 7, 19, 19, '其实我有粮草可以喂驴，我与我的妾，并我的仆人，有饼有酒，并不缺少甚么。'),
('CUV', '士师记', 7, 19, 20, '老年人说：愿你平安！你所需用的我都给你，只是不可在街上过夜。'),
('CUV', '士师记', 7, 19, 21, '于是领他们到家里，喂上驴，他们就洗脚吃喝。'),
('CUV', '士师记', 7, 19, 22, '他们心里正欢畅的时候，城中的匪徒围住房子，连连叩门，对房主老人说：你把那进你家的人带出来，我们要与他交合。'),
('CUV', '士师记', 7, 19, 23, '那房主出来对他们说：弟兄们哪，不要这样作恶；这人既然进了我的家，你们就不要行这丑事。'),
('CUV', '士师记', 7, 19, 24, '我有个女儿，还是处女，并有这人的妾，我将他们领出来任凭你们玷辱他们，只是向这人不可行这样的丑事。'),
('CUV', '士师记', 7, 19, 25, '那些人却不听从他的话。那人就把他的妾拉出去交给他们，他们便与他交合，终夜凌辱他，直到天色快亮才放他去。'),
('CUV', '士师记', 7, 19, 26, '天快亮的时候，妇人回到他主人住宿的房门前，就仆倒在地，直到天亮。'),
('CUV', '士师记', 7, 19, 27, '早晨，他的主人起来开了房门，出去要行路，不料那妇人仆倒在房门前，两手搭在门槛上；'),
('CUV', '士师记', 7, 19, 28, '就对妇人说：起来，我们走罢！妇人却不回答。那人便将他驮在驴上，起身回本处去了。'),
('CUV', '士师记', 7, 19, 29, '到了家里，用刀将妾的尸身切成十二块，使人拿著传送以色列的四境。'),
('CUV', '士师记', 7, 19, 30, '凡看见的人都说：从以色列人出埃及地，直到今日，这样的事没有行过，也没有见过。现在应当思想，大家商议当怎样办理。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '士师记', 7, 20, 1, '于是以色列从但到别是巴，以及住基列地的众人都出来，如同一人，聚集在米斯巴耶和华面前。'),
('CUV', '士师记', 7, 20, 2, '以色列民的首领，就是各支派的军长，都站在神百姓的会中；拿刀的步兵共有四十万。'),
('CUV', '士师记', 7, 20, 3, '以色列人上到米斯巴，便雅悯人都听见了。以色列人说：请你将这件恶事的情由对我们说明。'),
('CUV', '士师记', 7, 20, 4, '那利未人，就是被害之妇人的丈夫，回答说：我和我的妾到了便雅悯的基比亚住宿。'),
('CUV', '士师记', 7, 20, 5, '基比亚人夜间起来，围了我住的房子，想要杀我，又将我的妾强奸致死。'),
('CUV', '士师记', 7, 20, 6, '我就把我妾的尸身切成块子，使人拿著传送以色列得为业的全地，因为基比亚人在以色列中行了扔菏丑恶的事。'),
('CUV', '士师记', 7, 20, 7, '你们以色列人都当筹划商议。'),
('CUV', '士师记', 7, 20, 8, '众民都起来如同一人，说：我们连一人都不回自己帐棚、自己房屋去。'),
('CUV', '士师记', 7, 20, 9, '我们向基比亚人必这样行，照所掣的签去攻击他们。'),
('CUV', '士师记', 7, 20, 10, '我们要在以色列各支派中，一百人挑取十人，一千人挑取百人，一万人挑取千人，为民运粮，等大众到了便雅悯的基比亚，就照基比亚人在以色列中所行的丑事征伐他们。'),
('CUV', '士师记', 7, 20, 11, '于是以色列众人彼此连合如同一人，聚集攻击那城'),
('CUV', '士师记', 7, 20, 12, '以色列众支派打发人去，问便雅悯支派的各家说：你们中间怎么做了这样的恶事呢？'),
('CUV', '士师记', 7, 20, 13, '现在你们要将基比亚的那些匪徒交出来，我们好治死他们，从以色列中除掉这恶。便雅悯人却不肯听从他们弟兄以色列人的话。'),
('CUV', '士师记', 7, 20, 14, '便雅悯人从他们的各城里出来，聚集到了基比亚，要与以色列人打仗。'),
('CUV', '士师记', 7, 20, 15, '那时便雅悯人从各城里点出拿刀的，共有二万六千；另外还有基比亚人点出七百精兵。'),
('CUV', '士师记', 7, 20, 16, '在众军之中有拣选的七百精兵，都是左手便利的，能用机弦甩石打人，毫发不差。'),
('CUV', '士师记', 7, 20, 17, '便雅悯人之外，点出以色列人拿刀的，共有四十万，都是战士。'),
('CUV', '士师记', 7, 20, 18, '以色列人就起来，到伯特利去求问神说：我们中间谁当首先上去与便雅悯人争战呢？耶和华说：犹大当先上去。'),
('CUV', '士师记', 7, 20, 19, '以色列人早晨起来，对著基比亚安营。'),
('CUV', '士师记', 7, 20, 20, '以色列人出来，要与便雅悯人打仗，就在基比亚前摆阵。'),
('CUV', '士师记', 7, 20, 21, '便雅悯人就从基比亚出来，当日杀死以色列人二万二千。'),
('CUV', '士师记', 7, 20, 22, '以色列人彼此奋勇，仍在头一日摆阵的地方又摆阵。'),
('CUV', '士师记', 7, 20, 23, '未摆阵之先，以色列人上去，在耶和华面前哭号，直到晚上，求问耶和华说：我们再去与我们弟兄便雅悯人打仗可以不可以？耶和华说：可以上去攻击他们。'),
('CUV', '士师记', 7, 20, 24, '第二日，以色列人就上前攻击便雅悯人。'),
('CUV', '士师记', 7, 20, 25, '便雅悯人也在这日从基比亚出来，与以色列人接战，又杀死他们一万八千，都是拿刀的。'),
('CUV', '士师记', 7, 20, 26, '以色列众人就上到伯特利，坐在耶和华面前哭号，当日禁食直到晚上；又在耶和华面前献燔祭和平安祭。'),
('CUV', '士师记', 7, 20, 27, '那时，神的约柜在那里；亚伦的孙子、以利亚撒的儿子非尼哈侍立在约柜前。以色列人问耶和华说：我们当再出去与我们弟兄便雅悯人打仗呢？还是罢兵呢？耶和华说：你们当上去，因为明日我必将他们交在你们手中。'),
('CUV', '士师记', 7, 20, 28, 'a'),
('CUV', '士师记', 7, 20, 29, '以色列人在基比亚的四围设下伏兵。'),
('CUV', '士师记', 7, 20, 30, '第三日，以色列人又上去攻击便雅悯人，在基比亚前摆阵，与前两次一样。'),
('CUV', '士师记', 7, 20, 31, '便雅悯人也出来迎敌，就被引诱离城；在田间两条路上，一通伯特利，一通基比亚，像前两次，动手杀死以色列人约有三十个。'),
('CUV', '士师记', 7, 20, 32, '便雅悯人说：他们仍旧败在我们面前。但以色列人说：我们不如逃跑，引诱他们离开城到路上来。'),
('CUV', '士师记', 7, 20, 33, '以色列众人都起来，在巴力他玛摆阵，以色列的伏兵从马利迦巴埋伏的地方冲上前去。'),
('CUV', '士师记', 7, 20, 34, '有以色列人中的一万精兵，来到基比亚前接战，势派甚是凶猛；便雅悯人却不知道灾祸临近了。'),
('CUV', '士师记', 7, 20, 35, '耶和华使以色列人杀败便雅悯人。那日，以色列人杀死便雅悯人二万五千一百，都是拿刀的。'),
('CUV', '士师记', 7, 20, 36, '于是便雅悯人知道自己败了。先是以色列人；因为靠著在基比亚前所设的伏兵，就在便雅悯人面前诈败。'),
('CUV', '士师记', 7, 20, 37, '伏兵急忙闯进基比亚，用刀杀死全城的人。'),
('CUV', '士师记', 7, 20, 38, '以色列人预先同伏兵约定在城内放火，以烟气上腾为号。'),
('CUV', '士师记', 7, 20, 39, '以色列人临退阵的时候，便雅悯人动手杀死以色列人，约有三十个，就说：他们仍像前次被我们杀败了。'),
('CUV', '士师记', 7, 20, 40, '当烟气如柱从城中上腾的时候，便雅悯人回头观看，见全城的烟气冲天。'),
('CUV', '士师记', 7, 20, 41, '以色列人又转身回来，便雅悯人就甚惊惶，因为看见灾祸临到自己了。'),
('CUV', '士师记', 7, 20, 42, '他们在以色列人面前转身往旷野逃跑；以色列人在后面追杀。那从各城里出来的，也都夹攻杀灭他们。'),
('CUV', '士师记', 7, 20, 43, '以色列人围绕便雅悯人，追赶他们，在他们歇脚之处、对著日出之地的基比亚践踏他们。'),
('CUV', '士师记', 7, 20, 44, '便雅悯人死了的有一万八千，都是勇士。'),
('CUV', '士师记', 7, 20, 45, '其余的人转身向旷野逃跑，往临门磐去。以色列人在道路上杀了他们五千人，如拾取遗穗一样，追到基顿又杀了他们二千人。'),
('CUV', '士师记', 7, 20, 46, '那日便雅悯死了的共有二万五千人，都是拿刀的勇士。'),
('CUV', '士师记', 7, 20, 47, '只剩下六百人，转身向旷野逃跑，到了临门磐，就在那里住了四个月。'),
('CUV', '士师记', 7, 20, 48, '以色列人又转到便雅悯地，将各城的人和牲畜，并一切所遇见的，都用刀杀尽，又放火烧了一切城邑。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '士师记', 7, 21, 1, '以色列人在米斯巴曾起誓说：我们都不将女儿给便雅悯人为妻。'),
('CUV', '士师记', 7, 21, 2, '以色列人来到伯特利，坐在神面前直到晚上，放声痛哭，'),
('CUV', '士师记', 7, 21, 3, '说：耶和华─以色列的神啊，为何以色列中有这样缺了一支派的事呢？'),
('CUV', '士师记', 7, 21, 4, '次日清早，百姓起来，在那里筑了一座坛，献燔祭和平安祭。'),
('CUV', '士师记', 7, 21, 5, '以色列人彼此问说：以色列各支派中，谁没有同会众上到耶和华面前来呢？先是以色列人起过大誓说，凡不上米斯巴到耶和华面前来的，必将他治死。'),
('CUV', '士师记', 7, 21, 6, '以色列人为他们的弟兄便雅悯后悔，说：如今以色列中绝了一个支派了。'),
('CUV', '士师记', 7, 21, 7, '我们既在耶和华面前起誓说，必不将我们的女儿给便雅悯人为妻，现在我们当怎样办理、使他们剩下的人有妻呢？'),
('CUV', '士师记', 7, 21, 8, '又彼此问说：以色列支派中谁没有上米斯巴到耶和华面前来呢？他们就查出基列雅比没有一人进营到会众那里；'),
('CUV', '士师记', 7, 21, 9, '因为百姓被数的时候，没有一个基列雅比人在那里。'),
('CUV', '士师记', 7, 21, 10, '会众就打发一万二千大勇士，吩咐他们说：你们去用刀将基列雅比人连妇女带孩子都击杀了。'),
('CUV', '士师记', 7, 21, 11, '所当行的就是这样：要将一切男子和已嫁的女子尽行杀戮。'),
('CUV', '士师记', 7, 21, 12, '他们在基列雅比人中，遇见了四百个未嫁的处女，就带到迦南地的示罗营里。'),
('CUV', '士师记', 7, 21, 13, '全会众打发人到临门磐的便雅悯人那里，向他们说和睦的话。'),
('CUV', '士师记', 7, 21, 14, '当时便雅悯人回来了，以色列人就把所存活基列雅比的女子给他们为妻，还是不够。'),
('CUV', '士师记', 7, 21, 15, '百姓为便雅悯人后悔，因为耶和华使以色列人缺了一个支派（原文是使以色列中有了破口）。'),
('CUV', '士师记', 7, 21, 16, '会中的长老说：便雅悯中的女子既然除灭了，我们当怎样办理、使那余剩的人有妻呢？'),
('CUV', '士师记', 7, 21, 17, '又说：便雅悯逃脱的人当有地业，免得以色列中涂抹了一个支派。'),
('CUV', '士师记', 7, 21, 18, '只是我们不能将自己的女儿给他们为妻；因为以色列人曾起誓说，有将女儿给便雅悯人为妻的，必受咒诅。'),
('CUV', '士师记', 7, 21, 19, '他们又说：在利波拿以南，伯特利以北，在示剑大路以东的示罗，年年有耶和华的节期；'),
('CUV', '士师记', 7, 21, 20, '就吩咐便雅悯人说：你们去，在葡萄园中埋伏。'),
('CUV', '士师记', 7, 21, 21, '若看见示罗的女子出来跳舞，就从葡萄园出来，在示罗的女子中各抢一个为妻，回便雅悯地去。'),
('CUV', '士师记', 7, 21, 22, '他们的父亲或是弟兄若来与我们争竞，我们就说：求你们看我们的情面，施恩给这些人，因我们在争战的时候没有给他们留下女子为妻。这也不是你们将子女给他们的；若是你们给的，就算有罪。'),
('CUV', '士师记', 7, 21, 23, '于是便雅悯人照样而行，按著他们的数目从跳舞的女子中抢去为妻，就回自己的地业去，又重修城邑居住。'),
('CUV', '士师记', 7, 21, 24, '当时以色列人离开那里，各归本支派、本宗族、本地业去了。'),
('CUV', '士师记', 7, 21, 25, '那时，以色列中没有王，各人任意而行。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路得记', 8, 1, 1, '当士师秉政的时候，国中遭遇饥荒。在犹大、伯利恒，有一个人带著妻子和两个儿子往摩押地去寄居。'),
('CUV', '路得记', 8, 1, 2, '这人名叫以利米勒，他的妻名叫拿俄米；他两个儿子，一个名叫玛伦，一个名叫基连，都是犹大的伯利恒的以法他人。他们到了摩押地，就住在那里。'),
('CUV', '路得记', 8, 1, 3, '后来拿俄米的丈夫以利米勒死了，剩下妇人和他两个儿子。'),
('CUV', '路得记', 8, 1, 4, '这两个儿子娶了摩押女子为妻，一个名叫俄珥巴，一个名叫路得，在那里住了约有十年。'),
('CUV', '路得记', 8, 1, 5, '玛伦和基连二人也死了，剩下拿俄米，没有丈夫，也没有儿子。'),
('CUV', '路得记', 8, 1, 6, '他就与两个儿妇起身，要从摩押地归回；因为他在摩押地听见耶和华眷顾自己的百姓，赐粮食与他们。'),
('CUV', '路得记', 8, 1, 7, '于是他和两个儿妇起行离开所住的地方，要回犹大地去。'),
('CUV', '路得记', 8, 1, 8, '拿俄米对两个儿妇说：你们各人回娘家去罢。愿耶和华恩待你们，像你们恩待已死的人与我一样！'),
('CUV', '路得记', 8, 1, 9, '愿耶和华使你们各在新夫家中得平安！于是拿俄米与他们亲嘴。他们就放声而哭，'),
('CUV', '路得记', 8, 1, 10, '说：不然，我们必与你一同回你本国去。'),
('CUV', '路得记', 8, 1, 11, '拿俄米说：我女儿们哪，回去罢！为何要跟我去呢？我还能生子作你们的丈夫么？'),
('CUV', '路得记', 8, 1, 12, '我女儿们哪，回去罢！我年纪老迈，不能再有丈夫；即或说，我还有指望，今夜有丈夫可以生子，'),
('CUV', '路得记', 8, 1, 13, '你们岂能等著他们长大呢？你们岂能等著他们不嫁别人呢？我女儿们哪，不要这样。我为你们的缘故甚是愁苦，因为耶和华伸手攻击我。'),
('CUV', '路得记', 8, 1, 14, '两个儿妇又放声而哭，俄珥巴与婆婆亲嘴而别，只是路得舍不得拿俄米。'),
('CUV', '路得记', 8, 1, 15, '拿俄米说：看哪，你嫂子已经回他本国和他所拜的神那里去了，你也跟著你嫂子回去罢！'),
('CUV', '路得记', 8, 1, 16, '路得说：不要催我回去不跟随你。你往哪里去，我也往那里去；你在哪里住宿，我也在那里住宿；你的国就是我的国，你的神就是我的神。'),
('CUV', '路得记', 8, 1, 17, '你在哪里死，我也在那里死，也葬在那里。除非死能使你我相离！不然，愿耶和华重重地降罚与我。'),
('CUV', '路得记', 8, 1, 18, '拿俄米见路得定意要跟随自己去，就不再劝他了。'),
('CUV', '路得记', 8, 1, 19, '于是二人同行，来到伯利恒。他们到了伯利恒，合城的人就都惊讶。妇女们说：这是拿俄米么？'),
('CUV', '路得记', 8, 1, 20, '拿俄米对他们说：不要叫我拿俄米（就是甜的意思），要叫我玛拉（就是苦的意思），因为全能者使我受了大苦。'),
('CUV', '路得记', 8, 1, 21, '我满满地出去，耶和华使我空空地回来。耶和华降祸与我，全能者使我受苦。既是这样，你们为何还叫我拿俄米呢？'),
('CUV', '路得记', 8, 1, 22, '拿俄米和他儿妇摩押女子路得，从摩押地回来到伯利恒，正是动手割大麦的时候。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路得记', 8, 2, 1, '拿俄米的丈夫以利米勒的亲族中，有一个人名叫波阿斯，是个大财主。'),
('CUV', '路得记', 8, 2, 2, '摩押女子路得对拿俄米说：容我往田间去，我蒙谁的恩，就在谁的身后拾取麦穗。拿俄米说：女儿啊，你只管去。'),
('CUV', '路得记', 8, 2, 3, '路得就去了，来到田间，在收割的人身后拾取麦穗。他恰巧到了以利米勒本族的人波阿斯那块田里。'),
('CUV', '路得记', 8, 2, 4, '波阿斯正从伯利恒来，对收割的人说：愿耶和华与你们同在！他们回答说：愿耶和华赐福与你！'),
('CUV', '路得记', 8, 2, 5, '波阿斯问监管收割的仆人说：那是谁家的女子？'),
('CUV', '路得记', 8, 2, 6, '监管收割的仆人回答说：是那摩押女子，跟随拿俄米从摩押地回来的。'),
('CUV', '路得记', 8, 2, 7, '他说：请你容我跟著收割的人拾取打捆剩下的麦穗。他从早晨直到如今，除了在屋子里坐一会儿，常在这里。'),
('CUV', '路得记', 8, 2, 8, '波阿斯对路得说：女儿啊，听我说，不要往别人田里拾取麦穗，也不要离开这里，要常与我使女们在一处。'),
('CUV', '路得记', 8, 2, 9, '我的仆人在那块田收割，你就跟著他们去。我已经吩咐仆人不可欺负你；你若渴了，就可以到器皿那里喝仆人打来的水。'),
('CUV', '路得记', 8, 2, 10, '路得就俯伏在地叩拜，对他说：我既是外邦人，怎么蒙你的恩，这样顾恤我呢？'),
('CUV', '路得记', 8, 2, 11, '波阿斯回答说：自从你丈夫死后，凡你向婆婆所行的，并你离开父母和本地，到素不认识的民中，这些事人全都告诉我了。'),
('CUV', '路得记', 8, 2, 12, '愿耶和华照你所行的赏赐你。你来投靠耶和华─以色列神的翅膀下，愿你满得他的赏赐。'),
('CUV', '路得记', 8, 2, 13, '路得说：我主啊，愿在你眼前蒙恩。我虽然不及你的一个使女，你还用慈爱的话安慰我的心。'),
('CUV', '路得记', 8, 2, 14, '到了吃饭的时候，波阿斯对路得说：你到这里来吃饼，将饼蘸在醋里。路得就在收割的人旁边坐下；他们把烘了的穗子递给他。他吃饱了，还有余剩的。'),
('CUV', '路得记', 8, 2, 15, '他起来又拾取麦穗，波阿斯吩咐仆人说：他就是在捆中拾取麦穗，也可以容他，不可羞辱他；'),
('CUV', '路得记', 8, 2, 16, '并要从捆里抽出些来，留在地下任他拾取，不可叱吓他。'),
('CUV', '路得记', 8, 2, 17, '这样，路得在田间拾取麦穗，直到晚上，将所拾取的打了，约有一伊法大麦。'),
('CUV', '路得记', 8, 2, 18, '他就把所拾取的带进城去给婆婆看，又把他吃饱了所剩的给了婆婆。'),
('CUV', '路得记', 8, 2, 19, '婆婆问他说：你今日在哪里拾取麦穗，在哪里做工呢？愿那顾恤你的得福。路得就告诉婆婆说：我今日在一个名叫波阿斯的人那里做工。'),
('CUV', '路得记', 8, 2, 20, '拿俄米对儿妇说：愿那人蒙耶和华赐福，因为他不断地恩待活人死人。拿俄米又说：那是我们本族的人，是一个至近的亲属。'),
('CUV', '路得记', 8, 2, 21, '摩押女子路得说：他对我说：你要紧随我的仆人拾取麦穗，直等他们收完了我的庄稼。'),
('CUV', '路得记', 8, 2, 22, '拿俄米对儿妇路得说：女儿啊，你跟著他的使女出去，不叫人遇见你在别人田间，这才为好。'),
('CUV', '路得记', 8, 2, 23, '于是路得与波阿斯的使女常在一处拾取麦穗，直到收完了大麦和小麦。路得仍与婆婆同住。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路得记', 8, 3, 1, '路得的婆婆拿俄米对他说：女儿啊，我不当为你找个安身之处，使你享福么？'),
('CUV', '路得记', 8, 3, 2, '你与波阿斯的使女常在一处，波阿斯不是我们的亲族么？他今夜在场上簸大麦；'),
('CUV', '路得记', 8, 3, 3, '你要沐浴抹膏，换上衣服，下到场上，却不要使那人认出你来。你等他吃喝完了，'),
('CUV', '路得记', 8, 3, 4, '到他睡的时候，你看准他睡的地方，就进去掀开他脚上的被，躺卧在那里，他必告诉你所当做的事。'),
('CUV', '路得记', 8, 3, 5, '路得说：凡你所吩咐的，我必遵行。'),
('CUV', '路得记', 8, 3, 6, '路得就下到场上，照他婆婆所吩咐他的而行。'),
('CUV', '路得记', 8, 3, 7, '波阿斯吃喝完了，心里欢畅，就去睡在麦堆旁边。路得便悄悄地来掀开他脚上的被，躺卧在那里。'),
('CUV', '路得记', 8, 3, 8, '到了夜半，那人忽然惊醒，翻过身来，不料有女子躺在他的脚下。'),
('CUV', '路得记', 8, 3, 9, '他就说：你是谁？回答说：我是你的婢女路得。求你用你的衣襟遮盖我，因为你是我一个至近的亲属。'),
('CUV', '路得记', 8, 3, 10, '波阿斯说：女儿啊，愿你蒙耶和华赐福。你末后的恩比先前更大；因为少年人无论贫富，你都没有跟从。'),
('CUV', '路得记', 8, 3, 11, '女儿啊，现在不要惧怕，凡你所说的，我必照著行；我本城的人都知道你是个贤德的女子。'),
('CUV', '路得记', 8, 3, 12, '我实在是你一个至近的亲属，只是还有一个人比我更近。'),
('CUV', '路得记', 8, 3, 13, '你今夜在这里住宿，明早他若肯为你尽亲属的本分，就由他罢！倘若不肯，我指著永生的耶和华起誓，我必为你尽了本分，你只管躺到天亮。'),
('CUV', '路得记', 8, 3, 14, '路得便在他脚下躺到天快亮，人彼此不能辨认的时候就起来了。波阿斯说：不可使人知道有女子到场上来；'),
('CUV', '路得记', 8, 3, 15, '又对路得说：打开你所披的外衣。他打开了，波阿斯就撮了六簸箕大麦，帮他扛在肩上，他便进城去了。'),
('CUV', '路得记', 8, 3, 16, '路得回到婆婆那里，婆婆说：女儿啊，怎么样了？路得就将那人向他所行的述说了一遍，'),
('CUV', '路得记', 8, 3, 17, '又说：那人给了我六簸箕大麦，对我说：你不可空手回去见你的婆婆。'),
('CUV', '路得记', 8, 3, 18, '婆婆说：女儿啊，你只管安坐等候，看这事怎样成就，因为那人今日不办成这事必不休息。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路得记', 8, 4, 1, '波阿斯到了城门，坐在那里，恰巧波阿斯所说的那至近的亲属经过。波阿斯说：某人哪，你来坐在这里。他就来坐下。'),
('CUV', '路得记', 8, 4, 2, '波阿斯又从本城的长老中拣选了十人，对他们说：请你们坐在这里。他们就都坐下。'),
('CUV', '路得记', 8, 4, 3, '波阿斯对那至近的亲属说：从摩押地回来的拿俄米，现在要卖我们族兄以利米勒的那块地；'),
('CUV', '路得记', 8, 4, 4, '我想当赎那块地的是你，其次是我，以外再没有别人了。你可以在这里的人面前和我本国的长老面前说明，你若肯赎就赎，若不肯赎就告诉我。那人回答说：我肯赎。'),
('CUV', '路得记', 8, 4, 5, '波阿斯说：你从拿俄米手中买这地的时候，也当娶（原文是买；10节同）死人的妻摩押女子路得，使死人在产业上存留他的名。'),
('CUV', '路得记', 8, 4, 6, '那人说：这样我就不能赎了，恐怕于我的产业有碍。你可以赎我所当赎的，我不能赎了。'),
('CUV', '路得记', 8, 4, 7, '从前，在以色列中要定夺甚么事，或赎回，或交易，这人就脱鞋给那人。以色列人都以此为证据。'),
('CUV', '路得记', 8, 4, 8, '那人对波阿斯说：你自己买罢！于是将鞋脱下来了。'),
('CUV', '路得记', 8, 4, 9, '波阿斯对长老和众民说：你们今日作见证，凡属以利米勒和基连、玛伦的，我都从拿俄米手中置买了；'),
('CUV', '路得记', 8, 4, 10, '又娶了玛伦的妻摩押女子路得为妻，好在死人的产业上存留他的名，免得他的名在本族本乡灭没。你们今日可以作见证。'),
('CUV', '路得记', 8, 4, 11, '在城门坐著的众民和长老都说：我们作见证。愿耶和华使进你家的这女子，像建立以色列家的拉结、利亚二人一样。又愿你在以法他得亨通，在伯利恒得名声。'),
('CUV', '路得记', 8, 4, 12, '愿耶和华从这少年女子赐你后裔，使你的家像他玛从犹大所生法勒斯的家一般。'),
('CUV', '路得记', 8, 4, 13, '于是，波阿斯娶了路得为妻，与他同房。耶和华使他怀孕生了一个儿子。'),
('CUV', '路得记', 8, 4, 14, '妇人们对拿俄米说：耶和华是应当称颂的！因为今日没有撇下你，使你无至近的亲属。愿这孩子在以色列中得名声。'),
('CUV', '路得记', 8, 4, 15, '他必提起你的精神，奉养你的老，因为是爱慕你的那儿妇所生的。有这儿妇比有七个儿子还好！'),
('CUV', '路得记', 8, 4, 16, '拿俄米就把孩子抱在怀中，作他的养母。'),
('CUV', '路得记', 8, 4, 17, '邻舍的妇人说：拿俄米得孩子了！就给孩子起名叫俄备得。这俄备得是耶西的父，耶西是大卫的父。'),
('CUV', '路得记', 8, 4, 18, '法勒斯的后代记在下面：法勒斯生希斯仑；'),
('CUV', '路得记', 8, 4, 19, '希斯仑生兰；兰生亚米拿达；'),
('CUV', '路得记', 8, 4, 20, '亚米拿达生拿顺；拿顺生撒门；'),
('CUV', '路得记', 8, 4, 21, '撒门生波阿斯；波阿斯生俄备得；'),
('CUV', '路得记', 8, 4, 22, '俄备得生耶西；耶西生大卫。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 1, 1, '以法莲山地的拉玛琐非有一个以法莲人，名叫以利加拿，是苏弗的玄孙，托户的曾孙，以利户的孙子，耶罗罕的儿子。'),
('CUV', '撒母耳记上', 9, 1, 2, '他有两个妻：一名哈拿，一名毗尼拿。毗尼拿有儿女，哈拿没有儿女。'),
('CUV', '撒母耳记上', 9, 1, 3, '这人每年从本城上到示罗，敬拜祭祀万军之耶和华；在那里有以利的两个儿子何弗尼、非尼哈当耶和华的祭司。'),
('CUV', '撒母耳记上', 9, 1, 4, '以利加拿每逢献祭的日子，将祭肉分给他的妻毗尼拿和毗尼拿所生的儿女；'),
('CUV', '撒母耳记上', 9, 1, 5, '给哈拿的却是双分，因为他爱哈拿。无奈耶和华不使哈拿生育。'),
('CUV', '撒母耳记上', 9, 1, 6, '毗尼拿见耶和华不使哈拿生育，就作他的对头，大大激动他，要使他生气。'),
('CUV', '撒母耳记上', 9, 1, 7, '每年上到耶和华殿的时候，以利加拿都以双分给哈拿；毗尼拿仍是激动他，以致他哭泣不吃饭。'),
('CUV', '撒母耳记上', 9, 1, 8, '他丈夫以利加拿对他说：哈拿啊，你为何哭泣，不吃饭，心里愁闷呢？有我不比十个儿子还好么？'),
('CUV', '撒母耳记上', 9, 1, 9, '他们在示罗吃喝完了，哈拿就站起来。祭司以利在耶和华殿的门框旁边，坐在自己的位上。'),
('CUV', '撒母耳记上', 9, 1, 10, '哈拿心里愁苦，就痛痛哭泣，祈祷耶和华，'),
('CUV', '撒母耳记上', 9, 1, 11, '许愿说：万军之耶和华啊，你若垂顾婢女的苦情，眷念不忘婢女，赐我一个儿子，我必使他终身归与耶和华，不用剃头刀剃他的头。'),
('CUV', '撒母耳记上', 9, 1, 12, '哈拿在耶和华面前不住地祈祷，以利定睛看他的嘴。'),
('CUV', '撒母耳记上', 9, 1, 13, '（原来哈拿心中默祷，只动嘴唇，不出声音，因此以利以为他喝醉了。）'),
('CUV', '撒母耳记上', 9, 1, 14, '以利对他说：你要醉到几时呢？你不应该喝酒。'),
('CUV', '撒母耳记上', 9, 1, 15, '哈拿回答说：主啊，不是这样。我是心里愁苦的妇人，清酒浓酒都没有喝，但在耶和华面前倾心吐意。'),
('CUV', '撒母耳记上', 9, 1, 16, '不要将婢女看作不正经的女子。我因被人激动，愁苦太多，所以祈求到如今。'),
('CUV', '撒母耳记上', 9, 1, 17, '以利说：你可以平平安安地回去。愿以色列的神允准你向他所求的！'),
('CUV', '撒母耳记上', 9, 1, 18, '哈拿说：愿婢女在你眼前蒙恩。于是妇人走去吃饭，面上再不带愁容了。'),
('CUV', '撒母耳记上', 9, 1, 19, '次日清早，他们起来，在耶和华面前敬拜，就回拉玛。到了家里，以利加拿和妻哈拿同房，耶和华顾念哈拿，'),
('CUV', '撒母耳记上', 9, 1, 20, '哈拿就怀孕。日期满足，生了一个儿子，给他起名叫撒母耳，说：这是我从耶和华那里求来的。'),
('CUV', '撒母耳记上', 9, 1, 21, '以利加拿和他全家都上示罗去，要向耶和华献年祭，并还所许的愿。'),
('CUV', '撒母耳记上', 9, 1, 22, '哈拿却没有上去，对丈夫说：等孩子断了奶，我便带他上去朝见耶和华，使他永远住在那里。'),
('CUV', '撒母耳记上', 9, 1, 23, '他丈夫以利加拿说：就随你的意行罢！可以等儿子断了奶。但愿耶和华应验他的话。于是妇人在家里乳养儿子，直到断了奶；'),
('CUV', '撒母耳记上', 9, 1, 24, '既断了奶，就把孩子带上示罗，到了耶和华的殿；又带了三只公牛，一伊法细面，一皮袋酒。（那时，孩子还小。）'),
('CUV', '撒母耳记上', 9, 1, 25, '宰了一只公牛，就领孩子到以利面前。'),
('CUV', '撒母耳记上', 9, 1, 26, '妇人说：主啊，我敢在你面前起誓，从前在你这里站著祈求耶和华的那妇人，就是我。'),
('CUV', '撒母耳记上', 9, 1, 27, '我祈求为要得这孩子；耶和华已将我所求的赐给我了。'),
('CUV', '撒母耳记上', 9, 1, 28, '所以，我将这孩子归与耶和华，使他终身归与耶和华。于是在那里敬拜耶和华。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 2, 1, '哈拿祷告说：我的心因耶和华快乐；我的角因耶和华高举。我的口向仇敌张开；我因耶和华的救恩欢欣。'),
('CUV', '撒母耳记上', 9, 2, 2, '只有耶和华为圣；除他以外没有可比的，也没有磐石像我们的神。'),
('CUV', '撒母耳记上', 9, 2, 3, '人不要夸口说骄傲的话，也不要出狂妄的言语；因耶和华是大有智识的神，人的行为被他衡量。'),
('CUV', '撒母耳记上', 9, 2, 4, '勇士的弓都已折断；跌倒的人以力量束腰。'),
('CUV', '撒母耳记上', 9, 2, 5, '素来饱足的，反作用人求食；饥饿的，再不饥饿。不生育的，生了七个儿子；多有儿女的，反倒衰微。'),
('CUV', '撒母耳记上', 9, 2, 6, '耶和华使人死，也使人活，使人下阴间，也使人往上升。'),
('CUV', '撒母耳记上', 9, 2, 7, '他使人贫穷，也使人富足，使人卑微，也使人高贵。'),
('CUV', '撒母耳记上', 9, 2, 8, '他从灰尘里抬举贫寒人，从粪堆中提拔穷乏人，使他们与王子同坐，得著荣耀的座位。地的柱子属于耶和华；他将世界立在其上。'),
('CUV', '撒母耳记上', 9, 2, 9, '他必保护圣民的脚步，使恶人在黑暗中寂然不动；人都不能靠力量得胜。'),
('CUV', '撒母耳记上', 9, 2, 10, '与耶和华争竞的，必被打碎；耶和华必从天上以雷攻击他，必审判地极的人，将力量赐与所立的王，高举受膏者的角。'),
('CUV', '撒母耳记上', 9, 2, 11, '以利加拿往拉玛回家去了。那孩子在祭司以利面前事奉耶和华。'),
('CUV', '撒母耳记上', 9, 2, 12, '以利的两个儿子是恶人，不认识耶和华。'),
('CUV', '撒母耳记上', 9, 2, 13, '这二祭司待百姓是这样的规矩：凡有人献祭，正煮肉的时候，祭司的仆人就来，手拿三齿的叉子，'),
('CUV', '撒母耳记上', 9, 2, 14, '将叉子往罐里，或鼎里，或釜里，或锅里一插，插上来的肉，祭司都取了去。凡上到示罗的以色列人，他们都是这样看待。'),
('CUV', '撒母耳记上', 9, 2, 15, '又在未烧脂油以前，祭司的仆人就来对献祭的人说：将肉给祭司，叫他烤罢。他不要煮过的，要生的。'),
('CUV', '撒母耳记上', 9, 2, 16, '献祭的人若说：必须先烧脂油，然后你可以随意取肉。仆人就说：你立时给我，不然我便抢去。'),
('CUV', '撒母耳记上', 9, 2, 17, '如此，这二少年人的罪在耶和华面前甚重了，因为他们藐视耶和华的祭物（或译：他们使人厌弃给耶和华献祭）。'),
('CUV', '撒母耳记上', 9, 2, 18, '那时，撒母耳还是孩子，穿著细麻布的以弗得，侍立在耶和华面前。'),
('CUV', '撒母耳记上', 9, 2, 19, '他母亲每年为他做一件小外袍，同著丈夫上来献年祭的时候带来给他。'),
('CUV', '撒母耳记上', 9, 2, 20, '以利为以利加拿和他的妻祝福，说：愿耶和华由这妇人再赐你后裔，代替你从耶和华求来的孩子。他们就回本乡去了。'),
('CUV', '撒母耳记上', 9, 2, 21, '耶和华眷顾哈拿，他就怀孕生了三个儿子，两个女儿。那孩子撒母耳在耶和华面前渐渐长大。'),
('CUV', '撒母耳记上', 9, 2, 22, '以利年甚老迈，听见他两个儿子待以色列众人的事，又听见他们与会幕门前伺候的妇人苟合，'),
('CUV', '撒母耳记上', 9, 2, 23, '他就对他们说：你们为何行这样的事呢？我从这众百姓听见你们的恶行。'),
('CUV', '撒母耳记上', 9, 2, 24, '我儿啊，不可这样！我听见你们的风声不好，你们使耶和华的百姓犯了罪。'),
('CUV', '撒母耳记上', 9, 2, 25, '人若得罪人，有士师审判他；人若得罪耶和华，谁能为他祈求呢？然而他们还是不听父亲的话，因为耶和华想要杀他们。'),
('CUV', '撒母耳记上', 9, 2, 26, '孩子撒母耳渐渐长大，耶和华与人越发喜爱他。'),
('CUV', '撒母耳记上', 9, 2, 27, '有神人来见以利，对他说：耶和华如此说：你祖父在埃及法老家作奴仆的时候，我不是向他们显现么？'),
('CUV', '撒母耳记上', 9, 2, 28, '在以色列众支派中，我不是拣选人作我的祭司，使他烧香，在我坛上献祭，在我面前穿以弗得，又将以色列人所献的火祭都赐给你父家么？'),
('CUV', '撒母耳记上', 9, 2, 29, '我所吩咐献在我居所的祭物，你们为何践踏？尊重你的儿子过于尊重我，将我民以色列所献美好的祭物肥己呢？'),
('CUV', '撒母耳记上', 9, 2, 30, '因此，耶和华─以色列的神说：我曾说，你和你父家必永远行在我面前；现在我却说，决不容你们这样行。因为尊重我的，我必重看他；藐视我的，他必被轻视。'),
('CUV', '撒母耳记上', 9, 2, 31, '日子必到，我要折断你的膀臂和你父家的膀臂，使你家中没有一个老年人。'),
('CUV', '撒母耳记上', 9, 2, 32, '在神使以色列人享福的时候，你必看见我居所的败落。在你家中必永远没有一个老年人。'),
('CUV', '撒母耳记上', 9, 2, 33, '我必不从我坛前灭尽你家中的人；那未灭的必使你眼目干瘪、心中忧伤。你家中所生的人都必死在中年。'),
('CUV', '撒母耳记上', 9, 2, 34, '你的两个儿子何弗尼、非尼哈所遭遇的事可作你的证据：他们二人必一日同死。'),
('CUV', '撒母耳记上', 9, 2, 35, '我要为自己立一个忠心的祭司；他必照我的心意而行。我要为他建立坚固的家；他必永远行在我的受膏者面前。'),
('CUV', '撒母耳记上', 9, 2, 36, '你家所剩下的人都必来叩拜他，求块银子，求个饼，说：求你赐我祭司的职分，好叫我得点饼吃。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 3, 1, '童子撒母耳在以利面前事奉耶和华。当那些日子，耶和华的言语稀少，不常有默示。'),
('CUV', '撒母耳记上', 9, 3, 2, '一日，以利睡卧在自己的地方；他眼目昏花，看不分明。'),
('CUV', '撒母耳记上', 9, 3, 3, '神的灯在神耶和华殿内约柜那里，还没有熄灭，撒母耳已经睡了。'),
('CUV', '撒母耳记上', 9, 3, 4, '耶和华呼唤撒母耳。撒母耳说：我在这里！'),
('CUV', '撒母耳记上', 9, 3, 5, '就跑到以利那里，说：你呼唤我？我在这里。以利回答说：我没有呼唤你，你去睡罢。他就去睡了。'),
('CUV', '撒母耳记上', 9, 3, 6, '耶和华又呼唤撒母耳。撒母耳起来，到以利那里，说：你呼唤我？我在这里。以利回答说：我的儿，我没有呼唤你，你去睡罢。'),
('CUV', '撒母耳记上', 9, 3, 7, '那时撒母耳还未认识耶和华，也未得耶和华的默示。'),
('CUV', '撒母耳记上', 9, 3, 8, '耶和华第三次呼唤撒母耳。撒母耳起来，到以利那里，说：你又呼唤我？我在这里。以利才明白是耶和华呼唤童子。'),
('CUV', '撒母耳记上', 9, 3, 9, '因此以利对撒母耳说：你仍去睡罢；若再呼唤你，你就说：耶和华啊，请说，仆人敬听！撒母耳就去，仍睡在原处。'),
('CUV', '撒母耳记上', 9, 3, 10, '耶和华又来站著，像前三次呼唤说：撒母耳啊！撒母耳啊！撒母耳回答说：请说，仆人敬听！'),
('CUV', '撒母耳记上', 9, 3, 11, '耶和华对撒母耳说：我在以色列中必行一件事，叫听见的人都必耳鸣。'),
('CUV', '撒母耳记上', 9, 3, 12, '我指著以利家所说的话，到了时候，我必始终应验在以利身上。'),
('CUV', '撒母耳记上', 9, 3, 13, '我曾告诉他必永远降罚与他的家，因他知道儿子作孽，自招咒诅，却不禁止他们。'),
('CUV', '撒母耳记上', 9, 3, 14, '所以我向以利家起誓说：以利家的罪孽，虽献祭奉礼物，永不能得赎去。'),
('CUV', '撒母耳记上', 9, 3, 15, '撒母耳睡到天亮，就开了耶和华的殿门，不敢将默示告诉以利。'),
('CUV', '撒母耳记上', 9, 3, 16, '以利呼唤撒母耳说：我儿撒母耳啊！撒母耳回答说：我在这里！'),
('CUV', '撒母耳记上', 9, 3, 17, '以利说：耶和华对你说甚么，你不要向我隐瞒；你若将神对你所说的隐瞒一句，愿他重重地降罚与你。'),
('CUV', '撒母耳记上', 9, 3, 18, '撒母耳就把一切话都告诉了以利，并没有隐瞒。以利说：这是出于耶和华，愿他凭自己的意旨而行。'),
('CUV', '撒母耳记上', 9, 3, 19, '撒母耳长大了，耶和华与他同在，使他所说的话一句都不落空。'),
('CUV', '撒母耳记上', 9, 3, 20, '从但到别是巴所有的以色列人都知道耶和华立撒母耳为先知。'),
('CUV', '撒母耳记上', 9, 3, 21, '耶和华又在示罗显现；因为耶和华将自己的话默示撒母耳，撒母耳就把这话传遍以色列地。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 4, 1, '以色列人出去与非利士人打仗，安营在以便以谢；非利士人安营在亚弗。'),
('CUV', '撒母耳记上', 9, 4, 2, '非利士人向以色列人摆阵。两军交战的时候，以色列人败在非利士人面前；非利士人在战场上杀了他们的军兵约有四千人。'),
('CUV', '撒母耳记上', 9, 4, 3, '百姓回到营里，以色列的长老说：耶和华今日为何使我们败在非利士人面前呢？我们不如将耶和华的约柜从示罗抬到我们这里来，好在我们中间救我们脱离敌人的手。'),
('CUV', '撒母耳记上', 9, 4, 4, '于是百姓打发人到示罗，从那里将坐在二基路伯上万军之耶和华的约柜抬来。以利的两个儿子何弗尼、非尼哈与神的约柜同来。'),
('CUV', '撒母耳记上', 9, 4, 5, '耶和华的约柜到了营中，以色列众人就大声欢呼，地便震动。'),
('CUV', '撒母耳记上', 9, 4, 6, '非利士人听见欢呼的声音，就说：在希伯来人营里大声欢呼，是甚么缘故呢？随后就知道耶和华的约柜到了营中。'),
('CUV', '撒母耳记上', 9, 4, 7, '非利士人就惧怕起来，说：有神到了他们营中；又说：我们有祸了！向来不曾有这样的事。'),
('CUV', '撒母耳记上', 9, 4, 8, '我们有祸了！谁能救我们脱离这些大能之神的手呢？从前在旷野用各样灾殃击打埃及人的，就是这些神。'),
('CUV', '撒母耳记上', 9, 4, 9, '非利士人哪，你们要刚强，要作大丈夫，免得作希伯来人的奴仆，如同他们作你们的奴仆一样。你们要作大丈夫，与他们争战。'),
('CUV', '撒母耳记上', 9, 4, 10, '非利士人和以色列人打仗，以色列人败了，各向各家奔逃，被杀的人甚多，以色列的步兵仆倒了三万。'),
('CUV', '撒母耳记上', 9, 4, 11, '神的约柜被掳去，以利的两个儿子何弗尼、非尼哈也都被杀了。'),
('CUV', '撒母耳记上', 9, 4, 12, '当日，有一个便雅悯人从阵上逃跑，衣服撕裂，头蒙灰尘，来到示罗。'),
('CUV', '撒母耳记上', 9, 4, 13, '到了的时候，以利正在道旁坐在自己的位上观望，为神的约柜心里担忧。那人进城报信，合城的人就都呼喊起来。'),
('CUV', '撒母耳记上', 9, 4, 14, '以利听见呼喊的声音就问说：这喧嚷是甚么缘故呢？那人急忙来报信给以利。'),
('CUV', '撒母耳记上', 9, 4, 15, '那时以利九十八岁了，眼目发直，不能看见。'),
('CUV', '撒母耳记上', 9, 4, 16, '那人对以利说：我是从阵上来的，今日我从阵上逃回。以利说：我儿，事情怎样？'),
('CUV', '撒母耳记上', 9, 4, 17, '报信的回答说：以色列人在非利士人面前逃跑，民中被杀的甚多！你的两个儿子何弗尼、非尼哈也都死了，并且神的约柜被掳去。'),
('CUV', '撒母耳记上', 9, 4, 18, '他一提神的约柜，以利就从他的位上往后跌倒，在门旁折断颈项而死；因为他年纪老迈，身体沉重。以利作以色列的士师四十年。'),
('CUV', '撒母耳记上', 9, 4, 19, '以利的儿妇、非尼哈的妻怀孕将到产期，他听见神的约柜被掳去，公公和丈夫都死了，就猛然疼痛，曲身生产；'),
('CUV', '撒母耳记上', 9, 4, 20, '将要死的时候，旁边站著的妇人们对他说：不要怕！你生了男孩子了。他却不回答，也不放在心上。'),
('CUV', '撒母耳记上', 9, 4, 21, '他给孩子起名叫以迦博，说：荣耀离开以色列了！这是因神的约柜被掳去，又因他公公和丈夫都死了。'),
('CUV', '撒母耳记上', 9, 4, 22, '他又说：荣耀离开以色列，因为神的约柜被掳去了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 5, 1, '非利士人将神的约柜从以便以谢抬到亚实突。'),
('CUV', '撒母耳记上', 9, 5, 2, '非利士人将神的约柜抬进大衮庙，放在大衮的旁边。'),
('CUV', '撒母耳记上', 9, 5, 3, '次日清早，亚实突人起来，见大衮仆倒在耶和华的约柜前，脸伏于地，就把大衮仍立在原处。'),
('CUV', '撒母耳记上', 9, 5, 4, '又次日清早起来，见大衮仆倒在耶和华的约柜前，脸伏于地，并且大衮的头和两手都在门槛上折断，只剩下大衮的残体。'),
('CUV', '撒母耳记上', 9, 5, 5, '（因此，大衮的祭司和一切进亚实突、大衮庙的人都不踏大衮庙的门槛，直到今日。）'),
('CUV', '撒母耳记上', 9, 5, 6, '耶和华的手重重加在亚实突人身上，败坏他们，使他们生痔疮。亚实突和亚实突的四境都是如此。'),
('CUV', '撒母耳记上', 9, 5, 7, '亚实突人见这光景，就说：以色列神的约柜不可留在我们这里，因为他的手重重加在我们和我们神大衮的身上；'),
('CUV', '撒母耳记上', 9, 5, 8, '就打发人去请非利士的众首领来聚集，问他们说：我们向以色列神的约柜应当怎样行呢？他们回答说：可以将以色列神的约柜运到迦特去。于是将以色列神的约柜运到那里去。'),
('CUV', '撒母耳记上', 9, 5, 9, '运到之后，耶和华的手攻击那城，使那城的人大大惊慌，无论大小都生痔疮。'),
('CUV', '撒母耳记上', 9, 5, 10, '他们就把神的约柜送到以革伦。神的约柜到了，以革伦人就喊嚷起来说：他们将以色列神的约柜运到我们这里，要害我们和我们的众民！'),
('CUV', '撒母耳记上', 9, 5, 11, '于是打发人去请非利士的众首领来，说：愿你们将以色列神的约柜送回原处，免得害了我们和我们的众民！原来神的手重重攻击那城，城中的人有因惊慌而死的；'),
('CUV', '撒母耳记上', 9, 5, 12, '未曾死的人都生了痔疮。合城呼号，声音上达于天。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 6, 1, '耶和华的约柜在非利士人之地七个月。'),
('CUV', '撒母耳记上', 9, 6, 2, '非利士人将祭司和占卜的聚了来，问他们说：我们向耶和华的约柜应当怎样行？请指示我们用何法将约柜送回原处。'),
('CUV', '撒母耳记上', 9, 6, 3, '他们说：若要将以色列神的约柜送回去，不可空空地送去，必要给他献赔罪的礼物，然后你们可得痊愈，并知道他的手为何不离开你们。'),
('CUV', '撒母耳记上', 9, 6, 4, '非利士人说：应当用甚么献为赔罪的礼物呢？他们回答说：当照非利士首领的数目，用五个金痔疮，五个金老鼠，因为在你们众人和你们首领的身上都是一样的灾。'),
('CUV', '撒母耳记上', 9, 6, 5, '所以当制造你们痔疮的像和毁坏你们田地老鼠的像，并要归荣耀给以色列的神，或者他向你们和你们的神，并你们的田地，把手放轻些。'),
('CUV', '撒母耳记上', 9, 6, 6, '你们为何硬著心像埃及人和法老一样呢？神在埃及人中间行奇事，埃及人岂不释放以色列人，他们就去了么？'),
('CUV', '撒母耳记上', 9, 6, 7, '现在你们应当造一辆新车，将两只未曾负轭有乳的母牛套在车上，使牛犊回家去，离开母牛。'),
('CUV', '撒母耳记上', 9, 6, 8, '把耶和华的约柜放在车上，将所献赔罪的金物装在匣子里，放在柜旁，将柜送去。'),
('CUV', '撒母耳记上', 9, 6, 9, '你们要看看：车若直行以色列的境界到伯示麦去，这大灾就是耶和华降在我们身上的；若不然，便可以知道不是他的手击打我们，是我们偶然遇见的。'),
('CUV', '撒母耳记上', 9, 6, 10, '非利士人就这样行：将两只有乳的母牛套在车上，将牛犊关在家里，'),
('CUV', '撒母耳记上', 9, 6, 11, '把耶和华的约柜和装金老鼠并金痔疮像的匣子都放在车上。'),
('CUV', '撒母耳记上', 9, 6, 12, '牛直行大道，往伯示麦去，一面走一面叫，不偏左右。非利士的首领跟在后面，直到伯示麦的境界。'),
('CUV', '撒母耳记上', 9, 6, 13, '伯示麦人正在平原收割麦子，举目看见约柜，就欢喜了。'),
('CUV', '撒母耳记上', 9, 6, 14, '车到了伯示麦人约书亚的田间，就站住了。在那里有一块大磐石，他们把车劈了，将两只母牛献给耶和华为燔祭。'),
('CUV', '撒母耳记上', 9, 6, 15, '利未人将耶和华的约柜和装金物的匣子拿下来，放在大磐石上。当日伯示麦人将燔祭和平安祭献给耶和华。'),
('CUV', '撒母耳记上', 9, 6, 16, '非利士人的五个首领看见，当日就回以革伦去了。'),
('CUV', '撒母耳记上', 9, 6, 17, '非利士人献给耶和华作赔罪的金痔疮像，就是这些：一个是为亚实突，一个是为迦萨，一个是为亚实基伦，一个是为迦特，一个是为以革伦。'),
('CUV', '撒母耳记上', 9, 6, 18, '金老鼠的数目是照非利士五个首领的城邑，就是坚固的城邑和乡村，以及大磐石。这磐石是放耶和华约柜的，到今日还在伯示麦人约书亚的田间。'),
('CUV', '撒母耳记上', 9, 6, 19, '耶和华因伯示麦人擅观他的约柜，就击杀了他们七十人；那时有五万人在那里（原文是七十人加五万人）。百姓因耶和华大大击杀他们，就哀哭了。'),
('CUV', '撒母耳记上', 9, 6, 20, '伯示麦人说：谁能在耶和华这圣洁的神面前侍立呢？这约柜可以从我们这里送到谁那里去呢？'),
('CUV', '撒母耳记上', 9, 6, 21, '于是打发人去见基列耶琳的居民，说：非利士人将耶和华的约柜送回来了，你们下来将约柜接到你们那里去罢！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 7, 1, '基列耶琳人就下来，将耶和华的约柜接上去，放在山上亚比拿达的家中，分派他儿子以利亚撒看守耶和华的约柜。'),
('CUV', '撒母耳记上', 9, 7, 2, '约柜在基列耶琳许久。过了二十年，以色列全家都倾向耶和华。'),
('CUV', '撒母耳记上', 9, 7, 3, '撒母耳对以色列全家说：你们若一心归顺耶和华，就要把外邦的神和亚斯他录从你们中间除掉，专心归向耶和华，单单地事奉他。他必救你们脱离非利士人的手。'),
('CUV', '撒母耳记上', 9, 7, 4, '以色列人就除掉诸巴力和亚斯他录，单单地事奉耶和华。'),
('CUV', '撒母耳记上', 9, 7, 5, '撒母耳说：要使以色列众人聚集在米斯巴，我好为你们祷告耶和华。'),
('CUV', '撒母耳记上', 9, 7, 6, '他们就聚集在米斯巴，打水浇在耶和华面前，当日禁食，说：我们得罪了耶和华。于是撒母耳在米斯巴审判以色列人。'),
('CUV', '撒母耳记上', 9, 7, 7, '非利士人听见以色列人聚集在米斯巴，非利士的首领就上来要攻击以色列人。以色列人听见，就惧怕非利士人。'),
('CUV', '撒母耳记上', 9, 7, 8, '以色列人对撒母耳说：愿你不住地为我们呼求耶和华─我们的神，救我们脱离非利士人的手。'),
('CUV', '撒母耳记上', 9, 7, 9, '撒母耳就把一只吃奶的羊羔献与耶和华作全牲的燔祭，为以色列人呼求耶和华；耶和华就应允他。'),
('CUV', '撒母耳记上', 9, 7, 10, '撒母耳正献燔祭的时候，非利士人前来要与以色列人争战。当日，耶和华大发雷声，惊乱非利士人，他们就败在以色列人面前。'),
('CUV', '撒母耳记上', 9, 7, 11, '以色列人从米斯巴出来，追赶非利士人，击杀他们，直到伯甲的下边。'),
('CUV', '撒母耳记上', 9, 7, 12, '撒母耳将一块石头立在米斯巴和善的中间，给石头起名叫以便以谢，说：到如今耶和华都帮助我们。'),
('CUV', '撒母耳记上', 9, 7, 13, '从此，非利士人就被制伏，不敢再入以色列人的境内。撒母耳作士师的时候，耶和华的手攻击非利士人。'),
('CUV', '撒母耳记上', 9, 7, 14, '非利士人所取以色列人的城邑，从以革伦直到迦特，都归以色列人了。属这些城的四境，以色列人也从非利士人手下收回。那时以色列人与亚摩利人和好。'),
('CUV', '撒母耳记上', 9, 7, 15, '撒母耳平生作以色列的士师。'),
('CUV', '撒母耳记上', 9, 7, 16, '他每年巡行到伯特利、吉甲、米斯巴，在这几处审判以色列人。'),
('CUV', '撒母耳记上', 9, 7, 17, '随后回到拉玛，因为他的家在那里；也在那里审判以色列人，且为耶和华筑了一座坛。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 8, 1, '撒母耳年纪老迈，就立他儿子作以色列的士师。'),
('CUV', '撒母耳记上', 9, 8, 2, '长子名叫约珥，次子名叫亚比亚；他们在别是巴作士师。'),
('CUV', '撒母耳记上', 9, 8, 3, '他儿子不行他的道，贪图财利，收受贿赂，屈枉正直。'),
('CUV', '撒母耳记上', 9, 8, 4, '以色列的长老都聚集，来到拉玛见撒母耳，'),
('CUV', '撒母耳记上', 9, 8, 5, '对他说：你年纪老迈了，你儿子不行你的道。现在求你为我们立一个王治理我们，像列国一样。'),
('CUV', '撒母耳记上', 9, 8, 6, '撒母耳不喜悦他们说立一个王治理我们，他就祷告耶和华。'),
('CUV', '撒母耳记上', 9, 8, 7, '耶和华对撒母耳说：百姓向你说的一切话，你只管依从；因为他们不是厌弃你，乃是厌弃我，不要我作他们的王。'),
('CUV', '撒母耳记上', 9, 8, 8, '自从我领他们出埃及到如今，他们常常离弃我，事奉别神。现在他们向你所行的，是照他们素来所行的。'),
('CUV', '撒母耳记上', 9, 8, 9, '故此你要依从他们的话，只是当警戒他们，告诉他们将来那王怎样管辖他们。'),
('CUV', '撒母耳记上', 9, 8, 10, '撒母耳将耶和华的话都传给求他立王的百姓，说：'),
('CUV', '撒母耳记上', 9, 8, 11, '管辖你们的王必这样行：他必派你们的儿子为他赶车、跟马，奔走在车前；'),
('CUV', '撒母耳记上', 9, 8, 12, '又派他们作千夫长、五十夫长，为他耕种田地，收割庄稼，打造军器和车上的器械；'),
('CUV', '撒母耳记上', 9, 8, 13, '必取你们的女儿为他制造香膏，做饭烤饼；'),
('CUV', '撒母耳记上', 9, 8, 14, '也必取你们最好的田地、葡萄园、橄榄园赐给他的臣仆。'),
('CUV', '撒母耳记上', 9, 8, 15, '你们的粮食和葡萄园所出的，他必取十分之一给他的太监和臣仆；'),
('CUV', '撒母耳记上', 9, 8, 16, '又必取你们的仆人婢女，健壮的少年人和你们的驴，供他的差役。'),
('CUV', '撒母耳记上', 9, 8, 17, '你们的羊群，他必取十分之一，你们也必作他的仆人。'),
('CUV', '撒母耳记上', 9, 8, 18, '那时你们必因所选的王哀求耶和华，耶和华却不应允你们。'),
('CUV', '撒母耳记上', 9, 8, 19, '百姓竟不肯听撒母耳的话，说：不然！我们定要一个王治理我们，'),
('CUV', '撒母耳记上', 9, 8, 20, '使我们像列国一样，有王治理我们，统领我们，为我们争战。'),
('CUV', '撒母耳记上', 9, 8, 21, '撒母耳听见百姓这一切话，就将这话陈明在耶和华面前。'),
('CUV', '撒母耳记上', 9, 8, 22, '耶和华对撒母耳说：你只管依从他们的话，为他们立王。撒母耳对以色列人说：你们各归各城去罢！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 9, 1, '有一个便雅悯人，名叫基士，是便雅悯人亚斐亚的玄孙，比歌拉的曾孙，洗罗的孙子，亚别的儿子，是个大能的勇士（或译：大财主）。'),
('CUV', '撒母耳记上', 9, 9, 2, '他有一个儿子，名叫扫罗，又健壮、又俊美，在以色列人中没有一个能比他的；身体比众民高过一头。'),
('CUV', '撒母耳记上', 9, 9, 3, '扫罗的父亲基士丢了几头驴，他就吩咐儿子扫罗说：你带一个仆人去寻找驴。'),
('CUV', '撒母耳记上', 9, 9, 4, '扫罗就走过以法莲山地，又过沙利沙地，都没有找著；又过沙琳地，驴也不在那里；又过便雅悯地，还没有找著。'),
('CUV', '撒母耳记上', 9, 9, 5, '到了苏弗地，扫罗对跟随他的仆人说：我们不如回去，恐怕我父亲不为驴挂心，反为我们担忧。'),
('CUV', '撒母耳记上', 9, 9, 6, '仆人说：这城里有一位神人，是众人所尊重的，凡他所说的全都应验。我们不如往他那里去，或者他能将我们当走的路指示我们。'),
('CUV', '撒母耳记上', 9, 9, 7, '扫罗对仆人说：我们若去，有甚么可以送那人呢？我们囊中的食物都吃尽了，也没有礼物可以送那神人，我们还有甚么没有？'),
('CUV', '撒母耳记上', 9, 9, 8, '仆人回答扫罗说：我手里有银子一舍客勒的四分之一，可以送那神人，请他指示我们当走的路。'),
('CUV', '撒母耳记上', 9, 9, 9, '（从前以色列中，若有人去问神，就说：我们问先见去罢！现在称为先知的，从前称为先见。）'),
('CUV', '撒母耳记上', 9, 9, 10, '扫罗对仆人说：你说的是，我们可以去。于是他们往神人所住的城里去了。'),
('CUV', '撒母耳记上', 9, 9, 11, '他们上坡要进城，就遇见几个少年女子出来打水，问他们说：先见在这里没有？'),
('CUV', '撒母耳记上', 9, 9, 12, '女子回答说：在这里，他在你们前面。快去罢！他今日正到城里，因为今日百姓要在邱坛献祭。'),
('CUV', '撒母耳记上', 9, 9, 13, '在他还没有上邱坛吃祭物之先，你们一进城必遇见他；因他未到，百姓不能吃，必等他先祝祭，然后请的客才吃。现在你们上去，这时候必遇见他。'),
('CUV', '撒母耳记上', 9, 9, 14, '二人就上去；将进城的时候，撒母耳正迎著他们来，要上邱坛去。'),
('CUV', '撒母耳记上', 9, 9, 15, '扫罗未到的前一日，耶和华已经指示撒母耳说：'),
('CUV', '撒母耳记上', 9, 9, 16, '明日这时候，我必使一个人从便雅悯地到你这里来，你要膏他作我民以色列的君。他必救我民脱离非利士人的手；因我民的哀声上达于我，我就眷顾他们。'),
('CUV', '撒母耳记上', 9, 9, 17, '撒母耳看见扫罗的时候，耶和华对他说：看哪，这人就是我对你所说的，他必治理我的民。'),
('CUV', '撒母耳记上', 9, 9, 18, '扫罗在城门里走到撒母耳跟前，说：请告诉我，先见的寓所在哪里？'),
('CUV', '撒母耳记上', 9, 9, 19, '撒母耳回答说：我就是先见。你在我前面上邱坛去，因为你们今日必与我同席；明日早晨我送你去，将你心里的事都告诉你。'),
('CUV', '撒母耳记上', 9, 9, 20, '至于你前三日所丢的那几头驴，你心里不必挂念，已经找著了。以色列众人所仰慕的是谁呢？不是仰慕你和你父的全家么？'),
('CUV', '撒母耳记上', 9, 9, 21, '扫罗说：我不是以色列支派中至小的便雅悯人么？我家不是便雅悯支派中至小的家么？你为何对我说这样的话呢？'),
('CUV', '撒母耳记上', 9, 9, 22, '撒母耳领扫罗和他仆人进了客堂，使他们在请来的客中坐首位；客约有三十个人。'),
('CUV', '撒母耳记上', 9, 9, 23, '撒母耳对厨役说：我交给你收存的那一分祭肉现在可以拿来。'),
('CUV', '撒母耳记上', 9, 9, 24, '厨役就把收存的腿拿来，摆在扫罗面前，撒母耳说：这是所留下的，放在你面前。吃罢！因我请百姓的时候，特意为你存留这肉到此时。当日，扫罗就与撒母耳同席。'),
('CUV', '撒母耳记上', 9, 9, 25, '众人从邱坛下来进城，撒母耳和扫罗在房顶上说话。'),
('CUV', '撒母耳记上', 9, 9, 26, '次日清早起来，黎明的时候，扫罗在房顶上。撒母耳呼叫他说：起来罢，我好送你回去。扫罗就起来，和撒母耳一同出去。'),
('CUV', '撒母耳记上', 9, 9, 27, '二人下到城角，撒母耳对扫罗说：要吩咐仆人先走（仆人就先走了）；你且站在这里，等我将神的话传与你听。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 10, 1, '撒母耳拿瓶膏油倒在扫罗的头上，与他亲嘴，说：这不是耶和华膏你作他产业的君么？'),
('CUV', '撒母耳记上', 9, 10, 2, '你今日与我离别之后，在便雅悯境内的泄撒，靠近拉结的坟墓，要遇见两个人。他们必对你说：你去找的那几头驴已经找著了。现在你父亲不为驴挂心，反为你担忧，说：我为儿子怎么才好呢？'),
('CUV', '撒母耳记上', 9, 10, 3, '你从那里往前行，到了他泊的橡树那里，必遇见三个往伯特利去拜神的人：一个带著三只山羊羔，一个带著三个饼，一个带著一皮袋酒。'),
('CUV', '撒母耳记上', 9, 10, 4, '他们必问你安，给你两个饼，你就从他们手中接过来。'),
('CUV', '撒母耳记上', 9, 10, 5, '此后你到神的山，在那里有非利士人的防兵。你到了城的时候，必遇见一班先知从邱坛下来，前面有鼓瑟的、击鼓的、吹笛的、弹琴的，他们都受感说话。'),
('CUV', '撒母耳记上', 9, 10, 6, '耶和华的灵必大大感动你，你就与他们一同受感说话；你要变为新人。'),
('CUV', '撒母耳记上', 9, 10, 7, '这兆头临到你，你就可以趁时而做，因为神与你同在。'),
('CUV', '撒母耳记上', 9, 10, 8, '你当在我以先下到吉甲，我也必下到那里献燔祭和平安祭。你要等候七日，等我到了那里，指示你当行的事。'),
('CUV', '撒母耳记上', 9, 10, 9, '扫罗转身离别撒母耳，神就赐他一个新心。当日这一切兆头都应验了。'),
('CUV', '撒母耳记上', 9, 10, 10, '扫罗到了那山，有一班先知遇见他，神的灵大大感动他，他就在先知中受感说话。'),
('CUV', '撒母耳记上', 9, 10, 11, '素来认识扫罗的，看见他和先知一同受感说话，就彼此说：基士的儿子遇见甚么了？扫罗也列在先知中么？'),
('CUV', '撒母耳记上', 9, 10, 12, '那地方有一个人说：这些人的父亲是谁呢？此后有句俗语说：扫罗也列在先知中么？'),
('CUV', '撒母耳记上', 9, 10, 13, '扫罗受感说话已毕，就上邱坛去了。'),
('CUV', '撒母耳记上', 9, 10, 14, '扫罗的叔叔问扫罗和他仆人说：你们往哪里去了？回答说：找驴去了。我们见没有驴，就到了撒母耳那里。'),
('CUV', '撒母耳记上', 9, 10, 15, '扫罗的叔叔说：请将撒母耳向你们所说的话告诉我。'),
('CUV', '撒母耳记上', 9, 10, 16, '扫罗对他叔叔说：他明明地告诉我们驴已经找著了。至于撒母耳所说的国事，扫罗却没有告诉叔叔。'),
('CUV', '撒母耳记上', 9, 10, 17, '撒母耳将百姓招聚到米斯巴耶和华那里，'),
('CUV', '撒母耳记上', 9, 10, 18, '对他们说：耶和华─以色列的神如此说：我领你们以色列人出埃及，救你们脱离埃及人的手，又救你们脱离欺压你们各国之人的手。'),
('CUV', '撒母耳记上', 9, 10, 19, '你们今日却厌弃了救你们脱离一切灾难的神，说：求你立一个王治理我们。现在你们应当按著支派、宗族都站在耶和华面前。'),
('CUV', '撒母耳记上', 9, 10, 20, '于是，撒母耳使以色列众支派近前来掣签，就掣出便雅悯支派来；'),
('CUV', '撒母耳记上', 9, 10, 21, '又使便雅悯支派按著宗族近前来，就掣出玛特利族，从其中又掣出基士的儿子扫罗。众人寻找他却寻不著，'),
('CUV', '撒母耳记上', 9, 10, 22, '就问耶和华说：那人到这里来了没有？耶和华说：他藏在器具中了。'),
('CUV', '撒母耳记上', 9, 10, 23, '众人就跑去从那里领出他来。他站在百姓中间，身体比众民高过一头。'),
('CUV', '撒母耳记上', 9, 10, 24, '撒母耳对众民说：你们看耶和华所拣选的人，众民中有可比他的么？众民就大声欢呼说：愿王万岁！'),
('CUV', '撒母耳记上', 9, 10, 25, '撒母耳将国法对百姓说明，又记在书上，放在耶和华面前，然后遣散众民，各回各家去了。'),
('CUV', '撒母耳记上', 9, 10, 26, '扫罗往基比亚回家去，有神感动的一群人跟随他。'),
('CUV', '撒母耳记上', 9, 10, 27, '但有些匪徒说：这人怎能救我们呢？就藐视他，没有送他礼物；扫罗却不理会。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 11, 1, '亚扪人的王拿辖上来，对著基列雅比安营。雅比众人对拿辖说：你与我们立约，我们就服事你。'),
('CUV', '撒母耳记上', 9, 11, 2, '亚扪人拿辖说：你们若由我剜出你们各人的右眼，以此凌辱以色列众人，我就与你们立约。'),
('CUV', '撒母耳记上', 9, 11, 3, '雅比的长老对他说：求你宽容我们七日，等我们打发人往以色列的全境去；若没有人救我们，我们就出来归顺你。'),
('CUV', '撒母耳记上', 9, 11, 4, '使者到了扫罗住的基比亚，将这话说给百姓听，百姓就都放声而哭。'),
('CUV', '撒母耳记上', 9, 11, 5, '扫罗正从田间赶牛回来，问说：百姓为甚么哭呢？众人将雅比人的话告诉他。'),
('CUV', '撒母耳记上', 9, 11, 6, '扫罗听见这话，就被神的灵大大感动，甚是发怒。'),
('CUV', '撒母耳记上', 9, 11, 7, '他将一对牛切成块子，托付使者传送以色列的全境，说：凡不出来跟随扫罗和撒母耳的，也必这样切开他的牛。于是耶和华使百姓惧怕，他们就都出来，如同一人。'),
('CUV', '撒母耳记上', 9, 11, 8, '扫罗在比色数点他们：以色列人有三十万，犹大人有三万。'),
('CUV', '撒母耳记上', 9, 11, 9, '众人对那使者说：你们要回复基列雅比人说，明日太阳近午的时候，你们必得解救。使者回去告诉雅比人，他们就欢喜了。'),
('CUV', '撒母耳记上', 9, 11, 10, '于是雅比人对亚扪人说：明日我们出来归顺你们，你们可以随意待我们。'),
('CUV', '撒母耳记上', 9, 11, 11, '第二日，扫罗将百姓分为三队，在晨更的时候入了亚扪人的营，击杀他们直到太阳近午，剩下的人都逃散，没有二人同在一处的。'),
('CUV', '撒母耳记上', 9, 11, 12, '百姓对撒母耳说：那说扫罗岂能管理我们的是谁呢？可以将他交出来，我们好杀死他。'),
('CUV', '撒母耳记上', 9, 11, 13, '扫罗说：今日耶和华在以色列中施行拯救，所以不可杀人。'),
('CUV', '撒母耳记上', 9, 11, 14, '撒母耳对百姓说：我们要往吉甲去，在那里立国。'),
('CUV', '撒母耳记上', 9, 11, 15, '众百姓就到了吉甲那里，在耶和华面前立扫罗为王，又在耶和华面前献平安祭。扫罗和以色列众人大大欢喜。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 12, 1, '撒母耳对以色列众人说：你们向我所求的，我已应允了，为你们立了一个王；'),
('CUV', '撒母耳记上', 9, 12, 2, '现在有这王在你们前面行。我已年老发白，我的儿子都在你们这里。我从幼年直到今日都在你们前面行。'),
('CUV', '撒母耳记上', 9, 12, 3, '我在这里，你们要在耶和华和他的受膏者面前给我作见证。我夺过谁的牛，抢过谁的驴，欺负过谁，虐待过谁，从谁手里受过贿赂因而眼瞎呢？若有，我必偿还。'),
('CUV', '撒母耳记上', 9, 12, 4, '众人说：你未曾欺负我们，虐待我们，也未曾从谁手里受过甚么。'),
('CUV', '撒母耳记上', 9, 12, 5, '撒母耳对他们说：你们在我手里没有找著甚么，有耶和华和他的受膏者今日为证。他们说：愿他为证。'),
('CUV', '撒母耳记上', 9, 12, 6, '撒母耳对百姓说：从前立摩西、亚伦，又领你们列祖出埃及地的是耶和华。'),
('CUV', '撒母耳记上', 9, 12, 7, '现在你们要站住，等我在耶和华面前对你们讲论耶和华向你们和你们列祖所行一切公义的事。'),
('CUV', '撒母耳记上', 9, 12, 8, '从前雅各到了埃及，后来你们列祖呼求耶和华，耶和华就差遣摩西、亚伦领你们列祖出埃及，使他们在这地方居住。'),
('CUV', '撒母耳记上', 9, 12, 9, '他们却忘记耶和华─他们的神，他就把他们付与夏琐将军西西拉的手里，和非利士人并摩押王的手里。于是这些人常来攻击他们。'),
('CUV', '撒母耳记上', 9, 12, 10, '他们就呼求耶和华说：我们离弃耶和华，事奉巴力和亚斯他录，是有罪了。现在求你救我们脱离仇敌的手，我们必事奉你。'),
('CUV', '撒母耳记上', 9, 12, 11, '耶和华就差遣耶路巴力、比但、耶弗他、撒母耳救你们脱离四围仇敌的手，你们才安然居住。'),
('CUV', '撒母耳记上', 9, 12, 12, '你们见亚扪人的王拿辖来攻击你们，就对我说：我们定要一个王治理我们。其实耶和华─你们的神是你们的王。'),
('CUV', '撒母耳记上', 9, 12, 13, '现在，你们所求所选的王在这里。看哪，耶和华已经为你们立王了。'),
('CUV', '撒母耳记上', 9, 12, 14, '你们若敬畏耶和华，事奉他，听从他的话，不违背他的命令，你们和治理你们的王也都顺从耶和华─你们的神就好了。'),
('CUV', '撒母耳记上', 9, 12, 15, '倘若不听从耶和华的话，违背他的命令，耶和华的手必攻击你们，像从前攻击你们列祖一样。'),
('CUV', '撒母耳记上', 9, 12, 16, '现在你们要站住，看耶和华在你们眼前要行一件大事。'),
('CUV', '撒母耳记上', 9, 12, 17, '这不是割麦子的时候么？我求告耶和华，他必打雷降雨，使你们又知道又看出，你们求立王的事是在耶和华面前犯大罪了。'),
('CUV', '撒母耳记上', 9, 12, 18, '于是撒母耳求告耶和华，耶和华就在这日打雷降雨，众民便甚惧怕耶和华和撒母耳。'),
('CUV', '撒母耳记上', 9, 12, 19, '众民对撒母耳说：求你为仆人们祷告耶和华─你的神，免得我们死亡，因为我们求立王的事正是罪上加罪了。'),
('CUV', '撒母耳记上', 9, 12, 20, '撒母耳对百姓说：不要惧怕！你们虽然行了这恶，却不要偏离耶和华，只要尽心事奉他。'),
('CUV', '撒母耳记上', 9, 12, 21, '若偏离耶和华去顺从那不能救人的虚神是无益的。'),
('CUV', '撒母耳记上', 9, 12, 22, '耶和华既喜悦选你们作他的子民，就必因他的大名不撇弃你们。'),
('CUV', '撒母耳记上', 9, 12, 23, '至于我，断不停止为你们祷告，以致得罪耶和华。我必以善道正路指教你们。'),
('CUV', '撒母耳记上', 9, 12, 24, '只要你们敬畏耶和华，诚诚实实地尽心事奉他，想念他向你们所行的事何等大。'),
('CUV', '撒母耳记上', 9, 12, 25, '你们若仍然作恶，你们和你们的王必一同灭亡。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 13, 1, '扫罗登基年四十岁；作以色列王二年的时候，'),
('CUV', '撒母耳记上', 9, 13, 2, '就从以色列中拣选了三千人：二千跟随扫罗在密抹和伯特利山，一千跟随约拿单在便雅悯的基比亚；其余的人扫罗都打发各回各家去了。'),
('CUV', '撒母耳记上', 9, 13, 3, '约拿单攻击迦巴、非利士人的防营，非利士人听见了。扫罗就在遍地吹角，意思说，要使希伯来人听见。'),
('CUV', '撒母耳记上', 9, 13, 4, '以色列众人听见扫罗攻击非利士人的防营，又听见以色列人为非利士人所憎恶，就跟随扫罗聚集在吉甲。'),
('CUV', '撒母耳记上', 9, 13, 5, '非利士人聚集，要与以色列人争战，有车三万辆，马兵六千，步兵像海边的沙那样多，就上来在伯亚文东边的密抹安营。'),
('CUV', '撒母耳记上', 9, 13, 6, '以色列百姓见自己危急窘迫，就藏在山洞、丛林、石穴、隐密处，和坑中。'),
('CUV', '撒母耳记上', 9, 13, 7, '有些希伯来人过了约但河，逃到迦得和基列地。扫罗还是在吉甲，百姓都战战兢兢地跟随他。'),
('CUV', '撒母耳记上', 9, 13, 8, '扫罗照著撒母耳所定的日期等了七日。撒母耳还没有来到吉甲，百姓也离开扫罗散去了。'),
('CUV', '撒母耳记上', 9, 13, 9, '扫罗说：把燔祭和平安祭带到我这里来。扫罗就献上燔祭。'),
('CUV', '撒母耳记上', 9, 13, 10, '刚献完燔祭，撒母耳就到了。扫罗出去迎接他，要问他好。'),
('CUV', '撒母耳记上', 9, 13, 11, '撒母耳说：你做的是甚么事呢？扫罗说：因为我见百姓离开我散去，你也不照所定的日期来到，而且非利士人聚集在密抹。'),
('CUV', '撒母耳记上', 9, 13, 12, '所以我心里说：恐怕我没有祷告耶和华。非利士人下到吉甲攻击我，我就勉强献上燔祭。'),
('CUV', '撒母耳记上', 9, 13, 13, '撒母耳对扫罗说：你做了糊涂事了，没有遵守耶和华─你神所吩咐你的命令。若遵守，耶和华必在以色列中坚立你的王位，直到永远。'),
('CUV', '撒母耳记上', 9, 13, 14, '现在你的王位必不长久。耶和华已经寻著一个合他心意的人，立他作百姓的君，因为你没有遵守耶和华所吩咐你的。'),
('CUV', '撒母耳记上', 9, 13, 15, '撒母耳就起来，从吉甲上到便雅悯的基比亚。扫罗数点跟随他的，约有六百人。'),
('CUV', '撒母耳记上', 9, 13, 16, '扫罗和他儿子约拿单，并跟随他们的人，都住在便雅悯的迦巴；但非利士人安营在密抹。'),
('CUV', '撒母耳记上', 9, 13, 17, '有掠兵从非利士营中出来，分为三队：一队往俄弗拉向书亚地去，'),
('CUV', '撒母耳记上', 9, 13, 18, '一队往伯和仑去，一队往洗波音谷对面的地境向旷野去。'),
('CUV', '撒母耳记上', 9, 13, 19, '那时，以色列全地没有一个铁匠；因为非利士人说，恐怕希伯来人制造刀枪。'),
('CUV', '撒母耳记上', 9, 13, 20, '以色列人要磨锄、犁、斧、铲，就下到非利士人那里去磨。'),
('CUV', '撒母耳记上', 9, 13, 21, '但有锉可以锉铲、犁、三齿叉、斧子，并赶牛锥。'),
('CUV', '撒母耳记上', 9, 13, 22, '所以到了争战的日子，跟随扫罗和约拿单的人没有一个手里有刀有枪的，惟独扫罗和他儿子约拿单有。'),
('CUV', '撒母耳记上', 9, 13, 23, '非利士人的一队防兵到了密抹的隘口。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 14, 1, '有一日，扫罗的儿子约拿单对拿他兵器的少年人说：我们不如过到那边，到非利士人的防营那里去。但他没有告诉父亲。'),
('CUV', '撒母耳记上', 9, 14, 2, '扫罗在基比亚的尽边，坐在米矶仑的石榴树下，跟随他的约有六百人。'),
('CUV', '撒母耳记上', 9, 14, 3, '在那里有亚希突的儿子亚希亚，穿著以弗得。（亚希突是以迦博的哥哥，非尼哈的儿子，以利的孙子。以利从前在示罗作耶和华的祭司。）约拿单去了，百姓却不知道。'),
('CUV', '撒母耳记上', 9, 14, 4, '约拿单要从隘口过到非利士防营那里去。这隘口两边各有一个山峰：一名播薛，一名西尼；'),
('CUV', '撒母耳记上', 9, 14, 5, '一峰向北，与密抹相对，一峰向南，与迦巴相对。'),
('CUV', '撒母耳记上', 9, 14, 6, '约拿单对拿兵器的少年人说：我们不如过到未受割礼人的防营那里去，或者耶和华为我们施展能力；因为耶和华使人得胜，不在乎人多人少。'),
('CUV', '撒母耳记上', 9, 14, 7, '拿兵器的对他说：随你的心意行罢。你可以上去，我必跟随你，与你同心。'),
('CUV', '撒母耳记上', 9, 14, 8, '约拿单说：我们要过到那些人那里去，使他们看见我们。'),
('CUV', '撒母耳记上', 9, 14, 9, '他们若对我们说：你们站住，等我们到你们那里去，我们就站住，不上他们那里去。'),
('CUV', '撒母耳记上', 9, 14, 10, '他们若说：你们上到我们这里来，这话就是我们的证据；我们便上去，因为耶和华将他们交在我们手里了。'),
('CUV', '撒母耳记上', 9, 14, 11, '二人就使非利士的防兵看见。非利士人说：希伯来人从所藏的洞穴里出来了！'),
('CUV', '撒母耳记上', 9, 14, 12, '防兵对约拿单和拿兵器的人说：你们上到这里来，我们有一件事指示你们。约拿单就对拿兵器的人说：你跟随我上去，因为耶和华将他们交在以色列人手里了。'),
('CUV', '撒母耳记上', 9, 14, 13, '约拿单就爬上去，拿兵器的人跟随他。约拿单杀倒非利士人，拿兵器的人也随著杀他们。'),
('CUV', '撒母耳记上', 9, 14, 14, '约拿单和拿兵器的人起头所杀的约有二十人，都在一亩地的半犁沟之内。'),
('CUV', '撒母耳记上', 9, 14, 15, '于是在营中、在田野、在众民内都有战兢，防兵和掠兵也都战兢，地也震动，战兢之势甚大。'),
('CUV', '撒母耳记上', 9, 14, 16, '在便雅悯的基比亚，扫罗的守望兵看见非利士的军众溃散，四围乱窜。'),
('CUV', '撒母耳记上', 9, 14, 17, '扫罗就对跟随他的民说：你们查点查点，看从我们这里出去的是谁？他们一查点，就知道约拿单和拿兵器的人没有在这里。'),
('CUV', '撒母耳记上', 9, 14, 18, '那时神的约柜在以色列人那里。扫罗对亚希亚说：你将神的约柜运了来。'),
('CUV', '撒母耳记上', 9, 14, 19, '扫罗正与祭司说话的时候，非利士营中的喧嚷越发大了；扫罗就对祭司说：停手罢！'),
('CUV', '撒母耳记上', 9, 14, 20, '扫罗和跟随他的人都聚集，来到战场，看见非利士人用刀互相击杀，大大惶乱。'),
('CUV', '撒母耳记上', 9, 14, 21, '从前由四方来跟随非利士军的希伯来人现在也转过来，帮助跟随扫罗和约拿单的以色列人了。'),
('CUV', '撒母耳记上', 9, 14, 22, '那藏在以法莲山地的以色列人听说非利士人逃跑，就出来紧紧地追杀他们。'),
('CUV', '撒母耳记上', 9, 14, 23, '那日，耶和华使以色列人得胜，一直战到伯亚文。'),
('CUV', '撒母耳记上', 9, 14, 24, '扫罗叫百姓起誓说，凡不等到晚上向敌人报完了仇吃甚么的，必受咒诅。因此这日百姓没有吃甚么，就极其困惫。'),
('CUV', '撒母耳记上', 9, 14, 25, '众民进入树林，见有蜜在地上。'),
('CUV', '撒母耳记上', 9, 14, 26, '他们进了树林，见有蜜流下来，却没有人敢用手取蜜入口，因为他们怕那誓言。'),
('CUV', '撒母耳记上', 9, 14, 27, '约拿单没有听见他父亲叫百姓起誓，所以伸手中的杖，用杖头蘸在蜂房里，转手送入口内，眼睛就明亮了。'),
('CUV', '撒母耳记上', 9, 14, 28, '百姓中有一人对他说：你父亲曾叫百姓严严地起誓说，今日吃甚么的，必受咒诅；因此百姓就疲乏了。'),
('CUV', '撒母耳记上', 9, 14, 29, '约拿单说：我父亲连累你们了。你看，我尝了这一点蜜，眼睛就明亮了。'),
('CUV', '撒母耳记上', 9, 14, 30, '今日百姓若任意吃了从仇敌所夺的物，击杀的非利士人岂不更多么？'),
('CUV', '撒母耳记上', 9, 14, 31, '这日，以色列人击杀非利士人，从密抹直到亚雅仑。百姓甚是疲乏，'),
('CUV', '撒母耳记上', 9, 14, 32, '就急忙将所夺的牛羊和牛犊宰于地上，肉还带血就吃了。'),
('CUV', '撒母耳记上', 9, 14, 33, '有人告诉扫罗说：百姓吃带血的肉，得罪耶和华了。扫罗说：你们有罪了，今日要将大石头滚到我这里来。'),
('CUV', '撒母耳记上', 9, 14, 34, '扫罗又说：你们散在百姓中，对他们说，你们各人将牛羊牵到我这里来宰了吃，不可吃带血的肉得罪耶和华。这夜，百姓就把牛羊牵到那里宰了。'),
('CUV', '撒母耳记上', 9, 14, 35, '扫罗为耶和华筑了一座坛，这是他初次为耶和华筑的坛。'),
('CUV', '撒母耳记上', 9, 14, 36, '扫罗说：我们不如夜里下去追赶非利士人，抢掠他们，直到天亮，不留他们一人。众民说：你看怎样好就去行罢！祭司说：我们先当亲近神。'),
('CUV', '撒母耳记上', 9, 14, 37, '扫罗求问神说：我下去追赶非利士人可以不可以？你将他们交在以色列人手里不交？这日神没有回答他。'),
('CUV', '撒母耳记上', 9, 14, 38, '扫罗说：你们百姓中的长老都上这里来，查明今日是谁犯了罪。'),
('CUV', '撒母耳记上', 9, 14, 39, '我指著救以色列─永生的耶和华起誓，就是我儿子约拿单犯了罪，他也必死。但百姓中无一人回答他。'),
('CUV', '撒母耳记上', 9, 14, 40, '扫罗就对以色列众人说：你们站在一边，我与我儿子约拿单也站在一边。百姓对扫罗说：你看怎样好就去行罢！'),
('CUV', '撒母耳记上', 9, 14, 41, '扫罗祷告耶和华─以色列的神说：求你指示实情。于是掣签掣出扫罗和约拿单来；百姓尽都无事。'),
('CUV', '撒母耳记上', 9, 14, 42, '扫罗说：你们再掣签，看是我，是我儿子约拿单，就掣出约拿单来。'),
('CUV', '撒母耳记上', 9, 14, 43, '扫罗对约拿单说：你告诉我，你做了甚么事？约拿单说：我实在以手里的杖，用杖头蘸了一点蜜尝了一尝。这样我就死么（或译：罢））？'),
('CUV', '撒母耳记上', 9, 14, 44, '扫罗说：约拿单哪，你定要死！若不然，愿神重重地降罚与我。'),
('CUV', '撒母耳记上', 9, 14, 45, '百姓对扫罗说：约拿单在以色列人中这样大行拯救，岂可使他死呢？断乎不可！我们指著永生的耶和华起誓，连他的一根头发也不可落地，因为他今日与神一同做事。于是百姓救约拿单免了死亡。'),
('CUV', '撒母耳记上', 9, 14, 46, '扫罗回去，不追赶非利士人；非利士人也回本地去了。'),
('CUV', '撒母耳记上', 9, 14, 47, '扫罗执掌以色列的国权，常常攻击他四围的一切仇敌，就是摩押人、亚扪人、以东人，和琐巴诸王，并非利士人。他无论往何处去，都打败仇敌。'),
('CUV', '撒母耳记上', 9, 14, 48, '扫罗奋勇攻击亚玛力人，救了以色列人脱离抢掠他们之人的手。'),
('CUV', '撒母耳记上', 9, 14, 49, '扫罗的儿子是约拿单、亦施韦、麦基舒亚。他的两个女儿：长女名米拉，次女名米甲。'),
('CUV', '撒母耳记上', 9, 14, 50, '扫罗的妻名叫亚希暖，是亚希玛斯的女儿。扫罗的元帅名叫押尼珥，是尼珥的儿子；尼珥是扫罗的叔叔。'),
('CUV', '撒母耳记上', 9, 14, 51, '扫罗的父亲基士，押尼珥的父亲尼珥，都是亚别的儿子。'),
('CUV', '撒母耳记上', 9, 14, 52, '扫罗平生常与非利士人大大争战。扫罗遇见有能力的人或勇士，都招募了来跟随他。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 15, 1, '撒母耳对扫罗说：耶和华差遣我膏你为王，治理他的百姓以色列；所以你当听从耶和华的话。'),
('CUV', '撒母耳记上', 9, 15, 2, '万军之耶和华如此说：以色列人出埃及的时候，在路上亚玛力人怎样待他们，怎样抵挡他们，我都没忘。'),
('CUV', '撒母耳记上', 9, 15, 3, '现在你要去击打亚玛力人，灭尽他们所有的，不可怜惜他们，将男女、孩童、吃奶的，并牛、羊、骆驼，和驴尽行杀死。'),
('CUV', '撒母耳记上', 9, 15, 4, '于是扫罗招聚百姓在提拉因，数点他们，共有步兵二十万，另有犹大人一万。'),
('CUV', '撒母耳记上', 9, 15, 5, '扫罗到了亚玛力的京城，在谷中设下埋伏。'),
('CUV', '撒母耳记上', 9, 15, 6, '扫罗对基尼人说：你们离开亚玛力人下去罢，恐怕我将你们和亚玛力人一同杀灭；因为以色列人出埃及的时候，你们曾恩待他们。于是基尼人离开亚玛力人去了。'),
('CUV', '撒母耳记上', 9, 15, 7, '扫罗击打亚玛力人，从哈腓拉直到埃及前的书珥，'),
('CUV', '撒母耳记上', 9, 15, 8, '生擒了亚玛力王亚甲，用刀杀尽亚玛力的众民。'),
('CUV', '撒母耳记上', 9, 15, 9, '扫罗和百姓却怜惜亚甲，也爱惜上好的牛、羊、牛犊、羊羔，并一切美物，不肯灭绝。凡下贱瘦弱的，尽都杀了。'),
('CUV', '撒母耳记上', 9, 15, 10, '耶和华的话临到撒母耳说：'),
('CUV', '撒母耳记上', 9, 15, 11, '我立扫罗为王，我后悔了；因为他转去不跟从我，不遵守我的命令。撒母耳便甚忧愁，终夜哀求耶和华。'),
('CUV', '撒母耳记上', 9, 15, 12, '撒母耳清早起来，迎接扫罗。有人告诉撒母耳说：扫罗到了迦密，在那里立了记纪念碑，又转身下到吉甲。'),
('CUV', '撒母耳记上', 9, 15, 13, '撒母耳到了扫罗那里，扫罗对他说：愿耶和华赐福与你，耶和华的命令我已遵守了。'),
('CUV', '撒母耳记上', 9, 15, 14, '撒母耳说：我耳中听见有羊叫、牛鸣，是从哪里来的呢？'),
('CUV', '撒母耳记上', 9, 15, 15, '扫罗说：这是百姓从亚玛力人那里带来的；因为他们爱惜上好的牛羊，要献与耶和华─你的神；其余的，我们都灭尽了。'),
('CUV', '撒母耳记上', 9, 15, 16, '撒母耳对扫罗说：你住口罢！等我将耶和华昨夜向我所说的话告诉你。扫罗说：请讲。'),
('CUV', '撒母耳记上', 9, 15, 17, '撒母耳对扫罗说：从前你虽然以自己为小，岂不是被立为以色列支派的元首么？耶和华膏你作以色列的王。'),
('CUV', '撒母耳记上', 9, 15, 18, '耶和华差遣你，吩咐你说，你去击打那些犯罪的亚玛力人，将他们灭绝净尽。'),
('CUV', '撒母耳记上', 9, 15, 19, '你为何没有听从耶和华的命令，急忙掳掠财物，行耶和华眼中看为恶的事呢？'),
('CUV', '撒母耳记上', 9, 15, 20, '扫罗对撒母耳说：我实在听从了耶和华的命令，行了耶和华所差遣我行的路，擒了亚玛力王亚甲来，灭尽了亚玛力人。'),
('CUV', '撒母耳记上', 9, 15, 21, '百姓却在所当灭的物中取了最好的牛羊，要在吉甲献与耶和华─你的神。'),
('CUV', '撒母耳记上', 9, 15, 22, '撒母耳说：耶和华喜悦燔祭和平安祭，岂如喜悦人听从他的话呢？听命胜于献祭；顺从胜于公羊的脂油。'),
('CUV', '撒母耳记上', 9, 15, 23, '悖逆的罪与行邪术的罪相等；顽梗的罪与拜虚神和偶像的罪相同。你既厌弃耶和华的命令，耶和华也厌弃你作王。'),
('CUV', '撒母耳记上', 9, 15, 24, '扫罗对撒母耳说：我有罪了，我因惧怕百姓，听从他们的话，就违背了耶和华的命令和你的言语。'),
('CUV', '撒母耳记上', 9, 15, 25, '现在求你赦免我的罪，同我回去，我好敬拜耶和华。'),
('CUV', '撒母耳记上', 9, 15, 26, '撒母耳对扫罗说：我不同你回去；因为你厌弃耶和华的命令，耶和华也厌弃你作以色列的王。'),
('CUV', '撒母耳记上', 9, 15, 27, '撒母耳转身要走，扫罗就扯住他外袍的衣襟，衣襟就撕断了。'),
('CUV', '撒母耳记上', 9, 15, 28, '撒母耳对他说：如此，今日耶和华使以色列国与你断绝，将这国赐与比你更好的人。'),
('CUV', '撒母耳记上', 9, 15, 29, '以色列的大能者必不致说谎，也不致后悔；因为他迥非世人，决不后悔。'),
('CUV', '撒母耳记上', 9, 15, 30, '扫罗说：我有罪了，虽然如此，求你在我百姓的长老和以色列人面前抬举我，同我回去，我好敬拜耶和华─你的神。'),
('CUV', '撒母耳记上', 9, 15, 31, '于是撒母耳转身跟随扫罗回去，扫罗就敬拜耶和华。'),
('CUV', '撒母耳记上', 9, 15, 32, '撒母耳说：要把亚玛力王亚甲带到我这里来。亚甲就欢欢喜喜地来到他面前，心里说，死亡的苦难必定过去了。'),
('CUV', '撒母耳记上', 9, 15, 33, '撒母耳说：你既用刀使妇人丧子，这样，你母亲在妇人中也必丧子。于是，撒母耳在吉甲耶和华面前将亚甲杀死。'),
('CUV', '撒母耳记上', 9, 15, 34, '撒母耳回了拉玛。扫罗上他所住的基比亚，回自己的家去了。'),
('CUV', '撒母耳记上', 9, 15, 35, '撒母耳直到死的日子，再没有见扫罗；但撒母耳为扫罗悲伤，是因耶和华后悔立他为以色列的王。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 16, 1, '耶和华对撒母耳说：我既厌弃扫罗作以色列的王，你为他悲伤要到几时呢？你将膏油盛满了角，我差遣你往伯利恒人耶西那里去；因为我在他众子之内，预定一个作王的。'),
('CUV', '撒母耳记上', 9, 16, 2, '撒母耳说：我怎能去呢？扫罗若听见，必要杀我。耶和华说：你可以带一只牛犊去，就说：我来是要向耶和华献祭。'),
('CUV', '撒母耳记上', 9, 16, 3, '你要请耶西来吃祭肉，我就指示你所当行的事。我所指给你的人，你要膏他。'),
('CUV', '撒母耳记上', 9, 16, 4, '撒母耳就照耶和华的话去行。到了伯利恒，那城里的长老都战战兢兢地出来迎接他，问他说：你是为平安来的么？'),
('CUV', '撒母耳记上', 9, 16, 5, '他说：为平安来的，我是给耶和华献祭。你们当自洁，来与我同吃祭肉。撒母耳就使耶西和他众子自洁，请他们来吃祭肉。'),
('CUV', '撒母耳记上', 9, 16, 6, '他们来的时候，撒母耳看见以利押，就心里说，耶和华的受膏者必定在他面前。'),
('CUV', '撒母耳记上', 9, 16, 7, '耶和华却对撒母耳说：不要看他的外貌和他身材高大，我不拣选他。因为，耶和华不像人看人：人是看外貌；耶和华是看内心。'),
('CUV', '撒母耳记上', 9, 16, 8, '耶西叫亚比拿达从撒母耳面前经过，撒母耳说：耶和华也不拣选他。'),
('CUV', '撒母耳记上', 9, 16, 9, '耶西又叫沙玛从撒母耳面前经过，撒母耳说：耶和华也不拣选他。'),
('CUV', '撒母耳记上', 9, 16, 10, '耶西叫他七个儿子都从撒母耳面前经过，撒母耳说：这都不是耶和华所拣选的。'),
('CUV', '撒母耳记上', 9, 16, 11, '撒母耳对耶西说：你的儿子都在这里么？他回答说：还有个小的，现在放羊。撒母耳对耶西说：你打发人去叫他来；他若不来，我们必不坐席。'),
('CUV', '撒母耳记上', 9, 16, 12, '耶西就打发人去叫了他来。他面色光红，双目清秀，容貌俊美。耶和华说：这就是他，你起来膏他。'),
('CUV', '撒母耳记上', 9, 16, 13, '撒母耳就用角里的膏油，在他诸兄中膏了他。从这日起，耶和华的灵就大大感动大卫。撒母耳起身回拉玛去了。'),
('CUV', '撒母耳记上', 9, 16, 14, '耶和华的灵离开扫罗，有恶魔从耶和华那里来扰乱他。'),
('CUV', '撒母耳记上', 9, 16, 15, '扫罗的臣仆对他说：现在有恶魔从神那里来扰乱你。'),
('CUV', '撒母耳记上', 9, 16, 16, '我们的主可以吩咐面前的臣仆，找一个善于弹琴的来，等神那里来的恶魔临到你身上的时候，使他用手弹琴，你就好了。'),
('CUV', '撒母耳记上', 9, 16, 17, '扫罗对臣仆说：你们可以为我找一个善于弹琴的，带到我这里来。'),
('CUV', '撒母耳记上', 9, 16, 18, '其中有一个少年人说：我曾见伯利恒人耶西的一个儿子善于弹琴，是大有勇敢的战士，说话合宜，容貌俊美，耶和华也与他同在。'),
('CUV', '撒母耳记上', 9, 16, 19, '于是扫罗差遣使者去见耶西，说：请你打发你放羊的儿子大卫到我这里来。'),
('CUV', '撒母耳记上', 9, 16, 20, '耶西就把几个饼和一皮袋酒，并一只山羊羔，都驮在驴上，交给他儿子大卫，送与扫罗。'),
('CUV', '撒母耳记上', 9, 16, 21, '大卫到了扫罗那里，就侍立在扫罗面前。扫罗甚喜爱他，他就作了扫罗拿兵器的人。'),
('CUV', '撒母耳记上', 9, 16, 22, '扫罗差遣人去见耶西，说：求你容大卫侍立在我面前，因为他在我眼前蒙了恩。'),
('CUV', '撒母耳记上', 9, 16, 23, '从神那里来的恶魔临到扫罗身上的时候，大卫就拿琴，用手而弹，扫罗便舒畅爽快，恶魔离了他。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 17, 1, '非利士人招聚他们的军旅，要来争战；聚集在属犹大的梭哥，安营在梭哥和亚西加中间的以弗大悯。'),
('CUV', '撒母耳记上', 9, 17, 2, '扫罗和以色列人也聚集，在以拉谷安营，摆列队伍，要与非利士人打仗。'),
('CUV', '撒母耳记上', 9, 17, 3, '非利士人站在这边山上，以色列人站在那边山上，当中有谷。'),
('CUV', '撒母耳记上', 9, 17, 4, '从非利士营中出来一个讨战的人，名叫歌利亚，是迦特人，身高六肘零一虎口；'),
('CUV', '撒母耳记上', 9, 17, 5, '头戴铜盔，身穿铠甲，甲重五千舍客勒；'),
('CUV', '撒母耳记上', 9, 17, 6, '腿上有铜护膝，两肩之中背负铜戟；'),
('CUV', '撒母耳记上', 9, 17, 7, '枪杆粗如织布的机轴，铁枪头重六百舍客勒。有一个拿盾牌的人在他前面走。'),
('CUV', '撒母耳记上', 9, 17, 8, '歌利亚对著以色列的军队站立，呼叫说：你们出来摆列队伍做甚么呢？我不是非利士人么？你们不是扫罗的仆人么？可以从你们中间拣选一人，使他下到我这里来。'),
('CUV', '撒母耳记上', 9, 17, 9, '他若能与我战斗，将我杀死，我们就作你们的仆人；我若胜了他，将他杀死，你们就作我们的仆人，服事我们。'),
('CUV', '撒母耳记上', 9, 17, 10, '那非利士人又说：我今日向以色列人的军队骂阵。你们叫一个人出来，与我战斗。'),
('CUV', '撒母耳记上', 9, 17, 11, '扫罗和以色列众人听见非利士人的这些话，就惊惶，极其害怕。'),
('CUV', '撒母耳记上', 9, 17, 12, '大卫是犹大、伯利恒的以法他人耶西的儿子。耶西有八个儿子。当扫罗的时候，耶西已经老迈。'),
('CUV', '撒母耳记上', 9, 17, 13, '耶西的三个大儿子跟随扫罗出征。这出征的三个儿子：长子名叫以利押，次子名叫亚比拿达，三子名叫沙玛。'),
('CUV', '撒母耳记上', 9, 17, 14, '大卫是最小的；那三个大儿子跟随扫罗。'),
('CUV', '撒母耳记上', 9, 17, 15, '大卫有时离开扫罗，回伯利恒放他父亲的羊。'),
('CUV', '撒母耳记上', 9, 17, 16, '那非利士人早晚都出来站著，如此四十日。'),
('CUV', '撒母耳记上', 9, 17, 17, '一日，耶西对他儿子大卫说：你拿一伊法烘了的穗子和十个饼，速速地送到营里去，交给你哥哥们；'),
('CUV', '撒母耳记上', 9, 17, 18, '再拿这十块奶饼，送给他们的千夫长，且问你哥哥们好，向他们要一封信来。'),
('CUV', '撒母耳记上', 9, 17, 19, '扫罗与大卫的三个哥哥和以色列众人，在以拉谷与非利士人打仗。'),
('CUV', '撒母耳记上', 9, 17, 20, '大卫早晨起来，将羊交托一个看守的人，照著他父亲所吩咐的话，带著食物去了。到了辎重营，军兵刚出到战场，呐喊要战。'),
('CUV', '撒母耳记上', 9, 17, 21, '以色列人和非利士人都摆列队伍，彼此相对。'),
('CUV', '撒母耳记上', 9, 17, 22, '大卫把他带来的食物留在看守物件人的手下，跑到战场，问他哥哥们安。'),
('CUV', '撒母耳记上', 9, 17, 23, '与他们说话的时候，那讨战的，就是属迦特的非利士人歌利亚，从非利士队中出来，说从前所说的话；大卫都听见了。'),
('CUV', '撒母耳记上', 9, 17, 24, '以色列众人看见那人，就逃跑，极其害怕。'),
('CUV', '撒母耳记上', 9, 17, 25, '以色列人彼此说：这上来的人你看见了么？他上来是要向以色列人骂阵。若有能杀他的，王必赏赐他大财，将自己的女儿给他为妻，并在以色列人中免他父家纳粮当差。'),
('CUV', '撒母耳记上', 9, 17, 26, '大卫问站在旁边的人说：有人杀这非利士人，除掉以色列人的耻辱，怎样待他呢？这未受割礼的非利士人是谁呢？竟敢向永生神的军队骂阵么？'),
('CUV', '撒母耳记上', 9, 17, 27, '百姓照先前的话回答他说：有人能杀这非利士人，必如此如此待他。'),
('CUV', '撒母耳记上', 9, 17, 28, '大卫的长兄以利押听见大卫与他们所说的话，就向他发怒，说：你下来做甚么呢？在旷野的那几只羊，你交托了谁呢？我知道你的骄傲和你心里的恶意，你下来特为要看争战！'),
('CUV', '撒母耳记上', 9, 17, 29, '大卫说：我做了甚么呢？我来岂没有缘故么？'),
('CUV', '撒母耳记上', 9, 17, 30, '大卫就离开他转向别人，照先前的话而问；百姓仍照先前的话回答他。'),
('CUV', '撒母耳记上', 9, 17, 31, '有人听见大卫所说的话，就告诉了扫罗；扫罗便打发人叫他来。'),
('CUV', '撒母耳记上', 9, 17, 32, '大卫对扫罗说：人都不必因那非利士人胆怯。你的仆人要去与那非利士人战斗。'),
('CUV', '撒母耳记上', 9, 17, 33, '扫罗对大卫说：你不能去与那非利士人战斗；因为你年纪太轻，他自幼就作战士。'),
('CUV', '撒母耳记上', 9, 17, 34, '大卫对扫罗说：你仆人为父亲放羊，有时来了狮子，有时来了熊，从群中啣一只羊羔去。'),
('CUV', '撒母耳记上', 9, 17, 35, '我就追赶他，击打他，将羊羔从他口中救出来。他起来要害我，我就揪著他的胡子，将他打死。'),
('CUV', '撒母耳记上', 9, 17, 36, '你仆人曾打死狮子和熊，这未受割礼的非利士人向永生神的军队骂阵，也必像狮子和熊一般。'),
('CUV', '撒母耳记上', 9, 17, 37, '大卫又说：耶和华救我脱离狮子和熊的爪，也必救我脱离这非利士人的手。扫罗对大卫说：你可以去罢！耶和华必与你同在。'),
('CUV', '撒母耳记上', 9, 17, 38, '扫罗就把自己的战衣给大卫穿上，将铜盔给他戴上，又给他穿上铠甲。'),
('CUV', '撒母耳记上', 9, 17, 39, '大卫把刀跨在战衣外，试试能走不能走；因为素来没有穿惯，就对扫罗说：我穿戴这些不能走，因为素来没有穿惯。于是摘脱了。'),
('CUV', '撒母耳记上', 9, 17, 40, '他手中拿杖，又在溪中挑选了五块光滑石子，放在袋里，就是牧人带的囊里；手中拿著甩石的机弦，就去迎那非利士人。'),
('CUV', '撒母耳记上', 9, 17, 41, '非利士人也渐渐地迎著大卫来，拿盾牌的走在前头。'),
('CUV', '撒母耳记上', 9, 17, 42, '非利士人观看，见了大卫，就藐视他；因为他年轻，面色光红，容貌俊美。'),
('CUV', '撒母耳记上', 9, 17, 43, '非利士人对大卫说：你拿杖到我这里来，我岂是狗呢？非利士人就指著自己的神咒诅大卫。'),
('CUV', '撒母耳记上', 9, 17, 44, '非利士人又对大卫说：来罢！我将你的肉给空中的飞鸟、田野的走兽吃。'),
('CUV', '撒母耳记上', 9, 17, 45, '大卫对非利士人说：你来攻击我，是靠著刀枪和铜戟；我来攻击你，是靠著万军之耶和华的名，就是你所怒骂带领以色列军队的神。'),
('CUV', '撒母耳记上', 9, 17, 46, '今日耶和华必将你交在我手里。我必杀你，斩你的头，又将非利士军兵的尸首给空中的飞鸟、地上的野兽吃，使普天下的人都知道以色列中有神；'),
('CUV', '撒母耳记上', 9, 17, 47, '又使这众人知道耶和华使人得胜，不是用刀用枪，因为争战的胜败全在乎耶和华。他必将你们交在我们手里。'),
('CUV', '撒母耳记上', 9, 17, 48, '非利士人起身，迎著大卫前来。大卫急忙迎著非利士人，往战场跑去。'),
('CUV', '撒母耳记上', 9, 17, 49, '大卫用手从囊中掏出一块石子来，用机弦甩去，打中非利士人的额，石子进入额内，他就仆倒，面伏于地。'),
('CUV', '撒母耳记上', 9, 17, 50, '这样，大卫用机弦甩石，胜了那非利士人，打死他；大卫手中却没有刀。'),
('CUV', '撒母耳记上', 9, 17, 51, '大卫跑去，站在非利士人身旁，将他的刀从鞘中拔出来，杀死他，割了他的头。非利士众人看见他们讨战的勇士死了，就都逃跑。'),
('CUV', '撒母耳记上', 9, 17, 52, '以色列人和犹大人便起身呐喊，追赶非利士人，直到迦特（或译：该）和以革伦的城门。被杀的非利士人倒在沙拉音的路上，直到迦特和以革伦。'),
('CUV', '撒母耳记上', 9, 17, 53, '以色列人追赶非利士人回来，就夺了他们的营盘。'),
('CUV', '撒母耳记上', 9, 17, 54, '大卫将那非利士人的头拿到耶路撒冷，却将他军装放在自己的帐棚里。'),
('CUV', '撒母耳记上', 9, 17, 55, '扫罗看见大卫去攻击非利士人，就问元帅押尼珥说：押尼珥啊，那少年人是谁的儿子？押尼珥说：我敢在王面前起誓，我不知道。'),
('CUV', '撒母耳记上', 9, 17, 56, '王说：你可以问问那幼年人是谁的儿子。'),
('CUV', '撒母耳记上', 9, 17, 57, '大卫打死非利士人回来，押尼珥领他到扫罗面前，他手中拿著非利士人的头。'),
('CUV', '撒母耳记上', 9, 17, 58, '扫罗问他说：少年人哪，你是谁的儿子？大卫说：我是你仆人伯利恒人耶西的儿子。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 18, 1, '大卫对扫罗说完了话，约拿单的心与大卫的心深相契合。约拿单爱大卫，如同爱自己的性命。'),
('CUV', '撒母耳记上', 9, 18, 2, '那日扫罗留住大卫，不容他再回父家。'),
('CUV', '撒母耳记上', 9, 18, 3, '约拿单爱大卫如同爱自己的性命，就与他结盟。'),
('CUV', '撒母耳记上', 9, 18, 4, '约拿单从身上脱下外袍，给了大卫，又将战衣、刀、弓、腰带都给了他。'),
('CUV', '撒母耳记上', 9, 18, 5, '扫罗无论差遣大卫往何处去，他都做事精明。扫罗就立他作战士长，众百姓和扫罗的臣仆无不喜悦。'),
('CUV', '撒母耳记上', 9, 18, 6, '大卫打死了那非利士人，同众人回来的时候，妇女们从以色列各城里出来，欢欢喜喜，打鼓击磬，歌唱跳舞，迎接扫罗王。'),
('CUV', '撒母耳记上', 9, 18, 7, '众妇女舞蹈唱和，说：扫罗杀死千千，大卫杀死万万。'),
('CUV', '撒母耳记上', 9, 18, 8, '扫罗甚发怒，不喜悦这话，就说：将万万归大卫，千千归我，只剩下王位没有给他了。'),
('CUV', '撒母耳记上', 9, 18, 9, '从这日起，扫罗就怒视大卫。'),
('CUV', '撒母耳记上', 9, 18, 10, '次日，从神那里来的恶魔大大降在扫罗身上，他就在家中胡言乱语。大卫照常弹琴，扫罗手里拿著枪。'),
('CUV', '撒母耳记上', 9, 18, 11, '扫罗把枪一抡，心里说，我要将大卫刺透，钉在墙上。大卫躲避他两次。'),
('CUV', '撒母耳记上', 9, 18, 12, '扫罗惧怕大卫；因为耶和华离开自己，与大卫同在。'),
('CUV', '撒母耳记上', 9, 18, 13, '所以扫罗使大卫离开自己，立他为千夫长，他就领兵出入。'),
('CUV', '撒母耳记上', 9, 18, 14, '大卫做事无不精明，耶和华也与他同在。'),
('CUV', '撒母耳记上', 9, 18, 15, '扫罗见大卫做事精明，就甚怕他。'),
('CUV', '撒母耳记上', 9, 18, 16, '但以色列和犹大众人都爱大卫，因为他领他们出入。'),
('CUV', '撒母耳记上', 9, 18, 17, '扫罗对大卫说：我将大女儿米拉给你为妻，只要你为我奋勇，为耶和华争战。扫罗心里说：我不好亲手害他，要藉非利士人的手害他。'),
('CUV', '撒母耳记上', 9, 18, 18, '大卫对扫罗说：我是谁，我是甚么出身，我父家在以色列中是何等的家，岂敢作王的女婿呢？'),
('CUV', '撒母耳记上', 9, 18, 19, '扫罗的女儿米拉到了当给大卫的时候，扫罗却给了米何拉人亚得列为妻。'),
('CUV', '撒母耳记上', 9, 18, 20, '扫罗的次女米甲爱大卫。有人告诉扫罗，扫罗就喜悦。'),
('CUV', '撒母耳记上', 9, 18, 21, '扫罗心里说：我将这女儿给大卫，作他的网罗，好藉非利士人的手害他。所以扫罗对大卫说：你今日可以第二次作我的女婿。'),
('CUV', '撒母耳记上', 9, 18, 22, '扫罗吩咐臣仆说：你们暗中对大卫说：王喜悦你，王的臣仆也都喜爱你，所以你当作王的女婿。'),
('CUV', '撒母耳记上', 9, 18, 23, '扫罗的臣仆就照这话说给大卫听。大卫说：你们以为作王的女婿是一件小事么？我是贫穷卑微的人。'),
('CUV', '撒母耳记上', 9, 18, 24, '扫罗的臣仆回奏说，大卫所说的如此如此。'),
('CUV', '撒母耳记上', 9, 18, 25, '扫罗说：你们要对大卫这样说：王不要甚么聘礼，只要一百非利士人的阳皮，好在王的仇敌身上报仇。扫罗的意思要使大卫丧在非利士人的手里。'),
('CUV', '撒母耳记上', 9, 18, 26, '扫罗的臣仆将这话告诉大卫，大卫就欢喜作王的女婿。日期还没有到，'),
('CUV', '撒母耳记上', 9, 18, 27, '大卫和跟随他的人起身前往，杀了二百非利士人，将阳皮满数交给王，为要作王的女婿。于是扫罗将女儿米甲给大卫为妻。'),
('CUV', '撒母耳记上', 9, 18, 28, '扫罗见耶和华与大卫同在，又知道女儿米甲爱大卫，'),
('CUV', '撒母耳记上', 9, 18, 29, '就更怕大卫，常作大卫的仇敌。'),
('CUV', '撒母耳记上', 9, 18, 30, '每逢非利士军长出来打仗，大卫比扫罗的臣仆做事精明，因此他的名被人尊重。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 19, 1, '扫罗对他儿子约拿单和众臣仆说，要杀大卫；扫罗的儿子约拿单却甚喜爱大卫。'),
('CUV', '撒母耳记上', 9, 19, 2, '约拿单告诉大卫说：我父扫罗想要杀你，所以明日早晨你要小心，到一个僻静地方藏身。'),
('CUV', '撒母耳记上', 9, 19, 3, '我就出到你所藏的田里，站在我父亲旁边与他谈论。我看他情形怎样，我必告诉你。'),
('CUV', '撒母耳记上', 9, 19, 4, '约拿单向他父亲扫罗替大卫说好话，说：王不可得罪王的仆人大卫；因为他未曾得罪你，他所行的都与你大有益处。'),
('CUV', '撒母耳记上', 9, 19, 5, '他拚命杀那非利士人，耶和华为以色列众人大行拯救；那时你看见，甚是欢喜，现在为何无故要杀大卫，流无辜人的血，自己取罪呢？'),
('CUV', '撒母耳记上', 9, 19, 6, '扫罗听了约拿单的话，就指著永生的耶和华起誓说：我必不杀他。'),
('CUV', '撒母耳记上', 9, 19, 7, '约拿单叫大卫来，把这一切事告诉他，带他去见扫罗。他就仍然侍立在扫罗面前。'),
('CUV', '撒母耳记上', 9, 19, 8, '此后又有争战的事。大卫出去与非利士人打仗，大大杀败他们，他们就在他面前逃跑。'),
('CUV', '撒母耳记上', 9, 19, 9, '从耶和华那里来的恶魔又降在扫罗身上（扫罗手里拿枪坐在屋里），大卫就用手弹琴。'),
('CUV', '撒母耳记上', 9, 19, 10, '扫罗用枪想要刺透大卫，钉在墙上；他却躲开，扫罗的枪刺入墙内。当夜大卫逃走，躲避了。'),
('CUV', '撒母耳记上', 9, 19, 11, '扫罗打发人到大卫的房屋那里窥探他，要等到天亮杀他。大卫的妻米甲对他说：你今夜若不逃命，明日你要被杀。'),
('CUV', '撒母耳记上', 9, 19, 12, '于是米甲将大卫从窗户里缒下去；大卫就逃走，躲避了。'),
('CUV', '撒母耳记上', 9, 19, 13, '米甲把家中的神像放在床上，头枕在山羊毛装的枕头上，用被遮盖。'),
('CUV', '撒母耳记上', 9, 19, 14, '扫罗打发人去捉拿大卫，米甲说：他病了。'),
('CUV', '撒母耳记上', 9, 19, 15, '扫罗又打发人去看大卫，说：当连床将他抬来，我好杀他。'),
('CUV', '撒母耳记上', 9, 19, 16, '使者进去，看见床上有神像，头枕在山羊毛装的枕头上。'),
('CUV', '撒母耳记上', 9, 19, 17, '扫罗对米甲说：你为甚么这样欺哄我，放我仇敌逃走呢？米甲回答说：他对我说：你放我走，不然我要杀你。'),
('CUV', '撒母耳记上', 9, 19, 18, '大卫逃避，来到拉玛见撒母耳，将扫罗向他所行的事述说了一遍。他和撒母耳就往拿约去居住。'),
('CUV', '撒母耳记上', 9, 19, 19, '有人告诉扫罗，说大卫在拉玛的拿约。'),
('CUV', '撒母耳记上', 9, 19, 20, '扫罗打发人去捉拿大卫。去的人见有一班先知都受感说话，撒母耳站在其中监管他们；打发去的人也受神的灵感动说话。'),
('CUV', '撒母耳记上', 9, 19, 21, '有人将这事告诉扫罗，他又打发人去，他们也受感说话。扫罗第三次打发人去，他们也受感说话。'),
('CUV', '撒母耳记上', 9, 19, 22, '然后扫罗自己往拉玛去，到了西沽的大井，问人说：撒母耳和大卫在哪里呢？有人说：在拉玛的拿约。'),
('CUV', '撒母耳记上', 9, 19, 23, '他就往拉玛的拿约去。神的灵也感动他，一面走一面说话，直到拉玛的拿约。'),
('CUV', '撒母耳记上', 9, 19, 24, '他就脱了衣服，在撒母耳面前受感说话，一昼一夜露体躺卧。因此有句俗语说：扫罗也列在先知中么？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 20, 1, '大卫从拉玛的拿约逃跑，来到约拿单那里，对他说：我做了甚么？有甚么罪孽呢？在你父亲面前犯了甚么罪，他竟寻索我的性命呢？'),
('CUV', '撒母耳记上', 9, 20, 2, '约拿单回答说：断然不是！你必不致死。我父作事，无论大小，没有不叫我知道的。怎么独有这事隐瞒我呢？决不如此。'),
('CUV', '撒母耳记上', 9, 20, 3, '大卫又起誓说：你父亲准知我在你眼前蒙恩。他心里说，不如不叫约拿单知道，恐怕他愁烦。我指著永生的耶和华，又敢在你面前起誓，我离死不过一步。'),
('CUV', '撒母耳记上', 9, 20, 4, '约拿单对大卫说：你心里所求的，我必为你成就。'),
('CUV', '撒母耳记上', 9, 20, 5, '大卫对约拿单说：明日是初一，我当与王同席，求你容我去藏在田野，直到第三日晚上。'),
('CUV', '撒母耳记上', 9, 20, 6, '你父亲若见我不在席上，你就说：大卫切求我许他回本城伯利恒去，因为他全家在那里献年祭。'),
('CUV', '撒母耳记上', 9, 20, 7, '你父亲若说好，仆人就平安了；他若发怒，你就知道他决意要害我。'),
('CUV', '撒母耳记上', 9, 20, 8, '求你施恩与仆人，因你在耶和华面前曾与仆人结盟。我若有罪，不如你自己杀我，何必将我交给你父亲呢？'),
('CUV', '撒母耳记上', 9, 20, 9, '约拿单说：断无此事！我若知道我父亲决意害你，我岂不告诉你呢？'),
('CUV', '撒母耳记上', 9, 20, 10, '大卫对约拿单说：你父亲若用厉言回答你，谁来告诉我呢？'),
('CUV', '撒母耳记上', 9, 20, 11, '约拿单对大卫说：你我且往田野去。二人就往田野去了。'),
('CUV', '撒母耳记上', 9, 20, 12, '约拿单对大卫说：愿耶和华─以色列的神为证。明日约在这时候，或第三日，我探我父亲的意思，若向你有好意，我岂不打发人告诉你么？'),
('CUV', '撒母耳记上', 9, 20, 13, '我父亲若有意害你，我不告诉你使你平平安安地走，愿耶和华重重地降罚与我。愿耶和华与你同在，如同从前与我父亲同在一样。'),
('CUV', '撒母耳记上', 9, 20, 14, '你要照耶和华的慈爱恩待我，不但我活著的时候免我死亡，'),
('CUV', '撒母耳记上', 9, 20, 15, '就是我死后，耶和华从地上剪除你仇敌的时候，你也永不可向我家绝了恩惠。'),
('CUV', '撒母耳记上', 9, 20, 16, '于是约拿单与大卫家结盟，说：愿耶和华藉大卫的仇敌追讨背约的罪。'),
('CUV', '撒母耳记上', 9, 20, 17, '约拿单因爱大卫如同爱自己的性命，就使他再起誓。'),
('CUV', '撒母耳记上', 9, 20, 18, '约拿单对他说：明日是初一，你的座位空设，人必理会你不在那里。'),
('CUV', '撒母耳记上', 9, 20, 19, '你等三日，就要速速下去，到你从前遇事所藏的地方，在以色磐石那里等候。'),
('CUV', '撒母耳记上', 9, 20, 20, '我要向磐石旁边射三箭，如同射箭靶一样。'),
('CUV', '撒母耳记上', 9, 20, 21, '我要打发童子，说：去把箭找来。我若对童子说：箭在后头，把箭拿来，你就可以回来；我指著永生的耶和华起誓，你必平安无事。'),
('CUV', '撒母耳记上', 9, 20, 22, '我若对童子说：箭在前头，你就要去，因为是耶和华打发你去的。'),
('CUV', '撒母耳记上', 9, 20, 23, '至于你我今日所说的话，有耶和华在你我中间为证，直到永远。'),
('CUV', '撒母耳记上', 9, 20, 24, '大卫就去藏在田野。到了初一日，王坐席要吃饭。'),
('CUV', '撒母耳记上', 9, 20, 25, '王照常坐在靠墙的位上，约拿单侍立，押尼珥坐在扫罗旁边，大卫的座位空设。'),
('CUV', '撒母耳记上', 9, 20, 26, '然而这日扫罗没有说甚么，他想大卫遇事，偶染不洁，他必定是不洁。'),
('CUV', '撒母耳记上', 9, 20, 27, '初二日大卫的座位还空设。扫罗问他儿子约拿单说：耶西的儿子为何昨日、今日没有来吃饭呢？'),
('CUV', '撒母耳记上', 9, 20, 28, '约拿单回答扫罗说：大卫切求我容他往伯利恒去。'),
('CUV', '撒母耳记上', 9, 20, 29, '他说：求你容我去，因为我家在城里有献祭的事；我长兄吩咐我去。如今我若在你眼前蒙恩，求你容我去见我的弟兄；所以大卫没有赴王的席。'),
('CUV', '撒母耳记上', 9, 20, 30, '扫罗向约拿单发怒，对他说：你这顽梗背逆之妇人所生的，我岂不知道你喜悦耶西的儿子，自取羞辱，以致你母亲露体蒙羞么？'),
('CUV', '撒母耳记上', 9, 20, 31, '耶西的儿子若在世间活著，你和你的国位必站立不住。现在你要打发人去，将他捉拿交给我；他是该死的。'),
('CUV', '撒母耳记上', 9, 20, 32, '约拿单对父亲扫罗说：他为甚么该死呢？他做了甚么呢？'),
('CUV', '撒母耳记上', 9, 20, 33, '扫罗向约拿单抡枪要刺他，约拿单就知道他父亲决意要杀大卫。'),
('CUV', '撒母耳记上', 9, 20, 34, '于是约拿单气忿忿地从席上起来，在这初二日没有吃饭。他因见父亲羞辱大卫，就为大卫愁烦。'),
('CUV', '撒母耳记上', 9, 20, 35, '次日早晨，约拿单按著与大卫约会的时候出到田野，有一个童子跟随。'),
('CUV', '撒母耳记上', 9, 20, 36, '约拿单对童子说：你跑去，把我所射的箭找来。童子跑去，约拿单就把箭射在童子前头。'),
('CUV', '撒母耳记上', 9, 20, 37, '童子到了约拿单落箭之地，约拿单呼叫童子说：箭不是在你前头么？'),
('CUV', '撒母耳记上', 9, 20, 38, '约拿单又呼叫童子说：速速地去，不要迟延！童子就拾起箭来，回到主人那里。'),
('CUV', '撒母耳记上', 9, 20, 39, '童子却不知道这是甚么意思，只有约拿单和大卫知道。'),
('CUV', '撒母耳记上', 9, 20, 40, '约拿单将弓箭交给童子，吩咐说：你拿到城里去。'),
('CUV', '撒母耳记上', 9, 20, 41, '童子一去，大卫就从磐石的南边出来，俯伏在地，拜了三拜；二人亲嘴，彼此哭泣，大卫哭得更恸。'),
('CUV', '撒母耳记上', 9, 20, 42, '约拿单对大卫说：我们二人曾指著耶和华的名起誓说：愿耶和华在你我中间，并你我后裔中间为证，直到永远。如今你平平安安地去罢！大卫就起身走了；约拿单也回城里去了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 21, 1, '大卫到了挪伯祭司亚希米勒那里，亚希米勒战战兢兢地出来迎接他，问他说：你为甚么独自来，没有人跟随呢？'),
('CUV', '撒母耳记上', 9, 21, 2, '大卫回答祭司亚希米勒说：王吩咐我一件事说：我差遣你委托你的这件事，不要使人知道。故此我已派定少年人在某处等候我。'),
('CUV', '撒母耳记上', 9, 21, 3, '现在你手下有甚么？求你给我五个饼或是别样的食物。'),
('CUV', '撒母耳记上', 9, 21, 4, '祭司对大卫说：我手下没有寻常的饼，只有圣饼；若少年人没有亲近妇人才可以给。'),
('CUV', '撒母耳记上', 9, 21, 5, '大卫对祭司说：实在约有三日我们没有亲近妇人；我出来的时候，虽是寻常行路，少年人的器皿还是洁净的；何况今日不更是洁净么？'),
('CUV', '撒母耳记上', 9, 21, 6, '祭司就拿圣饼给他；因为在那里没有别样饼，只有更换新饼，从耶和华面前撤下来的陈设饼。'),
('CUV', '撒母耳记上', 9, 21, 7, '（当日有扫罗的一个臣子留在耶和华面前。他名叫多益，是以东人，作扫罗的司牧长。）'),
('CUV', '撒母耳记上', 9, 21, 8, '大卫问亚希米勒说：你手下有枪有刀没有？因为王的事甚急，连刀剑器械我都没有带。'),
('CUV', '撒母耳记上', 9, 21, 9, '祭司说：你在以拉谷杀非利士人歌利亚的那刀在这里，裹在布中，放在以弗得后边，你要就可以拿去；除此以外，再没有别的。大卫说：这刀没有可比的！求你给我。'),
('CUV', '撒母耳记上', 9, 21, 10, '那日大卫起来，躲避扫罗，逃到迦特王亚吉那里。'),
('CUV', '撒母耳记上', 9, 21, 11, '亚吉的臣仆对亚吉说：这不是以色列国王大卫么？那里的妇女跳舞唱和，不是指著他说扫罗杀死千千，大卫杀死万万么？'),
('CUV', '撒母耳记上', 9, 21, 12, '大卫将这话放在心里，甚惧怕迦特王亚吉，'),
('CUV', '撒母耳记上', 9, 21, 13, '就在众人面前改变了寻常的举动，在他们手下假装疯癫，在城门的门扇上胡写乱画，使唾沫流在胡子上。'),
('CUV', '撒母耳记上', 9, 21, 14, '亚吉对臣仆说：你们看，这人是疯子。为甚么带他到我这里来呢？'),
('CUV', '撒母耳记上', 9, 21, 15, '我岂缺少疯子，你们带这人来在我面前疯癫么？这人岂可进我的家呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 22, 1, '大卫就离开那里，逃到亚杜兰洞。他的弟兄和他父亲的全家听见了，就都下到他那里。'),
('CUV', '撒母耳记上', 9, 22, 2, '凡受窘迫的、欠债的、心里苦恼的都聚集到大卫那里；大卫就作他们的头目，跟随他的约有四百人。'),
('CUV', '撒母耳记上', 9, 22, 3, '大卫从那里往摩押的米斯巴去，对摩押王说：求你容我父母搬来，住在你们这里，等我知道神要为我怎样行。'),
('CUV', '撒母耳记上', 9, 22, 4, '大卫领他父母到摩押王面前。大卫住山寨多少日子，他父母也住摩押王那里多少日子。'),
('CUV', '撒母耳记上', 9, 22, 5, '先知迦得对大卫说：你不要住在山寨，要往犹大地去。大卫就离开那里，进入哈列的树林。'),
('CUV', '撒母耳记上', 9, 22, 6, '扫罗在基比亚的拉玛，坐在垂丝柳树下，手里拿著枪，众臣仆侍立在左右。扫罗听见大卫和跟随他的人在何处，'),
('CUV', '撒母耳记上', 9, 22, 7, '就对左右侍立的臣仆说：便雅悯人哪，你们要听我的话！耶西的儿子能将田地和葡萄园赐给你们各人么？能立你们各人作千夫长百夫长么？'),
('CUV', '撒母耳记上', 9, 22, 8, '你们竟都结党害我！我的儿子与耶西的儿子结盟的时候，无人告诉我；我的儿子挑唆我的臣子谋害我，就如今日的光景，也无人告诉我，为我忧虑。'),
('CUV', '撒母耳记上', 9, 22, 9, '那时以东人多益站在扫罗的臣仆中，对他说：我曾看见耶西的儿子到了挪伯，亚希突的儿子亚希米勒那里。'),
('CUV', '撒母耳记上', 9, 22, 10, '亚希米勒为他求问耶和华，又给他食物，并给他杀非利士人歌利亚的刀。'),
('CUV', '撒母耳记上', 9, 22, 11, '王就打发人将祭司亚希突的儿子亚希米勒和他父亲的全家，就是住挪伯的祭司都召了来；他们就来见王。'),
('CUV', '撒母耳记上', 9, 22, 12, '扫罗说：亚希突的儿子，要听我的话！他回答说：主啊，我在这里。'),
('CUV', '撒母耳记上', 9, 22, 13, '扫罗对他说：你为甚么与耶西的儿子结党害我，将食物和刀给他，又为他求问神，使他起来谋害我，就如今日的光景？'),
('CUV', '撒母耳记上', 9, 22, 14, '亚希米勒回答王说：王的臣仆中有谁比大卫忠心呢？他是王的女婿，又是王的参谋，并且在王家中是尊贵的。'),
('CUV', '撒母耳记上', 9, 22, 15, '我岂是从今日才为他求问神呢？断不是这样！王不要将罪归我和我父的全家；因为这事，无论大小，仆人都不知道。'),
('CUV', '撒母耳记上', 9, 22, 16, '王说：亚希米勒啊，你和你父的全家都是该死的！'),
('CUV', '撒母耳记上', 9, 22, 17, '王就吩咐左右的侍卫说：你们去杀耶和华的祭司；因为他们帮助大卫，又知道大卫逃跑，竟没有告诉我。扫罗的臣子却不肯伸手杀耶和华的祭司。'),
('CUV', '撒母耳记上', 9, 22, 18, '王吩咐多益说：你去杀祭司罢！以东人多益就去杀祭司，那日杀了穿细麻布以弗得的八十五人；'),
('CUV', '撒母耳记上', 9, 22, 19, '又用刀将祭司城挪伯中的男女、孩童、吃奶的，和牛、羊、驴尽都杀灭。'),
('CUV', '撒母耳记上', 9, 22, 20, '亚希突的儿子亚希米勒有一个儿子，名叫亚比亚他，逃到大卫那里。'),
('CUV', '撒母耳记上', 9, 22, 21, '亚比亚他将扫罗杀耶和华祭司的事告诉大卫。'),
('CUV', '撒母耳记上', 9, 22, 22, '大卫对亚比亚他说：那日我见以东人多益在那里，就知道他必告诉扫罗。你父的全家丧命，都是因我的缘故。'),
('CUV', '撒母耳记上', 9, 22, 23, '你可以住在我这里，不要惧怕。因为寻索你命的就是寻索我的命；你在我这里可得保全。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 23, 1, '有人告诉大卫说：非利士人攻击基伊拉，抢夺禾场。'),
('CUV', '撒母耳记上', 9, 23, 2, '所以大卫求问耶和华说：我去攻打那些非利士人可以不可以？耶和华对大卫说：你可以去攻打非利士人，拯救基伊拉。'),
('CUV', '撒母耳记上', 9, 23, 3, '跟随大卫的人对他说：我们在犹大地这里尚且惧怕，何况往基伊拉去攻打非利士人的军旅呢？'),
('CUV', '撒母耳记上', 9, 23, 4, '大卫又求问耶和华。耶和华回答说：你起身下基伊拉去，我必将非利士人交在你手里。'),
('CUV', '撒母耳记上', 9, 23, 5, '大卫和跟随他的人往基伊拉去，与非利士人打仗，大大杀败他们，又夺获他们的牲畜。这样，大卫救了基伊拉的居民。'),
('CUV', '撒母耳记上', 9, 23, 6, '亚希米勒的儿子亚比亚他逃到基伊拉见大卫的时候，手里拿著以弗得。'),
('CUV', '撒母耳记上', 9, 23, 7, '有人告诉扫罗说：大卫到了基伊拉。扫罗说：他进了有门有闩的城，困闭在里头；这是神将他交在我手里了。'),
('CUV', '撒母耳记上', 9, 23, 8, '于是扫罗招聚众民，要下去攻打基伊拉城，围困大卫和跟随他的人。'),
('CUV', '撒母耳记上', 9, 23, 9, '大卫知道扫罗设计谋害他，就对祭司亚比亚他说：将以弗得拿过来。'),
('CUV', '撒母耳记上', 9, 23, 10, '大卫祷告说：耶和华─以色列的神啊，你仆人听真了扫罗要往基伊拉来，为我的缘故灭城。'),
('CUV', '撒母耳记上', 9, 23, 11, '基伊拉人将我交在扫罗手里不交？扫罗照著你仆人所听的话下来不下来？耶和华─以色列的神啊，求你指示仆人！耶和华说：扫罗必下来。'),
('CUV', '撒母耳记上', 9, 23, 12, '大卫又说：基伊拉人将我和跟随我的人交在扫罗手里不交？耶和华说：必交出来。'),
('CUV', '撒母耳记上', 9, 23, 13, '大卫和跟随他的约有六百人，就起身出了基伊拉，往他们所能往的地方去。有人告诉扫罗，大卫离开基伊拉逃走；于是扫罗不出来了。'),
('CUV', '撒母耳记上', 9, 23, 14, '大卫住在旷野的山寨里，常在西弗旷野的山地。扫罗天天寻索大卫，神却不将大卫交在他手里。'),
('CUV', '撒母耳记上', 9, 23, 15, '大卫知道扫罗出来寻索他的命。那时，他住在西弗旷野的树林里；'),
('CUV', '撒母耳记上', 9, 23, 16, '扫罗的儿子约拿单起身，往那树林里去见大卫，使他倚靠神得以坚固，'),
('CUV', '撒母耳记上', 9, 23, 17, '对他说：不要惧怕！我父扫罗的手必不加害于你；你必作以色列的王，我也作你的宰相。这事我父扫罗知道了。'),
('CUV', '撒母耳记上', 9, 23, 18, '于是二人在耶和华面前立约。大卫仍住在树林里，约拿单回家去了。'),
('CUV', '撒母耳记上', 9, 23, 19, '西弗人上到基比亚见扫罗，说：大卫不是在我们那里的树林里山寨中、旷野南边的哈基拉山藏著么？'),
('CUV', '撒母耳记上', 9, 23, 20, '王啊，请你随你的心愿下来，我们必亲自将他交在王的手里。'),
('CUV', '撒母耳记上', 9, 23, 21, '扫罗说：愿耶和华赐福与你们，因你们顾恤我。'),
('CUV', '撒母耳记上', 9, 23, 22, '请你们回去，再确实查明他的住处和行踪，是谁看见他在那里，因为我听见人说他甚狡猾。'),
('CUV', '撒母耳记上', 9, 23, 23, '所以要看准他藏匿的地方，回来据实地告诉我，我就与你们同去。他若在犹大的境内，我必从千门万户中搜出他来。'),
('CUV', '撒母耳记上', 9, 23, 24, '西弗人就起身，在扫罗以先往西弗去。大卫和跟随他的人却在玛云旷野南边的亚拉巴。'),
('CUV', '撒母耳记上', 9, 23, 25, '扫罗和跟随他的人去寻找大卫；有人告诉大卫，他就下到磐石，住在玛云的旷野。扫罗听见，便在玛云的旷野追赶大卫。'),
('CUV', '撒母耳记上', 9, 23, 26, '扫罗在山这边走，大卫和跟随他的人在山那边走。大卫急忙躲避扫罗；因为扫罗和跟随他的人，四面围住大卫和跟随他的人，要拿获他们。'),
('CUV', '撒母耳记上', 9, 23, 27, '忽有使者来报告扫罗说：非利士人犯境抢掠，请王快快回去！'),
('CUV', '撒母耳记上', 9, 23, 28, '于是扫罗不追赶大卫，回去攻打非利士人。因此那地方名叫西拉哈玛希罗结。'),
('CUV', '撒母耳记上', 9, 23, 29, '大卫从那里上去，住在隐基底的山寨里。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 24, 1, '扫罗追赶非利士人回来，有人告诉他说：大卫在隐基底的旷野。'),
('CUV', '撒母耳记上', 9, 24, 2, '扫罗就从以色列人中挑选三千精兵，率领他们往野羊的磐石去，寻索大卫和跟随他的人。'),
('CUV', '撒母耳记上', 9, 24, 3, '到了路旁的羊圈，在那里有洞，扫罗进去大解。大卫和跟随他的人正藏在洞里的深处。'),
('CUV', '撒母耳记上', 9, 24, 4, '跟随的人对大卫说：耶和华曾应许你说：我要将你的仇敌交在你手里，你可以任意待他。如今时候到了！大卫就起来，悄悄地割下扫罗外袍的衣襟。'),
('CUV', '撒母耳记上', 9, 24, 5, '随后大卫心中自责，因为割下扫罗的衣襟；'),
('CUV', '撒母耳记上', 9, 24, 6, '对跟随他的人说：我的主乃是耶和华的受膏者，我在耶和华面前万不敢伸手害他，因他是耶和华的受膏者。'),
('CUV', '撒母耳记上', 9, 24, 7, '大卫用这话拦住跟随他的人，不容他们起来害扫罗。扫罗起来，从洞里出去行路。'),
('CUV', '撒母耳记上', 9, 24, 8, '随后大卫也起来，从洞里出去，呼叫扫罗说：我主，我王！扫罗回头观看，大卫就屈身、脸伏于地下拜。'),
('CUV', '撒母耳记上', 9, 24, 9, '大卫对扫罗说：你为何听信人的谗言，说大卫想要害你呢？'),
('CUV', '撒母耳记上', 9, 24, 10, '今日你亲眼看见在洞中，耶和华将你交在我手里；有人叫我杀你，我却爱惜你，说：我不敢伸手害我的主，因为他是耶和华的受膏者。'),
('CUV', '撒母耳记上', 9, 24, 11, '我父啊，看看你外袍的衣襟在我手中。我割下你的衣襟，没有杀你；你由此可以知道我没有恶意叛逆你。你虽然猎取我的命，我却没有得罪你。'),
('CUV', '撒母耳记上', 9, 24, 12, '愿耶和华在你我中间判断是非，在你身上为我伸冤，我却不亲手加害于你。'),
('CUV', '撒母耳记上', 9, 24, 13, '古人有句俗语说：恶事出于恶人。我却不亲手加害于你。'),
('CUV', '撒母耳记上', 9, 24, 14, '以色列王出来要寻找谁呢？追赶谁呢？不过追赶一条死狗，一个虼蚤就是了。'),
('CUV', '撒母耳记上', 9, 24, 15, '愿耶和华在你我中间施行审判，断定是非，并且鉴察，为我伸冤，救我脱离你的手。'),
('CUV', '撒母耳记上', 9, 24, 16, '大卫向扫罗说完这话，扫罗说：我儿大卫，这是你的声音么？就放声大哭，'),
('CUV', '撒母耳记上', 9, 24, 17, '对大卫说：你比我公义；因为你以善待我，我却以恶待你。'),
('CUV', '撒母耳记上', 9, 24, 18, '你今日显明是以善待我；因为耶和华将我交在你手里，你却没有杀我。'),
('CUV', '撒母耳记上', 9, 24, 19, '人若遇见仇敌，岂肯放他平安无事地去呢？愿耶和华因你今日向我所行的，以善报你。'),
('CUV', '撒母耳记上', 9, 24, 20, '我也知道你必要作王，以色列的国必坚立在你手里。'),
('CUV', '撒母耳记上', 9, 24, 21, '现在你要指著耶和华向我起誓，不剪除我的后裔，在我父家不灭没我的名。'),
('CUV', '撒母耳记上', 9, 24, 22, '于是大卫向扫罗起誓，扫罗就回家去；大卫和跟随他的人上山寨去了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 25, 1, '撒母耳死了，以色列众人聚集，为他哀哭，将他葬在拉玛─他自己的坟墓（原文是房屋）里。大卫起身，下到巴兰的旷野。'),
('CUV', '撒母耳记上', 9, 25, 2, '在玛云有一个人，他的产业在迦密，是一个大富户，有三千绵羊，一千山羊；他正在迦密剪羊毛。'),
('CUV', '撒母耳记上', 9, 25, 3, '那人名叫拿八，是迦勒族的人；他的妻名叫亚比该，是聪明俊美的妇人。拿八为人刚愎凶恶。'),
('CUV', '撒母耳记上', 9, 25, 4, '大卫在旷野听见说拿八剪羊毛，'),
('CUV', '撒母耳记上', 9, 25, 5, '大卫就打发十个仆人，吩咐他们说：你们上迦密去见拿八，提我的名问他安。'),
('CUV', '撒母耳记上', 9, 25, 6, '要对那富户如此说：愿你平安，愿你家平安，愿你一切所有的都平安。'),
('CUV', '撒母耳记上', 9, 25, 7, '现在我听说有人为你剪羊毛，你的牧人在迦密的时候和我们在一处，我们没有欺负他们，他们也未曾失落甚么。'),
('CUV', '撒母耳记上', 9, 25, 8, '可以问你的仆人，他们必告诉你。所以愿我的仆人在你眼前蒙恩，因为是在好日子来的。求你随手取点赐与仆人和你儿子大卫。'),
('CUV', '撒母耳记上', 9, 25, 9, '大卫的仆人到了，将这话提大卫的名都告诉了拿八，就住了口。'),
('CUV', '撒母耳记上', 9, 25, 10, '拿八回答大卫的仆人说：大卫是谁？耶西的儿子是谁？近来悖逆主人奔逃的仆人甚多，'),
('CUV', '撒母耳记上', 9, 25, 11, '我岂可将饮食和为我剪羊毛人所宰的肉给我不知道从哪里来的人呢？'),
('CUV', '撒母耳记上', 9, 25, 12, '大卫的仆人就转身从原路回去，照这话告诉大卫。'),
('CUV', '撒母耳记上', 9, 25, 13, '大卫向跟随他的人说：你们各人都要带上刀！众人就都带上刀，大卫也带上刀。跟随大卫上去的约有四百人，留下二百人看守器具。'),
('CUV', '撒母耳记上', 9, 25, 14, '有拿八的一个仆人告诉拿八的妻亚比该说：大卫从旷野打发使者来问我主人的安，主人却辱骂他们。'),
('CUV', '撒母耳记上', 9, 25, 15, '但是那些人待我们甚好；我们在田野与他们来往的时候，没有受他们的欺负，也未曾失落甚么。'),
('CUV', '撒母耳记上', 9, 25, 16, '我们在他们那里牧羊的时候，他们昼夜作我们的保障。'),
('CUV', '撒母耳记上', 9, 25, 17, '所以你当筹划，看怎样行才好；不然，祸患定要临到我主人和他全家。他性情凶暴，无人敢与他说话。'),
('CUV', '撒母耳记上', 9, 25, 18, '亚比该急忙将二百饼，两皮袋酒，五只收拾好了的羊，五细亚烘好了的穗子，一百葡萄饼，二百无花果饼，都驮在驴上，'),
('CUV', '撒母耳记上', 9, 25, 19, '对仆人说：你们前头走，我随著你们去。这事他却没有告诉丈夫拿八。'),
('CUV', '撒母耳记上', 9, 25, 20, '亚比该骑著驴，正下山坡，见大卫和跟随他的人从对面下来，亚比该就迎接他们。'),
('CUV', '撒母耳记上', 9, 25, 21, '大卫曾说：我在旷野为那人看守所有的，以致他一样不失落，实在是徒然了！他向我以恶报善。'),
('CUV', '撒母耳记上', 9, 25, 22, '凡属拿八的男丁，我若留一个到明日早晨，愿神重重降罚与我！'),
('CUV', '撒母耳记上', 9, 25, 23, '亚比该见大卫，便急忙下驴，在大卫面前脸伏于地叩拜，'),
('CUV', '撒母耳记上', 9, 25, 24, '俯伏在大卫的脚前，说：我主啊，愿这罪归我！求你容婢女向你进言，更求你听婢女的话。'),
('CUV', '撒母耳记上', 9, 25, 25, '我主不要理这坏人拿八，他的性情与他的名相称；他名叫拿八（就是愚顽的意思），他为人果然愚顽。但我主所打发的仆人，婢女并没有看见。'),
('CUV', '撒母耳记上', 9, 25, 26, '我主啊，耶和华既然阻止你亲手报仇，取流血的罪，所以我指著永生的耶和华，又敢在你面前起誓说：愿你的仇敌和谋害你的人都像拿八一样。'),
('CUV', '撒母耳记上', 9, 25, 27, '如今求你将婢女送来的礼物给跟随你的仆人。'),
('CUV', '撒母耳记上', 9, 25, 28, '求你饶恕婢女的罪过。耶和华必为我主建立坚固的家，因我主为耶和华争战；并且在你平生的日子查不出有甚么过来。'),
('CUV', '撒母耳记上', 9, 25, 29, '虽有人起来追逼你，寻索你的性命，你的性命却在耶和华─你的神那里蒙保护，如包裹宝器一样；你仇敌的性命，耶和华必抛去，如用机弦甩石一样。'),
('CUV', '撒母耳记上', 9, 25, 30, '我主现在若不亲手报仇流无辜人的血，到了耶和华照所应许你的话赐福与你，立你作以色列的王，那时我主必不至心里不安，觉得良心有亏。耶和华赐福与我主的时候，求你记念婢女。'),
('CUV', '撒母耳记上', 9, 25, 31, 'a'),
('CUV', '撒母耳记上', 9, 25, 32, '大卫对亚比该说：耶和华─以色列的神是应当称颂的，因为他今日使你来迎接我。'),
('CUV', '撒母耳记上', 9, 25, 33, '你和你的见识也当称赞；因为你今日拦阻我亲手报仇、流人的血。'),
('CUV', '撒母耳记上', 9, 25, 34, '我指著阻止我加害于你的耶和华─以色列永生的神起誓，你若不速速地来迎接我，到明日早晨，凡属拿八的男丁必定不留一个。'),
('CUV', '撒母耳记上', 9, 25, 35, '大卫受了亚比该送来的礼物，就对他说：我听了你的话，准了你的情面，你可以平平安安地回家罢！'),
('CUV', '撒母耳记上', 9, 25, 36, '亚比该到拿八那里，见他在家里设摆筵席，如同王的筵席；拿八快乐大醉。亚比该无论大小事都没有告诉他，就等到次日早晨。'),
('CUV', '撒母耳记上', 9, 25, 37, '到了早晨，拿八醒了酒，他的妻将这些事都告诉他，他就魂不附体，身僵如石头一般。'),
('CUV', '撒母耳记上', 9, 25, 38, '过了十天，耶和华击打拿八，他就死了。'),
('CUV', '撒母耳记上', 9, 25, 39, '大卫听见拿八死了，就说：应当称颂耶和华，因他伸了拿八羞辱我的冤，又阻止仆人行恶；也使拿八的恶归到拿八的头上。于是大卫打发人去，与亚比该说，要娶他为妻。'),
('CUV', '撒母耳记上', 9, 25, 40, '大卫的仆人到了迦密见亚比该，对他说：大卫打发我们来见你，想要娶你为妻。'),
('CUV', '撒母耳记上', 9, 25, 41, '亚比该就起来，俯伏在地，说：我情愿作婢女，洗我主仆人的脚。'),
('CUV', '撒母耳记上', 9, 25, 42, '亚比该立刻起身，骑上驴，带著五个使女，跟从大卫的使者去了，就作了大卫的妻。'),
('CUV', '撒母耳记上', 9, 25, 43, '大卫先娶了耶斯列人亚希暖，他们二人都作了他的妻。'),
('CUV', '撒母耳记上', 9, 25, 44, '扫罗已将他的女儿米甲，就是大卫的妻，给了迦琳人拉亿的儿子帕提为妻。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 26, 1, '西弗人到基比亚见扫罗，说：大卫不是在旷野前的哈基拉山藏著么？'),
('CUV', '撒母耳记上', 9, 26, 2, '扫罗就起身，带领以色列人中挑选的三千精兵下到西弗的旷野，要在那里寻索大卫。'),
('CUV', '撒母耳记上', 9, 26, 3, '扫罗在旷野前的哈基拉山，在道路上安营。大卫住在旷野，听说扫罗到旷野来追寻他，'),
('CUV', '撒母耳记上', 9, 26, 4, '就打发人去探听，便知道扫罗果然来到。'),
('CUV', '撒母耳记上', 9, 26, 5, '大卫起来，到扫罗安营的地方，看见扫罗和他的元帅尼珥的儿子押尼珥睡卧之处；扫罗睡在辎重营里，百姓安营在他周围。'),
('CUV', '撒母耳记上', 9, 26, 6, '大卫对赫人亚希米勒和洗鲁雅的儿子约押的兄弟亚比筛说：谁同我下到扫罗营里去？亚比筛说：我同你下去。'),
('CUV', '撒母耳记上', 9, 26, 7, '于是大卫和亚比筛夜间到了百姓那里，见扫罗睡在辎重营里；他的枪在头旁，插在地上。押尼珥和百姓睡在他周围。'),
('CUV', '撒母耳记上', 9, 26, 8, '亚比筛对大卫说：现在神将你的仇敌交在你手里，求你容我拿枪将他刺透在地，一刺就成，不用再刺。'),
('CUV', '撒母耳记上', 9, 26, 9, '大卫对亚比筛说：不可害死他。有谁伸手害耶和华的受膏者而无罪呢？'),
('CUV', '撒母耳记上', 9, 26, 10, '大卫又说：我指著永生的耶和华起誓，他或被耶和华击打，或是死期到了，或是出战阵亡；'),
('CUV', '撒母耳记上', 9, 26, 11, '我在耶和华面前，万不敢伸手害耶和华的受膏者。现在你可以将他头旁的枪和水瓶拿来，我们就走。'),
('CUV', '撒母耳记上', 9, 26, 12, '大卫从扫罗的头旁拿了枪和水瓶，二人就走了，没有人看见，没有人知道，也没有人醒起，都睡著了，因为耶和华使他们沉沉地睡了。'),
('CUV', '撒母耳记上', 9, 26, 13, '大卫过到那边去，远远地站在山顶上，与他们相离甚远。'),
('CUV', '撒母耳记上', 9, 26, 14, '大卫呼叫百姓和尼珥的儿子押尼珥说：押尼珥啊，你为何不答应呢？押尼珥说：你是谁？竟敢呼叫王呢？'),
('CUV', '撒母耳记上', 9, 26, 15, '大卫对押尼珥说：你不是个勇士么？以色列中谁能比你呢？民中有人进来要害死王─你的主，你为何没有保护王─你的主呢？'),
('CUV', '撒母耳记上', 9, 26, 16, '你这样是不好的！我指著永生的耶和华起誓，你们都是该死的；因为没有保护你们的主，就是耶和华的受膏者。现在你看看王头旁的枪和水瓶在哪里。'),
('CUV', '撒母耳记上', 9, 26, 17, '扫罗听出是大卫的声音，就说：我儿大卫，这是你的声音么？大卫说：主─我的王啊，是我的声音；'),
('CUV', '撒母耳记上', 9, 26, 18, '又说：我做了甚么？我手里有甚么恶事？我主竟追赶仆人呢？'),
('CUV', '撒母耳记上', 9, 26, 19, '求我主我王听仆人的话：若是耶和华激发你攻击我，愿耶和华收纳祭物；若是人激发你，愿他在耶和华面前受咒诅；因为他现今赶逐我，不容我在耶和华的产业上有分，说：你去事奉别神罢！'),
('CUV', '撒母耳记上', 9, 26, 20, '现在求王不要使我的血流在离耶和华远的地方。以色列王出来是寻找一个虼蚤，如同人在山上猎取一个鹧鸪一般。'),
('CUV', '撒母耳记上', 9, 26, 21, '扫罗说：我有罪了！我儿大卫，你可以回来，因你今日看我的性命为宝贵；我必不再加害于你。我是糊涂人，大大错了。'),
('CUV', '撒母耳记上', 9, 26, 22, '大卫说：王的枪在这里，可以吩咐一个仆人过来拿去。'),
('CUV', '撒母耳记上', 9, 26, 23, '今日耶和华将王交在我手里，我却不肯伸手害耶和华的受膏者。耶和华必照各人的公义诚实报应他。'),
('CUV', '撒母耳记上', 9, 26, 24, '我今日重看你的性命，愿耶和华也重看我的性命，并且拯救我脱离一切患难。'),
('CUV', '撒母耳记上', 9, 26, 25, '扫罗对大卫说：我儿大卫，愿你得福！你必做大事，也必得胜。于是大卫起行，扫罗回他的本处去了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 27, 1, '大卫心里说：必有一日我死在扫罗手里，不如逃奔非利士地去。扫罗见我不在以色列的境内，就必绝望，不再寻索我；这样我可以脱离他的手。'),
('CUV', '撒母耳记上', 9, 27, 2, '于是大卫起身，和跟随他的六百人投奔迦特王─玛俄的儿子亚吉去了。'),
('CUV', '撒母耳记上', 9, 27, 3, '大卫和他的两个妻，就是耶斯列人亚希暖和作过拿八妻的迦密人亚比该，并跟随他的人，连各人的眷属，都住在迦特的亚吉那里。'),
('CUV', '撒母耳记上', 9, 27, 4, '有人告诉扫罗说：大卫逃到迦特。扫罗就不再寻索他了。'),
('CUV', '撒母耳记上', 9, 27, 5, '大卫对亚吉说：我若在你眼前蒙恩，求你在京外的城邑中赐我一个地方居住。仆人何必与王同住京都呢？'),
('CUV', '撒母耳记上', 9, 27, 6, '当日亚吉将洗革拉赐给他，因此洗革拉属犹大王，直到今日。'),
('CUV', '撒母耳记上', 9, 27, 7, '大卫在非利士地住了一年零四个月。'),
('CUV', '撒母耳记上', 9, 27, 8, '大卫和跟随他的人上去，侵夺基述人、基色人、亚玛力人之地。这几族历来住在那地，从书珥直到埃及。'),
('CUV', '撒母耳记上', 9, 27, 9, '大卫击杀那地的人，无论男女都没有留下一个，又夺获牛、羊、骆驼、驴，并衣服，回来见亚吉。'),
('CUV', '撒母耳记上', 9, 27, 10, '亚吉说：你们今日侵夺了甚么地方呢？大卫说：侵夺了犹大的南方、耶拉篾的南方、基尼的南方。'),
('CUV', '撒母耳记上', 9, 27, 11, '无论男女，大卫没有留下一个带到迦特来。他说：恐怕他们将我们的事告诉人，说大卫住在非利士地的时候常常这样行。'),
('CUV', '撒母耳记上', 9, 27, 12, '亚吉信了大卫，心里说：大卫使本族以色列人憎恶他，所以他必永远作我的仆人了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 28, 1, '那时，非利士人聚集军旅，要与以色列人打仗。亚吉对大卫说：你当知道，你和跟随你的人都要随我出战。'),
('CUV', '撒母耳记上', 9, 28, 2, '大卫对亚吉说：仆人所能做的事，王必知道。亚吉对大卫说：这样，我立你永远作我的护卫长。'),
('CUV', '撒母耳记上', 9, 28, 3, '那时撒母耳已经死了，以色列众人为他哀哭，葬他在拉玛，就是在他本城里。扫罗曾在国内不容有交鬼的和行巫术的人。'),
('CUV', '撒母耳记上', 9, 28, 4, '非利士人聚集，来到书念安营；扫罗聚集以色列众人在基利波安营。'),
('CUV', '撒母耳记上', 9, 28, 5, '扫罗看见非利士的军旅就惧怕，心中发颤。'),
('CUV', '撒母耳记上', 9, 28, 6, '扫罗求问耶和华，耶和华却不藉梦，或乌陵，或先知回答他。'),
('CUV', '撒母耳记上', 9, 28, 7, '扫罗吩咐臣仆说：当为我找一个交鬼的妇人，我好去问他。臣仆说：在隐多珥有一个交鬼的妇人。'),
('CUV', '撒母耳记上', 9, 28, 8, '于是扫罗改了装，穿上别的衣服，带著两个人，夜里去见那妇人。扫罗说：求你用交鬼的法术，将我所告诉你的死人，为我招上来。'),
('CUV', '撒母耳记上', 9, 28, 9, '妇人对他说：你知道扫罗从国中剪除交鬼的和行巫术的。你为何陷害我的性命，使我死呢？'),
('CUV', '撒母耳记上', 9, 28, 10, '扫罗向妇人指著耶和华起誓说：我指著永生的耶和华起誓，你必不因这事受刑。'),
('CUV', '撒母耳记上', 9, 28, 11, '妇人说：我为你招谁上来呢？回答说：为我招撒母耳上来。'),
('CUV', '撒母耳记上', 9, 28, 12, '妇人看见撒母耳，就大声呼叫，对扫罗说：你是扫罗，为甚么欺哄我呢？'),
('CUV', '撒母耳记上', 9, 28, 13, '王对妇人说：不要惧怕，你看见了甚么呢？妇人对扫罗说：我看见有神从地里上来。'),
('CUV', '撒母耳记上', 9, 28, 14, '扫罗说：他是怎样的形状？妇人说：有一个老人上来，身穿长衣。扫罗知道是撒母耳，就屈身，脸伏于地下拜。'),
('CUV', '撒母耳记上', 9, 28, 15, '撒母耳对扫罗说：你为甚么搅扰我，招我上来呢？扫罗回答说：我甚窘急；因为非利士人攻击我，神也离开我，不再藉先知或梦回答我。因此请你上来，好指示我应当怎样行。'),
('CUV', '撒母耳记上', 9, 28, 16, '撒母耳说：耶和华已经离开你，且与你为敌，你何必问我呢？'),
('CUV', '撒母耳记上', 9, 28, 17, '耶和华照他藉我说的话，已经从你手里夺去国权，赐与别人，就是大卫。'),
('CUV', '撒母耳记上', 9, 28, 18, '因你没有听从耶和华的命令；他恼怒亚玛力人，你没有灭绝他们，所以今日耶和华向你这样行，'),
('CUV', '撒母耳记上', 9, 28, 19, '并且耶和华必将你和以色列人交在非利士人的手里。明日你和你众子必与我在一处了；耶和华必将以色列的军兵交在非利士人手里。'),
('CUV', '撒母耳记上', 9, 28, 20, '扫罗猛然仆倒，挺身在地，因撒母耳的话甚是惧怕；那一昼一夜没有吃甚么，就毫无气力。'),
('CUV', '撒母耳记上', 9, 28, 21, '妇人到扫罗面前，见他极其惊恐，对他说：婢女听从你的话，不顾惜自己的性命，遵从你所吩咐的。'),
('CUV', '撒母耳记上', 9, 28, 22, '现在求你听婢女的话，容我在你面前摆上一点食物，你吃了，可以有气力行路。'),
('CUV', '撒母耳记上', 9, 28, 23, '扫罗不肯，说：我不吃。但他的仆人和妇人再三劝他，他才听了他们的话，从地上起来，坐在床上。'),
('CUV', '撒母耳记上', 9, 28, 24, '妇人急忙将家里的一只肥牛犊宰了，又拿面抟成无酵饼烤了，'),
('CUV', '撒母耳记上', 9, 28, 25, '摆在扫罗和他仆人面前。他们吃完，当夜就起身走了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 29, 1, '非利士人将他们的军旅聚到亚弗；以色列人在耶斯列的泉旁安营。'),
('CUV', '撒母耳记上', 9, 29, 2, '非利士人的首领各率军队，或百或千，挨次前进；大卫和跟随他的人同著亚吉跟在后边。'),
('CUV', '撒母耳记上', 9, 29, 3, '非利士人的首领说：这些希伯来人在这里做甚么呢？亚吉对他们说：这不是以色列王扫罗的臣子大卫么？他在我这里有些年日了。自从他投降我直到今日，我未曾见他有过错。'),
('CUV', '撒母耳记上', 9, 29, 4, '非利士人的首领向亚吉发怒，对他说：你要叫这人回你所安置他的地方，不可叫他同我们出战，恐怕他在阵上反为我们的敌人。他用甚么与他主人复和呢？岂不是用我们这些人的首级么？'),
('CUV', '撒母耳记上', 9, 29, 5, '从前以色列的妇女跳舞唱和说：扫罗杀死千千，大卫杀死万万，所说的不是这个大卫么？'),
('CUV', '撒母耳记上', 9, 29, 6, '亚吉叫大卫来，对他说：我指著永生的耶和华起誓，你是正直人。你随我在军中出入，我看你甚好。自从你投奔我到如今，我未曾见你有甚么过失；只是众首领不喜悦你。'),
('CUV', '撒母耳记上', 9, 29, 7, '现在你可以平平安安地回去，免得非利士人的首领不欢喜你。'),
('CUV', '撒母耳记上', 9, 29, 8, '大卫对亚吉说：我做了甚么呢？自从仆人到你面前，直到今日，你查出我有甚么过错，使我不去攻击主─我王的仇敌呢？'),
('CUV', '撒母耳记上', 9, 29, 9, '亚吉说：我知道你在我眼前是好人，如同神的使者一般；只是非利士人的首领说：这人不可同我们出战。'),
('CUV', '撒母耳记上', 9, 29, 10, '故此你和跟随你的人，就是你本主的仆人，要明日早晨起来，等到天亮回去罢！'),
('CUV', '撒母耳记上', 9, 29, 11, '于是大卫和跟随他的人早晨起来，回往非利士地去。非利士人也上耶斯列去了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 30, 1, '第三日，大卫和跟随他的人到了洗革拉。亚玛力人已经侵夺南地，攻破洗革拉，用火焚烧，'),
('CUV', '撒母耳记上', 9, 30, 2, '掳了城内的妇女和其中的大小人口，却没有杀一个，都带著走了。'),
('CUV', '撒母耳记上', 9, 30, 3, '大卫和跟随他的人到了那城，不料，城已烧毁，他们的妻子儿女都被掳去了。'),
('CUV', '撒母耳记上', 9, 30, 4, '大卫和跟随他的人就放声大哭，直哭得没有气力。'),
('CUV', '撒母耳记上', 9, 30, 5, '大卫的两个妻─耶斯列人亚希暖和作过拿八妻的迦密人亚比该，也被掳去了。'),
('CUV', '撒母耳记上', 9, 30, 6, '大卫甚是焦急，因众人为自己的儿女苦恼，说：要用石头打死他。大卫却倚靠耶和华─他的神，心里坚固。'),
('CUV', '撒母耳记上', 9, 30, 7, '大卫对亚希米勒的儿子祭司亚比亚他说：请你将以弗得拿过来。亚比亚他就将以弗得拿到大卫面前。'),
('CUV', '撒母耳记上', 9, 30, 8, '大卫求问耶和华说：我追赶敌军，追得上追不上呢？耶和华说：你可以追，必追得上，都救得回来。'),
('CUV', '撒母耳记上', 9, 30, 9, '于是，大卫和跟随他的六百人来到比梭溪；有不能前去的就留在那里。'),
('CUV', '撒母耳记上', 9, 30, 10, '大卫却带著四百人往前追赶，有二百人疲乏，不能过比梭溪，所以留在那里。'),
('CUV', '撒母耳记上', 9, 30, 11, '这四百人在田野遇见一个埃及人，就带他到大卫面前，给他饼吃，给他水喝，'),
('CUV', '撒母耳记上', 9, 30, 12, '又给他一块无花果饼，两个葡萄饼。他吃了，就精神复原；因为他三日三夜没有吃饼，没有喝水。'),
('CUV', '撒母耳记上', 9, 30, 13, '大卫问他说：你是属谁的？你是哪里的人？他回答说：我是埃及的少年人，是亚玛力人的奴仆；因我三日前患病，我主人就把我撇弃了。'),
('CUV', '撒母耳记上', 9, 30, 14, '我们侵夺了基利提的南方和属犹大的地，并迦勒地的南方，又用火烧了洗革拉。'),
('CUV', '撒母耳记上', 9, 30, 15, '大卫问他说：你肯领我们到敌军那里不肯？他回答说：你要向我指著神起誓，不杀我，也不将我交在我主人手里，我就领你下到敌军那里。'),
('CUV', '撒母耳记上', 9, 30, 16, '那人领大卫下去，见他们散在地上，吃喝跳舞，因为从非利士地和犹大地所掳来的财物甚多。'),
('CUV', '撒母耳记上', 9, 30, 17, '大卫从黎明直到次日晚上，击杀他们，除了四百骑骆驼的少年人之外，没有一个逃脱的。'),
('CUV', '撒母耳记上', 9, 30, 18, '亚玛力人所掳去的财物，大卫全都夺回，并救回他的两个妻来。'),
('CUV', '撒母耳记上', 9, 30, 19, '凡亚玛力人所掳去的，无论大小、儿女、财物，大卫都夺回来，没有失落一个。'),
('CUV', '撒母耳记上', 9, 30, 20, '大卫所夺来的牛群羊群，跟随他的人赶在原有的群畜前边，说：这是大卫的掠物。'),
('CUV', '撒母耳记上', 9, 30, 21, '大卫到了那疲乏不能跟随、留在比梭溪的二百人那里。他们出来迎接大卫并跟随的人。大卫前来问他们安。'),
('CUV', '撒母耳记上', 9, 30, 22, '跟随大卫人中的恶人和匪类说：这些人既然没有和我们同去，我们所夺的财物就不分给他们，只将他们各人的妻子儿女给他们，使他们带去就是了。'),
('CUV', '撒母耳记上', 9, 30, 23, '大卫说：弟兄们，耶和华所赐给我们的，不可不分给他们；因为他保佑我们，将那攻击我们的敌军交在我们手里。'),
('CUV', '撒母耳记上', 9, 30, 24, '这事谁肯依从你们呢？上阵的得多少，看守器具的也得多少；应当大家平分。'),
('CUV', '撒母耳记上', 9, 30, 25, '大卫定此为以色列的律例典章，从那日直到今日。'),
('CUV', '撒母耳记上', 9, 30, 26, '大卫到了洗革拉，从掠物中取些送给他朋友犹大的长老，说：这是从耶和华仇敌那里夺来的，送你们为礼物。'),
('CUV', '撒母耳记上', 9, 30, 27, '他送礼物给住伯特利的，南地拉末的，雅提珥的；'),
('CUV', '撒母耳记上', 9, 30, 28, '住亚罗珥的，息末的，以实提莫的；'),
('CUV', '撒母耳记上', 9, 30, 29, '住拉哈勒的，耶拉篾各城的，基尼各城的；'),
('CUV', '撒母耳记上', 9, 30, 30, '住何珥玛的，歌拉珊的，亚挞的；'),
('CUV', '撒母耳记上', 9, 30, 31, '住希伯仑的，并大卫和跟随他的人素来所到之处的人。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记上', 9, 31, 1, '非利士人与以色列人争战。以色列人在非利士人面前逃跑，在基利波有被杀仆倒的。'),
('CUV', '撒母耳记上', 9, 31, 2, '非利士人紧追扫罗和他儿子们，就杀了扫罗的儿子约拿单、亚比拿达、麦基舒亚。'),
('CUV', '撒母耳记上', 9, 31, 3, '势派甚大，扫罗被弓箭手追上，射伤甚重，'),
('CUV', '撒母耳记上', 9, 31, 4, '就吩咐拿他兵器的人说：你拔出刀来，将我刺死，免得那些未受割礼的人来刺我，凌辱我。但拿兵器的人甚惧怕，不肯刺他；扫罗就自己伏在刀上死了。'),
('CUV', '撒母耳记上', 9, 31, 5, '拿兵器的人见扫罗已死，也伏在刀上死了。'),
('CUV', '撒母耳记上', 9, 31, 6, '这样，扫罗和他三个儿子，与拿他兵器的人，以及跟随他的人，都一同死亡。'),
('CUV', '撒母耳记上', 9, 31, 7, '住平原那边并约但河西的以色列人，见以色列军兵逃跑，扫罗和他儿子都死了，也就弃城逃跑。非利士人便来住在其中。'),
('CUV', '撒母耳记上', 9, 31, 8, '次日，非利士人来剥那被杀之人的衣服，看见扫罗和他三个儿子仆倒在基利波山，'),
('CUV', '撒母耳记上', 9, 31, 9, '就割下他的首级，剥了他的军装，打发人到（或译：送到）非利士地的四境，报信与他们庙里的偶像和众民；'),
('CUV', '撒母耳记上', 9, 31, 10, '又将扫罗的军装放在亚斯他录庙里，将他的尸身钉在伯珊的城墙上。'),
('CUV', '撒母耳记上', 9, 31, 11, '基列雅比的居民听见非利士人向扫罗所行的事，'),
('CUV', '撒母耳记上', 9, 31, 12, '他们中间所有的勇士就起身，走了一夜，将扫罗和他儿子的尸身从伯珊城墙上取下来，送到雅比那里，用火烧了；'),
('CUV', '撒母耳记上', 9, 31, 13, '将他们骸骨葬在雅比的垂丝柳树下，就禁食七日。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记下', 10, 1, 1, '扫罗死后，大卫击杀亚玛力人回来，在洗革拉住了两天。'),
('CUV', '撒母耳记下', 10, 1, 2, '第三天，有一人从扫罗的营里出来，衣服撕裂，头蒙灰尘，到大卫面前伏地叩拜。'),
('CUV', '撒母耳记下', 10, 1, 3, '大卫问他说：你从哪里来？他说：我从以色列的营里逃来。'),
('CUV', '撒母耳记下', 10, 1, 4, '大卫又问他说：事情怎样？请你告诉我。他回答说：百姓从阵上逃跑，也有许多人仆倒死亡；扫罗和他儿子约拿单也死了。'),
('CUV', '撒母耳记下', 10, 1, 5, '大卫问报信的少年人说：你怎么知道扫罗和他儿子约拿单死了呢？'),
('CUV', '撒母耳记下', 10, 1, 6, '报信的少年人说：我偶然到基利波山，看见扫罗伏在自己枪上，有战车、马兵紧紧地追他。'),
('CUV', '撒母耳记下', 10, 1, 7, '他回头看见我，就呼叫我。我说：我在这里。'),
('CUV', '撒母耳记下', 10, 1, 8, '他问我说：你是甚么人？我说：我是亚玛力人。'),
('CUV', '撒母耳记下', 10, 1, 9, '他说：请你来，将我杀死；因为痛苦抓住我，我的生命尚存。'),
('CUV', '撒母耳记下', 10, 1, 10, '我准知他仆倒必不能活，就去将他杀死，把他头上的冠冕、臂上的镯子拿到我主这里。'),
('CUV', '撒母耳记下', 10, 1, 11, '大卫就撕裂衣服，跟随他的人也是如此，'),
('CUV', '撒母耳记下', 10, 1, 12, '而且悲哀哭号，禁食到晚上，是因扫罗和他儿子约拿单，并耶和华的民以色列家的人，倒在刀下。'),
('CUV', '撒母耳记下', 10, 1, 13, '大卫问报信的少年人说：你是哪里的人？他说：我是亚玛力客人的儿子。'),
('CUV', '撒母耳记下', 10, 1, 14, '大卫说：你伸手杀害耶和华的受膏者，怎么不畏惧呢？'),
('CUV', '撒母耳记下', 10, 1, 15, '大卫叫了一个少年人来，说：你去杀他罢！'),
('CUV', '撒母耳记下', 10, 1, 16, '大卫对他说：你流人血的罪归到自己的头上，因为你亲口作见证说：我杀了耶和华的受膏者。少年人就把他杀了。'),
('CUV', '撒母耳记下', 10, 1, 17, '大卫作哀歌，吊扫罗和他儿子约拿单，'),
('CUV', '撒母耳记下', 10, 1, 18, '且吩咐将这歌教导犹大人。这歌名叫弓歌，写在雅煞珥书上。'),
('CUV', '撒母耳记下', 10, 1, 19, '歌中说：以色列啊，你尊荣者在山上被杀！大英雄何竟死亡！'),
('CUV', '撒母耳记下', 10, 1, 20, '不要在迦特报告；不要在亚实基伦街上传扬；免得非利士的女子欢乐；免得未受割礼之人的女子矜夸。'),
('CUV', '撒母耳记下', 10, 1, 21, '基利波山哪，愿你那里没有雨露！愿你田地无土产可作供物！因为英雄的盾牌在那里被污丢弃；扫罗的盾牌仿佛未曾抹油。'),
('CUV', '撒母耳记下', 10, 1, 22, '约拿单的弓箭非流敌人的血不退缩；扫罗的刀剑非剖勇士的油不收回。'),
('CUV', '撒母耳记下', 10, 1, 23, '扫罗和约拿单─活时相悦相爱，死时也不分离─他们比鹰更快，比狮子还强。'),
('CUV', '撒母耳记下', 10, 1, 24, '以色列的女子啊，当为扫罗哭号！他曾使你们穿朱红色的美衣，使你们衣服有黄金的妆饰。'),
('CUV', '撒母耳记下', 10, 1, 25, '英雄何竟在阵上仆倒！约拿单何竟在山上被杀！'),
('CUV', '撒母耳记下', 10, 1, 26, '我兄约拿单哪，我为你悲伤！我甚喜悦你！你向我发的爱情奇妙非常，过于妇女的爱情。'),
('CUV', '撒母耳记下', 10, 1, 27, '英雄何竟仆倒！战具何竟灭没！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记下', 10, 2, 1, '此后，大卫问耶和华说：我上犹大的一个城去可以么？耶和华说：可以。大卫说：我上哪一个城去呢？耶和华说：上希伯仑去。'),
('CUV', '撒母耳记下', 10, 2, 2, '于是大卫和他的两个妻─一个是耶斯列人亚希暖，一个是作过迦密人拿八妻的亚比该─都上那里去了。'),
('CUV', '撒母耳记下', 10, 2, 3, '大卫也将跟随他的人和他们各人的眷属一同带上去，住在希伯仑的城邑中。'),
('CUV', '撒母耳记下', 10, 2, 4, '犹大人来到希伯仑，在那里膏大卫作犹大家的王。有人告诉大卫说：葬埋扫罗的是基列雅比人。'),
('CUV', '撒母耳记下', 10, 2, 5, '大卫就差人去见基列雅比人，对他们说：你们厚待你们的主─扫罗，将他葬埋。愿耶和华赐福与你们！'),
('CUV', '撒母耳记下', 10, 2, 6, '你们既行了这事，愿耶和华以慈爱诚实待你们，我也要为此厚待你们。'),
('CUV', '撒母耳记下', 10, 2, 7, '现在你们的主─扫罗死了，犹大家已经膏我作他们的王，所以你们要刚强奋勇。'),
('CUV', '撒母耳记下', 10, 2, 8, '扫罗的元帅尼珥的儿子押尼珥，曾将扫罗的儿子伊施波设带过河，到玛哈念，'),
('CUV', '撒母耳记下', 10, 2, 9, '立他作王，治理基列、亚书利、耶斯列、以法莲、便雅悯，和以色列众人。'),
('CUV', '撒母耳记下', 10, 2, 10, '扫罗的儿子伊施波设登基的时候年四十岁，作以色列王二年；惟独犹大家归从大卫。'),
('CUV', '撒母耳记下', 10, 2, 11, '大卫在希伯仑作犹大家的王，共七年零六个月。'),
('CUV', '撒母耳记下', 10, 2, 12, '尼珥的儿子押尼珥和扫罗的儿子伊施波设的仆人从玛哈念出来，往基遍去。'),
('CUV', '撒母耳记下', 10, 2, 13, '洗鲁雅的儿子约押和大卫的仆人也出来，在基遍池旁与他们相遇；一班坐在池这边，一班坐在池那边。'),
('CUV', '撒母耳记下', 10, 2, 14, '押尼珥对约押说：让少年人起来，在我们面前戏耍罢！约押说：可以。'),
('CUV', '撒母耳记下', 10, 2, 15, '就按著定数起来：属扫罗儿子伊施波设的便雅悯人过去十二名，大卫的仆人也过去十二名，'),
('CUV', '撒母耳记下', 10, 2, 16, '彼此揪头，用刀刺肋，一同仆倒。所以，那地叫作希利甲哈素林，就在基遍。'),
('CUV', '撒母耳记下', 10, 2, 17, '那日的战事凶猛，押尼珥和以色列人败在大卫的仆人面前。'),
('CUV', '撒母耳记下', 10, 2, 18, '在那里有洗鲁雅的三个儿子：约押、亚比筛、亚撒黑。亚撒黑脚快如野鹿一般；'),
('CUV', '撒母耳记下', 10, 2, 19, '亚撒黑追赶押尼珥，直追赶他不偏左右。'),
('CUV', '撒母耳记下', 10, 2, 20, '押尼珥回头说：你是亚撒黑么？回答说：是。'),
('CUV', '撒母耳记下', 10, 2, 21, '押尼珥对他说：你或转向左转向右，拿住一个少年人，剥去他的战衣。亚撒黑却不肯转开不追赶他。'),
('CUV', '撒母耳记下', 10, 2, 22, '押尼珥又对亚撒黑说：你转开不追赶我罢！我何必杀你呢？若杀你，有甚么脸见你哥哥约押呢？'),
('CUV', '撒母耳记下', 10, 2, 23, '亚撒黑仍不肯转开。故此，押尼珥就用枪𨱔刺入他的肚腹，甚至枪从背后透出，亚撒黑就在那里仆倒而死。众人赶到亚撒黑仆倒而死的地方，就都站住。'),
('CUV', '撒母耳记下', 10, 2, 24, '约押和亚比筛追赶押尼珥，日落的时候，到了通基遍旷野的路旁，基亚对面的亚玛山。'),
('CUV', '撒母耳记下', 10, 2, 25, '便雅悯人聚集，跟随押尼珥站在一个山顶上。'),
('CUV', '撒母耳记下', 10, 2, 26, '押尼珥呼叫约押说：刀剑岂可永远杀人么？你岂不知终久必有苦楚么？你要等何时才叫百姓回去、不追赶弟兄呢？'),
('CUV', '撒母耳记下', 10, 2, 27, '约押说：我指著永生的神起誓：你若不说戏耍的那句话，今日早晨百姓就回去，不追赶弟兄了。'),
('CUV', '撒母耳记下', 10, 2, 28, '于是约押吹角，众民就站住，不再追赶以色列人，也不再打仗了。'),
('CUV', '撒母耳记下', 10, 2, 29, '押尼珥和跟随他的人整夜经过亚拉巴，过约但河，走过毕伦，到了玛哈念。'),
('CUV', '撒母耳记下', 10, 2, 30, '约押追赶押尼珥回来，聚集众民，见大卫的仆人中缺少了十九个人和亚撒黑。'),
('CUV', '撒母耳记下', 10, 2, 31, '但大卫的仆人杀了便雅悯人和跟随押尼珥的人，共三百六十名。'),
('CUV', '撒母耳记下', 10, 2, 32, '众人将亚撒黑送到伯利恒，葬在他父亲的坟墓里。约押和跟随他的人走了一夜，天亮的时候到了希伯仑。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记下', 10, 3, 1, '扫罗家和大卫家争战许久。大卫家日见强盛；扫罗家日见衰弱。'),
('CUV', '撒母耳记下', 10, 3, 2, '大卫在希伯仑得了几个儿子：长子暗嫩是耶斯列人亚希暖所生的；'),
('CUV', '撒母耳记下', 10, 3, 3, '次子基利押（在历代上三章一节作但以利）是作过迦密人拿八的妻亚比该所生的；三子押沙龙是基述王达买的女儿玛迦所生的；'),
('CUV', '撒母耳记下', 10, 3, 4, '四子亚多尼雅是哈及所生的；五子示法提雅是亚比他所生的；'),
('CUV', '撒母耳记下', 10, 3, 5, '六子以特念是大卫的妻以格拉所生的。大卫这六个儿子都是在希伯仑生的。'),
('CUV', '撒母耳记下', 10, 3, 6, '扫罗家和大卫家争战的时候，押尼珥在扫罗家大有权势。'),
('CUV', '撒母耳记下', 10, 3, 7, '扫罗有一妃嫔，名叫利斯巴，是爱亚的女儿。一日，伊施波设对押尼珥说：你为甚么与我父的妃嫔同房呢？'),
('CUV', '撒母耳记下', 10, 3, 8, '押尼珥因伊施波设的话就甚发怒，说：我岂是犹大的狗头呢？我恩待你父扫罗的家和他的弟兄、朋友，不将你交在大卫手里，今日你竟为这妇人责备我么？'),
('CUV', '撒母耳记下', 10, 3, 9, '我若不照著耶和华起誓应许大卫的话行，废去扫罗的位，建立大卫的位，使他治理以色列和犹大，从但直到别是巴，愿神重重地降罚与我！'),
('CUV', '撒母耳记下', 10, 3, 10, 'a'),
('CUV', '撒母耳记下', 10, 3, 11, '伊施波设惧怕押尼珥，不敢回答一句。'),
('CUV', '撒母耳记下', 10, 3, 12, '押尼珥打发人去见大卫，替他说：这国归谁呢？又说：你与我立约，我必帮助你，使以色列人都归服你。'),
('CUV', '撒母耳记下', 10, 3, 13, '大卫说：好！我与你立约。但有一件，你来见我面的时候，若不将扫罗的女儿米甲带来，必不得见我的面。'),
('CUV', '撒母耳记下', 10, 3, 14, '大卫就打发人去见扫罗的儿子伊施波设，说：你要将我的妻米甲归还我；他是我从前用一百非利士人的阳皮所聘定的。'),
('CUV', '撒母耳记下', 10, 3, 15, '伊施波设就打发人去，将米甲从拉亿的儿子、他丈夫帕铁那里接回来。'),
('CUV', '撒母耳记下', 10, 3, 16, '米甲的丈夫跟著他，一面走一面哭，直跟到巴户琳。押尼珥说：你回去罢！帕铁就回去了。'),
('CUV', '撒母耳记下', 10, 3, 17, '押尼珥对以色列长老说：从前你们愿意大卫作王治理你们，'),
('CUV', '撒母耳记下', 10, 3, 18, '现在你们可以照心愿而行。因为耶和华曾论到大卫说：我必藉我仆人大卫的手，救我民以色列脱离非利士人和众仇敌的手。'),
('CUV', '撒母耳记下', 10, 3, 19, '押尼珥也用这话说给便雅悯人听，又到希伯仑，将以色列人和便雅悯全家一切所喜悦的事说给大卫听。'),
('CUV', '撒母耳记下', 10, 3, 20, '押尼珥带著二十个人来到希伯仑见大卫，大卫就为押尼珥和他带来的人设摆筵席。'),
('CUV', '撒母耳记下', 10, 3, 21, '押尼珥对大卫说：我要起身去招聚以色列众人来见我主我王，与你立约，你就可以照著心愿作王。于是大卫送押尼珥去，押尼珥就平平安安地去了。'),
('CUV', '撒母耳记下', 10, 3, 22, '约押和大卫的仆人攻击敌军，带回许多的掠物。那时押尼珥不在希伯仑大卫那里，因大卫已经送他去，他也平平安安地去了。'),
('CUV', '撒母耳记下', 10, 3, 23, '约押和跟随他的全军到了，就有人告诉约押说：尼珥的儿子押尼珥来见王，王送他去，他也平平安安地去了。'),
('CUV', '撒母耳记下', 10, 3, 24, '约押去见王说：你这是做甚么呢？押尼珥来见你，你为何送他去，他就踪影不见了呢？'),
('CUV', '撒母耳记下', 10, 3, 25, '你当晓得，尼珥的儿子押尼珥来是要诓哄你，要知道你的出入和你一切所行的事。'),
('CUV', '撒母耳记下', 10, 3, 26, '约押从大卫那里出来，就打发人去追赶押尼珥，在西拉井追上他，将他带回来，大卫却不知道。'),
('CUV', '撒母耳记下', 10, 3, 27, '押尼珥回到希伯仑，约押领他到城门的瓮洞，假作要与他说机密话，就在那里刺透他的肚腹，他便死了。这是报杀他兄弟亚撒黑的仇。'),
('CUV', '撒母耳记下', 10, 3, 28, '大卫听见了，就说：流尼珥的儿子押尼珥的血，这罪在耶和华面前必永不归我和我的国。'),
('CUV', '撒母耳记下', 10, 3, 29, '愿流他血的罪归到约押头上和他父的全家；又愿约押家不断有患漏症的，长大痲疯的，架拐而行的，被刀杀死的，缺乏饮食的。'),
('CUV', '撒母耳记下', 10, 3, 30, '约押和他兄弟亚比筛杀了押尼珥，是因押尼珥在基遍争战的时候杀了他们的兄弟亚撒黑。'),
('CUV', '撒母耳记下', 10, 3, 31, '大卫吩咐约押和跟随他的众人说：你们当撕裂衣服，腰束麻布，在押尼珥棺前哀哭。大卫王也跟在棺后。'),
('CUV', '撒母耳记下', 10, 3, 32, '他们将押尼珥葬在希伯仑。王在押尼珥的墓旁放声而哭，众民也都哭了。'),
('CUV', '撒母耳记下', 10, 3, 33, '王为押尼珥举哀，说：押尼珥何竟像愚顽人死呢？'),
('CUV', '撒母耳记下', 10, 3, 34, '你手未曾捆绑，脚未曾锁住。你死，如人死在罪孽之辈手下一样。于是众民又为押尼珥哀哭。'),
('CUV', '撒母耳记下', 10, 3, 35, '日头未落的时候，众民来劝大卫吃饭，但大卫起誓说：我若在日头未落以前吃饭，或吃别物，愿神重重地降罚与我！'),
('CUV', '撒母耳记下', 10, 3, 36, '众民知道了就都喜悦。凡王所行的，众民无不喜悦。'),
('CUV', '撒母耳记下', 10, 3, 37, '那日，以色列众民才知道杀尼珥的儿子押尼珥并非出于王意。'),
('CUV', '撒母耳记下', 10, 3, 38, '王对臣仆说：你们岂不知今日以色列人中死了一个作元帅的大丈夫么？'),
('CUV', '撒母耳记下', 10, 3, 39, '我虽然受膏为王，今日还是软弱；这洗鲁雅的两个儿子比我刚强。愿耶和华照著恶人所行的恶报应他。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记下', 10, 4, 1, '扫罗的儿子伊施波设听见押尼珥死在希伯仑，手就发软；以色列众人也都惊惶'),
('CUV', '撒母耳记下', 10, 4, 2, '扫罗的儿子伊施波设有两个军长，一名巴拿，一名利甲，是便雅悯支派、比录人临门的儿子。比录也属便雅悯。'),
('CUV', '撒母耳记下', 10, 4, 3, '比录人早先逃到基他音，在那里寄居，直到今日。'),
('CUV', '撒母耳记下', 10, 4, 4, '扫罗的儿子约拿单有一个儿子名叫米非波设，是瘸腿的。扫罗和约拿单死亡的消息从耶斯列传到的时候，他才五岁。他乳母抱著他逃跑；因为跑得太急，孩子掉在地上，腿就瘸了。'),
('CUV', '撒母耳记下', 10, 4, 5, '一日，比录人临门的两个儿子利甲和巴拿出去，约在午热的时候到了伊施波设的家；伊施波设正睡午觉。'),
('CUV', '撒母耳记下', 10, 4, 6, '他们进了房子，假作要取麦子，就刺透伊施波设的肚腹，逃跑了。'),
('CUV', '撒母耳记下', 10, 4, 7, '他们进房子的时候，伊施波设正在卧房里躺在床上，他们将他杀死，割了他的首级，拿著首级在亚拉巴走了一夜，'),
('CUV', '撒母耳记下', 10, 4, 8, '将伊施波设的首级拿到希伯仑见大卫王，说：王的仇敌扫罗曾寻索王的性命。看哪，这是他儿子伊施波设的首级；耶和华今日为我主我王在扫罗和他后裔的身上报了仇。'),
('CUV', '撒母耳记下', 10, 4, 9, '大卫对比录人临门的儿子利甲和他兄弟巴拿说：我指著救我性命脱离一切苦难、永生的耶和华起誓：'),
('CUV', '撒母耳记下', 10, 4, 10, '从前有人报告我说，扫罗死了，他自以为报好消息；我就拿住他，将他杀在洗革拉，这就作了他报消息的赏赐。'),
('CUV', '撒母耳记下', 10, 4, 11, '何况恶人将义人杀在他的床上，我岂不向你们讨流他血的罪、从世上除灭你们呢？'),
('CUV', '撒母耳记下', 10, 4, 12, '于是大卫吩咐少年人将他们杀了，砍断他们的手脚，挂在希伯仑的池旁，却将伊施波设的首级葬在希伯仑押尼珥的坟墓里。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记下', 10, 5, 1, '以色列众支派来到希伯仑见大卫，说：我们原是你的骨肉。'),
('CUV', '撒母耳记下', 10, 5, 2, '从前扫罗作我们王的时候，率领以色列人出入的是你；耶和华也曾应许你说：你必牧养我的民以色列，作以色列的君。'),
('CUV', '撒母耳记下', 10, 5, 3, '于是以色列的长老都来到希伯仑见大卫王，大卫在希伯仑耶和华面前与他们立约，他们就膏大卫作以色列的王。'),
('CUV', '撒母耳记下', 10, 5, 4, '大卫登基的时候年三十岁，在位四十年；'),
('CUV', '撒母耳记下', 10, 5, 5, '在希伯仑作犹大王七年零六个月，在耶路撒冷作以色列和犹大王三十三年。'),
('CUV', '撒母耳记下', 10, 5, 6, '大卫和跟随他的人到了耶路撒冷，要攻打住那地方的耶布斯人。耶布斯人对大卫说：你若不赶出瞎子、瘸子，必不能进这地方；心里想大卫决不能进去。'),
('CUV', '撒母耳记下', 10, 5, 7, '然而大卫攻取锡安的保障，就是大卫的城。'),
('CUV', '撒母耳记下', 10, 5, 8, '当日，大卫说：谁攻打耶布斯人，当上水沟攻打我心里所恨恶的瘸子、瞎子。从此有俗语说：在那里有瞎子、瘸子，他不能进屋去。'),
('CUV', '撒母耳记下', 10, 5, 9, '大卫住在保障里，给保障起名叫大卫城。大卫又从米罗以里，周围筑墙。'),
('CUV', '撒母耳记下', 10, 5, 10, '大卫日见强盛，因为耶和华─万军之神与他同在。'),
('CUV', '撒母耳记下', 10, 5, 11, '推罗王希兰将香柏木运到大卫那里，又差遣使者和木匠、石匠给大卫建造宫殿。'),
('CUV', '撒母耳记下', 10, 5, 12, '大卫就知道耶和华坚立他作以色列王，又为自己的民以色列使他的国兴旺。'),
('CUV', '撒母耳记下', 10, 5, 13, '大卫离开希伯仑之后，在耶路撒冷又立后妃，又生儿女。'),
('CUV', '撒母耳记下', 10, 5, 14, '在耶路撒冷所生的儿子是沙母亚、朔罢、拿单、所罗门、'),
('CUV', '撒母耳记下', 10, 5, 15, '益辖、以利书亚、尼斐、雅非亚、'),
('CUV', '撒母耳记下', 10, 5, 16, '以利沙玛、以利雅大、以利法列。'),
('CUV', '撒母耳记下', 10, 5, 17, '非利士人听见人膏大卫作以色列王，非利士人就上来寻索大卫；大卫听见，就下到保障。'),
('CUV', '撒母耳记下', 10, 5, 18, '非利士人来了，布散在利乏音谷。'),
('CUV', '撒母耳记下', 10, 5, 19, '大卫求问耶和华说：我可以上去攻打非利士人么？你将他们交在我手里么？耶和华说：你可以上去，我必将非利士人交在你手里。'),
('CUV', '撒母耳记下', 10, 5, 20, '大卫来到巴力毗拉心，在那里击杀非利士人，说：耶和华在我面前冲破敌人，如同水冲去一般。因此称那地方为巴力毗拉心。'),
('CUV', '撒母耳记下', 10, 5, 21, '非利士人将偶像撇在那里，大卫和跟随他的人拿去了。'),
('CUV', '撒母耳记下', 10, 5, 22, '非利士人又上来，布散在利乏音谷。'),
('CUV', '撒母耳记下', 10, 5, 23, '大卫求问耶和华；耶和华说：不要一直地上去，要转到他们后头，从桑林对面攻打他们。'),
('CUV', '撒母耳记下', 10, 5, 24, '你听见桑树梢上有脚步的声音，就要急速前去，因为那时耶和华已经在你前头去攻打非利士人的军队。'),
('CUV', '撒母耳记下', 10, 5, 25, '大卫就遵著耶和华所吩咐的去行，攻打非利士人，从迦巴直到基色。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记下', 10, 6, 1, '大卫又聚集以色列中所有挑选的人三万。'),
('CUV', '撒母耳记下', 10, 6, 2, '大卫起身，率领跟随他的众人前往，要从巴拉犹大将神的约柜运来；这约柜就是坐在二基路伯上万军之耶和华留名的约柜。'),
('CUV', '撒母耳记下', 10, 6, 3, '他们将神的约柜从冈上亚比拿达的家里抬出来，放在新车上；亚比拿达的两个儿子乌撒和亚希约赶这新车。'),
('CUV', '撒母耳记下', 10, 6, 4, '他们将神的约柜从冈上亚比拿达家里抬出来的时候，亚希约在柜前行走。'),
('CUV', '撒母耳记下', 10, 6, 5, '大卫和以色列的全家在耶和华面前，用松木制造的各样乐器和琴、瑟、鼓、钹、锣，作乐跳舞。'),
('CUV', '撒母耳记下', 10, 6, 6, '到了拿艮的禾场，因为牛失前蹄（或译：惊跳），乌撒就伸手扶住神的约柜。'),
('CUV', '撒母耳记下', 10, 6, 7, '神耶和华向乌撒发怒，因这错误击杀他，他就死在神的约柜旁。'),
('CUV', '撒母耳记下', 10, 6, 8, '大卫因耶和华击杀（原文是闯杀）乌撒，心里愁烦，就称那地方为毗列斯乌撒，直到今日。'),
('CUV', '撒母耳记下', 10, 6, 9, '那日，大卫惧怕耶和华，说：耶和华的约柜怎可运到我这里来？'),
('CUV', '撒母耳记下', 10, 6, 10, '于是大卫不肯将耶和华的约柜运进大卫的城，却运到迦特人俄别以东的家中。'),
('CUV', '撒母耳记下', 10, 6, 11, '耶和华的约柜在迦特人俄别以东家中三个月；耶和华赐福给俄别以东和他的全家。'),
('CUV', '撒母耳记下', 10, 6, 12, '有人告诉大卫王说：耶和华因为约柜赐福给俄别以东的家和一切属他的。大卫就去，欢欢喜喜地将神的约柜从俄别以东家中抬到大卫的城里。'),
('CUV', '撒母耳记下', 10, 6, 13, '抬耶和华约柜的人走了六步，大卫就献牛与肥羊为祭。'),
('CUV', '撒母耳记下', 10, 6, 14, '大卫穿著细麻布的以弗得，在耶和华面前极力跳舞。'),
('CUV', '撒母耳记下', 10, 6, 15, '这样，大卫和以色列的全家欢呼吹角，将耶和华的约柜抬上来。'),
('CUV', '撒母耳记下', 10, 6, 16, '耶和华的约柜进了大卫城的时候，扫罗的女儿米甲从窗户里观看，见大卫王在耶和华面前踊跃跳舞，心里就轻视他。'),
('CUV', '撒母耳记下', 10, 6, 17, '众人将耶和华的约柜请进去，安放在所预备的地方，就是在大卫所搭的帐幕里。大卫在耶和华面前献燔祭和平安祭。'),
('CUV', '撒母耳记下', 10, 6, 18, '大卫献完了燔祭和平安祭，就奉万军之耶和华的名给民祝福，'),
('CUV', '撒母耳记下', 10, 6, 19, '并且分给以色列众人，无论男女，每人一个饼，一块肉，一个葡萄饼；众人就各回各家去了。'),
('CUV', '撒母耳记下', 10, 6, 20, '大卫回家要给眷属祝福；扫罗的女儿米甲出来迎接他，说：以色列王今日在臣仆的婢女眼前露体，如同一个轻贱人无耻露体一样，有好大的荣耀啊！'),
('CUV', '撒母耳记下', 10, 6, 21, '大卫对米甲说：这是在耶和华面前；耶和华已拣选我，废了你父和你父的全家，立我作耶和华民以色列的君，所以我必在耶和华面前跳舞。'),
('CUV', '撒母耳记下', 10, 6, 22, '我也必更加卑微，自己看为轻贱。你所说的那些婢女，他们倒要尊敬我。'),
('CUV', '撒母耳记下', 10, 6, 23, '扫罗的女儿米甲，直到死日，没有生养儿女。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记下', 10, 7, 1, '王住在自己宫中，耶和华使他安靖，不被四围的仇敌扰乱。'),
('CUV', '撒母耳记下', 10, 7, 2, '那时，王对先知拿单说：看哪，我住在香柏木的宫中，神的约柜反在幔子里。'),
('CUV', '撒母耳记下', 10, 7, 3, '拿单对王说：你可以照你的心意而行，因为耶和华与你同在。'),
('CUV', '撒母耳记下', 10, 7, 4, '当夜，耶和华的话临到拿单说：'),
('CUV', '撒母耳记下', 10, 7, 5, '你去告诉我仆人大卫，说耶和华如此说：你岂可建造殿宇给我居住呢？'),
('CUV', '撒母耳记下', 10, 7, 6, '自从我领以色列人出埃及直到今日，我未曾住过殿宇，常在会幕和帐幕中行走。'),
('CUV', '撒母耳记下', 10, 7, 7, '凡我同以色列人所走的地方，我何曾向以色列一支派的士师，就是我吩咐牧养我民以色列的说：你们为何不给我建造香柏木的殿宇呢？'),
('CUV', '撒母耳记下', 10, 7, 8, '现在，你要告诉我仆人大卫，说万军之耶和华如此说：我从羊圈中将你召来，叫你不再跟从羊群，立你作我民以色列的君。'),
('CUV', '撒母耳记下', 10, 7, 9, '你无论往哪里去，我常与你同在，剪除你的一切仇敌。我必使你得大名，好像世上大大有名的人一样。'),
('CUV', '撒母耳记下', 10, 7, 10, '我必为我民以色列选定一个地方，栽培他们，使他们住自己的地方，不再迁移；凶恶之子也不像从前扰害他们，'),
('CUV', '撒母耳记下', 10, 7, 11, '并不像我命士师治理我民以色列的时候一样。我必使你安靖，不被一切仇敌扰乱，并且我─耶和华应许你，必为你建立家室。'),
('CUV', '撒母耳记下', 10, 7, 12, '你寿数满足、与你列祖同睡的时候，我必使你的后裔接续你的位；我也必坚定他的国。'),
('CUV', '撒母耳记下', 10, 7, 13, '他必为我的名建造殿宇；我必坚定他的国位，直到永远。'),
('CUV', '撒母耳记下', 10, 7, 14, '我要作他的父，他要作我的子；他若犯了罪，我必用人的杖责打他，用人的鞭责罚他。'),
('CUV', '撒母耳记下', 10, 7, 15, '但我的慈爱仍不离开他，像离开在你面前所废弃的扫罗一样。'),
('CUV', '撒母耳记下', 10, 7, 16, '你的家和你的国必在我（原文是你）面前永远坚立。你的国位也必坚定，直到永远。'),
('CUV', '撒母耳记下', 10, 7, 17, '拿单就按这一切话，照这默示，告诉大卫。'),
('CUV', '撒母耳记下', 10, 7, 18, '于是大卫王进去，坐在耶和华面前，说：主耶和华啊，我是谁？我的家算甚么？你竟使我到这地步呢？'),
('CUV', '撒母耳记下', 10, 7, 19, '主耶和华啊，这在你眼中还看为小，又应许你仆人的家至于久远。主耶和华啊，这岂是人所常遇的事么？'),
('CUV', '撒母耳记下', 10, 7, 20, '主耶和华啊，我还有何言可以对你说呢？因为你知道你的仆人。'),
('CUV', '撒母耳记下', 10, 7, 21, '你行这大事使仆人知道，是因你所应许的话，也是照你的心意。'),
('CUV', '撒母耳记下', 10, 7, 22, '主耶和华啊，你本为大，照我们耳中听见，没有可比你的；除你以外再无神。'),
('CUV', '撒母耳记下', 10, 7, 23, '世上有何民能比你的民以色列呢？你从埃及救赎他们作自己的子民，又在你赎出来的民面前行大而可畏的事，驱逐列邦人和他们的神，显出你的大名。'),
('CUV', '撒母耳记下', 10, 7, 24, '你曾坚立你的民以色列作你的子民，直到永远；你─耶和华也作了他们的神。'),
('CUV', '撒母耳记下', 10, 7, 25, '耶和华神啊，你所应许仆人和仆人家的话，求你坚定，直到永远；照你所说的而行。'),
('CUV', '撒母耳记下', 10, 7, 26, '愿人永远尊你的名为大，说：万军之耶和华是治理以色列的神。这样，你仆人大卫的家必在你面前坚立。'),
('CUV', '撒母耳记下', 10, 7, 27, '万军之耶和华─以色列的神啊，因你启示你的仆人说：我必为你建立家室，所以仆人大胆向你如此祈祷。'),
('CUV', '撒母耳记下', 10, 7, 28, '主耶和华啊，惟有你是神。你的话是真实的；你也应许将这福气赐给仆人。'),
('CUV', '撒母耳记下', 10, 7, 29, '现在求你赐福与仆人的家，可以永存在你面前。主耶和华啊，这是你所应许的。愿你永远赐福与仆人的家！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记下', 10, 8, 1, '此后，大卫攻打非利士人，把他们治服，从他们手下夺取了京城的权柄（原文是母城的嚼环）；'),
('CUV', '撒母耳记下', 10, 8, 2, '又攻打摩押人，使他们躺卧在地上，用绳量一量：量二绳的杀了，量一绳的存留。摩押人就归服大卫，给他进贡。'),
('CUV', '撒母耳记下', 10, 8, 3, '琐巴王利合的儿子哈大底谢往大河去，要夺回他的国权。大卫就攻打他，'),
('CUV', '撒母耳记下', 10, 8, 4, '擒拿了他的马兵一千七百，步兵二万，将拉战车的马砍断蹄筋，但留下一百辆车.的马。'),
('CUV', '撒母耳记下', 10, 8, 5, '大马色的亚兰人来帮助琐巴王哈大底谢，大卫就杀了亚兰人二万二千。'),
('CUV', '撒母耳记下', 10, 8, 6, '于是大卫在大马色的亚兰地设立防营，亚兰人就归服他，给他进贡。大卫无论往哪里去，耶和华都使他得胜。'),
('CUV', '撒母耳记下', 10, 8, 7, '他夺了哈大底谢臣仆所拿的金盾牌，带到耶路撒冷。'),
('CUV', '撒母耳记下', 10, 8, 8, '大卫王又从属哈大底谢的比他和比罗他城中夺取了许多的铜。'),
('CUV', '撒母耳记下', 10, 8, 9, '哈马王陀以听见大卫杀败哈大底谢的全军，'),
('CUV', '撒母耳记下', 10, 8, 10, '就打发他儿子约兰去见大卫王，问他的安，为他祝福，因为他杀败了哈大底谢（原来陀以与哈大底谢常常争战）。约兰带了金银铜的器皿来，'),
('CUV', '撒母耳记下', 10, 8, 11, '大卫王将这些器皿和他治服各国所得来的金银都分别为圣，献给耶和华，'),
('CUV', '撒母耳记下', 10, 8, 12, '就是从亚兰、摩押、亚扪、非利士、亚玛力人所得来的，以及从琐巴王利合的儿子哈大底谢所掠之物。'),
('CUV', '撒母耳记下', 10, 8, 13, '大卫在盐谷击杀了亚兰（或译：以东，见诗篇六十篇诗题）一万八千人回来，就得了大名；'),
('CUV', '撒母耳记下', 10, 8, 14, '又在以东全地设立防营，以东人就都归服大卫。大卫无论往哪里去，耶和华都使他得胜。'),
('CUV', '撒母耳记下', 10, 8, 15, '大卫作以色列众人的王，又向众民秉公行义。'),
('CUV', '撒母耳记下', 10, 8, 16, '洗鲁雅的儿子约押作元帅；亚希律的儿子约沙法作史官；'),
('CUV', '撒母耳记下', 10, 8, 17, '亚希突的儿子撒督和亚比亚他的儿子亚希米勒作祭司长；西莱雅作书记；'),
('CUV', '撒母耳记下', 10, 8, 18, '耶何耶大的儿子比拿雅统辖基利提人和比利提人。大卫的众子都作领袖。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记下', 10, 9, 1, '大卫问说：扫罗家还有剩下的人没有？我要因约拿单的缘故向他施恩。'),
('CUV', '撒母耳记下', 10, 9, 2, '扫罗家有一个仆人，名叫洗巴，有人叫他来见大卫，王问他说：你是洗巴么。回答说：仆人是。'),
('CUV', '撒母耳记下', 10, 9, 3, '王说：扫罗家还有人没有？我要照神的慈爱恩待他。洗巴对王说：还有约拿单的一个儿子，是瘸腿的。'),
('CUV', '撒母耳记下', 10, 9, 4, '王说：他在哪里？洗巴对王说：他在罗底巴，亚米利的儿子玛吉家里。'),
('CUV', '撒母耳记下', 10, 9, 5, '于是大卫王打发人去，从罗底巴亚米利的儿子玛吉家里召了他来。'),
('CUV', '撒母耳记下', 10, 9, 6, '扫罗的孙子、约拿单的儿子米非波设来见大卫，伏地叩拜。大卫说：米非波设！米非波设说：仆人在此。'),
('CUV', '撒母耳记下', 10, 9, 7, '大卫说：你不要惧怕，我必因你父亲约拿单的缘故施恩与你，将你祖父扫罗的一切田地都归还你；你也可以常与我同席吃饭。'),
('CUV', '撒母耳记下', 10, 9, 8, '米非波设又叩拜，说：仆人算甚么，不过如死狗一般，竟蒙王这样眷顾！'),
('CUV', '撒母耳记下', 10, 9, 9, '王召了扫罗的仆人洗巴来，对他说：我已将属扫罗和他的一切家产都赐给你主人的儿子了。'),
('CUV', '撒母耳记下', 10, 9, 10, '你和你的众子、仆人要为你主人的儿子米非波设耕种田地，把所产的拿来供他食用；他却要常与我同席吃饭。洗巴有十五个儿子，二十个仆人。'),
('CUV', '撒母耳记下', 10, 9, 11, '洗巴对王说：凡我主我王吩咐仆人的，仆人都必遵行。王又说：米非波设必与我同席吃饭，如王的儿子一样。'),
('CUV', '撒母耳记下', 10, 9, 12, '米非波设有一个小儿子，名叫米迦。凡住在洗巴家里的人都作了米非波设的仆人。'),
('CUV', '撒母耳记下', 10, 9, 13, '于是米非波设住在耶路撒冷，常与王同席吃饭。他两腿都是瘸的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记下', 10, 10, 1, '此后，亚扪人的王死了，他儿子哈嫩接续他作王。'),
('CUV', '撒母耳记下', 10, 10, 2, '大卫说：我要照哈嫩的父亲拿辖厚待我的恩典厚待哈嫩。于是大卫差遣臣仆，为他丧父安慰他。大卫的臣仆到了亚扪人的境内。'),
('CUV', '撒母耳记下', 10, 10, 3, '但亚扪人的首领对他们的主哈嫩说：大卫差人来安慰你，你想他是尊敬你父亲么？他差臣仆来不是详察窥探、要倾覆这城么？'),
('CUV', '撒母耳记下', 10, 10, 4, '哈嫩便将大卫臣仆的胡须剃去一半，又割断他们下半截的衣服，使他们露出下体，打发他们回去。'),
('CUV', '撒母耳记下', 10, 10, 5, '有人告诉大卫，他就差人去迎接他们，（因为他们甚觉羞耻），告诉他们说：可以住在耶利哥，等到胡须长起再回来。'),
('CUV', '撒母耳记下', 10, 10, 6, '亚扪人知道大卫憎恶他们，就打发人去，招募伯利合的亚兰人和琐巴的亚兰人，步兵二万，与玛迦王的人一千、陀伯人一万二千。'),
('CUV', '撒母耳记下', 10, 10, 7, '大卫听见了，就差派约押统带勇猛的全军出去。'),
('CUV', '撒母耳记下', 10, 10, 8, '亚扪人出来，在城门前摆阵；琐巴与利合的亚兰人、陀伯人，并玛迦人，另在郊野摆阵。'),
('CUV', '撒母耳记下', 10, 10, 9, '约押看见敌人在他前后摆阵，就从以色列军中挑选精兵，使他们对著亚兰人摆阵。'),
('CUV', '撒母耳记下', 10, 10, 10, '其余的兵交与他兄弟亚比筛，对著亚扪人摆阵。'),
('CUV', '撒母耳记下', 10, 10, 11, '约押对亚比筛说：亚兰人若强过我，你就来帮助我；亚扪人若强过你，我就去帮助你。'),
('CUV', '撒母耳记下', 10, 10, 12, '我们都当刚强，为本国的民和神的城邑作大丈夫。愿耶和华凭他的意旨而行！'),
('CUV', '撒母耳记下', 10, 10, 13, '于是，约押和跟随他的人前进攻打亚兰人；亚兰人在约押面前逃跑。'),
('CUV', '撒母耳记下', 10, 10, 14, '亚扪人见亚兰人逃跑，他们也在亚比筛面前逃跑进城。约押就离开亚扪人那里，回耶路撒冷去了。'),
('CUV', '撒母耳记下', 10, 10, 15, '亚兰人见自己被以色列人打败，就又聚集。'),
('CUV', '撒母耳记下', 10, 10, 16, '哈大底谢差遣人，将大河那边的亚兰人调来；他们到了希兰，哈大底谢的将军朔法率领他们。'),
('CUV', '撒母耳记下', 10, 10, 17, '有人告诉大卫，他就聚集以色列众人，过约但河，来到希兰。亚兰人迎著大卫摆阵，与他打仗。'),
('CUV', '撒母耳记下', 10, 10, 18, '亚兰人在以色列人面前逃跑；大卫杀了亚兰七百辆战车的人，四万马兵，又杀了亚兰的将军朔法。'),
('CUV', '撒母耳记下', 10, 10, 19, '属哈大底谢的诸王见自己被以色列人打败，就与以色列人和好，归服他们。于是亚兰人不敢再帮助亚扪人了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记下', 10, 11, 1, '过了一年，到列王出战的时候，大卫又差派约押，率领臣仆和以色列众人出战。他们就打败亚扪人，围攻拉巴。大卫仍住在耶路撒冷。'),
('CUV', '撒母耳记下', 10, 11, 2, '一日，太阳平西，大卫从床上起来，在王宫的平顶上游行，看见一个妇人沐浴，容貌甚美，'),
('CUV', '撒母耳记下', 10, 11, 3, '大卫就差人打听那妇人是谁。有人说：他是以连的女儿，赫人乌利亚的妻拔示巴。'),
('CUV', '撒母耳记下', 10, 11, 4, '大卫差人去，将妇人接来；那时他的月经才得洁净。他来了，大卫与他同房，他就回家去了。'),
('CUV', '撒母耳记下', 10, 11, 5, '于是他怀了孕，打发人去告诉大卫说：我怀了孕。'),
('CUV', '撒母耳记下', 10, 11, 6, '大卫差人到约押那里，说：你打发赫人乌利亚到我这里来。约押就打发乌利亚去见大卫。'),
('CUV', '撒母耳记下', 10, 11, 7, '乌利亚来了，大卫问约押好，也问兵好，又问争战的事怎样。'),
('CUV', '撒母耳记下', 10, 11, 8, '大卫对乌利亚说：你回家去，洗洗脚罢！乌利亚出了王宫，随后王送他一分食物。'),
('CUV', '撒母耳记下', 10, 11, 9, '乌利亚却和他主人的仆人一同睡在宫门外，没有回家去。'),
('CUV', '撒母耳记下', 10, 11, 10, '有人告诉大卫说：乌利亚没有回家去。大卫就问乌利亚说：你从远路上来，为甚么不回家去呢？'),
('CUV', '撒母耳记下', 10, 11, 11, '乌利亚对大卫说：约柜和以色列与犹大兵都住在棚里，我主约押和我主（或译：王）的仆人都在田野安营，我岂可回家吃喝、与妻子同寝呢？我敢在王面前起誓（原文是我指著王和王的性命起誓）：我决不行这事！'),
('CUV', '撒母耳记下', 10, 11, 12, '大卫吩咐乌利亚说：你今日仍住在这里，明日我打发你去。于是乌利亚那日和次日住在耶路撒冷。'),
('CUV', '撒母耳记下', 10, 11, 13, '大卫召了乌利亚来，叫他在自己面前吃喝，使他喝醉。到了晚上，乌利亚出去与他主的仆人一同住宿，还没有回到家里去。'),
('CUV', '撒母耳记下', 10, 11, 14, '次日早晨，大卫写信与约押，交乌利亚随手带去。'),
('CUV', '撒母耳记下', 10, 11, 15, '信内写著说：要派乌利亚前进，到阵势极险之处，你们便退后，使他被杀。'),
('CUV', '撒母耳记下', 10, 11, 16, '约押围城的时候，知道敌人那里有勇士，便将乌利亚派在那里。'),
('CUV', '撒母耳记下', 10, 11, 17, '城里的人出来和约押打仗；大卫的仆人中有几个被杀的，赫人乌利亚也死了。'),
('CUV', '撒母耳记下', 10, 11, 18, '于是，约押差人去将争战的一切事告诉大卫，'),
('CUV', '撒母耳记下', 10, 11, 19, '又嘱咐使者说：你把争战的一切事对王说完了，'),
('CUV', '撒母耳记下', 10, 11, 20, '王若发怒，问你说：你们打仗为甚么挨近城墙呢？岂不知敌人必从城上射箭么？'),
('CUV', '撒母耳记下', 10, 11, 21, '从前打死耶路比设（就是耶路巴力，见士师记九章一节）儿子亚比米勒的是谁呢？岂不是一个妇人从城上抛下一块上磨石来，打在他身上，他就死在提备斯么？你们为甚么挨近城墙呢？你就说：王的仆人─赫人乌利亚也死了。'),
('CUV', '撒母耳记下', 10, 11, 22, '使者起身，来见大卫，照著约押所吩咐他的话奏告大卫。'),
('CUV', '撒母耳记下', 10, 11, 23, '使者对大卫说：敌人强过我们，出到郊野与我们打仗，我们追杀他们，直到城门口。'),
('CUV', '撒母耳记下', 10, 11, 24, '射箭的从城上射王的仆人，射死几个，赫人乌利亚也死了。'),
('CUV', '撒母耳记下', 10, 11, 25, '王向使者说：你告诉约押说：不要因这事愁闷，刀剑或吞灭这人或吞灭那人，没有一定的；你只管竭力攻城，将城倾覆。可以用这话勉励约押。'),
('CUV', '撒母耳记下', 10, 11, 26, '乌利亚的妻听见丈夫乌利亚死了，就为他哀哭。'),
('CUV', '撒母耳记下', 10, 11, 27, '哀哭的日子过了，大卫差人将他接到宫里，他就作了大卫的妻，给大卫生了一个儿子。但大卫所行的这事，耶和华甚不喜悦。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记下', 10, 12, 1, '耶和华差遣拿单去见大卫。拿单到了大卫那里，对他说：在一座城里有两个人：一个是富户，一个是穷人。'),
('CUV', '撒母耳记下', 10, 12, 2, '富户有许多牛群羊群；'),
('CUV', '撒母耳记下', 10, 12, 3, '穷人除了所买来养活的一只小母羊羔之外，别无所有。羊羔在他家里和他儿女一同长大，吃他所吃的，喝他所喝的，睡在他怀中，在他看来如同女儿一样。'),
('CUV', '撒母耳记下', 10, 12, 4, '有一客人来到这富户家里；富户舍不得从自己的牛群羊群中取一只预备给客人吃，却取了那穷人的羊羔，预备给客人吃。'),
('CUV', '撒母耳记下', 10, 12, 5, '大卫就甚恼怒那人，对拿单说：我指著永生的耶和华起誓，行这事的人该死！'),
('CUV', '撒母耳记下', 10, 12, 6, '他必偿还羊羔四倍；因为他行这事，没有怜恤的心。'),
('CUV', '撒母耳记下', 10, 12, 7, '拿单对大卫说：你就是那人！耶和华─以色列的神如此说：我膏你作以色列的王，救你脱离扫罗的手。'),
('CUV', '撒母耳记下', 10, 12, 8, '我将你主人的家业赐给你，将你主人的妻交在你怀里，又将以色列和犹大家赐给你；你若还以为不足，我早就加倍地赐给你。'),
('CUV', '撒母耳记下', 10, 12, 9, '你为甚么藐视耶和华的命令，行他眼中看为恶的事呢？你借亚扪人的刀杀害赫人乌利亚，又娶了他的妻为妻。'),
('CUV', '撒母耳记下', 10, 12, 10, '你既藐视我，娶了赫人乌利亚的妻为妻，所以刀剑必永不离开你的家。'),
('CUV', '撒母耳记下', 10, 12, 11, '耶和华如此说：我必从你家中兴起祸患攻击你；我必在你眼前把你的妃嫔赐给别人，他在日光之下就与他们同寝。'),
('CUV', '撒母耳记下', 10, 12, 12, '你在暗中行这事，我却要在以色列众人面前，日光之下，报应你。'),
('CUV', '撒母耳记下', 10, 12, 13, '大卫对拿单说：我得罪耶和华了！拿单说：耶和华已经除掉你的罪，你必不至于死。'),
('CUV', '撒母耳记下', 10, 12, 14, '只是你行这事，叫耶和华的仇敌大得亵渎的机会，故此，你所得的孩子必定要死。'),
('CUV', '撒母耳记下', 10, 12, 15, '拿单就回家去了。耶和华击打乌利亚妻给大卫所生的孩子，使他得重病。'),
('CUV', '撒母耳记下', 10, 12, 16, '所以大卫为这孩子恳求神，而且禁食，进入内室，终夜躺在地上。'),
('CUV', '撒母耳记下', 10, 12, 17, '他家中的老臣来到他旁边，要把他从地上扶起来，他却不肯起来，也不同他们吃饭。'),
('CUV', '撒母耳记下', 10, 12, 18, '到第七日，孩子死了。大卫的臣仆不敢告诉他孩子死了，因他们说：孩子还活著的时候，我们劝他，他尚且不肯听我们的话，若告诉他孩子死了，岂不更加忧伤么？'),
('CUV', '撒母耳记下', 10, 12, 19, '大卫见臣仆彼此低声说话，就知道孩子死了，问臣仆说：孩子死了么？他们说：死了。'),
('CUV', '撒母耳记下', 10, 12, 20, '大卫就从地上起来，沐浴，抹膏，换了衣裳，进耶和华的殿敬拜；然后回宫，吩咐人摆饭，他便吃了。'),
('CUV', '撒母耳记下', 10, 12, 21, '臣仆问他说：你所行的是甚么意思？孩子活著的时候，你禁食哭泣；孩子死了，你倒起来吃饭。'),
('CUV', '撒母耳记下', 10, 12, 22, '大卫说：孩子还活著，我禁食哭泣；因为我想，或者耶和华怜恤我，使孩子不死也未可知。'),
('CUV', '撒母耳记下', 10, 12, 23, '孩子死了，我何必禁食，我岂能使他返回呢？我必往他那里去，他却不能回我这里来。'),
('CUV', '撒母耳记下', 10, 12, 24, '大卫安慰他的妻拔示巴，与他同寝，他就生了儿子，给他起名叫所罗门。耶和华也喜爱他，'),
('CUV', '撒母耳记下', 10, 12, 25, '就藉先知拿单赐他一个名字，叫耶底底亚，因为耶和华爱他。'),
('CUV', '撒母耳记下', 10, 12, 26, '约押攻取亚扪人的京城拉巴。'),
('CUV', '撒母耳记下', 10, 12, 27, '约押打发使者去见大卫，说：我攻打拉巴，取其水城。'),
('CUV', '撒母耳记下', 10, 12, 28, '现在你要聚集其余的军兵来，安营围攻这城，恐怕我取了这城，人就以我的名叫这城。'),
('CUV', '撒母耳记下', 10, 12, 29, '于是大卫聚集众军，往拉巴去攻城，就取了这城，'),
('CUV', '撒母耳记下', 10, 12, 30, '夺了亚扪人之王所戴的金冠冕（王：或译玛勒堪；玛勒堪就是米勒公，又名摩洛，亚扪族之神名），其上的金子重一他连得，又嵌著宝石。人将这冠冕戴在大卫头上。大卫从城里夺了许多财物，'),
('CUV', '撒母耳记下', 10, 12, 31, '将城里的人拉出来，放在锯下，或铁耙下，或铁斧下，或叫他经过砖窑（或译：强他们用锯，或用打粮食的铁器，或用铁斧做工，或使在砖窑里服役）；大卫待亚扪各城的居民都是如此。其后，大卫和众军都回耶路撒冷去了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记下', 10, 13, 1, '大卫的儿子押沙龙有一个美貌的妹子，名叫他玛。大卫的儿子暗嫩爱他。'),
('CUV', '撒母耳记下', 10, 13, 2, '暗嫩为他妹子他玛忧急成病。他玛还是处女，暗嫩以为难向他行事。'),
('CUV', '撒母耳记下', 10, 13, 3, '暗嫩有一个朋友，名叫约拿达，是大卫长兄示米亚的儿子。这约拿达为人极其狡猾。'),
('CUV', '撒母耳记下', 10, 13, 4, '他问暗嫩说：王的儿子啊，为何一天比一天瘦弱呢？请你告诉我。暗嫩回答说：我爱我兄弟押沙龙的妹子他玛。'),
('CUV', '撒母耳记下', 10, 13, 5, '约拿达说：你不如躺在床上装病；你父亲来看你，就对他说：求父叫我妹子他玛来，在我眼前预备食物，递给我吃，使我看见，好从他手里接过来吃。'),
('CUV', '撒母耳记下', 10, 13, 6, '于是暗嫩躺卧装病。王来看他，他对王说：求父叫我妹子他玛来，在我眼前为我做两个饼，我好从他手里接过来吃。'),
('CUV', '撒母耳记下', 10, 13, 7, '大卫就打发人到宫里，对他玛说：你往你哥哥暗嫩的屋里去，为他预备食物。'),
('CUV', '撒母耳记下', 10, 13, 8, '他玛就到他哥哥暗嫩的屋里；暗嫩正躺卧。他玛抟面，在他眼前做饼，且烤熟了，'),
('CUV', '撒母耳记下', 10, 13, 9, '在他面前将饼从锅里倒出来，他却不肯吃，便说：众人离开我出去罢！众人就都离开他，出去了。'),
('CUV', '撒母耳记下', 10, 13, 10, '暗嫩对他玛说：你把食物拿进卧房，我好从你手里接过来吃。他玛就把所做的饼拿进卧房，到他哥哥暗嫩那里，'),
('CUV', '撒母耳记下', 10, 13, 11, '拿著饼上前给他吃，他便拉住他玛，说：我妹妹，你来与我同寝。'),
('CUV', '撒母耳记下', 10, 13, 12, '他玛说：我哥哥，不要玷辱我。以色列人中不当这样行，你不要做这丑事；'),
('CUV', '撒母耳记下', 10, 13, 13, '你玷辱了我，我何以掩盖我的羞耻呢？你在以色列中也成了愚妄人。你可以求王，他必不禁止我归你。'),
('CUV', '撒母耳记下', 10, 13, 14, '但暗嫩不肯听他的话，因比他力大，就玷辱他，与他同寝。'),
('CUV', '撒母耳记下', 10, 13, 15, '随后，暗嫩极其恨他，那恨他的心比先前爱他的心更甚，对他说：你起来，去罢！'),
('CUV', '撒母耳记下', 10, 13, 16, '他玛说：不要这样！你赶出我去的这罪比你才行的更重！但暗嫩不肯听他的话，'),
('CUV', '撒母耳记下', 10, 13, 17, '就叫伺候自己的仆人来，说：将这个女子赶出去！他一出去，你就关门，上闩。'),
('CUV', '撒母耳记下', 10, 13, 18, '那时他玛穿著彩衣，因为没有出嫁的公主都是这样穿。暗嫩的仆人就把他赶出去，关门上闩。'),
('CUV', '撒母耳记下', 10, 13, 19, '他玛把灰尘撒在头上，撕裂所穿的彩衣，以手抱头，一面行走，一面哭喊。'),
('CUV', '撒母耳记下', 10, 13, 20, '他胞兄押沙龙问他说：莫非你哥哥暗嫩与你亲近了么？我妹妹，暂且不要作声，他是你的哥哥，不要将这事放在心上。他玛就孤孤单单地住在他胞兄押沙龙家里。'),
('CUV', '撒母耳记下', 10, 13, 21, '大卫王听见这事，就甚发怒。'),
('CUV', '撒母耳记下', 10, 13, 22, '押沙龙并不和他哥哥暗嫩说好说歹；因为暗嫩玷辱他妹妹他玛，所以押沙龙恨恶他。'),
('CUV', '撒母耳记下', 10, 13, 23, '过了二年，在靠近以法莲的巴力夏琐有人为押沙龙剪羊毛；押沙龙请王的众子与他同去。'),
('CUV', '撒母耳记下', 10, 13, 24, '押沙龙来见王，说：现在有人为仆人剪羊毛，请王和王的臣仆与仆人同去。'),
('CUV', '撒母耳记下', 10, 13, 25, '王对押沙龙说：我儿，我们不必都去，恐怕使你耗费太多。押沙龙再三请王，王仍是不肯去，只为他祝福。'),
('CUV', '撒母耳记下', 10, 13, 26, '押沙龙说：王若不去，求王许我哥哥暗嫩同去。王说：何必要他去呢？'),
('CUV', '撒母耳记下', 10, 13, 27, '押沙龙再三求王，王就许暗嫩和王的众子与他同去。'),
('CUV', '撒母耳记下', 10, 13, 28, '押沙龙吩咐仆人说：你们注意，看暗嫩饮酒畅快的时候，我对你们说杀暗嫩，你们便杀他，不要惧怕。这不是我吩咐你们的么？你们只管壮胆奋勇！'),
('CUV', '撒母耳记下', 10, 13, 29, '押沙龙的仆人就照押沙龙所吩咐的，向暗嫩行了。王的众子都起来，各人骑上骡子，逃跑了。'),
('CUV', '撒母耳记下', 10, 13, 30, '他们还在路上，有风声传到大卫那里，说：押沙龙将王的众子都杀了，没有留下一个。'),
('CUV', '撒母耳记下', 10, 13, 31, '王就起来，撕裂衣服，躺在地上。王的臣仆也都撕裂衣服，站在旁边。'),
('CUV', '撒母耳记下', 10, 13, 32, '大卫的长兄，示米亚的儿子约拿达说：我主，不要以为王的众子─少年人都杀了，只有暗嫩一个人死了。自从暗嫩玷辱押沙龙妹子他玛的那日，押沙龙就定意杀暗嫩了。'),
('CUV', '撒母耳记下', 10, 13, 33, '现在，我主我王，不要把这事放在心上，以为王的众子都死了，只有暗嫩一个人死了。'),
('CUV', '撒母耳记下', 10, 13, 34, '押沙龙逃跑了。守望的少年人举目观看，见有许多人从山坡的路上来。'),
('CUV', '撒母耳记下', 10, 13, 35, '约拿达对王说：看哪，王的众子都来了，果然与你仆人所说的相合。'),
('CUV', '撒母耳记下', 10, 13, 36, '话才说完，王的众子都到了，放声大哭。王和臣仆也都哭得甚恸。'),
('CUV', '撒母耳记下', 10, 13, 37, '押沙龙逃到基述王亚米忽的儿子达买那里去了。大卫天天为他儿子悲哀。'),
('CUV', '撒母耳记下', 10, 13, 38, '押沙龙逃到基述，在那里住了三年。'),
('CUV', '撒母耳记下', 10, 13, 39, '暗嫩死了以后，大卫王得了安慰，心里切切想念押沙龙。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记下', 10, 14, 1, '洗鲁雅的儿子约押，知道王心里想念押沙龙，'),
('CUV', '撒母耳记下', 10, 14, 2, '就打发人往提哥亚去，从那里叫了一个聪明的妇人来，对他说：请你假装居丧的，穿上孝衣，不要用膏抹身，要装作为死者许久悲哀的妇人；'),
('CUV', '撒母耳记下', 10, 14, 3, '进去见王，对王如此如此说。于是约押将当说的话教导了妇人。'),
('CUV', '撒母耳记下', 10, 14, 4, '提哥亚妇人到王面前，伏地叩拜，说：王啊，求你拯救！'),
('CUV', '撒母耳记下', 10, 14, 5, '王问他说：你有甚么事呢？回答说：婢女实在是寡妇，我丈夫死了。'),
('CUV', '撒母耳记下', 10, 14, 6, '我有两个儿子，一日在田间争斗，没有人解劝，这个就打死那个。'),
('CUV', '撒母耳记下', 10, 14, 7, '现在全家的人都起来攻击婢女，说：你将那打死兄弟的交出来，我们好治死他，偿他打死兄弟的命，灭绝那承受家业的。这样，他们要将我剩下的炭火灭尽，不与我丈夫留名留后在世上。'),
('CUV', '撒母耳记下', 10, 14, 8, '王对妇人说：你回家去罢！我必为你下令。'),
('CUV', '撒母耳记下', 10, 14, 9, '提哥亚妇人又对王说：我主我王，愿这罪归我和我父家，与王和王的位无干。'),
('CUV', '撒母耳记下', 10, 14, 10, '王说：凡难为你的，你就带他到我这里来，他必不再搅扰你。'),
('CUV', '撒母耳记下', 10, 14, 11, '妇人说：愿王记念耶和华─你的神，不许报血仇的人施行灭绝，恐怕他们灭绝我的儿子。王说：我指著永生的耶和华起誓：你的儿子连一根头发也不致落在地上。'),
('CUV', '撒母耳记下', 10, 14, 12, '妇人说：求我主我王容婢女再说一句话。王说：你说罢！'),
('CUV', '撒母耳记下', 10, 14, 13, '妇人说：王为何也起意要害神的民呢？王不使那逃亡的人回来，王的这话就是自证己错了！'),
('CUV', '撒母耳记下', 10, 14, 14, '我们都是必死的，如同水泼在地上，不能收回。神并不夺取人的性命，乃设法使逃亡的人不致成为赶出、回不来的。'),
('CUV', '撒母耳记下', 10, 14, 15, '我来将这话告诉我主我王，是因百姓使我惧怕。婢女想，不如将这话告诉王，或者王成就婢女所求的。'),
('CUV', '撒母耳记下', 10, 14, 16, '人要将我和我儿子从神的地业上一同除灭，王必应允救我脱离他的手。'),
('CUV', '撒母耳记下', 10, 14, 17, '婢女又想，我主我王的话必安慰我；因为我主我王能辨别是非，如同神的使者一样。惟愿耶和华─你的神与你同在！'),
('CUV', '撒母耳记下', 10, 14, 18, '王对妇人说：我要问你一句话，你一点不要瞒我。妇人说：愿我主我王说。'),
('CUV', '撒母耳记下', 10, 14, 19, '王说：你这些话莫非是约押的主意么？妇人说：我敢在我主我王面前起誓：王的话正对，不偏左右，是王的仆人约押吩咐我的，这些话是他教导我的。'),
('CUV', '撒母耳记下', 10, 14, 20, '王的仆人约押如此行，为要挽回这事。我主的智慧却如神使者的智慧，能知世上一切事。'),
('CUV', '撒母耳记下', 10, 14, 21, '王对约押说：我应允你这事。你可以去，把那少年人押沙龙带回来。'),
('CUV', '撒母耳记下', 10, 14, 22, '约押就面伏于地叩拜，祝谢于王，又说：王既应允仆人所求的，仆人今日知道在我主我王眼前蒙恩了。'),
('CUV', '撒母耳记下', 10, 14, 23, '于是约押起身往基述去，将押沙龙带回耶路撒冷。'),
('CUV', '撒母耳记下', 10, 14, 24, '王说：使他回自己家里去，不要见我的面。押沙龙就回自己家里去，没有见王的面。'),
('CUV', '撒母耳记下', 10, 14, 25, '以色列全地之中，无人像押沙龙那样俊美，得人的称赞，从脚底到头顶毫无暇疵。'),
('CUV', '撒母耳记下', 10, 14, 26, '他的头发甚重，每到年底剪发一次；所剪下来的，按王的平称一称，重二百舍客勒。'),
('CUV', '撒母耳记下', 10, 14, 27, '押沙龙生了三个儿子，一个女儿。女儿名叫他玛，是个容貌俊美的女子。'),
('CUV', '撒母耳记下', 10, 14, 28, '押沙龙住在耶路撒冷足有二年，没有见王的面。'),
('CUV', '撒母耳记下', 10, 14, 29, '押沙龙打发人去叫约押来，要托他去见王，约押却不肯来。第二次打发人去叫他，他仍不肯来。'),
('CUV', '撒母耳记下', 10, 14, 30, '所以押沙龙对仆人说：你们看，约押有一块田，与我的田相近，其中有大麦，你们去放火烧了。押沙龙的仆人就去放火烧了那田。'),
('CUV', '撒母耳记下', 10, 14, 31, '于是约押起来，到了押沙龙家里，问他说：你的仆人为何放火烧了我的田呢？'),
('CUV', '撒母耳记下', 10, 14, 32, '押沙龙回答约押说：我打发人去请你来，好托你去见王，替我说：我为何从基述回来呢？不如仍在那里。现在要许我见王的面；我若有罪，任凭王杀我就是了。'),
('CUV', '撒母耳记下', 10, 14, 33, '于是约押去见王，将这话奏告王，王便叫押沙龙来。押沙龙来见王，在王面前俯伏于地，王就与押沙龙亲嘴。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记下', 10, 15, 1, '此后，押沙龙为自己预备车马，又派五十人在他前头奔走。'),
('CUV', '撒母耳记下', 10, 15, 2, '押沙龙常常早晨起来，站在城门的道旁，凡有争讼要去求王判断的，押沙龙就叫他过来，问他说：你是哪一城的人？回答说：仆人是以色列某支派的人。'),
('CUV', '撒母耳记下', 10, 15, 3, '押沙龙对他说：你的事有情有理，无奈王没有委人听你伸诉。'),
('CUV', '撒母耳记下', 10, 15, 4, '押沙龙又说：恨不得我作国中的士师！凡有争讼求审判的到我这里来，我必秉公判断。'),
('CUV', '撒母耳记下', 10, 15, 5, '若有人近前来要拜押沙龙，押沙龙就伸手拉住他，与他亲嘴。'),
('CUV', '撒母耳记下', 10, 15, 6, '以色列人中，凡去见王求判断的，押沙龙都是如此待他们。这样，押沙龙暗中得了以色列人的心。'),
('CUV', '撒母耳记下', 10, 15, 7, '满了四十年（有作四年的），押沙龙对王说：求你准我往希伯仑去，还我向耶和华所许的愿。'),
('CUV', '撒母耳记下', 10, 15, 8, '因为仆人住在亚兰的基述，曾许愿说：耶和华若使我再回耶路撒冷，我必事奉他。'),
('CUV', '撒母耳记下', 10, 15, 9, '王说：你平平安安地去罢！押沙龙就起身，往希伯仑去了。'),
('CUV', '撒母耳记下', 10, 15, 10, '押沙龙打发探子走遍以色列各支派，说：你们一听见角声就说：押沙龙在希伯仑作王了！'),
('CUV', '撒母耳记下', 10, 15, 11, '押沙龙在耶路撒冷请了二百人与他同去，都是诚诚实实去的，并不知道其中的真情。'),
('CUV', '撒母耳记下', 10, 15, 12, '押沙龙献祭的时候，打发人去将大卫的谋士、基罗人亚希多弗从他本城请了来。于是叛逆的势派甚大；因为随从押沙龙的人民，日渐增多。'),
('CUV', '撒母耳记下', 10, 15, 13, '有人报告大卫说：以色列人的心都归向押沙龙了！'),
('CUV', '撒母耳记下', 10, 15, 14, '大卫就对耶路撒冷跟随他的臣仆说：我们要起来逃走，不然都不能躲避押沙龙了；要速速地去，恐怕他忽然来到，加害于我们，用刀杀尽合城的人。'),
('CUV', '撒母耳记下', 10, 15, 15, '王的臣仆对王说：我主我王所定的，仆人都愿遵行。'),
('CUV', '撒母耳记下', 10, 15, 16, '于是王带著全家的人出去了，但留下十个妃嫔看守宫殿。'),
('CUV', '撒母耳记下', 10, 15, 17, '王出去，众民都跟随他，到伯墨哈，就住下了。'),
('CUV', '撒母耳记下', 10, 15, 18, '王的臣仆都在他面前过去。基利提人、比利提人，就是从迦特跟随王来的六百人，也都在他面前过去。'),
('CUV', '撒母耳记下', 10, 15, 19, '王对迦特人以太说：你是外邦逃来的人，为甚么与我们同去呢？你可以回去与新王同住，或者回你本地去罢！'),
('CUV', '撒母耳记下', 10, 15, 20, '你来的日子不多，我今日怎好叫你与我们一同飘流、没有一定的住处呢？你不如带你的弟兄回去罢！愿耶和华用慈爱诚实待你。'),
('CUV', '撒母耳记下', 10, 15, 21, '以太对王说：我指著永生的耶和华起誓，又敢在王面前起誓：无论生死，王在哪里，仆人也必在那里。'),
('CUV', '撒母耳记下', 10, 15, 22, '大卫对以太说：你前去过河罢！于是迦特人以太带著跟随他的人和所有的妇人孩子，就都过去了。'),
('CUV', '撒母耳记下', 10, 15, 23, '本地的人都放声大哭。众民尽都过去，王也过了汲沦溪；众民往旷野去了。'),
('CUV', '撒母耳记下', 10, 15, 24, '撒督和抬神约柜的利未人也一同来了，将神的约柜放下。亚比亚他上来，等著众民从城里出来过去。'),
('CUV', '撒母耳记下', 10, 15, 25, '王对撒督说：你将神的约柜抬回城去。我若在耶和华眼前蒙恩，他必使我回来，再见约柜和他的居所。'),
('CUV', '撒母耳记下', 10, 15, 26, '倘若他说：我不喜悦你，看哪，我在这里，愿他凭自己的意旨待我！'),
('CUV', '撒母耳记下', 10, 15, 27, '王又对祭司撒督说：你不是先见么？你可以安然回城；你儿子亚希玛斯和亚比亚他的儿子约拿单都可以与你同去。'),
('CUV', '撒母耳记下', 10, 15, 28, '我在旷野的渡口那里等你们报信给我。'),
('CUV', '撒母耳记下', 10, 15, 29, '于是撒督和亚比亚他将神的约柜抬回耶路撒冷，他们就住在那里。'),
('CUV', '撒母耳记下', 10, 15, 30, '大卫蒙头赤脚上橄榄山，一面上一面哭。跟随他的人也都蒙头哭著上去；'),
('CUV', '撒母耳记下', 10, 15, 31, '有人告诉大卫说：亚希多弗也在叛党之中，随从押沙龙。大卫祷告说：耶和华啊，求你使亚希多弗的计谋变为愚拙！'),
('CUV', '撒母耳记下', 10, 15, 32, '大卫到了山顶、敬拜神的地方，见亚基人户筛，衣服撕裂，头蒙灰尘来迎接他。'),
('CUV', '撒母耳记下', 10, 15, 33, '大卫对他说：你若与我同去，必累赘我；'),
('CUV', '撒母耳记下', 10, 15, 34, '你若回城去，对押沙龙说：王啊，我愿作你的仆人；我向来作你父亲的仆人，现在我也照样作你的仆人。这样，你就可以为我破坏亚希多弗的计谋。'),
('CUV', '撒母耳记下', 10, 15, 35, '祭司撒督和亚比亚他岂不都在那里么？你在王宫里听见甚么，就要告诉祭司撒督和亚比亚他。'),
('CUV', '撒母耳记下', 10, 15, 36, '撒督的儿子亚希玛斯，亚比亚他的儿子约拿单，也都在那里。凡你们所听见的可以托这二人来报告我。'),
('CUV', '撒母耳记下', 10, 15, 37, '于是，大卫的朋友户筛进了城；押沙龙也进了耶路撒冷。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记下', 10, 16, 1, '大卫刚过山顶，见米非波设的仆人洗巴拉著备好了的两匹驴，驴上驮著二百面饼，一百葡萄饼，一百个夏天的果饼，一皮袋酒来迎接他。'),
('CUV', '撒母耳记下', 10, 16, 2, '王问洗巴说：你带这些来是甚么意思呢？洗巴说：驴是给王的家眷骑的；面饼和夏天的果饼是给少年人吃的；酒是给在旷野疲乏人喝的。'),
('CUV', '撒母耳记下', 10, 16, 3, '王问说：你主人的儿子在哪里呢？洗巴回答王说：他仍在耶路撒冷，因他说：以色列人今日必将我父的国归还我。'),
('CUV', '撒母耳记下', 10, 16, 4, '王对洗巴说：凡属米非波设的都归你了。洗巴说：我叩拜我主我王，愿我在你眼前蒙恩。'),
('CUV', '撒母耳记下', 10, 16, 5, '大卫王到了巴户琳，见有一个人出来，是扫罗族基拉的儿子，名叫示每。他一面走一面咒骂，'),
('CUV', '撒母耳记下', 10, 16, 6, '又拿石头砍大卫王和王的臣仆；众民和勇士都在王的左右。'),
('CUV', '撒母耳记下', 10, 16, 7, '示每咒骂说：你这流人血的坏人哪，去罢去罢！'),
('CUV', '撒母耳记下', 10, 16, 8, '你流扫罗全家的血，接续他作王；耶和华把这罪归在你身上，将这国交给你儿子押沙龙。现在你自取其祸，因为你是流人血的人。'),
('CUV', '撒母耳记下', 10, 16, 9, '洗鲁雅的儿子亚比筛对王说：这死狗岂可咒骂我主我王呢？求你容我过去，割下他的头来。'),
('CUV', '撒母耳记下', 10, 16, 10, '王说：洗鲁雅的儿子，我与你们有何关涉呢？他咒骂是因耶和华吩咐他说：你要咒骂大卫。如此，谁敢说你为甚么这样行呢？'),
('CUV', '撒母耳记下', 10, 16, 11, '大卫又对亚比筛和众臣仆说：我亲生的儿子尚且寻索我的性命，何况这便雅悯人呢？由他咒骂罢！因为这是耶和华吩咐他的。'),
('CUV', '撒母耳记下', 10, 16, 12, '或者耶和华见我遭难，为我今日被这人咒骂，就施恩与我。'),
('CUV', '撒母耳记下', 10, 16, 13, '于是大卫和跟随他的人往前行走。示每在大卫对面山坡，一面行走一面咒骂，又拿石头砍他，拿土扬他。'),
('CUV', '撒母耳记下', 10, 16, 14, '王和跟随他的众人疲疲乏乏地到了一个地方，就在那里歇息歇息。'),
('CUV', '撒母耳记下', 10, 16, 15, '押沙龙和以色列众人来到耶路撒冷；亚希多弗也与他同来。'),
('CUV', '撒母耳记下', 10, 16, 16, '大卫的朋友亚基人户筛去见押沙龙，对他说：愿王万岁！愿王万岁！'),
('CUV', '撒母耳记下', 10, 16, 17, '押沙龙问户筛说：这是你恩待朋友么？为甚么不与你的朋友同去呢？'),
('CUV', '撒母耳记下', 10, 16, 18, '户筛对押沙龙说：不然，耶和华和这民，并以色列众人所拣选的，我必归顺他，与他同住。'),
('CUV', '撒母耳记下', 10, 16, 19, '再者，我当服事谁呢？岂不是前王的儿子么？我怎样服事你父亲，也必照样服事你。'),
('CUV', '撒母耳记下', 10, 16, 20, '押沙龙对亚希多弗说：你们出个主意，我们怎样行才好？'),
('CUV', '撒母耳记下', 10, 16, 21, '亚希多弗对押沙龙说：你父所留下看守宫殿的妃嫔，你可以与他们亲近。以色列众人听见你父亲憎恶你，凡归顺你人的手就更坚强。'),
('CUV', '撒母耳记下', 10, 16, 22, '于是人为押沙龙在宫殿的平顶上支搭帐棚；押沙龙在以色列众人眼前，与他父的妃嫔亲近。'),
('CUV', '撒母耳记下', 10, 16, 23, '那时亚希多弗所出的主意好像人问神的话一样；他昔日给大卫，今日给押沙龙所出的主意，都是这样。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记下', 10, 17, 1, '亚希多弗又对押沙龙说：求你准我挑选一万二千人，今夜我就起身追赶大卫，'),
('CUV', '撒母耳记下', 10, 17, 2, '趁他疲乏手软，我忽然追上他，使他惊惶；跟随他的民必都逃跑，我就单杀王一人，'),
('CUV', '撒母耳记下', 10, 17, 3, '使众民都归顺你。你所寻找的人既然死了，众民就如已经归顺你；这样，也都平安无事了。'),
('CUV', '撒母耳记下', 10, 17, 4, '押沙龙和以色列的长老都以这话为美。'),
('CUV', '撒母耳记下', 10, 17, 5, '押沙龙说：要召亚基人户筛来，我们也要听他怎样说。'),
('CUV', '撒母耳记下', 10, 17, 6, '户筛到了押沙龙面前，押沙龙向他说：亚希多弗是如此如此说的，我们照著他的话行可以不可以？若不可，你就说罢！'),
('CUV', '撒母耳记下', 10, 17, 7, '户筛对押沙龙说：亚希多弗这次所定的谋不善。'),
('CUV', '撒母耳记下', 10, 17, 8, '户筛又说：你知道，你父亲和跟随他的人都是勇士，现在他们心里恼怒，如同田野丢崽子的母熊一般，而且你父亲是个战士，必不和民一同住宿。'),
('CUV', '撒母耳记下', 10, 17, 9, '他现今或藏在坑中或在别处，若有人首先被杀，凡听见的必说：跟随押沙龙的民被杀了。'),
('CUV', '撒母耳记下', 10, 17, 10, '虽有人胆大如狮子，他的心也必消化；因为以色列人都知道你父亲是英雄，跟随他的人也都是勇士。'),
('CUV', '撒母耳记下', 10, 17, 11, '依我之计，不如将以色列众人─从但直到别是巴，如同海边的沙那样多─聚集到你这里来，你也亲自率领他们出战。'),
('CUV', '撒母耳记下', 10, 17, 12, '这样，我们在何处遇见他，就下到他那里，如同露水下在地上一般，连他带跟随他的人，一个也不留下。'),
('CUV', '撒母耳记下', 10, 17, 13, '他若进了哪一座城，以色列众人必带绳子去，将那城拉到河里，甚至连一块小石头都不剩下。'),
('CUV', '撒母耳记下', 10, 17, 14, '押沙龙和以色列众人说：亚基人户筛的计谋比亚希多弗的计谋更好！这是因耶和华定意破坏亚希多弗的良谋，为要降祸与押沙龙。'),
('CUV', '撒母耳记下', 10, 17, 15, '户筛对祭司撒督和亚比亚他说：亚希多弗为押沙龙和以色列的长老所定的计谋是如此如此，我所定的计谋是如此如此。'),
('CUV', '撒母耳记下', 10, 17, 16, '现在你们要急速打发人去，告诉大卫说：今夜不可住在旷野的渡口，务要过河，免得王和跟随他的人都被吞灭。'),
('CUV', '撒母耳记下', 10, 17, 17, '那时，约拿单和亚希玛斯在隐罗结那里等候，不敢进城，恐怕被人看见。有一个使女出来，将这话告诉他们，他们就去报信给大卫王。'),
('CUV', '撒母耳记下', 10, 17, 18, '然而有一个童子看见他们，就去告诉押沙龙。他们急忙跑到巴户琳某人的家里；那人院中有一口井，他们就下到井里。'),
('CUV', '撒母耳记下', 10, 17, 19, '那家的妇人用盖盖上井口，又在上头铺上碎麦，事就没有泄漏。'),
('CUV', '撒母耳记下', 10, 17, 20, '押沙龙的仆人来到那家，问妇人说：亚希玛斯和约拿单在哪里？妇人说：他们过了河了。仆人找他们，找不著，就回耶路撒冷去了。'),
('CUV', '撒母耳记下', 10, 17, 21, '他们走后，二人从井里上来，去告诉大卫王说：亚希多弗如此如此定计害你，你们务要起来，快快过河。'),
('CUV', '撒母耳记下', 10, 17, 22, '于是大卫和跟随他的人都起来，过约但河。到了天亮，无一人不过约但河的。'),
('CUV', '撒母耳记下', 10, 17, 23, '亚希多弗见不依从他的计谋，就备上驴，归回本城；到了家，留下遗言，便吊死了，葬在他父亲的坟墓里。'),
('CUV', '撒母耳记下', 10, 17, 24, '大卫到了玛哈念，押沙龙和跟随他的以色列人也都过了约但河。'),
('CUV', '撒母耳记下', 10, 17, 25, '押沙龙立亚玛撒作元帅，代替约押。亚玛撒是以实玛利人（又作以色列人）以特拉的儿子。以特拉曾与拿辖的女儿亚比该亲近；这亚比该与约押的母亲洗鲁雅是姊妹。'),
('CUV', '撒母耳记下', 10, 17, 26, '押沙龙和以色列人都安营在基列地。'),
('CUV', '撒母耳记下', 10, 17, 27, '大卫到了玛哈念，亚扪族的拉巴人拿辖的儿子朔比，罗底巴人亚米利的儿子玛吉，基列的罗基琳人巴西莱，'),
('CUV', '撒母耳记下', 10, 17, 28, '带著被、褥、盆、碗、瓦器、小麦、大麦、麦面、炒谷、豆子、红豆、炒豆、'),
('CUV', '撒母耳记下', 10, 17, 29, '蜂蜜、奶油、绵羊、奶饼，供给大卫和跟随他的人吃；他们说：民在旷野，必饥渴困乏了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记下', 10, 18, 1, '大卫数点跟随他的人，立千夫长、百夫长率领他们。'),
('CUV', '撒母耳记下', 10, 18, 2, '大卫打发军兵出战，分为三队：一队在约押手下，一队在洗鲁雅的儿子、约押兄弟亚比筛手下，一队在迦特人以太手下。大卫对军兵说：我必与你们一同出战。'),
('CUV', '撒母耳记下', 10, 18, 3, '军兵却说：你不可出战。若是我们逃跑，敌人必不介意；我们阵亡一半，敌人也不介意。因为你一人强似我们万人，你不如在城里预备帮助我们。'),
('CUV', '撒母耳记下', 10, 18, 4, '王向他们说：你们以为怎样好，我就怎样行。于是王站在城门旁，军兵或百或千地挨次出去了。'),
('CUV', '撒母耳记下', 10, 18, 5, '王嘱咐约押、亚比筛、以太说：你们要为我的缘故宽待那少年人押沙龙。王为押沙龙嘱咐众将的话，兵都听见了。'),
('CUV', '撒母耳记下', 10, 18, 6, '兵就出到田野迎著以色列人，在以法莲树林里交战。'),
('CUV', '撒母耳记下', 10, 18, 7, '以色列人败在大卫的仆人面前；那日阵亡的甚多，共有二万人。'),
('CUV', '撒母耳记下', 10, 18, 8, '因为在那里四面打仗，死于树林的比死于刀剑的更多。'),
('CUV', '撒母耳记下', 10, 18, 9, '押沙龙偶然遇见大卫的仆人。押沙龙骑著骡子，从大橡树密枝底下经过，他的头发被树枝绕住，就悬挂起来，所骑的骡子便离他去了。'),
('CUV', '撒母耳记下', 10, 18, 10, '有个人看见，就告诉约押说：我看见押沙龙挂在橡树上了。'),
('CUV', '撒母耳记下', 10, 18, 11, '约押对报信的人说：你既看见他，为甚么不将他打死落在地上呢？你若打死他，我就赏你十舍客勒银子，一条带子。'),
('CUV', '撒母耳记下', 10, 18, 12, '那人对约押说：我就是得你一千舍客勒银子，我也不敢伸手害王的儿子；因为我们听见王嘱咐你和亚比筛并以太说：你们要谨慎，不可害那少年人押沙龙。'),
('CUV', '撒母耳记下', 10, 18, 13, '我若妄为害了他的性命，就是你自己也必与我为敌（原来，无论何事都瞒不过王。）'),
('CUV', '撒母耳记下', 10, 18, 14, '约押说：我不能与你留连。约押手拿三杆短枪，趁押沙龙在橡树上还活著，就刺透他的心。'),
('CUV', '撒母耳记下', 10, 18, 15, '给约押拿兵器的十个少年人围绕押沙龙，将他杀死。'),
('CUV', '撒母耳记下', 10, 18, 16, '约押吹角，拦阻众人，他们就回来，不再追赶以色列人。'),
('CUV', '撒母耳记下', 10, 18, 17, '他们将押沙龙丢在林中一个大坑里，上头堆起一大堆石头。以色列众人都逃跑，各回各家去了。'),
('CUV', '撒母耳记下', 10, 18, 18, '押沙龙活著的时候，在王谷立了一根石柱，因他说：我没有儿子为我留名。他就以自己的名称那石柱叫押沙龙柱，直到今日。'),
('CUV', '撒母耳记下', 10, 18, 19, '撒督的儿子亚希玛斯说：容我跑去，将耶和华向仇敌给王报仇的信息报与王知。'),
('CUV', '撒母耳记下', 10, 18, 20, '约押对他说：你今日不可去报信，改日可以报信；因为今日王的儿子死了，所以你不可去报信。'),
('CUV', '撒母耳记下', 10, 18, 21, '约押对古示人说：你去将你所看见的告诉王。古示人在约押面前下拜，就跑去了。'),
('CUV', '撒母耳记下', 10, 18, 22, '撒督的儿子亚希玛斯又对约押说：无论怎样，求你容我随著古示人跑去。约押说：我儿，你报这信息，既不得赏赐，何必要跑去呢？'),
('CUV', '撒母耳记下', 10, 18, 23, '他又说：无论怎样，我要跑去。约押说：你跑去罢！亚希玛斯就从平原往前跑，跑过古示人去了。'),
('CUV', '撒母耳记下', 10, 18, 24, '大卫正坐在城瓮里。守望的人上城门楼的顶上，举目观看，见有一个人独自跑来。'),
('CUV', '撒母耳记下', 10, 18, 25, '守望的人就大声告诉王。王说：他若独自来，必是报口信的。那人跑得渐渐近了。'),
('CUV', '撒母耳记下', 10, 18, 26, '守望的人又见一人跑来，就对守城门的人说：又有一人独自跑来。王说：这也必是报信的。'),
('CUV', '撒母耳记下', 10, 18, 27, '守望的人说：我看前头人的跑法，好像撒督的儿子亚希玛斯的跑法一样。王说：他是个好人，必是报好信息。'),
('CUV', '撒母耳记下', 10, 18, 28, '亚希玛斯向王呼叫说：平安了！就在王面前脸伏于地叩拜，说：耶和华─你的神是应当称颂的，因他已将那举手攻击我主我王的人交给王了。'),
('CUV', '撒母耳记下', 10, 18, 29, '王问说：少年人押沙龙平安不平安？亚希玛斯回答说：约押打发王的仆人，那时仆人听见众民大声喧哗，却不知道是甚么事。'),
('CUV', '撒母耳记下', 10, 18, 30, '王说：你退去，站在旁边。他就退去，站在旁边。'),
('CUV', '撒母耳记下', 10, 18, 31, '古示人也来到，说：有信息报给我主我王！耶和华今日向一切兴起攻击你的人给你报仇了。'),
('CUV', '撒母耳记下', 10, 18, 32, '王问古示人说：少年人押沙龙平安不平安？古示人回答说：愿我主我王的仇敌，和一切兴起要杀害你的人，都与那少年人一样。'),
('CUV', '撒母耳记下', 10, 18, 33, '王就心里伤恸，上城门楼去哀哭，一面走一面说：我儿押沙龙啊！我儿，我儿押沙龙啊！我恨不得替你死，押沙龙啊，我儿！我儿！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记下', 10, 19, 1, '有人告诉约押说：王为押沙龙哭泣悲哀。'),
('CUV', '撒母耳记下', 10, 19, 2, '众民听说王为他儿子忧愁，他们得胜的欢乐却变成悲哀。'),
('CUV', '撒母耳记下', 10, 19, 3, '那日众民暗暗地进城，就如败阵逃跑、惭愧的民一般。'),
('CUV', '撒母耳记下', 10, 19, 4, '王蒙著脸，大声哭号说：我儿押沙龙啊！押沙龙，我儿，我儿啊！'),
('CUV', '撒母耳记下', 10, 19, 5, '约押进去见王，说：你今日使你一切仆人脸面惭愧了！他们今日救了你的性命和你儿女妻妾的性命，'),
('CUV', '撒母耳记下', 10, 19, 6, '你却爱那恨你的人，恨那爱你的人。你今日明明地不以将帅、仆人为念。我今日看明，若押沙龙活著，我们都死亡，你就喜悦了。'),
('CUV', '撒母耳记下', 10, 19, 7, '现在你当出去，安慰你仆人的心。我指著耶和华起誓：你若不出去，今夜必无一人与你同在一处；这祸患就比你从幼年到如今所遭的更甚！'),
('CUV', '撒母耳记下', 10, 19, 8, '于是王起来，坐在城门口。众民听说王坐在城门口，就都到王面前。以色列人已经逃跑，各回各家.去了。'),
('CUV', '撒母耳记下', 10, 19, 9, '以色列众支派的人纷纷议论说：王曾救我们脱离仇敌的手，又救我们脱离非利士人的手，现在他躲避押沙龙逃走了。'),
('CUV', '撒母耳记下', 10, 19, 10, '我们膏押沙龙治理我们，他已经阵亡。现在为甚么不出一言请王回来呢？'),
('CUV', '撒母耳记下', 10, 19, 11, '大卫王差人去见祭司撒督和亚比亚他，说：你们当向犹大长老说：以色列众人已经有话请王回宫，你们为甚么落在他们后头呢？'),
('CUV', '撒母耳记下', 10, 19, 12, '你们是我的弟兄，是我的骨肉，为甚么在人后头请王回来呢？'),
('CUV', '撒母耳记下', 10, 19, 13, '也要对亚玛撒说：你不是我的骨肉么？我若不立你替约押常作元帅，愿神重重地降罚与我！'),
('CUV', '撒母耳记下', 10, 19, 14, '如此就挽回犹大众人的心，如同一人的心。他们便打发人去见王，说：请王和王的一切臣仆回来。'),
('CUV', '撒母耳记下', 10, 19, 15, '王就回来，到了约但河。犹大人来到吉甲，要去迎接王，请他过约但河。'),
('CUV', '撒母耳记下', 10, 19, 16, '巴户琳的便雅悯人、基拉的儿子示每急忙与犹大人一同下去迎接大卫王。'),
('CUV', '撒母耳记下', 10, 19, 17, '跟从示每的有一千便雅悯人，还有扫罗家的仆人洗巴和他十五个儿子，二十个仆人；他们都逿过约但河迎接王。'),
('CUV', '撒母耳记下', 10, 19, 18, '有摆渡船过去，渡王的家眷，任王使用。王要过约但河的时候，基拉的儿子示每就俯伏在王面前，'),
('CUV', '撒母耳记下', 10, 19, 19, '对王说：我主我王出耶路撒冷的时候，仆人行悖逆的事，现在求我主不要因此加罪与仆人，不要记念，也不要放在心上。'),
('CUV', '撒母耳记下', 10, 19, 20, '仆人明知自己有罪，所以约瑟全家之中，今日我首先下来迎接我主我王。'),
('CUV', '撒母耳记下', 10, 19, 21, '洗鲁雅的儿子亚比筛说：示每既咒骂耶和华的受膏者，不应当治死他么？'),
('CUV', '撒母耳记下', 10, 19, 22, '大卫说：洗鲁雅的儿子，我与你们有何关涉，使你们今日与我反对呢？今日在以色列中岂可治死人呢？我岂不知今日我作以色列的王么？'),
('CUV', '撒母耳记下', 10, 19, 23, '于是王对示每说：你必不死。王就向他起誓。'),
('CUV', '撒母耳记下', 10, 19, 24, '扫罗的孙子米非波设也下去迎接王。他自从王去的日子，直到王平平安安地回来，没有修脚，没有剃胡须，也没有洗衣服。'),
('CUV', '撒母耳记下', 10, 19, 25, '他来到耶路撒冷迎接王的时候，王问他说：米非波设，你为甚么没有与我同去呢？'),
('CUV', '撒母耳记下', 10, 19, 26, '他回答说：我主我王，仆人是瘸腿的。那日我想要备驴骑上，与王同去，无奈我的仆人欺哄了我，'),
('CUV', '撒母耳记下', 10, 19, 27, '又在我主我王面前谗毁我。然而我主我王如同神的使者一般，你看怎样好，就怎样行罢！'),
('CUV', '撒母耳记下', 10, 19, 28, '因为我祖全家的人，在我主我王面前都算为死人，王却使仆人在王的席上同人吃饭，我现在向王还能辨理诉冤么？'),
('CUV', '撒母耳记下', 10, 19, 29, '王对他说：你何必再提你的事呢？我说，你与洗巴均分地土。'),
('CUV', '撒母耳记下', 10, 19, 30, '米非波设对王说：我主我王既平平安安地回宫，就任凭洗巴都取了也可以。'),
('CUV', '撒母耳记下', 10, 19, 31, '基列人巴西莱从罗基琳下来，要送王过约但河，就与王一同过了约但河。'),
('CUV', '撒母耳记下', 10, 19, 32, '巴西莱年纪老迈，已经八十岁了。王住在玛哈念的时候，他就拿食物来供给王；他原是大富户。'),
('CUV', '撒母耳记下', 10, 19, 33, '王对巴西莱说：你与我同去，我要在耶路撒冷那里养你的老。'),
('CUV', '撒母耳记下', 10, 19, 34, '巴西莱对王说：我在世的年日还能有多少，使我与王同上耶路撒冷呢？'),
('CUV', '撒母耳记下', 10, 19, 35, '仆人现在八十岁了，还能尝出饮食的滋味、辨别美恶么？还能听男女歌唱的声音么？仆人何必累赘我主我王呢？'),
('CUV', '撒母耳记下', 10, 19, 36, '仆人只要送王过约但河，王何必赐我这样的恩典呢？'),
('CUV', '撒母耳记下', 10, 19, 37, '求你准我回去，好死在我本城，葬在我父母的墓旁。这里有王的仆人金罕，让他同我主我王过去，可以随意待他。'),
('CUV', '撒母耳记下', 10, 19, 38, '王说：金罕可以与我同去，我必照你的心愿待他。你向我求甚么，我都必为你成就。'),
('CUV', '撒母耳记下', 10, 19, 39, '于是众民过约但河，王也过去。王与巴西莱亲嘴，为他祝福，巴西莱就回本地去了。'),
('CUV', '撒母耳记下', 10, 19, 40, '王过去，到了吉甲，金罕也跟他过去。犹大众民和以色列民的一半也都送王过去。'),
('CUV', '撒母耳记下', 10, 19, 41, '以色列众人来见王，对他说：我们弟兄犹大人为甚么暗暗送王和王的家眷，并跟随王的人过约但河？'),
('CUV', '撒母耳记下', 10, 19, 42, '犹大众人回答以色列人说：因为王与我们是亲属，你们为何因这事发怒呢？我们吃了王的甚么呢？王赏赐了我们甚么呢？'),
('CUV', '撒母耳记下', 10, 19, 43, '以色列人回答犹大人说：按支派，我们与王有十分的情分；在大卫身上，我们也比你们更有情分。你们为何藐视我们，请王回来不先与我们商量呢？但犹大人的话比以色列人的话更硬。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记下', 10, 20, 1, '在那里恰巧有一个匪徒，名叫示巴，是便雅悯人比基利的儿子。他吹角，说：我们与大卫无分，与耶西的儿子无涉。以色列人哪，你们各回各家去罢！'),
('CUV', '撒母耳记下', 10, 20, 2, '于是以色列人都离开大卫，跟随比基利的儿子示巴。但犹大人从约但河直到耶路撒冷，都紧紧跟随他们的王。'),
('CUV', '撒母耳记下', 10, 20, 3, '大卫王来到耶路撒冷，进了宫殿，就把从前留下看守宫殿的十个妃嫔禁闭在冷宫，养活他们，不与他们亲近。他们如同寡妇被禁，直到死的日子。'),
('CUV', '撒母耳记下', 10, 20, 4, '王对亚玛撒说：你要在三日之内将犹大人招聚了来，你也回到这里来。'),
('CUV', '撒母耳记下', 10, 20, 5, '亚玛撒就去招聚犹大人，却耽延过了王所限的日期。'),
('CUV', '撒母耳记下', 10, 20, 6, '大卫对亚比筛说：现在恐怕比基利的儿子示巴加害于我们比押沙龙更甚。你要带领你主的仆人追赶他，免得他得了坚固城，躲避我们。'),
('CUV', '撒母耳记下', 10, 20, 7, '约押的人和基利提人、比利提人，并所有的勇士，都跟著亚比筛，从耶路撒冷出去追赶比基利的儿子示巴。'),
('CUV', '撒母耳记下', 10, 20, 8, '他们到了基遍的大磐石那里，亚玛撒来迎接他们。那时约押穿著战衣，腰束佩刀的带子，刀在鞘内；约押前行，刀从鞘内掉出来。'),
('CUV', '撒母耳记下', 10, 20, 9, '约押左手拾起刀来，对亚玛撒说：我兄弟，你好啊！就用右手抓住亚玛撒的胡子，要与他亲嘴。'),
('CUV', '撒母耳记下', 10, 20, 10, '亚玛撒没有防备约押手里所拿的刀；约押用刀刺入他的肚腹，他的肠子流在地上，没有再刺他，就死了。约押和他兄弟亚比筛往前追赶比基利的儿子示巴。'),
('CUV', '撒母耳记下', 10, 20, 11, '有约押的一个少年人站在亚玛撒尸身旁边，对众人说：谁喜悦约押，谁归顺大卫，就当跟随约押去。'),
('CUV', '撒母耳记下', 10, 20, 12, '亚玛撒在道路上滚在自己的血里。那人见众民经过都站住，就把亚玛撒的尸身从路上挪到田间，用衣服遮盖。'),
('CUV', '撒母耳记下', 10, 20, 13, '尸身从路上挪移之后，众民就都跟随约押去追赶比基利的儿子示巴。'),
('CUV', '撒母耳记下', 10, 20, 14, '他走遍以色列各支派，直到伯玛迦的亚比拉，并比利人的全地；那些地方的人也都聚集跟随他。'),
('CUV', '撒母耳记下', 10, 20, 15, '约押和跟随的人到了伯玛迦的亚比拉，围困示巴，就对著城筑垒；跟随约押的众民用锤撞城，要使城塌陷。'),
('CUV', '撒母耳记下', 10, 20, 16, '有一个聪明妇人从城上呼叫说：听啊，听啊，请约押近前来，我好与他说话。'),
('CUV', '撒母耳记下', 10, 20, 17, '约押就近前来，妇人问他说：你是约押不是？他说：我是。妇人说：求你听婢女的话。约押说：我听。'),
('CUV', '撒母耳记下', 10, 20, 18, '妇人说：古时有话说，当先在亚比拉求问，然后事就定妥。'),
('CUV', '撒母耳记下', 10, 20, 19, '我们这城的人在以色列人中是和平、忠厚的。你为何要毁坏以色列中的大城，吞灭耶和华的产业呢？'),
('CUV', '撒母耳记下', 10, 20, 20, '约押回答说：我决不吞灭毁坏，'),
('CUV', '撒母耳记下', 10, 20, 21, '乃因以法莲山地的一个人─比基利的儿子示巴─举手攻击大卫王，你们若将他一人交出来，我便离城而去。妇人对约押说：那人的首级必从城墙上丢给你。'),
('CUV', '撒母耳记下', 10, 20, 22, '妇人就凭他的智慧去劝众人。他们便割下比基利的儿子示巴的首级，丢给约押。约押吹角，众人就离城而散，各归各家去了。约押回耶路撒冷，到王那里。'),
('CUV', '撒母耳记下', 10, 20, 23, '约押作以色列全军的元帅；耶何耶大的儿子比拿雅统辖基利提人和比利提人；'),
('CUV', '撒母耳记下', 10, 20, 24, '亚多兰掌管服苦的人；亚希律的儿子约沙法作史官；'),
('CUV', '撒母耳记下', 10, 20, 25, '示法作书记；撒督和亚比亚他作祭司长；'),
('CUV', '撒母耳记下', 10, 20, 26, '睚珥人以拉作大卫的宰相。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记下', 10, 21, 1, '大卫年间有饥荒，一连三年，大卫就求问耶和华。耶和华说：这饥荒是因扫罗和他流人血之家杀死基遍人。'),
('CUV', '撒母耳记下', 10, 21, 2, '原来这基遍人不是以色列人，乃是亚摩利人中所剩的；以色列人曾向他们起誓，不杀灭他们，扫罗却为以色列人和犹大人发热心，想要杀灭他们。大卫王召了他们来，'),
('CUV', '撒母耳记下', 10, 21, 3, '问他们说：我当为你们怎样行呢？可用甚么赎这罪，使你们为耶和华的产业祝福呢？'),
('CUV', '撒母耳记下', 10, 21, 4, '基遍人回答说：我们和扫罗与他家的事并不关乎金银，也不要因我们的缘故杀一个以色列人。大卫说：你们怎样说，我就为你们怎样行。'),
('CUV', '撒母耳记下', 10, 21, 5, '他们对王说：那从前谋害我们、要灭我们、使我们不得再住以色列境内的人，'),
('CUV', '撒母耳记下', 10, 21, 6, '现在愿将他的子孙七人交给我们，我们好在耶和华面前，将他们悬挂在耶和华拣选扫罗的基比亚。王说：我必交给你们。'),
('CUV', '撒母耳记下', 10, 21, 7, '王因为曾与扫罗的儿子约拿单指著耶和华起誓结盟，就爱惜扫罗的孙子、约拿单的儿子米非波设，不交出来，'),
('CUV', '撒母耳记下', 10, 21, 8, '却把爱雅的女儿利斯巴给扫罗所生的两个儿子亚摩尼、米非波设，和扫罗女儿米甲的姊姊给米何拉人巴西莱儿子亚得列所生的五个儿子'),
('CUV', '撒母耳记下', 10, 21, 9, '交在基遍人的手里。基遍人就把他们，在耶和华面前，悬挂在山上，这七人就一同死亡。被杀的时候正是收割的日子，就是动手割大麦的时候。'),
('CUV', '撒母耳记下', 10, 21, 10, '爱雅的女儿利斯巴用麻布在磐石上搭棚，从动手收割的时候直到天降雨在尸身上的时候，日间不容空中的雀鸟落在尸身上，夜间不让田野的走兽前来糟践。'),
('CUV', '撒母耳记下', 10, 21, 11, '有人将扫罗的妃嫔爱雅女儿利斯巴所行的这事告诉大卫。'),
('CUV', '撒母耳记下', 10, 21, 12, '大卫就去，从基列雅比人那里将扫罗和他儿子约拿单的骸骨搬了来（是因非利士人从前在基利波杀扫罗，将尸身悬挂在伯珊的街市上，基列雅比人把尸身偷了去。）'),
('CUV', '撒母耳记下', 10, 21, 13, '大卫将扫罗和他儿子约拿单的骸骨从那里搬了来，又收殓被悬挂七人的骸骨，'),
('CUV', '撒母耳记下', 10, 21, 14, '将扫罗和他儿子约拿单的骸骨葬在便雅悯的洗拉，在扫罗父亲基士的坟墓里；众人行了王所吩咐的。此后神垂听国民所求的。'),
('CUV', '撒母耳记下', 10, 21, 15, '非利士人与以色列人打仗；大卫带领仆人下去，与非利士人接战，大卫就疲乏了。'),
('CUV', '撒母耳记下', 10, 21, 16, '伟人的一个儿子以实比诺要杀大卫；他的铜枪重三百舍客勒，又佩著新刀。'),
('CUV', '撒母耳记下', 10, 21, 17, '但洗鲁雅的儿子亚比筛帮助大卫，攻打非利士人，将他杀死。当日，跟随大卫的人向大卫起誓说：以后你不可再与我们一同出战，恐怕熄灭以色列的灯。'),
('CUV', '撒母耳记下', 10, 21, 18, '后来，以色列人在歌伯与非利士人打仗，户沙人西比该杀了伟人的一个儿子撒弗。'),
('CUV', '撒母耳记下', 10, 21, 19, '又在歌伯与非利士人打仗，伯利恒人雅雷俄珥金的儿子伊勒哈难杀了迦特人歌利亚。这人的枪杆粗如织布的机轴。'),
('CUV', '撒母耳记下', 10, 21, 20, '又在迦特打仗，那里有一个身量高大的人，手脚都是六指，共有二十四个指头；他也是伟人的儿子。'),
('CUV', '撒母耳记下', 10, 21, 21, '这人向以色列人骂阵，大卫的哥哥示米亚的儿子约拿单就杀了他。'),
('CUV', '撒母耳记下', 10, 21, 22, '这四个人是迦特伟人的儿子，都死在大卫和他仆人的手下。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记下', 10, 22, 1, '当耶和华救大卫脱离一切仇敌和扫罗之手的日子，他向耶和华念这诗，'),
('CUV', '撒母耳记下', 10, 22, 2, '说：耶和华是我的岩石，我的山寨，我的救主，'),
('CUV', '撒母耳记下', 10, 22, 3, '我的神，我的磐石，我所投靠的。他是我的盾牌，是拯救我的角，是我的高台，是我的避难所。我的救主啊，你是救我脱离强暴的。'),
('CUV', '撒母耳记下', 10, 22, 4, '我要求告当赞美的耶和华，这样，我必从仇敌手中被救出来。'),
('CUV', '撒母耳记下', 10, 22, 5, '曾有死亡的波浪环绕我，匪类的急流使我惊惧，'),
('CUV', '撒母耳记下', 10, 22, 6, '阴间的绳索缠绕我，死亡的网罗临到我。'),
('CUV', '撒母耳记下', 10, 22, 7, '我在急难中求告耶和华，向我的神呼求。他从殿中听了我的声音；我的呼求入了他的耳中。'),
('CUV', '撒母耳记下', 10, 22, 8, '那时因他发怒，地就摇撼战抖；天的根基也震动摇撼。'),
('CUV', '撒母耳记下', 10, 22, 9, '从他鼻孔冒烟上腾；从他口中发火焚烧，连炭也著了。'),
('CUV', '撒母耳记下', 10, 22, 10, '他又使天下垂，亲自降临；有黑云在他脚下。'),
('CUV', '撒母耳记下', 10, 22, 11, '他坐著基路伯飞行，在风的翅膀上显现。'),
('CUV', '撒母耳记下', 10, 22, 12, '他以黑暗和聚集的水、天空的厚云为他四围的行宫。'),
('CUV', '撒母耳记下', 10, 22, 13, '因他面前的光辉炭都著了。'),
('CUV', '撒母耳记下', 10, 22, 14, '耶和华从天上打雷；至高者发出声音。'),
('CUV', '撒母耳记下', 10, 22, 15, '他射出箭来，使仇敌四散，发出闪电，使他们扰乱。'),
('CUV', '撒母耳记下', 10, 22, 16, '耶和华的斥责一发，鼻孔的气一出，海底就出现，大地的根基也显露。'),
('CUV', '撒母耳记下', 10, 22, 17, '他从高天伸手抓住我，把我从大水中拉上来。'),
('CUV', '撒母耳记下', 10, 22, 18, '他救我脱离我的劲敌和那些恨我的人，因为他们比我强盛。'),
('CUV', '撒母耳记下', 10, 22, 19, '我遭遇灾难的日子，他们来攻击我；但耶和华是我的倚靠。'),
('CUV', '撒母耳记下', 10, 22, 20, '他又领我到宽阔之处；他救拔我，因他喜悦我。'),
('CUV', '撒母耳记下', 10, 22, 21, '耶和华按著我的公义报答我，按著我手中的清洁赏赐我。'),
('CUV', '撒母耳记下', 10, 22, 22, '因为我遵守了耶和华的道，未曾作恶离开我的神。'),
('CUV', '撒母耳记下', 10, 22, 23, '他的一切典章常在我面前；他的律例，我也未曾离弃。'),
('CUV', '撒母耳记下', 10, 22, 24, '我在他面前作了完全人；我也保守自己远离我的罪孽。'),
('CUV', '撒母耳记下', 10, 22, 25, '所以耶和华按我的公义，按我在他眼前的清洁赏赐我。'),
('CUV', '撒母耳记下', 10, 22, 26, '慈爱的人，你以慈爱待他；完全的人，你以完全待他；'),
('CUV', '撒母耳记下', 10, 22, 27, '清洁的人，你以清洁待他；乖僻的人，你以弯曲待他。'),
('CUV', '撒母耳记下', 10, 22, 28, '困苦的百姓，你必拯救；但你的眼目察看高傲的人，使他降卑。'),
('CUV', '撒母耳记下', 10, 22, 29, '耶和华啊，你是我的灯；耶和华必照明我的黑暗。'),
('CUV', '撒母耳记下', 10, 22, 30, '我藉著你冲入敌军，藉著我的神跳过墙垣。'),
('CUV', '撒母耳记下', 10, 22, 31, '至于神，他的道是完全的；耶和华的话是炼净的。凡投靠他的，他便作他们的盾牌。'),
('CUV', '撒母耳记下', 10, 22, 32, '除了耶和华，谁是神呢？除了我们的神，谁是磐石呢？'),
('CUV', '撒母耳记下', 10, 22, 33, '神是我坚固的保障；他引导完全人行他的路。'),
('CUV', '撒母耳记下', 10, 22, 34, '他使我的脚快如母鹿的蹄，又使我在高处安稳。'),
('CUV', '撒母耳记下', 10, 22, 35, '他教导我的手能以争战，甚至我的膀臂能开铜弓。'),
('CUV', '撒母耳记下', 10, 22, 36, '你把你的救恩给我作盾牌；你的温和使我为大。'),
('CUV', '撒母耳记下', 10, 22, 37, '你使我脚下的地步宽阔；我的脚未曾滑跌。'),
('CUV', '撒母耳记下', 10, 22, 38, '我追赶我的仇敌，灭绝了他们，未灭以先，我没有归回。'),
('CUV', '撒母耳记下', 10, 22, 39, '我灭绝了他们，打伤了他们，使他们不能起来；他们都倒在我的脚下。'),
('CUV', '撒母耳记下', 10, 22, 40, '因为你曾以力量束我的腰，使我能争战；你也使那起来攻击我的都服在我以下。'),
('CUV', '撒母耳记下', 10, 22, 41, '你又使我的仇敌在我面前转背逃跑，叫我能以剪除那恨我的人。'),
('CUV', '撒母耳记下', 10, 22, 42, '他们仰望，却无人拯救；就是呼求耶和华，他也不应允。'),
('CUV', '撒母耳记下', 10, 22, 43, '我捣碎他们，如同地上的灰尘，践踏他们，四散在地，如同街上的泥土。'),
('CUV', '撒母耳记下', 10, 22, 44, '你救我脱离我百姓的争竞，保护我作列国的元首；我素不认识的民必事奉我。'),
('CUV', '撒母耳记下', 10, 22, 45, '外邦人要投降我，一听见我的名声就必顺从我。'),
('CUV', '撒母耳记下', 10, 22, 46, '外邦人要衰残，战战兢兢地出他们的营寨。'),
('CUV', '撒母耳记下', 10, 22, 47, '耶和华是活神，愿我的磐石被人称颂！愿神─那拯救我的磐石被人尊崇！'),
('CUV', '撒母耳记下', 10, 22, 48, '这位神就是那为我伸冤、使众民服在我以下的。'),
('CUV', '撒母耳记下', 10, 22, 49, '你救我脱离仇敌，又把我举起，高过那些起来攻击我的；你救我脱离强暴的人。'),
('CUV', '撒母耳记下', 10, 22, 50, '耶和华啊，因此我要在外邦中称谢你，歌颂你的名。'),
('CUV', '撒母耳记下', 10, 22, 51, '耶和华赐极大的救恩给他所立的王，施慈爱给他的受膏者，就是给大卫和他的后裔，直到永远！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记下', 10, 23, 1, '以下是大卫末了的话。耶西的儿子大卫得居高位，是雅各神所膏的，作以色列的美歌者，说：'),
('CUV', '撒母耳记下', 10, 23, 2, '耶和华的灵藉著我说：他的话在我口中。'),
('CUV', '撒母耳记下', 10, 23, 3, '以色列的神、以色列的磐石晓谕我说：那以公义治理人民的，敬畏神执掌权柄，'),
('CUV', '撒母耳记下', 10, 23, 4, '他必像日出的晨光，如无云的清晨，雨后的晴光，使地发生嫩草。'),
('CUV', '撒母耳记下', 10, 23, 5, '我家在神面前并非如此；神却与我立永远的约。这约凡事坚稳，关乎我的一切救恩和我一切所想望的，他岂不为我成就么？'),
('CUV', '撒母耳记下', 10, 23, 6, '但匪类都必像荆棘被丢弃；人不敢用手拿他；'),
('CUV', '撒母耳记下', 10, 23, 7, '拿他的人必带铁器和枪杆，终久他必被火焚烧。'),
('CUV', '撒母耳记下', 10, 23, 8, '大卫勇士的名字记在下面：他革扪人约设巴设，又称伊斯尼人亚底挪，他是军长的统领，一时击杀了八百人。'),
('CUV', '撒母耳记下', 10, 23, 9, '其次是亚合人朵多的儿子以利亚撒。从前非利士人聚集要打仗，以色列人迎著上去，有跟随大卫的三个勇士向非利士人骂阵，其中有以利亚撒。'),
('CUV', '撒母耳记下', 10, 23, 10, '他起来击杀非利士人，直到手臂疲乏，手黏住刀把。那日耶和华使以色列人大获全胜；众民在以利亚撒后头专夺财物。'),
('CUV', '撒母耳记下', 10, 23, 11, '其次是哈拉人亚基的儿子沙玛。一日，非利士人聚集成群，在一块长满红豆的田里，众民就在非利士人面前逃跑。'),
('CUV', '撒母耳记下', 10, 23, 12, '沙玛却站在那田间击杀非利士人，救护了那田。耶和华使以色列人大获全胜。'),
('CUV', '撒母耳记下', 10, 23, 13, '收割的时候，有三十个勇士中的三个人下到亚杜兰洞见大卫。非利士的军兵在利乏音谷安营。'),
('CUV', '撒母耳记下', 10, 23, 14, '那时大卫在山寨，非利士人的防营在伯利恒。'),
('CUV', '撒母耳记下', 10, 23, 15, '大卫渴想，说：甚愿有人将伯利恒城门旁、井里的水打来给我喝。'),
('CUV', '撒母耳记下', 10, 23, 16, '这三个勇士就闯过非利士人的营盘，从伯利恒城门旁的井里打水，拿来奉给大卫。他却不肯喝，将水奠在耶和华面前，'),
('CUV', '撒母耳记下', 10, 23, 17, '说：耶和华啊，这三个人冒死去打水；这水好像他们的血一般，我断不敢喝。如此，大卫不肯喝。这是三个勇士所做的事。'),
('CUV', '撒母耳记下', 10, 23, 18, '洗鲁雅的儿子、约押的兄弟亚比筛是这三个勇士的首领；他举枪杀了三百人，就在三个勇士里得了名。'),
('CUV', '撒母耳记下', 10, 23, 19, '他在这三个勇士里是最尊贵的，所以作他们的首领，只是不及前三个勇士。'),
('CUV', '撒母耳记下', 10, 23, 20, '有甲薛勇士耶何耶大的儿子比拿雅行过大能的事；他杀了摩押人亚利伊勒的两个儿子，又在下雪的时候下坑里去，杀了一个狮子，'),
('CUV', '撒母耳记下', 10, 23, 21, '又杀了一个强壮的埃及人；埃及人手里拿著枪，比拿雅只拿著棍子下去，从埃及人手里夺过枪来，用那枪将他杀死。'),
('CUV', '撒母耳记下', 10, 23, 22, '这是耶何耶大的儿子比拿雅所行的事，就在三个勇士里得了名。'),
('CUV', '撒母耳记下', 10, 23, 23, '他比那三十个勇士都尊贵，只是不及前三个勇士。大卫立他作护卫长。'),
('CUV', '撒母耳记下', 10, 23, 24, '三十个勇士里有约押的兄弟亚撒黑，伯利恒人朵多的儿子伊勒哈难，'),
('CUV', '撒母耳记下', 10, 23, 25, '哈律人沙玛，哈律人以利加，'),
('CUV', '撒母耳记下', 10, 23, 26, '帕勒提人希利斯，提哥亚人益吉的儿子以拉，'),
('CUV', '撒母耳记下', 10, 23, 27, '亚拿突人亚比以谢，户沙人米本乃，'),
('CUV', '撒母耳记下', 10, 23, 28, '亚合人撒们，尼陀法人玛哈莱，'),
('CUV', '撒母耳记下', 10, 23, 29, '尼陀法人巴拿的儿子希立，便雅悯族、基比亚人利拜的儿子以太，'),
('CUV', '撒母耳记下', 10, 23, 30, '比拉顿人比拿雅，迦实溪人希太，'),
('CUV', '撒母耳记下', 10, 23, 31, '伯亚拉巴人亚比亚本，巴鲁米人押斯玛弗，'),
('CUV', '撒母耳记下', 10, 23, 32, '沙本人以利雅哈巴，雅善儿子中的约拿单，'),
('CUV', '撒母耳记下', 10, 23, 33, '哈拉人沙玛，哈拉人沙拉的儿子亚希暗，'),
('CUV', '撒母耳记下', 10, 23, 34, '玛迦人亚哈拜的儿子以利法列，基罗人亚希多弗的儿子以连，'),
('CUV', '撒母耳记下', 10, 23, 35, '迦密人希斯莱，亚巴人帕莱，'),
('CUV', '撒母耳记下', 10, 23, 36, '琐巴人拿单的儿子以甲，迦得人巴尼，'),
('CUV', '撒母耳记下', 10, 23, 37, '亚扪人洗勒，比录人拿哈莱（是给洗鲁雅的儿子约押拿兵器的），'),
('CUV', '撒母耳记下', 10, 23, 38, '以帖人以拉，以帖人迦立，'),
('CUV', '撒母耳记下', 10, 23, 39, '赫人乌利亚，共有三十七人。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒母耳记下', 10, 24, 1, '耶和华又向以色列人发怒，就激动大卫，使他吩咐人去数点以色列人和犹大人。'),
('CUV', '撒母耳记下', 10, 24, 2, '大卫就吩咐跟随他的元帅约押说：你去走遍以色列众支派，从但直到别是巴，数点百姓，我好知道他们的数目。'),
('CUV', '撒母耳记下', 10, 24, 3, '约押对王说：无论百姓多少，愿耶和华─你的神再加增百倍，使我主我王亲眼得见。我主我王何必喜悦行这事呢？'),
('CUV', '撒母耳记下', 10, 24, 4, '但王的命令胜过约押和众军长。约押和众军长就从王面前出去，数点以色列的百姓。'),
('CUV', '撒母耳记下', 10, 24, 5, '他们过了约但河，在迦得谷中、城的右边亚罗珥安营，与雅谢相对，'),
('CUV', '撒母耳记下', 10, 24, 6, '又到了基列和他停合示地，又到了但雅安，绕到西顿，'),
('CUV', '撒母耳记下', 10, 24, 7, '来到推罗的保障，并希未人和迦南人的各城，又到犹大南方的别是巴。'),
('CUV', '撒母耳记下', 10, 24, 8, '他们走遍全地，过了九个月零二十天，就回到耶路撒冷。'),
('CUV', '撒母耳记下', 10, 24, 9, '约押将百姓的总数奏告于王：以色列拿刀的勇士有八十万；犹大有五十万。'),
('CUV', '撒母耳记下', 10, 24, 10, '大卫数点百姓以后，就心中自责，祷告耶和华说：我行这事大有罪了。耶和华啊，求你除掉仆人的罪孽，因我所行的甚是愚昧。'),
('CUV', '撒母耳记下', 10, 24, 11, '大卫早晨起来，耶和华的话临到先知迦得，就是大卫的先见，说：'),
('CUV', '撒母耳记下', 10, 24, 12, '你去告诉大卫，说耶和华如此说：我有三样灾，随你选择一样，我好降与你。'),
('CUV', '撒母耳记下', 10, 24, 13, '于是迦得来见大卫，对他说：你愿意国中有七年的饥荒呢？是在你敌人面前逃跑，被追赶三个月呢？是在你国中有三日的瘟疫呢？现在你要揣摩思想，我好回复那差我来的。'),
('CUV', '撒母耳记下', 10, 24, 14, '大卫对迦得说：我甚为难！我愿落在耶和华的手里，因为他有丰盛的怜悯。我不愿落在人的手里。'),
('CUV', '撒母耳记下', 10, 24, 15, '于是，耶和华降瘟疫与以色列人，自早晨到所定的时候；从但直到别是巴，民间死了七万人。'),
('CUV', '撒母耳记下', 10, 24, 16, '天使向耶路撒冷伸手要灭城的时候，耶和华后悔，就不降这灾了，吩咐灭民的天使说：够了！住手罢！那时耶和华的使者在耶布斯人亚劳拿的禾场那里。'),
('CUV', '撒母耳记下', 10, 24, 17, '大卫看见灭民的天使，就祷告耶和华说：我犯了罪，行了恶；但这群羊做了甚么呢？愿你的手攻击我和我的父家。'),
('CUV', '撒母耳记下', 10, 24, 18, '当日，迦得来见大卫，对他说：你上去，在耶布斯人亚劳拿的禾场上为耶和华筑一座坛。'),
('CUV', '撒母耳记下', 10, 24, 19, '大卫就照著迦得奉耶和华名所说的话上去了。'),
('CUV', '撒母耳记下', 10, 24, 20, '亚劳拿观看，见王和他臣仆前来，就迎接出去，脸伏于地，向王下拜，'),
('CUV', '撒母耳记下', 10, 24, 21, '说：我主我王为何来到仆人这里呢？大卫说：我要买你这禾场，为耶和华筑一座坛，使民间的瘟疫止住。'),
('CUV', '撒母耳记下', 10, 24, 22, '亚劳拿对大卫说：我主我王，你喜悦用甚么，就拿去献祭。看哪，这里有牛可以作燔祭，有打粮的器具和套牛的轭可以当柴烧。'),
('CUV', '撒母耳记下', 10, 24, 23, '王啊，这一切，我亚劳拿都奉给你；又对王说：愿耶和华─你的神悦纳你。'),
('CUV', '撒母耳记下', 10, 24, 24, '王对亚劳拿说：不然。我必要按著价值向你买；我不肯用白得之物作燔祭献给耶和华─我的神。大卫就用五十舍客勒银子买了那禾场与牛。'),
('CUV', '撒母耳记下', 10, 24, 25, '大卫在那里为耶和华筑了一座坛，献燔祭和平安祭。如此，耶和华垂听国民所求的，瘟疫在以色列人中就止住了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪上', 11, 1, 1, '大卫王年纪老迈，虽用被遮盖，仍不觉暖。'),
('CUV', '列王纪上', 11, 1, 2, '所以臣仆对他说：不如为我主我王寻找一个处女，使他伺候王，奉养王，睡在王的怀中，好叫我主我王得暖。'),
('CUV', '列王纪上', 11, 1, 3, '于是在以色列全境寻找美貌的童女，寻得书念的一个童女亚比煞，就带到王那里。'),
('CUV', '列王纪上', 11, 1, 4, '这童女极其美貌，他奉养王，伺候王，王却没有与他亲近。'),
('CUV', '列王纪上', 11, 1, 5, '那时，哈及的儿子亚多尼雅自尊，说：我必作王，就为自己预备车辆、马兵，又派五十人在他前头奔走。'),
('CUV', '列王纪上', 11, 1, 6, '他父亲素来没有使他忧闷，说：你是做甚么呢？他甚俊美，生在押沙龙之后。'),
('CUV', '列王纪上', 11, 1, 7, '亚多尼雅与洗鲁雅的儿子约押，和祭司亚比亚他商议；二人就顺从他，帮助他。'),
('CUV', '列王纪上', 11, 1, 8, '但祭司撒督、耶何耶大的儿子比拿雅、先知拿单、示每、利以，并大卫的勇士都不顺从亚多尼雅。'),
('CUV', '列王纪上', 11, 1, 9, '一日，亚多尼雅在隐罗结旁、琐希列磐石那里宰了牛羊、肥犊，请他的诸弟兄，就是王的众子，并所有作王臣仆的犹大人；'),
('CUV', '列王纪上', 11, 1, 10, '惟独先知拿单和比拿雅并勇士，与他的兄弟所罗门，他都没有请。'),
('CUV', '列王纪上', 11, 1, 11, '拿单对所罗门的母亲拔示巴说：哈及的儿子亚多尼雅作王了，你没有听见么？我们的主大卫却不知道。'),
('CUV', '列王纪上', 11, 1, 12, '现在我可以给你出个主意，好保全你和你儿子所罗门的性命。'),
('CUV', '列王纪上', 11, 1, 13, '你进去见大卫王，对他说：我主我王啊，你不曾向婢女起誓说：你儿子所罗门必接续我作王，坐在我的位上么？现在亚多尼雅怎么作了王呢？'),
('CUV', '列王纪上', 11, 1, 14, '你还与王说话的时候，我也随后进去，证实你的话。'),
('CUV', '列王纪上', 11, 1, 15, '拔示巴进入内室见王，王甚老迈，书念的童女亚比煞正伺候王。'),
('CUV', '列王纪上', 11, 1, 16, '拔示巴向王屈身下拜；王说：你要甚么？'),
('CUV', '列王纪上', 11, 1, 17, '他说：我主啊，你曾向婢女指著耶和华─你的神起誓说：你儿子所罗门必接续我作王，坐在我的位上。'),
('CUV', '列王纪上', 11, 1, 18, '现在亚多尼雅作王了，我主我王却不知道。'),
('CUV', '列王纪上', 11, 1, 19, '他宰了许多牛羊、肥犊，请了王的众子和祭司亚比亚他，并元帅约押；惟独王的仆人所罗门，他没有请。'),
('CUV', '列王纪上', 11, 1, 20, '我主我王啊，以色列众人的眼目都仰望你，等你晓谕他们，在我主我王之后谁坐你的位。'),
('CUV', '列王纪上', 11, 1, 21, '若不然，到我主我王与列祖同睡以后，我和我儿子所罗门必算为罪人了。'),
('CUV', '列王纪上', 11, 1, 22, '拔示巴还与王说话的时候，先知拿单也进来了。'),
('CUV', '列王纪上', 11, 1, 23, '有人奏告王说：先知拿单来了。拿单进到王前，脸伏于地。'),
('CUV', '列王纪上', 11, 1, 24, '拿单说：我主我王果然应许亚多尼雅说你必接续我作王，坐在我的位上么？'),
('CUV', '列王纪上', 11, 1, 25, '他今日下去，宰了许多牛羊、肥犊，请了王的众子和军长，并祭司亚比亚他；他们正在亚多尼雅面前吃喝，说：愿亚多尼雅王万岁！'),
('CUV', '列王纪上', 11, 1, 26, '惟独我，就是你的仆人和祭司撒督，耶何耶大的儿子比拿雅，并王的仆人所罗门，他都没有请。'),
('CUV', '列王纪上', 11, 1, 27, '这事果然出乎我主我王么？王却没有告诉仆人们，在我主我王之后谁坐你的位。'),
('CUV', '列王纪上', 11, 1, 28, '大卫王吩咐说：叫拔示巴来。拔示巴就进来，站在王面前。'),
('CUV', '列王纪上', 11, 1, 29, '王起誓说：我指著救我性命脱离一切苦难、永生的耶和华起誓。'),
('CUV', '列王纪上', 11, 1, 30, '我既然指著耶和华─以色列的神向你起誓说：你儿子所罗门必接续我作王，坐在我的位上。我今日就必照这话而行。'),
('CUV', '列王纪上', 11, 1, 31, '于是，拔示巴脸伏于地，向王下拜，说：愿我主大卫王万岁！'),
('CUV', '列王纪上', 11, 1, 32, '大卫王又吩咐说：将祭司撒督、先知拿单、耶何耶大的儿子比拿雅召来！他们就都来到王面前。'),
('CUV', '列王纪上', 11, 1, 33, '王对他们说：要带领你们主的仆人，使我儿子所罗门骑我的骡子，送他下到基训；'),
('CUV', '列王纪上', 11, 1, 34, '在那里，祭司撒督和先知拿单要膏他作以色列的王；你们也要吹角，说：愿所罗门王万岁！'),
('CUV', '列王纪上', 11, 1, 35, '然后要跟随他上来，使他坐在我的位上，接续我作王。我已立他作以色列和犹大的君。'),
('CUV', '列王纪上', 11, 1, 36, '耶何耶大的儿子比拿雅对王说：阿们！愿耶和华─我主我王的神也这样命定。'),
('CUV', '列王纪上', 11, 1, 37, '耶和华怎样与我主我王同在，愿他照样与所罗门同在，使他的国位比我主大卫王的国位更大。'),
('CUV', '列王纪上', 11, 1, 38, '于是，祭司撒督、先知拿单、耶何耶大的儿子比拿雅，和基利提人、比利提人都下去使所罗门骑大卫王的骡子，将他送到基训。'),
('CUV', '列王纪上', 11, 1, 39, '祭司撒督就从帐幕中取了盛膏油的角来，用膏膏所罗门。人就吹角，众民都说：愿所罗门王万岁！'),
('CUV', '列王纪上', 11, 1, 40, '众民跟随他上来，且吹笛，大大欢呼，声音震地。'),
('CUV', '列王纪上', 11, 1, 41, '亚多尼雅和所请的众客筵宴方毕，听见这声音；约押听见角声就说：城中为何有这响呢？'),
('CUV', '列王纪上', 11, 1, 42, '他正说话的时候，祭司亚比亚他的儿子约拿单来了。亚多尼雅对他说：进来罢！你是个忠义的人，必是报好信息。'),
('CUV', '列王纪上', 11, 1, 43, '约拿单对亚多尼雅说：我们的主大卫王诚然立所罗门为王了。'),
('CUV', '列王纪上', 11, 1, 44, '王差遣祭司撒督、先知拿单、耶何耶大的儿子比拿雅，和基利提人、比利提人都去使所罗门骑王的骡子。'),
('CUV', '列王纪上', 11, 1, 45, '祭司撒督和先知拿单在基训已经膏他作王。众人都从那里欢呼著上来，声音使城震动，这就是你们所听见的声音；'),
('CUV', '列王纪上', 11, 1, 46, '并且所罗门登了国位。'),
('CUV', '列王纪上', 11, 1, 47, '王的臣仆也来为我们的主大卫王祝福，说：愿王的神使所罗门的名比王的名更尊荣；使他的国位比王的国位更大。王就在床上屈身下拜。'),
('CUV', '列王纪上', 11, 1, 48, '王又说：耶和华─以色列的神是应当称颂的；因他赐我一人今日坐在我的位上，我也亲眼看见了。'),
('CUV', '列王纪上', 11, 1, 49, '亚多尼雅的众客听见这话就都惊惧，起来四散。'),
('CUV', '列王纪上', 11, 1, 50, '亚多尼雅惧怕所罗门，就起来，去抓住祭坛的角。'),
('CUV', '列王纪上', 11, 1, 51, '有人告诉所罗门说：亚多尼雅惧怕所罗门王，现在抓住祭坛的角，说：愿所罗门王今日向我起誓，必不用刀杀仆人。'),
('CUV', '列王纪上', 11, 1, 52, '所罗门说：他若作忠义的人，连一根头发也不致落在地上；他若行恶，必要死亡。'),
('CUV', '列王纪上', 11, 1, 53, '于是所罗门王差遣人，使亚多尼雅从坛上下来，他就来，向所罗门王下拜；所罗门对他说：你回家去罢！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪上', 11, 2, 1, '大卫的死期临近了，就嘱吩他儿子所罗门说：'),
('CUV', '列王纪上', 11, 2, 2, '我现在要走世人必走的路。所以，你当刚强，作大丈夫，'),
('CUV', '列王纪上', 11, 2, 3, '遵守耶和华─你神所吩咐的，照著摩西律法上所写的行主的道，谨守他的律例、诫命、典章、法度。这样，你无论做甚么事，不拘往何处去，尽都亨通。'),
('CUV', '列王纪上', 11, 2, 4, '耶和华必成就向我所应许的话说：你的子孙若谨慎自己的行为，尽心尽意诚诚实实地行在我面前，就不断人坐以色列的国位。'),
('CUV', '列王纪上', 11, 2, 5, '你知道洗鲁雅的儿子约押向我所行的，就是杀了以色列的两个元帅：尼珥的儿子押尼珥和益帖儿子亚玛撒。他在太平之时流这二人的血，如在争战之时一样，将这血染了腰间束的带和脚上穿的鞋。'),
('CUV', '列王纪上', 11, 2, 6, '所以你要照你的智慧行，不容他白头安然下阴间。'),
('CUV', '列王纪上', 11, 2, 7, '你当恩待基列人巴西莱的众子，使他们常与你同席吃饭；因为我躲避你哥哥押沙龙的时候，他们拿食物来迎接我。'),
('CUV', '列王纪上', 11, 2, 8, '在你这里有巴户琳的便雅悯人，基拉的儿子示每；我往玛哈念去的那日，他用狠毒的言语咒骂我，后来却下约但河迎接我，我就指著耶和华向他起誓说：我必不用刀杀你。'),
('CUV', '列王纪上', 11, 2, 9, '现在你不要以他为无罪。你是聪明人，必知道怎样待他，使他白头见杀，流血下到阴间。'),
('CUV', '列王纪上', 11, 2, 10, '大卫与他列祖同睡，葬在大卫城。'),
('CUV', '列王纪上', 11, 2, 11, '大卫作以色列王四十年：在希伯仑作王七年，在耶路撒冷作王三十三年。'),
('CUV', '列王纪上', 11, 2, 12, '所罗门坐他父亲大卫的位，他的国甚是坚固。'),
('CUV', '列王纪上', 11, 2, 13, '哈及的儿子亚多尼雅去见所罗门的母亲拔示巴，拔示巴问他说：你来是为平安么？回答说：是为平安；'),
('CUV', '列王纪上', 11, 2, 14, '又说：我有话对你说。拔示巴说：你说罢。'),
('CUV', '列王纪上', 11, 2, 15, '亚多尼雅说：你知道国原是归我的，以色列众人也都仰望我作王，不料，国反归了我兄弟，因他得国是出乎耶和华。'),
('CUV', '列王纪上', 11, 2, 16, '现在我有一件事求你，望你不要推辞。拔示巴说：你说罢。'),
('CUV', '列王纪上', 11, 2, 17, '他说：求你请所罗门王将书念的女子亚比煞赐我为妻，因他必不推辞你。'),
('CUV', '列王纪上', 11, 2, 18, '拔示巴说：好，我必为你对王提说。'),
('CUV', '列王纪上', 11, 2, 19, '于是，拔示巴去见所罗门王，要为亚多尼雅提说；王起来迎接，向他下拜，就坐在位上，吩咐人为王母设一座位，他便坐在王的右边。'),
('CUV', '列王纪上', 11, 2, 20, '拔示巴说：我有一件小事求你，望你不要推辞。王说：请母亲说，我必不推辞。'),
('CUV', '列王纪上', 11, 2, 21, '拔示巴说：求你将书念的女子亚比煞赐给你哥哥亚多尼雅为妻。'),
('CUV', '列王纪上', 11, 2, 22, '所罗门王对他母亲说：为何单替他求书念的女子亚比煞呢？也可以为他求国罢！他是我的哥哥，他有祭司亚比亚他和洗鲁雅的儿子约押为辅佐。'),
('CUV', '列王纪上', 11, 2, 23, '所罗门王就指著耶和华起誓说：亚多尼雅这话是自己送命，不然，愿神重重地降罚与我。'),
('CUV', '列王纪上', 11, 2, 24, '耶和华坚立我，使我坐在父亲大卫的位上，照著所应许的话为我建立家室；现在我指著永生的耶和华起誓，亚多尼雅今日必被治死。'),
('CUV', '列王纪上', 11, 2, 25, '于是所罗门王差遣耶何耶大的儿子比拿雅，将亚多尼雅杀死。'),
('CUV', '列王纪上', 11, 2, 26, '王对祭司亚比亚他说：你回亚拿突归自己的田地去罢！你本是该死的，但因你在我父亲大卫面前抬过主耶和华的约柜，又与我父亲同受一切苦难，所以我今日不将你杀死。'),
('CUV', '列王纪上', 11, 2, 27, '所罗门就革除亚比亚他，不许他作耶和华的祭司。这样，便应验耶和华在示罗论以利家所说的话。'),
('CUV', '列王纪上', 11, 2, 28, '约押虽然没有归从押沙龙，却归从了亚多尼雅。他听见这风声，就逃到耶和华的帐幕，抓住祭坛的角。'),
('CUV', '列王纪上', 11, 2, 29, '有人告诉所罗门王说：约押逃到耶和华的帐幕，现今在祭坛的旁边。所罗门就差遣耶何耶大的儿子比拿雅，说你去将他杀死。'),
('CUV', '列王纪上', 11, 2, 30, '比拿雅来到耶和华的帐幕，对约押说：王吩咐说，你出来罢！他说：我不出去，我要死在这里。比拿雅就去回复王，说约押如此如此回答我。'),
('CUV', '列王纪上', 11, 2, 31, '王说：你可以照著他的话行，杀死他，将他葬埋，好叫约押流无辜人血的罪不归我和我的父家了。'),
('CUV', '列王纪上', 11, 2, 32, '耶和华必使约押流人血的罪归到他自己的头上；因为他用刀杀了两个比他又义又好的人，就是以色列元帅尼珥的儿子押尼珥和犹大元帅益帖的儿子亚玛撒，我父亲大卫却不知道。'),
('CUV', '列王纪上', 11, 2, 33, '故此，流这二人血的罪必归到约押和他后裔的头上，直到永远；惟有大卫和他的后裔，并他的家与国，必从耶和华那里得平安，直到永远。'),
('CUV', '列王纪上', 11, 2, 34, '于是耶何耶大的儿子比拿雅上去，将约押杀死，葬在旷野约押自己的坟墓(原文作房屋)里。'),
('CUV', '列王纪上', 11, 2, 35, '王就立耶何耶大的儿子比拿雅作元帅，代替约押，又使祭司撒督代替亚比亚他。'),
('CUV', '列王纪上', 11, 2, 36, '王差遣人将示每召来，对他说：你要在耶路撒冷建造房屋居住，不可出来往别处去。'),
('CUV', '列王纪上', 11, 2, 37, '你当确实地知道，你何日出来过汲沦溪，何日必死！你的罪(原文作血)必归到自己的头上。'),
('CUV', '列王纪上', 11, 2, 38, '示每对王说：这话甚好！我主我王怎样说，仆人必怎样行。于是示每多日住在耶路撒冷。'),
('CUV', '列王纪上', 11, 2, 39, '过了三年，示每的两个仆人逃到迦特王玛迦的儿子亚吉那里去。有人告诉示每说：你的仆人在迦特。'),
('CUV', '列王纪上', 11, 2, 40, '示每起来，备上驴，往迦特到亚吉那里去找他的仆人，就从迦特带他仆人回来。'),
('CUV', '列王纪上', 11, 2, 41, '有人告诉所罗门说：示每出耶路撒冷往迦特去，回来了。'),
('CUV', '列王纪上', 11, 2, 42, '王就差遣人将示每召了来，对他说：我岂不是叫你指著耶和华起誓，并且警戒你说你当确实地知道，你哪日出来往别处去，那日必死么？你也对我说：这话甚好，我必听从。'),
('CUV', '列王纪上', 11, 2, 43, '现在你为何不遵守你指著耶和华起的誓和我所吩咐你的命令呢？'),
('CUV', '列王纪上', 11, 2, 44, '王又对示每说：你向我父亲大卫所行的一切恶事，你自己心里也知道，所以耶和华必使你的罪恶归到自己的头上；'),
('CUV', '列王纪上', 11, 2, 45, '惟有所罗门王必得福，并且大卫的国位必在耶和华面前坚定，直到永远。'),
('CUV', '列王纪上', 11, 2, 46, '于是王吩咐耶何耶大的儿子比拿雅，他就去杀死示每。这样，便坚定了所罗门的国位。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪上', 11, 3, 1, '所罗门与埃及王法老结亲，娶了法老的女儿为妻，接他进入大卫城，直等到造完了自己的宫和耶和华的殿，并耶路撒冷周围的城墙。'),
('CUV', '列王纪上', 11, 3, 2, '当那些日子，百姓仍在邱坛献祭，因为还没有为耶和华的名建殿。'),
('CUV', '列王纪上', 11, 3, 3, '所罗门爱耶和华，遵行他父亲大卫的律例，只是还在邱坛献祭烧香。'),
('CUV', '列王纪上', 11, 3, 4, '所罗门王上基遍去献祭；因为在那里有极大(或作出名)的邱坛，他在那坛上献一千牺牲作燔祭。'),
('CUV', '列王纪上', 11, 3, 5, '在基遍，夜间梦中，耶和华向所罗门显现，对他说：你愿我赐你甚么？你可以求。'),
('CUV', '列王纪上', 11, 3, 6, '所罗门说：你仆人─我父亲大卫用诚实、公义、正直的心行在你面前，你就向他大施恩典，又为他存留大恩，赐他一个儿子坐在他的位上，正如今日一样。'),
('CUV', '列王纪上', 11, 3, 7, '耶和华─我的神啊，如今你使仆人接续我父亲大卫作王；但我是幼童，不知道应当怎样出入。'),
('CUV', '列王纪上', 11, 3, 8, '仆人住在你所拣选的民中，这民多得不可胜数。'),
('CUV', '列王纪上', 11, 3, 9, '所以求你赐我智慧，可以判断你的民，能辨别是非。不然，谁能判断这众多的民呢？'),
('CUV', '列王纪上', 11, 3, 10, '所罗门因为求这事，就蒙主喜悦。'),
('CUV', '列王纪上', 11, 3, 11, '神对他说：你既然求这事，不为自己求寿、求富，也不求灭绝你仇敌的性命，单求智慧可以听讼，'),
('CUV', '列王纪上', 11, 3, 12, '我就应允你所求的，赐你聪明智慧，甚至在你以前没有像你的，在你以后也没有像你的。'),
('CUV', '列王纪上', 11, 3, 13, '你所没有求的，我也赐给你，就是富足、尊荣，使你在世的日子，列王中没有一个能比你的。'),
('CUV', '列王纪上', 11, 3, 14, '你若效法你父亲大卫，遵行我的道，谨守我的律例、诫命，我必使你长寿。'),
('CUV', '列王纪上', 11, 3, 15, '所罗门醒了，不料是个梦。他就回到耶路撒冷，站在耶和华的约柜前，献燔祭和平安祭，又为他众臣仆设摆筵席。'),
('CUV', '列王纪上', 11, 3, 16, '一日，有两个妓女来，站在王面前。'),
('CUV', '列王纪上', 11, 3, 17, '一个说：我主啊，我和这妇人同住一房；他在房中的时候，我生了一个男孩。'),
('CUV', '列王纪上', 11, 3, 18, '我生孩子后第三日，这妇人也生了孩子。我们是同住的，除了我们二人之外，房中再没有别人。'),
('CUV', '列王纪上', 11, 3, 19, '夜间，这妇人睡著的时候，压死了他的孩子。'),
('CUV', '列王纪上', 11, 3, 20, '他半夜起来，趁我睡著，从我旁边把我的孩子抱去，放在他怀里，将他的死孩子放在我怀里。'),
('CUV', '列王纪上', 11, 3, 21, '天要亮的时候，我起来要给我的孩子吃奶，不料，孩子死了；及至天亮，我细细地察看，不是我所生的孩子。'),
('CUV', '列王纪上', 11, 3, 22, '那妇人说：不然，活孩子是我的，死孩子是你的。这妇人说：不然，死孩子是你的，活孩子是我的。他们在王面前如此争论。'),
('CUV', '列王纪上', 11, 3, 23, '王说：这妇人说活孩子是我的，死孩子是你的，那妇人说不然，死孩子是你的，活孩子是我的，'),
('CUV', '列王纪上', 11, 3, 24, '就吩咐说：拿刀来！人就拿刀来。'),
('CUV', '列王纪上', 11, 3, 25, '王说：将活孩子劈成两半，一半给那妇人，一半给这妇人。'),
('CUV', '列王纪上', 11, 3, 26, '活孩子的母亲为自己的孩子心里急痛，就说：求我主将活孩子给那妇人罢，万不可杀他！那妇人说：这孩子也不归我，也不归你，把他劈了罢！'),
('CUV', '列王纪上', 11, 3, 27, '王说：将活孩子给这妇人，万不可杀他；这妇人实在是他的母亲。'),
('CUV', '列王纪上', 11, 3, 28, '以色列众人听见王这样判断，就都敬畏他；因为见他心里有神的智慧，能以断案。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪上', 11, 4, 1, '所罗门作以色列众人的王。'),
('CUV', '列王纪上', 11, 4, 2, '他的臣子记在下面：撒督的儿子亚撒利雅作祭司，'),
('CUV', '列王纪上', 11, 4, 3, '示沙的两个儿子以利何烈、亚希亚作书记，亚希律的儿子约沙法作史官，'),
('CUV', '列王纪上', 11, 4, 4, '耶何耶大的儿子比拿雅作元帅，撒督和亚比亚他作祭司长，'),
('CUV', '列王纪上', 11, 4, 5, '拿单的儿子亚撒利雅作众吏长，王的朋友拿单的儿子撒布得作领袖，'),
('CUV', '列王纪上', 11, 4, 6, '亚希煞作家宰，亚比大的儿子亚多尼兰掌管服苦的人。'),
('CUV', '列王纪上', 11, 4, 7, '所罗门在以色列全地立了十二个官吏，使他们供给王和王家的食物，每年各人供给一月。'),
('CUV', '列王纪上', 11, 4, 8, '他们的名字记在下面：在以法莲山地有便户珥；'),
('CUV', '列王纪上', 11, 4, 9, '在玛迦斯、沙宾、伯示麦、以伦伯哈南有便底甲；'),
('CUV', '列王纪上', 11, 4, 10, '在亚鲁泊有便希悉，他管理梭哥和希弗全地；'),
('CUV', '列王纪上', 11, 4, 11, '在多珥山冈(或作全境)有便亚比拿达，他娶了所罗门的女儿他法为妻；'),
('CUV', '列王纪上', 11, 4, 12, '在他纳和米吉多，并靠近撒拉他拿、耶斯列下边的伯善全地，从伯善到亚伯米何拉直到约念之外，有亚希律的儿子巴拿；'),
('CUV', '列王纪上', 11, 4, 13, '在基列的拉末有便基别，他管理在基列的玛拿西子孙睚珥的城邑，巴珊的亚珥歌伯地的大城六十座，都有城墙和铜闩；'),
('CUV', '列王纪上', 11, 4, 14, '在玛哈念有易多的儿子亚希拿达；'),
('CUV', '列王纪上', 11, 4, 15, '在拿弗他利有亚希玛斯，他也娶了所罗门的一个女儿巴实抹为妻；'),
('CUV', '列王纪上', 11, 4, 16, '在亚设和亚禄有户筛的儿子巴拿；'),
('CUV', '列王纪上', 11, 4, 17, '在以萨迦有帕路亚的儿子约沙法；'),
('CUV', '列王纪上', 11, 4, 18, '在便雅悯有以拉的儿子示每；'),
('CUV', '列王纪上', 11, 4, 19, '在基列地，就是从前属亚摩利王西宏和巴珊王噩之地，有乌利的儿子基别一人管理。'),
('CUV', '列王纪上', 11, 4, 20, '犹大人和以色列人如同海边的沙那样多，都吃喝快乐。'),
('CUV', '列王纪上', 11, 4, 21, '所罗门统管诸国，从大河到非利士地，直到埃及的边界。所罗门在世的日子，这些国都进贡服事他。'),
('CUV', '列王纪上', 11, 4, 22, '所罗门每日所用的食物：细面三十歌珥，粗面六十歌珥，'),
('CUV', '列王纪上', 11, 4, 23, '肥牛十只，草场的牛二十只，羊一百只，还有鹿、羚羊、麃子，并肥禽。'),
('CUV', '列王纪上', 11, 4, 24, '所罗门管理大河西边的诸王，以及从提弗萨直到迦萨的全地，四境尽都平安。'),
('CUV', '列王纪上', 11, 4, 25, '所罗门在世的日子，从但到别是巴的犹大人和以色列人都在自己的葡萄树下和无花果树下安然居住。'),
('CUV', '列王纪上', 11, 4, 26, '所罗门有套车的马四万，还有马兵一万二千。'),
('CUV', '列王纪上', 11, 4, 27, '那十二个官吏各按各月供给所罗门王，并一切与他同席之人的食物，一无所缺。'),
('CUV', '列王纪上', 11, 4, 28, '众人各按各分，将养马与快马的大麦和干草送到官吏那里。'),
('CUV', '列王纪上', 11, 4, 29, '神赐给所罗门极大的智慧聪明和广大的心，如同海沙不可测量。'),
('CUV', '列王纪上', 11, 4, 30, '所罗门的智慧超过东方人和埃及人的一切智慧。'),
('CUV', '列王纪上', 11, 4, 31, '他的智慧胜过万人，胜过以斯拉人以探，并玛曷的儿子希幔、甲各、达大的智慧。他的名声传扬在四围的列国。'),
('CUV', '列王纪上', 11, 4, 32, '他作箴言三千句，诗歌一千零五首。'),
('CUV', '列王纪上', 11, 4, 33, '他讲论草木，自利巴嫩的香柏树直到墙上长的牛膝草，又讲论飞禽走兽、昆虫水族。'),
('CUV', '列王纪上', 11, 4, 34, '天下列王听见所罗门的智慧，就都差人来听他的智慧话。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪上', 11, 5, 1, '推罗王希兰，平素爱大卫；他听见以色列人膏所罗门，接续他父亲作王，就差遣臣仆来见他。'),
('CUV', '列王纪上', 11, 5, 2, '所罗门也差遣人去见希兰，说：'),
('CUV', '列王纪上', 11, 5, 3, '你知道我父亲大卫因四围的争战，不能为耶和华─他神的名建殿，直等到耶和华使仇敌都服在他脚下。'),
('CUV', '列王纪上', 11, 5, 4, '现在耶和华─我的神使我四围平安，没有仇敌，没有灾祸。'),
('CUV', '列王纪上', 11, 5, 5, '我定意要为耶和华─我神的名建殿，是照耶和华应许我父亲大卫的话说：我必使你儿子接续你坐你的位，他必为我的名建殿。'),
('CUV', '列王纪上', 11, 5, 6, '所以求你吩咐你的仆人在利巴嫩为我砍伐香柏木，我的仆人也必帮助他们，我必照你所定的，给你仆人的工价；因为你知道，在我们中间没有人像西顿人善于砍伐树木。'),
('CUV', '列王纪上', 11, 5, 7, '希兰听见所罗门的话，就甚喜悦，说：今日应当称颂耶和华；因他赐给大卫一个有智慧的儿子，治理这众多的民。'),
('CUV', '列王纪上', 11, 5, 8, '希兰打发人去见所罗门，说：你差遣人向我所提的那事，我都听见了；论到香柏木和松木，我必照你的心愿而行。'),
('CUV', '列王纪上', 11, 5, 9, '我的仆人必将这木料从利巴嫩运到海里，扎成筏子，浮海运到你所指定我的地方，在那里拆开，你就可以收取；你也要成全我的心愿，将食物给我的家。'),
('CUV', '列王纪上', 11, 5, 10, '于是希兰照著所罗门所要的，给他香柏木和松木；'),
('CUV', '列王纪上', 11, 5, 11, '所罗门给希兰麦子二万歌珥，清油二十歌珥，作他家的食物。所罗门每年都是这样给希兰。'),
('CUV', '列王纪上', 11, 5, 12, '耶和华照著所应许的赐智慧给所罗门。希兰与所罗门和好，彼此立约。'),
('CUV', '列王纪上', 11, 5, 13, '所罗门王从以色列人中挑取服苦的人共有三万，'),
('CUV', '列王纪上', 11, 5, 14, '派他们轮流每月一万人上利巴嫩去；一个月在利巴嫩，两个月在家里。亚多尼兰掌管他们。'),
('CUV', '列王纪上', 11, 5, 15, '所罗门用七万扛抬的，八万在山上凿石头的。'),
('CUV', '列王纪上', 11, 5, 16, '此外，所罗门用三千三百督工的，监管工人。'),
('CUV', '列王纪上', 11, 5, 17, '王下令，人就凿出又大又宝贵的石头来，用以立殿的根基。'),
('CUV', '列王纪上', 11, 5, 18, '所罗门的匠人和希兰的匠人，并迦巴勒人，都将石头凿好，预备木料和石头建殿。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪上', 11, 6, 1, '以色列人出埃及地后四百八十年，所罗门作以色列王第四年西弗月，就是二月，开工建造耶和华的殿。'),
('CUV', '列王纪上', 11, 6, 2, '所罗门王为耶和华所建的殿，长六十肘，宽二十肘，高三十肘。'),
('CUV', '列王纪上', 11, 6, 3, '殿前的廊子长二十肘，与殿的宽窄一样，阔十肘；'),
('CUV', '列王纪上', 11, 6, 4, '又为殿做了严紧的窗櫺。'),
('CUV', '列王纪上', 11, 6, 5, '靠著殿墙，围著外殿内殿，造了三层旁屋；'),
('CUV', '列王纪上', 11, 6, 6, '下层宽五肘，中层宽六肘，上层宽七肘。殿外旁屋的梁木搁在殿墙坎上，免得插入殿墙。'),
('CUV', '列王纪上', 11, 6, 7, '建殿是用山中凿成的石头。建殿的时候，锤子、斧子，和别样铁器的响声都没有听见。'),
('CUV', '列王纪上', 11, 6, 8, '在殿右边当中的旁屋有门，门内有旋螺的楼梯，可以上到第二层，从第二层可以上到第三层。'),
('CUV', '列王纪上', 11, 6, 9, '所罗门建殿，安置香柏木的栋梁，又用香柏木板遮盖。'),
('CUV', '列王纪上', 11, 6, 10, '靠著殿所造的旁屋，每层高五肘，香柏木的栋梁搁在殿墙坎上。'),
('CUV', '列王纪上', 11, 6, 11, '耶和华的话临到所罗门说：'),
('CUV', '列王纪上', 11, 6, 12, '论到你所建的这殿，你若遵行我的律例，谨守我的典章，遵从我的一切诫命，我必向你应验我所应许你父亲大卫的话。'),
('CUV', '列王纪上', 11, 6, 13, '我必住在以色列人中间，并不丢弃我民以色列。'),
('CUV', '列王纪上', 11, 6, 14, '所罗门建造殿宇。'),
('CUV', '列王纪上', 11, 6, 15, '殿里面用香柏木板贴墙，从地到棚顶都用木板遮蔽，又用松木板铺地。'),
('CUV', '列王纪上', 11, 6, 16, '内殿，就是至圣所，长二十肘，从地到棚顶用香柏木板遮蔽(或作隔断)。'),
('CUV', '列王纪上', 11, 6, 17, '内殿前的外殿，长四十肘。'),
('CUV', '列王纪上', 11, 6, 18, '殿里一点石头都不显露，一概用香柏木遮蔽；上面刻著野瓜和初开的花。'),
('CUV', '列王纪上', 11, 6, 19, '殿里预备了内殿，好安放耶和华的约柜。'),
('CUV', '列王纪上', 11, 6, 20, '内殿长二十肘，宽二十肘，高二十肘，墙面都贴上精金；又用香柏木做坛，包上精金。'),
('CUV', '列王纪上', 11, 6, 21, '所罗门用精金贴了殿内的墙，又用金链子挂在内殿前门扇，用金包裹。'),
('CUV', '列王纪上', 11, 6, 22, '全殿都贴上金子，直到贴完；内殿前的坛，也都用金包裹。'),
('CUV', '列王纪上', 11, 6, 23, '他用橄榄木做两个基路伯，各高十肘，安在内殿。'),
('CUV', '列王纪上', 11, 6, 24, '这一个基路伯有两个翅膀，各长五肘，从这翅膀尖到那翅膀尖共有十肘；'),
('CUV', '列王纪上', 11, 6, 25, '那一个基路伯的两个翅膀也是十肘，两个基路伯的尺寸、形像都是一样。'),
('CUV', '列王纪上', 11, 6, 26, '这基路伯高十肘，那基路伯也是如此。'),
('CUV', '列王纪上', 11, 6, 27, '他将两个基路伯安在内殿里；基路伯的翅膀是张开的，这基路伯的一个翅膀挨著这边的墙，那基路伯的一个翅膀挨著那边的墙，里边的两个翅膀在殿中间彼此相接；'),
('CUV', '列王纪上', 11, 6, 28, '又用金子包裹二基路伯。'),
('CUV', '列王纪上', 11, 6, 29, '内殿、外殿周围的墙上都刻著基路伯、棕树，和初开的花。'),
('CUV', '列王纪上', 11, 6, 30, '内殿、外殿的地板都贴上金子。'),
('CUV', '列王纪上', 11, 6, 31, '又用橄榄木制造内殿的门扇、门楣、门框；门口有墙的五分之一。'),
('CUV', '列王纪上', 11, 6, 32, '在橄榄木做的两门扇上刻著基路伯、棕树，和初开的花，都贴上金子。'),
('CUV', '列王纪上', 11, 6, 33, '又用橄榄木制造外殿的门框，门口有墙的四分之一。'),
('CUV', '列王纪上', 11, 6, 34, '用松木做门两扇。这扇分两扇，是折叠的；那扇分两扇；也是折叠的。'),
('CUV', '列王纪上', 11, 6, 35, '上面刻著基路伯、棕树，和初开的花，都用金子贴了。'),
('CUV', '列王纪上', 11, 6, 36, '他又用凿成的石头三层、香柏木一层建筑内院。'),
('CUV', '列王纪上', 11, 6, 37, '所罗门在位第四年西弗月，立了耶和华殿的根基。'),
('CUV', '列王纪上', 11, 6, 38, '到十一年布勒月，就是八月，殿和一切属殿的都按著样式造成。他建殿的工夫共有七年。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪上', 11, 7, 1, '所罗门为自己建造宫室，十三年方才造成；'),
('CUV', '列王纪上', 11, 7, 2, '又建造利巴嫩林宫，长一百肘，宽五十肘，高三十肘，有香柏木柱三(原文作四)行，柱上有香柏木柁梁。'),
('CUV', '列王纪上', 11, 7, 3, '其上以香柏木为盖，每行柱子十五根，共有四十五根。'),
('CUV', '列王纪上', 11, 7, 4, '有窗户三层，窗与窗相对。'),
('CUV', '列王纪上', 11, 7, 5, '所有的门框都是厚木见方的，有窗户三层，窗与窗相对。'),
('CUV', '列王纪上', 11, 7, 6, '并建造有柱子的廊子，长五十肘，宽三十肘；在这廊前又有廊子，廊外有柱子和台阶。'),
('CUV', '列王纪上', 11, 7, 7, '又建造一廊，其中设立审判的座位，这廊从地到顶都用香柏木遮蔽。'),
('CUV', '列王纪上', 11, 7, 8, '廊后院内有所罗门住的宫室；工作与这工作相同。所罗门又为所娶法老的女儿建造一宫，做法与这廊子一样。'),
('CUV', '列王纪上', 11, 7, 9, '建造这一切所用的石头都是宝贵的，是按著尺寸凿成的，是用锯里外锯齐的；从根基直到檐石，从外头直到大院，都是如此。'),
('CUV', '列王纪上', 11, 7, 10, '根基是宝贵的大石头，有长十肘的，有长八肘的；'),
('CUV', '列王纪上', 11, 7, 11, '上面有香柏木和按著尺寸凿成宝贵的石头。'),
('CUV', '列王纪上', 11, 7, 12, '大院周围有凿成的石头三层、香柏木一层，都照耶和华殿的内院和殿廊的样式。'),
('CUV', '列王纪上', 11, 7, 13, '所罗门王差遣人往推罗去，将户兰召了来。'),
('CUV', '列王纪上', 11, 7, 14, '他是拿弗他利支派中一个寡妇的儿子，他父亲是推罗人，作铜匠的。户兰满有智慧、聪明、技能，善于各样铜作。他来到所罗门王那里，做王一切所要做的。'),
('CUV', '列王纪上', 11, 7, 15, '他制造两根铜柱，每根高十八肘，围十二肘。'),
('CUV', '列王纪上', 11, 7, 16, '又用铜铸了两个柱顶安在柱上，各高五肘。'),
('CUV', '列王纪上', 11, 7, 17, '柱顶上有装修的网子和拧成的炼索，每顶七个。'),
('CUV', '列王纪上', 11, 7, 18, '网子周围有两行石榴遮盖柱顶，两个柱顶都是如此。'),
('CUV', '列王纪上', 11, 7, 19, '廊子的柱顶径四肘，刻著百合花。'),
('CUV', '列王纪上', 11, 7, 20, '两柱顶的鼓肚上挨著网子，各有两行石榴环绕，两行共有二百。'),
('CUV', '列王纪上', 11, 7, 21, '他将两根柱子立在殿廊前头：右边立一根，起名叫雅斤；左边立一根，起名叫波阿斯。'),
('CUV', '列王纪上', 11, 7, 22, '在柱顶上刻著百合花。这样，造柱子的工就完毕了。'),
('CUV', '列王纪上', 11, 7, 23, '他又铸一个铜海，样式是圆的，高五肘，径十肘，围三十肘。'),
('CUV', '列王纪上', 11, 7, 24, '在海边之下，周围有野瓜的样式；每肘十瓜，共有两行，是铸海的时候铸上的。'),
('CUV', '列王纪上', 11, 7, 25, '有十二只铜牛驮海：三只向北，三只向西，三只向南，三只向东；海在牛上，牛尾都向内。'),
('CUV', '列王纪上', 11, 7, 26, '海厚一掌，边如杯边，又如百合花，可容二千罢特。'),
('CUV', '列王纪上', 11, 7, 27, '他用铜制造十个盆座，每座长四肘，宽四肘，高三肘。'),
('CUV', '列王纪上', 11, 7, 28, '座的造法是这样：四面都有心子，心子在边子当中，'),
('CUV', '列王纪上', 11, 7, 29, '心子上有狮子和牛，并基路伯；边上有小座，狮子和牛以下有垂下的璎珞。'),
('CUV', '列王纪上', 11, 7, 30, '每盆座有四个铜轮和铜轴。小座的四角上在盆以下，有铸成的盆架，其旁都有璎珞。'),
('CUV', '列王纪上', 11, 7, 31, '小座高一肘，口是圆的，仿佛座的样式，径一肘半，在口上有雕工，心子是方的，不是圆的。'),
('CUV', '列王纪上', 11, 7, 32, '四个轮子在心子以下，轮轴与座相连，每轮高一肘半。'),
('CUV', '列王纪上', 11, 7, 33, '轮的样式如同车轮；轴、辋、辐、毂都是铸的。'),
('CUV', '列王纪上', 11, 7, 34, '每座四角上都有盆架，是与座一同铸成的。'),
('CUV', '列王纪上', 11, 7, 35, '座上有圆架，高半肘；座上有撑子和心子，是与座一同铸的。'),
('CUV', '列王纪上', 11, 7, 36, '在撑子和心子上刻著基路伯、狮子，和棕树，周围有璎珞。'),
('CUV', '列王纪上', 11, 7, 37, '十个盆座都是这样，铸法、尺寸、样式相同。'),
('CUV', '列王纪上', 11, 7, 38, '又用铜制造十个盆，每盆可容四十罢特。盆径四肘，在那十座上，每座安设一盆。'),
('CUV', '列王纪上', 11, 7, 39, '五个安在殿门的右边，五个放在殿门的左边；又将海放在殿门的右旁，就是南边。'),
('CUV', '列王纪上', 11, 7, 40, '户兰又造了盆、铲子，和盘子。这样，他为所罗门王做完了耶和华殿的一切工。'),
('CUV', '列王纪上', 11, 7, 41, '所造的就是：两根柱子和柱上两个如球的顶；并两个盖柱顶的网子；'),
('CUV', '列王纪上', 11, 7, 42, '和四百石榴，安在两个网子上，每网两行，盖著两个柱上如球的顶；'),
('CUV', '列王纪上', 11, 7, 43, '十个座和其上的十个盆；'),
('CUV', '列王纪上', 11, 7, 44, '海和海下的十二只牛；'),
('CUV', '列王纪上', 11, 7, 45, '盆、铲子、盘子。这一切都是户兰给所罗门王用光亮的铜为耶和华的殿造成的，'),
('CUV', '列王纪上', 11, 7, 46, '是遵王命在约但平原、疏割和撒拉但中间藉胶泥铸成的。'),
('CUV', '列王纪上', 11, 7, 47, '这一切所罗门都没有过秤；因为甚多，铜的轻重也无法可查。'),
('CUV', '列王纪上', 11, 7, 48, '所罗门又造耶和华殿里的金坛和陈设饼的金桌子；'),
('CUV', '列王纪上', 11, 7, 49, '内殿前的精金灯台：右边五个，左边五个，并其上的金花、灯盏、蜡剪，'),
('CUV', '列王纪上', 11, 7, 50, '与精金的杯、盘、镊子、调羹、火鼎，以及至圣所、内殿的门枢，和外殿的门枢。'),
('CUV', '列王纪上', 11, 7, 51, '所罗门王做完了耶和华殿的一切工，就把他父大卫分别为圣的金银和器皿都带来放在耶和华殿的府库里。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪上', 11, 8, 1, '那时，所罗门将以色列的长老和各支派的首领，并以色列的族长，招聚到耶路撒冷，要把耶和华的约柜从大卫城─就是锡安─运上来。'),
('CUV', '列王纪上', 11, 8, 2, '以他念月，就是七月，在节前，以色列人都聚集到所罗门王那里。'),
('CUV', '列王纪上', 11, 8, 3, '以色列长老来到，祭司便抬起约柜，'),
('CUV', '列王纪上', 11, 8, 4, '祭司和利未人将耶和华的约柜运上来，又将会幕和会幕的一切圣器具都带上来。'),
('CUV', '列王纪上', 11, 8, 5, '所罗门王和聚集到他那里的以色列全会众，一同在约柜前献牛羊为祭，多得不可胜数。'),
('CUV', '列王纪上', 11, 8, 6, '祭司将耶和华的约柜抬进内殿，就是至圣所，放在两个基路伯的翅膀底下。'),
('CUV', '列王纪上', 11, 8, 7, '基路伯张著翅膀在约柜之上，遮掩约柜和抬柜的杠。'),
('CUV', '列王纪上', 11, 8, 8, '这杠甚长，杠头在内殿前的圣所可以看见，在殿外却不能看见，直到如今还在那里。'),
('CUV', '列王纪上', 11, 8, 9, '约柜里惟有两块石版，就是以色列人出埃及地后，耶和华与他们立约的时候摩西在何烈山所放的。除此以外，并无别物。'),
('CUV', '列王纪上', 11, 8, 10, '祭司从圣所出来的时候，有云充满耶和华的殿；'),
('CUV', '列王纪上', 11, 8, 11, '甚至祭司不能站立供职，因为耶和华的荣光充满了殿。'),
('CUV', '列王纪上', 11, 8, 12, '那时所罗门说：耶和华曾说，他必住在幽暗之处。'),
('CUV', '列王纪上', 11, 8, 13, '我已经建造殿宇作你的居所，为你永远的住处。'),
('CUV', '列王纪上', 11, 8, 14, '王转脸为以色列会众祝福，以色列会众就都站立。'),
('CUV', '列王纪上', 11, 8, 15, '所罗门说：耶和华─以色列的神是应当称颂的！因他亲口向我父大卫所应许的，也亲手成就了。'),
('CUV', '列王纪上', 11, 8, 16, '他说：自从我领我民以色列出埃及以来，我未曾在以色列各支派中选择一城建造殿宇─为我名的居所，但拣选大卫治理我民以色列。'),
('CUV', '列王纪上', 11, 8, 17, '所罗门说：我父大卫曾立意，要为耶和华─以色列神的名建殿。'),
('CUV', '列王纪上', 11, 8, 18, '耶和华却对我父大卫说：你立意为我的名建殿，这意思甚好。'),
('CUV', '列王纪上', 11, 8, 19, '只是你不可建殿，惟你所生的儿子必为我名建殿。'),
('CUV', '列王纪上', 11, 8, 20, '现在耶和华成就了他所应许的话，使我接续我父大卫坐以色列的国位，又为耶和华─以色列神的名建造了殿。'),
('CUV', '列王纪上', 11, 8, 21, '我也在其中为约柜预备一处。约柜内有耶和华的约，就是他领我们列祖出埃及地的时候，与他们所立的约。'),
('CUV', '列王纪上', 11, 8, 22, '所罗门当著以色列会众，站在耶和华的坛前，向天举手说：'),
('CUV', '列王纪上', 11, 8, 23, '耶和华─以色列的神啊，天上地下没有神可比你的！你向那尽心行在你面前的仆人守约施慈爱；'),
('CUV', '列王纪上', 11, 8, 24, '向你仆人─我父大卫所应许的话现在应验了。你亲口应许，亲手成就，正如今日一样。'),
('CUV', '列王纪上', 11, 8, 25, '耶和华─以色列的神啊，你所应许你仆人─我父大卫的话说：你的子孙若谨慎自己的行为，在我面前行事像你所行的一样，就不断人坐以色列的国位。现在求你应验这话。'),
('CUV', '列王纪上', 11, 8, 26, '以色列的神啊，求你成就向你仆人─我父大卫所应许的话。'),
('CUV', '列王纪上', 11, 8, 27, '神果真住在地上么？看哪，天和天上的天尚且不足你居住的，何况我所建的这殿呢？'),
('CUV', '列王纪上', 11, 8, 28, '惟求耶和华─我的神垂顾仆人的祷告祈求，俯听仆人今日在你面前的祈祷呼吁。'),
('CUV', '列王纪上', 11, 8, 29, '愿你昼夜看顾这殿，就是你应许立为你名的居所；求你垂听仆人向此处祷告的话。'),
('CUV', '列王纪上', 11, 8, 30, '你仆人和你民以色列向此处祈祷的时候，求你在天上你的居所垂听，垂听而赦免。'),
('CUV', '列王纪上', 11, 8, 31, '人若得罪邻舍，有人叫他起誓，他来到这殿在你的坛前起誓，'),
('CUV', '列王纪上', 11, 8, 32, '求你在天上垂听，判断你的仆人：定恶人有罪，照他所行的报应在他头上；定义人有理，照他的义赏赐他。'),
('CUV', '列王纪上', 11, 8, 33, '你的民以色列若得罪你，败在仇敌面前，又归向你，承认你的名，在这殿里祈求祷告，'),
('CUV', '列王纪上', 11, 8, 34, '求你在天上垂听，赦免你民以色列的罪，使他们归回你赐给他们列祖之地。'),
('CUV', '列王纪上', 11, 8, 35, '你的民因得罪你，你惩罚他们，使天闭塞不下雨；他们若向此处祷告，承认你的名，离开他们的罪，'),
('CUV', '列王纪上', 11, 8, 36, '求你在天上垂听，赦免你仆人以色列民的罪，将当行的善道指教他们，且降雨在你的地，就是你赐给你民为业之地。'),
('CUV', '列王纪上', 11, 8, 37, '国中若有饥荒、瘟疫、旱风、霉烂、蝗虫、蚂蚱，或有仇敌犯境围困城邑，无论遭遇甚么灾祸疾病，'),
('CUV', '列王纪上', 11, 8, 38, '你的民以色列，或是众人，或是一人，自觉有罪(原文作灾)，向这殿举手，无论祈求甚么，祷告甚么，'),
('CUV', '列王纪上', 11, 8, 39, '求你在天上你的居所垂听赦免。你是知道人心的，要照各人所行的待他们（惟有你知道世人的心），'),
('CUV', '列王纪上', 11, 8, 40, '使他们在你赐给我们列祖之地上一生一世敬畏你。'),
('CUV', '列王纪上', 11, 8, 41, '论到不属你民以色列的外邦人，为你名从远方而来，'),
('CUV', '列王纪上', 11, 8, 42, '（他们听人论说你的大名和大能的手，并伸出来的膀臂）向这殿祷告，'),
('CUV', '列王纪上', 11, 8, 43, '求你在天上你的居所垂听，照著外邦人所祈求的而行，使天下万民都认识你的名，敬畏你像你的民以色列一样；又使他们知道我建造的这殿是称为你名下的。'),
('CUV', '列王纪上', 11, 8, 44, '你的民若奉你的差遣，无论往何处去与仇敌争战，向耶和华所选择的城与我为你名所建造的殿祷告，'),
('CUV', '列王纪上', 11, 8, 45, '求你在天上垂听他们的祷告祈求，使他们得胜。'),
('CUV', '列王纪上', 11, 8, 46, '你的民若得罪你（世上没有不犯罪的人），你向他们发怒，将他们交给仇敌掳到仇敌之地，或远或近，'),
('CUV', '列王纪上', 11, 8, 47, '他们若在掳到之地想起罪来，回心转意，恳求你说：我们有罪了，我们悖逆了，我们作恶了；'),
('CUV', '列王纪上', 11, 8, 48, '他们若在掳到之地尽心尽性归服你，又向自己的地，就是你赐给他们列祖之地和你所选择的城，并我为你名所建造的殿祷告，'),
('CUV', '列王纪上', 11, 8, 49, '求你在天上你的居所垂听他们的祷告祈求，为他们伸冤；'),
('CUV', '列王纪上', 11, 8, 50, '饶恕得罪你的民，赦免他们的一切过犯，使他们在掳他们的人面前蒙怜恤。'),
('CUV', '列王纪上', 11, 8, 51, '因为他们是你的子民，你的产业，是你从埃及领出来脱离铁炉的。'),
('CUV', '列王纪上', 11, 8, 52, '愿你的眼目看顾仆人，听你民以色列的祈求，无论何时向你祈求，愿你垂听。'),
('CUV', '列王纪上', 11, 8, 53, '主耶和华啊，你将他们从地上的万民中分别出来作你的产业，是照你领我们列祖出埃及的时候，藉你仆人摩西所应许的话。'),
('CUV', '列王纪上', 11, 8, 54, '所罗门在耶和华的坛前屈膝跪著，向天举手，在耶和华面前祷告祈求已毕，就起来，'),
('CUV', '列王纪上', 11, 8, 55, '站著，大声为以色列全会众祝福，说：'),
('CUV', '列王纪上', 11, 8, 56, '耶和华是应当称颂的！因为他照著一切所应许的赐平安给他的民以色列人，凡藉他仆人摩西应许赐福的话，一句都没有落空。'),
('CUV', '列王纪上', 11, 8, 57, '愿耶和华─我们的神与我们同在，像与我们列祖同在一样，不撇下我们，不丢弃我们，'),
('CUV', '列王纪上', 11, 8, 58, '使我们的心归向他，遵行他的道，谨守他吩咐我们列祖的诫命、律例、典章。'),
('CUV', '列王纪上', 11, 8, 59, '我在耶和华面前祈求的这些话，愿耶和华─我们的神昼夜垂念，每日为他仆人与他民以色列伸冤，'),
('CUV', '列王纪上', 11, 8, 60, '使地上的万民都知道惟独耶和华是神，并无别神。'),
('CUV', '列王纪上', 11, 8, 61, '所以你们当向耶和华─我们的神存诚实的心，遵行他的律例，谨守他的诫命，至终如今日一样。'),
('CUV', '列王纪上', 11, 8, 62, '王和以色列众民一同在耶和华面前献祭。'),
('CUV', '列王纪上', 11, 8, 63, '所罗门向耶和华献平安祭，用牛二万二千，羊十二万。这样，王和以色列众民为耶和华的殿行奉献之礼。'),
('CUV', '列王纪上', 11, 8, 64, '当日，王因耶和华殿前的铜坛太小，容不下燔祭、素祭，和平安祭牲的脂油，便将耶和华殿前院子当中分别为圣，在那里献燔祭、素祭，和平安祭牲的脂油。'),
('CUV', '列王纪上', 11, 8, 65, '那时，所罗门和以色列众人，就是从哈马口直到埃及小河所有的以色列人，都聚集成为大会，在耶和华─我们的神面前守节七日又七日，共十四日。'),
('CUV', '列王纪上', 11, 8, 66, '第八日，王遣散众民；他们都为王祝福。因见耶和华向他仆人大卫和他民以色列所施的一切恩惠，就都心中喜乐，各归各家去了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪上', 11, 9, 1, '所罗门建造耶和华殿和王宫，并一切所愿意建造的都完毕了，'),
('CUV', '列王纪上', 11, 9, 2, '耶和华就二次向所罗门显现，如先前在基遍向他显现一样，'),
('CUV', '列王纪上', 11, 9, 3, '对他说：你向我所祷告祈求的，我都应允了。我已将你所建的这殿分别为圣，使我的名永远在其中；我的眼、我的心也必常在那里。'),
('CUV', '列王纪上', 11, 9, 4, '你若效法你父大卫，存诚实正直的心行在我面前，遵行我一切所吩咐你的，谨守我的律例典章，'),
('CUV', '列王纪上', 11, 9, 5, '我就必坚固你的国位在以色列中，直到永远，正如我应许你父大卫说：你的子孙必不断人坐以色列的国位。'),
('CUV', '列王纪上', 11, 9, 6, '倘若你们和你们的子孙转去不跟从我，不守我指示你们的诫命律例，去事奉敬拜别神，'),
('CUV', '列王纪上', 11, 9, 7, '我就必将以色列人从我赐给他们的地上剪除，并且我为己名所分别为圣的殿也必舍弃不顾，使以色列人在万民中作笑谈，被讥诮。'),
('CUV', '列王纪上', 11, 9, 8, '这殿虽然甚高，将来经过的人必惊讶、嗤笑，说：耶和华为何向这地和这殿如此行呢？'),
('CUV', '列王纪上', 11, 9, 9, '人必回答说：是因此地的人离弃领他们列祖出埃及地之耶和华─他们的神，去亲近别神，事奉敬拜他，所以耶和华使这一切灾祸临到他们。'),
('CUV', '列王纪上', 11, 9, 10, '所罗门建造耶和华殿和王宫，这两所二十年才完毕了。'),
('CUV', '列王纪上', 11, 9, 11, '推罗王希兰曾照所罗门所要的，资助他香柏木、松木，和金子；所罗门王就把加利利地的二十座城给了希兰。'),
('CUV', '列王纪上', 11, 9, 12, '希兰从推罗出来，察看所罗门给他的城邑，就不喜悦，'),
('CUV', '列王纪上', 11, 9, 13, '说：我兄啊，你给我的是甚么城邑呢？他就给这城邑之地起名叫迦步勒，直到今日。'),
('CUV', '列王纪上', 11, 9, 14, '希兰给所罗门一百二十他连得金子。'),
('CUV', '列王纪上', 11, 9, 15, '所罗门王挑取服苦的人，是为建造耶和华的殿、自己的宫、米罗、耶路撒冷的城墙、夏琐、米吉多，并基色。'),
('CUV', '列王纪上', 11, 9, 16, '先前埃及王法老上来攻取基色，用火焚烧，杀了城内居住的迦南人，将城赐给他女儿所罗门的妻作妆奁。'),
('CUV', '列王纪上', 11, 9, 17, '所罗门建造基色、下伯和仑、'),
('CUV', '列王纪上', 11, 9, 18, '巴拉，并国中旷野里的达莫，'),
('CUV', '列王纪上', 11, 9, 19, '又建造所有的积货城，并屯车和马兵的城，与耶路撒冷、利巴嫩，以及自己治理的全国中所愿建造的。'),
('CUV', '列王纪上', 11, 9, 20, '至于国中所剩下不属以色列人的亚摩利人、赫人、比利洗人、希未人、耶布斯人，'),
('CUV', '列王纪上', 11, 9, 21, '就是以色列人不能灭尽的，所罗门挑取他们的后裔作服苦的奴仆，直到今日。'),
('CUV', '列王纪上', 11, 9, 22, '惟有以色列人，所罗门不使他们作奴仆，乃是作他的战士、臣仆、统领、军长、车兵长、马兵长。'),
('CUV', '列王纪上', 11, 9, 23, '所罗门有五百五十督工的，监管工人。'),
('CUV', '列王纪上', 11, 9, 24, '法老的女儿从大卫城搬到所罗门为他建造的宫里。那时，所罗门才建造米罗。'),
('CUV', '列王纪上', 11, 9, 25, '所罗门每年三次在他为耶和华所筑的坛上献燔祭和平安祭，又在耶和华面前的坛上烧香。这样，他建造殿的工程完毕了。'),
('CUV', '列王纪上', 11, 9, 26, '所罗门王在以东地红海边，靠近以禄的以旬迦别制造船只。'),
('CUV', '列王纪上', 11, 9, 27, '希兰差遣他的仆人，就是熟悉泛海的船家，与所罗门的仆人一同坐船航海。'),
('CUV', '列王纪上', 11, 9, 28, '他们到了俄斐，从那里得了四百二十他连得金子，运到所罗门王那里。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪上', 11, 10, 1, '示巴女王听见所罗门因耶和华之名所得的名声，就来要用难解的话试问所罗门。'),
('CUV', '列王纪上', 11, 10, 2, '跟随他到耶路撒冷的人甚多，又有骆驼驮著香料、宝石，和许多金子。他来见了所罗门王，就把心里所有的对所罗门都说出来。'),
('CUV', '列王纪上', 11, 10, 3, '所罗门王将他所问的都答上了，没有一句不明白、不能答的。'),
('CUV', '列王纪上', 11, 10, 4, '示巴女王见所罗门大有智慧，和他所建造的宫室，'),
('CUV', '列王纪上', 11, 10, 5, '席上的珍馐美味，群臣分列而坐，仆人两旁侍立，以及他们的衣服装饰和酒政的衣服装饰，又见他上耶和华殿的台阶(或作他在耶和华殿里所献的燔祭)，就诧异得神不守舍；'),
('CUV', '列王纪上', 11, 10, 6, '对王说：我在本国里所听见论到你的事和你的智慧实在是真的！'),
('CUV', '列王纪上', 11, 10, 7, '我先不信那些话，及至我来亲眼见了才知道人所告诉我的还不到一半。你的智慧和你的福分越过我所听见的风声。'),
('CUV', '列王纪上', 11, 10, 8, '你的臣子、你的仆人常侍立在你面前听你智慧的话是有福的！'),
('CUV', '列王纪上', 11, 10, 9, '耶和华─你的神是应当称颂的！他喜悦你，使你坐以色列的国位；因为他永远爱以色列，所以立你作王，使你秉公行义。'),
('CUV', '列王纪上', 11, 10, 10, '于是，示巴女王将一百二十他连得金子和宝石，与极多的香料，送给所罗门王。他送给王的香料，以后奉来的不再有这样多。'),
('CUV', '列王纪上', 11, 10, 11, '〈希兰的船只从俄斐运了金子来，又从俄斐运了许多檀香木(或作乌木；下同)和宝石来。'),
('CUV', '列王纪上', 11, 10, 12, '王用檀香木为耶和华殿和王宫做栏杆，又为歌唱的人做琴瑟。以后再没有这样的檀香木进国来，也没有人看见过，直到如今。〉'),
('CUV', '列王纪上', 11, 10, 13, '示巴女王一切所要所求的，所罗门王都送给他，另外照自己的厚意餽送他。于是女王和他臣仆转回本国去了。'),
('CUV', '列王纪上', 11, 10, 14, '所罗门每年所得的金子共有六百六十六他连得。'),
('CUV', '列王纪上', 11, 10, 15, '另外还有商人和杂族(历代下九章14节作亚拉伯)的诸王，与国中的省长所进的金子。'),
('CUV', '列王纪上', 11, 10, 16, '所罗门王用锤出来的金子打成挡牌二百面，每面用金子六百舍客勒；'),
('CUV', '列王纪上', 11, 10, 17, '又用锤出来的金子打成盾牌三百面，每面用金子三弥那，都放在利巴嫩林宫里。'),
('CUV', '列王纪上', 11, 10, 18, '王用象牙制造一个宝座，用精金包裹。'),
('CUV', '列王纪上', 11, 10, 19, '宝座有六层台阶，座的后背是圆的，两旁有扶手，靠近扶手有两个狮子站立。'),
('CUV', '列王纪上', 11, 10, 20, '六层台阶上有十二个狮子站立，每层有两个：左边一个，右边一个；在列国中没有这样做的。'),
('CUV', '列王纪上', 11, 10, 21, '所罗门王一切的饮器都是金子的。利巴嫩林宫里的一切器皿都是精金的。所罗门年间，银子算不了甚么。'),
('CUV', '列王纪上', 11, 10, 22, '因为王有他施船只与希兰的船只一同航海，三年一次，装载金银、象牙、猿猴、孔雀回来。'),
('CUV', '列王纪上', 11, 10, 23, '所罗门王的财宝与智慧胜过天下的列王。'),
('CUV', '列王纪上', 11, 10, 24, '普天下的王都求见所罗门，要听神赐给他智慧的话。'),
('CUV', '列王纪上', 11, 10, 25, '他们各带贡物，就是金器、银器、衣服、军械、香料、骡马，每年有一定之例。'),
('CUV', '列王纪上', 11, 10, 26, '所罗门聚集战车马兵，有战车一千四百辆，马兵一万二千名，安置在屯车的城邑和耶路撒冷，就是王那里。'),
('CUV', '列王纪上', 11, 10, 27, '王在耶路撒冷使银子多如石头，香柏木多如高原的桑树。'),
('CUV', '列王纪上', 11, 10, 28, '所罗门的马是从埃及带来的，是王的商人一群一群按著定价买来的。'),
('CUV', '列王纪上', 11, 10, 29, '从埃及买来的车，每辆价银六百舍客勒，马每匹一百五十舍客勒。赫人诸王和亚兰诸王所买的车马，也是按这价值经他们手买来的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪上', 11, 11, 1, '所罗门王在法老的女儿之外，又宠爱许多外邦女子，就是摩押女子、亚扪女子、以东女子、西顿女子、赫人女子。'),
('CUV', '列王纪上', 11, 11, 2, '论到这些国的人，耶和华曾晓谕以色列人说：你们不可与他们往来相通，因为他们必诱惑你们的心去随从他们的神。所罗门却恋爱这些女子。'),
('CUV', '列王纪上', 11, 11, 3, '所罗门有妃七百，都是公主；还有嫔三百。这些妃嫔诱惑他的心。'),
('CUV', '列王纪上', 11, 11, 4, '所罗门年老的时候，他的妃嫔诱惑他的心去随从别神，不效法他父亲大卫诚诚实实地顺服耶和华─他的神。'),
('CUV', '列王纪上', 11, 11, 5, '因为所罗门随从西顿人的女神亚斯他录和亚扪人可憎的神米勒公。'),
('CUV', '列王纪上', 11, 11, 6, '所罗门行耶和华眼中看为恶的事，不效法他父亲大卫专心顺从耶和华。'),
('CUV', '列王纪上', 11, 11, 7, '所罗门为摩押可憎的神基抹和亚扪人可憎的神摩洛，在耶路撒冷对面的山上建筑邱坛。'),
('CUV', '列王纪上', 11, 11, 8, '他为那些向自己的神烧香献祭的外邦女子，就是他娶来的妃嫔也是这样行。'),
('CUV', '列王纪上', 11, 11, 9, '耶和华向所罗门发怒，因为他的心偏离向他两次显现的耶和华─以色列的神。'),
('CUV', '列王纪上', 11, 11, 10, '耶和华曾吩咐他不可随从别神，他却没有遵守耶和华所吩咐的。'),
('CUV', '列王纪上', 11, 11, 11, '所以耶和华对他说：你既行了这事，不遵守我所吩咐你守的约和律例，我必将你的国夺回，赐给你的臣子。'),
('CUV', '列王纪上', 11, 11, 12, '然而，因你父亲大卫的缘故，我不在你活著的日子行这事，必从你儿子的手中将国夺回。'),
('CUV', '列王纪上', 11, 11, 13, '只是我不将全国夺回，要因我仆人大卫和我所选择的耶路撒冷，还留一支派给你的儿子。'),
('CUV', '列王纪上', 11, 11, 14, '耶和华使以东人哈达兴起，作所罗门的敌人；他是以东王的后裔。'),
('CUV', '列王纪上', 11, 11, 15, '先前大卫攻击以东，元帅约押上去葬埋阵亡的人，将以东的男丁都杀了。'),
('CUV', '列王纪上', 11, 11, 16, '约押和以色列众人在以东住了六个月，直到将以东的男丁尽都剪除。'),
('CUV', '列王纪上', 11, 11, 17, '那时哈达还是幼童；他和他父亲的臣仆，几个以东人逃往埃及。'),
('CUV', '列王纪上', 11, 11, 18, '他们从米甸起行，到了巴兰；从巴兰带著几个人来到埃及见埃及王法老；法老为他派定粮食，又给他房屋田地。'),
('CUV', '列王纪上', 11, 11, 19, '哈达在法老面前大蒙恩惠，以致法老将王后答比匿的妹子赐他为妻。'),
('CUV', '列王纪上', 11, 11, 20, '答比匿的妹子给哈达生了一个儿子，名叫基努拔。答比匿使基努拔在法老的宫里断奶，基努拔就与法老的众子一同住在法老的宫里。'),
('CUV', '列王纪上', 11, 11, 21, '哈达在埃及听见大卫与他列祖同睡，元帅约押也死了，就对法老说：求王容我回本国去。'),
('CUV', '列王纪上', 11, 11, 22, '法老对他说：你在我这里有甚么缺乏，你竟要回你本国去呢？他回答说：我没有缺乏甚么，只是求王容我回去。'),
('CUV', '列王纪上', 11, 11, 23, '神又使以利亚大的儿子利逊兴起，作所罗门的敌人。他先前逃避主人琐巴王哈大底谢。'),
('CUV', '列王纪上', 11, 11, 24, '大卫击杀琐巴人的时候，利逊招聚了一群人，自己作他们的头目，往大马色居住，在那里作王。'),
('CUV', '列王纪上', 11, 11, 25, '所罗门活著的时候，哈达为患之外，利逊也作以色列的敌人。他恨恶以色列人，且作了亚兰人的王。'),
('CUV', '列王纪上', 11, 11, 26, '所罗门的臣仆、尼八的儿子耶罗波安也举手攻击王。他是以法莲支派的洗利达人，他母亲是寡妇，名叫洗鲁阿。'),
('CUV', '列王纪上', 11, 11, 27, '他举手攻击王的缘故，乃由先前所罗门建造米罗，修补他父亲大卫城的破口。'),
('CUV', '列王纪上', 11, 11, 28, '耶罗波安是大有才能的人。所罗门见这少年人殷勤，就派他监管约瑟家的一切工程。'),
('CUV', '列王纪上', 11, 11, 29, '一日，耶罗波安出了耶路撒冷，示罗人先知亚希雅在路上遇见他；亚希雅身上穿著一件新衣。他们二人在田野，以外并无别人。'),
('CUV', '列王纪上', 11, 11, 30, '亚希雅将自己穿的那件新衣撕成十二片，'),
('CUV', '列王纪上', 11, 11, 31, '对耶罗波安说：你可以拿十片。耶和华─以色列的神如此说：我必将国从所罗门手里夺回，将十个支派赐给你。'),
('CUV', '列王纪上', 11, 11, 32, '（我因仆人大卫和我在以色列众支派中所选择的耶路撒冷城的缘故，仍给所罗门留一个支派。）'),
('CUV', '列王纪上', 11, 11, 33, '因为他离弃我，敬拜西顿人的女神亚斯他录、摩押的神基抹，和亚扪人的神米勒公，没有遵从我的道，行我眼中看为正的事，守我的律例典章，像他父亲大卫一样。'),
('CUV', '列王纪上', 11, 11, 34, '但我不从他手里将全国夺回；使他终身为君，是因我所拣选的仆人大卫谨守我的诫命律例。'),
('CUV', '列王纪上', 11, 11, 35, '我必从他儿子的手里将国夺回，以十个支派赐给你，'),
('CUV', '列王纪上', 11, 11, 36, '还留一个支派给他的儿子，使我仆人大卫在我所选择立我名的耶路撒冷城里，在我面前长有灯光。'),
('CUV', '列王纪上', 11, 11, 37, '我必拣选你，使你照心里一切所愿的，作王治理以色列。'),
('CUV', '列王纪上', 11, 11, 38, '你若听从我一切所吩咐你的，遵行我的道，行我眼中看为正的事，谨守我的律例诫命，像我仆人大卫所行的，我就与你同在，为你立坚固的家，像我为大卫所立的一样，将以色列人赐给你。'),
('CUV', '列王纪上', 11, 11, 39, '我必因所罗门所行的使大卫后裔受患难，但不至于永远。'),
('CUV', '列王纪上', 11, 11, 40, '所罗门因此想要杀耶罗波安。耶罗波安却起身逃往埃及；到了埃及王示撒那里，就住在埃及，直到所罗门死了。'),
('CUV', '列王纪上', 11, 11, 41, '所罗门其余的事，凡他所行的和他的智慧都写在所罗门记上。'),
('CUV', '列王纪上', 11, 11, 42, '所罗门在耶路撒冷作以色列众人的王共四十年。'),
('CUV', '列王纪上', 11, 11, 43, '所罗门与他列祖同睡，葬在他父亲大卫的城里。他儿子罗波安接续他作王。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪上', 11, 12, 1, '罗波安往示剑去；因为以色列人都到了示剑要立他作王。'),
('CUV', '列王纪上', 11, 12, 2, '尼八的儿子耶罗波安先前躲避所罗门王，逃往埃及，住在那里（他听见这事。）'),
('CUV', '列王纪上', 11, 12, 3, '以色列人打发人去请他来，他就和以色列会众都来见罗波安，对他说：'),
('CUV', '列王纪上', 11, 12, 4, '你父亲使我们负重轭，做苦工，现在求你使我们做的苦工、负的重轭轻松些，我们就事奉你。'),
('CUV', '列王纪上', 11, 12, 5, '罗波安对他们说：你们暂且去，第三日再来见我。民就去了。'),
('CUV', '列王纪上', 11, 12, 6, '罗波安之父所罗门在世的日子，有侍立在他面前的老年人，罗波安王和他们商议，说：你们给我出个甚么主意，我好回复这民。'),
('CUV', '列王纪上', 11, 12, 7, '老年人对他说：现在王若服事这民如仆人，用好话回答他们，他们就永远作王的仆人。'),
('CUV', '列王纪上', 11, 12, 8, '王却不用老年人给他出的主意，就和那些与他一同长大、在他面前侍立的少年人商议，'),
('CUV', '列王纪上', 11, 12, 9, '说：这民对我说：你父亲使我们负重轭，求你使我们轻松些。你们给我出个甚么主意，我好回复他们。'),
('CUV', '列王纪上', 11, 12, 10, '那同他长大的少年人说：这民对王说：你父亲使我们负重轭，求你使我们轻松些。王要对他们如此说：我的小拇指头比我父亲的腰还粗。'),
('CUV', '列王纪上', 11, 12, 11, '我父亲使你们负重轭，我必使你们负更重的轭！我父亲用鞭子责打你们，我要用蝎子鞭责打你们！'),
('CUV', '列王纪上', 11, 12, 12, '耶罗波安和众百姓遵著罗波安王所说你们第三日再来见我的那话，第三日他们果然来了。'),
('CUV', '列王纪上', 11, 12, 13, '王用严厉的话回答百姓，不用老年人给他所出的主意，'),
('CUV', '列王纪上', 11, 12, 14, '照著少年人所出的主意对民说：我父亲使你们负重轭，我必使你们负更重的轭！我父亲用鞭子责打你们，我要用蝎子鞭责打你们！'),
('CUV', '列王纪上', 11, 12, 15, '王不肯依从百姓，这事乃出于耶和华，为要应验他藉示罗人亚希雅对尼八的儿子耶罗波安所说的话。'),
('CUV', '列王纪上', 11, 12, 16, '以色列众民见王不依从他们，就对王说：我们与大卫有甚么分儿呢？与耶西的儿子并没有关涉。以色列人哪，各回各家去罢！大卫家啊，自己顾自己罢！于是，以色列人都回自己家里去了，'),
('CUV', '列王纪上', 11, 12, 17, '惟独住犹大城邑的以色列人，罗波安仍作他们的王。'),
('CUV', '列王纪上', 11, 12, 18, '罗波安王差遣掌管服苦之人的亚多兰往以色列人那里去，以色列人就用石头打死他。罗波安王急忙上车，逃回耶路撒冷去了。'),
('CUV', '列王纪上', 11, 12, 19, '这样，以色列人背叛大卫家，直到今日。'),
('CUV', '列王纪上', 11, 12, 20, '以色列众人听见耶罗波安回来了，就打发人去请他到会众面前，立他作以色列众人的王。除了犹大支派以外，没有顺从大卫家的。'),
('CUV', '列王纪上', 11, 12, 21, '罗波安来到耶路撒冷，招聚犹大全家和便雅悯支派的人共十八万，都是挑选的战士，要与以色列家争战，好将国夺回，再归所罗门的儿子罗波安。'),
('CUV', '列王纪上', 11, 12, 22, '但神的话临到神人示玛雅，说：'),
('CUV', '列王纪上', 11, 12, 23, '你去告诉所罗门的儿子犹大王罗波安和犹大、便雅悯全家，并其余的民说：'),
('CUV', '列王纪上', 11, 12, 24, '耶和华如此说：你们不可上去与你们的弟兄以色列人争战。各归各家去罢！因为这事出于我。众人就听从耶和华的话，遵著耶和华的命回去了。'),
('CUV', '列王纪上', 11, 12, 25, '耶罗波安在以法莲山地建筑示剑，就住在其中；又从示剑出去，建筑毗努伊勒。'),
('CUV', '列王纪上', 11, 12, 26, '耶罗波安心里说：恐怕这国仍归大卫家；'),
('CUV', '列王纪上', 11, 12, 27, '这民若上耶路撒冷去，在耶和华的殿里献祭，他们的心必归向他们的主─犹大王罗波安，就把我杀了，仍归犹大王罗波安。'),
('CUV', '列王纪上', 11, 12, 28, '耶罗波安王就筹划定妥，铸造了两个金牛犊，对众民说：以色列人哪，你们上耶路撒冷去实在是难；这就是领你们出埃及地的神。'),
('CUV', '列王纪上', 11, 12, 29, '他就把牛犊一只安在伯特利，一只安在但。'),
('CUV', '列王纪上', 11, 12, 30, '这事叫百姓陷在罪里，因为他们往但去拜那牛犊。'),
('CUV', '列王纪上', 11, 12, 31, '耶罗波安在邱坛那里建殿，将那不属利未人的凡民立为祭司。'),
('CUV', '列王纪上', 11, 12, 32, '耶罗波安定八月十五日为节期，像在犹大的节期一样，自己上坛献祭。他在伯特利也这样向他所铸的牛犊献祭，又将立为邱坛的祭司安置在伯特利。'),
('CUV', '列王纪上', 11, 12, 33, '他在八月十五日，就是他私自所定的月日，为以色列人立作节期的日子，在伯特利上坛烧香。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪上', 11, 13, 1, '那时，有一个神人奉耶和华的命从犹大来到伯特利。耶罗波安正站在坛旁要烧香；'),
('CUV', '列王纪上', 11, 13, 2, '神人奉耶和华的命向坛呼叫，说：坛哪，坛哪！耶和华如此说：大卫家里必生一个儿子，名叫约西亚，他必将邱坛的祭司，就是在你上面烧香的，杀在你上面，人的骨头也必烧在你上面。'),
('CUV', '列王纪上', 11, 13, 3, '当日，神人设个预兆，说：这坛必破裂，坛上的灰必倾撒，这是耶和华说的预兆。'),
('CUV', '列王纪上', 11, 13, 4, '耶罗波安王听见神人向伯特利的坛所呼叫的话，就从坛上伸手，说：拿住他罢！王向神人所伸的手就枯干了，不能弯回；'),
('CUV', '列王纪上', 11, 13, 5, '坛也破裂了，坛上的灰倾撒了，正如神人奉耶和华的命所设的预兆。'),
('CUV', '列王纪上', 11, 13, 6, '王对神人说：请你为我祷告，求耶和华─你神的恩典使我的手复原。于是神人祈祷耶和华，王的手就复了原，仍如寻常一样。'),
('CUV', '列王纪上', 11, 13, 7, '王对神人说：请你同我回去吃饭，加添心力，我也必给你赏赐。'),
('CUV', '列王纪上', 11, 13, 8, '神人对王说：你就是把你的宫一半给我，我也不同你进去，也不在这地方吃饭喝水；'),
('CUV', '列王纪上', 11, 13, 9, '因为有耶和华的话嘱咐我，说不可在伯特利吃饭喝水，也不可从你去的原路回来。'),
('CUV', '列王纪上', 11, 13, 10, '于是神人从别的路回去，不从伯特利来的原路回去。'),
('CUV', '列王纪上', 11, 13, 11, '有一个老先知住在伯特利，他儿子们来，将神人当日在伯特利所行的一切事和向王所说的话都告诉了父亲。'),
('CUV', '列王纪上', 11, 13, 12, '父亲问他们说：神人从哪条路去了呢？儿子们就告诉他；原来他们看见那从犹大来的神人所去的路。'),
('CUV', '列王纪上', 11, 13, 13, '老先知就吩咐他儿子们说：你们为我备驴。他们备好了驴，他就骑上，'),
('CUV', '列王纪上', 11, 13, 14, '去追赶神人，遇见他坐在橡树底下，就问他说：你是从犹大来的神人不是？他说：是。'),
('CUV', '列王纪上', 11, 13, 15, '老先知对他说：请你同我回家吃饭。'),
('CUV', '列王纪上', 11, 13, 16, '神人说：我不可同你回去进你的家，也不可在这里同你吃饭喝水；'),
('CUV', '列王纪上', 11, 13, 17, '因为有耶和华的话嘱咐我说：你在那里不可吃饭喝水，也不可从你去的原路回来。'),
('CUV', '列王纪上', 11, 13, 18, '老先知对他说：我也是先知，和你一样。有天使奉耶和华的命对我说：你去把他带回你的家，叫他吃饭喝水。这都是老先知诓哄他。'),
('CUV', '列王纪上', 11, 13, 19, '于是神人同老先知回去，在他家里吃饭喝水。'),
('CUV', '列王纪上', 11, 13, 20, '二人坐席的时候，耶和华的话临到那带神人回来的先知，'),
('CUV', '列王纪上', 11, 13, 21, '他就对那从犹大来的神人说：耶和华如此说：你既违背耶和华的话，不遵守耶和华─你神的命令，'),
('CUV', '列王纪上', 11, 13, 22, '反倒回来，在耶和华禁止你吃饭喝水的地方吃了喝了，因此你的尸身不得入你列祖的坟墓。'),
('CUV', '列王纪上', 11, 13, 23, '吃喝完了，老先知为所带回来的先知备驴。'),
('CUV', '列王纪上', 11, 13, 24, '他就去了，在路上有个狮子遇见他，将他咬死，尸身倒在路上，驴站在尸身旁边，狮子也站在尸身旁边。'),
('CUV', '列王纪上', 11, 13, 25, '有人从那里经过，看见尸身倒在路上，狮子站在尸身旁边，就来到老先知所住的城里述说这事。'),
('CUV', '列王纪上', 11, 13, 26, '那带神人回来的先知听见这事，就说：这是那违背了耶和华命令的神人，所以耶和华把他交给狮子；狮子抓伤他，咬死他，是应验耶和华对他说的话。'),
('CUV', '列王纪上', 11, 13, 27, '老先知就吩咐他儿子们说：你们为我备驴。他们就备了驴。'),
('CUV', '列王纪上', 11, 13, 28, '他去了，看见神人的尸身倒在路上，驴和狮子站在尸身旁边，狮子却没有吃尸身，也没有抓伤驴。'),
('CUV', '列王纪上', 11, 13, 29, '老先知就把神人的尸身驮在驴上，带回自己的城里，要哀哭他，葬埋他；'),
('CUV', '列王纪上', 11, 13, 30, '就把他的尸身葬在自己的坟墓里，哀哭他，说：哀哉！我兄啊。'),
('CUV', '列王纪上', 11, 13, 31, '安葬之后，老先知对他儿子们说：我死了，你们要葬我在神人的坟墓里，使我的尸骨靠近他的尸骨，'),
('CUV', '列王纪上', 11, 13, 32, '因为他奉耶和华的命指著伯特利的坛和撒玛利亚各城有邱坛之殿所说的话必定应验。'),
('CUV', '列王纪上', 11, 13, 33, '这事以后，耶罗波安仍不离开他的恶道，将凡民立为邱坛的祭司；凡愿意的，他都分别为圣，立为邱坛的祭司。'),
('CUV', '列王纪上', 11, 13, 34, '这事叫耶罗波安的家陷在罪里，甚至他的家从地上除灭了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪上', 11, 14, 1, '那时，耶罗波安的儿子亚比雅病了。'),
('CUV', '列王纪上', 11, 14, 2, '耶罗波安对他的妻说：你可以起来改装，使人不知道你是耶罗波安的妻，往示罗去，在那里有先知亚希雅。他曾告诉我说，你必作这民的王。'),
('CUV', '列王纪上', 11, 14, 3, '现在你要带十个饼，与几个薄饼，和一瓶蜜去见他，他必告诉你儿子将要怎样。'),
('CUV', '列王纪上', 11, 14, 4, '耶罗波安的妻就这样行，起身往示罗去，到了亚希雅的家。亚希雅因年纪老迈，眼目发直，不能看见。'),
('CUV', '列王纪上', 11, 14, 5, '耶和华先晓谕亚希雅说：耶罗波安的妻要来问你，因他儿子病了，你当此此如此告诉他。他进来的时候必装作别的妇人。'),
('CUV', '列王纪上', 11, 14, 6, '他刚进门，亚希雅听见他脚步的响声，就说：耶罗波安的妻，进来罢！你为何装作别的妇人呢？我奉差遣将凶事告诉你。'),
('CUV', '列王纪上', 11, 14, 7, '你回去告诉耶罗波安说：耶和华─以色列的神如此说：我从民中将你高举，立你作我民以色列的君，'),
('CUV', '列王纪上', 11, 14, 8, '将国从大卫家夺回赐给你；你却不效法我仆人大卫，遵守我的诫命，一心顺从我，行我眼中看为正的事。'),
('CUV', '列王纪上', 11, 14, 9, '你竟行恶，比那在你以先的更甚，为自己立了别神，铸了偶像，惹我发怒，将我丢在背后。'),
('CUV', '列王纪上', 11, 14, 10, '因此，我必使灾祸临到耶罗波安的家，将属耶罗波安的男丁，无论困住的、自由的都从以色列中剪除，必除尽耶罗波安的家，如人除尽粪土一般。'),
('CUV', '列王纪上', 11, 14, 11, '凡属耶罗波安的人，死在城中的必被狗吃，死在田野的必被空中的鸟吃。这是耶和华说的。'),
('CUV', '列王纪上', 11, 14, 12, '所以你起身回家去罢！你的脚一进城，你儿子就必死了。'),
('CUV', '列王纪上', 11, 14, 13, '以色列众人必为他哀哭，将他葬埋。凡属耶罗波安的人，惟有他得入坟墓；因为在耶罗波安的家中，只有他向耶和华─以色列的神显出善行。'),
('CUV', '列王纪上', 11, 14, 14, '耶和华必另立一王治理以色列。到了日期，他必剪除耶罗波安的家；那日期已经到了。'),
('CUV', '列王纪上', 11, 14, 15, '耶和华必击打以色列人，使他们摇动，像水中的芦苇一般；又将他们从耶和华赐给他们列祖的美地上拔出来，分散在大河那边；因为他们做木偶，惹耶和华发怒。'),
('CUV', '列王纪上', 11, 14, 16, '因耶罗波安所犯的罪，又使以色列人陷在罪里，耶和华必将以色列人交给仇敌。'),
('CUV', '列王纪上', 11, 14, 17, '耶罗波安的妻起身回去，到了得撒，刚到门槛，儿子就死了。'),
('CUV', '列王纪上', 11, 14, 18, '以色列众人将他葬埋，为他哀哭，正如耶和华藉他仆人先知亚希雅所说的话。'),
('CUV', '列王纪上', 11, 14, 19, '耶罗波安其余的事，他怎样争战，怎样作王，都写在以色列诸王记上。'),
('CUV', '列王纪上', 11, 14, 20, '耶罗波安作王二十二年，就与他列祖同睡。他儿子拿答接续他作王。'),
('CUV', '列王纪上', 11, 14, 21, '所罗门的儿子罗波安作犹大王。他登基的时候年四十一岁，在耶路撒冷，就是耶和华从以色列众支派中所选择立他名的城，作王十七年。罗波安的母亲名叫拿玛，是亚扪人。'),
('CUV', '列王纪上', 11, 14, 22, '犹大人行耶和华眼中看为恶的事，犯罪触动他的愤恨，比他们列祖更甚。'),
('CUV', '列王纪上', 11, 14, 23, '因为他们在各高冈上，各青翠树下筑坛，立柱像和木偶。'),
('CUV', '列王纪上', 11, 14, 24, '国中也有娈童。犹大人效法耶和华在以色列人面前所赶出的外邦人，行一切可憎恶的事。'),
('CUV', '列王纪上', 11, 14, 25, '罗波安王第五年，埃及王示撒上来攻取耶路撒冷，'),
('CUV', '列王纪上', 11, 14, 26, '夺了耶和华殿和王宫里的宝物，尽都带走，又夺去所罗门制造的金盾牌。'),
('CUV', '列王纪上', 11, 14, 27, '罗波安王制造铜盾牌代替那金盾牌，交给守王宫门的护卫长看守。'),
('CUV', '列王纪上', 11, 14, 28, '王每逢进耶和华的殿，护卫兵就拿这盾牌，随后仍将盾牌送回，放在护卫房。'),
('CUV', '列王纪上', 11, 14, 29, '罗波安其余的事，凡他所行的，都写在犹大列王记上。'),
('CUV', '列王纪上', 11, 14, 30, '罗波安与耶罗波安时常争战。'),
('CUV', '列王纪上', 11, 14, 31, '罗波安与他列祖同睡，葬在大卫城他列祖的坟地里。他母亲名叫拿玛，是亚扪人。他儿子亚比央(又名亚比雅)接续他作王。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪上', 11, 15, 1, '尼八的儿子耶罗波安王十八年，亚比央登基作犹大王，'),
('CUV', '列王纪上', 11, 15, 2, '在耶路撒冷作王三年。他母亲名叫玛迦，是押沙龙的女儿。'),
('CUV', '列王纪上', 11, 15, 3, '亚比央行他父亲在他以前所行的一切恶，他的心不像他祖大卫的心，诚诚实实地顺服耶和华─他的神。'),
('CUV', '列王纪上', 11, 15, 4, '然而耶和华─他的神因大卫的缘故，仍使他在耶路撒冷有灯光，叫他儿子接续他作王，坚立耶路撒冷。'),
('CUV', '列王纪上', 11, 15, 5, '因为大卫除了赫人乌利亚那件事，都是行耶和华眼中看为正的事，一生没有违背耶和华一切所吩咐的。'),
('CUV', '列王纪上', 11, 15, 6, '罗波安在世的日子常与耶罗波安争战。'),
('CUV', '列王纪上', 11, 15, 7, '亚比央其余的事，凡他所行的，都写在犹大列王记上。亚比央常与耶罗波安争战。'),
('CUV', '列王纪上', 11, 15, 8, '亚比央与他列祖同睡，葬在大卫的城里。他儿子亚撒接续他作王。'),
('CUV', '列王纪上', 11, 15, 9, '以色列王耶罗波安二十年，亚撒登基作犹大王，'),
('CUV', '列王纪上', 11, 15, 10, '在耶路撒冷作王四十一年。他祖母名叫玛迦，是押沙龙的女儿。'),
('CUV', '列王纪上', 11, 15, 11, '亚撒效法他祖大卫行耶和华眼中看为正的事，'),
('CUV', '列王纪上', 11, 15, 12, '从国中除去娈童，又除掉他列祖所造的一切偶像；'),
('CUV', '列王纪上', 11, 15, 13, '并且贬了他祖母玛迦太后的位，因他造了可憎的偶像亚舍拉。亚撒砍下他的偶像，烧在汲沦溪边，'),
('CUV', '列王纪上', 11, 15, 14, '只是邱坛还没有废去。亚撒一生却向耶和华存诚实的心。'),
('CUV', '列王纪上', 11, 15, 15, '亚撒将他父亲所分别为圣与自己所分别为圣的金银和器皿都奉到耶和华的殿里。'),
('CUV', '列王纪上', 11, 15, 16, '亚撒和以色列王巴沙在世的日子常常争战。'),
('CUV', '列王纪上', 11, 15, 17, '以色列王巴沙上来要攻击犹大，修筑拉玛，不许人从犹大王亚撒那里出入。'),
('CUV', '列王纪上', 11, 15, 18, '于是亚撒将耶和华殿和王宫府库里所剩下的金银都交在他臣仆手中，打发他们往住大马色的亚兰王─希旬的孙子、他伯利们的儿子便哈达那里去，'),
('CUV', '列王纪上', 11, 15, 19, '说：你父曾与我父立约，我与你也要立约。现在我将金银送你为礼物，求你废掉你与以色列王巴沙所立的约，使他离开我。'),
('CUV', '列王纪上', 11, 15, 20, '便哈达听从亚撒王的话，派军长去攻击以色列的城邑；他们就攻破以云、但、亚伯伯玛迦、基尼烈全境、拿弗他利全境。'),
('CUV', '列王纪上', 11, 15, 21, '巴沙听见，就停工不修筑拉玛了，仍住在得撒。'),
('CUV', '列王纪上', 11, 15, 22, '于是亚撒王宣告犹大众人，不准一个推辞，吩咐他们将巴沙修筑拉玛所用的石头、木头都运去，用以修筑便雅悯的迦巴和米斯巴。'),
('CUV', '列王纪上', 11, 15, 23, '亚撒其余的事，凡他所行的，并他的勇力与他所建筑的城邑，都写在犹大列王记上。亚撒年老的时候，脚上有病。'),
('CUV', '列王纪上', 11, 15, 24, '亚撒与他列祖同睡，葬在他祖大卫城他列祖的坟地里。他儿子约沙法接续他作王。'),
('CUV', '列王纪上', 11, 15, 25, '犹大王亚撒第二年，耶罗波安的儿子拿答登基作以色列王共二年，'),
('CUV', '列王纪上', 11, 15, 26, '拿答行耶和华眼中看为恶的事，行他父亲所行的，犯他父亲使以色列人陷在罪里的那罪。'),
('CUV', '列王纪上', 11, 15, 27, '以萨迦人亚希雅的儿子巴沙背叛拿答，在非利士的基比顿杀了他。那时拿答和以色列众人正围困基比顿。'),
('CUV', '列王纪上', 11, 15, 28, '在犹大王亚撒第三年巴沙杀了他，篡了他的位。'),
('CUV', '列王纪上', 11, 15, 29, '巴沙一作王就杀了耶罗波安的全家，凡有气息的没有留下一个，都灭尽了，正应验耶和华藉他仆人示罗人亚希雅所说的话。'),
('CUV', '列王纪上', 11, 15, 30, '这是因为耶罗波安所犯的罪使以色列人陷在罪里，惹动耶和华─以色列神的怒气。'),
('CUV', '列王纪上', 11, 15, 31, '拿答其余的事，凡他所行的，都写在以色列诸王记上。'),
('CUV', '列王纪上', 11, 15, 32, '亚撒和以色列王巴沙在世的日子常常争战。'),
('CUV', '列王纪上', 11, 15, 33, '犹大王亚撒第三年，亚希雅的儿子巴沙在得撒登基作以色列众人的王共廿四年。'),
('CUV', '列王纪上', 11, 15, 34, '他行耶和华眼中看为恶的事，行耶罗波安所行的道，犯他使以色列人陷在罪里的那罪。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪上', 11, 16, 1, '耶和华的话临到哈拿尼的儿子耶户，责备巴沙说：'),
('CUV', '列王纪上', 11, 16, 2, '我既从尘埃中提拔你，立你作我民以色列的君，你竟行耶罗波安所行的道，使我民以色列陷在罪里，惹我发怒，'),
('CUV', '列王纪上', 11, 16, 3, '我必除尽你和你的家，使你的家像尼八的儿子耶罗波安的家一样。'),
('CUV', '列王纪上', 11, 16, 4, '凡属巴沙的人，死在城中的必被狗吃，死在田野的必被空中的鸟吃。'),
('CUV', '列王纪上', 11, 16, 5, '巴沙其余的事，凡他所行的和他的勇力，都写在以色列诸王记上。'),
('CUV', '列王纪上', 11, 16, 6, '巴沙与他列祖同睡，葬在得撒。他儿子以拉接续他作王。'),
('CUV', '列王纪上', 11, 16, 7, '耶和华的话临到哈拿尼的儿子先知耶户，责备巴沙和他的家，因他行耶和华眼中看为恶的一切事，以他手所做的惹耶和华发怒，像耶罗波安的家一样，又因他杀了耶罗波安的全家。'),
('CUV', '列王纪上', 11, 16, 8, '犹大王亚撒二十六年，巴沙的儿子以拉在得撒登基作以色列王共二年。'),
('CUV', '列王纪上', 11, 16, 9, '有管理他一半战车的臣子心利背叛他。当他在得撒家宰亚杂家里喝醉的时候，'),
('CUV', '列王纪上', 11, 16, 10, '心利就进去杀了他，篡了他的位。这是犹大王亚撒二十七年的事。'),
('CUV', '列王纪上', 11, 16, 11, '心利一坐王位就杀了巴沙的全家，连他的亲属、朋友也没有留下一个男丁。'),
('CUV', '列王纪上', 11, 16, 12, '心利这样灭绝巴沙的全家，正如耶和华藉先知耶户责备巴沙的话。'),
('CUV', '列王纪上', 11, 16, 13, '这是因巴沙和他儿子以拉的一切罪，就是他们使以色列人陷在罪里的那罪，以虚无的神惹耶和华─以色列神的怒气。'),
('CUV', '列王纪上', 11, 16, 14, '以拉其余的事，凡他所行的，都写在以色列诸王记上。'),
('CUV', '列王纪上', 11, 16, 15, '犹大王亚撒二十七年，心利在得撒作王七日。那时民正安营围攻非利士的基比顿。'),
('CUV', '列王纪上', 11, 16, 16, '民在营中听说心利背叛，又杀了王，故此以色列众人当日在营中立元帅暗利作以色列王。'),
('CUV', '列王纪上', 11, 16, 17, '暗利率领以色列众人，从基比顿上去，围困得撒。'),
('CUV', '列王纪上', 11, 16, 18, '心利见城破失，就进了王宫的卫所，放火焚烧宫殿，自焚而死。'),
('CUV', '列王纪上', 11, 16, 19, '这是因他犯罪，行耶和华眼中看为恶的事，行耶罗波安所行的，犯他使以色列人陷在罪里的那罪。'),
('CUV', '列王纪上', 11, 16, 20, '心利其余的事和他背叛的情形都写在以色列诸王记上。'),
('CUV', '列王纪上', 11, 16, 21, '那时，以色列民分为两半：一半随从基纳的儿子提比尼，要立他作王；一半随从暗利。'),
('CUV', '列王纪上', 11, 16, 22, '但随从暗利的民胜过随从基纳的儿子提比尼的民。提比尼死了，暗利就作了王。'),
('CUV', '列王纪上', 11, 16, 23, '犹大王亚撒三十一年，暗利登基作以色列王共十二年；在得撒作王六年。'),
('CUV', '列王纪上', 11, 16, 24, '暗利用二他连得银子向撒玛买了撒玛利亚山，在山上造城，就按著山的原主撒玛的名，给所造的城起名叫撒玛利亚。'),
('CUV', '列王纪上', 11, 16, 25, '暗利行耶和华眼中看为恶的事，比他以前的列王作恶更甚。'),
('CUV', '列王纪上', 11, 16, 26, '因他行了尼八的儿子耶罗波安所行的，犯他使以色列人陷在罪里的那罪，以虚无的神惹耶和华─以色列神的怒气。'),
('CUV', '列王纪上', 11, 16, 27, '暗利其余的事和他所显出的勇力都写在以色列诸王记上。'),
('CUV', '列王纪上', 11, 16, 28, '暗利与他列祖同睡，葬在撒玛利亚。他儿子亚哈接续他作王。'),
('CUV', '列王纪上', 11, 16, 29, '犹大王亚撒三十八年，暗利的儿子亚哈登基作了以色列王。暗利的儿子亚哈在撒玛利亚作以色列王二十二年。'),
('CUV', '列王纪上', 11, 16, 30, '暗利的儿子亚哈行耶和华眼中看为恶的事，比他以前的列王更甚，'),
('CUV', '列王纪上', 11, 16, 31, '犯了尼八的儿子耶罗波安所犯的罪；他还以为轻，又娶了西顿王谒巴力的女儿耶洗别为妻，去事奉敬拜巴力，'),
('CUV', '列王纪上', 11, 16, 32, '在撒玛利亚建造巴力的庙，在庙里为巴力筑坛。'),
('CUV', '列王纪上', 11, 16, 33, '亚哈又做亚舍拉，他所行的惹耶和华─以色列神的怒气，比他以前的以色列诸王更甚。'),
('CUV', '列王纪上', 11, 16, 34, '亚哈在位的时候，有伯特利人希伊勒重修耶利哥城；立根基的时候，丧了长子亚比兰；安门的时候，丧了幼子西割，正如耶和华藉嫩的儿子约书亚所说的话。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪上', 11, 17, 1, '基列寄居的提斯比人以利亚对亚哈说：我指著所事奉永生耶和华─以色列的神起誓，这几年我若不祷告，必不降露，不下雨。'),
('CUV', '列王纪上', 11, 17, 2, '耶和华的话临到以利亚说：'),
('CUV', '列王纪上', 11, 17, 3, '你离开这里往东去，藏在约但河东边的基立溪旁。'),
('CUV', '列王纪上', 11, 17, 4, '你要喝那溪里的水，我已吩咐乌鸦在那里供养你。'),
('CUV', '列王纪上', 11, 17, 5, '于是以利亚照著耶和华的话，去住在约但河东的基立溪旁。'),
('CUV', '列王纪上', 11, 17, 6, '乌鸦早晚给他叼饼和肉来，他也喝那溪里的水。'),
('CUV', '列王纪上', 11, 17, 7, '过了些日子，溪水就干了，因为雨没有下在地上。'),
('CUV', '列王纪上', 11, 17, 8, '耶和华的话临到他说：'),
('CUV', '列王纪上', 11, 17, 9, '你起身往西顿的撒勒法(撒勒法与路四26同)去，住在那里；我已吩咐那里的一个寡妇供养你。'),
('CUV', '列王纪上', 11, 17, 10, '以利亚就起身往撒勒法去。到了城门，见有一个寡妇在那里捡柴，以利亚呼叫他说：求你用器皿取点水来给我喝。'),
('CUV', '列王纪上', 11, 17, 11, '他去取水的时候，以利亚又呼叫他说：也求你拿点饼来给我！'),
('CUV', '列王纪上', 11, 17, 12, '他说：我指著永生耶和华─你的神起誓，我没有饼，坛内只有一把面，瓶里只有一点油；我现在找两根柴，回家要为我和我儿子做饼；我们吃了，死就死罢！'),
('CUV', '列王纪上', 11, 17, 13, '以利亚对他说：不要惧怕！可以照你所说的去做罢！只要先为我做一个小饼拿来给我，然后为你和你的儿子做饼。'),
('CUV', '列王纪上', 11, 17, 14, '因为耶和华─以色列的神如此说：坛内的面必不减少，瓶里的油必不缺短，直到耶和华使雨降在地上的日子。'),
('CUV', '列王纪上', 11, 17, 15, '妇人就照以利亚的话去行。他和他家中的人，并以利亚，吃了许多日子。'),
('CUV', '列王纪上', 11, 17, 16, '坛内的面果不减少，瓶里的油也不缺短，正如耶和华借以利亚所说的话。'),
('CUV', '列王纪上', 11, 17, 17, '这事以后，作那家主母的妇人，他儿子病了；病得甚重，以致身无气息。'),
('CUV', '列王纪上', 11, 17, 18, '妇人对以利亚说：神人哪，我与你何干？你竟到我这里来，使神想念我的罪，以致我的儿子死呢？'),
('CUV', '列王纪上', 11, 17, 19, '以利亚对他说：把你儿子交给我。以利亚就从妇人怀中将孩子接过来，抱到他所住的楼中，放在自己的床上，'),
('CUV', '列王纪上', 11, 17, 20, '就求告耶和华说：耶和华─我的神啊，我寄居在这寡妇的家里，你就降祸与他，使他的儿子死了么？'),
('CUV', '列王纪上', 11, 17, 21, '以利亚三次伏在孩子的身上，求告耶和华说：耶和华─我的神啊，求你使这孩子的灵魂仍入他的身体！'),
('CUV', '列王纪上', 11, 17, 22, '耶和华应允以利亚的话，孩子的灵魂仍入他的身体，他就活了。'),
('CUV', '列王纪上', 11, 17, 23, '以利亚将孩子从楼上抱下来，进屋子交给他母亲，说：看哪，你的儿子活了！'),
('CUV', '列王纪上', 11, 17, 24, '妇人对以利亚说：现在我知道你是神人，耶和华藉你口所说的话是真的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪上', 11, 18, 1, '过了许久，到第三年，耶和华的话临到以利亚说：你去，使亚哈得见你；我要降雨在地上。'),
('CUV', '列王纪上', 11, 18, 2, '以利亚就去，要使亚哈得见他。那时，撒玛利亚有大饥荒；'),
('CUV', '列王纪上', 11, 18, 3, '亚哈将他的家宰俄巴底召了来。〈俄巴底甚是敬畏耶和华，'),
('CUV', '列王纪上', 11, 18, 4, '耶洗别杀耶和华众先知的时候，俄巴底将一百个先知藏了，每五十人藏在一个洞里，拿饼和水供养他们。〉'),
('CUV', '列王纪上', 11, 18, 5, '亚哈对俄巴底说：我们走遍这地，到一切水泉旁和一切溪边，或者找得著青草，可以救活骡马，免得绝了牲畜。'),
('CUV', '列王纪上', 11, 18, 6, '于是二人分地游行，亚哈独走一路，俄巴底独走一路。'),
('CUV', '列王纪上', 11, 18, 7, '俄巴底在路上恰与以利亚相遇，俄巴底认出他来，就俯伏在地，说：你是我主以利亚不是？'),
('CUV', '列王纪上', 11, 18, 8, '回答说：是。你去告诉你主人说，以利亚在这里。'),
('CUV', '列王纪上', 11, 18, 9, '俄巴底说：仆人有甚么罪，你竟要将我交在亚哈手里，使他杀我呢？'),
('CUV', '列王纪上', 11, 18, 10, '我指著永生耶和华─你的神起誓，无论哪一邦哪一国，我主都打发人去找你。若说你没有在那里，就必使那邦那国的人起誓说，实在是找不著你。'),
('CUV', '列王纪上', 11, 18, 11, '现在你说，要去告诉你主人说，以利亚在这里；'),
('CUV', '列王纪上', 11, 18, 12, '恐怕我一离开你，耶和华的灵就提你到我所不知道的地方去。这样，我去告诉亚哈，他若找不著你，就必杀我；仆人却是自幼敬畏耶和华的。'),
('CUV', '列王纪上', 11, 18, 13, '耶洗别杀耶和华众先知的时候，我将耶和华的一百个先知藏了，每五十人藏在一个洞里，拿饼和水供养他们，岂没有人将这事告诉我主么？'),
('CUV', '列王纪上', 11, 18, 14, '现在你说，要去告诉你主人说，以利亚在这里，他必杀我。'),
('CUV', '列王纪上', 11, 18, 15, '以利亚说：我指著所事奉永生的万军之耶和华起誓，我今日必使亚哈得见我。'),
('CUV', '列王纪上', 11, 18, 16, '于是俄巴底去迎著亚哈，告诉他；亚哈就去迎著以利亚。'),
('CUV', '列王纪上', 11, 18, 17, '亚哈见了以利亚，便说：使以色列遭灾的就是你么？'),
('CUV', '列王纪上', 11, 18, 18, '以利亚说：使以色列遭灾的不是我，乃是你和你父家；因为你们离弃耶和华的诫命，去随从巴力。'),
('CUV', '列王纪上', 11, 18, 19, '现在你当差遣人，招聚以色列众人和事奉巴力的那四百五十个先知，并耶洗别所供养事奉亚舍拉的那四百个先知，使他们都上迦密山去见我。'),
('CUV', '列王纪上', 11, 18, 20, '亚哈就差遣人招聚以色列众人和先知都上迦密山。'),
('CUV', '列王纪上', 11, 18, 21, '以利亚前来对众民说：你们心持两意要到几时呢？若耶和华是神，就当顺从耶和华；若巴力是神，就当顺从巴力。众民一言不答。'),
('CUV', '列王纪上', 11, 18, 22, '以利亚对众民说：作耶和华先知的只剩下我一个人；巴力的先知却有四百五十个人。'),
('CUV', '列王纪上', 11, 18, 23, '当给我们两只牛犊，巴力的先知可以挑选一只，切成块子，放在柴上，不要点火；我也预备一只牛犊放在柴上，也不点火。'),
('CUV', '列王纪上', 11, 18, 24, '你们求告你们神的名，我也求告耶和华的名。那降火显应的神，就是神。众民回答说：这话甚好。'),
('CUV', '列王纪上', 11, 18, 25, '以利亚对巴力的先知说：你们既是人多，当先挑选一只牛犊，预备好了，就求告你们神的名，却不要点火。'),
('CUV', '列王纪上', 11, 18, 26, '他们将所得的牛犊预备好了，从早晨到午间，求告巴力的名说：巴力啊，求你应允我们！却没有声音，没有应允的。他们在所筑的坛四围踊跳。'),
('CUV', '列王纪上', 11, 18, 27, '到了正午，以利亚嬉笑他们，说：大声求告罢！因为他是神，他或默想，或走到一边，或行路，或睡觉，你们当叫醒他。'),
('CUV', '列王纪上', 11, 18, 28, '他们大声求告，按著他们的规矩，用刀枪自割、自刺，直到身体流血。'),
('CUV', '列王纪上', 11, 18, 29, '从午后直到献晚祭的时候，他们狂呼乱叫，却没有声音，没有应允的，也没有理会的。'),
('CUV', '列王纪上', 11, 18, 30, '以利亚对众民说：你们到我这里来。众民就到他那里。他便重修已经毁坏耶和华的坛。'),
('CUV', '列王纪上', 11, 18, 31, '以利亚照雅各子孙支派的数目，取了十二块石头（耶和华的话曾临到雅各说：你的名要叫以色列），'),
('CUV', '列王纪上', 11, 18, 32, '用这些石头为耶和华的名筑一座坛，在坛的四围挖沟，可容谷种二细亚，'),
('CUV', '列王纪上', 11, 18, 33, '又在坛上摆好了柴，把牛犊切成块子放在柴上，对众人说：你们用四个桶盛满水，倒在燔祭和柴上；'),
('CUV', '列王纪上', 11, 18, 34, '又说：倒第二次。他们就倒第二次；又说：倒第三次。他们就倒第三次。'),
('CUV', '列王纪上', 11, 18, 35, '水流在坛的四围，沟里也满了水。'),
('CUV', '列王纪上', 11, 18, 36, '到了献晚祭的时候，先知以利亚近前来，说：亚伯拉罕、以撒、以色列的神，耶和华啊，求你今日使人知道你是以色列的神，也知道我是你的仆人，又是奉你的命行这一切事。'),
('CUV', '列王纪上', 11, 18, 37, '耶和华啊，求你应允我，应允我！使这民知道你─耶和华是神，又知道是你叫这民的心回转。'),
('CUV', '列王纪上', 11, 18, 38, '于是，耶和华降下火来，烧尽燔祭、木柴、石头、尘土，又烧干沟里的水。'),
('CUV', '列王纪上', 11, 18, 39, '众民看见了，就俯伏在地，说：耶和华是神！耶和华是神！'),
('CUV', '列王纪上', 11, 18, 40, '以利亚对他们说：拿住巴力的先知，不容一人逃脱！众人就拿住他们。以利亚带他们到基顺河边，在那里杀了他们。'),
('CUV', '列王纪上', 11, 18, 41, '以利亚对亚哈说：你现在可以上去吃喝，因为有多雨的响声了。'),
('CUV', '列王纪上', 11, 18, 42, '亚哈就上去吃喝。以利亚上了迦密山顶，屈身在地，将脸伏在两膝之中；'),
('CUV', '列王纪上', 11, 18, 43, '对仆人说：你上去，向海观看。仆人就上去观看，说：没有甚么。他说：你再去观看。如此七次。'),
('CUV', '列王纪上', 11, 18, 44, '第七次仆人说：我看见有一小片云从海里上来，不过如人手那样大。以利亚说：你上去告诉亚哈，当套车下去，免得被雨阻挡。'),
('CUV', '列王纪上', 11, 18, 45, '霎时间，天因风云黑暗，降下大雨。亚哈就坐车往耶斯列去了。'),
('CUV', '列王纪上', 11, 18, 46, '耶和华的灵(原文是手)降在以利亚身上，他就束上腰，奔在亚哈前头，直到耶斯列的城门。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪上', 11, 19, 1, '亚哈将以利亚一切所行的和他用刀杀众先知的事都告诉耶洗别。'),
('CUV', '列王纪上', 11, 19, 2, '耶洗别就差遣人去见以利亚，告诉他说：明日约在这时候，我若不使你的性命像那些人的性命一样，愿神明重重地降罚与我。'),
('CUV', '列王纪上', 11, 19, 3, '以利亚见这光景就起来逃命，到了犹大的别是巴，将仆人留在那里，'),
('CUV', '列王纪上', 11, 19, 4, '自己在旷野走了一日的路程，来到一棵罗腾(小树名，松类；下同)树下，就坐在那里求死，说：耶和华啊，罢了！求你取我的性命，因为我不胜于我的列祖。'),
('CUV', '列王纪上', 11, 19, 5, '他就躺在罗腾树下，睡著了。有一个天使拍他，说：起来吃罢！'),
('CUV', '列王纪上', 11, 19, 6, '他观看，见头旁有一瓶水与炭火烧的饼，他就吃了喝了，仍然躺下。'),
('CUV', '列王纪上', 11, 19, 7, '耶和华的使者第二次来拍他，说：起来吃罢！因为你当走的路甚远。'),
('CUV', '列王纪上', 11, 19, 8, '他就起来吃了喝了，仗著这饮食的力，走了四十昼夜，到了神的山，就是何烈山。'),
('CUV', '列王纪上', 11, 19, 9, '他在那里进了一个洞，就住在洞中。耶和华的话临到他说：以利亚啊，你在这里做甚么？'),
('CUV', '列王纪上', 11, 19, 10, '他说：我为耶和华─万军之神大发热心；因为以色列人背弃了你的约，毁坏了你的坛，用刀杀了你的先知，只剩下我一个人，他们还要寻索我的命。'),
('CUV', '列王纪上', 11, 19, 11, '耶和华说：你出来站在山上，在我面前。那时耶和华从那里经过，在他面前有烈风大作，崩山碎石，耶和华却不在风中；风后地震，耶和华却不在其中；'),
('CUV', '列王纪上', 11, 19, 12, '地震后有火，耶和华也不在火中；火后有微小的声音。'),
('CUV', '列王纪上', 11, 19, 13, '以利亚听见，就用外衣蒙上脸，出来站在洞口。有声音向他说：以利亚啊，你在这里做甚么？'),
('CUV', '列王纪上', 11, 19, 14, '他说：我为耶和华─万军之神大发热心；因为以色列人背弃了你的约，毁坏了你的坛，用刀杀了你的先知，只剩下我一个人，他们还要寻索我的命。'),
('CUV', '列王纪上', 11, 19, 15, '耶和华对他说：你回去，从旷野往大马色去。到了那里，就要膏哈薛作亚兰王，'),
('CUV', '列王纪上', 11, 19, 16, '又膏宁示的孙子耶户作以色列王，并膏亚伯米何拉人沙法的儿子以利沙作先知接续你。'),
('CUV', '列王纪上', 11, 19, 17, '将来躲避哈薛之刀的，必被耶户所杀；躲避耶户之刀的，必被以利沙所杀。'),
('CUV', '列王纪上', 11, 19, 18, '但我在以色列人中为自己留下七千人，是未曾向巴力屈膝的，未曾与巴力亲嘴的。'),
('CUV', '列王纪上', 11, 19, 19, '于是，以利亚离开那里走了，遇见沙法的儿子以利沙耕地；在他前头有十二对牛，自己赶著第十二对。以利亚到他那里去，将自己的外衣搭在他身上。'),
('CUV', '列王纪上', 11, 19, 20, '以利沙就离开牛，跑到以利亚那里，说：求你容我先与父母亲嘴，然后我便跟随你。以利亚对他说：你回去罢，我向你做了甚么呢？'),
('CUV', '列王纪上', 11, 19, 21, '以利沙就离开他回去，宰了一对牛，用套牛的器具煮肉给民吃，随后就起身跟随以利亚，服事他。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪上', 11, 20, 1, '亚兰王便哈达聚集他的全军，率领三十二个王，带著车马上来围攻撒玛利亚；'),
('CUV', '列王纪上', 11, 20, 2, '又差遣使者进城见以色列王亚哈，对他说：便哈达如此说：'),
('CUV', '列王纪上', 11, 20, 3, '你的金银都要归我，你妻子儿女中最美的也要归我。'),
('CUV', '列王纪上', 11, 20, 4, '以色列王回答说：我主我王啊，可以依著你的话，我与我所有的都归你。'),
('CUV', '列王纪上', 11, 20, 5, '使者又来说：便哈达如此说：我已差遣人去见你，要你将你的金银、妻子、儿女都给我。'),
('CUV', '列王纪上', 11, 20, 6, '但明日约在这时候，我还要差遣臣仆到你那里，搜查你的家和你仆人的家，将你眼中一切所喜爱的都拿了去。'),
('CUV', '列王纪上', 11, 20, 7, '以色列王召了国中的长老来，对他们说：请你们看看，这人是怎样地谋害我，他先差遣人到我这里来，要我的妻子、儿女，和金银，我并没有推辞他。'),
('CUV', '列王纪上', 11, 20, 8, '长老和百姓对王说：不要听从他，也不要应允他。'),
('CUV', '列王纪上', 11, 20, 9, '故此，以色列王对便哈达的使者说：你们告诉我主我王说：王头一次差遣人向仆人所要的，仆人都依从；但这次所要的，我不能依从。使者就去回复便哈达。'),
('CUV', '列王纪上', 11, 20, 10, '便哈达又差遣人去见亚哈说：撒玛利亚的尘土若够跟从我的人每人捧一捧的，愿神明重重地降罚与我！'),
('CUV', '列王纪上', 11, 20, 11, '以色列王说：你告诉他说，才顶盔贯甲的，休要像摘盔卸甲的夸口。'),
('CUV', '列王纪上', 11, 20, 12, '便哈达和诸王正在帐幕里喝酒，听见这话，就对他臣仆说：摆队罢！他们就摆队攻城。'),
('CUV', '列王纪上', 11, 20, 13, '有一个先知来见以色列王亚哈，说：耶和华如此说：这一大群人你看见了么？今日我必将他们交在你手里，你就知道我是耶和华。'),
('CUV', '列王纪上', 11, 20, 14, '亚哈说：藉著谁呢？他回答说：耶和华说，藉著跟从省长的少年人。亚哈说：要谁率领呢？他说：要你亲自率领。'),
('CUV', '列王纪上', 11, 20, 15, '于是亚哈数点跟从省长的少年人，共有二百三十二名，后又数点以色列的众兵，共有七千名。'),
('CUV', '列王纪上', 11, 20, 16, '午间，他们就出城；便哈达和帮助他的三十二个王正在帐幕里痛饮。'),
('CUV', '列王纪上', 11, 20, 17, '跟从省长的少年人先出城；便哈达差遣人去探望，他们回报说：有人从撒玛利亚出来了。'),
('CUV', '列王纪上', 11, 20, 18, '他说：他们若为讲和出来，要活捉他们；若为打仗出来，也要活捉他们。'),
('CUV', '列王纪上', 11, 20, 19, '跟从省长的少年人出城，军兵跟随他们；'),
('CUV', '列王纪上', 11, 20, 20, '各人遇见敌人就杀。亚兰人逃跑，以色列人追赶他们；亚兰王便哈达骑著马和马兵一同逃跑。'),
('CUV', '列王纪上', 11, 20, 21, '以色列王出城攻打车马，大大击杀亚兰人。'),
('CUV', '列王纪上', 11, 20, 22, '那先知来见以色列王，对他说：你当自强，留心怎样防备；因为到明年这时候，亚兰王必上来攻击你。'),
('CUV', '列王纪上', 11, 20, 23, '亚兰王的臣仆对亚兰王说：以色列人的神是山神，所以他们胜过我们；但在平原与他们打仗，我们必定得胜。'),
('CUV', '列王纪上', 11, 20, 24, '王当这样行：把诸王革去，派军长代替他们，'),
('CUV', '列王纪上', 11, 20, 25, '又照著王丧失军兵之数，再招募一军，马补马，车补车，我们在平原与他们打仗，必定得胜。王便听臣仆的话去行。'),
('CUV', '列王纪上', 11, 20, 26, '次年，便哈达果然点齐亚兰人上亚弗去，要与以色列人打仗。'),
('CUV', '列王纪上', 11, 20, 27, '以色列人也点齐军兵，预备食物，迎著亚兰人出去，对著他们安营，好像两小群山羊羔；亚兰人却满了地面。'),
('CUV', '列王纪上', 11, 20, 28, '有神人来见以色列王，说：耶和华如此说：亚兰人既说我─耶和华是山神，不是平原的神，所以我必将这一大群人都交在你手中，你们就知道我是耶和华。'),
('CUV', '列王纪上', 11, 20, 29, '以色列人与亚兰人相对安营七日，到第七日两军交战；那一日以色列人杀了亚兰人步兵十万，'),
('CUV', '列王纪上', 11, 20, 30, '其余的逃入亚弗城；城墙塌倒，压死剩下的二万七千人。便哈达也逃入城，藏在严密的屋子里。'),
('CUV', '列王纪上', 11, 20, 31, '他的臣仆对他说：我们听说以色列王都是仁慈的王，现在我们不如腰束麻布，头套绳索，出去投降以色列王，或者他存留王的性命。'),
('CUV', '列王纪上', 11, 20, 32, '于是他们腰束麻布，头套绳索，去见以色列王，说：王的仆人便哈达说，求王存留我的性命。亚哈说：他还活著么？他是我的兄弟。'),
('CUV', '列王纪上', 11, 20, 33, '这些人留心探出他的口气来，便急忙就著他的话说：便哈达是王的兄弟！王说：你们去请他来。便哈达出来见王，王就请他上车。'),
('CUV', '列王纪上', 11, 20, 34, '便哈达对王说：我父从你父那里所夺的城邑，我必归还。你可以在大马色立街市，像我父在撒玛利亚所立的一样。亚哈说：我照此立约，放你回去，就与他立约，放他去了。'),
('CUV', '列王纪上', 11, 20, 35, '有先知的一个门徒奉耶和华的命对他的同伴说：你打我罢！那人不肯打他。'),
('CUV', '列王纪上', 11, 20, 36, '他就对那人说：你既不听从耶和华的话，你一离开我，必有狮子咬死你。那人一离开他，果然遇见狮子，把他咬死了。'),
('CUV', '列王纪上', 11, 20, 37, '先知的门徒又遇见一个人，对他说：你打我罢！那人就打他，将他打伤。'),
('CUV', '列王纪上', 11, 20, 38, '他就去了，用头巾蒙眼，改换面目，在路旁等候王。'),
('CUV', '列王纪上', 11, 20, 39, '王从那里经过，他向王呼叫说：仆人在阵上的时候，有人带了一个人来，对我说：你看守这人，若把他失了，你的性命必代替他的性命；不然，你必交出一他连得银子来。'),
('CUV', '列王纪上', 11, 20, 40, '仆人正在忙乱之间，那人就不见了。以色列王对他说：你自己定妥了，必照样判断你。'),
('CUV', '列王纪上', 11, 20, 41, '他急忙除掉蒙眼的头巾，以色列王就认出他是一个先知。'),
('CUV', '列王纪上', 11, 20, 42, '他对王说：耶和华如此说：因你将我定要灭绝的人放去，你的命就必代替他的命，你的民也必代替他的民。'),
('CUV', '列王纪上', 11, 20, 43, '于是以色列王闷闷不乐地回到撒玛利亚，进了他的宫。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪上', 11, 21, 1, '这事以后，又有一事。耶斯列人拿伯在耶斯列有一个葡萄园，靠近撒玛利亚王亚哈的宫。'),
('CUV', '列王纪上', 11, 21, 2, '亚哈对拿伯说：你将你的葡萄园给我作菜园，因为是靠近我的宫；我就把更好的葡萄园换给你，或是你要银子，我就按著价值给你。'),
('CUV', '列王纪上', 11, 21, 3, '拿伯对亚哈说：我敬畏耶和华，万不敢将我先人留下的产业给你。'),
('CUV', '列王纪上', 11, 21, 4, '亚哈因耶斯列人拿伯说我不敢将我先人留下的产业给你，就闷闷不乐地回宫，躺在床上，转脸向内，也不吃饭。'),
('CUV', '列王纪上', 11, 21, 5, '王后耶洗别来问他说：你为甚么心里这样忧闷，不吃饭呢？'),
('CUV', '列王纪上', 11, 21, 6, '他回答说：因我向耶斯列人拿伯说：你将你的葡萄园给我，我给你价银，或是你愿意，我就把别的葡萄园换给你；他却说：我不将我的葡萄园给你。'),
('CUV', '列王纪上', 11, 21, 7, '王后耶洗别对亚哈说：你现在是治理以色列国不是？只管起来，心里畅畅快快地吃饭，我必将耶斯列人拿伯的葡萄园给你。'),
('CUV', '列王纪上', 11, 21, 8, '于是托亚哈的名写信，用王的印印上，送给那些与拿伯同城居住的长老贵胄。'),
('CUV', '列王纪上', 11, 21, 9, '信上写著说：你们当宣告禁食，叫拿伯坐在民间的高位上，'),
('CUV', '列王纪上', 11, 21, 10, '又叫两个匪徒坐在拿伯对面，作见证告他说：你谤渎神和王了；随后就把他拉出去用石头打死。'),
('CUV', '列王纪上', 11, 21, 11, '那些与拿伯同城居住的长老贵胄得了耶洗别的信，就照信而行，'),
('CUV', '列王纪上', 11, 21, 12, '宣告禁食，叫拿伯坐在民间的高位上。'),
('CUV', '列王纪上', 11, 21, 13, '有两个匪徒来，坐在拿伯的对面，当著众民作见证告他说：拿伯谤渎神和王了！众人就把他拉到城外，用石头打死。'),
('CUV', '列王纪上', 11, 21, 14, '于是打发人去见耶洗别，说：拿伯被石头打死了。'),
('CUV', '列王纪上', 11, 21, 15, '耶洗别听见拿伯被石头打死，就对亚哈说：你起来得耶斯列人拿伯不肯为价银给你的葡萄园罢！现在他已经死了。'),
('CUV', '列王纪上', 11, 21, 16, '亚哈听见拿伯死了，就起来，下去要得耶斯列人拿伯的葡萄园。'),
('CUV', '列王纪上', 11, 21, 17, '耶和华的话临到提斯比人以利亚说：'),
('CUV', '列王纪上', 11, 21, 18, '你起来，去见住撒玛利亚的以色列王亚哈，他下去要得拿伯的葡萄园，现今正在那园里。'),
('CUV', '列王纪上', 11, 21, 19, '你要对他说：耶和华如此说：你杀了人，又得他的产业么？又要对他说：耶和华如此说：狗在何处舔拿伯的血，也必在何处舔你的血。'),
('CUV', '列王纪上', 11, 21, 20, '亚哈对以利亚说：我仇敌啊，你找到我么？他回答说：我找到你了；因为你卖了自己，行耶和华眼中看为恶的事。'),
('CUV', '列王纪上', 11, 21, 21, '耶和华说：我必使灾祸临到你，将你除尽。凡属你的男丁，无论困住的、自由的，都从以色列中剪除。'),
('CUV', '列王纪上', 11, 21, 22, '我必使你的家像尼八的儿子耶罗波安的家，又像亚希雅的儿子巴沙的家；因为你惹我发怒，又使以色列人陷在罪里。'),
('CUV', '列王纪上', 11, 21, 23, '论到耶洗别，耶和华也说：狗在耶斯列的外郭必吃耶洗别的肉。'),
('CUV', '列王纪上', 11, 21, 24, '凡属亚哈的人，死在城中的必被狗吃，死在田野的必被空中的鸟吃。'),
('CUV', '列王纪上', 11, 21, 25, '（从来没有像亚哈的，因他自卖，行耶和华眼中看为恶的事，受了王后耶洗别的耸动；'),
('CUV', '列王纪上', 11, 21, 26, '就照耶和华在以色列人面前所赶出的亚摩利人，行了最可憎恶的事，信从偶像。）'),
('CUV', '列王纪上', 11, 21, 27, '亚哈听见这话，就撕裂衣服，禁食，身穿麻布，睡卧也穿著麻布，并且缓缓而行。'),
('CUV', '列王纪上', 11, 21, 28, '耶和华的话临到提斯比人以利亚说：'),
('CUV', '列王纪上', 11, 21, 29, '亚哈在我面前这样自卑，你看见了么？因他在我面前自卑，他还在世的时候，我不降这祸；到他儿子的时候，我必降这祸与他的家。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪上', 11, 22, 1, '亚兰国和以色列国三年没有争战。'),
('CUV', '列王纪上', 11, 22, 2, '到第三年，犹大王约沙法下去见以色列王。'),
('CUV', '列王纪上', 11, 22, 3, '以色列王对臣仆说：你们不知道基列的拉末是属我们的么？我们岂可静坐不动，不从亚兰王手里夺回来么？'),
('CUV', '列王纪上', 11, 22, 4, '亚哈问约沙法说：你肯同我去攻取基列的拉末吗？约沙法对以色列王说：你我不分彼此，我的民与你的民一样，我的马与你的马一样。'),
('CUV', '列王纪上', 11, 22, 5, '约沙法对以色列王说：请你先求问耶和华。'),
('CUV', '列王纪上', 11, 22, 6, '于是以色列王招聚先知，约有四百人，问他们说：我上去攻取基列的拉末可以不可以？他们说：可以上去，因为主必将那城交在王的手里。'),
('CUV', '列王纪上', 11, 22, 7, '约沙法说：这里不是还有耶和华的先知，我们可以求问他么？'),
('CUV', '列王纪上', 11, 22, 8, '以色列王对约沙法说：还有一个人，是音拉的儿子米该雅，我们可以托他求问耶和华。只是我恨他；因为他指著我所说的预言，不说吉语，单说凶言。约沙法说：王不必这样说。'),
('CUV', '列王纪上', 11, 22, 9, '以色列王就召了一个太监来，说：你快去，将音拉的儿子米该雅召来。'),
('CUV', '列王纪上', 11, 22, 10, '以色列王和犹大王约沙法在撒玛利亚城门前的空场上，各穿朝服，坐在位上，所有的先知都在他们面前说预言。'),
('CUV', '列王纪上', 11, 22, 11, '基拿拿的儿子西底家造了两个铁角，说：耶和华如此说：你要用这角抵触亚兰人，直到将他们灭尽。'),
('CUV', '列王纪上', 11, 22, 12, '所有的先知也都这样预言说：可以上基列的拉末去，必然得胜，因为耶和华必将那城交在王的手中。'),
('CUV', '列王纪上', 11, 22, 13, '那去召米该雅的使者对米该雅说；众先知一口同音地都向王说吉言，你不如与他们说一样的话，也说吉言。'),
('CUV', '列王纪上', 11, 22, 14, '米该雅说：我指著永生的耶和华起誓，耶和华对我说甚么，我就说甚么。'),
('CUV', '列王纪上', 11, 22, 15, '米该雅到王面前，王问他说：米该雅啊，我们上去攻取基列的拉末可以不可以？他回答说：可以上去，必然得胜，耶和华必将那城交在王的手中。'),
('CUV', '列王纪上', 11, 22, 16, '王对他说：我当嘱咐你几次，你才奉耶和华的名向我说实话呢？'),
('CUV', '列王纪上', 11, 22, 17, '米该雅说：我看见以色列众民散在山上，如同没有牧人的羊群一般。耶和华说：这民没有主人，他们可以平平安安地各归各家去。'),
('CUV', '列王纪上', 11, 22, 18, '以色列王对约沙法说：我岂没有告诉你，这人指著我所说的预言，不说吉语单说凶言么？'),
('CUV', '列王纪上', 11, 22, 19, '米该雅说：你要听耶和华的话！我看见耶和华坐在宝座上，天上的万军侍立在他左右。'),
('CUV', '列王纪上', 11, 22, 20, '耶和华说：谁去引诱亚哈上基列的拉末去阵亡呢？这个就这样说，那个就那样说。'),
('CUV', '列王纪上', 11, 22, 21, '随后有一个神灵出来，站在耶和华面前，说：我去引诱他。'),
('CUV', '列王纪上', 11, 22, 22, '耶和华问他说：你用何法呢？他说：我去，要在他众先知口中作谎言的灵。耶和华说：这样，你必能引诱他，你去如此行罢！'),
('CUV', '列王纪上', 11, 22, 23, '现在耶和华使谎言的灵入了你这些先知的口，并且耶和华已经命定降祸与你。'),
('CUV', '列王纪上', 11, 22, 24, '基拿拿的儿子西底家前来，打米该雅的脸，说：耶和华的灵从哪里离开我与你说话呢？'),
('CUV', '列王纪上', 11, 22, 25, '米该雅说：你进严密的屋子藏躲的那日，就必看见了。'),
('CUV', '列王纪上', 11, 22, 26, '以色列王说：将米该雅带回，交给邑宰亚们和王的儿子约阿施，说'),
('CUV', '列王纪上', 11, 22, 27, '王如此说，把这个人下在监里，使他受苦，吃不饱喝不足，等候我平平安安地回来。'),
('CUV', '列王纪上', 11, 22, 28, '米该雅说：你若能平平安安地回来，那就是耶和华没有藉我说这话了；又说：众民哪，你们都要听！'),
('CUV', '列王纪上', 11, 22, 29, '以色列王和犹大王约沙法上基列的拉末去了。'),
('CUV', '列王纪上', 11, 22, 30, '以色列王对约沙法说：我要改装上阵，你可以仍穿王服。以色列王就改装上阵。'),
('CUV', '列王纪上', 11, 22, 31, '先是亚兰王吩咐他的三十二个车兵长说：他们的兵将，无论大小，你们都不可与他们争战，只要与以色列王争战。'),
('CUV', '列王纪上', 11, 22, 32, '车兵长看见约沙法，便说：这必是以色列王！就转过去与他争战，约沙法便呼喊。'),
('CUV', '列王纪上', 11, 22, 33, '车兵长见不是以色列王，就转去不追他了。'),
('CUV', '列王纪上', 11, 22, 34, '有一人随便开弓，恰巧射入以色列王的甲缝里。王对赶车的说：我受了重伤，你转过车来，拉我出阵罢！'),
('CUV', '列王纪上', 11, 22, 35, '那日，阵势越战越猛，有人扶王站在车上，抵挡亚兰人。到晚上，王就死了，血从伤处流在车中。'),
('CUV', '列王纪上', 11, 22, 36, '约在日落的时候，有号令传遍军中，说：各归本城，各归本地罢！'),
('CUV', '列王纪上', 11, 22, 37, '王既死了，众人将他送到撒玛利亚，就葬在那里；'),
('CUV', '列王纪上', 11, 22, 38, '又有人把他的车洗在撒玛利亚的池旁（妓女在那里洗澡），狗来舔他的血，正如耶和华所说的话。'),
('CUV', '列王纪上', 11, 22, 39, '亚哈其余的事，凡他所行的和他所修造的象牙宫，并所建筑的一切城邑，都写在以色列诸王记上。'),
('CUV', '列王纪上', 11, 22, 40, '亚哈与他列祖同睡。他儿子亚哈谢接续他作王。'),
('CUV', '列王纪上', 11, 22, 41, '以色列王亚哈第四年，亚撒的儿子约沙法登基作了犹大王。'),
('CUV', '列王纪上', 11, 22, 42, '约沙法登基的时候年三十五岁，在耶路撒冷作王二十五年。他母亲名叫阿苏巴，乃示利希的女儿。'),
('CUV', '列王纪上', 11, 22, 43, '约沙法行他父亲亚撒所行的道，不偏离左右，行耶和华眼中看为正的事；只是邱坛还没有废去，百姓仍在那里献祭烧香。'),
('CUV', '列王纪上', 11, 22, 44, '约沙法与以色列王和好。'),
('CUV', '列王纪上', 11, 22, 45, '约沙法其余的事和他所显出的勇力，并他怎样争战，都写在犹大列王记上。'),
('CUV', '列王纪上', 11, 22, 46, '约沙法将他父亲亚撒在世所剩下的娈童都从国中除去了。'),
('CUV', '列王纪上', 11, 22, 47, '那时以东没有王，有总督治理。'),
('CUV', '列王纪上', 11, 22, 48, '约沙法制造他施船只，要往俄斐去，将金子运来；只是没有去，因为船在以旬迦别破坏了。'),
('CUV', '列王纪上', 11, 22, 49, '亚哈的儿子亚哈谢对约沙法说：容我的仆人和你的仆人坐船同去罢！约沙法却不肯。'),
('CUV', '列王纪上', 11, 22, 50, '约沙法与列祖同睡。葬在大卫城他列祖的坟地里。他儿子约兰接续他作王。'),
('CUV', '列王纪上', 11, 22, 51, '犹大王约沙法十七年，亚哈的儿子亚哈谢在撒玛利亚登基，作以色列王共二年。'),
('CUV', '列王纪上', 11, 22, 52, '他行耶和华眼中看为恶的事，效法他的父母，又行尼八的儿子耶罗波安使以色列人陷在罪里的事。'),
('CUV', '列王纪上', 11, 22, 53, '他照他父亲一切所行的，事奉敬拜巴力，惹耶和华─以色列神的怒气。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪下', 12, 1, 1, '亚哈死后，摩押背叛以色列。'),
('CUV', '列王纪下', 12, 1, 2, '亚哈谢在撒玛利亚，一日从楼上的栏杆里掉下来，就病了；于是差遣使者说：你们去问以革伦的神巴力西卜，我这病能好不能好。'),
('CUV', '列王纪下', 12, 1, 3, '但耶和华的使者对提斯比人以利亚说：你起来，去迎著撒玛利亚王的使者，对他们说：你们去问以革伦神巴力西卜，岂因以色列中没有神么？'),
('CUV', '列王纪下', 12, 1, 4, '所以耶和华如此说：你必不下你所上的床，必定要死！以利亚就去了。'),
('CUV', '列王纪下', 12, 1, 5, '使者回来见王，王问他们说：你们为甚么回来呢？'),
('CUV', '列王纪下', 12, 1, 6, '使者回答说：有一个人迎著我们来，对我们说：你们回去见差你们来的王，对他说：耶和华如此说，你差人去问以革伦神巴力西卜，岂因以色列中没有神么？所以你必不下所上的床，必定要死。'),
('CUV', '列王纪下', 12, 1, 7, '王问他们说：迎著你们来告诉你们这话的，是怎样的人？'),
('CUV', '列王纪下', 12, 1, 8, '回答说：他身穿毛衣，腰束皮带。王说：这必是提斯比人以利亚。'),
('CUV', '列王纪下', 12, 1, 9, '于是，王差遣五十夫长，带领五十人去见以利亚，他就上到以利亚那里；以利亚正坐在山顶上。五十夫长对他说：神人哪，王吩咐你下来！'),
('CUV', '列王纪下', 12, 1, 10, '以利亚回答说：我若是神人，愿火从天上降下来，烧灭你和你那五十人！于是有火从天上降下来，烧灭五十夫长和他那五十人。'),
('CUV', '列王纪下', 12, 1, 11, '王第二次差遣一个五十夫长，带领五十人去见以利亚。五十夫长对以利亚说：神人哪，王吩咐你快快下来！'),
('CUV', '列王纪下', 12, 1, 12, '以利亚回答说：我若是神人，愿火从天上降下来，烧灭你和你那五十人！于是神的火从天上降下来，烧灭五十夫长和他那五十人。'),
('CUV', '列王纪下', 12, 1, 13, '王第三次差遣一个五十夫长，带领五十人去。这五十夫长上去，双膝跪在以利亚面前，哀求他说：神人哪，愿我的性命和你这五十个仆人的性命在你眼前看为宝贵！'),
('CUV', '列王纪下', 12, 1, 14, '已经有火从天上降下来，烧灭前两次来的五十夫长和他们各自带的五十人；现在愿我的性命在你眼前看为宝贵！'),
('CUV', '列王纪下', 12, 1, 15, '耶和华的使者对以利亚说：你同著他下去，不要怕他！以利亚就起来，同著他下去见王，'),
('CUV', '列王纪下', 12, 1, 16, '对王说：耶和华如此说：你差人去问以革伦神巴力西卜，岂因以色列中没有神可以求问么？所以你必不下所上的床，必定要死！'),
('CUV', '列王纪下', 12, 1, 17, '亚哈谢果然死了，正如耶和华借以利亚所说的话。因他没有儿子，他兄弟约兰接续他作王，正在犹大王约沙法的儿子约兰第二年。'),
('CUV', '列王纪下', 12, 1, 18, '亚哈谢其余所行的事都写在以色列诸王记上。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪下', 12, 2, 1, '耶和华要用旋风接以利亚升天的时候，以利亚与以利沙从吉甲前往。'),
('CUV', '列王纪下', 12, 2, 2, '以利亚对以利沙说：耶和华差我往伯特利去，你可以在这里等候。以利沙说：我指著永生的耶和华，又敢在你面前起誓，我必不离开你。于是二人下到伯特利。'),
('CUV', '列王纪下', 12, 2, 3, '住伯特利的先知门徒出来见以利沙，对他说：耶和华今日要接你的师傅离开你，你知道不知道？他说：我知道，你们不要作声。'),
('CUV', '列王纪下', 12, 2, 4, '以利亚对以利沙说：耶和华差遣我往耶利哥去，你可以在这里等候。以利沙说：我指著永生的耶和华，又敢在你面前起誓，我必不离开你。于是二人到了耶利哥。'),
('CUV', '列王纪下', 12, 2, 5, '住耶利哥的先知门徒就近以利沙，对他说：耶和华今日要接你的师傅离开你，你知道不知道？他说：我知道，你们不要作声。'),
('CUV', '列王纪下', 12, 2, 6, '以利亚对以利沙说：耶和华差遣我往约但河去，你可以在这里等候。以利沙说：我指著永生的耶和华，又敢在你面前起誓，我必不离开你。于是二人一同前往。'),
('CUV', '列王纪下', 12, 2, 7, '有先知门徒去了五十人，远远地站在他们对面；二人在约但河边站住。'),
('CUV', '列王纪下', 12, 2, 8, '以利亚将自己的外衣卷起来，用以打水，水就左右分开，二人走干地而过。'),
('CUV', '列王纪下', 12, 2, 9, '过去之后，以利亚对以利沙说：我未曾被接去离开你，你要我为你做甚么，只管求我。以利沙说：愿感动你的灵加倍地感动我。'),
('CUV', '列王纪下', 12, 2, 10, '以利亚说：你所求的难得。虽然如此，我被接去离开你的时候，你若看见我，就必得著；不然，必得不著了。'),
('CUV', '列王纪下', 12, 2, 11, '他们正走著说话，忽有火车火马将二人隔开，以利亚就乘旋风升天去了。'),
('CUV', '列王纪下', 12, 2, 12, '以利沙看见，就呼叫说：我父啊！我父啊！以色列的战车马兵啊！以后不再见他了。于是以利沙把自己的衣服撕为两片。'),
('CUV', '列王纪下', 12, 2, 13, '他拾起以利亚身上掉下来的外衣，回去站在约但河边。'),
('CUV', '列王纪下', 12, 2, 14, '他用以利亚身上掉下来的外衣打水，说：耶和华─以利亚的神在哪里呢？打水之后，水也左右分开，以利沙就过来了。'),
('CUV', '列王纪下', 12, 2, 15, '住耶利哥的先知门徒从对面看见他，就说：感动以利亚的灵感动以利沙了。他们就来迎接他，在他面前俯伏于地，'),
('CUV', '列王纪下', 12, 2, 16, '对他说：仆人们这里有五十个壮士，求你容他们去寻找你师傅，或者耶和华的灵将他提起来，投在某山某谷。以利沙说：你们不必打发人去。'),
('CUV', '列王纪下', 12, 2, 17, '他们再三催促他，他难以推辞，就说：你们打发人去罢！他们便打发五十人去，寻找了三天，也没有找著。'),
('CUV', '列王纪下', 12, 2, 18, '以利沙仍然在耶利哥等候他们回到他那里；他对他们说：我岂没有告诉你们不必去么？'),
('CUV', '列王纪下', 12, 2, 19, '耶利哥城的人对以利沙说：这城的地势美好，我主看见了；只是水恶劣，土产不熟而落。'),
('CUV', '列王纪下', 12, 2, 20, '以利沙说：你们拿一个新瓶来，装盐给我；他们就拿来给他。'),
('CUV', '列王纪下', 12, 2, 21, '他出到水源，将盐倒在水中，说：耶和华如此说：我治好了这水，从此必不再使人死，也不再使地土不生产。'),
('CUV', '列王纪下', 12, 2, 22, '于是那水治好了，直到今日，正如以利沙所说的。'),
('CUV', '列王纪下', 12, 2, 23, '以利沙从那里上伯特利去，正上去的时候，有些童子从城里出来，戏笑他说：秃头的上去罢！秃头的上去罢！'),
('CUV', '列王纪下', 12, 2, 24, '他回头看见，就奉耶和华的名咒诅他们。于是有两个母熊从林中出来，撕裂他们中间四十二个童子。'),
('CUV', '列王纪下', 12, 2, 25, '以利沙从伯特利上迦密山，又从迦密山回到撒玛利亚。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪下', 12, 3, 1, '犹大王约沙法十八年，亚哈的儿子约兰在撒玛利亚登基作了以色列王十二年。'),
('CUV', '列王纪下', 12, 3, 2, '他行耶和华眼中看为恶的事，但不至像他父母所行的，因为除掉他父所造巴力的柱像。'),
('CUV', '列王纪下', 12, 3, 3, '然而，他贴近尼八的儿子耶罗波安使以色列人陷在罪里的那罪，总不离开。'),
('CUV', '列王纪下', 12, 3, 4, '摩押王米沙牧养许多羊，每年将十万羊羔的毛和十万公绵羊的毛给以色列王进贡。'),
('CUV', '列王纪下', 12, 3, 5, '亚哈死后，摩押王背叛以色列王。'),
('CUV', '列王纪下', 12, 3, 6, '那时约兰王出撒玛利亚，数点以色列众人。'),
('CUV', '列王纪下', 12, 3, 7, '前行的时候，差人去见犹大王约沙法，说：摩押王背叛我，你肯同我去攻打摩押么？他说：我肯上去，你我不分彼此，我的民与你的民一样，我的马与你的马一样。'),
('CUV', '列王纪下', 12, 3, 8, '约兰说：我们从哪条路上去呢？回答说：从以东旷野的路上去。'),
('CUV', '列王纪下', 12, 3, 9, '于是，以色列王和犹大王，并以东王，都一同去绕行七日的路程；军队和所带的牲畜没有水喝。'),
('CUV', '列王纪下', 12, 3, 10, '以色列王说：哀哉！耶和华招聚我们这三王，乃要交在摩押人的手里。'),
('CUV', '列王纪下', 12, 3, 11, '约沙法说：这里不是有耶和华的先知么？我们可以托他求问耶和华。以色列王的一个臣子回答说：这里有沙法的儿子以利沙，就是从前服事以利亚的(原文作倒水在以利亚手上的)。'),
('CUV', '列王纪下', 12, 3, 12, '约沙法说：他必有耶和华的话。于是以色列王和约沙法，并以东王都下去见他。'),
('CUV', '列王纪下', 12, 3, 13, '以利沙对以色列王说：我与你何干？去问你父亲的先知和你母亲的先知罢！以色列王对他说：不要这样说，耶和华招聚我们这三王，乃要交在摩押人的手里。'),
('CUV', '列王纪下', 12, 3, 14, '以利沙说：我指著所事奉永生的万军耶和华起誓，我若不看犹大王约沙法的情面，必不理你，不顾你。'),
('CUV', '列王纪下', 12, 3, 15, '现在你们给我找一个弹琴的来。弹琴的时候，耶和华的灵(原文作手)就降在以利沙身上。'),
('CUV', '列王纪下', 12, 3, 16, '他便说：耶和华如此说：你们要在这谷中满处挖沟；'),
('CUV', '列王纪下', 12, 3, 17, '因为耶和华如此说：你们虽不见风，不见雨，这谷必满了水，使你们和牲畜有水喝。'),
('CUV', '列王纪下', 12, 3, 18, '在耶和华眼中这还算为小事，他也必将摩押人交在你们手中。'),
('CUV', '列王纪下', 12, 3, 19, '你们必攻破一切坚城美邑，砍伐各种佳树，塞住一切水泉，用石头糟踏一切美田。'),
('CUV', '列王纪下', 12, 3, 20, '次日早晨，约在献祭的时候，有水从以东而来，遍地就满了水。'),
('CUV', '列王纪下', 12, 3, 21, '摩押众人听见这三王上来要与他们争战，凡能顶盔贯甲的，无论老少，尽都聚集站在边界上。'),
('CUV', '列王纪下', 12, 3, 22, '次日早晨，日光照在水上，摩押人起来，看见对面水红如血，'),
('CUV', '列王纪下', 12, 3, 23, '就说：这是血啊！必是三王互相击杀，俱都灭亡。摩押人哪，我们现在去抢夺财物罢！'),
('CUV', '列王纪下', 12, 3, 24, '摩押人到了以色列营，以色列人就起来攻打他们，以致他们在以色列人面前逃跑。以色列人往前追杀摩押人，直杀入摩押的境内，'),
('CUV', '列王纪下', 12, 3, 25, '拆毁摩押的城邑，各人抛石填满一切美田，塞住一切水泉，砍伐各种佳树，只剩下吉珥哈列设的石墙；甩石的兵在四围攻打那城。'),
('CUV', '列王纪下', 12, 3, 26, '摩押王见阵势甚大，难以对敌，就率领七百拿刀的兵，要冲过阵去到以东王那里，却是不能；'),
('CUV', '列王纪下', 12, 3, 27, '便将那应当接续他作王的长子，在城上献为燔祭。以色列人遭遇耶和华的大怒(或作招人痛恨)，于是三王离开摩押王，各回本国去了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪下', 12, 4, 1, '有一个先知门徒的妻哀求以利沙说：你仆人─我丈夫死了，他敬畏耶和华是你所知道的。现在有债主来，要取我两个儿子作奴仆。'),
('CUV', '列王纪下', 12, 4, 2, '以利沙问他说：我可以为你做甚么呢？你告诉我，你家里有甚么？他说：婢女家中除了一瓶油之外，没有甚么。'),
('CUV', '列王纪下', 12, 4, 3, '以利沙说：你去，向你众邻舍借空器皿，不要少借；'),
('CUV', '列王纪下', 12, 4, 4, '回到家里，关上门，你和你儿子在里面将油倒在所有的器皿里，倒满了的放在一边。'),
('CUV', '列王纪下', 12, 4, 5, '于是，妇人离开以利沙去了，关上门，自己和儿子在里面；儿子把器皿拿来，他就倒油。'),
('CUV', '列王纪下', 12, 4, 6, '器皿都满了，他对儿子说：再给我拿器皿来。儿子说：再没有器皿了。油就止住了。'),
('CUV', '列王纪下', 12, 4, 7, '妇人去告诉神人，神人说：你去卖油还债，所剩的你和你儿子可以靠著度日。'),
('CUV', '列王纪下', 12, 4, 8, '一日，以利沙走到书念，在那里有一个大户的妇人强留他吃饭。此后，以利沙每从那里经过就进去吃饭。'),
('CUV', '列王纪下', 12, 4, 9, '妇人对丈夫说：我看出那常从我们这里经过的是圣洁的神人。'),
('CUV', '列王纪下', 12, 4, 10, '我们可以为他在墙上盖一间小楼，在其中安放床榻、桌子、椅子、灯台，他来到我们这里，就可以住在其间。'),
('CUV', '列王纪下', 12, 4, 11, '一日，以利沙来到那里，就进了那楼躺卧。'),
('CUV', '列王纪下', 12, 4, 12, '以利沙吩咐仆人基哈西说：你叫这书念妇人来。他就把妇人叫了来，妇人站在以利沙面前。'),
('CUV', '列王纪下', 12, 4, 13, '以利沙吩咐仆人说：你对他说：你既为我们费了许多心思，可以为你做甚么呢？你向王或元帅有所求的没有？他回答说：我在我本乡安居无事。'),
('CUV', '列王纪下', 12, 4, 14, '以利沙对仆人说：究竟当为他做甚么呢？基哈西说：他没有儿子，他丈夫也老了。'),
('CUV', '列王纪下', 12, 4, 15, '以利沙说：再叫他来。于是叫了他来，他就站在门口。'),
('CUV', '列王纪下', 12, 4, 16, '以利沙说：明年到这时候，你必抱一个儿子。他说：神人，我主啊，不要那样欺哄婢女。'),
('CUV', '列王纪下', 12, 4, 17, '妇人果然怀孕，到了那时候，生了一个儿子，正如以利沙所说的。'),
('CUV', '列王纪下', 12, 4, 18, '孩子渐渐长大，一日到他父亲和收割的人那里，'),
('CUV', '列王纪下', 12, 4, 19, '他对父亲说：我的头啊，我的头啊！他父亲对仆人说：把他抱到他母亲那里。'),
('CUV', '列王纪下', 12, 4, 20, '仆人抱去，交给他母亲；孩子坐在母亲的膝上，到晌午就死了。'),
('CUV', '列王纪下', 12, 4, 21, '他母亲抱他上了楼，将他放在神人的床上，关上门出来，'),
('CUV', '列王纪下', 12, 4, 22, '呼叫他丈夫说：你叫一个仆人给我牵一匹驴来，我要快快地去见神人，就回来。'),
('CUV', '列王纪下', 12, 4, 23, '丈夫说：今日不是月朔，也不是安息日，你为何要去见他呢？妇人说：平安无事。'),
('CUV', '列王纪下', 12, 4, 24, '于是备上驴，对仆人说：你快快赶著走，我若不吩咐你，就不要迟慢。'),
('CUV', '列王纪下', 12, 4, 25, '妇人就往迦密山去见神人。神人远远地看见他，对仆人基哈西说：看哪，书念的妇人来了！'),
('CUV', '列王纪下', 12, 4, 26, '你跑去迎接他，问他说：你平安么？你丈夫平安么？孩子平安么？他说：平安。'),
('CUV', '列王纪下', 12, 4, 27, '妇人上了山，到神人那里，就抱住神人的脚。基哈西前来要推开他，神人说：由他罢！因为他心里愁苦，耶和华向我隐瞒，没有指示我。'),
('CUV', '列王纪下', 12, 4, 28, '妇人说：我何尝向我主求过儿子呢？我岂没有说过，不要欺哄我么？'),
('CUV', '列王纪下', 12, 4, 29, '以利沙吩咐基哈西说：你束上腰，手拿我的杖前去；若遇见人，不要向他问安；人若向你问安，也不要回答；要把我的杖放在孩子脸上。'),
('CUV', '列王纪下', 12, 4, 30, '孩子的母亲说：我指著永生的耶和华，又敢在你面前起誓，我必不离开你。于是以利沙起身，随著他去了。'),
('CUV', '列王纪下', 12, 4, 31, '基哈西先去，把杖放在孩子脸上，却没有声音，也没有动静。基哈西就迎著以利沙回来，告诉他说：孩子还没有醒过来。'),
('CUV', '列王纪下', 12, 4, 32, '以利沙来到，进了屋子，看见孩子死了，放在自己的床上。'),
('CUV', '列王纪下', 12, 4, 33, '他就关上门，只有自己和孩子在里面，他便祈祷耶和华，'),
('CUV', '列王纪下', 12, 4, 34, '上床伏在孩子身上，口对口，眼对眼，手对手；既伏在孩子身上，孩子的身体就渐渐温和了。'),
('CUV', '列王纪下', 12, 4, 35, '然后他下来，在屋里来往走了一趟，又上去伏在孩子身上，孩子打了七个喷嚏，就睁开眼睛了。'),
('CUV', '列王纪下', 12, 4, 36, '以利沙叫基哈西说：你叫这书念妇人来；于是叫了他来。以利沙说：将你儿子抱起来。'),
('CUV', '列王纪下', 12, 4, 37, '妇人就进来，在以利沙脚前俯伏于地，抱起他儿子出去了。'),
('CUV', '列王纪下', 12, 4, 38, '以利沙又来到吉甲，那地正有饥荒。先知门徒坐在他面前，他吩咐仆人说：你将大锅放在火上，给先知门徒熬汤。'),
('CUV', '列王纪下', 12, 4, 39, '有一个人去到田野掐菜，遇见一棵野瓜籐，就摘了一兜野瓜回来，切了搁在熬汤的锅中，因为他们不知道是甚么东西；'),
('CUV', '列王纪下', 12, 4, 40, '倒出来给众人吃，吃的时候，都喊叫说：神人哪，锅中有致死的毒物！所以众人不能吃了。'),
('CUV', '列王纪下', 12, 4, 41, '以利沙说：拿点面来，就把面撒在锅中，说：倒出来，给众人吃罢！锅中就没有毒了。'),
('CUV', '列王纪下', 12, 4, 42, '有一个人从巴力沙利沙来，带著初熟大麦做的饼二十个，并新穗子，装在口袋里送给神人。神人说：把这些给众人吃。'),
('CUV', '列王纪下', 12, 4, 43, '仆人说：这一点岂可摆给一百人吃呢？以利沙说：你只管给众人吃罢！因为耶和华如此说，众人必吃了，还剩下。'),
('CUV', '列王纪下', 12, 4, 44, '仆人就摆在众人面前，他们吃了，果然还剩下，正如耶和华所说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪下', 12, 5, 1, '亚兰王的元帅乃缦在他主人面前为尊为大，因耶和华曾藉他使亚兰人得胜；他又是大能的勇士，只是长了大痲疯。'),
('CUV', '列王纪下', 12, 5, 2, '先前亚兰人成群地出去，从以色列国掳了一个小女子，这女子就服事乃缦的妻。'),
('CUV', '列王纪下', 12, 5, 3, '他对主母说：巴不得我主人去见撒玛利亚的先知，必能治好他的大痲疯。'),
('CUV', '列王纪下', 12, 5, 4, '乃缦进去，告诉他主人说，以色列国的女子如此如此说。'),
('CUV', '列王纪下', 12, 5, 5, '亚兰王说：你可以去，我也达信于以色列王。于是乃缦带银子十他连得，金子六千舍客勒，衣裳十套，就去了；'),
('CUV', '列王纪下', 12, 5, 6, '且带信给以色列王，信上说：我打发臣仆乃缦去见你，你接到这信，就要治好他的大痲疯。'),
('CUV', '列王纪下', 12, 5, 7, '以色列王看了信就撕裂衣服，说：我岂是神，能使人死使人活呢？这人竟打发人来，叫我治好他的大痲疯。你们看一看，这人何以寻隙攻击我呢？'),
('CUV', '列王纪下', 12, 5, 8, '神人以利沙听见以色列王撕裂衣服，就打发人去见王，说：你为甚么撕了衣服呢？可使那人到我这里来，他就知道以色列中有先知了。'),
('CUV', '列王纪下', 12, 5, 9, '于是，乃缦带著车马到了以利沙的家，站在门前。'),
('CUV', '列王纪下', 12, 5, 10, '以利沙打发一个使者，对乃缦说：你去在约但河中沐浴七回，你的肉就必复原，而得洁净。'),
('CUV', '列王纪下', 12, 5, 11, '乃缦却发怒走了，说：我想他必定出来见我，站著求告耶和华─他神的名，在患处以上摇手，治好这大痲疯。'),
('CUV', '列王纪下', 12, 5, 12, '大马色的河亚罢拿和法珥法岂不比以色列的一切水更好么？我在那里沐浴不得洁净么？于是气忿忿地转身去了。'),
('CUV', '列王纪下', 12, 5, 13, '他的仆人进前来，对他说：我父啊，先知若吩咐你做一件大事，你岂不做么？何况说你去沐浴而得洁净呢？'),
('CUV', '列王纪下', 12, 5, 14, '于是乃缦下去，照著神人的话，在约但河里沐浴七回；他的肉复原，好像小孩子的肉，他就洁净了。'),
('CUV', '列王纪下', 12, 5, 15, '乃缦带著一切跟随他的人，回到神人那里，站在他面前，说：如今我知道，除了以色列之外，普天下没有神。现在求你收点仆人的礼物。'),
('CUV', '列王纪下', 12, 5, 16, '以利沙说：我指著所事奉永生的耶和华起誓，我必不受。乃缦再三地求他，他却不受。'),
('CUV', '列王纪下', 12, 5, 17, '乃缦说：你若不肯受，请将两骡子驮的土赐给仆人。从今以后，仆人必不再将燔祭或平安祭献与别神，只献给耶和华。'),
('CUV', '列王纪下', 12, 5, 18, '惟有一件事，愿耶和华饶恕你仆人：我主人进临门庙叩拜的时候，我用手搀他在临门庙，我也屈身。我在临门庙屈身的这事，愿耶和华饶恕我。'),
('CUV', '列王纪下', 12, 5, 19, '以利沙对他说：你可以平平安安地回去！乃缦就离开他去了；走了不远，'),
('CUV', '列王纪下', 12, 5, 20, '神人以利沙的仆人基哈西心里说：我主人不愿从这亚兰人乃缦手里受他带来的礼物，我指著永生的耶和华起誓，我必跑去追上他，向他要些。'),
('CUV', '列王纪下', 12, 5, 21, '于是基哈西追赶乃缦。乃缦看见有人追赶，就急忙下车迎著他，说：都平安么？'),
('CUV', '列王纪下', 12, 5, 22, '说：都平安。我主人打发我来说：刚才有两个少年人，是先知门徒，从以法莲山地来见我，请你赐他们一他连得银子，两套衣裳。'),
('CUV', '列王纪下', 12, 5, 23, '乃缦说：请受二他连得；再三地请受，便将二他连得银子装在两个口袋里，又将两套衣裳交给两个仆人；他们就在基哈西前头抬著走。'),
('CUV', '列王纪下', 12, 5, 24, '到了山冈，基哈西从他们手中接过来，放在屋里，打发他们回去。'),
('CUV', '列王纪下', 12, 5, 25, '基哈西进去，站在他主人面前。以利沙问他说：基哈西你从哪里来？回答说：仆人没有往哪里去。'),
('CUV', '列王纪下', 12, 5, 26, '以利沙对他说：那人下车转回迎你的时候，我的心岂没有去呢？这岂是受银子、衣裳、买橄榄园、葡萄园、牛羊、仆婢的时候呢？'),
('CUV', '列王纪下', 12, 5, 27, '因此，乃缦的大痲疯必沾染你和你的后裔，直到永远。基哈西从以利沙面前退出去，就长了大痲疯，像雪那样白。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪下', 12, 6, 1, '先知门徒对以利沙说：看哪，我们同你所住的地方过于窄小，'),
('CUV', '列王纪下', 12, 6, 2, '求你容我们往约但河去，各人从那里取一根木料建造房屋居住。他说：你们去罢！'),
('CUV', '列王纪下', 12, 6, 3, '有一人说：求你与仆人同去。回答说：我可以去。'),
('CUV', '列王纪下', 12, 6, 4, '于是以利沙与他们同去。到了约但河，就砍伐树木。'),
('CUV', '列王纪下', 12, 6, 5, '有一人砍树的时候，斧头掉在水里，他就呼叫说：哀哉！我主啊，这斧子是借的。'),
('CUV', '列王纪下', 12, 6, 6, '神人问说：掉在哪里了？他将那地方指给以利沙看。以利沙砍了一根木头，抛在水里，斧头就漂上来了。'),
('CUV', '列王纪下', 12, 6, 7, '以利沙说：拿起来罢！那人就伸手拿起来了。'),
('CUV', '列王纪下', 12, 6, 8, '亚兰王与以色列人争战，和他的臣仆商议说：我要在某处某处安营。'),
('CUV', '列王纪下', 12, 6, 9, '神人打发人去见以色列王，说：你要谨慎，不要从某处经过，因为亚兰人从那里下来了。'),
('CUV', '列王纪下', 12, 6, 10, '以色列王差人去窥探神人所告诉所警戒他去的地方，就防备未受其害，不止一两次。'),
('CUV', '列王纪下', 12, 6, 11, '亚兰王因这事心里惊疑，召了臣仆来，对他们说：我们这里有谁帮助以色列王，你们不指给我么？'),
('CUV', '列王纪下', 12, 6, 12, '有一个臣仆说：我主，我王！无人帮助他，只有以色列中的先知以利沙，将王在卧房所说的话告诉以色列王了。'),
('CUV', '列王纪下', 12, 6, 13, '王说：你们去探他在哪里，我好打发人去捉拿他。有人告诉王说：他在多坍。'),
('CUV', '列王纪下', 12, 6, 14, '王就打发车马和大军往那里去，夜间到了，围困那城。'),
('CUV', '列王纪下', 12, 6, 15, '神人的仆人清早起来出去，看见车马军兵围困了城。仆人对神人说：哀哉！我主啊，我们怎样行才好呢？'),
('CUV', '列王纪下', 12, 6, 16, '神人说：不要惧怕！与我们同在的比与他们同在的更多。'),
('CUV', '列王纪下', 12, 6, 17, '以利沙祷告说：耶和华啊，求你开这少年人的眼目，使他能看见。耶和华开他的眼目，他就看见满山有火车火马围绕以利沙。'),
('CUV', '列王纪下', 12, 6, 18, '敌人下到以利沙那里，以利沙祷告耶和华说：求你使这些人的眼目昏迷。耶和华就照以利沙的话，使他们的眼目昏迷。'),
('CUV', '列王纪下', 12, 6, 19, '以利沙对他们说：这不是那道，也不是那城；你们跟我去，我必领你们到所寻找的人那里。于是领他们到了撒玛利亚。'),
('CUV', '列王纪下', 12, 6, 20, '他们进了撒玛利亚，以利沙祷告说：耶和华啊，求你开这些人的眼目，使他们能看见。耶和华开他们的眼目，他们就看见了，不料，是在撒玛利亚的城中。'),
('CUV', '列王纪下', 12, 6, 21, '以色列王见了他们，就问以利沙说：我父啊，我可以击杀他们么？'),
('CUV', '列王纪下', 12, 6, 22, '回答说：不可击杀他们！就是你用刀用弓掳来的，岂可击杀他们么(或作也不可击杀，何况这些人呢)？当在他们面前设摆饮食，使他们吃喝回到他们的主人那里。'),
('CUV', '列王纪下', 12, 6, 23, '王就为他们预备了许多食物；他们吃喝完了，打发他们回到他们主人那里。从此，亚兰军不再犯以色列境了。'),
('CUV', '列王纪下', 12, 6, 24, '此后，亚兰王便哈达聚集他的全军，上来围困撒玛利亚。'),
('CUV', '列王纪下', 12, 6, 25, '于是撒玛利亚被围困，有饥荒，甚至一个驴头值银八十舍客勒，二升鸽子粪值银五舍客勒。'),
('CUV', '列王纪下', 12, 6, 26, '一日，以色列王在城上经过，有一个妇人向他呼叫说：我主，我王啊！求你帮助。'),
('CUV', '列王纪下', 12, 6, 27, '王说：耶和华不帮助你，我从何处帮助你？是从禾场，是从酒醡呢？'),
('CUV', '列王纪下', 12, 6, 28, '王问妇人说：你有甚么苦处？他回答说：这妇人对我说：将你的儿子取来，我们今日可以吃，明日可以吃我的儿子。'),
('CUV', '列王纪下', 12, 6, 29, '我们就煮了我的儿子吃了。次日我对他说：要将你的儿子取来，我们可以吃。他却将他的儿子藏起来了。'),
('CUV', '列王纪下', 12, 6, 30, '王听见妇人的话，就撕裂衣服；（王在城上经过）百姓看见王贴身穿著麻衣。'),
('CUV', '列王纪下', 12, 6, 31, '王说：我今日若容沙法的儿子以利沙的头仍在他项上，愿神重重地降罚与我！'),
('CUV', '列王纪下', 12, 6, 32, '那时，以利沙正坐在家中，长老也与他同坐。王打发一个伺候他的人去；他还没有到，以利沙对长老说：你们看这凶手之子，打发人来斩我的头；你们看著使者来到，就关上门，用门将他推出去。在他后头不是有他主人脚步的响声么？'),
('CUV', '列王纪下', 12, 6, 33, '正说话的时候，使者来到，王也到了，说：这灾祸是从耶和华那里来的，我何必再仰望耶和华呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪下', 12, 7, 1, '以利沙说：你们要听耶和华的话，耶和华如此说：明日约到这时候，在撒玛利亚城门口，一细亚细面要卖银一舍客勒，二细亚大麦也要卖银一舍客勒。'),
('CUV', '列王纪下', 12, 7, 2, '有一个搀扶王的军长对神人说：即便耶和华使天开了窗户，也不能有这事。以利沙说：你必亲眼看见，却不得吃。'),
('CUV', '列王纪下', 12, 7, 3, '在城门那里有四个长大痲疯的人，他们彼此说：我们为何坐在这里等死呢？'),
('CUV', '列王纪下', 12, 7, 4, '我们若说，进城去罢！城里有饥荒，必死在那里；若在这里坐著不动，也必是死。来罢，我们去投降亚兰人的军队，他们若留我们的活命，就活著；若杀我们，就死了罢！'),
('CUV', '列王纪下', 12, 7, 5, '黄昏的时候，他们起来往亚兰人的营盘去；到了*营边，不见一人在那里。'),
('CUV', '列王纪下', 12, 7, 6, '因为主使亚兰人的军队听见车马的声音，是大军的声音；他们就彼此说：这必是以色列王贿买赫人的诸王和埃及人的诸王来攻击我们。'),
('CUV', '列王纪下', 12, 7, 7, '所以，在黄昏的时候他们起来逃跑，撇下帐棚、马、驴，营盘照旧，只顾逃命。'),
('CUV', '列王纪下', 12, 7, 8, '那些长大痲疯的到了营边，进了帐棚，吃了喝了，且从其中拿出金银和衣服来，去收藏了；回来又进了一座帐棚，从其中拿出财物来去收藏了。'),
('CUV', '列王纪下', 12, 7, 9, '那时，他们彼此说：我们所做的不好！今日是有好信息的日子，我们竟不作声！若等到天亮，罪必临到我们。来罢，我们与王家报信去！'),
('CUV', '列王纪下', 12, 7, 10, '他们就去叫守城门的，告诉他们说：我们到了亚兰人的营，不见一人在那里，也无人声，只有拴著的马和驴，帐棚都照旧。'),
('CUV', '列王纪下', 12, 7, 11, '守城门的叫了众守门的人来，他们就进去与王家报信。'),
('CUV', '列王纪下', 12, 7, 12, '王夜间起来，对臣仆说：我告诉你们亚兰人向我们如何行。他们知道我们饥饿，所以离营，埋伏在田野，说：以色列人出城的时候，我们就活捉他们，得以进城。'),
('CUV', '列王纪下', 12, 7, 13, '有一个臣仆对王说：我们不如用城里剩下之马中的五匹马（马和城里剩下的以色列人都是一样，快要灭绝），打发人去窥探。'),
('CUV', '列王纪下', 12, 7, 14, '于是取了两辆车和马，王差人去追寻亚兰军，说：你们去窥探窥探。'),
('CUV', '列王纪下', 12, 7, 15, '他们就追寻到约但河，看见满道上都是亚兰人急跑时丢弃的衣服器具，使者就回来报告王。'),
('CUV', '列王纪下', 12, 7, 16, '众人就出去，掳掠亚兰人的营盘。于是一细亚细面卖银一舍客勒，二细亚大麦也卖银一舍客勒，正如耶和华所说的。'),
('CUV', '列王纪下', 12, 7, 17, '王派搀扶他的那军长在城门口弹压，众人在那里将他践踏，他就死了，正如神人在王下来见他的时候所说的。'),
('CUV', '列王纪下', 12, 7, 18, '神人曾对王说：明日约到这时候，在撒玛利亚城门口，二细亚大麦要卖银一舍客勒，一细亚细面也要卖银一舍客勒。'),
('CUV', '列王纪下', 12, 7, 19, '那军长对神人说：即便耶和华使天开了窗户，也不能有这事。神人说：你必亲眼看见，却不得吃。'),
('CUV', '列王纪下', 12, 7, 20, '这话果然应验在他身上；因为众人在城门口将他践踏，他就死了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪下', 12, 8, 1, '以利沙曾对所救活之子的那妇人说：你和你的全家要起身往你可住的地方去住，因为耶和华命饥荒降在这地七年。'),
('CUV', '列王纪下', 12, 8, 2, '妇人就起身，照神人的话带著全家往非利士地去，住了七年。'),
('CUV', '列王纪下', 12, 8, 3, '七年完了，那妇人从非利士地回来，就出去为自己的房屋田地哀告王。'),
('CUV', '列王纪下', 12, 8, 4, '那时王正与神人的仆人基哈西说：请你将以利沙所行的一切大事告诉我。'),
('CUV', '列王纪下', 12, 8, 5, '基哈西告诉王以利沙如何使死人复活，恰巧以利沙所救活、他儿子的那妇人为自己的房屋田地来哀告王。基哈西说：我主我王，这就是那妇人，这是他的儿子，就是以利沙所救活的。'),
('CUV', '列王纪下', 12, 8, 6, '王问那妇人，他就把那事告诉王。于是王为他派一个太监，说：凡属这妇人的都还给他，自从他离开本地直到今日，他田地的出产也都还给他。'),
('CUV', '列王纪下', 12, 8, 7, '以利沙来到大马色，亚兰王便哈达正患病。有人告诉王说：神人来到这里了。'),
('CUV', '列王纪下', 12, 8, 8, '王就吩咐哈薛说：你带著礼物去见神人，托他求问耶和华，我这病能好不能好？'),
('CUV', '列王纪下', 12, 8, 9, '于是哈薛用四十个骆驼，驮著大马色的各样美物为礼物，去见以利沙。到了他那里，站在他面前，说：你儿子亚兰王便哈达打发我来见你，他问说：我这病能好不能好？'),
('CUV', '列王纪下', 12, 8, 10, '以利沙对哈薛说：你回去告诉他说，这病必能好；但耶和华指示我，他必要死。'),
('CUV', '列王纪下', 12, 8, 11, '神人定睛看著哈薛，甚至他惭愧。神人就哭了；'),
('CUV', '列王纪下', 12, 8, 12, '哈薛说：我主为甚么哭？回答说：因为我知道你必苦害以色列人，用火焚烧他们的保障，用刀杀死他们的壮丁，摔死他们的婴孩，剖开他们的孕妇。'),
('CUV', '列王纪下', 12, 8, 13, '哈薛说：你仆人算甚么，不过是一条狗，焉能行这大事呢？以利沙回答说：耶和华指示我，你必作亚兰王。'),
('CUV', '列王纪下', 12, 8, 14, '哈薛离开以利沙，回去见他的主人。主人问他说：以利沙对你说甚么？回答说：他告诉我你必能好。'),
('CUV', '列王纪下', 12, 8, 15, '次日，哈薛拿被窝浸在水中，蒙住王的脸，王就死了。于是哈薛篡了他的位。'),
('CUV', '列王纪下', 12, 8, 16, '以色列王亚哈的儿子约兰第五年，犹大王约沙法还在位的时候，约沙法的儿子约兰登基作了犹大王。'),
('CUV', '列王纪下', 12, 8, 17, '约兰登基的时候年三十二岁，在耶路撒冷作王八年。'),
('CUV', '列王纪下', 12, 8, 18, '他行以色列诸王所行的，与亚哈家一样；因为他娶了亚哈的女儿为妻，行耶和华眼中看为恶的事。'),
('CUV', '列王纪下', 12, 8, 19, '耶和华却因他仆人大卫的缘故，仍不肯灭绝犹大，照他所应许大卫的话，永远赐灯光与他的子孙。'),
('CUV', '列王纪下', 12, 8, 20, '约兰年间，以东人背叛犹大，脱离他的权下，自己立王。'),
('CUV', '列王纪下', 12, 8, 21, '约兰率领所有的战车往撒益去，夜间起来，攻打围困他的以东人和车兵长；犹大兵就逃跑，各回各家去了。'),
('CUV', '列王纪下', 12, 8, 22, '这样，以东人背叛犹大，脱离他的权下，直到今日。那时立拿人也背叛了。'),
('CUV', '列王纪下', 12, 8, 23, '约兰其余的事，凡他所行的，都写在犹大列王记上。'),
('CUV', '列王纪下', 12, 8, 24, '约兰与他列祖同睡，葬在大卫城他列祖的坟地里。他儿子亚哈谢接续他作王。'),
('CUV', '列王纪下', 12, 8, 25, '以色列王亚哈的儿子约兰十二年，犹大王约兰的儿子亚哈谢登基。'),
('CUV', '列王纪下', 12, 8, 26, '他登基的时候年二十二岁，在耶路撒冷作王一年。他母亲名叫亚他利雅，是以色列王暗利的孙女。'),
('CUV', '列王纪下', 12, 8, 27, '亚哈谢效法亚哈家行耶和华眼中看为恶的事，与亚哈家一样，因为他是亚哈家的女婿。'),
('CUV', '列王纪下', 12, 8, 28, '他与亚哈的儿子约兰同往基列的拉末去，与亚兰王哈薛争战。亚兰人打伤了约兰，'),
('CUV', '列王纪下', 12, 8, 29, '约兰王回到耶斯列，医治在拉末与亚兰王哈薛打仗的时候所受的伤。犹大王约兰的儿子亚哈谢因为亚哈的儿子约兰病了，就下到耶斯列看望他。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪下', 12, 9, 1, '先知以利沙叫了一个先知门徒来，吩咐他说：你束上腰，手拿这瓶膏油往基列的拉末去。'),
('CUV', '列王纪下', 12, 9, 2, '到了那里，要寻找宁示的孙子、约沙法的儿子耶户，使他从同僚中起来，带他进严密的屋子，'),
('CUV', '列王纪下', 12, 9, 3, '将瓶里的膏油倒在他头上，说：耶和华如此说：我膏你作以色列王。说完了，就开门逃跑，不要迟延。'),
('CUV', '列王纪下', 12, 9, 4, '于是那少年先知往基列的拉末去了。'),
('CUV', '列王纪下', 12, 9, 5, '到了那里，看见众军长都坐著，就说：将军哪，我有话对你说。耶户说：我们众人里，你要对哪一个说呢？回答说：将军哪，我要对你说。'),
('CUV', '列王纪下', 12, 9, 6, '耶户就起来，进了屋子，少年人将膏油倒在他头上，对他说：耶和华─以色列的神如此说：我膏你作耶和华民以色列的王。'),
('CUV', '列王纪下', 12, 9, 7, '你要击杀你主人亚哈的全家，我好在耶洗别身上伸我仆人众先知和耶和华一切仆人流血的冤。'),
('CUV', '列王纪下', 12, 9, 8, '亚哈全家必都灭亡，凡属亚哈的男丁，无论是困住的、自由的，我必从以色列中剪除，'),
('CUV', '列王纪下', 12, 9, 9, '使亚哈的家像尼八儿子耶罗波安的家，又像亚希雅儿子巴沙的家。'),
('CUV', '列王纪下', 12, 9, 10, '耶洗别必在耶斯列田里被狗所吃，无人葬埋。说完了，少年人就开门逃跑了。'),
('CUV', '列王纪下', 12, 9, 11, '耶户出来，回到他主人的臣仆那里，有一人问他说：平安么？这狂妄的人来见你有甚么事呢？回答说：你们认得那人，也知道他说甚么。'),
('CUV', '列王纪下', 12, 9, 12, '他们说：这是假话，你据实地告诉我们。回答说：他如此如此对我说。他说：耶和华如此说：我膏你作以色列王。'),
('CUV', '列王纪下', 12, 9, 13, '他们就急忙各将自己的衣服铺在上层台阶，使耶户坐在其上；他们吹角，说：耶户作王了！'),
('CUV', '列王纪下', 12, 9, 14, '这样，宁示的孙子、约沙法的儿子耶户背叛约兰。先是约兰和以色列众人因为亚兰王哈薛的缘故，把守基列的拉末；'),
('CUV', '列王纪下', 12, 9, 15, '但约兰王回到耶斯列，医治与亚兰王哈薛打仗所受的伤。耶户说：若合你们的意思，就不容人逃出城往耶斯列报信去。'),
('CUV', '列王纪下', 12, 9, 16, '于是耶户坐车往耶斯列去，因为约兰病卧在那里。犹大王亚哈谢已经下去看望他。'),
('CUV', '列王纪下', 12, 9, 17, '有一个守望的人站在耶斯列的楼上，看见耶户带著一群人来，就说：我看见一群人。约兰说：打发一个骑马的去迎接他们，问说：平安不平安？'),
('CUV', '列王纪下', 12, 9, 18, '骑马的就去迎接耶户，说：王问说，平安不平安？耶户说：平安不平安与你何干？你转在我后头罢！守望的人又说：使者到了他们那里，却不回来。'),
('CUV', '列王纪下', 12, 9, 19, '王又打发一个骑马的去。这人到了他们那里，说：王问说，平安不平安？耶户说：平安不平安与你何干？你转在我后头罢！'),
('CUV', '列王纪下', 12, 9, 20, '守望的人又说：他到了他们那里，也不回来；车赶得甚猛，像宁示的孙子耶户的赶法。'),
('CUV', '列王纪下', 12, 9, 21, '约兰吩咐说：套车！人就给他套车。以色列王约兰和犹大王亚哈谢各坐自己的车出去迎接耶户，在耶斯列人拿伯的田那里遇见他。'),
('CUV', '列王纪下', 12, 9, 22, '约兰见耶户就说：耶户啊，平安么？耶户说：你母亲耶洗别的淫行邪术这样多，焉能平安呢？'),
('CUV', '列王纪下', 12, 9, 23, '约兰就转车逃跑，对亚哈谢说：亚哈谢啊，反了！'),
('CUV', '列王纪下', 12, 9, 24, '耶户开满了弓，射中约兰的脊背，箭从心窝穿出，约兰就仆倒在车上。'),
('CUV', '列王纪下', 12, 9, 25, '耶户对他的军长毕甲说：你把他抛在耶斯列人拿伯的田间。你当追想，你我一同坐车跟随他父亚哈的时候，耶和华对亚哈所说的预言，'),
('CUV', '列王纪下', 12, 9, 26, '说：我昨日看见拿伯的血和他众子的血，我必在这块田上报应你。这是耶和华说的，现在你要照著耶和华的话，把他抛在这田间。'),
('CUV', '列王纪下', 12, 9, 27, '犹大王亚哈谢见这光景，就从园亭之路逃跑。耶户追赶他，说：把这人也杀在车上。到了靠近以伯莲的姑珥坡上击伤了他。他逃到米吉多，就死在那里。'),
('CUV', '列王纪下', 12, 9, 28, '他的臣仆用车将他的尸首送到耶路撒冷，葬在大卫城他自己的坟墓里，与他列祖同葬。'),
('CUV', '列王纪下', 12, 9, 29, '亚哈谢登基作犹大王的时候，是在亚哈的儿子约兰第十一年。'),
('CUV', '列王纪下', 12, 9, 30, '耶户到了耶斯列；耶洗别听见就擦粉、梳头，从窗户里往外观看。'),
('CUV', '列王纪下', 12, 9, 31, '耶户进门的时候，耶洗别说：杀主人的心利啊，平安么？'),
('CUV', '列王纪下', 12, 9, 32, '耶户抬头向窗户观看，说：谁顺从我？有两三个太监从窗户往外看他。'),
('CUV', '列王纪下', 12, 9, 33, '耶户说：把他扔下来！他们就把他扔下来。他的血溅在墙上和马上；于是把他践踏了。'),
('CUV', '列王纪下', 12, 9, 34, '耶户进去，吃了喝了，吩咐说：你们把这被咒诅的妇人葬埋了，因为他是王的女儿。'),
('CUV', '列王纪下', 12, 9, 35, '他们就去葬埋他，只寻得他的头骨和脚，并手掌。'),
('CUV', '列王纪下', 12, 9, 36, '他们回去告诉耶户，耶户说：这正应验耶和华藉他仆人提斯比人以利亚所说的话，说：在耶斯列田间，狗必吃耶洗别的肉；'),
('CUV', '列王纪下', 12, 9, 37, '耶洗别的尸首必在耶斯列田间如同粪土，甚至人不能说这是耶洗别。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪下', 12, 10, 1, '亚哈有七十个儿子在撒玛利亚。耶户写信送到撒玛利亚，通知耶斯列的首领，就是长老和教养亚哈众子的人，说：'),
('CUV', '列王纪下', 12, 10, 2, '你们那里既有你们主人的众子和车马、器械、坚固城，'),
('CUV', '列王纪下', 12, 10, 3, '接了这信，就可以在你们主人的众子中选择一个贤能合宜的，使他坐他父亲的位，你们也可以为你们主人的家争战。'),
('CUV', '列王纪下', 12, 10, 4, '他们却甚惧怕，彼此说：二王在他面前尚且站立不住，我们怎能站得住呢。'),
('CUV', '列王纪下', 12, 10, 5, '家宰、邑宰，和长老，并教养众子的人，打发人去见耶户，说：我们是你的仆人，凡你所吩咐我们的都必遵行，我们不立谁作王，你看怎样好就怎样行。'),
('CUV', '列王纪下', 12, 10, 6, '耶户又给他们写信说：你们若归顺我，听从我的话，明日这时候，要将你们主人众子的首级带到耶斯列来见我。那时王的儿子七十人都住在教养他们那城中的尊贵人家里。'),
('CUV', '列王纪下', 12, 10, 7, '信一到，他们就把王的七十个儿子杀了，将首级装在筐里，送到在耶斯列的耶户那里。'),
('CUV', '列王纪下', 12, 10, 8, '有使者来告诉耶户说：他们将王众子的首级送来了。耶户说：将首级在城门口堆作两堆，搁到明日。'),
('CUV', '列王纪下', 12, 10, 9, '次日早晨，耶户出来，站著对众民说：你们都是公义的，我背叛我主人，将他杀了；这些人却是谁杀的呢？'),
('CUV', '列王纪下', 12, 10, 10, '由此可知，耶和华指著亚哈家所说的话一句没有落空，因为耶和华藉他仆人以利亚所说的话都成就了。'),
('CUV', '列王纪下', 12, 10, 11, '凡亚哈家在耶斯列所剩下的人和他的大臣、密友、祭司，耶户尽都杀了，没有留下一个。'),
('CUV', '列王纪下', 12, 10, 12, '耶户起身往撒玛利亚去。在路上、牧人剪羊毛之处，'),
('CUV', '列王纪下', 12, 10, 13, '遇见犹大王亚哈谢的弟兄，问他们说：你们是谁？回答说：我们是亚哈谢的弟兄，现在下去要问王和太后的众子安。'),
('CUV', '列王纪下', 12, 10, 14, '耶户吩咐说：活捉他们！跟从的人就活捉了他们，将他们杀在剪羊毛之处的坑边，共四十二人，没有留下一个。'),
('CUV', '列王纪下', 12, 10, 15, '耶户从那里前行，恰遇利甲的儿子约拿达来迎接他，耶户问他安，对他说：你诚心待我像我诚心待你么？约拿达回答说：是。耶户说：若是这样，你向我伸手，他就伸手；耶户拉他上车。'),
('CUV', '列王纪下', 12, 10, 16, '耶户说：你和我同去，看我为耶和华怎样热心；于是请他坐在车上，'),
('CUV', '列王纪下', 12, 10, 17, '到了撒玛利亚，就把撒玛利亚的亚哈家剩下的人都杀了，直到灭尽，正如耶和华对以利亚所说的。'),
('CUV', '列王纪下', 12, 10, 18, '耶户招聚众民，对他们说：亚哈事奉巴力还冷淡，耶户却更热心。'),
('CUV', '列王纪下', 12, 10, 19, '现在我要给巴力献大祭。应当叫巴力的众先知和一切拜巴力的人，并巴力的众祭司，都到我这里来，不可缺少一个；凡不来的必不得活。耶户这样行，是用诡计要杀尽拜巴力的人。'),
('CUV', '列王纪下', 12, 10, 20, '耶户说：要为巴力宣告严肃会！于是宣告了。'),
('CUV', '列王纪下', 12, 10, 21, '耶户差人走遍以色列地；凡拜巴力的人都来齐了，没有一个不来的。他们进了巴力庙，巴力庙中从前边直到后边都满了人。'),
('CUV', '列王纪下', 12, 10, 22, '耶户吩咐掌管礼服的人说：拿出礼服来，给一切拜巴力的人穿。他就拿出礼服来给了他们。'),
('CUV', '列王纪下', 12, 10, 23, '耶户和利甲的儿子约拿达进了巴力庙，对拜巴力的人说：你们察看察看，在你们这里不可有耶和华的仆人，只可容留拜巴力的人。'),
('CUV', '列王纪下', 12, 10, 24, '耶户和约拿达进去，献平安祭和燔祭。耶户先安排八十人在庙外，吩咐说：我将这些人交在你们手中，若有一人脱逃，谁放的必叫他偿命！'),
('CUV', '列王纪下', 12, 10, 25, '耶户献完了燔祭，就出来吩咐护卫兵和众军长说：你们进去杀他们，不容一人出来！护卫兵和军长就用刀杀他们，将尸首抛出去，便到巴力庙的城去了，'),
('CUV', '列王纪下', 12, 10, 26, '将巴力庙中的柱像都拿出来烧了；'),
('CUV', '列王纪下', 12, 10, 27, '毁坏了巴力柱像，拆毁了巴力庙作为厕所，直到今日。'),
('CUV', '列王纪下', 12, 10, 28, '这样，耶户在以色列中灭了巴力。'),
('CUV', '列王纪下', 12, 10, 29, '只是耶户不离开尼八的儿子耶罗波安使以色列人陷在罪里的那罪，就是拜伯特利和但的金牛犊。'),
('CUV', '列王纪下', 12, 10, 30, '耶和华对耶户说：因你办好我眼中看为正的事，照我的心意待亚哈家，你的子孙必接续你坐以色列的国位，直到四代。'),
('CUV', '列王纪下', 12, 10, 31, '只是耶户不尽心遵守耶和华─以色列神的律法，不离开耶罗波安使以色列人陷在罪里的那罪。'),
('CUV', '列王纪下', 12, 10, 32, '在那些日子，耶和华才割裂以色列国，使哈薛攻击以色列的境界，'),
('CUV', '列王纪下', 12, 10, 33, '乃是约但河东、基列全地，从靠近亚嫩谷边的亚罗珥起，就是基列和巴珊的迦得人、流便人、玛拿西人之地。'),
('CUV', '列王纪下', 12, 10, 34, '耶户其余的事，凡他所行的和他的勇力都写在以色列诸王记上。'),
('CUV', '列王纪下', 12, 10, 35, '耶户与他列祖同睡，葬在撒玛利亚；他儿子约哈斯接续他作王。'),
('CUV', '列王纪下', 12, 10, 36, '耶户在撒玛利亚作以色列王二十八年。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪下', 12, 11, 1, '亚哈谢的母亲亚他利雅见他儿子死了，就起来剿灭王室。'),
('CUV', '列王纪下', 12, 11, 2, '但约兰王的女儿，亚哈谢的妹子约示巴，将亚哈谢的儿子约阿施从那被杀的王子中偷出来，把他和他的乳母都藏在卧房里，躲避亚他利雅，免得被杀。'),
('CUV', '列王纪下', 12, 11, 3, '约阿施和他的乳母藏在耶和华的殿里六年；亚他利雅篡了国位。'),
('CUV', '列王纪下', 12, 11, 4, '第七年，耶何耶大打发人叫迦利人(或作亲兵)和护卫兵的众百夫长来，领他们进了耶和华的殿，与他们立约，使他们在耶和华殿里起誓，又将王的儿子指给他们看，'),
('CUV', '列王纪下', 12, 11, 5, '吩咐他们说：你们当这样行：凡安息日进班的三分之一要看守王宫，'),
('CUV', '列王纪下', 12, 11, 6, '三分之一要在苏珥门，三分之一要在护卫兵院的后门。这样把守王宫，拦阻闲人。'),
('CUV', '列王纪下', 12, 11, 7, '你们安息日所有出班的三分之二要在耶和华的殿里护卫王；'),
('CUV', '列王纪下', 12, 11, 8, '各人手拿兵器，四围护卫王。凡擅入你们班次的必当治死，王出入的时候，你们当跟随他。'),
('CUV', '列王纪下', 12, 11, 9, '众百夫长就照著祭司耶何耶大一切所吩咐的去行，各带所管安息日进班出班的人来见祭司耶何耶大。'),
('CUV', '列王纪下', 12, 11, 10, '祭司便将耶和华殿里所藏大卫王的枪和盾牌交给百夫长。'),
('CUV', '列王纪下', 12, 11, 11, '护卫兵手中各拿兵器，在坛和殿那里，从殿右直到殿左，站在王子的四围。'),
('CUV', '列王纪下', 12, 11, 12, '祭司领王子出来，给他戴上冠冕，将律法书交给他，膏他作王；众人就拍掌说：愿王万岁！'),
('CUV', '列王纪下', 12, 11, 13, '亚他利雅听见护卫兵和民的声音，就到民那里，进耶和华的殿，'),
('CUV', '列王纪下', 12, 11, 14, '看见王照例站在柱旁，百夫长和吹号的人侍立在王左右，国中的众民欢乐吹号；亚他利雅就撕裂衣服，喊叫说：反了！反了！'),
('CUV', '列王纪下', 12, 11, 15, '祭司耶何耶大吩咐管辖军兵的百夫长说：将他赶出班外，凡跟随他的必用刀杀死！因为祭司说不可在耶和华殿里杀他，'),
('CUV', '列王纪下', 12, 11, 16, '众兵就闪开让他去；他从马路上王宫去，便在那里被杀。'),
('CUV', '列王纪下', 12, 11, 17, '耶何耶大使王和民与耶和华立约，作耶和华的民；又使王与民立约。'),
('CUV', '列王纪下', 12, 11, 18, '于是国民都到巴力庙，拆毁了庙，打碎坛和像，又在坛前将巴力的祭司玛坦杀了。祭司耶何耶大派官看守耶和华的殿，'),
('CUV', '列王纪下', 12, 11, 19, '又率领百夫长和迦利人(或作亲兵)与护卫兵，以及国中的众民，请王从耶和华殿下来，由护卫兵的门进入王宫，他就坐了王位。'),
('CUV', '列王纪下', 12, 11, 20, '国民都欢乐，合城都安静。众人已将亚他利雅在王宫那里用刀杀了。'),
('CUV', '列王纪下', 12, 11, 21, '约阿施登基的时候年方七岁。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪下', 12, 12, 1, '耶户第七年，约阿施登基，在耶路撒冷作王四十年。他母亲名叫西比亚，是别是巴人。'),
('CUV', '列王纪下', 12, 12, 2, '约阿施在祭司耶何耶大教训他的时候，就行耶和华眼中看为正的事；'),
('CUV', '列王纪下', 12, 12, 3, '只是邱坛还没有废去，百姓仍在那里献祭烧香。'),
('CUV', '列王纪下', 12, 12, 4, '约阿施对众祭司说：凡奉到耶和华殿分别为圣之物所值通用的银子，或各人当纳的身价，或乐意奉到耶和华殿的银子，'),
('CUV', '列王纪下', 12, 12, 5, '你们当从所认识的人收了来，修理殿的一切破坏之处。'),
('CUV', '列王纪下', 12, 12, 6, '无奈到了约阿施王二十三年，祭司仍未修理殿的破坏之处。'),
('CUV', '列王纪下', 12, 12, 7, '所以约阿施王召了大祭司耶何耶大和众祭司来，对他们说：你们怎么不修理殿的破坏之处呢？从今以后，你们不要从所认识的人再收银子，要将所收的交出来，修理殿的破坏之处。'),
('CUV', '列王纪下', 12, 12, 8, '众祭司答应不再收百姓的银子，也不修理殿的破坏之处。'),
('CUV', '列王纪下', 12, 12, 9, '祭司耶何耶大取了一个柜子，在柜盖上钻了一个窟窿，放于坛旁，在进耶和华殿的右边；守门的祭司将奉到耶和华殿的一切银子投在柜里。'),
('CUV', '列王纪下', 12, 12, 10, '他们见柜里的银子多了，便叫王的书记和大祭司上来，将耶和华殿里的银子数算包起来。'),
('CUV', '列王纪下', 12, 12, 11, '把所平的银子交给督工的，就是耶和华殿里办事的人；他们把银子转交修理耶和华殿的木匠和工人，'),
('CUV', '列王纪下', 12, 12, 12, '并瓦匠、石匠，又买木料和凿成的石头，修理耶和华殿的破坏之处，以及修理殿的各样使用。'),
('CUV', '列王纪下', 12, 12, 13, '但那奉到耶和华殿的银子，没有用以做耶和华殿里的银杯、蜡剪、碗、号，和别样的金银器皿，'),
('CUV', '列王纪下', 12, 12, 14, '乃将那银子交给督工的人修理耶和华的殿；'),
('CUV', '列王纪下', 12, 12, 15, '且将银子交给办事的人转交做工的人，不与他们算账，因为他们办事诚实。'),
('CUV', '列王纪下', 12, 12, 16, '惟有赎愆祭、赎罪祭的银子没有奉到耶和华的殿，都归祭司。'),
('CUV', '列王纪下', 12, 12, 17, '那时，亚兰王哈薛上来攻打迦特，攻取了，就定意上来攻打耶路撒冷。'),
('CUV', '列王纪下', 12, 12, 18, '犹大王约阿施将他列祖犹大王约沙法、约兰、亚哈谢所分别为圣的物和自己所分别为圣的物，并耶和华殿与王宫府库里所有的金子都送给亚兰王哈薛；哈薛就不上耶路撒冷来了。'),
('CUV', '列王纪下', 12, 12, 19, '约阿施其余的事，凡他所行的都写在犹大列王记上。'),
('CUV', '列王纪下', 12, 12, 20, '约阿施的臣仆起来背叛，在下悉拉的米罗宫那里将他杀了。'),
('CUV', '列王纪下', 12, 12, 21, '杀他的那臣仆就是示米押的儿子约撒甲和朔默的儿子约萨拔。众人将他葬在大卫城他列祖的坟地里。他儿子亚玛谢接续他作王。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪下', 12, 13, 1, '犹大王亚哈谢的儿子约阿施二十三年，耶户的儿子约哈斯在撒玛利亚登基作以色列王十七年。'),
('CUV', '列王纪下', 12, 13, 2, '约哈斯行耶和华眼中看为恶的事，效法尼八的儿子耶罗波安使以色列人陷在罪里的那罪，总不离开。'),
('CUV', '列王纪下', 12, 13, 3, '于是，耶和华的怒气向以色列人发作，将他们屡次交在亚兰王哈薛和他儿子便哈达的手里。'),
('CUV', '列王纪下', 12, 13, 4, '约哈斯恳求耶和华，耶和华就应允他，因为见以色列人所受亚兰王的欺压。'),
('CUV', '列王纪下', 12, 13, 5, '耶和华赐给以色列人一位拯救者，使他们脱离亚兰人的手；于是以色列人仍旧安居在家里。'),
('CUV', '列王纪下', 12, 13, 6, '然而他们不离开耶罗波安家使以色列人陷在罪里的那罪，仍然去行，并且在撒玛利亚留下亚舍拉。'),
('CUV', '列王纪下', 12, 13, 7, '亚兰王灭绝约哈斯的民，践踏他们如禾场上的尘沙，只给约哈斯留下五十马兵，十辆战车，一万步兵。'),
('CUV', '列王纪下', 12, 13, 8, '约哈斯其余的事，凡他所行的和他的勇力都写在以色列诸王记上。'),
('CUV', '列王纪下', 12, 13, 9, '约哈斯与他列祖同睡，葬在撒玛利亚。他儿子约阿施接续他作王。'),
('CUV', '列王纪下', 12, 13, 10, '犹大王约阿施三十七年，约哈斯的儿子约阿施在撒玛利亚登基作以色列王十六年。'),
('CUV', '列王纪下', 12, 13, 11, '他行耶和华眼中看为恶的事，不离开尼八的儿子耶罗波安使以色列人陷在罪里的一切罪，仍然去行。'),
('CUV', '列王纪下', 12, 13, 12, '约阿施其余的事，凡他所行的和他与犹大王亚玛谢争战的勇力，都写在以色列诸王记上。'),
('CUV', '列王纪下', 12, 13, 13, '约阿施与他列祖同睡，耶罗波安坐了他的位。约阿施与以色列诸王一同葬在撒玛利亚。'),
('CUV', '列王纪下', 12, 13, 14, '以利沙得了必死的病，以色列王约阿施下来看他，伏在他脸上哭泣，说：我父啊！我父啊！以色列的战车马兵啊！'),
('CUV', '列王纪下', 12, 13, 15, '以利沙对他说：你取弓箭来。王就取了弓箭来；'),
('CUV', '列王纪下', 12, 13, 16, '又对以色列王说：你用手拿弓。王就用手拿弓。以利沙按手在王的手上，'),
('CUV', '列王纪下', 12, 13, 17, '说：你开朝东的窗户。他就开了。以利沙说：射箭罢！他就射箭。以利沙说：这是耶和华的得胜箭，就是战胜亚兰人的箭；因为你必在亚弗攻打亚兰人，直到灭尽他们。'),
('CUV', '列王纪下', 12, 13, 18, '以利沙又说：取几枝箭来。他就取了来。以利沙说：打地罢！他打了三次，便止住了。'),
('CUV', '列王纪下', 12, 13, 19, '神人向他发怒，说：应当击打五六次，就能攻打亚兰人直到灭尽；现在只能打败亚兰人三次。'),
('CUV', '列王纪下', 12, 13, 20, '以利沙死了，人将他葬埋。到了新年，有一群摩押人犯境，'),
('CUV', '列王纪下', 12, 13, 21, '有人正葬死人，忽然看见一群人，就把死人抛在以利沙的坟墓里，一碰著以利沙的骸骨，死人就复活，站起来了。'),
('CUV', '列王纪下', 12, 13, 22, '约哈斯年间，亚兰王哈薛屡次欺压以色列人。'),
('CUV', '列王纪下', 12, 13, 23, '耶和华却因与亚伯拉罕、以撒、雅各所立的约，仍施恩给以色列人，怜恤他们，眷顾他们，不肯灭尽他们，尚未赶逐他们离开自己面前。'),
('CUV', '列王纪下', 12, 13, 24, '亚兰王哈薛死了，他儿子便哈达接续他作王。'),
('CUV', '列王纪下', 12, 13, 25, '从前哈薛和约阿施的父亲约哈斯争战，攻取了些城邑，现在约哈斯的儿子约阿施三次打败哈薛的儿子便哈达，就收回了以色列的城邑。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪下', 12, 14, 1, '以色列王约哈斯的儿子约阿施第二年，犹大王约阿施的儿子亚玛谢登基。'),
('CUV', '列王纪下', 12, 14, 2, '他登基的时候年二十五岁，在耶路撒冷作王二十九年。他母亲名叫约耶但，是耶路撒冷人。'),
('CUV', '列王纪下', 12, 14, 3, '亚玛谢行耶和华眼中看为正的事，但不如他祖大卫，乃效法他父约阿施一切所行的；'),
('CUV', '列王纪下', 12, 14, 4, '只是邱坛还没有废去，百姓仍在那里献祭烧香。'),
('CUV', '列王纪下', 12, 14, 5, '国一坚定，就把杀他父王的臣仆杀了，'),
('CUV', '列王纪下', 12, 14, 6, '却没有治死杀王之人的儿子，是照摩西律法书上耶和华所吩咐的说：不可因子杀父，也不可因父杀子，各人要为本身的罪而死。'),
('CUV', '列王纪下', 12, 14, 7, '亚玛谢在盐谷杀了以东人一万，又攻取了西拉，改名叫约帖，直到今日。'),
('CUV', '列王纪下', 12, 14, 8, '那时，亚玛谢差遣使者去见耶户的孙子约哈斯的儿子以色列王约阿施，说：你来，我们二人相见于战场。'),
('CUV', '列王纪下', 12, 14, 9, '以色列王约阿施差遣使者去见犹大王亚玛谢，说：利巴嫩的蒺藜差遣使者去见利巴嫩的香柏树，说：将你的女儿给我儿子为妻。后来利巴嫩有一个野兽经过，把蒺藜践踏了。'),
('CUV', '列王纪下', 12, 14, 10, '你打败了以东人就心高气傲，你以此为荣耀，在家里安居就罢了，为何要惹祸，使自己和犹大国一同败亡呢？'),
('CUV', '列王纪下', 12, 14, 11, '亚玛谢却不肯听这话。于是以色列王约阿施上来，在犹大的伯示麦与犹大王亚玛谢相见于战场。'),
('CUV', '列王纪下', 12, 14, 12, '犹大人败在以色列人面前，各自逃回家里去了。'),
('CUV', '列王纪下', 12, 14, 13, '以色列王约阿施在伯示麦擒住亚哈谢的孙子、约阿施的儿子犹大王亚玛谢，就来到耶路撒冷，拆毁耶路撒冷的城墙，从以法莲门直到角门共四百肘，'),
('CUV', '列王纪下', 12, 14, 14, '又将耶和华殿里与王宫府库里所有的金银和器皿都拿了去，并带人去为质，就回撒玛利亚去了。'),
('CUV', '列王纪下', 12, 14, 15, '约阿施其余所行的事和他的勇力，并与犹大王亚玛谢争战的事，都写在以色列诸王记上。'),
('CUV', '列王纪下', 12, 14, 16, '约阿施与他列祖同睡，葬在撒玛利亚，以色列诸王的坟地里。他儿子耶罗波安接续他作王。'),
('CUV', '列王纪下', 12, 14, 17, '以色列王约哈斯的儿子约阿施死后，犹大王约阿施的儿子亚玛谢又活了十五年。'),
('CUV', '列王纪下', 12, 14, 18, '亚玛谢其余的事都写在犹大列王记上。'),
('CUV', '列王纪下', 12, 14, 19, '耶路撒冷有人背叛亚玛谢，他就逃到拉吉；叛党却打发人到拉吉将他杀了。'),
('CUV', '列王纪下', 12, 14, 20, '人就用马将他的尸首驮到耶路撒冷，葬在大卫城他列祖的坟地里。'),
('CUV', '列王纪下', 12, 14, 21, '犹大众民立亚玛谢的儿子亚撒利雅(又名乌西雅)接续他父作王，那时他年十六岁。'),
('CUV', '列王纪下', 12, 14, 22, '亚玛谢与他列祖同睡之后，亚撒利雅收回以拉他仍归犹大，又重新修理。'),
('CUV', '列王纪下', 12, 14, 23, '犹大王约阿施的儿子亚玛谢十五年，以色列王约阿施的儿子耶罗波安在撒玛利亚登基，作王四十一年。'),
('CUV', '列王纪下', 12, 14, 24, '他行耶和华眼中看为恶的事，不离开尼八的儿子耶罗波安使以色列人陷在罪里的一切罪。'),
('CUV', '列王纪下', 12, 14, 25, '他收回以色列边界之地，从哈马口直到亚拉巴海，正如耶和华─以色列的神藉他仆人迦特希弗人亚米太的儿子先知约拿所说的。'),
('CUV', '列王纪下', 12, 14, 26, '因为耶和华看见以色列人甚是艰苦，无论困住的、自由的都没有了，也无人帮助以色列人。'),
('CUV', '列王纪下', 12, 14, 27, '耶和华并没有说要将以色列的名从天下涂抹，乃藉约阿施的儿子耶罗波安拯救他们。'),
('CUV', '列王纪下', 12, 14, 28, '耶罗波安其余的事，凡他所行的和他的勇力，他怎样争战，怎样收回大马色和先前属犹大的哈马归以色列，都写在以色列诸王记上。'),
('CUV', '列王纪下', 12, 14, 29, '耶罗波安与他列祖以色列诸王同睡。他儿子撒迦利雅接续他作王。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪下', 12, 15, 1, '以色列王耶罗波安二十七年，犹大王亚玛谢的儿子亚撒利雅登基，'),
('CUV', '列王纪下', 12, 15, 2, '他登基的时候年十六岁，在耶路撒冷作王五十二年。他母亲名叫耶可利雅，是耶路撒冷人。'),
('CUV', '列王纪下', 12, 15, 3, '亚撒利雅行耶和华眼中看为正的事，效法他父亲亚玛谢一切所行的；'),
('CUV', '列王纪下', 12, 15, 4, '只是邱坛还没有废去，百姓仍在那里献祭烧香。'),
('CUV', '列王纪下', 12, 15, 5, '耶和华降灾与王，使他长大痲疯，直到死日，他就住在别的宫里。他的儿子约坦管理家事，治理国民。'),
('CUV', '列王纪下', 12, 15, 6, '亚撒利雅其余的事，凡他所行的都写在犹大列王记上。'),
('CUV', '列王纪下', 12, 15, 7, '亚撒利雅与他列祖同睡，葬在大卫城他列祖的坟地里。他儿子约坦接续他作王。'),
('CUV', '列王纪下', 12, 15, 8, '犹大王亚撒利雅三十八年，耶罗波安的儿子撒迦利雅在撒玛利亚作以色列王六个月。'),
('CUV', '列王纪下', 12, 15, 9, '他行耶和华眼中看为恶的事，效法他列祖所行的，不离开尼八的儿子耶罗波安使以色列人陷在罪里的那罪。'),
('CUV', '列王纪下', 12, 15, 10, '雅比的儿子沙龙背叛他，在百姓面前击杀他，篡了他的位。'),
('CUV', '列王纪下', 12, 15, 11, '撒迦利雅其余的事都写在以色列诸王记上。'),
('CUV', '列王纪下', 12, 15, 12, '这是从前耶和华应许耶户说：你的子孙必坐以色列的国位直到四代。这话果然应验了。'),
('CUV', '列王纪下', 12, 15, 13, '犹大王乌西雅(就是亚撒利雅)三十九年，雅比的儿子沙龙登基在撒玛利亚作王一个月。'),
('CUV', '列王纪下', 12, 15, 14, '迦底的儿子米拿现从得撒上撒玛利亚，杀了雅比的儿子沙龙，篡了他的位。'),
('CUV', '列王纪下', 12, 15, 15, '沙龙其余的事和他背叛的情形都写在以色列诸王记上。'),
('CUV', '列王纪下', 12, 15, 16, '那时米拿现从得撒起攻打提斐萨和其四境，击杀城中一切的人，剖开其中所有的孕妇，都因他们没有给他开城。'),
('CUV', '列王纪下', 12, 15, 17, '犹大王亚撒利雅三十九年，迦底的儿子米拿现登基，在撒玛利亚作以色列王十年。'),
('CUV', '列王纪下', 12, 15, 18, '他行耶和华眼中看为恶的事，终身不离开尼八的儿子耶罗波安使以色列人陷在罪里的那罪。'),
('CUV', '列王纪下', 12, 15, 19, '亚述王普勒来攻击以色列国，米拿现给他一千他连得银子，请普勒帮助他坚定国位。'),
('CUV', '列王纪下', 12, 15, 20, '米拿现向以色列一切大富户索要银子，使他们各出五十舍客勒，就给了亚述王。于是亚述王回去，不在国中停留。'),
('CUV', '列王纪下', 12, 15, 21, '米拿现其余的事，凡他所行的都写在以色列诸王记上。'),
('CUV', '列王纪下', 12, 15, 22, '米拿现与他列祖同睡。他儿子比加辖接续他作王。'),
('CUV', '列王纪下', 12, 15, 23, '犹大王亚撒利雅五十年，米拿现的儿子比加辖在撒玛利亚登基作以色列王二年。'),
('CUV', '列王纪下', 12, 15, 24, '他行耶和华眼中看为恶的事，不离开尼八的儿子耶罗波安使以色列人陷在罪里的那罪。'),
('CUV', '列王纪下', 12, 15, 25, '比加辖的将军、利玛利的儿子比加背叛他，在撒玛利亚王宫里的卫所杀了他。亚珥歌伯和亚利耶并基列的五十人帮助比加；比加击杀他，篡了他的位。'),
('CUV', '列王纪下', 12, 15, 26, '比加辖其余的事，凡他所行的都写在以色列诸王记上。'),
('CUV', '列王纪下', 12, 15, 27, '犹大王亚撒利雅五十二年，利玛利的儿子比加在撒玛利亚登基作以色列王二十年。'),
('CUV', '列王纪下', 12, 15, 28, '他行耶和华眼中看为恶的事，不离开尼八的儿子耶罗波安使以色列人陷在罪里的那罪。'),
('CUV', '列王纪下', 12, 15, 29, '以色列王比加年间，亚述王提革拉毗列色来夺了以云、亚伯伯玛迦、亚挪、基低斯、夏琐、基列、加利利，和拿弗他利全地，将这些地方的居民都掳到亚述去了。'),
('CUV', '列王纪下', 12, 15, 30, '乌西雅的儿子约坦二十年，以拉的儿子何细亚背叛利玛利的儿子比加，击杀他，篡了他的位。'),
('CUV', '列王纪下', 12, 15, 31, '比加其余的事，凡他所行的都写在以色列诸王记上。'),
('CUV', '列王纪下', 12, 15, 32, '以色列王利玛利的儿子比加第二年，犹大王乌西雅的儿子约坦登基。'),
('CUV', '列王纪下', 12, 15, 33, '他登基的时候年二十五岁，在耶路撒冷作王十六年。他母亲名叫耶路沙，是撒督的女儿。'),
('CUV', '列王纪下', 12, 15, 34, '约坦行耶和华眼中看为正的事，效法他父亲乌西雅一切所行的；'),
('CUV', '列王纪下', 12, 15, 35, '只是邱坛还没有废去，百姓仍在那里献祭烧香。约坦建立耶和华殿的上门。'),
('CUV', '列王纪下', 12, 15, 36, '约坦其余的事，凡他所行的都写在犹大列王记上。'),
('CUV', '列王纪下', 12, 15, 37, '在那些日子，耶和华才使亚兰王利汛和利玛利的儿子比加去攻击犹大。'),
('CUV', '列王纪下', 12, 15, 38, '约坦与他列祖同睡，葬在他祖大卫城他列祖的坟地里。他儿子亚哈斯接续他作王。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪下', 12, 16, 1, '利玛利的儿子比加十七年，犹大王约坦的儿子亚哈斯登基。'),
('CUV', '列王纪下', 12, 16, 2, '他登基的时候年二十岁，在耶路撒冷作王十六年；不像他祖大卫行耶和华─他神眼中看为正的事，'),
('CUV', '列王纪下', 12, 16, 3, '却效法以色列诸王所行的，又照著耶和华从以色列人面前赶出的外邦人所行可憎的事，使他的儿子经火，'),
('CUV', '列王纪下', 12, 16, 4, '并在邱坛上、山冈上、各青翠树下献祭烧香。'),
('CUV', '列王纪下', 12, 16, 5, '亚兰王利汛和以色列王利玛利的儿子比加上来攻打耶路撒冷，围困亚哈斯，却不能胜他。'),
('CUV', '列王纪下', 12, 16, 6, '当时亚兰王利汛收回以拉他归与亚兰，将犹大人从以拉他赶出去。亚兰人(有作以东人的)就来到以拉他，住在那里，直到今日。'),
('CUV', '列王纪下', 12, 16, 7, '亚哈斯差遣使者去见亚述王提革拉毗列色，说：我是你的仆人、你的儿子。现在亚兰王和以色列王攻击我，求你来救我脱离他们的手。'),
('CUV', '列王纪下', 12, 16, 8, '亚哈斯将耶和华殿里和王宫府库里所有的金银都送给亚述王为礼物。'),
('CUV', '列王纪下', 12, 16, 9, '亚述王应允了他，就上去攻打大马色，将城攻取，杀了利汛，把居民掳到吉珥。'),
('CUV', '列王纪下', 12, 16, 10, '亚哈斯王上大马色去迎接亚述王提革拉毗列色，在大马色看见一座坛，就照坛的规模样式作法画了图样，送到祭司乌利亚那里。'),
('CUV', '列王纪下', 12, 16, 11, '祭司乌利亚照著亚哈斯王从大马色送来的图样，在亚哈斯王没有从大马色回来之先，建筑一座坛。'),
('CUV', '列王纪下', 12, 16, 12, '王从大马色回来看见坛，就近前来，在坛上献祭；'),
('CUV', '列王纪下', 12, 16, 13, '烧燔祭、素祭、浇奠祭，将平安祭牲的血洒在坛上，'),
('CUV', '列王纪下', 12, 16, 14, '又将耶和华面前的铜坛从耶和华殿和新坛的中间搬到新坛的北边。'),
('CUV', '列王纪下', 12, 16, 15, '亚哈斯王吩咐祭司乌利亚说：早晨的燔祭、晚上的素祭，王的燔祭、素祭，国内众民的燔祭、素祭、奠祭都要烧在大坛上。燔祭牲和平安祭牲的血也要洒在这坛上，只是铜坛我要用以求问耶和华。'),
('CUV', '列王纪下', 12, 16, 16, '祭司乌利亚就照著亚哈斯王所吩咐的行了。'),
('CUV', '列王纪下', 12, 16, 17, '亚哈斯王打掉盆座四面镶著的心子，把盆从座上挪下来，又将铜海从驮海的铜牛上搬下来，放在铺石地；'),
('CUV', '列王纪下', 12, 16, 18, '又因亚述王的缘故，将耶和华殿为安息日所盖的廊子和王从外入殿的廊子挪移，围绕耶和华的殿。'),
('CUV', '列王纪下', 12, 16, 19, '亚哈斯其余所行的事都写在犹大列王记上。'),
('CUV', '列王纪下', 12, 16, 20, '亚哈斯与他列祖同睡，葬在大卫城他列祖的坟地里。他儿子希西家接续他作王。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪下', 12, 17, 1, '犹大王亚哈斯十二年，以拉的儿子何细亚在撒玛利亚登基作以色列王九年。'),
('CUV', '列王纪下', 12, 17, 2, '他行耶和华眼中看为恶的事，只是不像在他以前的以色列诸王。'),
('CUV', '列王纪下', 12, 17, 3, '亚述王撒缦以色上来攻击何细亚，何细亚就服事他，给他进贡。'),
('CUV', '列王纪下', 12, 17, 4, '何细亚背叛，差人去见埃及王梭，不照往年所行的与亚述王进贡。亚述王知道了，就把他锁禁，囚在监里。'),
('CUV', '列王纪下', 12, 17, 5, '亚述王上来攻击以色列遍地，上到撒玛利亚，围困三年。'),
('CUV', '列王纪下', 12, 17, 6, '何细亚第九年亚述王攻取了撒玛利亚，将以色列人掳到亚述，把他们安置在哈腊与歌散的哈博河边，并玛代人的城邑。'),
('CUV', '列王纪下', 12, 17, 7, '这是因以色列人得罪那领他们出埃及地、脱离埃及王法老手的耶和华─他们的神，去敬畏别神，'),
('CUV', '列王纪下', 12, 17, 8, '随从耶和华在他们面前所赶出外邦人的风俗和以色列诸王所立的条规。'),
('CUV', '列王纪下', 12, 17, 9, '以色列人暗中行不正的事，违背耶和华─他们的神，在他们所有的城邑，从瞭望楼直到坚固城，建筑邱坛；'),
('CUV', '列王纪下', 12, 17, 10, '在各高冈上、各青翠树下立柱像和木偶；'),
('CUV', '列王纪下', 12, 17, 11, '在邱坛上烧香，效法耶和华在他们面前赶出的外邦人所行的，又行恶事惹动耶和华的怒气；'),
('CUV', '列王纪下', 12, 17, 12, '且事奉偶像，就是耶和华警戒他们不可行的。'),
('CUV', '列王纪下', 12, 17, 13, '但耶和华藉众先知、先见劝戒以色列人和犹大人说：当离开你们的恶行，谨守我的诫命律例，遵行我吩咐你们列祖，并藉我仆人众先知所传给你们的律法。'),
('CUV', '列王纪下', 12, 17, 14, '他们却不听从，竟硬著颈项，效法他们列祖，不信服耶和华─他们的神，'),
('CUV', '列王纪下', 12, 17, 15, '厌弃他的律例和他与他们列祖所立的约，并劝戒他们的话，随从虚无的神，自己成为虚妄，效法周围的外邦人，就是耶和华嘱咐他们不可效法的；'),
('CUV', '列王纪下', 12, 17, 16, '离弃耶和华─他们神的一切诫命，为自己铸了两个牛犊的像，立了亚舍拉，敬拜天上的万象，事奉巴力，'),
('CUV', '列王纪下', 12, 17, 17, '又使他们的儿女经火，用占卜，行法术卖了自己，行耶和华眼中看为恶的事，惹动他的怒气。'),
('CUV', '列王纪下', 12, 17, 18, '所以耶和华向以色列人大大发怒，从自己面前赶出他们，只剩下犹大一个支派。'),
('CUV', '列王纪下', 12, 17, 19, '犹大人也不遵守耶和华─他们神的诫命，随从以色列人所立的条规。'),
('CUV', '列王纪下', 12, 17, 20, '耶和华就厌弃以色列全族，使他们受苦，把他们交在抢夺他们的人手中，以致赶出他们离开自己面前，'),
('CUV', '列王纪下', 12, 17, 21, '将以色列国从大卫家夺回；他们就立尼八的儿子耶罗波安作王。耶罗波安引诱以色列人不随从耶和华，陷在大罪里。'),
('CUV', '列王纪下', 12, 17, 22, '以色列人犯耶罗波安所犯的一切罪，总不离开，'),
('CUV', '列王纪下', 12, 17, 23, '以致耶和华从自己面前赶出他们，正如藉他仆人众先知所说的。这样，以色列人从本地被掳到亚述，直到今日。'),
('CUV', '列王纪下', 12, 17, 24, '亚述王从巴比伦、古他、亚瓦、哈马，和西法瓦音迁移人来，安置在撒玛利亚的城邑，代替以色列人；他们就得了撒玛利亚，住在其中。'),
('CUV', '列王纪下', 12, 17, 25, '他们才住那里的时候，不敬畏耶和华，所以耶和华叫狮子进入他们中间，咬死了些人。'),
('CUV', '列王纪下', 12, 17, 26, '有人告诉亚述王说：你所迁移安置在撒玛利亚各城的那些民，不知道那地之神的规矩，所以那神叫狮子进入他们中间，咬死他们。'),
('CUV', '列王纪下', 12, 17, 27, '亚述王就吩咐说：叫所掳来的祭司回去一个，使他住在那里，将那地之神的规矩指教那些民。'),
('CUV', '列王纪下', 12, 17, 28, '于是有一个从撒玛利亚掳去的祭司回来，住在伯特利，指教他们怎样敬畏耶和华。'),
('CUV', '列王纪下', 12, 17, 29, '然而，各族之人在所住的城里各为自己制造神像，安置在撒玛利亚人所造有邱坛的殿中。'),
('CUV', '列王纪下', 12, 17, 30, '巴比伦人造疏割•比讷像；古他人造匿甲像；哈马人造亚示玛像；'),
('CUV', '列王纪下', 12, 17, 31, '亚瓦人造匿哈和他珥他像；西法瓦音人用火焚烧儿女，献给西法瓦音的神亚得米勒和亚拿米勒。'),
('CUV', '列王纪下', 12, 17, 32, '他们惧怕耶和华，也从他们中间立邱坛的祭司，为他们在有邱坛的殿中献祭。'),
('CUV', '列王纪下', 12, 17, 33, '他们又惧怕耶和华，又事奉自己的神，从何邦迁移，就随何邦的风俗。'),
('CUV', '列王纪下', 12, 17, 34, '他们直到如今仍照先前的风俗去行，不专心敬畏耶和华，不全守自己的规矩、典章，也不遵守耶和华吩咐雅各后裔的律法、诫命。〈雅各，就是从前耶和华起名叫以色列的。〉'),
('CUV', '列王纪下', 12, 17, 35, '耶和华曾与他们立约，嘱咐他们说：不可敬畏别神，不可跪拜事奉他，也不可向他献祭。'),
('CUV', '列王纪下', 12, 17, 36, '但那用大能和伸出来的膀臂领你们出埃及地的耶和华，你们当敬畏，跪拜，向他献祭。'),
('CUV', '列王纪下', 12, 17, 37, '他给你们写的律例、典章、律法、诫命，你们应当永远谨守遵行，不可敬畏别神。'),
('CUV', '列王纪下', 12, 17, 38, '我─耶和华与你们所立的约你们不可忘记，也不可敬畏别神。'),
('CUV', '列王纪下', 12, 17, 39, '但要敬畏耶和华─你们的神，他必救你们脱离一切仇敌的手。'),
('CUV', '列王纪下', 12, 17, 40, '他们却不听从，仍照先前的风俗去行。'),
('CUV', '列王纪下', 12, 17, 41, '如此这些民又惧怕耶和华，又事奉他们的偶像。他们子子孙孙也都照样行，效法他们的祖宗，直到今日。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪下', 12, 18, 1, '以色列王以拉的儿子何细亚第三年，犹大王亚哈斯的儿子希西家登基。'),
('CUV', '列王纪下', 12, 18, 2, '他登基的时候年二十五岁，在耶路撒冷作王二十九年。他母亲名叫亚比，是撒迦利雅的女儿。'),
('CUV', '列王纪下', 12, 18, 3, '希西家行耶和华眼中看为正的事，效法他祖大卫一切所行的。'),
('CUV', '列王纪下', 12, 18, 4, '他废去邱坛，毁坏柱像，砍下木偶，打碎摩西所造的铜蛇，因为到那时以色列人仍向铜蛇烧香。希西家叫铜蛇为铜块(或作人称铜蛇为铜像)。'),
('CUV', '列王纪下', 12, 18, 5, '希西家倚靠耶和华─以色列的神，在他前后的犹大列王中没有一个及他的。'),
('CUV', '列王纪下', 12, 18, 6, '因为他专靠耶和华，总不离开，谨守耶和华所吩咐摩西的诫命。'),
('CUV', '列王纪下', 12, 18, 7, '耶和华与他同在，他无论往何处去尽都亨通。他背叛、不肯事奉亚述王。'),
('CUV', '列王纪下', 12, 18, 8, '希西家攻击非利士人，直到迦萨，并迦萨的四境，从瞭望楼到坚固城。'),
('CUV', '列王纪下', 12, 18, 9, '希西家王第四年，就是以色列王以拉的儿子何细亚第七年，亚述王撒缦以色上来围困撒玛利亚；'),
('CUV', '列王纪下', 12, 18, 10, '过了三年就攻取了城。希西家第六年，以色列王何细亚第九年，撒玛利亚被攻取了。'),
('CUV', '列王纪下', 12, 18, 11, '亚述王将以色列人掳到亚述，把他们安置在哈腊与歌散的哈博河边，并玛代人的城邑；'),
('CUV', '列王纪下', 12, 18, 12, '都因他们不听从耶和华─他们神的话，违背他的约，就是耶和华仆人摩西吩咐他们所当守的。'),
('CUV', '列王纪下', 12, 18, 13, '希西家王十四年，亚述王西拿基立上来攻击犹大的一切坚固城，将城攻取。'),
('CUV', '列王纪下', 12, 18, 14, '犹大王希西家差人往拉吉去见亚述王，说：我有罪了，求你离开我；凡你罚我的，我必承当。于是亚述王罚犹大王希西家银子三百他连得，金子三十他连得。'),
('CUV', '列王纪下', 12, 18, 15, '希西家就把耶和华殿里和王宫府库里所有的银子都给了他。'),
('CUV', '列王纪下', 12, 18, 16, '那时，犹大王希西家将耶和华殿门上的金子和他自己包在柱上的金子都刮下来，给了亚述王。'),
('CUV', '列王纪下', 12, 18, 17, '亚述王从拉吉差遣他珥探、拉伯撒利，和拉伯沙基率领大军往耶路撒冷，到希西家王那里去。他们上到耶路撒冷，就站在上池的水沟旁，在漂布地的大路上。'),
('CUV', '列王纪下', 12, 18, 18, '他们呼叫王的时候，就有希勒家的儿子家宰以利亚敬，并书记舍伯那和亚萨的儿子史官约亚，出来见他们。'),
('CUV', '列王纪下', 12, 18, 19, '拉伯沙基说：你们去告诉希西家说，亚述大王如此说：你所倚靠的有甚么可仗赖的呢？'),
('CUV', '列王纪下', 12, 18, 20, '你说有打仗的计谋和能力，我看不过是虚话。你到底倚靠谁才背叛我呢？'),
('CUV', '列王纪下', 12, 18, 21, '看哪，你所倚靠的埃及是那压伤的苇杖；人若靠这杖，就必刺透他的手。埃及王法老向一切倚靠他的人也是这样。'),
('CUV', '列王纪下', 12, 18, 22, '你们若对我说：我们倚靠耶和华─我们的神，希西家岂不是将神的邱坛和祭坛废去，且对犹大和耶路撒冷的人说：你们当在耶路撒冷这坛前敬拜么？'),
('CUV', '列王纪下', 12, 18, 23, '现在你把当头给我主亚述王，我给你二千匹马，看你这一面骑马的人够不够。'),
('CUV', '列王纪下', 12, 18, 24, '若不然，怎能打败我主臣仆中最小的军长呢？你竟倚靠埃及的战车马兵么？'),
('CUV', '列王纪下', 12, 18, 25, '现在我上来攻击毁灭这地，岂没有耶和华的意思么？耶和华吩咐我说：你上去攻击毁灭这地罢！'),
('CUV', '列王纪下', 12, 18, 26, '希勒家的儿子以利亚敬和舍伯那，并约亚，对拉伯沙基说：求你用亚兰言语和仆人说话，因为我们懂得；不要用犹大言语和我们说话，达到城上百姓的耳中。'),
('CUV', '列王纪下', 12, 18, 27, '拉伯沙基说：我主差遣我来，岂是单对你和你的主说这些话么？不也是对这些坐在城上、要与你们一同吃自己粪、喝自己尿的人说么？'),
('CUV', '列王纪下', 12, 18, 28, '于是拉伯沙基站著，用犹大言语大声喊著说：你们当听亚述大王的话！'),
('CUV', '列王纪下', 12, 18, 29, '王如此说：你们不要被希西家欺哄了；因他不能救你们脱离我的手。'),
('CUV', '列王纪下', 12, 18, 30, '也不要听希西家使你们倚靠耶和华，说耶和华必要拯救我们，这城必不交在亚述王的手中。'),
('CUV', '列王纪下', 12, 18, 31, '不要听希西家的话！因亚述王如此说：你们要与我和好，出来投降我，各人就可以吃自己葡萄树和无花果树的果子，喝自己井里的水。'),
('CUV', '列王纪下', 12, 18, 32, '等我来领你们到一个地方与你们本地一样，就是有五谷和新酒之地，有粮食和葡萄园之地，有橄榄树和蜂蜜之地，好使你们存活，不至于死。希西家劝导你们，说耶和华必拯救我们；你们不要听他的话。'),
('CUV', '列王纪下', 12, 18, 33, '列国的神有哪一个救他本国脱离亚述王的手呢？'),
('CUV', '列王纪下', 12, 18, 34, '哈马、亚珥拔的神在哪里呢？西法瓦音、希拿、以瓦的神在哪里呢？他们曾救撒玛利亚脱离我的手么？'),
('CUV', '列王纪下', 12, 18, 35, '这些国的神有谁曾救自己的国脱离我的手呢？难道耶和华能救耶路撒冷脱离我的手么？'),
('CUV', '列王纪下', 12, 18, 36, '百姓静默不言，并不回答一句，因为王曾吩咐说：不要回答他。'),
('CUV', '列王纪下', 12, 18, 37, '当下，希勒家的儿子家宰以利亚敬和书记舍伯那，并亚萨的儿子史官约亚，都撕裂衣服，来到希西家那里，将拉伯沙基的话告诉了他。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪下', 12, 19, 1, '希西家王听见，就撕裂衣服，披上麻布，进了耶和华的殿；'),
('CUV', '列王纪下', 12, 19, 2, '使家宰以利亚敬和书记舍伯那，并祭司中的长老，都披上麻布，去见亚摩斯的儿子先知以赛亚，'),
('CUV', '列王纪下', 12, 19, 3, '对他说：希西家如此说：今日是急难、责罚、凌辱的日子，就如妇人将要生产婴孩，却没有力量生产。'),
('CUV', '列王纪下', 12, 19, 4, '或者耶和华─你的神听见拉伯沙基的一切话，就是他主人亚述王打发他来辱骂永生神的话，耶和华─你的神听见这话，就发斥责。故此，求你为余剩的民扬声祷告。'),
('CUV', '列王纪下', 12, 19, 5, '希西家王的臣仆就去见以赛亚。'),
('CUV', '列王纪下', 12, 19, 6, '以赛亚对他们说：要这样对你们的主人说，耶和华如此说：你听见亚述王的仆人亵渎我的话，不要惧怕。'),
('CUV', '列王纪下', 12, 19, 7, '我必惊动(原文作使灵进入)他的心，他要听见风声就归回本地。我必使他在那里倒在刀下。'),
('CUV', '列王纪下', 12, 19, 8, '拉伯沙基回去，正遇见亚述王攻打立拿，原来他早听见亚述王拔营离开拉吉。'),
('CUV', '列王纪下', 12, 19, 9, '亚述王听见人论古实王特哈加说：他出来要与你争战。于是亚述王又打发使者去见希西家，吩咐他们说：'),
('CUV', '列王纪下', 12, 19, 10, '你们对犹大王希西家如此说：不要听你所倚靠的神欺哄你，说耶路撒冷必不交在亚述王的手中。'),
('CUV', '列王纪下', 12, 19, 11, '你总听说亚述诸王向列国所行的，乃是尽行灭绝，难道你还能得救么？'),
('CUV', '列王纪下', 12, 19, 12, '我列祖所毁灭的，就是歌散、哈兰、利色，和属提•拉撒的伊甸人，这些国的神何曾拯救这些国呢？'),
('CUV', '列王纪下', 12, 19, 13, '哈马的王、亚珥拔的王、西法瓦音城的王、希拿，和以瓦的王都在哪里呢？'),
('CUV', '列王纪下', 12, 19, 14, '希西家从使者手里接过书信来，看完了，就上耶和华的殿，将书信在耶和华面前展开。'),
('CUV', '列王纪下', 12, 19, 15, '希西家向耶和华祷告说：坐在二基路伯上耶和华─以色列的神啊，你是天下万国的神，你曾创造天地。'),
('CUV', '列王纪下', 12, 19, 16, '耶和华啊，求你侧耳而听！耶和华啊，求你睁眼而看！要听西拿基立打发使者来辱骂永生神的话。'),
('CUV', '列王纪下', 12, 19, 17, '耶和华啊，亚述诸王果然使列国和列国之地变为荒凉，'),
('CUV', '列王纪下', 12, 19, 18, '将列国的神像都扔在火里；因为他本不是神，乃是人手所造的，是木头石头的，所以灭绝他。'),
('CUV', '列王纪下', 12, 19, 19, '耶和华─我们的神啊，现在求你救我们脱离亚述王的手，使天下万国都知道惟独你─耶和华是神！'),
('CUV', '列王纪下', 12, 19, 20, '亚摩斯的儿子以赛亚就打发人去见希西家，说：耶和华─以色列的神如此说：你既然求我攻击亚述王西拿基立，我已听见了。'),
('CUV', '列王纪下', 12, 19, 21, '耶和华论他这样说：锡安的处女藐视你，嗤笑你；耶路撒冷的女子向你摇头。'),
('CUV', '列王纪下', 12, 19, 22, '你辱骂谁？亵渎谁？扬起声来，高举眼目攻击谁呢？乃是攻击以色列的圣者！'),
('CUV', '列王纪下', 12, 19, 23, '你藉你的使者辱骂主，并说：我率领许多战车上山顶，到利巴嫩极深之处；我要砍伐其中高大的香柏树和佳美的松树；我必上极高之处，进入肥田的树林。'),
('CUV', '列王纪下', 12, 19, 24, '我已经在外邦挖井喝水；我必用脚掌踏干埃及的一切河。'),
('CUV', '列王纪下', 12, 19, 25, '耶和华说，我早先所做的，古时所立的，就是现在藉你使坚固城荒废，变为乱堆，这事你岂没有听见么？'),
('CUV', '列王纪下', 12, 19, 26, '所以其中的居民力量甚小，惊惶羞愧。他们像野草，像青菜，如房顶上的草，又如未长成而枯干的禾稼。'),
('CUV', '列王纪下', 12, 19, 27, '你坐下，你出去，你进来，你向我发烈怒，我都知道。'),
('CUV', '列王纪下', 12, 19, 28, '因你向我发烈怒，又因你狂傲的话达到我耳中，我就要用钩子钩上你的鼻子，把嚼环放在你口里，使你从你来的路转回去。'),
('CUV', '列王纪下', 12, 19, 29, '以色列人哪，我赐你们一个证据：你们今年要吃自生的，明年也要吃自长的；至于后年，你们要耕种收割，栽植葡萄园，吃其中的果子。'),
('CUV', '列王纪下', 12, 19, 30, '犹大家所逃脱余剩的，仍要往下扎根，向上结果。'),
('CUV', '列王纪下', 12, 19, 31, '必有余剩的民从耶路撒冷而出；必有逃脱的人从锡安山而来。耶和华的热心必成就这事。'),
('CUV', '列王纪下', 12, 19, 32, '所以，耶和华论亚述王如此说：他必不得来到这城，也不在这里射箭，不得拿盾牌到城前，也不筑垒攻城。'),
('CUV', '列王纪下', 12, 19, 33, '他从哪条路来，必从那条路回去，必不得来到这城。这是耶和华说的。'),
('CUV', '列王纪下', 12, 19, 34, '因我为自己的缘故，又为我仆人大卫的缘故，必保护拯救这城。'),
('CUV', '列王纪下', 12, 19, 35, '当夜，耶和华的使者出去，在亚述营中杀了十八万五千人。清早有人起来，一看，都是死尸了。'),
('CUV', '列王纪下', 12, 19, 36, '亚述王西拿基立就拔营回去，住在尼尼微。'),
('CUV', '列王纪下', 12, 19, 37, '一日在他的神尼斯洛庙里叩拜，他儿子亚得米勒和沙利色用刀杀了他，就逃到亚拉腊地。他儿子以撒哈顿接续他作王。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪下', 12, 20, 1, '那时，希西家病得要死。亚摩斯的儿子先知以赛亚去见他，对他说：耶和华如此说：你当留遗命与你的家，因为你必死，不能活了。'),
('CUV', '列王纪下', 12, 20, 2, '希西家就转脸朝墙，祷告耶和华说：'),
('CUV', '列王纪下', 12, 20, 3, '耶和华啊，求你记念我在你面前怎样存完全的心，按诚实行事，又做你眼中所看为善的。希西家就痛哭了。'),
('CUV', '列王纪下', 12, 20, 4, '以赛亚出来，还没有到中院(院或作城)，耶和华的话就临到他，说：'),
('CUV', '列王纪下', 12, 20, 5, '你回去告诉我民的君希西家说：耶和华─你祖大卫的神如此说：我听见了你的祷告，看见了你的眼泪，我必医治你；到第三日，你必上到耶和华的殿。'),
('CUV', '列王纪下', 12, 20, 6, '我必加增你十五年的寿数，并且我要救你和这城脱离亚述王的手。我为自己和我仆人大卫的缘故，必保护这城。'),
('CUV', '列王纪下', 12, 20, 7, '以赛亚说：当取一块无花果饼来。人就取了来，贴在疮上，王便痊愈了。'),
('CUV', '列王纪下', 12, 20, 8, '希西家问以赛亚说：耶和华必医治我，到第三日，我能上耶和华的殿，有甚么兆头呢？'),
('CUV', '列王纪下', 12, 20, 9, '以赛亚说：耶和华必成就他所说的。这是他给你的兆头：你要日影向前进十度呢？是要往后退十度呢？'),
('CUV', '列王纪下', 12, 20, 10, '希西家回答说：日影向前进十度容易，我要日影往后退十度。'),
('CUV', '列王纪下', 12, 20, 11, '先知以赛亚求告耶和华，耶和就使亚哈斯的日晷向前进的日影，往后退了十度。'),
('CUV', '列王纪下', 12, 20, 12, '那时，巴比伦王巴拉但的儿子比罗达•巴拉但听见希西家病而痊愈，就送书信和礼物给他。'),
('CUV', '列王纪下', 12, 20, 13, '希西家听从使者的话，就把他宝库的金子、银子、香料、贵重的膏油，和他武库的一切军器，并他所有的财宝，都给他们看。他家中和他全国之内，希西家没有一样不给他们看的。'),
('CUV', '列王纪下', 12, 20, 14, '于是先知以赛亚来见希西家王，问他说：这些人说甚么？他们从哪里来见你？希西家说：他们从远方的巴比伦来。'),
('CUV', '列王纪下', 12, 20, 15, '以赛亚说：他们在你家里看见了甚么？希西家说：凡我家中所有的，他们都看见了；我财宝中没有一样不给他们看的。'),
('CUV', '列王纪下', 12, 20, 16, '以赛亚对希西家说：你要听耶和华的话，'),
('CUV', '列王纪下', 12, 20, 17, '日子必到，凡你家里所有的，并你列祖积蓄到如今的，都要被掳到巴比伦去，不留下一样。这是耶和华说的。'),
('CUV', '列王纪下', 12, 20, 18, '并且从你本身所生的众子，其中必有被掳去在巴比伦王宫里当太监的。'),
('CUV', '列王纪下', 12, 20, 19, '希西家对以赛亚说：你所说耶和华的话甚好！若在我的年日中有太平和稳固的景况，岂不是好么？'),
('CUV', '列王纪下', 12, 20, 20, '希西家其余的事和他的勇力，他怎样挖池、挖沟、引水入城，都写在犹大列王记上。'),
('CUV', '列王纪下', 12, 20, 21, '希西家与他列祖同睡。他儿子玛拿西接续他作王。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪下', 12, 21, 1, '玛拿西登基的时候年十二岁，在耶路撒冷作王五十五年。他母亲名叫协西巴。'),
('CUV', '列王纪下', 12, 21, 2, '玛拿西行耶和华眼中看为恶的事，效法耶和华在以色列人面前赶出的外邦人所行可憎的事。'),
('CUV', '列王纪下', 12, 21, 3, '重新建筑他父希西家所毁坏的邱坛，又为巴力筑坛，做亚舍拉像，效法以色列王亚哈所行的，且敬拜事奉天上的万象；'),
('CUV', '列王纪下', 12, 21, 4, '在耶和华殿宇中筑坛。耶和华曾指著这殿说：我必立我的名在耶路撒冷。'),
('CUV', '列王纪下', 12, 21, 5, '他在耶和华殿的两院中为天上的万象筑坛，'),
('CUV', '列王纪下', 12, 21, 6, '并使他的儿子经火，又观兆，用法术，立交鬼的和行巫术的，多行耶和华眼中看为恶的事，惹动他的怒气；'),
('CUV', '列王纪下', 12, 21, 7, '又在殿内立雕刻的亚舍拉像。耶和华曾对大卫和他儿子所罗门说：我在以色列众支派中所选择的耶路撒冷和这殿，必立我的名，直到永远。'),
('CUV', '列王纪下', 12, 21, 8, '以色列人若谨守遵行我一切所吩咐他们的和我仆人摩西所吩咐他们的一切律法，我就不再使他们挪移离开我所赐给他们列祖之地。'),
('CUV', '列王纪下', 12, 21, 9, '他们却不听从。玛拿西引诱他们行恶，比耶和华在以色列人面前所灭的列国更甚。'),
('CUV', '列王纪下', 12, 21, 10, '耶和华藉他仆人众先知说：'),
('CUV', '列王纪下', 12, 21, 11, '因犹大王玛拿西行这些可憎的恶事比先前亚摩利人所行的更甚，使犹大人拜他的偶像，陷在罪里；'),
('CUV', '列王纪下', 12, 21, 12, '所以耶和华─以色列的神如此说：我必降祸与耶路撒冷和犹大，叫一切听见的人无不耳鸣。'),
('CUV', '列王纪下', 12, 21, 13, '我必用量撒玛利亚的准绳和亚哈家的线铊拉在耶路撒冷上，必擦净耶路撒冷，如人擦盘，将盘倒扣。'),
('CUV', '列王纪下', 12, 21, 14, '我必弃掉所余剩的子民(原文作产业)，把他们交在仇敌手中，使他们成为一切仇敌掳掠之物；'),
('CUV', '列王纪下', 12, 21, 15, '是因他们自从列祖出埃及直到如今，常行我眼中看为恶的事，惹动我的怒气。'),
('CUV', '列王纪下', 12, 21, 16, '玛拿西行耶和华眼中看为恶的事，使犹大人陷在罪里，又流许多无辜人的血，充满了耶路撒冷，从这边直到那边。'),
('CUV', '列王纪下', 12, 21, 17, '玛拿西其余的事，凡他所行的和他所犯的罪都写在犹大列王记上。'),
('CUV', '列王纪下', 12, 21, 18, '玛拿西与他列祖同睡，葬在自己宫院乌撒的园内；他儿子亚们接续他作王。'),
('CUV', '列王纪下', 12, 21, 19, '亚们登基的时候年二十二岁，在耶路撒冷作王二年。他母亲名叫米舒利密，是约提巴人哈鲁斯的女儿。'),
('CUV', '列王纪下', 12, 21, 20, '亚们行耶和华眼中看为恶的事，与他父亲玛拿西所行的一样；'),
('CUV', '列王纪下', 12, 21, 21, '行他父亲一切所行的，敬奉他父亲所敬奉的偶像，'),
('CUV', '列王纪下', 12, 21, 22, '离弃耶和华─他列祖的神，不遵行耶和华的道。'),
('CUV', '列王纪下', 12, 21, 23, '亚们王的臣仆背叛他，在宫里杀了他。'),
('CUV', '列王纪下', 12, 21, 24, '但国民杀了那些背叛亚们王的人，立他儿子约西亚接续他作王。'),
('CUV', '列王纪下', 12, 21, 25, '亚们其余所行的事都写在犹大列王记上。'),
('CUV', '列王纪下', 12, 21, 26, '亚们葬在乌撒的园内自己的坟墓里。他儿子约西亚接续他作王。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪下', 12, 22, 1, '约西亚登基的时候年八岁，在耶路撒冷作王三十一年。他母亲名叫耶底大，是波斯加人亚大雅的女儿。'),
('CUV', '列王纪下', 12, 22, 2, '约西亚行耶和华眼中看为正的事，行他祖大卫一切所行的，不偏左右。'),
('CUV', '列王纪下', 12, 22, 3, '约西亚王十八年，王差遣米书兰的孙子、亚萨利的儿子─书记沙番上耶和华殿去，吩咐他说：'),
('CUV', '列王纪下', 12, 22, 4, '你去见大祭司希勒家，使他将奉到耶和华殿的银子，就是守门的从民中收聚的银子，数算数算，'),
('CUV', '列王纪下', 12, 22, 5, '交给耶和华殿里办事的人，使他们转交耶和华殿里做工的人，好修理殿的破坏之处，'),
('CUV', '列王纪下', 12, 22, 6, '就是转交木匠和工人，并瓦匠，又买木料和凿成的石头修理殿宇，'),
('CUV', '列王纪下', 12, 22, 7, '将银子交在办事的人手里，不与他们算帐，因为他们办事诚实。'),
('CUV', '列王纪下', 12, 22, 8, '大祭司希勒家对书记沙番说：我在耶和华殿里得了律法书。希勒家将书递给沙番，沙番就看了。'),
('CUV', '列王纪下', 12, 22, 9, '书记沙番到王那里，回复王说：你的仆人已将殿里的银子倒出数算，交给耶和华殿里办事的人了。'),
('CUV', '列王纪下', 12, 22, 10, '书记沙番又对王说：祭司希勒家递给我一卷书。沙番就在王面前读那书。'),
('CUV', '列王纪下', 12, 22, 11, '王听见律法书上的话，便撕裂衣服，'),
('CUV', '列王纪下', 12, 22, 12, '吩咐祭司希勒家与沙番的儿子亚希甘、米该亚的儿子亚革波、书记沙番和王的臣仆亚撒雅，说：'),
('CUV', '列王纪下', 12, 22, 13, '你们去为我、为民、为犹大众人，以这书上的话求问耶和华；因为我们列祖没有听从这书上的言语，没有遵著书上所吩咐我们的去行，耶和华就向我们大发烈怒。'),
('CUV', '列王纪下', 12, 22, 14, '于是，祭司希勒家和亚希甘、亚革波、沙番、亚撒雅都去见女先知户勒大。户勒大是掌管礼服沙龙的妻；沙龙是哈珥哈斯的孙子、特瓦的儿子。户勒大住在耶路撒冷第二区。他们请问于他。'),
('CUV', '列王纪下', 12, 22, 15, '他对他们说：耶和华─以色列的神如此说：你们可以回复那差遣你们来见我的人说，'),
('CUV', '列王纪下', 12, 22, 16, '耶和华如此说：我必照著犹大王所读那书上的一切话，降祸与这地和其上的居民。'),
('CUV', '列王纪下', 12, 22, 17, '因为他们离弃我，向别神烧香，用他们手所做的惹我发怒，所以我的忿怒必向这地发作，总不止息。'),
('CUV', '列王纪下', 12, 22, 18, '然而，差遣你们来求问耶和华的犹大王，你们要这样回复他说：耶和华─以色列的神如此说：至于你所听见的话，'),
('CUV', '列王纪下', 12, 22, 19, '就是听见我指著这地和其上的居民所说、要使这地变为荒场、民受咒诅的话，你便心里敬服，在我面前自卑，撕裂衣服，向我哭泣，因此我应允了你。这是我─耶和华说的。'),
('CUV', '列王纪下', 12, 22, 20, '我必使你平平安安地归到坟墓到你列祖那里；我要降与这地的一切灾祸，你也不至亲眼看见。他们就回复王去了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪下', 12, 23, 1, '王差遣人招聚犹大和耶路撒冷的众长老来。'),
('CUV', '列王纪下', 12, 23, 2, '王和犹大众人与耶路撒冷的居民，并祭司、先知，和所有的百姓，无论大小，都一同上到耶和华的殿；王就把耶和华殿里所得的约书念给他们听。'),
('CUV', '列王纪下', 12, 23, 3, '王站在柱旁，在耶和华面前立约，要尽心尽性地顺从耶和华，遵守他的诫命、法度、律例，成就这书上所记的约言。众民都服从这约。'),
('CUV', '列王纪下', 12, 23, 4, '王吩咐大祭司希勒家和副祭司，并把门的，将那为巴力和亚舍拉，并天上万象所造的器皿，都从耶和华殿里搬出来，在耶路撒冷外汲沦溪旁的田间烧了，把灰拿到伯特利去。'),
('CUV', '列王纪下', 12, 23, 5, '从前犹大列王所立拜偶像的祭司，在犹大城邑的邱坛和耶路撒冷的周围烧香，现在王都废去，又废去向巴力和日、月、行星(或作十二宫)，并天上万象烧香的人；'),
('CUV', '列王纪下', 12, 23, 6, '又从耶和华殿里将亚舍拉搬到耶路撒冷外汲沦溪边焚烧，打碎成灰，将灰撒在平民的坟上；'),
('CUV', '列王纪下', 12, 23, 7, '又拆毁耶和华殿里娈童的屋子，就是妇女为亚舍拉织帐子的屋子，'),
('CUV', '列王纪下', 12, 23, 8, '并且从犹大的城邑带众祭司来，污秽祭司烧香的邱坛，从迦巴直到别是巴，又拆毁城门旁的邱坛，这邱坛在邑宰约书亚门前，进城门的左边。'),
('CUV', '列王纪下', 12, 23, 9, '但是邱坛的祭司不登耶路撒冷耶和华的坛，只在他们弟兄中间吃无酵饼。'),
('CUV', '列王纪下', 12, 23, 10, '又污秽欣嫩子谷的陀斐特，不许人在那里使儿女经火献给摩洛；'),
('CUV', '列王纪下', 12, 23, 11, '又将犹大列王在耶和华殿门旁、太监拿单米勒靠近游廊的屋子、向日头所献的马废去，且用火焚烧日车。'),
('CUV', '列王纪下', 12, 23, 12, '犹大列王在亚哈斯楼顶上所筑的坛和玛拿西在耶和华殿两院中所筑的坛，王都拆毁打碎了，就把灰倒在汲沦溪中。'),
('CUV', '列王纪下', 12, 23, 13, '从前以色列王所罗门在耶路撒冷前、邪僻山右边为西顿人可憎的神亚斯他录、摩押人可憎的神基抹、亚扪人可憎的神米勒公所筑的邱坛，王都污秽了，'),
('CUV', '列王纪下', 12, 23, 14, '又打碎柱像，砍下木偶，将人的骨头充满了那地方。'),
('CUV', '列王纪下', 12, 23, 15, '他将伯特利的坛，就是叫以色列人陷在罪里、尼八的儿子耶罗波安所筑的那坛，都拆毁焚烧，打碎成灰，并焚烧了亚舍拉。'),
('CUV', '列王纪下', 12, 23, 16, '约西亚回头，看见山上的坟墓，就打发人将坟墓里的骸骨取出来，烧在坛上，污秽了坛，正如从前神人宣传耶和华的话。'),
('CUV', '列王纪下', 12, 23, 17, '约西亚问说：我所看见的是甚么碑？那城里的人回答说：先前有神人从犹大来，预先说王现在向伯特利坛所行的事，这就是他的墓碑。'),
('CUV', '列王纪下', 12, 23, 18, '约西亚说：由他罢！不要挪移他的骸骨。他们就不动他的骸骨，也不动从撒玛利亚来那先知的骸骨。'),
('CUV', '列王纪下', 12, 23, 19, '从前以色列诸王在撒玛利亚的城邑建筑邱坛的殿，惹动耶和华的怒气，现在约西亚都废去了，就如他在伯特利所行的一般；'),
('CUV', '列王纪下', 12, 23, 20, '又将邱坛的祭司都杀在坛上，并在坛上烧人的骨头，就回耶路撒冷去了。'),
('CUV', '列王纪下', 12, 23, 21, '王吩咐众民说：你们当照这约书上所写的，向耶和华─你们的神守逾越节。'),
('CUV', '列王纪下', 12, 23, 22, '自从士师治理以色列人和以色列王、犹大王的时候，直到如今，实在没有守过这样的逾越节；'),
('CUV', '列王纪下', 12, 23, 23, '只有约西亚王十八年在耶路撒冷向耶和华守这逾越节。'),
('CUV', '列王纪下', 12, 23, 24, '凡犹大国和耶路撒冷所有交鬼的、行巫术的，与家中的神像和偶像，并一切可憎之物，约西亚尽都除掉，成就了祭司希勒家在耶和华殿里所得律法书上所写的话。'),
('CUV', '列王纪下', 12, 23, 25, '在约西亚以前没有王像他尽心、尽性、尽力地归向耶和华，遵行摩西的一切律法；在他以后也没有兴起一个王像他。'),
('CUV', '列王纪下', 12, 23, 26, '然而，耶和华向犹大所发猛烈的怒气仍不止息，是因玛拿西诸事惹动他。'),
('CUV', '列王纪下', 12, 23, 27, '耶和华说：我必将犹大人从我面前赶出，如同赶出以色列人一般；我必弃掉我从前所选择的这城─耶路撒冷和我所说立我名的殿。'),
('CUV', '列王纪下', 12, 23, 28, '约西亚其余的事，凡他所行的都写在犹大列王记上。'),
('CUV', '列王纪下', 12, 23, 29, '约西亚年间，埃及王法老尼哥上到伯拉河攻击亚述王；约西亚王去抵挡他。埃及王遇见约西亚在米吉多，就杀了他。'),
('CUV', '列王纪下', 12, 23, 30, '他的臣仆用车将他的尸首从米吉多送到耶路撒冷，葬在他自己的坟墓里。国民膏约西亚的儿子约哈斯接续他父亲作王。'),
('CUV', '列王纪下', 12, 23, 31, '约哈斯登基的时候年二十三岁，在耶路撒冷作王三个月。他母亲名叫哈慕他，是立拿人耶利米的女儿。'),
('CUV', '列王纪下', 12, 23, 32, '约哈斯行耶和华眼中看为恶的事，效法他列祖一切所行的。'),
('CUV', '列王纪下', 12, 23, 33, '法老尼哥将约哈斯锁禁在哈马地的利比拉，不许他在耶路撒冷作王，又罚犹大国银子一百他连得，金子一他连得。'),
('CUV', '列王纪下', 12, 23, 34, '法老尼哥立约西亚的儿子以利亚敬接续他父亲约西亚作王，给他改名叫约雅敬，却将约哈斯带到埃及，他就死在那里。'),
('CUV', '列王纪下', 12, 23, 35, '约雅敬将金银给法老，遵著法老的命向国民征取金银，按著各人的力量派定，索要金银，好给法老尼哥。'),
('CUV', '列王纪下', 12, 23, 36, '约雅敬登基的时候年二十五岁，在耶路撒冷作王十一年。他母亲名叫西布大，是鲁玛人毗大雅的女儿。'),
('CUV', '列王纪下', 12, 23, 37, '约雅敬行耶和华眼中看为恶的事，效法他列祖一切所行的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪下', 12, 24, 1, '约雅敬年间，巴比伦王尼布甲尼撒上到犹大；约雅敬服事他三年，然后背叛他。'),
('CUV', '列王纪下', 12, 24, 2, '耶和华使迦勒底军、亚兰军、摩押军，和亚扪人的军来攻击约雅敬，毁灭犹大，正如耶和华藉他仆人众先知所说的。'),
('CUV', '列王纪下', 12, 24, 3, '这祸临到犹大人，诚然是耶和华所命的，要将他们从自己面前赶出，是因玛拿西所犯的一切罪；'),
('CUV', '列王纪下', 12, 24, 4, '又因他流无辜人的血，充满了耶路撒冷；耶和华决不肯赦免。'),
('CUV', '列王纪下', 12, 24, 5, '约雅敬其余的事，凡他所行的都写在犹大列王记上。'),
('CUV', '列王纪下', 12, 24, 6, '约雅敬与他列祖同睡。他儿子约雅斤接续他作王。'),
('CUV', '列王纪下', 12, 24, 7, '埃及王不再从他国中出来；因为巴比伦王将埃及王所管之地，从埃及小河直到伯拉河都夺去了。'),
('CUV', '列王纪下', 12, 24, 8, '约雅斤登基的时候年十八岁，在耶路撒冷作王三个月。他母亲名叫尼护施他，是耶路撒冷人以利拿单的女儿。'),
('CUV', '列王纪下', 12, 24, 9, '约雅斤行耶和华眼中看为恶的事，效法他父亲一切所行的。'),
('CUV', '列王纪下', 12, 24, 10, '那时，巴比伦王尼布甲尼撒的军兵上到耶路撒冷，围困城。'),
('CUV', '列王纪下', 12, 24, 11, '当他军兵围困城的时候，巴比伦王尼布甲尼撒就亲自来了。'),
('CUV', '列王纪下', 12, 24, 12, '犹大王约雅斤和他母亲、臣仆、首领、太监一同出城，投降巴比伦王；巴比伦王便拿住他。那时是巴比伦王第八年。'),
('CUV', '列王纪下', 12, 24, 13, '巴比伦王将耶和华殿和王宫里的宝物都拿去了，将以色列王所罗门所造耶和华殿里的金器都毁坏了，正如耶和华所说的；'),
('CUV', '列王纪下', 12, 24, 14, '又将耶路撒冷的众民和众首领，并所有大能的勇士，共一万人，连一切木匠、铁匠都掳了去；除了国中极贫穷的人以外，没有剩下的；'),
('CUV', '列王纪下', 12, 24, 15, '并将约雅斤和王母、后妃、太监，与国中的大官，都从耶路撒冷掳到巴比伦去了；'),
('CUV', '列王纪下', 12, 24, 16, '又将一切勇士七千人和木匠、铁匠一千人，都是能上阵的勇士，全掳到巴比伦去了。'),
('CUV', '列王纪下', 12, 24, 17, '巴比伦王立约雅斤的叔叔玛探雅代替他作王，给玛探雅改名叫西底家。'),
('CUV', '列王纪下', 12, 24, 18, '西底家登基的时候年二十一岁，在耶路撒冷作王十一年。他母亲名叫哈慕他，是立拿人耶利米的女儿。'),
('CUV', '列王纪下', 12, 24, 19, '西底家行耶和华眼中看为恶的事，是照约雅敬一切所行的。'),
('CUV', '列王纪下', 12, 24, 20, '因此耶和华的怒气在耶路撒冷和犹大发作，以致将人民从自己面前赶出。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '列王纪下', 12, 25, 1, '西底家背叛巴比伦王。他作王第九年十月初十日，巴比伦王尼布甲尼撒率领全军来攻击耶路撒冷，对城安营，四围筑垒攻城。'),
('CUV', '列王纪下', 12, 25, 2, '于是城被围困，直到西底家王十一年。'),
('CUV', '列王纪下', 12, 25, 3, '四月初九日，城里有大饥荒，甚至百姓都没有粮食。'),
('CUV', '列王纪下', 12, 25, 4, '城被攻破，一切兵丁就在夜间从靠近王园两城中间的门逃跑。迦勒底人正在四围攻城，王就向亚拉巴逃走。'),
('CUV', '列王纪下', 12, 25, 5, '迦勒底的军队追赶王，在耶利哥的平原追上他；他的全军都离开他四散了。'),
('CUV', '列王纪下', 12, 25, 6, '迦勒底人就拿住王，带他到在利比拉的巴比伦王那里审判他。'),
('CUV', '列王纪下', 12, 25, 7, '在西底家眼前杀了他的众子，并且剜了西底家的眼睛，用铜链锁著他，带到巴比伦去。'),
('CUV', '列王纪下', 12, 25, 8, '巴比伦王尼布甲尼撒十九年五月初七日，巴比伦王的臣仆、护卫长尼布撒拉旦来到耶路撒冷，'),
('CUV', '列王纪下', 12, 25, 9, '用火焚烧耶和华的殿和王宫，又焚烧耶路撒冷的房屋，就是各大户家的房屋。'),
('CUV', '列王纪下', 12, 25, 10, '跟从护卫长迦勒底的全军就拆毁耶路撒冷四围的城墙。'),
('CUV', '列王纪下', 12, 25, 11, '那时护卫长尼布撒拉旦将城里所剩下的百姓，并已经投降巴比伦王的人，以及大众所剩下的人，都掳去了。'),
('CUV', '列王纪下', 12, 25, 12, '但护卫长留下些民中最穷的，使他们修理葡萄园，耕种田地。'),
('CUV', '列王纪下', 12, 25, 13, '耶和华殿的铜柱，并耶和华殿的盆座和铜海，迦勒底人都打碎了，将那铜运到巴比伦去了，'),
('CUV', '列王纪下', 12, 25, 14, '又带去锅、铲子、蜡剪、调羹，并所用的一切铜器，'),
('CUV', '列王纪下', 12, 25, 15, '火鼎、碗，无论金的银的，护卫长也都带去了。'),
('CUV', '列王纪下', 12, 25, 16, '所罗门为耶和华殿所造的两根铜柱、一个铜海，和几个盆座，这一切的铜，多得无法可称。'),
('CUV', '列王纪下', 12, 25, 17, '这一根柱子高十八肘，柱上有铜顶，高三肘；铜顶的周围有网子和石榴，都是铜的。那一根柱子，照此一样，也有网子。'),
('CUV', '列王纪下', 12, 25, 18, '护卫长拿住大祭司西莱雅、副祭司西番亚，和三个把门的，'),
('CUV', '列王纪下', 12, 25, 19, '又从城中拿住一个管理兵丁的官(或作太监)，并在城里所遇常见王面的五个人和检点国民军长的书记，以及城里遇见的国民六十个人。'),
('CUV', '列王纪下', 12, 25, 20, '护卫长尼布撒拉旦将这些人带到在利比拉的巴比伦王那里。'),
('CUV', '列王纪下', 12, 25, 21, '巴比伦王就把他们击杀在哈马地的利比拉。这样，犹大人被掳去离开本地。'),
('CUV', '列王纪下', 12, 25, 22, '至于犹大国剩下的民，就是巴比伦王尼布甲尼撒所剩下的，巴比伦王立了沙番的孙子、亚希甘的儿子基大利作他们的省长。'),
('CUV', '列王纪下', 12, 25, 23, '众军长和属他们的人听见巴比伦王立了基大利作省长，于是军长尼探雅的儿子以实玛利、加利亚的儿子约哈难、尼陀法人单户蔑的儿子西莱雅、玛迦人的儿子雅撒尼亚，和属他们的人都到米斯巴见基大利。'),
('CUV', '列王纪下', 12, 25, 24, '基大利向他们和属他们的人起誓说：你们不必惧怕迦勒底臣仆，只管住在这地服事巴比伦王，就可以得福。'),
('CUV', '列王纪下', 12, 25, 25, '七月间，宗室以利沙玛的孙子、尼探雅的儿子以实玛利带著十个人来，杀了基大利和同他在米斯巴的犹大人与迦勒底人。'),
('CUV', '列王纪下', 12, 25, 26, '于是众民，无论大小，连众军长；因为惧怕迦勒底人，都起身往埃及去了。'),
('CUV', '列王纪下', 12, 25, 27, '犹大王约雅斤被掳后三十七年，巴比伦王以未米罗达元年十二月二十七日，使犹大王约雅斤抬头，提他出监；'),
('CUV', '列王纪下', 12, 25, 28, '又对他说恩言，使他的位高过与他一同在巴比伦众王的位，'),
('CUV', '列王纪下', 12, 25, 29, '给他脱了囚服。他终身常在巴比伦王面前吃饭。'),
('CUV', '列王纪下', 12, 25, 30, '王赐他所需用的食物，日日赐他一分，终身都是这样。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 1, 1, '亚当生塞特；塞特生以挪士；'),
('CUV', '历代志上', 13, 1, 2, '以挪士生该南；该南生玛勒列；玛勒列生雅列；'),
('CUV', '历代志上', 13, 1, 3, '雅列生以诺；以诺生玛土撒拉；玛土撒拉生拉麦；'),
('CUV', '历代志上', 13, 1, 4, '拉麦生挪亚；挪亚生闪、含、雅弗。'),
('CUV', '历代志上', 13, 1, 5, '雅弗的儿子是歌篾、玛各、玛代、雅完、土巴、米设、提拉。'),
('CUV', '历代志上', 13, 1, 6, '歌篾的儿子是亚实基拿、低法(创十章三节作利法)、陀迦玛。'),
('CUV', '历代志上', 13, 1, 7, '雅完的儿子是以利沙、他施、基提、多单(有作罗单的)。'),
('CUV', '历代志上', 13, 1, 8, '含的儿子是古实、麦西、弗、迦南。'),
('CUV', '历代志上', 13, 1, 9, '古实的儿子是西巴、哈腓拉、撒弗他、拉玛、撒弗提迦。拉玛的儿子是示巴、底但。'),
('CUV', '历代志上', 13, 1, 10, '古实生宁录；他为世上英雄之首。'),
('CUV', '历代志上', 13, 1, 11, '麦西生路低人、亚拿米人、利哈比人、拿弗土希人、'),
('CUV', '历代志上', 13, 1, 12, '帕斯鲁细人、迦斯路希人、迦斐托人；从迦斐托出来的有非利士人。'),
('CUV', '历代志上', 13, 1, 13, '迦南生长子西顿，又生赫'),
('CUV', '历代志上', 13, 1, 14, '和耶布斯人、亚摩利人、革迦撒人、'),
('CUV', '历代志上', 13, 1, 15, '希未人、亚基人、西尼人、'),
('CUV', '历代志上', 13, 1, 16, '亚瓦底人、洗玛利人，并哈马人。'),
('CUV', '历代志上', 13, 1, 17, '闪的儿子是以拦、亚述、亚法撒、路德、亚兰、乌斯、户勒、基帖、米设(创十23作玛施)。'),
('CUV', '历代志上', 13, 1, 18, '亚法撒生沙拉；沙拉生希伯。'),
('CUV', '历代志上', 13, 1, 19, '希伯生了两个儿子：一个名叫法勒(就是分的意思)，因为那时人就分地居住；法勒的兄弟名叫约坍。'),
('CUV', '历代志上', 13, 1, 20, '约坍生亚摩答、沙列、哈萨玛非、耶拉、'),
('CUV', '历代志上', 13, 1, 21, '哈多兰、乌萨、德拉、'),
('CUV', '历代志上', 13, 1, 22, '以巴录、亚比玛利、示巴、'),
('CUV', '历代志上', 13, 1, 23, '阿斐、哈腓拉、约巴。这都是约坍的儿子。'),
('CUV', '历代志上', 13, 1, 24, '闪生亚法撒；亚法撒生沙拉；'),
('CUV', '历代志上', 13, 1, 25, '沙拉生希伯；希伯生法勒；法勒生拉吴；'),
('CUV', '历代志上', 13, 1, 26, '拉吴生西鹿；西鹿生拿鹤；拿鹤生他拉；'),
('CUV', '历代志上', 13, 1, 27, '他拉生亚伯兰，亚伯兰就是亚伯拉罕。'),
('CUV', '历代志上', 13, 1, 28, '亚伯拉罕的儿子是以撒、以实玛利。'),
('CUV', '历代志上', 13, 1, 29, '以实玛利的儿子记在下面：以实玛利的长子是尼拜约，其次是基达、押德别、米比衫、'),
('CUV', '历代志上', 13, 1, 30, '米施玛、度玛、玛撒、哈达、提玛、'),
('CUV', '历代志上', 13, 1, 31, '伊突、拿非施、基底玛。这都是以实玛利的儿子。'),
('CUV', '历代志上', 13, 1, 32, '亚伯拉罕的妾基土拉所生的儿子，就是心兰、约珊、米但、米甸、伊施巴、书亚。约珊的儿子是示巴、底但。'),
('CUV', '历代志上', 13, 1, 33, '米甸的儿子是以法、以弗、哈诺、亚比大、以勒大。这都是基土拉的子孙。'),
('CUV', '历代志上', 13, 1, 34, '亚伯拉罕生以撒；以撒的儿子是以扫和以色列。'),
('CUV', '历代志上', 13, 1, 35, '以扫的儿子是以利法、流珥、耶乌施、雅兰、可拉。'),
('CUV', '历代志上', 13, 1, 36, '以利法的儿子是提幔、阿抹、洗玻、迦坦、基纳斯、亭纳、亚玛力。'),
('CUV', '历代志上', 13, 1, 37, '流珥的儿子是拿哈、谢拉、沙玛、米撒。'),
('CUV', '历代志上', 13, 1, 38, '西珥的儿子是罗坍、朔巴、祭便、亚拿、底顺、以察、底珊。'),
('CUV', '历代志上', 13, 1, 39, '罗坍的儿子是何利、荷幔；罗坍的妹子是亭纳。'),
('CUV', '历代志上', 13, 1, 40, '朔巴的儿子是亚勒文、玛拿辖、以巴录、示非、阿南。祭便的儿子是亚雅、亚拿。'),
('CUV', '历代志上', 13, 1, 41, '亚拿的儿子是底顺。底顺的儿子是哈默兰、伊是班、益兰、基兰。'),
('CUV', '历代志上', 13, 1, 42, '以察的儿子是辟罕、撒番、亚干。底珊的儿子是乌斯、亚兰。'),
('CUV', '历代志上', 13, 1, 43, '以色列人未有君王治理之先，在以东地作王的记在下面：有比珥的儿子比拉，他的京城名叫亭哈巴。'),
('CUV', '历代志上', 13, 1, 44, '比拉死了，波斯拉人谢拉的儿子约巴接续他作王。'),
('CUV', '历代志上', 13, 1, 45, '约巴死了，提幔地的人户珊接续他作王。'),
('CUV', '历代志上', 13, 1, 46, '户珊死了，比达的儿子哈达接续他作王。这哈达就是在摩押地杀败米甸人的，他的京城名叫亚未得。'),
('CUV', '历代志上', 13, 1, 47, '哈达死了，玛士利加人桑拉接续他作王。'),
('CUV', '历代志上', 13, 1, 48, '桑拉死了，大河边的利河伯人扫罗接续他作王。'),
('CUV', '历代志上', 13, 1, 49, '扫罗死了，亚革波的儿子巴勒哈南接续他作王。'),
('CUV', '历代志上', 13, 1, 50, '巴勒哈南死了，哈达接续他作王。他的京城名叫巴伊，他的妻子名叫米希他别，是米萨合的孙女，玛特列的女儿。'),
('CUV', '历代志上', 13, 1, 51, '哈达死了，以东人的族长有亭纳族长、亚勒瓦族长、耶帖族长、'),
('CUV', '历代志上', 13, 1, 52, '亚何利巴玛族长、以拉族长、比嫩族长、'),
('CUV', '历代志上', 13, 1, 53, '基纳斯族长、提幔族长、米比萨族长、'),
('CUV', '历代志上', 13, 1, 54, '玛基叠族长、以兰族长。这都是以东人的族长。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 2, 1, '以色列的儿子是流便、西缅、利未、犹大、以萨迦、西布伦、'),
('CUV', '历代志上', 13, 2, 2, '但、约瑟、便雅悯、拿弗他利、迦得、亚设。'),
('CUV', '历代志上', 13, 2, 3, '犹大的儿子是珥、俄南、示拉，这三人是迦南人书亚女儿所生的。犹大的长子珥在耶和华眼中看为恶，耶和华就使他死了。'),
('CUV', '历代志上', 13, 2, 4, '犹大的儿妇他玛给犹大生法勒斯和谢拉。犹大共有五个儿子。'),
('CUV', '历代志上', 13, 2, 5, '法勒斯的儿子是希斯仑、哈母勒。'),
('CUV', '历代志上', 13, 2, 6, '谢拉的儿子是心利、以探、希幔、甲各、大拉(即达大)，共五人。'),
('CUV', '历代志上', 13, 2, 7, '迦米的儿子是亚干，这亚干在当灭的物上犯了罪，连累了以色列人。'),
('CUV', '历代志上', 13, 2, 8, '以探的儿子是亚撒利雅.。'),
('CUV', '历代志上', 13, 2, 9, '希斯仑所生的儿子是耶拉篾、兰、基路拜。'),
('CUV', '历代志上', 13, 2, 10, '兰生亚米拿达；亚米拿达生拿顺。拿顺作犹大人的首领。'),
('CUV', '历代志上', 13, 2, 11, '拿顺生撒门；撒门生波阿斯；'),
('CUV', '历代志上', 13, 2, 12, '波阿斯生俄备得；俄备得生耶西；'),
('CUV', '历代志上', 13, 2, 13, '耶西生长子以利押，次子亚比拿达，三子示米亚(即沙玛，见撒上十六章九节)，'),
('CUV', '历代志上', 13, 2, 14, '四子拿坦业，五子拉代，'),
('CUV', '历代志上', 13, 2, 15, '六子阿鲜，七子大卫。'),
('CUV', '历代志上', 13, 2, 16, '他们的姊妹是洗鲁雅和亚比该。洗鲁雅的儿子是亚比筛、约押、亚撒黑，共三人。'),
('CUV', '历代志上', 13, 2, 17, '亚比该生亚玛撒；亚玛撒的父亲是以实玛利人益帖。'),
('CUV', '历代志上', 13, 2, 18, '希斯仑的儿子迦勒娶阿苏巴和耶略为妻，阿苏巴的儿子是耶设、朔罢、押墩。'),
('CUV', '历代志上', 13, 2, 19, '阿苏巴死了，迦勒又娶以法他，生了户珥。'),
('CUV', '历代志上', 13, 2, 20, '户珥生乌利；乌利生比撒列。'),
('CUV', '历代志上', 13, 2, 21, '希斯仑正六十岁娶了基列父亲玛吉的女儿，与他同房；玛吉的女儿生了西割；'),
('CUV', '历代志上', 13, 2, 22, '西割生睚珥。睚珥在基列地有二十三个城邑。'),
('CUV', '历代志上', 13, 2, 23, '后来基述人和亚兰人夺了睚珥的城邑，并基纳和其乡村，共六十个。这都是基列父亲玛吉之子的。'),
('CUV', '历代志上', 13, 2, 24, '希斯仑在迦勒以法他死后，他的妻亚比雅给他生了亚施户；亚施户是提哥亚的父亲。'),
('CUV', '历代志上', 13, 2, 25, '希斯仑的长子耶拉篾生长子兰，又生布拿、阿连、阿鲜、亚希雅。'),
('CUV', '历代志上', 13, 2, 26, '耶拉篾又娶一妻名叫亚他拉，是阿南的母亲。'),
('CUV', '历代志上', 13, 2, 27, '耶拉篾长子兰的儿子是玛斯、雅悯、以结。'),
('CUV', '历代志上', 13, 2, 28, '阿南的儿子是沙买、雅大。沙买的儿子是拿答、亚比述。'),
('CUV', '历代志上', 13, 2, 29, '亚比述的妻名叫亚比孩，亚比孩给他生了亚办和摩利。'),
('CUV', '历代志上', 13, 2, 30, '拿答的儿子是西列、亚遍；西列死了没有儿子。'),
('CUV', '历代志上', 13, 2, 31, '亚遍的儿子是以示；以示的儿子是示珊；示珊的儿子是亚来。'),
('CUV', '历代志上', 13, 2, 32, '沙买兄弟雅大的儿子是益帖、约拿单；益帖死了没有儿子。'),
('CUV', '历代志上', 13, 2, 33, '约拿单的儿子是比勒、撒萨。这都是耶拉篾的子孙。'),
('CUV', '历代志上', 13, 2, 34, '示珊没有儿子，只有女儿。示珊有一个仆人名叫耶哈，是埃及人。'),
('CUV', '历代志上', 13, 2, 35, '示珊将女儿给了仆人耶哈为妻，给他生了亚太。'),
('CUV', '历代志上', 13, 2, 36, '亚太生拿单；拿单生撒拔；'),
('CUV', '历代志上', 13, 2, 37, '撒拔生以弗拉；以弗拉生俄备得；'),
('CUV', '历代志上', 13, 2, 38, '俄备得生耶户；耶户生亚撒利雅；'),
('CUV', '历代志上', 13, 2, 39, '亚撒利雅生希利斯；希利斯生以利亚萨；'),
('CUV', '历代志上', 13, 2, 40, '以利亚萨生西斯买；西斯买生沙龙；'),
('CUV', '历代志上', 13, 2, 41, '沙龙生耶加米雅；耶加米雅生以利沙玛。'),
('CUV', '历代志上', 13, 2, 42, '耶拉篾兄弟迦勒的长子米沙，是西弗之祖玛利沙的儿子，是希伯仑之祖。'),
('CUV', '历代志上', 13, 2, 43, '希伯仑的儿子是可拉、他普亚、利肯、示玛。'),
('CUV', '历代志上', 13, 2, 44, '示玛生拉含，是约干之祖。利肯生沙买。'),
('CUV', '历代志上', 13, 2, 45, '沙买的儿子是玛云；玛云是伯夙之祖。'),
('CUV', '历代志上', 13, 2, 46, '迦勒的妾以法生哈兰、摩撒、迦谢；哈兰生迦卸。'),
('CUV', '历代志上', 13, 2, 47, '〈雅代的儿子是利健、约坦、基珊、毗力、以法、沙亚弗。〉'),
('CUV', '历代志上', 13, 2, 48, '迦勒的妾玛迦生示别、特哈拿，'),
('CUV', '历代志上', 13, 2, 49, '又生麦玛拿之祖沙亚弗、抹比拿和基比亚之祖示法。迦勒的女儿是押撒。'),
('CUV', '历代志上', 13, 2, 50, '迦勒的子孙就是以法他的长子、户珥的儿子，记在下面：基列耶琳之祖朔巴，'),
('CUV', '历代志上', 13, 2, 51, '伯利恒之祖萨玛，伯迦得之祖哈勒。'),
('CUV', '历代志上', 13, 2, 52, '基列耶琳之祖朔巴的子孙是哈罗以和一半米努哈人(即玛拿哈人)。'),
('CUV', '历代志上', 13, 2, 53, '基列耶琳的诸族是以帖人、布特人、舒玛人、密来人，又从这些族中生出琐拉人和以实陶人来。'),
('CUV', '历代志上', 13, 2, 54, '萨玛的子孙是伯利恒人、尼陀法人、亚他绿伯约押人、一半玛拿哈人、琐利人，'),
('CUV', '历代志上', 13, 2, 55, '和住雅比斯众文士家的特拉人、示米押人、苏甲人。这都是基尼人利甲家之祖哈末所生的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 3, 1, '大卫在希伯仑所生的儿子记在下面：长子暗嫩是耶斯列人亚希暖生的。次子但以利是迦密人亚比该生的。'),
('CUV', '历代志上', 13, 3, 2, '三子押沙龙是基述王达买的女儿玛迦生的。四子亚多尼雅是哈及生的。'),
('CUV', '历代志上', 13, 3, 3, '五子示法提雅是亚比他生的。六子以特念是大卫的妻以格拉生的。'),
('CUV', '历代志上', 13, 3, 4, '这六人都是大卫在希伯仑生的。大卫在希伯仑作王七年零六个月，在耶路撒冷作王三十三年。'),
('CUV', '历代志上', 13, 3, 5, '大卫在耶路撒冷所生的儿子是示米亚、朔罢、拿单、所罗门。这四人是亚米利的女儿拔书亚生的。'),
('CUV', '历代志上', 13, 3, 6, '还有益辖、以利沙玛、以利法列、'),
('CUV', '历代志上', 13, 3, 7, '挪迦、尼斐、雅非亚、'),
('CUV', '历代志上', 13, 3, 8, '以利沙玛、以利雅大、以利法列，共九人。'),
('CUV', '历代志上', 13, 3, 9, '这都是大卫的儿子，还有他们的妹子他玛，妃嫔的儿子不在其内。'),
('CUV', '历代志上', 13, 3, 10, '所罗门的儿子是罗波安；罗波安的儿子是亚比雅；亚比雅的儿子是亚撒；亚撒的儿子是约沙法；'),
('CUV', '历代志上', 13, 3, 11, '约沙法的儿子是约兰；约兰的儿子是亚哈谢；亚哈谢的儿子是约阿施；'),
('CUV', '历代志上', 13, 3, 12, '约阿施的儿子是亚玛谢；亚玛谢的儿子是亚撒利雅；亚撒利雅的儿子是约坦；'),
('CUV', '历代志上', 13, 3, 13, '约坦的儿子是亚哈斯；亚哈斯的儿子是希西家；希西家的儿子是玛拿西；'),
('CUV', '历代志上', 13, 3, 14, '玛拿西的儿子是亚们；亚们的儿子是约西亚；'),
('CUV', '历代志上', 13, 3, 15, '约西亚的长子是约哈难，次子是约雅敬，三子是西底家，四子是沙龙。'),
('CUV', '历代志上', 13, 3, 16, '约雅敬的儿子是耶哥尼雅和西底家。'),
('CUV', '历代志上', 13, 3, 17, '耶哥尼雅被掳。他的儿子是撒拉铁、'),
('CUV', '历代志上', 13, 3, 18, '玛基兰、毗大雅、示拿萨、耶加米、何沙玛、尼大比雅。'),
('CUV', '历代志上', 13, 3, 19, '毗大雅的儿子是所罗巴伯、示每。所罗巴伯的儿子是米书兰、哈拿尼雅，他们的妹子名叫示罗密。'),
('CUV', '历代志上', 13, 3, 20, '米书兰的儿子是哈舒巴、阿黑、比利家、哈撒底、于沙希悉，共五人。'),
('CUV', '历代志上', 13, 3, 21, '哈拿尼雅的儿子是毗拉提、耶筛亚。还有利法雅的众子，亚珥难的众子，俄巴底亚的众子，示迦尼的众子。'),
('CUV', '历代志上', 13, 3, 22, '示迦尼的儿子是示玛雅；示玛雅的儿子是哈突、以甲、巴利亚、尼利雅、沙法，共六人。'),
('CUV', '历代志上', 13, 3, 23, '尼利雅的儿子是以利约乃、希西家、亚斯利干，共三人。'),
('CUV', '历代志上', 13, 3, 24, '以利约乃的儿子是何大雅、以利亚实、毗莱雅、阿谷、约哈难、第莱雅、阿拿尼，共七人。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 4, 1, '犹大的儿子是法勒斯、希斯仑、迦米、户珥、朔巴。'),
('CUV', '历代志上', 13, 4, 2, '朔巴的儿子利亚雅生雅哈；雅哈生亚户买和拉哈。这是琐拉人的诸族。'),
('CUV', '历代志上', 13, 4, 3, '以坦之祖的儿子是耶斯列、伊施玛、伊得巴；他们的妹子名叫哈悉勒玻尼。'),
('CUV', '历代志上', 13, 4, 4, '基多之祖是毗努伊勒。户沙之祖是以谢珥。这都是伯利恒之祖以法他的长子户珥所生的。'),
('CUV', '历代志上', 13, 4, 5, '提哥亚之祖亚施户有两个妻子：一名希拉，一名拿拉。'),
('CUV', '历代志上', 13, 4, 6, '拿拉给亚施户生亚户撒、希弗、提米尼、哈辖斯他利。这都是拿拉的儿子。'),
('CUV', '历代志上', 13, 4, 7, '希拉的儿子是洗列、琐辖、伊提南。'),
('CUV', '历代志上', 13, 4, 8, '哥斯生亚诺、琐比巴，并哈仑儿子亚哈黑的诸族。'),
('CUV', '历代志上', 13, 4, 9, '雅比斯比他众弟兄更尊贵，他母亲给他起名叫雅比斯，意思说：我生他甚是痛苦。'),
('CUV', '历代志上', 13, 4, 10, '雅比斯求告以色列的神说：甚愿你赐福与我，扩张我的境界，常与我同在，保佑我不遭患难，不受艰苦。神就应允他所求的。'),
('CUV', '历代志上', 13, 4, 11, '书哈的弟兄基绿生米黑，米黑是伊施屯之祖。'),
('CUV', '历代志上', 13, 4, 12, '伊施屯生伯拉巴、巴西亚，并珥拿辖之祖提欣拿，这都是利迦人。'),
('CUV', '历代志上', 13, 4, 13, '基纳斯的儿子是俄陀聂、西莱雅。俄陀聂的儿子是哈塔。'),
('CUV', '历代志上', 13, 4, 14, '悯挪太生俄弗拉；西莱雅生革夏纳欣人之祖约押。他们都是匠人。'),
('CUV', '历代志上', 13, 4, 15, '耶孚尼的儿子是迦勒；迦勒的儿子是以路、以拉、拿安。以拉的儿子是基纳斯。'),
('CUV', '历代志上', 13, 4, 16, '耶哈利勒的儿子是西弗、西法、提利、亚撒列。'),
('CUV', '历代志上', 13, 4, 17, '以斯拉的儿子是益帖、米列、以弗、雅伦。米列娶法老女儿比提雅为妻，生米利暗、沙买，和以实提摩之祖益巴。米列又娶犹大女子为妻，生基多之祖雅列，梭哥之祖希伯，和撒挪亚之祖耶古铁。'),
('CUV', '历代志上', 13, 4, 18, 'a'),
('CUV', '历代志上', 13, 4, 19, '荷第雅的妻是拿含的妹子，他所生的儿子是迦米人基伊拉和玛迦人以实提摩之祖。'),
('CUV', '历代志上', 13, 4, 20, '示门的儿子是暗嫩、林拿、便哈南、提伦。以示的儿子是梭黑与便梭黑。'),
('CUV', '历代志上', 13, 4, 21, '犹大的儿子是示拉；示拉的儿子是利迦之祖珥，玛利沙之祖拉大，和属亚实比族织细麻布的各家。'),
('CUV', '历代志上', 13, 4, 22, '还有约敬、哥西巴人、约阿施、萨拉，就是在摩押地掌权的，又有雅叔比利恒。这都是古时所记载的。'),
('CUV', '历代志上', 13, 4, 23, '这些人都是窑匠，是尼他应和基低拉的居民；与王同处，为王做工。'),
('CUV', '历代志上', 13, 4, 24, '西缅的儿子是尼母利、雅悯、雅立、谢拉、扫罗。'),
('CUV', '历代志上', 13, 4, 25, '扫罗的儿子是沙龙；沙龙的儿子是米比衫；米比衫的儿子是米施玛；'),
('CUV', '历代志上', 13, 4, 26, '米施玛的儿子是哈母利；哈母利的儿子是撒刻；撒刻的儿子是示每。'),
('CUV', '历代志上', 13, 4, 27, '示每有十六个儿子，六个女儿，他弟兄的儿女不多，他们各家不如犹大族的人丁增多。'),
('CUV', '历代志上', 13, 4, 28, '西缅人住在别是巴、摩拉大、哈萨书亚、'),
('CUV', '历代志上', 13, 4, 29, '辟拉、以森、陀腊、'),
('CUV', '历代志上', 13, 4, 30, '彼土利、何珥玛、洗革拉、'),
('CUV', '历代志上', 13, 4, 31, '伯玛嘉博、哈萨苏撒、伯比利、沙拉音，这些城邑直到大卫作王的时候都是属西缅人的。'),
('CUV', '历代志上', 13, 4, 32, '他们的五个城邑是以坦、亚因、临门、陀健、亚珊；'),
('CUV', '历代志上', 13, 4, 33, '还有属城的乡村，直到巴力。这是他们的住处，他们都有家谱。'),
('CUV', '历代志上', 13, 4, 34, '还有米所巴、雅米勒、亚玛谢的儿子约沙、'),
('CUV', '历代志上', 13, 4, 35, '约珥、约示比的儿子耶户；约示比是西莱雅的儿子；西莱雅是亚薛的儿子。'),
('CUV', '历代志上', 13, 4, 36, '还有以利约乃、雅哥巴、约朔海、亚帅雅、亚底业、耶西篾、比拿雅、'),
('CUV', '历代志上', 13, 4, 37, '示非的儿子细撒。示非是亚龙的儿子；亚龙是耶大雅的儿子；耶大雅是申利的儿子；申利是示玛雅的儿子。'),
('CUV', '历代志上', 13, 4, 38, '以上所记的人名都是作族长的，他们宗族的人数增多。'),
('CUV', '历代志上', 13, 4, 39, '他们往平原东边基多口去，寻找牧放羊群的草场，'),
('CUV', '历代志上', 13, 4, 40, '寻得肥美的草场地，又宽阔又平静。从前住那里的是含族的人。'),
('CUV', '历代志上', 13, 4, 41, '以上录名的人，在犹大王希西家年间，来攻击含族人的帐棚和那里所有的米乌尼人，将他们灭尽，就住在他们的地方，直到今日，因为那里有草场可以牧放羊群。'),
('CUV', '历代志上', 13, 4, 42, '这西缅人中，有五百人上西珥山，率领他们的是以示的儿子毗拉提、尼利雅、利法雅，和乌薛，'),
('CUV', '历代志上', 13, 4, 43, '杀了逃脱剩下的亚玛力人，就住在那里直到今日。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 5, 1, '以色列的长子原是流便；因他污秽了父亲的床，他长子的名分就归了约瑟。只是按家谱他不算长子。'),
('CUV', '历代志上', 13, 5, 2, '犹大胜过一切弟兄，君王也是从他而出；长子的名分却归约瑟。'),
('CUV', '历代志上', 13, 5, 3, '以色列长子流便的儿子是哈诺、法路、希斯伦、迦米。'),
('CUV', '历代志上', 13, 5, 4, '约珥的儿子是示玛雅；示玛雅的儿子是歌革；歌革的儿子是示每；'),
('CUV', '历代志上', 13, 5, 5, '示每的儿子是米迦；米迦的儿子是利亚雅；利亚雅的儿子是巴力；'),
('CUV', '历代志上', 13, 5, 6, '巴力的儿子是备拉。这备拉作流便支派的首领，被亚述王提革拉毗尼色掳去。'),
('CUV', '历代志上', 13, 5, 7, '他的弟兄照著宗族，按著家谱作族长的是耶利、撒迦利雅、比拉。'),
('CUV', '历代志上', 13, 5, 8, '比拉是亚撒的儿子；亚撒是示玛的儿子；示玛是约珥的儿子；约珥所住的地方是从亚罗珥直到尼波和巴力免，'),
('CUV', '历代志上', 13, 5, 9, '又向东延到伯拉河这边的旷野，因为他们在基列地牲畜增多。'),
('CUV', '历代志上', 13, 5, 10, '扫罗年间，他们与夏甲人争战，夏甲人倒在他们手下，他们就在基列东边的全地，住在夏甲人的帐棚里。'),
('CUV', '历代志上', 13, 5, 11, '迦得的子孙在流便对面，住在巴珊地，延到撒迦。'),
('CUV', '历代志上', 13, 5, 12, '他们中间有作族长的约珥，有作副族长的沙番，还有雅乃和住在巴珊的沙法。'),
('CUV', '历代志上', 13, 5, 13, '他们族弟兄是米迦勒、米书兰、示巴、约赖、雅干、细亚、希伯，共七人。'),
('CUV', '历代志上', 13, 5, 14, '这都是亚比孩的儿子。亚比孩是户利的儿子；户利是耶罗亚的儿子；耶罗亚是基列的儿子；基列是米迦勒的儿子；米迦勒是耶示筛的儿子；耶示筛是耶哈多的儿子；耶哈多是布斯的儿子。'),
('CUV', '历代志上', 13, 5, 15, '还有古尼的孙子、押比叠的儿子亚希。这都是作族长的。'),
('CUV', '历代志上', 13, 5, 16, '他们住在基列与巴珊和巴珊的乡村，并沙仑的郊野，直到四围的交界。'),
('CUV', '历代志上', 13, 5, 17, '这些人在犹大王约坦并在以色列王耶罗波安年间，都载入家谱。'),
('CUV', '历代志上', 13, 5, 18, '流便人、迦得人，和玛拿西半支派的人，能拿盾牌和刀剑、拉弓射箭、出征善战的勇士共有四万四千七百六十名。'),
('CUV', '历代志上', 13, 5, 19, '他们与夏甲人、伊突人、拿非施人、挪答人争战。'),
('CUV', '历代志上', 13, 5, 20, '他们得了神的帮助，夏甲人和跟随夏甲的人都交在他们手中；因为他们在阵上呼求神，倚赖神，神就应允他们。'),
('CUV', '历代志上', 13, 5, 21, '他们掳掠了夏甲人的牲畜，有骆驼五万，羊二十五万，驴二千；又有人十万。'),
('CUV', '历代志上', 13, 5, 22, '敌人被杀仆倒的甚多，因为这争战是出乎神。他们就住在敌人的地上，直到被掳的时候。'),
('CUV', '历代志上', 13, 5, 23, '玛拿西半支派的人住在那地。从巴珊延到巴力黑们、示尼珥与黑门山。'),
('CUV', '历代志上', 13, 5, 24, '他们的族长是以弗、以示、以列、亚斯列、耶利米、何达威雅、雅叠，都是大能的勇士，是有名的人，也是作族长的。'),
('CUV', '历代志上', 13, 5, 25, '他们得罪了他们列祖的神，随从那地之民的神行邪淫；这民就是神在他们面前所除灭的。'),
('CUV', '历代志上', 13, 5, 26, '故此，以色列的神激动亚述王普勒和亚述王提革拉毗尼色的心，他们就把流便人、迦得人、玛拿西半支派的人掳到哈腊、哈博、哈拉与歌散河边，直到今日还在那里。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 6, 1, '利未的儿子是革顺、哥辖、米拉利。'),
('CUV', '历代志上', 13, 6, 2, '哥辖的儿子是暗兰、以斯哈、希伯伦、乌薛。'),
('CUV', '历代志上', 13, 6, 3, '暗兰的儿子是亚伦、摩西，还有女儿米利暗。亚伦的儿子是拿答、亚比户、以利亚撒、以他玛。'),
('CUV', '历代志上', 13, 6, 4, '以利亚撒生非尼哈；非尼哈生亚比书；'),
('CUV', '历代志上', 13, 6, 5, '亚比书生布基；布基生乌西；'),
('CUV', '历代志上', 13, 6, 6, '乌西生西拉希雅；西拉希雅生米拉约；'),
('CUV', '历代志上', 13, 6, 7, '米拉约生亚玛利雅；亚玛利雅生亚希突；'),
('CUV', '历代志上', 13, 6, 8, '亚希突生撒督；撒督生亚希玛斯；'),
('CUV', '历代志上', 13, 6, 9, '亚希玛斯生亚撒利雅；亚撒利雅生约哈难；'),
('CUV', '历代志上', 13, 6, 10, '约哈难生亚撒利雅（这亚撒利雅在所罗门于耶路撒冷所建造的殿中，供祭司的职分）；'),
('CUV', '历代志上', 13, 6, 11, '亚撒利雅生亚玛利雅；亚玛利雅生亚希突；'),
('CUV', '历代志上', 13, 6, 12, '亚希突生撒督；撒督生沙龙；'),
('CUV', '历代志上', 13, 6, 13, '沙龙生希勒家；希勒家生亚撒利雅；'),
('CUV', '历代志上', 13, 6, 14, '亚撒利雅生西莱雅；西莱雅生约萨答。'),
('CUV', '历代志上', 13, 6, 15, '当耶和华藉尼布甲尼撒的手掳掠犹大和耶路撒冷人的时候，这约萨答也被掳去。'),
('CUV', '历代志上', 13, 6, 16, '利未的儿子是革顺、哥辖、米拉利。'),
('CUV', '历代志上', 13, 6, 17, '革顺的儿子名叫立尼、示每。'),
('CUV', '历代志上', 13, 6, 18, '哥辖的儿子是暗兰、以斯哈、希伯伦、乌薛。'),
('CUV', '历代志上', 13, 6, 19, '米拉利的儿子是抹利、母示。这是按著利未人宗族分的各家。'),
('CUV', '历代志上', 13, 6, 20, '革顺的儿子是立尼；立尼的儿子是雅哈；雅哈的儿子是薪玛；'),
('CUV', '历代志上', 13, 6, 21, '薪玛的儿子是约亚；约亚的儿子是易多；易多的儿子是谢拉；谢拉的儿子是耶特赖。'),
('CUV', '历代志上', 13, 6, 22, '哥辖的儿子是亚米拿达；亚米拿达的儿子是可拉；可拉的儿子是亚惜；'),
('CUV', '历代志上', 13, 6, 23, '亚惜的儿子是以利加拿；以利加拿的儿子是以比雅撒；以比雅撒的儿子是亚惜；'),
('CUV', '历代志上', 13, 6, 24, '亚惜的儿子是他哈；他哈的儿子是乌列；乌列的儿子是乌西雅；乌西雅的儿子是少罗。'),
('CUV', '历代志上', 13, 6, 25, '以利加拿的儿子是亚玛赛和亚希摩。'),
('CUV', '历代志上', 13, 6, 26, '亚希摩的儿子是以利加拿；以利加拿的儿子是琐菲；琐菲的儿子是拿哈；'),
('CUV', '历代志上', 13, 6, 27, '拿哈的儿子是以利押；以利押的儿子是耶罗罕；耶罗罕的儿子是以利加拿；以利加拿的儿子是撒母耳。'),
('CUV', '历代志上', 13, 6, 28, '撒母耳的长子是约珥，次子是亚比亚。'),
('CUV', '历代志上', 13, 6, 29, '米拉利的儿子是抹利；抹利的儿子是立尼；立尼的儿子是示每；示每的儿子是乌撒；'),
('CUV', '历代志上', 13, 6, 30, '乌撒的儿子是示米亚；示米亚的儿子是哈基雅；哈基雅的儿子是亚帅雅。'),
('CUV', '历代志上', 13, 6, 31, '约柜安设之后，大卫派人在耶和华殿中管理歌唱的事。'),
('CUV', '历代志上', 13, 6, 32, '他们就在会幕前当歌唱的差，及至所罗门在耶路撒冷建造了耶和华的殿，他们便按著班次供职。'),
('CUV', '历代志上', 13, 6, 33, '供职的人和他们的子孙记在下面：哥辖的子孙中有歌唱的希幔。希幔是约珥的儿子；约珥是撒母耳的儿子；'),
('CUV', '历代志上', 13, 6, 34, '撒母耳是以利加拿的儿子；以利加拿是耶罗罕的儿子；耶罗罕是以列的儿子；以列是陀亚的儿子；'),
('CUV', '历代志上', 13, 6, 35, '陀亚是苏弗的儿子；苏弗是以利加拿的儿子；以利加拿是玛哈的儿子；玛哈是亚玛赛的儿子；'),
('CUV', '历代志上', 13, 6, 36, '亚玛赛是以利加拿的儿子；以利加拿是约珥的儿子；约珥是亚撒利雅的儿子；亚撒利雅是西番雅的儿子；'),
('CUV', '历代志上', 13, 6, 37, '西番雅是他哈的儿子；他哈是亚惜的儿子；亚惜是以比雅撒的儿子；以比雅撒是可拉的儿子；'),
('CUV', '历代志上', 13, 6, 38, '可拉是以斯哈的儿子；以斯哈是哥辖的儿子；哥辖是利未的儿子；利未是以色列的儿子。'),
('CUV', '历代志上', 13, 6, 39, '希幔的族兄亚萨是比利家的儿子，亚萨在希幔右边供职。比利家是示米亚的儿子；'),
('CUV', '历代志上', 13, 6, 40, '示米亚是米迦勒的儿子；米迦勒是巴西雅的儿子；巴西雅是玛基雅的儿子；'),
('CUV', '历代志上', 13, 6, 41, '玛基雅是伊特尼的儿子；伊特尼是谢拉的儿子；谢拉是亚大雅的儿子；'),
('CUV', '历代志上', 13, 6, 42, '亚大雅是以探的儿子；以探是薪玛的儿子；薪玛是示每的儿子；'),
('CUV', '历代志上', 13, 6, 43, '示每是雅哈的儿子；雅哈是革顺的儿子。革顺是利未的儿子。'),
('CUV', '历代志上', 13, 6, 44, '他们的族弟兄米拉利的子孙，在他们左边供职的有以探。以探是基示的儿子；基示是亚伯底的儿子；亚伯底是玛鹿的儿子；'),
('CUV', '历代志上', 13, 6, 45, '玛鹿是哈沙比雅的儿子；哈沙比雅是亚玛谢的儿子；亚玛谢是希勒家的儿子；'),
('CUV', '历代志上', 13, 6, 46, '希勒家是暗西的儿子；暗西是巴尼的儿子；巴尼是沙麦的儿子；'),
('CUV', '历代志上', 13, 6, 47, '沙麦是末力的儿子；末力是母示的儿子；母示是米拉利的儿子；米拉利是利未的儿子。'),
('CUV', '历代志上', 13, 6, 48, '他们的族弟兄利未人也被派办神殿中的一切事。'),
('CUV', '历代志上', 13, 6, 49, '亚伦和他的子孙在燔祭坛和香坛上献祭烧香，又在至圣所办理一切的事，为以色列人赎罪，是照神仆人摩西所吩咐的。'),
('CUV', '历代志上', 13, 6, 50, '亚伦的儿子是以利亚撒；以利亚撒的儿子是非尼哈；非尼哈的儿子是亚比书；'),
('CUV', '历代志上', 13, 6, 51, '亚比书的儿子是布基；布基的儿子是乌西；乌西的儿子是西拉希雅；'),
('CUV', '历代志上', 13, 6, 52, '西拉希雅的儿子是米拉约；米拉约的儿子是亚玛利雅；亚玛利雅的儿子是亚希突；'),
('CUV', '历代志上', 13, 6, 53, '亚希突的儿子是撒督；撒督的儿子是亚希玛斯。'),
('CUV', '历代志上', 13, 6, 54, '他们的住处按著境内的营寨，记在下面：哥辖族亚伦的子孙先拈阄得地，'),
('CUV', '历代志上', 13, 6, 55, '在犹大地中得了希伯仑和四围的郊野；'),
('CUV', '历代志上', 13, 6, 56, '只是属城的田地和村庄都为耶孚尼的儿子迦勒所得。'),
('CUV', '历代志上', 13, 6, 57, '亚伦的子孙得了逃城希伯仑，又得了立拿与其郊野，雅提珥、以实提莫与其郊野；'),
('CUV', '历代志上', 13, 6, 58, '希仑与其郊野，底璧与其郊野，'),
('CUV', '历代志上', 13, 6, 59, '亚珊与其郊野，伯示麦与其郊野。'),
('CUV', '历代志上', 13, 6, 60, '在便雅悯支派的地中，得了迦巴与其郊野，阿勒篾与其郊野，亚拿突与其郊野。他们诸家所得的城共十三座。'),
('CUV', '历代志上', 13, 6, 61, '哥辖族其余的人又拈阄，在玛拿西半支派的地中得了十座城。'),
('CUV', '历代志上', 13, 6, 62, '革顺族按著宗族，在以萨迦支派的地中，亚设支派的地中，拿弗他利支派的地中，巴珊内玛拿西支派的地中，得了十三座城。'),
('CUV', '历代志上', 13, 6, 63, '米拉利族按著宗族拈阄，在流便支派的地中，迦得支派的地中，西布伦支派的地中，得了十二座城。'),
('CUV', '历代志上', 13, 6, 64, '以色列人将这些城与其郊野给了利未人。'),
('CUV', '历代志上', 13, 6, 65, '这以上录名的城，在犹大、西缅、便雅悯三支派的地中，以色列人拈阄给了他们。'),
('CUV', '历代志上', 13, 6, 66, '哥辖族中有几家在以法莲支派的地中也得了城邑，'),
('CUV', '历代志上', 13, 6, 67, '在以法莲山地得了逃城示剑与其郊野，又得了基色与其郊野，'),
('CUV', '历代志上', 13, 6, 68, '约缅与其郊野，伯和仑与其郊野，'),
('CUV', '历代志上', 13, 6, 69, '亚雅仑与其郊野，迦特临门与其郊野。'),
('CUV', '历代志上', 13, 6, 70, '哥辖族其余的人在玛拿西半支派的地中得了亚乃与其郊野，比连与其郊野。'),
('CUV', '历代志上', 13, 6, 71, '革顺族在玛拿西半支派的地中得了巴珊的哥兰与其郊野，亚斯他录与其郊野；'),
('CUV', '历代志上', 13, 6, 72, '又在以萨迦支派的地中得了基低斯与其郊野，大比拉与其郊野，'),
('CUV', '历代志上', 13, 6, 73, '拉末与其郊野，亚年与其郊野；'),
('CUV', '历代志上', 13, 6, 74, '在亚设支派的地中得了玛沙与其郊野，押顿与其郊野，'),
('CUV', '历代志上', 13, 6, 75, '户割与其郊野，利合与其郊野；'),
('CUV', '历代志上', 13, 6, 76, '在拿弗他利支派的地中得了加利利的基低斯与其郊野，哈们与其郊野，基列亭与其郊野。'),
('CUV', '历代志上', 13, 6, 77, '还有米拉利族的人在西布伦支派的地中得了临摩挪与其郊野，他泊与其郊野；'),
('CUV', '历代志上', 13, 6, 78, '又在耶利哥的约但河东，在流便支派的地中得了旷野的比悉与其郊野，雅哈撒与其郊野，'),
('CUV', '历代志上', 13, 6, 79, '基底莫与其郊野，米法押与其郊野；'),
('CUV', '历代志上', 13, 6, 80, '又在迦得支派的地中得了基列的拉末与其郊野，玛哈念与其郊野，'),
('CUV', '历代志上', 13, 6, 81, '希实本与其郊野，雅谢与其郊野。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 7, 1, '以萨迦的儿子是陀拉、普瓦、雅述(创四六13是约伯)、伸仑，共四人。'),
('CUV', '历代志上', 13, 7, 2, '陀拉的儿子是乌西、利法雅、耶勒、雅买、易伯散、示母利，都是陀拉的族长，是大能的勇士。到大卫年间，他们的人数共有二万二千六百名。'),
('CUV', '历代志上', 13, 7, 3, '乌西的儿子是伊斯拉希；伊斯拉希的儿子是米迦勒、俄巴底亚、约珥、伊示雅，共五人，都是族长。'),
('CUV', '历代志上', 13, 7, 4, '他们所率领的，按著宗族出战的军队，共有三万六千人，因为他们的妻和子众多。'),
('CUV', '历代志上', 13, 7, 5, '他们的族弟兄在以萨迦各族中都是大能的勇士，按著家谱计算共有八万七千人。'),
('CUV', '历代志上', 13, 7, 6, '便雅悯的儿子是比拉、比结、耶叠，共三人。'),
('CUV', '历代志上', 13, 7, 7, '比拉的儿子是以斯本、乌西、乌薛、耶利摩、以利，共五人，都是族长，是大能的勇士。按著家谱计算，他们的子孙共有二万二千零三十四人。'),
('CUV', '历代志上', 13, 7, 8, '比结的儿子是细米拉、约阿施、以利以谢、以利约乃、暗利、耶利摩、亚比雅、亚拿突、亚拉篾。这都是比结的儿子。'),
('CUV', '历代志上', 13, 7, 9, '他们都是族长，是大能的勇士。按著家谱计算，他们的子孙共有二万零二百人。'),
('CUV', '历代志上', 13, 7, 10, '耶叠的儿子是比勒罕；比勒罕的儿子是耶乌施、便雅悯、以忽、基拿拿、细坦、他施、亚希沙哈。'),
('CUV', '历代志上', 13, 7, 11, '这都是耶叠的儿子，都是族长，是大能的勇士；他们的子孙能上阵打仗的，共有一万七千二百人。'),
('CUV', '历代志上', 13, 7, 12, '还有以珥的儿子书品、户品，并亚黑的儿子户伸。'),
('CUV', '历代志上', 13, 7, 13, '拿弗他利的儿子是雅薛、沽尼、耶色、沙龙。这都是辟拉的子孙。'),
('CUV', '历代志上', 13, 7, 14, '玛拿西的儿子亚斯列是他妾亚兰人所生的，又生了基列之父玛吉。'),
('CUV', '历代志上', 13, 7, 15, '玛吉娶的妻是户品、书品的妹子，名叫玛迦。玛拿西的次子名叫西罗非哈；西罗非哈但有几个女儿。'),
('CUV', '历代志上', 13, 7, 16, '玛吉的妻玛迦生了一个儿子，起名叫毗利施。毗利施的兄弟名叫示利施；示利施的儿子是乌兰和利金。'),
('CUV', '历代志上', 13, 7, 17, '乌兰的儿子是比但。这都是基列的子孙。基列是玛吉的儿子，玛吉是玛拿西的儿子。'),
('CUV', '历代志上', 13, 7, 18, '基列的妹子哈摩利吉生了伊施荷、亚比以谢、玛拉。'),
('CUV', '历代志上', 13, 7, 19, '〈示米大的儿子是亚现、示剑、利克希、阿尼安。〉'),
('CUV', '历代志上', 13, 7, 20, '以法莲的儿子是书提拉；书提拉的儿子是比列；比列的儿子是他哈；他哈的儿子是以拉大；以拉大的儿子是他哈；'),
('CUV', '历代志上', 13, 7, 21, '他哈的儿子是撒拔；撒拔的儿子是书提拉。以法莲又生以谢、以列；这二人因为下去夺取迦特人的牲畜，被本地的迦特人杀了。'),
('CUV', '历代志上', 13, 7, 22, '他们的父亲以法莲为他们悲哀了多日，他的弟兄都来安慰他。'),
('CUV', '历代志上', 13, 7, 23, '以法莲与妻同房，他妻就怀孕生了一子，以法莲因为家里遭祸，就给这儿子起名叫比利亚。'),
('CUV', '历代志上', 13, 7, 24, '他的女儿名叫舍伊拉，就是建筑上伯和仑、下伯和仑与乌羡舍伊拉的。'),
('CUV', '历代志上', 13, 7, 25, '比利阿的儿子是利法和利悉。利悉的儿子是他拉；他拉的儿子是他罕；'),
('CUV', '历代志上', 13, 7, 26, '他罕的儿子是拉但；拉但的儿子是亚米忽；亚米忽的儿子是以利沙玛；'),
('CUV', '历代志上', 13, 7, 27, '以利沙玛的儿子是嫩；嫩的儿子是约书亚。'),
('CUV', '历代志上', 13, 7, 28, '以法莲人的地业和住处是伯特利与其村庄；东边拿兰，西边基色与其村庄；示剑与其村庄，直到迦萨与其村庄；'),
('CUV', '历代志上', 13, 7, 29, '还有靠近玛拿西人的境界，伯善与其村庄；他纳与其村庄；米吉多与其村庄；多珥与其村庄。以色列儿子约瑟的子孙住在这些地方。'),
('CUV', '历代志上', 13, 7, 30, '亚设的儿子是音拿、亦施瓦、亦施韦、比利亚，还有他们的妹子西拉。'),
('CUV', '历代志上', 13, 7, 31, '比利亚的儿子是希别、玛结；玛结是比撒威的父亲。'),
('CUV', '历代志上', 13, 7, 32, '希别生雅弗勒、朔默、何坦，和他们的妹子书雅。'),
('CUV', '历代志上', 13, 7, 33, '雅弗勒的儿子是巴萨、宾哈、亚施法。这都是雅弗勒的儿子。'),
('CUV', '历代志上', 13, 7, 34, '朔默的儿子是亚希、罗迦、耶户巴、亚兰。'),
('CUV', '历代志上', 13, 7, 35, '朔默兄弟希连的儿子是琐法、音那、示利斯、亚抹。'),
('CUV', '历代志上', 13, 7, 36, '琐法的儿子是书亚、哈尼弗、书阿勒、比利、音拉、'),
('CUV', '历代志上', 13, 7, 37, '比悉、河得、珊玛、施沙、益兰、比拉。'),
('CUV', '历代志上', 13, 7, 38, '益帖的儿子是耶孚尼、毗斯巴、亚拉。'),
('CUV', '历代志上', 13, 7, 39, '乌拉的儿子是亚拉、汉尼业、利写。'),
('CUV', '历代志上', 13, 7, 40, '这都是亚设的子孙，都是族长，是精壮大能的勇士，也是首领中的头目，按著家谱计算，他们的子孙能出战的共有二万六千人。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 8, 1, '便雅悯的长子比拉，次子亚实别，三子亚哈拉，'),
('CUV', '历代志上', 13, 8, 2, '四子挪哈，五子拉法。'),
('CUV', '历代志上', 13, 8, 3, '比拉的儿子是亚大、基拉、亚比忽、'),
('CUV', '历代志上', 13, 8, 4, '亚比书、乃幔、亚何亚、'),
('CUV', '历代志上', 13, 8, 5, '基拉、示孚汛、户兰。'),
('CUV', '历代志上', 13, 8, 6, '以忽的儿子作迦巴居民的族长，被掳到玛拿辖；'),
('CUV', '历代志上', 13, 8, 7, '以忽的儿子乃幔、亚希亚、基拉也被掳去。基拉生乌撒、亚希忽。'),
('CUV', '历代志上', 13, 8, 8, '沙哈连休他二妻户伸和巴拉之后，在摩押地生了儿子。'),
('CUV', '历代志上', 13, 8, 9, '他与妻贺得同房，生了约巴、洗比雅、米沙、玛拉干、'),
('CUV', '历代志上', 13, 8, 10, '耶乌斯、沙迦、米玛。他这些儿子都是族长。'),
('CUV', '历代志上', 13, 8, 11, '他的妻户伸给他生的儿子有亚比突、以利巴力。'),
('CUV', '历代志上', 13, 8, 12, '以利巴力的儿子是希伯、米珊、沙麦。沙麦建立阿挪和罗德二城与其村庄。'),
('CUV', '历代志上', 13, 8, 13, '又有比利亚和示玛是亚雅仑居民的族长，是驱逐迦特人的。'),
('CUV', '历代志上', 13, 8, 14, '亚希约、沙煞、耶利末、'),
('CUV', '历代志上', 13, 8, 15, '西巴第雅、亚拉得、亚得、'),
('CUV', '历代志上', 13, 8, 16, '米迦勒、伊施巴、约哈都是比利亚的儿子。'),
('CUV', '历代志上', 13, 8, 17, '西巴第雅、米书兰、希西基、希伯、'),
('CUV', '历代志上', 13, 8, 18, '伊施米莱、伊斯利亚、约巴都是以利巴力的儿子。'),
('CUV', '历代志上', 13, 8, 19, '雅金、细基利、撒底、'),
('CUV', '历代志上', 13, 8, 20, '以利乃、洗勒太、以列、'),
('CUV', '历代志上', 13, 8, 21, '亚大雅、比拉雅、申拉都是示每的儿子。'),
('CUV', '历代志上', 13, 8, 22, '伊施班、希伯、以列、'),
('CUV', '历代志上', 13, 8, 23, '亚伯顿、细基利、哈难、'),
('CUV', '历代志上', 13, 8, 24, '哈拿尼雅、以拦、安陀提雅、'),
('CUV', '历代志上', 13, 8, 25, '伊弗底雅、毗努伊勒都是沙煞的儿子。'),
('CUV', '历代志上', 13, 8, 26, '珊示莱、示哈利、亚他利雅、'),
('CUV', '历代志上', 13, 8, 27, '雅利西、以利亚、细基利都是耶罗罕的儿子。'),
('CUV', '历代志上', 13, 8, 28, '这些人都是著名的族长，住在耶路撒冷。'),
('CUV', '历代志上', 13, 8, 29, '在基遍住的有基遍的父亲耶利。他的妻名叫玛迦；'),
('CUV', '历代志上', 13, 8, 30, '他长子是亚伯顿。他又生苏珥、基士、巴力、拿答、'),
('CUV', '历代志上', 13, 8, 31, '基多、亚希约、撒迦、米基罗。'),
('CUV', '历代志上', 13, 8, 32, '米基罗生示米暗。这些人和他们的弟兄在耶路撒冷对面居住。'),
('CUV', '历代志上', 13, 8, 33, '尼珥生基士；基士生扫罗；扫罗生约拿单、麦基舒亚、亚比拿达、伊施巴力。'),
('CUV', '历代志上', 13, 8, 34, '约拿单的儿子是米力巴力(撒下四章四节作米非波设)；米力巴力生米迦。'),
('CUV', '历代志上', 13, 8, 35, '米迦的儿子是毗敦、米勒、他利亚、亚哈斯；'),
('CUV', '历代志上', 13, 8, 36, '亚哈斯生耶何阿达；耶何阿达生亚拉篾、亚斯玛威、心利；心利生摩撒；'),
('CUV', '历代志上', 13, 8, 37, '摩撒生比尼亚；比尼亚的儿子是拉法；拉法的儿子是以利亚萨；以利亚萨的儿子是亚悉。'),
('CUV', '历代志上', 13, 8, 38, '亚悉有六个儿子，他们的名字是亚斯利干、波基路、以实玛利、示亚利雅、俄巴底雅、哈难。这都是亚悉的儿子。'),
('CUV', '历代志上', 13, 8, 39, '亚悉兄弟以设的长子是乌兰，次子耶乌施，三子是以利法列。'),
('CUV', '历代志上', 13, 8, 40, '乌兰的儿子都是大能的勇士，是弓箭手，他们有许多的子孙，共一百五十名，都是便雅悯人。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 9, 1, '以色列人都按家谱计算，写在以色列诸王记上。犹大人因犯罪就被掳到巴比伦。'),
('CUV', '历代志上', 13, 9, 2, '先从巴比伦回来，住在自己地业城邑中的有以色列人、祭司、利未人、尼提宁的首领。'),
('CUV', '历代志上', 13, 9, 3, '住在耶路撒冷的有犹大人、便雅悯人、以法莲人、玛拿西人。'),
('CUV', '历代志上', 13, 9, 4, '犹大儿子法勒斯的子孙中有乌太。乌太是亚米忽的儿子；亚米忽是暗利的儿子；暗利是音利的儿子；音利是巴尼的儿子。'),
('CUV', '历代志上', 13, 9, 5, '示罗的子孙中有长子亚帅雅和他的众子。'),
('CUV', '历代志上', 13, 9, 6, '谢拉的子孙中有耶乌利和他的弟兄，共六百九十人。'),
('CUV', '历代志上', 13, 9, 7, '便雅悯人中有哈西努的曾孙、何达威雅的孙子、米书兰的儿子撒路，'),
('CUV', '历代志上', 13, 9, 8, '又有耶罗罕的儿子伊比尼雅，米基立的孙子、乌西的儿子以拉，伊比尼雅的曾孙、流珥的孙子、示法提雅的儿子米书兰，'),
('CUV', '历代志上', 13, 9, 9, '和他们的族弟兄，按著家谱计算共有九百五十六名。这些人都是他们的族长。'),
('CUV', '历代志上', 13, 9, 10, '祭司中有耶大雅、耶何雅立、雅斤，'),
('CUV', '历代志上', 13, 9, 11, '还有管理神殿希勒家的儿子亚萨利雅。希勒家是米书兰的儿子；米书兰是撒督的儿子；撒督是米拉约的儿子；米拉约是亚希突的儿子。'),
('CUV', '历代志上', 13, 9, 12, '有玛基雅的曾孙、巴施户珥的孙子、耶罗罕的儿子亚大雅，又有亚第业的儿子玛赛；亚第业是雅希细拉的儿子；雅希细拉是米书兰的儿子；米书兰是米实利密的儿子；米实利密是音麦的儿子。'),
('CUV', '历代志上', 13, 9, 13, '他们和众弟兄都是族长，共有一千七百六十人，是善于做神殿使用之工的。'),
('CUV', '历代志上', 13, 9, 14, '利未人米拉利的子孙中，有哈沙比雅的曾孙、押利甘的孙子、哈述的儿子示玛雅。'),
('CUV', '历代志上', 13, 9, 15, '有拔巴甲、黑勒施、迦拉，并亚萨的曾孙、细基利的孙子、米迦的儿子玛探雅，'),
('CUV', '历代志上', 13, 9, 16, '又有耶杜顿的曾孙、迦拉的孙子、示玛雅的儿子俄巴底，还有以利加拿的孙子、亚撒的儿子比利家。他们都住在尼陀法人的村庄。'),
('CUV', '历代志上', 13, 9, 17, '守门的是沙龙、亚谷、达们、亚希幔，和他们的弟兄；沙龙为长。'),
('CUV', '历代志上', 13, 9, 18, '从前这些人看守朝东的王门，如今是利未营中守门的。'),
('CUV', '历代志上', 13, 9, 19, '可拉的曾孙、以比雅撒的孙子、可利的儿子沙龙，和他的族弟兄可拉人都管理使用之工，并守会幕的门。他们的祖宗曾管理耶和华的营盘，又把守营门。'),
('CUV', '历代志上', 13, 9, 20, '从前以利亚撒的儿子非尼哈管理他们，耶和华也与他同在。'),
('CUV', '历代志上', 13, 9, 21, '米施利米雅的儿子撒迦利雅是看守会幕之门的。'),
('CUV', '历代志上', 13, 9, 22, '被选守门的人共有二百一十二名。他们在自己的村庄，按著家谱计算，是大卫和先见撒母耳所派当这紧要职任的。'),
('CUV', '历代志上', 13, 9, 23, '他们和他们的子孙按著班次看守耶和华殿的门，就是会幕的门。'),
('CUV', '历代志上', 13, 9, 24, '在东西南北，四方都有守门的。'),
('CUV', '历代志上', 13, 9, 25, '他们的族弟兄住在村庄，每七日来与他们换班。'),
('CUV', '历代志上', 13, 9, 26, '这四个门领都是利未人，各有紧要的职任，看守神殿的仓库。'),
('CUV', '历代志上', 13, 9, 27, '他们住在神殿的四围，是因委托他们守殿，要每日早晨开门。'),
('CUV', '历代志上', 13, 9, 28, '利未人中有管理使用器皿的，按著数目拿出拿入；'),
('CUV', '历代志上', 13, 9, 29, '又有人管理器具和圣所的器皿，并细面、酒、油、乳香、香料。'),
('CUV', '历代志上', 13, 9, 30, '祭司中有人用香料做膏油。'),
('CUV', '历代志上', 13, 9, 31, '利未人玛他提雅是可拉族沙龙的长子，他紧要的职任是管理盘中烤的物。'),
('CUV', '历代志上', 13, 9, 32, '他们族弟兄哥辖子孙中，有管理陈设饼的，每安息日预备摆列。'),
('CUV', '历代志上', 13, 9, 33, '歌唱的有利未人的族长，住在属殿的房屋，昼夜供职，不做别样的工。'),
('CUV', '历代志上', 13, 9, 34, '以上都是利未人著名的族长，住在耶路撒冷。'),
('CUV', '历代志上', 13, 9, 35, '在基遍住的有基遍的父亲耶利。他的妻名叫玛迦；'),
('CUV', '历代志上', 13, 9, 36, '他长子是亚伯顿。他又生苏珥、基士、巴力、尼珥、拿答、'),
('CUV', '历代志上', 13, 9, 37, '基多、亚希约、撒迦利雅、米基罗。'),
('CUV', '历代志上', 13, 9, 38, '米基罗生示米暗。这些人和他们的弟兄在耶路撒冷对面居住。'),
('CUV', '历代志上', 13, 9, 39, '尼珥生基士；基士生扫罗；扫罗生约拿单、麦基舒亚、亚比拿达、伊施巴力。'),
('CUV', '历代志上', 13, 9, 40, '约拿单的儿子是米力巴力(即米非波设)；米力巴力生米迦。'),
('CUV', '历代志上', 13, 9, 41, '米迦的儿子是毗敦、米勒、他利亚、亚哈斯。'),
('CUV', '历代志上', 13, 9, 42, '亚哈斯生雅拉；雅拉生亚拉篾、亚斯玛威、心利；心利生摩撒；'),
('CUV', '历代志上', 13, 9, 43, '摩撒生比尼亚；比尼亚生利法雅；利法雅的儿子是以利亚萨；以利亚萨的儿子是亚悉。'),
('CUV', '历代志上', 13, 9, 44, '亚悉有六个儿子，他们的名字是亚斯利干、波基路、以实玛利、示亚利雅、俄巴底雅、哈难。这都是亚悉的儿子。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 10, 1, '非利士人与以色列人争战，以色列人在非利士人面前逃跑，在基利波山有被杀仆倒的。'),
('CUV', '历代志上', 13, 10, 2, '非利士人紧追扫罗和他儿子们，就杀了扫罗的儿子约拿单、亚比拿达、麦基舒亚。'),
('CUV', '历代志上', 13, 10, 3, '势派甚大，扫罗被弓箭手追上，射伤甚重，'),
('CUV', '历代志上', 13, 10, 4, '就吩咐拿他兵器的人说：你拔出刀来，将我刺死，免得那些未受割礼的人来凌辱我。但拿兵器的人甚惧怕，不肯刺他；'),
('CUV', '历代志上', 13, 10, 5, '扫罗就自己伏在刀上死了。拿兵器的人见扫罗已死，也伏在刀上死了。'),
('CUV', '历代志上', 13, 10, 6, '这样，扫罗和他三个儿子，并他的全家都一同死亡。'),
('CUV', '历代志上', 13, 10, 7, '住平原的以色列众人见以色列军兵逃跑，扫罗和他儿子都死了，也就弃城逃跑，非利士人便来住在其中。'),
('CUV', '历代志上', 13, 10, 8, '次日，非利士人来剥那被杀之人的衣服，看见扫罗和他儿子仆倒在基利波山，'),
('CUV', '历代志上', 13, 10, 9, '就剥了他的军装，割下他的首级，打发人到(或作送到)非利士地的四境报信与他们的偶像和众民，'),
('CUV', '历代志上', 13, 10, 10, '又将扫罗的军装放在他们神的庙里，将他的首级钉在大衮庙中。'),
('CUV', '历代志上', 13, 10, 11, '基列雅比人听见非利士人向扫罗所行的一切事，'),
('CUV', '历代志上', 13, 10, 12, '他们中间所有的勇士就起身前去，将扫罗和他儿子的尸身送到雅比，将他们的尸骨葬在雅比的橡树下，就禁食七日。'),
('CUV', '历代志上', 13, 10, 13, '这样，扫罗死了。因为他干犯耶和华，没有遵守耶和华的命；又因他求问交鬼的妇人，'),
('CUV', '历代志上', 13, 10, 14, '没有求问耶和华，所以耶和华使他被杀，把国归于耶西的儿子大卫。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 11, 1, '以色列众人聚集到希伯仑见大卫，说：我们原是你的骨肉。'),
('CUV', '历代志上', 13, 11, 2, '从前扫罗作王的时候，率领以色列人出入的是你；耶和华─你的神也曾应许你说：你必牧养我的民以色列，作以色列的君。'),
('CUV', '历代志上', 13, 11, 3, '于是以色列的长老都来到希伯仑见大卫王。大卫在希伯仑耶和华面前与他们立约，他们就膏大卫作以色列的王，是照耶和华藉撒母耳所说的话。'),
('CUV', '历代志上', 13, 11, 4, '大卫和以色列众人到了耶路撒冷，就是耶布斯；那时耶布斯人住在那里。'),
('CUV', '历代志上', 13, 11, 5, '耶布斯人对大卫说：你决不能进这地方。然而大卫攻取锡安的保障，就是大卫的城。'),
('CUV', '历代志上', 13, 11, 6, '大卫说：谁先攻打耶布斯人，必作首领元帅。洗鲁雅的儿子约押先上去，就作了元帅。'),
('CUV', '历代志上', 13, 11, 7, '大卫住在保障里，所以那保障叫作大卫城。'),
('CUV', '历代志上', 13, 11, 8, '大卫又从米罗起，四围建筑城墙，其余的是约押修理。'),
('CUV', '历代志上', 13, 11, 9, '大卫日见强盛，因为万军之耶和华与他同在。'),
('CUV', '历代志上', 13, 11, 10, '以下记录跟随大卫勇士的首领，就是奋勇帮助他得国、照著耶和华吩咐以色列人的话、与以色列人一同立他作王的。'),
('CUV', '历代志上', 13, 11, 11, '大卫勇士的数目记在下面：哈革摩尼的儿子雅朔班，他是军长的统领，一时举枪杀了三百人。'),
('CUV', '历代志上', 13, 11, 12, '其次是亚合人犰多的儿子以利亚撒，他是三个勇士里的一个。'),
('CUV', '历代志上', 13, 11, 13, '他从前与大卫在巴斯达闵，非利士人聚集要打仗。那里有一块长满大麦的田，众民就在非利士人面前逃跑；'),
('CUV', '历代志上', 13, 11, 14, '这勇士便站在那田间击杀非利士人，救护了那田。耶和华使以色列人大获全胜。'),
('CUV', '历代志上', 13, 11, 15, '三十个勇士中的三个人下到磐石那里，进了亚杜兰洞见大卫；非利士的军队在利乏音谷安营。'),
('CUV', '历代志上', 13, 11, 16, '那时大卫在山寨，非利士人的防营在伯利恒。'),
('CUV', '历代志上', 13, 11, 17, '大卫渴想，说：甚愿有人将伯利恒城门旁井里的水打来给我喝！'),
('CUV', '历代志上', 13, 11, 18, '这三个勇士就闯过非利士人的营盘，从伯利恒城门旁的井里打水，拿来奉给大卫。他却不肯喝，将水奠在耶和华面前，'),
('CUV', '历代志上', 13, 11, 19, '说：我的神啊，这三个人冒死去打水，这水好像他们的血一般，我断不敢喝！如此，大卫不肯喝。这是三个勇士所做的事。'),
('CUV', '历代志上', 13, 11, 20, '约押的兄弟亚比筛是这三个勇士的首领；他举枪杀了三百人，就在三个勇士里得了名。'),
('CUV', '历代志上', 13, 11, 21, '他在这三个勇士里是最尊贵的，所以作他们的首领；只是不及前三个勇士。'),
('CUV', '历代志上', 13, 11, 22, '有甲薛勇士耶何耶大的儿子比拿雅行过大能的事：他杀了摩押人亚利伊勒的两个儿子，又在下雪的时候下坑里去杀了一个狮子，'),
('CUV', '历代志上', 13, 11, 23, '又杀了一个埃及人。埃及人身高五肘，手里拿著枪，枪杆粗如织布的机轴；比拿雅只拿著棍子下去，从埃及人手里夺过枪来，用那枪将他刺死。'),
('CUV', '历代志上', 13, 11, 24, '这是耶何耶大的儿子比拿雅所行的事，就在三个勇士里得了名。'),
('CUV', '历代志上', 13, 11, 25, '他比那三十个勇士都尊贵，只是不及前三个勇士。大卫立他作护卫长。'),
('CUV', '历代志上', 13, 11, 26, '军中的勇士有约押的兄弟亚撒黑，伯利恒人朵多的儿子伊勒哈难，'),
('CUV', '历代志上', 13, 11, 27, '哈律人沙玛，比伦人希利斯，'),
('CUV', '历代志上', 13, 11, 28, '提哥亚人益吉的儿子以拉，亚拿突人亚比以谢，'),
('CUV', '历代志上', 13, 11, 29, '户沙人西比该，亚合人以来，'),
('CUV', '历代志上', 13, 11, 30, '尼陀法人玛哈莱，尼陀法人巴拿的儿子希立，'),
('CUV', '历代志上', 13, 11, 31, '便雅悯族基比亚人利拜的儿子以太，比拉顿人比拿雅，'),
('CUV', '历代志上', 13, 11, 32, '迦实溪人户莱，亚拉巴人亚比，'),
('CUV', '历代志上', 13, 11, 33, '巴路米人押斯玛弗，沙本人以利雅哈巴，'),
('CUV', '历代志上', 13, 11, 34, '基孙人哈深的众子，哈拉人沙基的儿子约拿单，'),
('CUV', '历代志上', 13, 11, 35, '哈拉人沙甲的儿子亚希暗，吾珥的儿子以利法勒，'),
('CUV', '历代志上', 13, 11, 36, '米基拉人希弗，比伦人亚希雅，'),
('CUV', '历代志上', 13, 11, 37, '迦密人希斯罗，伊斯拜的儿子拿莱，'),
('CUV', '历代志上', 13, 11, 38, '拿单的兄弟约珥，哈基利的儿子弥伯哈，'),
('CUV', '历代志上', 13, 11, 39, '亚扪人洗勒，比录人拿哈莱〈拿哈莱是给洗鲁雅的儿子约押拿兵器的〉，'),
('CUV', '历代志上', 13, 11, 40, '以帖人以拉，以帖人迦立，'),
('CUV', '历代志上', 13, 11, 41, '赫人乌利亚，亚莱的儿子撒拔，'),
('CUV', '历代志上', 13, 11, 42, '流便人示撒的儿子亚第拿〈他是流便支派中的一个族长，率领三十人〉，'),
('CUV', '历代志上', 13, 11, 43, '玛迦的儿子哈难，弥特尼人约沙法，'),
('CUV', '历代志上', 13, 11, 44, '亚施他拉人乌西亚，亚罗珥人何坦的儿子沙玛、耶利，'),
('CUV', '历代志上', 13, 11, 45, '提洗人申利的儿子耶叠和他的兄弟约哈，'),
('CUV', '历代志上', 13, 11, 46, '玛哈未人以利业，伊利拿安的儿子耶利拜、约沙未雅，摩押人伊特玛、'),
('CUV', '历代志上', 13, 11, 47, '以利业、俄备得，并米琐八人雅西业。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 12, 1, '大卫因怕基士的儿子扫罗，躲在洗革拉的时候，有勇士到他那里帮助他打仗。'),
('CUV', '历代志上', 13, 12, 2, '他们善于拉弓，能用左右两手甩石射箭，都是便雅悯人扫罗的族弟兄。'),
('CUV', '历代志上', 13, 12, 3, '为首的是亚希以谢，其次是约阿施，都是基比亚人示玛的儿子。还有亚斯玛威的儿子耶薛和毗力，又有比拉迦，并亚拿突人耶户，'),
('CUV', '历代志上', 13, 12, 4, '基遍人以实买雅〈他在三十人中是勇士，管理他们〉，且有耶利米、雅哈悉、约哈难，和基得拉人约撒拔、'),
('CUV', '历代志上', 13, 12, 5, '伊利乌赛、耶利摩、比亚利雅、示玛利雅，哈律弗人示法提雅，'),
('CUV', '历代志上', 13, 12, 6, '可拉人以利加拿、耶西亚、亚萨列、约以谢、雅朔班，'),
('CUV', '历代志上', 13, 12, 7, '基多人耶罗罕的儿子犹拉和西巴第雅。'),
('CUV', '历代志上', 13, 12, 8, '迦得支派中有人到旷野的山寨投奔大卫，都是大能的勇士，能拿盾牌和枪的战士。他们的面貌好像狮子，快跑如同山上的鹿。'),
('CUV', '历代志上', 13, 12, 9, '第一以薛，第二俄巴底雅，第三以利押，'),
('CUV', '历代志上', 13, 12, 10, '第四弥施玛拿，第五耶利米，'),
('CUV', '历代志上', 13, 12, 11, '第六亚太，第七以利业，'),
('CUV', '历代志上', 13, 12, 12, '第八约哈难，第九以利萨巴，'),
('CUV', '历代志上', 13, 12, 13, '第十耶利米，第十一末巴奈。'),
('CUV', '历代志上', 13, 12, 14, '这都是迦得人中的军长，至小的能抵一百人，至大的能抵一千人。'),
('CUV', '历代志上', 13, 12, 15, '正月，约但河水涨过两岸的时候，他们过河，使一切住平原的人东奔西逃。'),
('CUV', '历代志上', 13, 12, 16, '又有便雅悯和犹大人到山寨大卫那里。'),
('CUV', '历代志上', 13, 12, 17, '大卫出去迎接他们，对他们说：你们若是和和平平地来帮助我，我心就与你们相契；你们若是将我这无罪的人卖在敌人手里，愿我们列祖的神察看责罚。'),
('CUV', '历代志上', 13, 12, 18, '那时神的灵感动那三十个勇士的首领亚玛撒，他就说：大卫啊，我们是归于你的！耶西的儿子啊，我们是帮助你的！愿你平平安安，愿帮助你的也都平安！因为你的神帮助你。大卫就收留他们，立他们作军长。'),
('CUV', '历代志上', 13, 12, 19, '大卫从前与非利士人同去，要与扫罗争战，有些玛拿西人来投奔大卫，他们却没有帮助非利士人；因为非利士人的首领商议，打发他们回去，说：恐怕大卫拿我们的首级，归降他的主人扫罗。'),
('CUV', '历代志上', 13, 12, 20, '大卫往洗革拉去的时候，有玛拿西人的千夫长押拿、约撒拔、耶叠、米迦勒、约撒拔、以利户、洗勒太都来投奔他。'),
('CUV', '历代志上', 13, 12, 21, '这些人帮助大卫攻击群贼；他们都是大能的勇士，且作军长。'),
('CUV', '历代志上', 13, 12, 22, '那时天天有人来帮助大卫，以致成了大军，如神的军一样。'),
('CUV', '历代志上', 13, 12, 23, '预备打仗的兵来到希伯仑见大卫，要照著耶和华的话将扫罗的国位归与大卫。他们的数目如下：'),
('CUV', '历代志上', 13, 12, 24, '犹大支派，拿盾牌和枪预备打仗的有六千八百人。'),
('CUV', '历代志上', 13, 12, 25, '西缅支派，能上阵大能的勇士有七千一百人。'),
('CUV', '历代志上', 13, 12, 26, '利未支派有四千六百人。'),
('CUV', '历代志上', 13, 12, 27, '耶何耶大是亚伦家的首领，跟从他的有三千七百人。'),
('CUV', '历代志上', 13, 12, 28, '还有少年大能的勇士撒督，同著他的有族长二十二人。'),
('CUV', '历代志上', 13, 12, 29, '便雅悯支派，扫罗的族弟兄也有三千人，他们向来大半归顺扫罗家。'),
('CUV', '历代志上', 13, 12, 30, '以法莲支派大能的勇士，在本族著名的有二万零八百人。'),
('CUV', '历代志上', 13, 12, 31, '玛拿西半支派，册上有名的共一万八千人，都来立大卫作王。'),
('CUV', '历代志上', 13, 12, 32, '以萨迦支派，有二百族长都通达时务，知道以色列人所当行的；他们族弟兄都听从他们的命令。'),
('CUV', '历代志上', 13, 12, 33, '西布伦支派，能上阵用各样兵器打仗、行伍整齐、不生二心的有五万人。'),
('CUV', '历代志上', 13, 12, 34, '拿弗他利支派，有一千军长；跟从他们、拿盾牌和枪的有三万七千人。'),
('CUV', '历代志上', 13, 12, 35, '但支派，能摆阵的有二万八千六百人。'),
('CUV', '历代志上', 13, 12, 36, '亚设支派，能上阵打仗的有四万人。'),
('CUV', '历代志上', 13, 12, 37, '约但河东的流便支派、迦得支派、玛拿西半支派，拿著各样兵器打仗的有十二万人。'),
('CUV', '历代志上', 13, 12, 38, '以上都是能守行伍的战士，他们都诚心来到希伯仑，要立大卫作以色列的王。以色列其余的人也都一心要立大卫作王。'),
('CUV', '历代志上', 13, 12, 39, '他们在那里三日，与大卫一同吃喝，因为他们的族弟兄给他们预备了。'),
('CUV', '历代志上', 13, 12, 40, '靠近他们的人以及以萨迦、西布伦、拿弗他利人将许多面饼、无花果饼、干葡萄、酒、油，用驴、骆驼、骡子、牛驮来，又带了许多的牛和羊来，因为以色列人甚是欢乐。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 13, 1, '大卫与千夫长、百夫长，就是一切首领商议。'),
('CUV', '历代志上', 13, 13, 2, '大卫对以色列全会众说：你们若以为美，见这事是出于耶和华─我们的神，我们就差遣人走遍以色列地，见我们未来的弟兄，又见住在有郊野之城的祭司利未人，使他们都到这里来聚集。'),
('CUV', '历代志上', 13, 13, 3, '我们要把神的约柜运到我们这里来；因为在扫罗年间，我们没有在约柜前求问神。'),
('CUV', '历代志上', 13, 13, 4, '全会众都说可以如此行；这事在众民眼中都看为好。'),
('CUV', '历代志上', 13, 13, 5, '于是，大卫将以色列人从埃及的西曷河直到哈马口都招聚了来，要从基列耶琳将神的约柜运来。'),
('CUV', '历代志上', 13, 13, 6, '大卫率领以色列众人上到巴拉，就是属犹大的基列耶琳，要从那里将约柜运来。这约柜就是坐在二基路伯上耶和华神留名的约柜。'),
('CUV', '历代志上', 13, 13, 7, '他们将神的约柜从亚比拿达的家里抬出来，放在新车上。乌撒和亚希约赶车。'),
('CUV', '历代志上', 13, 13, 8, '大卫和以色列众人在神前用琴、瑟、锣、鼓、号作乐，极力跳舞歌唱。'),
('CUV', '历代志上', 13, 13, 9, '到了基顿(撒下六章六节作拿艮)的禾场；因为牛失前蹄(或作惊跳)，乌撒就伸手扶住约柜。'),
('CUV', '历代志上', 13, 13, 10, '耶和华向他发怒，因他伸手扶住约柜击杀他，他就死在神面前。'),
('CUV', '历代志上', 13, 13, 11, '大卫因耶和华击杀(原文作闯杀)乌撒，心里愁烦，就称那地方为毗列斯乌撒，直到今日。'),
('CUV', '历代志上', 13, 13, 12, '那日，大卫惧怕神，说：神的约柜怎可运到我这里来？'),
('CUV', '历代志上', 13, 13, 13, '于是大卫不将约柜运进大卫的城，却运到迦特人俄别以东的家中。'),
('CUV', '历代志上', 13, 13, 14, '神的约柜在俄别以东家中三个月，耶和华赐福给俄别以东的家和他一切所有的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 14, 1, '推罗王希兰将香柏木运到大卫那里，又差遣使者和石匠、木匠给大卫建造宫殿。'),
('CUV', '历代志上', 13, 14, 2, '大卫就知道耶和华坚立他作以色列王，又为自己的民以色列，使他的国兴旺。'),
('CUV', '历代志上', 13, 14, 3, '大卫在耶路撒冷又立后妃，又生儿女。'),
('CUV', '历代志上', 13, 14, 4, '在耶路撒冷所生的众子是沙母亚、朔罢、拿单、所罗门、'),
('CUV', '历代志上', 13, 14, 5, '益辖、以利书亚、以法列、'),
('CUV', '历代志上', 13, 14, 6, '挪迦、尼斐、雅非亚、'),
('CUV', '历代志上', 13, 14, 7, '以利沙玛、比利雅大、以利法列。'),
('CUV', '历代志上', 13, 14, 8, '非利士人听见大卫受膏作以色列众人的王，非利士众人就上来寻索大卫。大卫听见，就出去迎敌。'),
('CUV', '历代志上', 13, 14, 9, '非利士人来了，布散在利乏音谷。'),
('CUV', '历代志上', 13, 14, 10, '大卫求问神，说：我可以上去攻打非利士人么？你将他们交在我手里么？耶和华说：你可以上去，我必将他们交在你手里。'),
('CUV', '历代志上', 13, 14, 11, '非利士人来到巴力毗拉心，大卫在那里杀败他们。大卫说：神藉我的手冲破敌人，如同水冲去一般；因此称那地方为巴力毗拉心。'),
('CUV', '历代志上', 13, 14, 12, '非利士人将神像撇在那里，大卫吩咐人用火焚烧了。'),
('CUV', '历代志上', 13, 14, 13, '非利士人又布散在利乏音谷。'),
('CUV', '历代志上', 13, 14, 14, '大卫又求问神。神说：不要一直地上去，要转到他们后头，从桑林对面攻打他们。'),
('CUV', '历代志上', 13, 14, 15, '你听见桑树梢上有脚步的声音，就要出战，因为神已经在你前头去攻打非利士人的军队。'),
('CUV', '历代志上', 13, 14, 16, '大卫就遵著神所吩咐的，攻打非利士人的军队，从基遍直到基色。'),
('CUV', '历代志上', 13, 14, 17, '于是大卫的名传扬到列国，耶和华使列国都惧怕他。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 15, 1, '大卫在大卫城为自己建造宫殿，又为神的约柜预备地方，支搭帐幕。'),
('CUV', '历代志上', 13, 15, 2, '那时大卫说：除了利未人之外，无人可抬神的约柜；因为耶和华拣选他们抬神的约柜，且永远事奉他。'),
('CUV', '历代志上', 13, 15, 3, '大卫招聚以色列众人众人到耶路撒冷，要将耶和华的约柜抬到他所预备的地方。'),
('CUV', '历代志上', 13, 15, 4, '大卫又聚集亚伦的子孙和利未人。'),
('CUV', '历代志上', 13, 15, 5, '哥辖子孙中有族长乌列和他的弟兄一百二十人。'),
('CUV', '历代志上', 13, 15, 6, '米拉利子孙中有族长亚帅雅和他的弟兄二百二十人。'),
('CUV', '历代志上', 13, 15, 7, '革顺子孙中有族长约珥和他的弟兄一百三十人。'),
('CUV', '历代志上', 13, 15, 8, '以利撒反子孙中有族长示玛雅和他的弟兄二百人。'),
('CUV', '历代志上', 13, 15, 9, '希伯仑子孙中有族长以列和他的弟兄八十人。'),
('CUV', '历代志上', 13, 15, 10, '乌薛子孙中有族长亚米拿达和他的弟兄一百一十二人。'),
('CUV', '历代志上', 13, 15, 11, '大卫将祭司撒督和亚比亚他，并利未人乌列、亚帅雅、约珥、示玛雅、以列、亚米拿达召来，'),
('CUV', '历代志上', 13, 15, 12, '对他们说：你们是利未人的族长，你们和你们的弟兄应当自洁，好将耶和华─以色列神的约柜抬到我所预备的地方。'),
('CUV', '历代志上', 13, 15, 13, '因你们先前没有抬这约柜，按定例求问耶和华─我们的神，所以他刑罚(原文作闯杀)我们。'),
('CUV', '历代志上', 13, 15, 14, '于是祭司利未人自洁，好将耶和华─以色列神的约柜抬上来。'),
('CUV', '历代志上', 13, 15, 15, '利未子孙就用杠，肩抬神的约柜，是照耶和华藉摩西所吩咐的。'),
('CUV', '历代志上', 13, 15, 16, '大卫吩咐利未人的族长，派他们歌唱的弟兄用琴瑟和钹作乐，欢欢喜喜地大声歌颂。'),
('CUV', '历代志上', 13, 15, 17, '于是利未人派约珥的儿子希幔和他弟兄中比利家的儿子亚萨，并他们族弟兄米拉利子孙里古沙雅的儿子以探。'),
('CUV', '历代志上', 13, 15, 18, '其次还有他们的弟兄撒迦利雅、便雅薛、示米拉末、耶歇、乌尼、以利押、比拿雅、玛西雅、玛他提雅、以利斐利户、弥克尼雅，并守门的俄别以东和耶利。'),
('CUV', '历代志上', 13, 15, 19, '这样，派歌唱的希幔、亚萨、以探敲铜钹，大发响声；'),
('CUV', '历代志上', 13, 15, 20, '派撒迦利雅、雅薛、示米拉末、耶歇、乌尼、以利押、玛西雅、比拿雅鼓瑟，调用女音；'),
('CUV', '历代志上', 13, 15, 21, '又派玛他提雅、以利斐利户、弥克尼雅、俄别以东、耶利、亚撒西雅领首弹琴，调用第八。'),
('CUV', '历代志上', 13, 15, 22, '利未人的族长基拿尼雅是歌唱人的首领，又教训人歌唱，因为他精通此事。'),
('CUV', '历代志上', 13, 15, 23, '比利家、以利加拿是约柜前守门的。'),
('CUV', '历代志上', 13, 15, 24, '祭司示巴尼、约沙法、拿坦业、亚玛赛、撒迦利雅、比拿亚、以利以谢在神的约柜前吹号。俄别以东和耶希亚也是约柜前守门的。'),
('CUV', '历代志上', 13, 15, 25, '于是，大卫和以色列的长老，并千夫长都去从俄别以东的家欢欢喜喜地将耶和华的约柜抬上来。'),
('CUV', '历代志上', 13, 15, 26, '神赐恩与抬耶和华约柜的利未人，他们就献上七只公牛，七只公羊。'),
('CUV', '历代志上', 13, 15, 27, '大卫和抬约柜的利未人，并歌唱人的首领基拿尼雅，以及歌唱的人，都穿著细麻布的外袍；大卫另外穿著细麻布的以弗得。'),
('CUV', '历代志上', 13, 15, 28, '这样，以色列众人欢呼吹角、吹号、敲钹、鼓瑟、弹琴，大发响声，将耶和华的约柜抬上来。'),
('CUV', '历代志上', 13, 15, 29, '耶和华的约柜进了大卫城的时候，扫罗的女儿米甲从窗户里观看，见大卫王踊跃跳舞，心里就轻视他。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 16, 1, '众人将神的约柜请进去，安放在大卫所搭的帐幕里，就在神面前献燔祭和平安祭。'),
('CUV', '历代志上', 13, 16, 2, '大卫献完了燔祭和平安祭，就奉耶和华的名给民祝福，'),
('CUV', '历代志上', 13, 16, 3, '并且分给以色列人，无论男女，每人一个饼，一块肉，一个葡萄饼。'),
('CUV', '历代志上', 13, 16, 4, '大卫派几个利未人在耶和华的约柜前事奉，颂扬，称谢，赞美耶和华─以色列的神：'),
('CUV', '历代志上', 13, 16, 5, '为首的是亚萨，其次是撒迦利雅、雅薛、示米拉末、耶歇、玛他提雅、以利押、比拿雅、俄别以东、耶利，鼓瑟弹琴；惟有亚萨敲钹，大发响声；'),
('CUV', '历代志上', 13, 16, 6, '祭司比拿雅和雅哈悉常在神的约柜前吹号。'),
('CUV', '历代志上', 13, 16, 7, '那日，大卫初次藉亚萨和他的弟兄以诗歌称颂耶和华，说：'),
('CUV', '历代志上', 13, 16, 8, '你们要称谢耶和华，求告他的名，在万民中传扬他的作为！'),
('CUV', '历代志上', 13, 16, 9, '要向他唱诗、歌颂，谈论他一切奇妙的作为。'),
('CUV', '历代志上', 13, 16, 10, '要以他的圣名夸耀；寻求耶和华的人，心中应当欢喜。'),
('CUV', '历代志上', 13, 16, 11, '要寻求耶和华与他的能力，时常寻求他的面。'),
('CUV', '历代志上', 13, 16, 12, '他仆人以色列的后裔，他所拣选雅各的子孙哪，你们要记念他奇妙的作为和他的奇事，并他口中的判语。'),
('CUV', '历代志上', 13, 16, 13, 'a'),
('CUV', '历代志上', 13, 16, 14, '他是耶和华─我们的神，全地都有他的判断。'),
('CUV', '历代志上', 13, 16, 15, '你们要记念他的约，直到永远；他所吩咐的话，直到千代，'),
('CUV', '历代志上', 13, 16, 16, '就是与亚伯拉罕所立的约，向以撒所起的誓。'),
('CUV', '历代志上', 13, 16, 17, '他又将这约向雅各定为律例，向以色列定为永远的约，'),
('CUV', '历代志上', 13, 16, 18, '说：我必将迦南地赐给你，作你产业的分。'),
('CUV', '历代志上', 13, 16, 19, '当时你们人丁有限，数目稀少，并且在那地为寄居的；'),
('CUV', '历代志上', 13, 16, 20, '他们从这邦游到那邦，从这国行到那国。'),
('CUV', '历代志上', 13, 16, 21, '耶和华不容甚么人欺负他们，为他们的缘故责备君王，'),
('CUV', '历代志上', 13, 16, 22, '说：不可难为我受膏的人，也不可恶待我的先知！'),
('CUV', '历代志上', 13, 16, 23, '全地都要向耶和华歌唱！天天传扬他的救恩，'),
('CUV', '历代志上', 13, 16, 24, '在列邦中述说他的荣耀，在万民中述说他的奇事。'),
('CUV', '历代志上', 13, 16, 25, '因耶和华为大，当受极大的赞美；他在万神之上，当受敬畏。'),
('CUV', '历代志上', 13, 16, 26, '外邦的神都属虚无，惟独耶和华创造诸天。'),
('CUV', '历代志上', 13, 16, 27, '有尊荣和威严在他面前，有能力和喜乐在他圣所。'),
('CUV', '历代志上', 13, 16, 28, '民中的万族啊，你们要将荣耀能力归给耶和华，都归给耶和华！'),
('CUV', '历代志上', 13, 16, 29, '要将耶和华的名所当得的荣耀归给他，拿供物来奉到他面前；当以圣洁的(的或作为)妆饰敬拜耶和华。'),
('CUV', '历代志上', 13, 16, 30, '全地要在他面前战抖，世界也坚定不得动摇。'),
('CUV', '历代志上', 13, 16, 31, '愿天欢喜，愿地快乐；愿人在列邦中说：耶和华作王了'),
('CUV', '历代志上', 13, 16, 32, '愿海和其中所充满的澎湃；愿田和其中所有的都欢乐。'),
('CUV', '历代志上', 13, 16, 33, '那时，林中的树木都要在耶和华面前欢呼，因为他来要审判全地。'),
('CUV', '历代志上', 13, 16, 34, '应当称谢耶和华；因他本为善，他的慈爱永远长存！'),
('CUV', '历代志上', 13, 16, 35, '要说：拯救我们的神啊，求你救我们，聚集我们，使我们脱离外邦，我们好称赞你的圣名，以赞美你为夸胜。'),
('CUV', '历代志上', 13, 16, 36, '耶和华─以色列的神，从亘古直到永远，是应当称颂的！众民都说：阿们！并且赞美耶和华。'),
('CUV', '历代志上', 13, 16, 37, '大卫派亚萨和他的弟兄在约柜前常常事奉耶和华，一日尽一日的职分；'),
('CUV', '历代志上', 13, 16, 38, '又派俄别以东和他的弟兄六十八人，与耶杜顿的儿子俄别以东，并何萨作守门的；'),
('CUV', '历代志上', 13, 16, 39, '且派祭司撒督和他弟兄众祭司在基遍的邱坛、耶和华的帐幕前燔祭坛上，每日早晚，照著耶和华律法书上所吩咐以色列人的，常给耶和华献燔祭。'),
('CUV', '历代志上', 13, 16, 40, 'a'),
('CUV', '历代志上', 13, 16, 41, '与他们一同被派的有希幔、耶杜顿，和其余被选名字录在册上的，称谢耶和华，因他的慈爱永远长存。'),
('CUV', '历代志上', 13, 16, 42, '希幔、耶杜顿同著他们吹号、敲钹，大发响声，并用别的乐器随著歌颂神。耶杜顿的子孙作守门的。'),
('CUV', '历代志上', 13, 16, 43, '于是众民各归各家；大卫也回去为家眷祝福。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 17, 1, '大卫住在自己宫中，对先知拿单说：看哪，我住在香柏木的宫中，耶和华的约柜反在幔子里。'),
('CUV', '历代志上', 13, 17, 2, '拿单对大卫说：你可以照你的心意而行，因为神与你同在。'),
('CUV', '历代志上', 13, 17, 3, '当夜，神的话临到拿单，说：'),
('CUV', '历代志上', 13, 17, 4, '你去告诉我仆人大卫，说耶和华如此说：你不可建造殿宇给我居住。'),
('CUV', '历代志上', 13, 17, 5, '自从我领以色列人出埃及，直到今日，我未曾住过殿宇，乃从这会幕到那会幕，从这帐幕到那帐幕。'),
('CUV', '历代志上', 13, 17, 6, '凡我同以色列人所走的地方，我何曾向以色列的一个士师，就是我吩咐牧养我民的说：你为何不给我建造香柏木的殿宇呢？'),
('CUV', '历代志上', 13, 17, 7, '现在你要告诉我仆人大卫，说万军之耶和华如此说：我从羊圈中将你召来，叫你不再跟从羊群，立你作我民以色列的君。'),
('CUV', '历代志上', 13, 17, 8, '你无论往哪里去，我常与你同在，剪除你的一切仇敌；我必使你得大名，好像世上大大有名的人一样。'),
('CUV', '历代志上', 13, 17, 9, '我必为我民以色列选定一个地方，栽培他们，使他们住自己的地方，不再迁移；凶恶之子也不像从前扰害他们，'),
('CUV', '历代志上', 13, 17, 10, '并不像我命士师治理我民以色列的时候一样。我必治服你的一切仇敌，并且我─耶和华应许你，必为你建立家室。'),
('CUV', '历代志上', 13, 17, 11, '你寿数满足归你列祖的时候，我必使你的后裔接续你的位，我也必坚定他的国。'),
('CUV', '历代志上', 13, 17, 12, '他必为我建造殿宇；我必坚定他的国位直到永远。'),
('CUV', '历代志上', 13, 17, 13, '我要作他的父，他要作我的子；并不使我的慈爱离开他，像离开在你以前的扫罗一样。'),
('CUV', '历代志上', 13, 17, 14, '我却要将他永远坚立在我家里和我国里；他的国位也必坚定，直到永远。'),
('CUV', '历代志上', 13, 17, 15, '拿单就按这一切话，照这默示告诉大卫。'),
('CUV', '历代志上', 13, 17, 16, '于是大卫王进去，坐在耶和华面前，说：耶和华神啊，我是谁，我的家算甚么，你竟使我到这地步呢？'),
('CUV', '历代志上', 13, 17, 17, '神啊，这在你眼中还看为小，又应许你仆人的家至于久远。耶和华神啊，你看顾我好像看顾高贵的人。'),
('CUV', '历代志上', 13, 17, 18, '你加于仆人的尊荣，我还有何言可说呢？因为你知道你的仆人。'),
('CUV', '历代志上', 13, 17, 19, '耶和华啊，你行了这大事，并且显明出来，是因你仆人的缘故，也是照你的心意。'),
('CUV', '历代志上', 13, 17, 20, '耶和华啊，照我们耳中听见，没有可比你的，除你以外再无神。'),
('CUV', '历代志上', 13, 17, 21, '世上有何民能比你的民以色列呢？你神从埃及救赎他们作自己的子民，又在你赎出来的民面前行大而可畏的事，驱逐列邦人，显出你的大名。'),
('CUV', '历代志上', 13, 17, 22, '你使以色列人作你的子民，直到永远；你─耶和华也作他们的神。'),
('CUV', '历代志上', 13, 17, 23, '耶和华啊，你所应许仆人和仆人家的话，求你坚定，直到永远，照你所说的而行。'),
('CUV', '历代志上', 13, 17, 24, '愿你的名永远坚立，被尊为大，说：万军之耶和华是以色列的神，是治理以色列的神。这样，你仆人大卫的家必在你面前坚立。'),
('CUV', '历代志上', 13, 17, 25, '我的神啊，因你启示仆人说，我必为你建立家室，所以仆人大胆在你面前祈祷。'),
('CUV', '历代志上', 13, 17, 26, '耶和华啊，惟有你是神，你也应许将这福气赐给仆人。'),
('CUV', '历代志上', 13, 17, 27, '现在你喜悦赐福与仆人的家，可以永存在你面前。耶和华啊，你已经赐福，还要赐福到永远。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 18, 1, '此后，大卫攻打非利士人，把他们治服，从他们手下夺取了迦特和属迦特的村庄；'),
('CUV', '历代志上', 13, 18, 2, '又攻打摩押，摩押人就归服大卫，给他进贡。'),
('CUV', '历代志上', 13, 18, 3, '琐巴王哈大利谢(撒下八章三节作哈大底谢)往伯拉河去，要坚定自己的国权，大卫就攻打他，直到哈马，'),
('CUV', '历代志上', 13, 18, 4, '夺了他的战车一千，马兵七千，步兵二万，将拉战车的马砍断蹄筋，但留下一百辆车的马。'),
('CUV', '历代志上', 13, 18, 5, '大马色的亚兰人来帮助琐巴王哈大利谢，大卫就杀了亚兰人二万二千。'),
('CUV', '历代志上', 13, 18, 6, '于是大卫在大马色的亚兰地设立防营，亚兰人就归服他，给他进贡。大卫无论往哪里去，耶和华都使他得胜。'),
('CUV', '历代志上', 13, 18, 7, '他夺了哈大利谢臣仆所拿的金盾牌带到耶路撒冷。'),
('CUV', '历代志上', 13, 18, 8, '大卫又从属哈大利谢的提巴(或作比他)和均二城中夺取了许多的铜。后来所罗门用此制造铜海、铜柱，和一切的铜器。'),
('CUV', '历代志上', 13, 18, 9, '哈马王陀乌听见大卫杀败琐巴王哈大利谢的全军，'),
('CUV', '历代志上', 13, 18, 10, '就打发他儿子哈多兰去见大卫王，问他的安，为他祝福，因为他杀败了哈大利谢〈原来陀乌与哈大利谢常常争战〉。哈多兰带了金银铜的各样器皿来。'),
('CUV', '历代志上', 13, 18, 11, '大卫王将这些器皿，并从各国夺来的金银，就是从以东、摩押、亚扪、非利士、亚玛力人所夺来的，都分别为圣献给耶和华。'),
('CUV', '历代志上', 13, 18, 12, '洗鲁雅的儿子亚比筛在盐谷击杀了以东一万八千人。'),
('CUV', '历代志上', 13, 18, 13, '大卫在以东地设立防营，以东人就都归服他。大卫无论往哪里去，耶和华都使他得胜。'),
('CUV', '历代志上', 13, 18, 14, '大卫作以色列众人的王，又向众民秉公行义。'),
('CUV', '历代志上', 13, 18, 15, '洗鲁雅的儿子约押作元帅；亚希律的儿子约沙法作史官；'),
('CUV', '历代志上', 13, 18, 16, '亚希突的儿子撒督和亚比亚他的儿子亚希米勒作祭司长；沙威沙作书记；'),
('CUV', '历代志上', 13, 18, 17, '耶何耶大的儿子比拿雅统辖基利提人和比利提人。大卫的众子都在王的左右作领袖。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 19, 1, '此后，亚扪人的王拿辖死了，他儿子接续他作王。'),
('CUV', '历代志上', 13, 19, 2, '大卫说：我要照哈嫩的父亲拿辖厚待我的恩典厚待哈嫩。于是大卫差遣使者为他丧父安慰他。大卫的臣仆到了亚扪人的境内见哈嫩，要安慰他，'),
('CUV', '历代志上', 13, 19, 3, '但亚扪人的首领对哈嫩说：大卫差人来安慰你，你想他是尊敬你父亲么？他的臣仆来见你不是为详察窥探、倾覆这地么？'),
('CUV', '历代志上', 13, 19, 4, '哈嫩便将大卫臣仆的胡须剃去一半，又割断他们下半截的衣服，使他们露出下体，打发他们回去。'),
('CUV', '历代志上', 13, 19, 5, '有人将臣仆所遇的事告诉大卫，他就差人去迎接他们，因为他们甚觉羞耻；告诉他们说：可以住在耶利哥，等到胡须长起再回来。'),
('CUV', '历代志上', 13, 19, 6, '亚扪人知道大卫憎恶他们，哈嫩和亚扪人就打发人拿一千他连得银子，从米所波大米、亚兰、玛迦、琐巴雇战车和马兵，'),
('CUV', '历代志上', 13, 19, 7, '于是雇了三万二千辆战车和玛迦王并他的军兵；他们来安营在米底巴前。亚扪人也从他们的城里出来，聚集交战。'),
('CUV', '历代志上', 13, 19, 8, '大卫听见了，就差派约押统带勇猛的全军出去。'),
('CUV', '历代志上', 13, 19, 9, '亚扪人出来在城门前摆阵，所来的诸王另在郊野摆阵。'),
('CUV', '历代志上', 13, 19, 10, '约押看见敌人在他前后摆阵，就从以色列军中挑选精兵，使他们对著亚兰人摆阵；'),
('CUV', '历代志上', 13, 19, 11, '其余的兵交与他兄弟亚比筛，对著亚扪人摆阵。'),
('CUV', '历代志上', 13, 19, 12, '约押对亚比筛说：亚兰人若强过我，你就来帮助我；亚扪人若强过你，我就去帮助你。'),
('CUV', '历代志上', 13, 19, 13, '我们都当刚强，为本国的民和神的城邑作大丈夫，愿耶和华凭他的意旨而行。'),
('CUV', '历代志上', 13, 19, 14, '于是约押和跟随他的人前进攻打亚兰人；亚兰人在约押面前逃跑。'),
('CUV', '历代志上', 13, 19, 15, '亚扪人见亚兰人逃跑，他们也在约押的兄弟亚比筛面前逃跑进城。约押就回耶路撒冷去了。'),
('CUV', '历代志上', 13, 19, 16, '亚兰人见自己被以色列人打败，就打发使者将大河那边的亚兰人调来，哈大利谢的将军朔法率领他们。'),
('CUV', '历代志上', 13, 19, 17, '有人告诉大卫，他就聚集以色列众人过约但河，来到亚兰人那里，迎著他们摆阵。大卫既摆阵攻击亚兰人，亚兰人就与他打仗。'),
('CUV', '历代志上', 13, 19, 18, '亚兰人在以色列人面前逃跑。大卫杀了亚兰七千辆战车的人，四万步兵，又杀了亚兰的将军朔法。'),
('CUV', '历代志上', 13, 19, 19, '属哈大利谢的诸王见自己被以色列人打败，就与大卫和好，归服他。于是亚兰人不敢再帮助亚扪人了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 20, 1, '过了一年，到列王出战的时候，约押率领军兵毁坏亚扪人的地，围攻拉巴；大卫仍住在耶路撒冷。约押攻打拉巴，将城倾覆。'),
('CUV', '历代志上', 13, 20, 2, '大卫夺了亚扪人之王(王或作玛勒堪。玛勒堪即米勒公，是亚扪族之神名)所戴的金冠冕，其上的金子重一他连得，又嵌著宝石；人将这冠冕戴在大卫头上。大卫从城里夺了许多财物，'),
('CUV', '历代志上', 13, 20, 3, '将城里的人拉出来，放在锯下，或铁耙下，或铁斧下(或作强他们用锯，或用打粮食的铁器，或用铁斧作工)，大卫待亚扪各城的居民都是如此。其后大卫和众军都回耶路撒冷去了。'),
('CUV', '历代志上', 13, 20, 4, '后来，以色列人在基色与非利士人打仗。户沙人西比该杀了伟人的一个儿子细派，非利士人就被制伏了。'),
('CUV', '历代志上', 13, 20, 5, '又与非利士人打仗。睚珥的儿子伊勒哈难杀了迦特人歌利亚的兄弟拉哈米；这人的枪杆粗如织布的机轴。'),
('CUV', '历代志上', 13, 20, 6, '又在迦特打仗。那里有一个身量高大的人，手脚都是六指，共有二十四个指头，他也是伟人的儿子。'),
('CUV', '历代志上', 13, 20, 7, '这人向以色列人骂阵，大卫的哥哥示米亚的儿子约拿单就杀了他。'),
('CUV', '历代志上', 13, 20, 8, '这三个人是迦特伟人的儿子，都死在大卫和他仆人的手下。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 21, 1, '撒但起来攻击以色列人，激动大卫数点他们。'),
('CUV', '历代志上', 13, 21, 2, '大卫就吩咐约押和民中的首领说：你们去数点以色列人，从别是巴直到但，回来告诉我，我好知道他们的数目。'),
('CUV', '历代志上', 13, 21, 3, '约押说：愿耶和华使他的百姓比现在加增百倍。我主我王啊，他们不都是你的仆人么？我主为何吩咐行这事，为何使以色列人陷在罪里呢？'),
('CUV', '历代志上', 13, 21, 4, '但王的命令胜过约押。约押就出去，走遍以色列地，回到耶路撒冷，'),
('CUV', '历代志上', 13, 21, 5, '将百姓的总数奏告大卫：以色列人拿刀的有一百一十万；犹大人拿刀的有四十七万。'),
('CUV', '历代志上', 13, 21, 6, '惟有利未人和便雅悯人没有数在其中，因为约押厌恶王的这命令。'),
('CUV', '历代志上', 13, 21, 7, '神不喜悦这数点百姓的事，便降灾给以色列人。'),
('CUV', '历代志上', 13, 21, 8, '大卫祷告神说：我行这事大有罪了！现在求你除掉仆人的罪孽，因我所行的甚是愚昧。'),
('CUV', '历代志上', 13, 21, 9, '耶和华吩咐大卫的先见迦得说：'),
('CUV', '历代志上', 13, 21, 10, '你去告诉大卫说，耶和华如此说：我有三样灾，随你选择一样，我好降与你。'),
('CUV', '历代志上', 13, 21, 11, '于是，迦得来见大卫，对他说：耶和华如此说：你可以随意选择：'),
('CUV', '历代志上', 13, 21, 12, '或三年的饥荒；或败在你敌人面前，被敌人的刀追杀三个月；或在你国中有耶和华的刀，就是三日的瘟疫，耶和华的使者在以色列的四境施行毁灭。现在你要想一想，我好回复那差我来的。'),
('CUV', '历代志上', 13, 21, 13, '大卫对迦得说：我甚为难。我愿落在耶和华的手里，因为他有丰盛的怜悯；我不愿落在人的手里。'),
('CUV', '历代志上', 13, 21, 14, '于是，耶和华降瘟疫与以色列人，以色列人就死了七万。'),
('CUV', '历代志上', 13, 21, 15, '神差遣使者去灭耶路撒冷，刚要灭的时候，耶和华看见后悔，就不降这灾了，吩咐灭城的天使说：够了，住手罢！那时，耶和华的使者站在耶布斯人阿珥楠的禾场那里。'),
('CUV', '历代志上', 13, 21, 16, '大卫举目，看见耶和华的使者站在天地间，手里有拔出来的刀，伸在耶路撒冷以上。大卫和长老都身穿麻衣，面伏于地。'),
('CUV', '历代志上', 13, 21, 17, '大卫祷告神说：吩咐数点百姓的不是我么？我犯了罪，行了恶，但这群羊做了甚么呢？愿耶和华─我神的手攻击我和我的父家，不要攻击你的民，降瘟疫与他们。'),
('CUV', '历代志上', 13, 21, 18, '耶和华的使者吩咐迦得去告诉大卫，叫他上去，在耶布斯人阿珥楠的禾场上为耶和华筑一座坛；'),
('CUV', '历代志上', 13, 21, 19, '大卫就照著迦得奉耶和华名所说的话上去了。'),
('CUV', '历代志上', 13, 21, 20, '那时阿珥楠正打麦子，回头看见天使，就和他四个儿子都藏起来了。'),
('CUV', '历代志上', 13, 21, 21, '大卫到了阿珥楠那里，阿珥楠看见大卫，就从禾场上出去，脸伏于地，向他下拜。'),
('CUV', '历代志上', 13, 21, 22, '大卫对阿珥楠说：你将这禾场与相连之地卖给我，我必给你足价，我好在其上为耶和华筑一座坛，使民间的瘟疫止住。'),
('CUV', '历代志上', 13, 21, 23, '阿珥楠对大卫说：你可以用这禾场，愿我主我王照你所喜悦的去行。我也将牛给你作燔祭，把打粮的器具当柴烧，拿麦子作素祭。这些我都送给你。'),
('CUV', '历代志上', 13, 21, 24, '大卫王对阿珥楠说：不然！我必要用足价向你买。我不用你的物献给耶和华，也不用白得之物献为燔祭。'),
('CUV', '历代志上', 13, 21, 25, '于是大卫为那块地平了六百舍客勒金子给阿珥楠。'),
('CUV', '历代志上', 13, 21, 26, '大卫在那里为耶和华筑了一座坛，献燔祭和平安祭，求告耶和华。耶和华就应允他，使火从天降在燔祭坛上。'),
('CUV', '历代志上', 13, 21, 27, '耶和华吩咐使者，他就收刀入鞘。'),
('CUV', '历代志上', 13, 21, 28, '那时，大卫见耶和华在耶布斯人阿珥楠的禾场上应允了他，就在那里献祭。'),
('CUV', '历代志上', 13, 21, 29, '摩西在旷野所造之耶和华的帐幕和燔祭坛都在基遍的高处；'),
('CUV', '历代志上', 13, 21, 30, '只是大卫不敢前去求问神，因为惧怕耶和华使者的刀。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 22, 1, '大卫说：这就是耶和华神的殿，为以色列人献燔祭的坛。'),
('CUV', '历代志上', 13, 22, 2, '大卫吩咐聚集住以色列地的外邦人，从其中派石匠凿石头，要建造神的殿。'),
('CUV', '历代志上', 13, 22, 3, '大卫预备许多铁做门上的钉子和钩子，又预备许多铜，多得无法可称；'),
('CUV', '历代志上', 13, 22, 4, '又预备无数的香柏木，因为西顿人和推罗人给大卫运了许多香柏木来。'),
('CUV', '历代志上', 13, 22, 5, '大卫说：我儿子所罗门还年幼娇嫩，要为耶和华建造的殿宇必须高大辉煌，使名誉荣耀传遍万国；所以我要为殿预备材料。于是，大卫在未死之先预备的材料甚多。'),
('CUV', '历代志上', 13, 22, 6, '大卫召了他儿子所罗门来，嘱咐他给耶和华─以色列的神建造殿宇，'),
('CUV', '历代志上', 13, 22, 7, '对所罗门说：我儿啊，我心里本想为耶和华─我神的名建造殿宇，'),
('CUV', '历代志上', 13, 22, 8, '只是耶和华的话临到我说：你流了多人的血，打了多次大仗，你不可为我的名建造殿宇，因为你在我眼前使多人的血流在地上。'),
('CUV', '历代志上', 13, 22, 9, '你要生一个儿子，他必作太平的人；我必使他安静，不被四围的仇敌扰乱。他的名要叫所罗门(即太平之意)。他在位的日子，我必使以色列人平安康泰。'),
('CUV', '历代志上', 13, 22, 10, '他必为我的名建造殿宇。他要作我的子；我要作他的父。他作以色列王；我必坚定他的国位，直到永远。'),
('CUV', '历代志上', 13, 22, 11, '我儿啊，现今愿耶和华与你同在，使你亨通，照他指著你说的话，建造耶和华─你神的殿。'),
('CUV', '历代志上', 13, 22, 12, '但愿耶和华赐你聪明智慧，好治理以色列国，遵行耶和华─你神的律法。'),
('CUV', '历代志上', 13, 22, 13, '你若谨守遵行耶和华藉摩西吩咐以色列的律例典章，就得亨通。你当刚强壮胆，不要惧怕，也不要惊惶。'),
('CUV', '历代志上', 13, 22, 14, '我在困难之中为耶和华的殿预备了金子十万他连得，银子一百万他连得，铜和铁多得无法可称；我也预备了木头、石头，你还可以增添。'),
('CUV', '历代志上', 13, 22, 15, '你有许多匠人，就是石匠、木匠，和一切能做各样工的巧匠，'),
('CUV', '历代志上', 13, 22, 16, '并有无数的金银铜铁。你当起来办事，愿耶和华与你同在。'),
('CUV', '历代志上', 13, 22, 17, '大卫又吩咐以色列的众首领帮助他儿子所罗门，说：'),
('CUV', '历代志上', 13, 22, 18, '耶和华─你们的神不是与你们同在么？不是叫你们四围都平安么？因他已将这地的居民交在我手中，这地就在耶和华与他百姓面前制伏了。'),
('CUV', '历代志上', 13, 22, 19, '现在你们应当立定心意，寻求耶和华─你们的神；也当起来建造耶和华神的圣所，好将耶和华的约柜和供奉神的圣器皿都搬进为耶和华名建造的殿里。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 23, 1, '大卫年纪老迈，日子满足，就立他儿子所罗门作以色列的王。'),
('CUV', '历代志上', 13, 23, 2, '大卫招聚以色列的众首领和祭司利未人。'),
('CUV', '历代志上', 13, 23, 3, '利未人从三十岁以外的都被数点，他们男丁的数目共有三万八千；'),
('CUV', '历代志上', 13, 23, 4, '其中有二万四千人管理耶和华殿的事，有六千人作官长和士师，'),
('CUV', '历代志上', 13, 23, 5, '有四千人作守门的，又有四千人用大卫所做的乐器颂赞耶和华。'),
('CUV', '历代志上', 13, 23, 6, '大卫将利未人革顺、哥辖、米拉利的子孙分了班次。'),
('CUV', '历代志上', 13, 23, 7, '革顺的子孙有拉但和示每。'),
('CUV', '历代志上', 13, 23, 8, '拉但的长子是耶歇，还有细坦和约珥，共三人。'),
('CUV', '历代志上', 13, 23, 9, '示每的儿子是示罗密、哈薛、哈兰三人。这是拉但族的族长。'),
('CUV', '历代志上', 13, 23, 10, '示每的儿子是雅哈、细拿、耶乌施、比利亚共四人。'),
('CUV', '历代志上', 13, 23, 11, '雅哈是长子，细撒是次子。但耶乌施和比利亚的子孙不多，所以算为一族。'),
('CUV', '历代志上', 13, 23, 12, '哥辖的儿子是暗兰、以斯哈、希伯伦、乌薛共四人。'),
('CUV', '历代志上', 13, 23, 13, '暗兰的儿子是亚伦、摩西。亚伦和他的子孙分出来，好分别至圣的物，在耶和华面前烧香、事奉他，奉他的名祝福，直到永远。'),
('CUV', '历代志上', 13, 23, 14, '至于神人摩西，他的子孙名字记在利未支派的册上。'),
('CUV', '历代志上', 13, 23, 15, '摩西的儿子是革舜和以利以谢。'),
('CUV', '历代志上', 13, 23, 16, '革舜的长子是细布业；'),
('CUV', '历代志上', 13, 23, 17, '以利以谢的儿子是利哈比雅。以利以谢没有别的儿子，但利哈比雅的子孙甚多。'),
('CUV', '历代志上', 13, 23, 18, '以斯哈的长子是示罗密。'),
('CUV', '历代志上', 13, 23, 19, '希伯伦的长子是耶利雅，次子是亚玛利亚，三子是雅哈悉，四子是耶加面。'),
('CUV', '历代志上', 13, 23, 20, '乌薛的长子是米迦，次子是耶西雅。'),
('CUV', '历代志上', 13, 23, 21, '米拉利的儿子是抹利、母示。抹利的儿子是以利亚撒、基士。'),
('CUV', '历代志上', 13, 23, 22, '以利亚撒死了，没有儿子，只有女儿，他们本族基士的儿子娶了他们为妻。'),
('CUV', '历代志上', 13, 23, 23, '母示的儿子是末力、以得、耶利摩共三人。'),
('CUV', '历代志上', 13, 23, 24, '以上利未子孙作族长的，照著男丁的数目，从二十岁以外，都办耶和华殿的事务。'),
('CUV', '历代志上', 13, 23, 25, '大卫说：耶和华─以色列的神已经使他的百姓平安，他永远住在耶路撒冷。'),
('CUV', '历代志上', 13, 23, 26, '利未人不必再抬帐幕和其中所用的一切器皿了。'),
('CUV', '历代志上', 13, 23, 27, '照著大卫临终所吩咐的，利未人从二十岁以外的都被数点。'),
('CUV', '历代志上', 13, 23, 28, '他们的职任是服事亚伦的子孙，在耶和华的殿和院子，并屋中办事，洁净一切圣物，就是办神殿的事务，'),
('CUV', '历代志上', 13, 23, 29, '并管理陈设饼，素祭的细面，或无酵薄饼，或用盘烤，或用油调和的物，又管理各样的升斗尺度；'),
('CUV', '历代志上', 13, 23, 30, '每日早晚，站立称谢赞美耶和华，'),
('CUV', '历代志上', 13, 23, 31, '又在安息日、月朔，并节期，按数照例，将燔祭常常献给耶和华；'),
('CUV', '历代志上', 13, 23, 32, '又看守会幕和圣所，并守耶和华吩咐他们弟兄亚伦子孙的，办耶和华殿的事。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 24, 1, '亚伦子孙的班次记在下面：亚伦的儿子是拿答、亚比户、以利亚撒、以他玛。'),
('CUV', '历代志上', 13, 24, 2, '拿答、亚比户死在他们父亲之先，没有留下儿子；故此，以利亚撒、以他玛供祭司的职分。'),
('CUV', '历代志上', 13, 24, 3, '以利亚撒的子孙撒督和以他玛的子孙亚希米勒，同著大卫将他们的族弟兄分成班次。'),
('CUV', '历代志上', 13, 24, 4, '以利亚撒子孙中为首的比以他玛子孙中为首的更多，分班如下：以利亚撒的子孙中有十六个族长，以他玛的子孙中有八个族长；'),
('CUV', '历代志上', 13, 24, 5, '都掣签分立，彼此一样。在圣所和神面前作首领的有以利亚撒的子孙，也有以他玛的子孙。'),
('CUV', '历代志上', 13, 24, 6, '作书记的利未人拿坦业的儿子示玛雅在王和首领，与祭司撒督、亚比亚他的儿子亚希米勒，并祭司利未人的族长面前记录他们的名字。在以利亚撒的子孙中取一族，在以他玛的子孙中取一族。'),
('CUV', '历代志上', 13, 24, 7, '掣签的时候，第一掣出来的是耶何雅立，第二是耶大雅，'),
('CUV', '历代志上', 13, 24, 8, '第三是哈琳，第四是梭琳，'),
('CUV', '历代志上', 13, 24, 9, '第五是玛基雅，第六是米雅民，'),
('CUV', '历代志上', 13, 24, 10, '第七是哈歌斯，第八是亚比雅，'),
('CUV', '历代志上', 13, 24, 11, '第九是耶书亚，第十是示迦尼，'),
('CUV', '历代志上', 13, 24, 12, '第十一是以利亚实，第十二是雅金，'),
('CUV', '历代志上', 13, 24, 13, '第十三是胡巴，第十四是耶是比押，'),
('CUV', '历代志上', 13, 24, 14, '第十五是璧迦，第十六是音麦，'),
('CUV', '历代志上', 13, 24, 15, '第十七是希悉，第十八是哈辟悉，'),
('CUV', '历代志上', 13, 24, 16, '第十九是毗他希雅，第二十是以西结，'),
('CUV', '历代志上', 13, 24, 17, '第二十一是雅斤，第二十二是迦末，'),
('CUV', '历代志上', 13, 24, 18, '第二十三是第来雅，第二十四是玛西亚。'),
('CUV', '历代志上', 13, 24, 19, '这就是他们的班次，要照耶和华─以色列的神藉他们祖宗亚伦所吩咐的条例进入耶和华的殿办理事务。'),
('CUV', '历代志上', 13, 24, 20, '利未其余的子孙如下：暗兰的子孙里有书巴业；书巴业的子孙里有耶希底亚。'),
('CUV', '历代志上', 13, 24, 21, '利哈比雅的子孙里有长子伊示雅。'),
('CUV', '历代志上', 13, 24, 22, '以斯哈的子孙里有示罗摩；示罗摩的子孙里有雅哈。'),
('CUV', '历代志上', 13, 24, 23, '希伯伦的子孙里有长子耶利雅，次子亚玛利亚，三子雅哈悉，四子耶加面。'),
('CUV', '历代志上', 13, 24, 24, '乌薛的子孙里有米迦；米迦的子孙里有沙密。'),
('CUV', '历代志上', 13, 24, 25, '米迦的兄弟是伊示雅；伊示雅的子孙里有撒迦利雅。'),
('CUV', '历代志上', 13, 24, 26, '米拉利的儿子是抹利、母示、雅西雅；雅西雅的儿子有比挪；'),
('CUV', '历代志上', 13, 24, 27, '米拉利的子孙里有雅西雅的儿子比挪、朔含、撒刻、伊比利。'),
('CUV', '历代志上', 13, 24, 28, '抹利的儿子是以利亚撒；以利亚撒没有儿子。'),
('CUV', '历代志上', 13, 24, 29, '基士的子孙里有耶拉篾。'),
('CUV', '历代志上', 13, 24, 30, '母示的儿子是末力、以得、耶利摩。按著宗族这都是利未的子孙。'),
('CUV', '历代志上', 13, 24, 31, '他们在大卫王和撒督，并亚希米勒与祭司利未人的族长面前掣签，正如他们弟兄亚伦的子孙一般。各族的长者与兄弟没有分别。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 25, 1, '大卫和众首领分派亚萨、希幔，并耶杜顿的子孙弹琴、鼓瑟、敲钹、唱歌(原文作说预言；本章同)。他们供职的人数记在下面：'),
('CUV', '历代志上', 13, 25, 2, '亚萨的儿子撒刻、约瑟、尼探雅、亚萨利拉都归亚萨指教，遵王的旨意唱歌。'),
('CUV', '历代志上', 13, 25, 3, '耶杜顿的儿子基大利、西利、耶筛亚、哈沙比雅、玛他提雅、示每共六人，都归他们父亲耶杜顿指教，弹琴，唱歌，称谢，颂赞耶和华。'),
('CUV', '历代志上', 13, 25, 4, '希幔的儿子布基雅、玛探雅、乌薛、细布业、耶利摩、哈拿尼雅、哈拿尼、以利亚他、基大利提、罗幔提•以谢、约施比加沙、玛罗提、何提、玛哈秀；'),
('CUV', '历代志上', 13, 25, 5, '这都是希幔的儿子，吹角颂赞。希幔奉神之命作王的先见。神赐给希幔十四个儿子，三个女儿，'),
('CUV', '历代志上', 13, 25, 6, '都归他们父亲指教，在耶和华的殿唱歌、敲钹、弹琴、鼓瑟，办神殿的事务。亚萨、耶杜顿、希幔都是王所命定的。'),
('CUV', '历代志上', 13, 25, 7, '他们和他们的弟兄学习颂赞耶和华；善于歌唱的共有二百八十八人。'),
('CUV', '历代志上', 13, 25, 8, '这些人无论大小，为师的、为徒的，都一同掣签分了班次。'),
('CUV', '历代志上', 13, 25, 9, '掣签的时候，第一掣出来的是亚萨的儿子约瑟。第二是基大利；他和他弟兄并儿子共十二人。'),
('CUV', '历代志上', 13, 25, 10, '第三是撒刻；他和他儿子并弟兄共十二人。'),
('CUV', '历代志上', 13, 25, 11, '第四是伊洗利；他和他儿子并弟兄共十二人。'),
('CUV', '历代志上', 13, 25, 12, '第五是尼探雅；他和他儿子并弟兄共十二人。'),
('CUV', '历代志上', 13, 25, 13, '第六是布基雅；他和他儿子并弟兄共十二人。'),
('CUV', '历代志上', 13, 25, 14, '第七是耶萨利拉；他和他儿子并弟兄共十二人。'),
('CUV', '历代志上', 13, 25, 15, '第八是耶筛亚；他和他儿子并弟兄共十二人。'),
('CUV', '历代志上', 13, 25, 16, '第九是玛探雅；他和他儿子并弟兄共十二人。'),
('CUV', '历代志上', 13, 25, 17, '第十是示每；他和他儿子并弟兄共十二人。'),
('CUV', '历代志上', 13, 25, 18, '第十一是亚萨烈；他和他儿子并弟兄共十二人。'),
('CUV', '历代志上', 13, 25, 19, '第十二是哈沙比雅；他和他儿子并弟兄共十二人。'),
('CUV', '历代志上', 13, 25, 20, '第十三是书巴业；他和他儿子并弟兄共十二人。'),
('CUV', '历代志上', 13, 25, 21, '第十四是玛他提雅；他和他儿子并弟兄共十二人。'),
('CUV', '历代志上', 13, 25, 22, '第十五是耶利摩；他和他儿子并弟兄共十二人。'),
('CUV', '历代志上', 13, 25, 23, '第十六是哈拿尼雅；他和他儿子并弟兄共十二人。'),
('CUV', '历代志上', 13, 25, 24, '第十七是约施比加沙；他和他儿子并弟兄共十二人。'),
('CUV', '历代志上', 13, 25, 25, '第十八是哈拿尼；他和他儿子并弟兄共十二人。'),
('CUV', '历代志上', 13, 25, 26, '第十九是玛罗提；他和他儿子并弟兄共十二人。'),
('CUV', '历代志上', 13, 25, 27, '第二十是以利亚他；他和他儿子并弟兄共十二人。'),
('CUV', '历代志上', 13, 25, 28, '第二十一是何提；他和他儿子并弟兄共十二人。'),
('CUV', '历代志上', 13, 25, 29, '第二十二是基大利提；他和他儿子并弟兄共十二人。'),
('CUV', '历代志上', 13, 25, 30, '第二十三是玛哈秀；他和他儿子并弟兄共十二人。'),
('CUV', '历代志上', 13, 25, 31, '第二十四是罗幔提•以谢；他和他儿子并弟兄共十二人。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 26, 1, '守门的班次记在下面：可拉族亚萨的子孙中，有可利的儿子米施利米雅。'),
('CUV', '历代志上', 13, 26, 2, '米施利米雅的长子是撒迦利亚，次子是耶叠，三子是西巴第雅，四子是耶提聂，'),
('CUV', '历代志上', 13, 26, 3, '五子是以拦，六子是约哈难，七子是以利约乃。'),
('CUV', '历代志上', 13, 26, 4, '俄别以东的长子是示玛雅，次子是约萨拔，三子是约亚，四子是沙甲，五子是拿坦业，'),
('CUV', '历代志上', 13, 26, 5, '六子是亚米利，七子是以萨迦，八子是毗乌利太，因为神赐福与俄别以东。'),
('CUV', '历代志上', 13, 26, 6, '他的儿子示玛雅有几个儿子，都是大能的壮士，掌管父亲的家。'),
('CUV', '历代志上', 13, 26, 7, '示玛雅的儿子是俄得尼、利法益、俄备得、以利萨巴。以利萨巴的弟兄是壮士，还有以利户和西玛迦。'),
('CUV', '历代志上', 13, 26, 8, '这都是俄别以东的子孙，他们和他们的儿子并弟兄，都是善于办事的壮士。俄别以东的子孙共六十二人。'),
('CUV', '历代志上', 13, 26, 9, '米施利米雅的儿子和弟兄都是壮士，共十八人。'),
('CUV', '历代志上', 13, 26, 10, '米拉利子孙何萨有几个儿子：长子是申利，他原不是长子，是他父亲立他作长子。'),
('CUV', '历代志上', 13, 26, 11, '次子是希勒家，三子是底巴利雅，四子是撒迦利亚。何萨的儿子并弟兄共十三人。'),
('CUV', '历代志上', 13, 26, 12, '这些人都是守门的班长，与他们的弟兄一同在耶和华殿里按班供职。'),
('CUV', '历代志上', 13, 26, 13, '他们无论大小，都按著宗族掣签分守各门。'),
('CUV', '历代志上', 13, 26, 14, '掣签守东门的是示利米雅；他的儿子撒迦利亚是精明的谋士，掣签守北门。'),
('CUV', '历代志上', 13, 26, 15, '俄别以东守南门，他的儿子守库房。'),
('CUV', '历代志上', 13, 26, 16, '书聘与何萨守西门，在靠近沙利基门、通著往上去的街道上，班与班相对。'),
('CUV', '历代志上', 13, 26, 17, '每日东门有六个利未人，北门有四个，南门有四个，库房有两个，又有两个轮班替换。'),
('CUV', '历代志上', 13, 26, 18, '在西面街道上有四个，在游廊上有两个。'),
('CUV', '历代志上', 13, 26, 19, '以上是可拉子孙和米拉利子孙守门的班次。'),
('CUV', '历代志上', 13, 26, 20, '利未子孙中有亚希雅掌管神殿的府库和圣物的府库。'),
('CUV', '历代志上', 13, 26, 21, '革顺族、拉但子孙里，作族长的是革顺族拉但的子孙耶希伊利。'),
('CUV', '历代志上', 13, 26, 22, '耶希伊利的儿子西坦和他兄弟约珥掌管耶和华殿里的府库。'),
('CUV', '历代志上', 13, 26, 23, '暗兰族、以斯哈族、希伯伦族、乌泄族也有职分。'),
('CUV', '历代志上', 13, 26, 24, '摩西的孙子、革舜的儿子细布业掌管府库。'),
('CUV', '历代志上', 13, 26, 25, '还有他的弟兄以利以谢。以利以谢的儿子是利哈比雅；利哈比雅的儿子是耶筛亚；耶筛亚的儿子是约兰；约兰的儿子是细基利；细基利的儿子是示罗密。'),
('CUV', '历代志上', 13, 26, 26, '这示罗密和他的弟兄掌管府库的圣物，就是大卫王和众族长、千夫长、百夫长，并军长所分别为圣的物。'),
('CUV', '历代志上', 13, 26, 27, '他们将争战时所夺的财物分别为圣，以备修造耶和华的殿。'),
('CUV', '历代志上', 13, 26, 28, '先见撒母耳、基士的儿子扫罗、尼珥的儿子押尼珥、洗鲁雅的儿子约押所分别为圣的物都归示罗密和他的弟兄掌管。'),
('CUV', '历代志上', 13, 26, 29, '以斯哈族有基拿尼雅和他众子作官长和士师，管理以色列的外事。'),
('CUV', '历代志上', 13, 26, 30, '希伯伦族有哈沙比雅和他弟兄一千七百人，都是壮士，在约但河西、以色列地办理耶和华与王的事。'),
('CUV', '历代志上', 13, 26, 31, '希伯伦族中有耶利雅作族长。大卫作王第四十年，在基列的雅谢，从这族中寻得大能的勇士。'),
('CUV', '历代志上', 13, 26, 32, '耶利雅的弟兄有二千七百人，都是壮士，且作族长；大卫王派他们在流便支派、迦得支派、玛拿西半支派中办理神和王的事。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 27, 1, '以色列人的族长、千夫长、百夫长，和官长都分定班次，每班是二万四千人，周年按月轮流，替换出入服事王。'),
('CUV', '历代志上', 13, 27, 2, '正月第一班的班长是撒巴第业的儿子雅朔班；他班内有二万四千人。'),
('CUV', '历代志上', 13, 27, 3, '他是法勒斯的子孙，统管正月班的一切军长。'),
('CUV', '历代志上', 13, 27, 4, '二月的班长是亚哈希人朵代，还有副官密基罗；他班内有二万四千人。'),
('CUV', '历代志上', 13, 27, 5, '三月第三班的班长(原文作军长；下同)是祭司耶何耶大的儿子比拿雅；他班内有二万四千人。'),
('CUV', '历代志上', 13, 27, 6, '这比拿雅是那三十人中的勇士，管理那三十人；他班内又有他儿子暗米萨拔。'),
('CUV', '历代志上', 13, 27, 7, '四月第四班的班长是约押的兄弟亚撒黑。接续他的是他儿子西巴第雅；他班内有二万四千人。'),
('CUV', '历代志上', 13, 27, 8, '五月第五班的班长是伊斯拉人珊合；他班内有二万四千人。'),
('CUV', '历代志上', 13, 27, 9, '六月第六班的班长是提哥亚人益吉的儿子以拉；他班内有二万四千人。'),
('CUV', '历代志上', 13, 27, 10, '七月第七班的班长是以法莲族比伦人希利斯；他班内有二万四千人。'),
('CUV', '历代志上', 13, 27, 11, '八月第八班的班长是谢拉族户沙人西比该；他班内有二万四千人。'),
('CUV', '历代志上', 13, 27, 12, '九月第九班的班长是便雅悯族亚拿突人亚比以谢；他班内有二万四千人。'),
('CUV', '历代志上', 13, 27, 13, '十月第十班的班长是谢拉族尼陀法人玛哈莱；他班内有二万四千人。'),
('CUV', '历代志上', 13, 27, 14, '十一月第十一班的班长是以法莲族比拉顿人比拿雅；他班内有二万四千人。'),
('CUV', '历代志上', 13, 27, 15, '十二月第十二班的班长是俄陀聂族尼陀法人黑玳；他班内有二万四千人。'),
('CUV', '历代志上', 13, 27, 16, '管理以色列众支派的记在下面：管流便人的是细基利的儿子以利以谢；管西缅人的是玛迦的儿子示法提雅；'),
('CUV', '历代志上', 13, 27, 17, '管利未人的是基母利的儿子哈沙比雅；管亚伦子孙的是撒督；'),
('CUV', '历代志上', 13, 27, 18, '管犹大人的是大卫的一个哥哥以利户，管以萨迦人的是米迦勒的儿子暗利；'),
('CUV', '历代志上', 13, 27, 19, '管西布伦人的是俄巴第雅的儿子伊施玛雅；管拿弗他利人的是亚斯列的儿子耶利摩；'),
('CUV', '历代志上', 13, 27, 20, '管以法莲人的是阿撒细雅的儿子何细亚；管玛拿西半支派的是毗大雅的儿子约珥；'),
('CUV', '历代志上', 13, 27, 21, '管基列地玛拿西那半支派的是撒迦利亚的儿子易多；管便雅悯人的是押尼珥的儿子雅西业；'),
('CUV', '历代志上', 13, 27, 22, '管但人的是耶罗罕的儿子亚萨列。以上是以色列众支派的首领。'),
('CUV', '历代志上', 13, 27, 23, '以色列人二十岁以内的，大卫没有记其数目；因耶和华曾应许说，必加增以色列人如天上的星那样多。'),
('CUV', '历代志上', 13, 27, 24, '洗鲁雅的儿子约押动手数点，当时耶和华的烈怒临到以色列人；因此，没有点完，数目也没有写在大卫王记上。'),
('CUV', '历代志上', 13, 27, 25, '掌管王府库的是亚叠的儿子押斯马威。掌管田野城邑村庄保障之仓库的是乌西雅的儿子约拿单。'),
('CUV', '历代志上', 13, 27, 26, '掌管耕田种地的是基绿的儿子以斯利。'),
('CUV', '历代志上', 13, 27, 27, '掌管葡萄园的是拉玛人示每。掌管葡萄园酒窖的是实弗米人撒巴底。'),
('CUV', '历代志上', 13, 27, 28, '掌管高原橄榄树和桑树的是基第利人巴勒哈南。掌管油库的是约阿施。'),
('CUV', '历代志上', 13, 27, 29, '掌管沙仑牧放牛群的是沙仑人施提赉。掌管山谷牧养牛群的是亚第赉的儿子沙法。'),
('CUV', '历代志上', 13, 27, 30, '掌管驼群的是以实玛利人阿比勒。掌管驴群的是米仑人耶希底亚。掌管羊群的是夏甲人雅悉。'),
('CUV', '历代志上', 13, 27, 31, '这都是给大卫王掌管产业的。'),
('CUV', '历代志上', 13, 27, 32, '大卫的叔叔约拿单作谋士；这人有智慧，又作书记。哈摩尼的儿子耶歇作王众子的师傅。'),
('CUV', '历代志上', 13, 27, 33, '亚希多弗也作王的谋士。亚基人户筛作王的陪伴。'),
('CUV', '历代志上', 13, 27, 34, '亚希多弗之后，有比拿雅的儿子耶何耶大和亚比亚他接续他作谋士。约押作王的元帅。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 28, 1, '大卫招聚以色列各支派的首领和轮班服事王的军长，与千夫长、百夫长，掌管王和王子产业牲畜的，并太监，以及大能的勇士，都到耶路撒冷来。'),
('CUV', '历代志上', 13, 28, 2, '大卫王就站起来，说：我的弟兄，我的百姓啊，你们当听我言，我心里本想建造殿宇，安放耶和华的约柜，作为我神的脚凳；我已经预备建造的材料。'),
('CUV', '历代志上', 13, 28, 3, '只是神对我说：你不可为我的名建造殿宇；因你是战士，流了人的血。'),
('CUV', '历代志上', 13, 28, 4, '然而，耶和华─以色列的神在我父的全家拣选我作以色列的王，直到永远。因他拣选犹大为首领；在犹大支派中拣选我父家，在我父的众子里喜悦我，立我作以色列众人的王。'),
('CUV', '历代志上', 13, 28, 5, '耶和华赐我许多儿子，在我儿子中拣选所罗门坐耶和华的国位，治理以色列人。'),
('CUV', '历代志上', 13, 28, 6, '耶和华对我说：你儿子所罗门必建造我的殿和院宇；因为我拣选他作我的子，我也必作他的父。'),
('CUV', '历代志上', 13, 28, 7, '他若恒久遵行我的诫命典章如今日一样，我就必坚定他的国位，直到永远。'),
('CUV', '历代志上', 13, 28, 8, '现今在耶和华的会中，以色列众人眼前所说的，我们的神也听见了。你们应当寻求耶和华─你们神的一切诫命，谨守遵行，如此你们可以承受这美地，遗留给你们的子孙，永远为业。'),
('CUV', '历代志上', 13, 28, 9, '我儿所罗门哪，你当认识耶和华─你父的神，诚心乐意地事奉他；因为他鉴察众人的心，知道一切心思意念。你若寻求他，他必使你寻见；你若离弃他，他必永远丢弃你。'),
('CUV', '历代志上', 13, 28, 10, '你当谨慎，因耶和华拣选你建造殿宇作为圣所。你当刚强去行。'),
('CUV', '历代志上', 13, 28, 11, '大卫将殿的游廊、旁屋、府库、楼房、内殿，和施恩所的样式指示他儿子所罗门，'),
('CUV', '历代志上', 13, 28, 12, '又将被灵感动所得的样式，就是耶和华神殿的院子、周围的房屋、殿的府库，和圣物府库的一切样式都指示他；'),
('CUV', '历代志上', 13, 28, 13, '又指示他祭司和利未人的班次与耶和华殿里各样的工作，并耶和华殿里一切器皿的样式，'),
('CUV', '历代志上', 13, 28, 14, '以及各样应用金器的分两和各样应用银器的分两，'),
('CUV', '历代志上', 13, 28, 15, '金灯台和金灯的分两，银灯台和银灯的分两，轻重各都合宜；'),
('CUV', '历代志上', 13, 28, 16, '陈设饼金桌子的分两，银桌子的分两，'),
('CUV', '历代志上', 13, 28, 17, '精金的肉叉子、盘子，和爵的分两，各金碗与各银碗的分两，'),
('CUV', '历代志上', 13, 28, 18, '精金香坛的分两，并用金子做基路伯(原文作用金子做车式的基路伯)；基路伯张开翅膀，遮掩耶和华的约柜。'),
('CUV', '历代志上', 13, 28, 19, '大卫说：这一切工作的样式都是耶和华用手划出来使我明白的。'),
('CUV', '历代志上', 13, 28, 20, '大卫又对他儿子所罗门说：你当刚强壮胆去行！不要惧怕，也不要惊惶。因为耶和华神就是我的神，与你同在；他必不撇下你，也不丢弃你，直到耶和华殿的工作都完毕了。'),
('CUV', '历代志上', 13, 28, 21, '有祭司和利未人的各班，为要办理神殿各样的事，又有灵巧的人在各样的工作上乐意帮助你；并有众首领和众民一心听从你的命令。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志上', 13, 29, 1, '大卫王对会众说：我儿子所罗门是神特选的，还年幼娇嫩；这工程甚大，因这殿不是为人，乃是为耶和华神建造的。'),
('CUV', '历代志上', 13, 29, 2, '我为我神的殿已经尽力，预备金子做金器，银子做银器，铜做铜器，铁做铁器，木做木器，还有红玛瑙可镶嵌的宝石，彩石和一切的宝石，并许多汉白玉。'),
('CUV', '历代志上', 13, 29, 3, '且因我心中爱慕我神的殿，就在预备建造圣殿的材料之外，又将我自己积蓄的金银献上，建造我神的殿，'),
('CUV', '历代志上', 13, 29, 4, '就是俄斐金三千他连得、精炼的银子七千他连得，以贴殿墙。'),
('CUV', '历代志上', 13, 29, 5, '金子做金器，银子做银器，并藉匠人的手制造一切。今日有谁乐意将自己献给耶和华呢？'),
('CUV', '历代志上', 13, 29, 6, '于是，众族长和以色列各支派的首领、千夫长、百夫长，并监管王工的官长，都乐意献上。'),
('CUV', '历代志上', 13, 29, 7, '他们为神殿的使用献上金子五千他连得零一万达利克，银子一万他连得，铜一万八千他连得，铁十万他连得。'),
('CUV', '历代志上', 13, 29, 8, '凡有宝石的都交给革顺人耶歇，送入耶和华殿的府库。'),
('CUV', '历代志上', 13, 29, 9, '因这些人诚心乐意献给耶和华，百姓就欢喜，大卫王也大大欢喜。'),
('CUV', '历代志上', 13, 29, 10, '所以，大卫在会众面前称颂耶和华说：耶和华─我们的父，以色列的神是应当称颂，直到永永远远的！'),
('CUV', '历代志上', 13, 29, 11, '耶和华啊，尊大、能力、荣耀、强胜、威严都是你的；凡天上地下的都是你的；国度也是你的，并且你为至高，为万有之首。'),
('CUV', '历代志上', 13, 29, 12, '丰富尊荣都从你而来，你也治理万物。在你手里有大能大力，使人尊大强盛都出于你。'),
('CUV', '历代志上', 13, 29, 13, '我们的神啊，现在我们称谢你，赞美你荣耀之名！'),
('CUV', '历代志上', 13, 29, 14, '我算甚么，我的民算甚么，竟能如此乐意奉献？因为万物都从你而来，我们把从你而得的献给你。'),
('CUV', '历代志上', 13, 29, 15, '我们在你面前是客旅，是寄居的，与我们列祖一样。我们在世的日子如影儿，不能长存(或作没有长存的指望)。'),
('CUV', '历代志上', 13, 29, 16, '耶和华─我们的神啊，我们预备这许多材料，要为你的圣名建造殿宇，都是从你而来，都是属你的。'),
('CUV', '历代志上', 13, 29, 17, '我的神啊，我知道你察验人心，喜悦正直；我以正直的心乐意献上这一切物。现在我喜欢见你的民在这里都乐意奉献与你。'),
('CUV', '历代志上', 13, 29, 18, '耶和华─我们列祖亚伯拉罕、以撒、以色列的神啊，求你使你的民常存这样的心思意念，坚定他们的心归向你，'),
('CUV', '历代志上', 13, 29, 19, '又求你赐我儿子所罗门诚实的心，遵守你的命令、法度、律例，成就这一切的事，用我所预备的建造殿宇。'),
('CUV', '历代志上', 13, 29, 20, '大卫对全会众说：你们应当称颂耶和华─你们的神。于是会众称颂耶和华─他们列祖的神，低头拜耶和华与王。'),
('CUV', '历代志上', 13, 29, 21, '次日，他们向耶和华献平安祭和燔祭，就是献公牛一千只，公绵羊一千只，羊羔一千只，并同献的奠祭；又为以色列众人献许多的祭。那日，他们在耶和华面前吃喝，大大欢乐。'),
('CUV', '历代志上', 13, 29, 22, '他们奉耶和华的命再膏大卫的儿子所罗门作王，又膏撒督作祭司。'),
('CUV', '历代志上', 13, 29, 23, '于是所罗门坐在耶和华所赐的位上，接续他父亲大卫作王，万事亨通；以色列众人也都听从他。'),
('CUV', '历代志上', 13, 29, 24, '众首领和勇士，并大卫王的众子，都顺服所罗门王。'),
('CUV', '历代志上', 13, 29, 25, '耶和华使所罗门在以色列众人眼前甚为尊大，极其威严，胜过在他以前的以色列王。'),
('CUV', '历代志上', 13, 29, 26, '耶西的儿子大卫作以色列众人的王，'),
('CUV', '历代志上', 13, 29, 27, '作王共四十年：在希伯仑作王七年，在耶路撒冷作王三十三年。'),
('CUV', '历代志上', 13, 29, 28, '他年纪老迈，日子满足，享受丰富、尊荣，就死了。他儿子所罗门接续他作王。'),
('CUV', '历代志上', 13, 29, 29, '大卫王始终的事都写在先见撒母耳的书上和先知拿单并先见迦得的书上。'),
('CUV', '历代志上', 13, 29, 30, '他的国事和他的勇力，以及他和以色列并列国所经过的事都写在这书上。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 1, 1, '大卫的儿子所罗门国位坚固；耶和华─他的神与他同在，使他甚为尊大。'),
('CUV', '历代志下', 14, 1, 2, '所罗门吩咐以色列众人，就是千夫长、百夫长、审判官、首领与族长都来。'),
('CUV', '历代志下', 14, 1, 3, '所罗门和会众都往基遍的邱坛去，因那里有神的会幕，就是耶和华仆人摩西在旷野所制造的。'),
('CUV', '历代志下', 14, 1, 4, '只是神的约柜，大卫已经从基列耶琳搬到他所预备的地方，因他曾在耶路撒冷为约柜支搭了帐幕，'),
('CUV', '历代志下', 14, 1, 5, '并且户珥的孙子、乌利的儿子比撒列所造的铜坛也在基遍耶和华的会幕前。所罗门和会众都就近坛前。'),
('CUV', '历代志下', 14, 1, 6, '所罗门上到耶和华面前会幕的铜坛那里，献一千牺牲为燔祭。'),
('CUV', '历代志下', 14, 1, 7, '当夜，神向所罗门显现，对他说：你愿我赐你甚么，你可以求。'),
('CUV', '历代志下', 14, 1, 8, '所罗门对神说：你曾向我父大卫大施慈爱，使我接续他作王。'),
('CUV', '历代志下', 14, 1, 9, '耶和华神啊，现在求你成就向我父大卫所应许的话；因你立我作这民的王，他们如同地上尘沙那样多。'),
('CUV', '历代志下', 14, 1, 10, '求你赐我智慧聪明，我好在这民前出入；不然，谁能判断这众多的民呢？'),
('CUV', '历代志下', 14, 1, 11, '神对所罗门说：我已立你作我民的王。你既有这心意，并不求资财、丰富、尊荣，也不求灭绝那恨你之人的性命，又不求大寿数，只求智慧聪明好判断我的民；'),
('CUV', '历代志下', 14, 1, 12, '我必赐你智慧聪明，也必赐你资财、丰富、尊荣。在你以前的列王都没有这样，在你以后也必没有这样的。'),
('CUV', '历代志下', 14, 1, 13, '于是，所罗门从基遍邱坛会幕前回到耶路撒冷，治理以色列人。'),
('CUV', '历代志下', 14, 1, 14, '所罗门聚集战车马兵，有战车一千四百辆，马兵一万二千名，安置在屯车的城邑和耶路撒冷，就是王那里。'),
('CUV', '历代志下', 14, 1, 15, '王在耶路撒冷使金银多如石头，香柏木多如高原的桑树。'),
('CUV', '历代志下', 14, 1, 16, '所罗门的马是从埃及带来的，是王的商人一群一群按著定价买来的。'),
('CUV', '历代志下', 14, 1, 17, '他们从埃及买来的车，每辆价银六百舍客勒，马每匹一百五十舍客勒。赫人诸王和亚兰诸王所买的车马，也是按这价值经他们手买来的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 2, 1, '所罗门定意要为耶和华的名建造殿宇，又为自己的国建造宫室。'),
('CUV', '历代志下', 14, 2, 2, '所罗门就挑选七万扛抬的，八万在山上凿石头的，三千六百督工的。'),
('CUV', '历代志下', 14, 2, 3, '所罗门差人去见推罗王希兰，说：你曾运香柏木与我父大卫建宫居住，求你也这样待我。'),
('CUV', '历代志下', 14, 2, 4, '我要为耶和华─我神的名建造殿宇，分别为圣献给他，在他面前焚烧美香，常摆陈设饼，每早晚、安息日、月朔，并耶和华─我们神所定的节期献燔祭。这是以色列人永远的定例。'),
('CUV', '历代志下', 14, 2, 5, '我所要建造的殿宇甚大；因为我们的神至大，超乎诸神。'),
('CUV', '历代志下', 14, 2, 6, '天和天上的天，尚且不足他居住的，谁能为他建造殿宇呢？我是谁？能为他建造殿宇吗？不过在他面前烧香而已。'),
('CUV', '历代志下', 14, 2, 7, '现在求你差一个巧匠来，就是善用金、银、铜、铁，和紫色、朱红色、蓝色线，并精于雕刻之工的巧匠，与我父大卫在犹大和耶路撒冷所预备的巧匠一同做工；'),
('CUV', '历代志下', 14, 2, 8, '又求你从利巴嫩运些香柏木、松木、檀香木到我这里来，因我知道你的仆人善于砍伐利巴嫩的树木。我的仆人也必与你的仆人同工。'),
('CUV', '历代志下', 14, 2, 9, '这样，可以给我预备许多的木料，因我要建造的殿宇高大出奇。'),
('CUV', '历代志下', 14, 2, 10, '你的仆人砍伐树木，我必给他们打好了的小麦二万歌珥，大麦二万歌珥，酒二万罢特，油二万罢特。'),
('CUV', '历代志下', 14, 2, 11, '推罗王希兰写信回答所罗门说：耶和华因为爱他的子民，所以立你作他们的王；'),
('CUV', '历代志下', 14, 2, 12, '又说：创造天地的耶和华─以色列的神是应当称颂的！他赐给大卫王一个有智慧的儿子，使他有谋略聪明，可以为耶和华建造殿宇，又为自己的国建造宫室。'),
('CUV', '历代志下', 14, 2, 13, '现在我打发一个精巧有聪明的人去，他是我父亲希兰所用的，'),
('CUV', '历代志下', 14, 2, 14, '是但支派一个妇人的儿子。他父亲是推罗人，他善用金、银、铜、铁、石、木，和紫色、蓝色、朱红色线与细麻制造各物，并精于雕刻，又能想出各样的巧工。请你派定这人，与你的巧匠和你父─我主大卫的巧匠一同做工。'),
('CUV', '历代志下', 14, 2, 15, '我主所说的小麦、大麦、酒、油，愿我主运来给众仆人。'),
('CUV', '历代志下', 14, 2, 16, '我们必照你所需用的，从利巴嫩砍伐树木，扎成筏子，浮海运到约帕；你可以从那里运到耶路撒冷。'),
('CUV', '历代志下', 14, 2, 17, '所罗门仿照他父大卫数点住在以色列地所有寄居的外邦人，共有十五万三千六百名；'),
('CUV', '历代志下', 14, 2, 18, '使七万人扛抬材料，八万人在山上凿石头，三千六百人督理工作。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 3, 1, '所罗门就在耶路撒冷、耶和华向他父大卫显现的摩利亚山上，就是耶布斯人阿珥楠的禾场上、大卫所指定的地方预备好了，开工建造耶和华的殿。'),
('CUV', '历代志下', 14, 3, 2, '所罗门作王第四年二月初二日开工建造。'),
('CUV', '历代志下', 14, 3, 3, '所罗门建筑神殿的根基，乃是这样：长六十肘，宽二十肘，都按著古时的尺寸。'),
('CUV', '历代志下', 14, 3, 4, '殿前的廊子长二十肘，与殿的宽窄一样，高一百二十肘；里面贴上精金。'),
('CUV', '历代志下', 14, 3, 5, '大殿的墙都用松木板遮蔽，又贴了精金，上面雕刻棕树和链子；'),
('CUV', '历代志下', 14, 3, 6, '又用宝石装饰殿墙，使殿华美；所用的金子都是巴瓦音的金子。'),
('CUV', '历代志下', 14, 3, 7, '又用金子贴殿和殿的栋梁、门槛、墙壁、门扇；墙上雕刻基路伯。'),
('CUV', '历代志下', 14, 3, 8, '又建造至圣所，长二十肘，与殿的宽窄一样，宽也是二十肘；贴上精金，共用金子六百他连得。'),
('CUV', '历代志下', 14, 3, 9, '金钉重五十舍客勒。楼房都贴上金子。'),
('CUV', '历代志下', 14, 3, 10, '在至圣所按造像的法子造两个基路伯，用金子包裹。'),
('CUV', '历代志下', 14, 3, 11, '两个基路伯的翅膀共长二十肘。这基路伯的一个翅膀长五肘，挨著殿这边的墙；那一个翅膀也长五肘，与那基路伯翅膀相接。'),
('CUV', '历代志下', 14, 3, 12, '那基路伯的一个翅膀长五肘，挨著殿那边的墙；那一个翅膀也长五肘，与这基路伯的翅膀相接。'),
('CUV', '历代志下', 14, 3, 13, '两个基路伯张开翅膀，共长二十肘，面向外殿而立。'),
('CUV', '历代志下', 14, 3, 14, '又用蓝色、紫色、朱红色线和细麻织幔子，在其上绣出基路伯来。'),
('CUV', '历代志下', 14, 3, 15, '在殿前造了两根柱子，高三十五肘；每柱顶高五肘。'),
('CUV', '历代志下', 14, 3, 16, '又照圣所内链子的样式做链子，安在柱顶上；又做一百石榴，安在链子上。'),
('CUV', '历代志下', 14, 3, 17, '将两根柱子立在殿前，一根在右边，一根在左边；右边的起名叫雅斤，左边的起名叫波阿斯。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 4, 1, '他又制造一座铜坛，长二十肘，宽二十肘，高十肘；'),
('CUV', '历代志下', 14, 4, 2, '又铸一个铜海，样式是圆的，高五肘，径十肘，围三十肘；'),
('CUV', '历代志下', 14, 4, 3, '海周围有野瓜(原文作牛)的样式，每肘十瓜，共有两行，是铸海的时候铸上的；'),
('CUV', '历代志下', 14, 4, 4, '有十二只铜牛驮海：三只向北，三只向西，三只向南，三只向东；海在牛上，牛尾向内；'),
('CUV', '历代志下', 14, 4, 5, '海厚一掌，边如杯边，又如百合花，可容三千罢特；'),
('CUV', '历代志下', 14, 4, 6, '又制造十个盆：五个放在右边，五个放在左边，献燔祭所用之物都洗在其内；但海是为祭司沐浴的。'),
('CUV', '历代志下', 14, 4, 7, '他又照所定的样式造十个金灯台放在殿里：五个在右边，五个在左边；'),
('CUV', '历代志下', 14, 4, 8, '又造十张桌子放在殿里：五张在右边，五张在左边；又造一百个金碗；'),
('CUV', '历代志下', 14, 4, 9, '又建立祭司院和大院，并院门，用铜包裹门扇；'),
('CUV', '历代志下', 14, 4, 10, '将海安在殿门的右边，就是南边。'),
('CUV', '历代志下', 14, 4, 11, '户兰又造了盆、铲、碗。这样，他为所罗门王做完了神殿的工。'),
('CUV', '历代志下', 14, 4, 12, '所造的就是：两根柱子和柱上两个如球的顶，并两个盖柱顶的网子'),
('CUV', '历代志下', 14, 4, 13, '和四百石榴，安在两个网子上〈每网两行盖著两个柱上如球的顶〉。'),
('CUV', '历代志下', 14, 4, 14, '盆座和其上的盆，'),
('CUV', '历代志下', 14, 4, 15, '海和海下的十二只牛，'),
('CUV', '历代志下', 14, 4, 16, '盆、铲子、肉锸子，与耶和华殿里的一切器皿，都是巧匠户兰用光亮的铜为所罗门王造成的，'),
('CUV', '历代志下', 14, 4, 17, '是在约但平原疏割和撒利但中间藉胶泥铸成的。'),
('CUV', '历代志下', 14, 4, 18, '所罗门制造的这一切甚多，铜的轻重无法可查。'),
('CUV', '历代志下', 14, 4, 19, '所罗门又造神殿里的金坛和陈设饼的桌子，'),
('CUV', '历代志下', 14, 4, 20, '并精金的灯台和灯盏，可以照例点在内殿前。'),
('CUV', '历代志下', 14, 4, 21, '灯台上的花和灯盏，并蜡剪都是金的，且是纯金的；'),
('CUV', '历代志下', 14, 4, 22, '又用精金制造镊子、盘子、调羹、火鼎。至于殿门和至圣所的门扇，并殿的门扇，都是金子妆饰的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 5, 1, '所罗门做完了耶和华殿的一切工，就把他父大卫分别为圣的金银和器皿都带来，放在神殿的府库里。'),
('CUV', '历代志下', 14, 5, 2, '那时，所罗门将以色列的长老、各支派的首领，并以色列的族长招聚到耶路撒冷，要把耶和华的约柜从大卫城─就是锡安─运上来。'),
('CUV', '历代志下', 14, 5, 3, '于是以色列众人在七月节前都聚集到王那里。'),
('CUV', '历代志下', 14, 5, 4, '以色列众长老来到，利未人便抬起约柜。'),
('CUV', '历代志下', 14, 5, 5, '祭司利未人将约柜运上来，又将会幕和会幕的一切圣器具都带上来。'),
('CUV', '历代志下', 14, 5, 6, '所罗门王和聚集到他那里的以色列全会众都在约柜前献牛羊为祭，多得不可胜数。'),
('CUV', '历代志下', 14, 5, 7, '祭司将耶和华的约柜抬进内殿，就是至圣所，放在两个基路伯的翅膀底下。'),
('CUV', '历代志下', 14, 5, 8, '基路伯张著翅膀在约柜之上，遮掩约柜和抬柜的杠。'),
('CUV', '历代志下', 14, 5, 9, '这杠甚长，杠头在内殿前可以看见，在殿外却不能看见，直到如今还在那里。'),
('CUV', '历代志下', 14, 5, 10, '约柜里惟有两块石版，就是以色列人出埃及后，耶和华与他们立约的时候，摩西在何烈山所放的。除此以外，并无别物。'),
('CUV', '历代志下', 14, 5, 11, '当时，在那里所有的祭司都已自洁，并不分班供职。'),
('CUV', '历代志下', 14, 5, 12, '他们出圣所的时候，歌唱的利未人亚萨、希幔、耶杜顿，和他们的众子众弟兄都穿细麻布衣服，站在坛的东边，敲钹、鼓瑟、弹琴，同著他们有一百二十个祭司吹号。'),
('CUV', '历代志下', 14, 5, 13, '吹号的、歌唱的都一齐发声，声合为一，赞美感谢耶和华。吹号、敲钹，用各种乐器，扬声赞美耶和华说：耶和华本为善，他的慈爱永远长存！那时，耶和华的殿有云充满，'),
('CUV', '历代志下', 14, 5, 14, '甚至祭司不能站立供职，因为耶和华的荣光充满了神的殿。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 6, 1, '那时，所罗门说：耶和华曾说他必住在幽暗之处。'),
('CUV', '历代志下', 14, 6, 2, '但我已经建造殿宇作你的居所，为你永远的住处。'),
('CUV', '历代志下', 14, 6, 3, '王转脸为以色列会众祝福，以色列会众就都站立。'),
('CUV', '历代志下', 14, 6, 4, '所罗门说：耶和华─以色列的神是应当称颂的！因他亲口向我父大卫所应许的，也亲手成就了。'),
('CUV', '历代志下', 14, 6, 5, '他说：自从我领我民出埃及地以来，我未曾在以色列众支派中选择一城建造殿宇为我名的居所，也未曾拣选一人作我民以色列的君；'),
('CUV', '历代志下', 14, 6, 6, '但选择耶路撒冷为我名的居所，又拣选大卫治理我民以色列。'),
('CUV', '历代志下', 14, 6, 7, '所罗门说：我父大卫曾立意要为耶和华─以色列神的名建殿，'),
('CUV', '历代志下', 14, 6, 8, '耶和华却对我父大卫说：你立意要为我的名建殿，这意思甚好；'),
('CUV', '历代志下', 14, 6, 9, '只是你不可建殿，惟你所生的儿子必为我名建殿。'),
('CUV', '历代志下', 14, 6, 10, '现在耶和华成就了他所应许的话，使我接续我父大卫坐以色列的国位，是照耶和华所说的，又为耶和华─以色列神的名建造了殿。'),
('CUV', '历代志下', 14, 6, 11, '我将约柜安置在其中，柜内有耶和华的约，就是他与以色列人所立的约。'),
('CUV', '历代志下', 14, 6, 12, '所罗门当著以色列会众，站在耶和华的坛前，举起手来，'),
('CUV', '历代志下', 14, 6, 13, '〈所罗门曾造一个铜台，长五肘，宽五肘，高三肘，放在院中〉就站在台上，当著以色列的会众跪下，向天举手，'),
('CUV', '历代志下', 14, 6, 14, '说：耶和华─以色列的神啊，天上地下没有神可比你的！你向那尽心行在你面前的仆人守约施慈爱；'),
('CUV', '历代志下', 14, 6, 15, '向你仆人─我父大卫所应许的话现在应验了。你亲口应许，亲手成就，正如今日一样。'),
('CUV', '历代志下', 14, 6, 16, '耶和华─以色列的神啊，你所应许你仆人─我父大卫的话说：你的子孙若谨慎自己的行为，遵守我的律法，像你在我面前所行的一样，就不断人坐以色列的国位。现在求你应验这话。'),
('CUV', '历代志下', 14, 6, 17, '耶和华─以色列的神啊，求你成就向你仆人大卫所应许的话。'),
('CUV', '历代志下', 14, 6, 18, '神果真与世人同住在地上么？看哪，天和天上的天尚且不足你居住的，何况我所建的这殿呢？'),
('CUV', '历代志下', 14, 6, 19, '惟求耶和华─我的神垂顾仆人的祷告祈求，俯听仆人在你面前的祈祷呼吁。'),
('CUV', '历代志下', 14, 6, 20, '愿你昼夜看顾这殿，就是你应许立为你名的居所；求你垂听仆人向此处祷告的话。'),
('CUV', '历代志下', 14, 6, 21, '你仆人和你民以色列向此处祈祷的时候，求你从天上你的居所垂听，垂听而赦免。'),
('CUV', '历代志下', 14, 6, 22, '人若得罪邻舍，有人叫他起誓，他来到这殿，在你的坛前起誓，'),
('CUV', '历代志下', 14, 6, 23, '求你从天上垂听，判断你的仆人，定恶人有罪，照他所行的报应在他头上；定义人有理，照他的义赏赐他。'),
('CUV', '历代志下', 14, 6, 24, '你的民以色列若得罪你，败在仇敌面前，又回心转意承认你的名，在这殿里向你祈求祷告，'),
('CUV', '历代志下', 14, 6, 25, '求你从天上垂听，赦免你民以色列的罪，使他们归回你赐给他们和他们列祖之地。'),
('CUV', '历代志下', 14, 6, 26, '你的民因得罪你，你惩罚他们，使天闭塞不下雨，他们若向此处祷告，承认你的名，离开他们的罪，'),
('CUV', '历代志下', 14, 6, 27, '求你在天上垂听，赦免你仆人和你民以色列的罪，将当行的善道指教他们，且降雨在你的地，就是你赐给你民为业之地。'),
('CUV', '历代志下', 14, 6, 28, '国中若有饥荒、瘟疫、旱风、霉烂、蝗虫、蚂蚱，或有仇敌犯境，围困城邑，无论遭遇甚么灾祸疾病，'),
('CUV', '历代志下', 14, 6, 29, '你的民以色列，或是众人，或是一人，自觉灾祸甚苦，向这殿举手，无论祈求甚么，祷告甚么，'),
('CUV', '历代志下', 14, 6, 30, '求你从天上你的居所垂听赦免。你是知道人心的，要照各人所行的待他们（惟有你知道世人的心），'),
('CUV', '历代志下', 14, 6, 31, '使他们在你赐给我们列祖之地上一生一世敬畏你，遵行你的道。'),
('CUV', '历代志下', 14, 6, 32, '论到不属你民以色列的外邦人，为你的大名和大能的手，并伸出来的膀臂，从远方而来，向这殿祷告，'),
('CUV', '历代志下', 14, 6, 33, '求你从天上你的居所垂听，照著外邦人所祈求的而行，使天下万民都认识你的名，敬畏你，像你的民以色列一样，又使他们知道我建造的这殿是称为你名下的。'),
('CUV', '历代志下', 14, 6, 34, '你的民若奉你的差遣，无论往何处去与仇敌争战，向你所选择的城与我为你名所建造的殿祷告，'),
('CUV', '历代志下', 14, 6, 35, '求你从天上垂听他们的祷告祈求，使他们得胜。'),
('CUV', '历代志下', 14, 6, 36, '你的民若得罪你（世上没有不犯罪的人），你向他们发怒，将他们交给仇敌掳到或远或近之地；'),
('CUV', '历代志下', 14, 6, 37, '他们若在掳到之地想起罪来，回心转意，恳求你说：我们有罪了，我们悖逆了，我们作恶了；'),
('CUV', '历代志下', 14, 6, 38, '他们若在掳到之地尽心尽性归服你，又向自己的地，就是你赐给他们列祖之地和你所选择的城，并我为你名所建造的殿祷告，'),
('CUV', '历代志下', 14, 6, 39, '求你从天上你的居所垂听你民的祷告祈求，为他们伸冤，赦免他们的过犯。'),
('CUV', '历代志下', 14, 6, 40, '我的神啊，现在求你睁眼看，侧耳听在此处所献的祷告。'),
('CUV', '历代志下', 14, 6, 41, '耶和华神啊，求你起来，和你有能力的约柜同入安息之所。耶和华神啊，愿你的祭司披上救恩；愿你的圣民蒙福欢乐。'),
('CUV', '历代志下', 14, 6, 42, '耶和华神啊，求你不要厌弃你的受膏者，要记念向你仆人大卫所施的慈爱。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 7, 1, '所罗门祈祷已毕，就有火从天上降下来，烧尽燔祭和别的祭。耶和华的荣光充满了殿；'),
('CUV', '历代志下', 14, 7, 2, '因耶和华的荣光充满了耶和华殿，所以祭司不能进殿。'),
('CUV', '历代志下', 14, 7, 3, '那火降下、耶和华的荣光在殿上的时候，以色列众人看见，就在铺石地俯伏叩拜，称谢耶和华说：耶和华本为善，他的慈爱永远长存！'),
('CUV', '历代志下', 14, 7, 4, '王和众民在耶和华面前献祭。'),
('CUV', '历代志下', 14, 7, 5, '所罗门王用牛二万二千，羊十二万献祭。这样，王和众民为神的殿行奉献之礼。'),
('CUV', '历代志下', 14, 7, 6, '祭司侍立，各供其职；利未人也拿著耶和华的乐器，就是大卫王造出来、藉利未人颂赞耶和华的。（他的慈爱永远长存！）祭司在众人面前吹号，以色列人都站立。'),
('CUV', '历代志下', 14, 7, 7, '所罗门因他所造的铜坛容不下燔祭、素祭，和脂油，便将耶和华殿前院子当中分别为圣，在那里献燔祭和平安祭牲的脂油。'),
('CUV', '历代志下', 14, 7, 8, '那时所罗门和以色列众人，就是从哈马口直到埃及小河，所有的以色列人都聚集成为大会，守节七日。'),
('CUV', '历代志下', 14, 7, 9, '第八日设立严肃会，行奉献坛的礼七日，守节七日。'),
('CUV', '历代志下', 14, 7, 10, '七月二十三日，王遣散众民；他们因见耶和华向大卫和所罗门与他民以色列所施的恩惠，就都心中喜乐，各归各家去了。'),
('CUV', '历代志下', 14, 7, 11, '所罗门造成了耶和华殿和王宫；在耶和华殿和王宫凡他心中所要做的，都顺顺利利地做成了。'),
('CUV', '历代志下', 14, 7, 12, '夜间耶和华向所罗门显现，对他说：我已听了你的祷告，也选择这地方作为祭祀我的殿宇。'),
('CUV', '历代志下', 14, 7, 13, '我若使天闭塞不下雨，或使蝗虫吃这地的出产，或使瘟疫流行在我民中，'),
('CUV', '历代志下', 14, 7, 14, '这称为我名下的子民，若是自卑、祷告，寻求我的面，转离他们的恶行，我必从天上垂听，赦免他们的罪，医治他们的地。'),
('CUV', '历代志下', 14, 7, 15, '我必睁眼看、侧耳听在此处所献的祷告。'),
('CUV', '历代志下', 14, 7, 16, '现在我已选择这殿，分别为圣，使我的名永在其中，我的眼、我的心也必常在那里。'),
('CUV', '历代志下', 14, 7, 17, '你若在我面前效法你父大卫所行的，遵行我一切所吩咐你的，谨守我的律例典章，'),
('CUV', '历代志下', 14, 7, 18, '我就必坚固你的国位，正如我与你父大卫所立的约，说：你的子孙必不断人作以色列的王。'),
('CUV', '历代志下', 14, 7, 19, '倘若你们转去丢弃我指示你们的律例诫命，去事奉敬拜别神，'),
('CUV', '历代志下', 14, 7, 20, '我就必将以色列人从我赐给他们的地上拔出根来，并且我为己名所分别为圣的殿也必舍弃不顾，使他在万民中作笑谈，被讥诮。'),
('CUV', '历代志下', 14, 7, 21, '这殿虽然甚高，将来经过的人必惊讶说：耶和华为何向这地和这殿如此行呢？'),
('CUV', '历代志下', 14, 7, 22, '人必回答说：是因此地的人离弃耶和华─他们列祖的神，就是领他们出埃及地的神，去亲近别神，敬拜事奉他，所以耶和华使这一切灾祸临到他们。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 8, 1, '所罗门建造耶和华殿和王宫，二十年才完毕了。'),
('CUV', '历代志下', 14, 8, 2, '以后所罗门重新修筑希兰送给他的那些城邑，使以色列人住在那里。'),
('CUV', '历代志下', 14, 8, 3, '所罗门往哈马琐巴去，攻取了那地方。'),
('CUV', '历代志下', 14, 8, 4, '所罗门建造旷野里的达莫，又建造哈马所有的积货城，'),
('CUV', '历代志下', 14, 8, 5, '又建造上伯和仑、下伯和仑作为保障，都有墙，有门，有闩；'),
('CUV', '历代志下', 14, 8, 6, '又建造巴拉和所有的积货城，并屯车辆马兵的城，与耶路撒冷、利巴嫩，以及自己治理的全国中所愿意建造的。'),
('CUV', '历代志下', 14, 8, 7, '至于国中所剩下不属以色列人的赫人、亚摩利人、比利洗人、希未人、耶布斯人，'),
('CUV', '历代志下', 14, 8, 8, '就是以色列人未曾灭绝的，所罗门挑取他们的后裔作服苦的奴仆，直到今日。'),
('CUV', '历代志下', 14, 8, 9, '惟有以色列人，所罗门不使他们当奴仆做工，乃是作他的战士、军长的统领、车兵长、马兵长。'),
('CUV', '历代志下', 14, 8, 10, '所罗门王有二百五十督工的，监管工人。'),
('CUV', '历代志下', 14, 8, 11, '所罗门将法老的女儿带出大卫城，上到为他建造的宫里；因所罗门说：耶和华约柜所到之处都为圣地，所以我的妻不可住在以色列王大卫的宫里。'),
('CUV', '历代志下', 14, 8, 12, '所罗门在耶和华的坛上，就是在廊子前他所筑的坛上，与耶和华献燔祭；'),
('CUV', '历代志下', 14, 8, 13, '又遵著摩西的吩咐在安息日、月朔，并一年三节，就是除酵节、七七节、住棚节，献每日所当献的祭。'),
('CUV', '历代志下', 14, 8, 14, '所罗门照著他父大卫所定的例，派定祭司的班次，使他们各供己事，又使利未人各尽其职，赞美耶和华，在祭司面前做每日所当做的；又派守门的按著班次看守各门，因为神人大卫是这样吩咐的。'),
('CUV', '历代志下', 14, 8, 15, '王所吩咐众祭司和利未人的，无论是管府库或办别的事，他们都不违背。'),
('CUV', '历代志下', 14, 8, 16, '所罗门建造耶和华的殿，从立根基直到成功的日子，工料俱备。这样，耶和华的殿全然完毕。'),
('CUV', '历代志下', 14, 8, 17, '那时，所罗门往以东地靠海的以旬迦别和以禄去。'),
('CUV', '历代志下', 14, 8, 18, '希兰差遣他的臣仆，将船只和熟悉泛海的仆人送到所罗门那里。他们同著所罗门的仆人到了俄斐，得了四百五十他连得金子，运到所罗门王那里。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 9, 1, '示巴女王听见所罗门的名声，就来到耶路撒冷，要用难解的话试问所罗门；跟随他的人甚多，又有骆驼驮著香料、宝石，和许多金子。他来见了所罗门，就把心里所有的对所罗门都说出来。'),
('CUV', '历代志下', 14, 9, 2, '所罗门将他所问的都答上了，没有一句不明白、不能答的。'),
('CUV', '历代志下', 14, 9, 3, '示巴女王见所罗门的智慧和他所建造的宫室、'),
('CUV', '历代志下', 14, 9, 4, '席上的珍馐美味、群臣分列而坐、仆人两旁侍立，以及他们的衣服装饰、酒政，和酒政的衣服装饰，又见他上耶和华殿的台阶，就诧异得神不守舍，'),
('CUV', '历代志下', 14, 9, 5, '对王说：我在本国里所听见论到你的事和你的智慧实在是真的！'),
('CUV', '历代志下', 14, 9, 6, '我先不信那些话，及至我来亲眼见了，才知道你的大智慧；人所告诉我的，还不到一半；你的实迹越过我所听见的名声。'),
('CUV', '历代志下', 14, 9, 7, '你的群臣、你的仆人常侍立在你面前听你智慧的话是有福的。'),
('CUV', '历代志下', 14, 9, 8, '耶和华─你的神是应当称颂的！他喜悦你，使你坐他的国位，为耶和华─你的神作王；因为你的神爱以色列人，要永远坚立他们，所以立你作他们的王，使你秉公行义。'),
('CUV', '历代志下', 14, 9, 9, '于是示巴女王将一百二十他连得金子和宝石，与极多的香料送给所罗门王；他送给王的香料，以后再没有这样的。'),
('CUV', '历代志下', 14, 9, 10, '希兰的仆人和所罗门的仆人从俄斐运了金子来，也运了檀香木(或作乌木；下同)和宝石来。'),
('CUV', '历代志下', 14, 9, 11, '王用檀香木为耶和华殿和王宫做台，又为歌唱的人做琴瑟；犹大地从来没有见过这样的。'),
('CUV', '历代志下', 14, 9, 12, '所罗门王按示巴女王所带来的，还他礼物，另外照他一切所要所求的，都送给他。于是女王和他臣仆转回本国去了。'),
('CUV', '历代志下', 14, 9, 13, '所罗门每年所得的金子共有六百六十六他连得，'),
('CUV', '历代志下', 14, 9, 14, '另外还有商人所进的金子，并且亚拉伯诸王与属国的省长都带金银给所罗门。'),
('CUV', '历代志下', 14, 9, 15, '所罗门王用锤出来的金子打成挡牌二百面，每面用金子六百舍客勒；'),
('CUV', '历代志下', 14, 9, 16, '又用锤出来的金子打成盾牌三百面，每面用金子三百舍客勒，都放在利巴嫩林宫里。'),
('CUV', '历代志下', 14, 9, 17, '王用象牙制造一个大宝座，用精金包裹。'),
('CUV', '历代志下', 14, 9, 18, '宝座有六层台阶，又有金脚凳，与宝座相连。宝座两旁有扶手，靠近扶手有两个狮子站立。'),
('CUV', '历代志下', 14, 9, 19, '六层台阶上有十二个狮子站立，每层有两个：左边一个，右边一个；在列国中没有这样做的。'),
('CUV', '历代志下', 14, 9, 20, '所罗门王一切的饮器都是金的，利巴嫩林宫里的一切器皿都是精金的。所罗门年间，银子算不了甚么。'),
('CUV', '历代志下', 14, 9, 21, '因为王的船只与希兰的仆人一同往他施去；他施船只三年一次装载金、银、象牙、猿猴、孔雀回来。'),
('CUV', '历代志下', 14, 9, 22, '所罗门王的财宝与智慧胜过天下的列王。'),
('CUV', '历代志下', 14, 9, 23, '普天下的王都求见所罗门，要听神赐给他智慧的话。'),
('CUV', '历代志下', 14, 9, 24, '他们各带贡物，就是金器、银器、衣服、军械、香料、骡马，每年有一定之例。'),
('CUV', '历代志下', 14, 9, 25, '所罗门有套车的马四千棚，有马兵一万二千，安置在屯车的城邑和耶路撒冷，就是王那里。'),
('CUV', '历代志下', 14, 9, 26, '所罗门统管诸王，从大河到非利士地，直到埃及的边界。'),
('CUV', '历代志下', 14, 9, 27, '王在耶路撒冷使银子多如石头，香柏木多如高原的桑树。'),
('CUV', '历代志下', 14, 9, 28, '有人从埃及和各国为所罗门赶马群来。'),
('CUV', '历代志下', 14, 9, 29, '所罗门其余的事，自始至终，不都写在先知拿单的书上和示罗人亚希雅的预言书上，并先见易多论尼八儿子耶罗波安的默示书上么？'),
('CUV', '历代志下', 14, 9, 30, '所罗门在耶路撒冷作以色列众人的王共四十年。'),
('CUV', '历代志下', 14, 9, 31, '所罗门与他列祖同睡，葬在他父大卫城里。他儿子罗波安接续他作王。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 10, 1, '罗波安往示剑去，因为以色列人都到了示剑，要立他作王。'),
('CUV', '历代志下', 14, 10, 2, '尼八的儿子耶罗波安先前躲避所罗门王，逃往埃及，住在那里；他听见这事，就从埃及回来。'),
('CUV', '历代志下', 14, 10, 3, '以色列人打发人去请他，他就和以色列众人来见罗波安，对他说：'),
('CUV', '历代志下', 14, 10, 4, '你父亲使我们负重轭做苦工，现在求你使我们做的苦工负的重轭轻松些，我们就事奉你。'),
('CUV', '历代志下', 14, 10, 5, '罗波安对他们说：第三日再来见我罢！民就去了。'),
('CUV', '历代志下', 14, 10, 6, '罗波安之父所罗门在世的日子，有侍立在他面前的老年人，罗波安王和他们商议，说：你们给我出个甚么主意，我好回复这民。'),
('CUV', '历代志下', 14, 10, 7, '老年人对他说：王若恩待这民，使他们喜悦，用好话回复他们，他们就永远作王的仆人。'),
('CUV', '历代志下', 14, 10, 8, '王却不用老年人给他出的主意，就和那些与他一同长大、在他面前侍立的少年人商议，'),
('CUV', '历代志下', 14, 10, 9, '说：这民对我说：你父亲使我们负重轭，求你使我们轻松些；你们给我出个甚么主意，我好回复他们。'),
('CUV', '历代志下', 14, 10, 10, '那同他长大的少年人说：这民对王说：你父亲使我们负重轭，求你使我们轻松些；王要对他们如此说：我的小拇指比我父亲的腰还粗；'),
('CUV', '历代志下', 14, 10, 11, '我父亲使你们负重轭，我必使你们负更重的轭；我父亲用鞭子责打你们，我要用蝎子鞭责打你们。'),
('CUV', '历代志下', 14, 10, 12, '耶罗波安和众百姓遵著罗波安王所说你们第三日再来见我的那话，第三日他们果然来了。'),
('CUV', '历代志下', 14, 10, 13, '罗波安王用严厉的话回复他们，不用老年人所出的主意，'),
('CUV', '历代志下', 14, 10, 14, '照著少年人所出的主意对他们说：我父亲使你们负重轭，我必使你们负更重的轭；我父亲用鞭子责打你们，我要用蝎子鞭责打你们。'),
('CUV', '历代志下', 14, 10, 15, '王不肯依从百姓；这事乃出于神，为要应验耶和华藉示罗人亚希雅对尼八儿子耶罗波安所说的话。'),
('CUV', '历代志下', 14, 10, 16, '以色列众民见王不依从他们，就对王说：我们与大卫有甚么分儿呢？与耶西的儿子并没有关涉！以色列人哪，各回各家去罢！大卫家啊，自己顾自己罢！于是，以色列众人都回自己家里去了。'),
('CUV', '历代志下', 14, 10, 17, '惟独住在犹大城邑的以色列人，罗波安仍作他们的王。'),
('CUV', '历代志下', 14, 10, 18, '罗波安王差遣掌管服苦之人的哈多兰往以色列人那里去，以色列人就用石头打死他。罗波安王急忙上车，逃回耶路撒冷去了。'),
('CUV', '历代志下', 14, 10, 19, '这样，以色列人背叛大卫家，直到今日。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 11, 1, '罗波安来到耶路撒冷，招聚犹大家和便雅悯家，共十八万人，都是挑选的战士，要与以色列人争战，好将国夺回再归自己。'),
('CUV', '历代志下', 14, 11, 2, '但耶和华的话临到神人示玛雅说：'),
('CUV', '历代志下', 14, 11, 3, '你去告诉所罗门的儿子犹大王罗波安和住犹大、便雅悯的以色列众人说，'),
('CUV', '历代志下', 14, 11, 4, '耶和华如此说：你们不可上去与你们的弟兄争战，各归各家去罢！因为这事出于我。众人就听从耶和华的话归回，不去与耶罗波安争战。'),
('CUV', '历代志下', 14, 11, 5, '罗波安住在耶路撒冷，在犹大地修筑城邑，'),
('CUV', '历代志下', 14, 11, 6, '为保障修筑伯利恒、以坦、提哥亚、'),
('CUV', '历代志下', 14, 11, 7, '伯夙、梭哥、亚杜兰、'),
('CUV', '历代志下', 14, 11, 8, '迦特、玛利沙、西弗、'),
('CUV', '历代志下', 14, 11, 9, '亚多莱音、拉吉、亚西加、'),
('CUV', '历代志下', 14, 11, 10, '琐拉、亚雅仑、希伯仑。这都是犹大和便雅悯的坚固城。'),
('CUV', '历代志下', 14, 11, 11, '罗波安又坚固各处的保障，在其中安置军长，又预备下粮食、油、酒。'),
('CUV', '历代志下', 14, 11, 12, '他在各城里预备盾牌和枪，且使城极其坚固。犹大和便雅悯都归了他。'),
('CUV', '历代志下', 14, 11, 13, '以色列全地的祭司和利未人都从四方来归罗波安。'),
('CUV', '历代志下', 14, 11, 14, '利未人撇下他们的郊野和产业，来到犹大与耶路撒冷，是因耶罗波安和他的儿子拒绝他们，不许他们供祭司职分事奉耶和华。'),
('CUV', '历代志下', 14, 11, 15, '耶罗波安为邱坛、为鬼魔(原文作公山羊)、为自己所铸造的牛犊设立祭司。'),
('CUV', '历代志下', 14, 11, 16, '以色列各支派中，凡立定心意寻求耶和华─以色列神的，都随从利未人，来到耶路撒冷祭祀耶和华─他们列祖的神。'),
('CUV', '历代志下', 14, 11, 17, '这样，就坚固犹大国，使所罗门的儿子罗波安强盛三年，因为他们三年遵行大卫和所罗门的道。'),
('CUV', '历代志下', 14, 11, 18, '罗波安娶大卫儿子耶利摩的女儿玛哈拉为妻，又娶耶西儿子以利押的女儿亚比孩为妻。'),
('CUV', '历代志下', 14, 11, 19, '从他生了几个儿子，就是耶乌施、示玛利雅、撒罕。'),
('CUV', '历代志下', 14, 11, 20, '后来又娶押沙龙的女儿玛迦(十三章二节作乌列的女儿米该雅)，从他生了亚比雅、亚太、细撒、示罗密。'),
('CUV', '历代志下', 14, 11, 21, '罗波安娶十八个妻，立六十个妾，生二十八个儿子，六十个女儿；他却爱押沙龙的女儿玛迦，比爱别的妻妾更甚。'),
('CUV', '历代志下', 14, 11, 22, '罗波安立玛迦的儿子亚比雅作太子，在他弟兄中为首，因为想要立他接续作王。'),
('CUV', '历代志下', 14, 11, 23, '罗波安办事精明，使他众子分散在犹大和便雅悯全地各坚固城里，又赐他们许多粮食，为他们多寻妻子。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 12, 1, '罗波安的国坚立，他强盛的时候就离弃耶和华的律法，以色列人也都随从他。'),
('CUV', '历代志下', 14, 12, 2, '罗波安王第五年，埃及王示撒上来攻打耶路撒冷，因为王和民得罪了耶和华。'),
('CUV', '历代志下', 14, 12, 3, '示撒带战车一千二百辆，马兵六万，并且跟从他出埃及的路比人、苏基人，和古实人，多得不可胜数。'),
('CUV', '历代志下', 14, 12, 4, '他攻取了犹大的坚固城，就来到耶路撒冷。'),
('CUV', '历代志下', 14, 12, 5, '那时，犹大的首领因为示撒就聚集在耶路撒冷。有先知示玛雅去见罗波安和众首领，对他们说：耶和华如此说：你们离弃了我，所以我使你们落在示撒手里。'),
('CUV', '历代志下', 14, 12, 6, '于是王和以色列的众首领都自卑说：耶和华是公义的。'),
('CUV', '历代志下', 14, 12, 7, '耶和华见他们自卑，耶和华的话就临到示玛雅说：他们既自卑，我必不灭绝他们；必使他们略得拯救，我不藉著示撒的手将我的怒气倒在耶路撒冷。'),
('CUV', '历代志下', 14, 12, 8, '然而他们必作示撒的仆人，好叫他们知道，服事我与服事外邦人有何分别。'),
('CUV', '历代志下', 14, 12, 9, '于是，埃及王示撒上来攻取耶路撒冷，夺了耶和华殿和王宫里的宝物，尽都带走，又夺去所罗门制造的金盾牌。'),
('CUV', '历代志下', 14, 12, 10, '罗波安王制造铜盾牌代替那金盾牌，交给守王宫门的护卫长看守。'),
('CUV', '历代志下', 14, 12, 11, '王每逢进耶和华的殿，护卫兵就拿这盾牌，随后仍将盾牌送回，放在护卫房。'),
('CUV', '历代志下', 14, 12, 12, '王自卑的时候，耶和华的怒气就转消了，不将他灭尽，并且在犹大中间也有善益的事。'),
('CUV', '历代志下', 14, 12, 13, '罗波安王自强，在耶路撒冷作王。他登基的时候年四十一岁，在耶路撒冷，就是耶和华从以色列众支派中所选择立他名的城，作王十七年。罗波安的母亲名叫拿玛，是亚扪人。'),
('CUV', '历代志下', 14, 12, 14, '罗波安行恶，因他不立定心意寻求耶和华。'),
('CUV', '历代志下', 14, 12, 15, '罗波安所行的事，自始至终不都写在先知示玛雅和先见易多的史记上么？罗波安与耶罗波安时常争战。'),
('CUV', '历代志下', 14, 12, 16, '罗波安与他列祖同睡，葬在大卫城里。他儿子亚比雅接续他作王。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 13, 1, '耶罗波安王十八年，亚比雅登基作犹大王，'),
('CUV', '历代志下', 14, 13, 2, '在耶路撒冷作王三年。他母亲名叫米该亚(又作玛迦)，是基比亚人乌列的女儿。亚比雅常与耶罗波安争战。'),
('CUV', '历代志下', 14, 13, 3, '有一次亚比雅率领挑选的兵四十万摆阵，都是勇敢的战士；耶罗波安也挑选大能的勇士八十万，对亚比雅摆阵。'),
('CUV', '历代志下', 14, 13, 4, '亚比雅站在以法莲山地中的洗玛脸山上，说：耶罗波安和以色列众人哪，要听我说！'),
('CUV', '历代志下', 14, 13, 5, '耶和华─以色列的神曾立盐(即不废坏的意思)约，将以色列国永远赐给大卫和他的子孙，你们不知道么？'),
('CUV', '历代志下', 14, 13, 6, '无奈大卫儿子所罗门的臣仆、尼八儿子耶罗波安起来背叛他的主人。'),
('CUV', '历代志下', 14, 13, 7, '有些无赖的匪徒聚集跟从他，逞强攻击所罗门的儿子罗波安；那时罗波安还幼弱，不能抵挡他们。'),
('CUV', '历代志下', 14, 13, 8, '现在你们有意抗拒大卫子孙手下所治耶和华的国，你们的人也甚多，你们那里又有耶罗波安为你们所造当作神的金牛犊。'),
('CUV', '历代志下', 14, 13, 9, '你们不是驱逐耶和华的祭司亚伦的后裔和利未人么？不是照著外邦人的恶俗为自己立祭司么？无论何人牵一只公牛犊、七只公绵羊将自己分别出来，就可作虚无之神的祭司。'),
('CUV', '历代志下', 14, 13, 10, '至于我们，耶和华是我们的神，我们并没有离弃他。我们有事奉耶和华的祭司，都是亚伦的后裔，并有利未人各尽其职，'),
('CUV', '历代志下', 14, 13, 11, '每日早晚向耶和华献燔祭，烧美香，又在精金的桌子上摆陈设饼；又有金灯台和灯盏，每晚点起，因为我们遵守耶和华─我们神的命；惟有你们离弃了他。'),
('CUV', '历代志下', 14, 13, 12, '率领我们的是神，我们这里也有神的祭司拿号向你们吹出大声。以色列人哪，不要与耶和华─你们列祖的神争战，因你们必不能亨通。'),
('CUV', '历代志下', 14, 13, 13, '耶罗波安却在犹大人的后头设伏兵。这样，以色列人在犹大人的前头，伏兵在犹大人的后头。'),
('CUV', '历代志下', 14, 13, 14, '犹大人回头观看，见前后都有敌兵，就呼求耶和华，祭司也吹号。'),
('CUV', '历代志下', 14, 13, 15, '于是犹大人呐喊；犹大人呐喊的时候，神就使耶罗波安和以色列众人败在亚比雅与犹大人面前。'),
('CUV', '历代志下', 14, 13, 16, '以色列人在犹大人面前逃跑，神将他们交在犹大人手里。'),
('CUV', '历代志下', 14, 13, 17, '亚比雅和他的军兵大大杀戮以色列人，以色列人仆倒死亡的精兵有五十万。'),
('CUV', '历代志下', 14, 13, 18, '那时，以色列人被制伏了，犹大人得胜，是因倚靠耶和华─他们列祖的神。'),
('CUV', '历代志下', 14, 13, 19, '亚比雅追赶耶罗波安，攻取了他的几座城，就是伯特利和属伯特利的镇市，耶沙拿和属耶沙拿的镇市，以法拉音(或作以弗伦)和属以法拉音的镇市。'),
('CUV', '历代志下', 14, 13, 20, '亚比雅在世的时候，耶罗波安不能再强盛；耶和华攻击他，他就死了。'),
('CUV', '历代志下', 14, 13, 21, '亚比雅却渐渐强盛，娶妻妾十四个，生了二十二个儿子，十六个女儿。'),
('CUV', '历代志下', 14, 13, 22, '亚比雅其余的事和他的言行都写在先知易多的传上。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 14, 1, '亚比雅与他列祖同睡，葬在大卫城里。他儿子亚撒接续他作王。亚撒年间，国中太平十年。'),
('CUV', '历代志下', 14, 14, 2, '亚撒行耶和华─他神眼中看为善为正的事，'),
('CUV', '历代志下', 14, 14, 3, '除掉外邦神的坛和邱坛，打碎柱像，砍下木偶，'),
('CUV', '历代志下', 14, 14, 4, '吩咐犹大人寻求耶和华─他们列祖的神，遵行他的律法、诫命；'),
('CUV', '历代志下', 14, 14, 5, '又在犹大各城邑除掉邱坛和日像，那时国享太平；'),
('CUV', '历代志下', 14, 14, 6, '又在犹大建造了几座坚固城。国中太平数年，没有战争，因为耶和华赐他平安。'),
('CUV', '历代志下', 14, 14, 7, '他对犹大人说：我们要建造这些城邑，四围筑墙，盖楼，安门，做闩；地还属我们，是因寻求耶和华─我们的神；我们既寻求他，他就赐我们四境平安。于是建造城邑，诸事亨通。'),
('CUV', '历代志下', 14, 14, 8, '亚撒的军兵，出自犹大拿盾牌拿枪的三十万人；出自便雅悯拿盾牌拉弓的二十八万人。这都是大能的勇士。'),
('CUV', '历代志下', 14, 14, 9, '有古实王谢拉率领军兵一百万，战车三百辆，出来攻击犹大人，到了玛利沙。'),
('CUV', '历代志下', 14, 14, 10, '于是亚撒出去与他迎敌，就在玛利沙的洗法谷彼此摆阵。'),
('CUV', '历代志下', 14, 14, 11, '亚撒呼求耶和华─他的神说：耶和华啊，惟有你能帮助软弱的，胜过强盛的。耶和华─我们的神啊，求你帮助我们；因为我们仰赖你，奉你的名来攻击这大军。耶和华啊，你是我们的神，不要容人胜过你。'),
('CUV', '历代志下', 14, 14, 12, '于是耶和华使古实人败在亚撒和犹大人面前，古实人就逃跑了；'),
('CUV', '历代志下', 14, 14, 13, '亚撒和跟随他的军兵追赶他们，直到基拉耳。古实人被杀的甚多，不能再强盛，因为败在耶和华与他军兵面前。犹大人就夺了许多财物，'),
('CUV', '历代志下', 14, 14, 14, '又打破基拉耳四围的城邑；耶和华使其中的人都甚恐惧。犹大人又将所有的城掳掠一空，因其中的财物甚多，'),
('CUV', '历代志下', 14, 14, 15, '又毁坏了群畜的圈，夺取许多的羊和骆驼，就回耶路撒冷去了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 15, 1, '神的灵感动俄德的儿子亚撒利雅。'),
('CUV', '历代志下', 14, 15, 2, '他出来迎接亚撒，对他说：亚撒和犹大、便雅悯众人哪，要听我说：你们若顺从耶和华，耶和华必与你们同在；你们若寻求他，就必寻见；你们若离弃他，他必离弃你们。'),
('CUV', '历代志下', 14, 15, 3, '以色列人不信真神，没有训诲的祭司，也没有律法，已经好久了；'),
('CUV', '历代志下', 14, 15, 4, '但他们在急难的时候归向耶和华─以色列的神，寻求他，他就被他们寻见。'),
('CUV', '历代志下', 14, 15, 5, '那时，出入的人不得平安，列国的居民都遭大乱；'),
('CUV', '历代志下', 14, 15, 6, '这国攻击那国，这城攻击那城，互相破坏，因为神用各样灾难扰乱他们。'),
('CUV', '历代志下', 14, 15, 7, '现在你们要刚强，不要手软，因你们所行的必得赏赐。'),
('CUV', '历代志下', 14, 15, 8, '亚撒听见这话和俄德儿子先知亚撒利雅的预言，就壮起胆来，在犹大、便雅悯全地，并以法莲山地所夺的各城，将可憎之物尽都除掉，又在耶和华殿的廊前重新修筑耶和华的坛；'),
('CUV', '历代志下', 14, 15, 9, '又招聚犹大、便雅悯的众人，并他们中间寄居的以法莲人、玛拿西人、西缅人。有许多以色列人归降亚撒，因见耶和华─他的神与他同在。'),
('CUV', '历代志下', 14, 15, 10, '亚撒十五年三月，他们都聚集在耶路撒冷。'),
('CUV', '历代志下', 14, 15, 11, '当日他们从所取的掳物中，将牛七百只、羊七千只献给耶和华。'),
('CUV', '历代志下', 14, 15, 12, '他们就立约，要尽心尽性地寻求耶和华─他们列祖的神。'),
('CUV', '历代志下', 14, 15, 13, '凡不寻求耶和华─以色列神的，无论大小、男女，必被治死。'),
('CUV', '历代志下', 14, 15, 14, '他们就大声欢呼，吹号吹角，向耶和华起誓。'),
('CUV', '历代志下', 14, 15, 15, '犹大众人为所起的誓欢喜；因他们是尽心起誓，尽意寻求耶和华，耶和华就被他们寻见，且赐他们四境平安。'),
('CUV', '历代志下', 14, 15, 16, '亚撒王贬了他祖母玛迦太后的位，因他造了可憎的偶像亚舍拉。亚撒砍下他的偶像，捣得粉碎，烧在汲沦溪边。'),
('CUV', '历代志下', 14, 15, 17, '只是邱坛还没有从以色列中废去，然而亚撒的心一生诚实。'),
('CUV', '历代志下', 14, 15, 18, '亚撒将他父所分别为圣、与自己所分别为圣的金银和器皿都奉到神的殿里。'),
('CUV', '历代志下', 14, 15, 19, '从这时直到亚撒三十五年，都没有争战的事。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 16, 1, '亚撒三十六年，以色列王巴沙上来攻击犹大，修筑拉玛，不许人从犹大王亚撒那里出入。'),
('CUV', '历代志下', 14, 16, 2, '于是亚撒从耶和华殿和王宫的府库里拿出金银来，送与住大马色的亚兰王便哈达，说：'),
('CUV', '历代志下', 14, 16, 3, '你父曾与我父立约，我与你也要立约。现在我将金银送给你，求你废掉你与以色列王巴沙所立的约，使他离开我。'),
('CUV', '历代志下', 14, 16, 4, '便哈达听从亚撒王的话，派军长去攻击以色列的城邑。他们就攻破以云、但、亚伯玛音，和拿弗他利一切的积货城。'),
('CUV', '历代志下', 14, 16, 5, '巴沙听见就停工，不修筑拉玛了。'),
('CUV', '历代志下', 14, 16, 6, '于是亚撒王率领犹大众人，将巴沙修筑拉玛所用的石头、木头都运去，用以修筑迦巴和米斯巴。'),
('CUV', '历代志下', 14, 16, 7, '那时，先见哈拿尼来见犹大王亚撒，对他说：因你仰赖亚兰王，没有仰赖耶和华─你的神，所以亚兰王的军兵脱离了你的手。'),
('CUV', '历代志下', 14, 16, 8, '古实人、路比人的军队不是甚大么？战车马兵不是极多么？只因你仰赖耶和华，他便将他们交在你手里。'),
('CUV', '历代志下', 14, 16, 9, '耶和华的眼目遍察全地，要显大能帮助向他心存诚实的人。你这事行得愚昧；此后，你必有争战的事。'),
('CUV', '历代志下', 14, 16, 10, '亚撒因此恼恨先见，将他囚在监里。那时亚撒也虐待一些人民。'),
('CUV', '历代志下', 14, 16, 11, '亚撒所行的事，自始至终都写在犹大和以色列诸王记上。'),
('CUV', '历代志下', 14, 16, 12, '亚撒作王三十九年，他脚上有病，而且甚重。病的时候没有求耶和华，只求医生。'),
('CUV', '历代志下', 14, 16, 13, '他作王四十一年而死，与他列祖同睡，'),
('CUV', '历代志下', 14, 16, 14, '葬在大卫城自己所凿的坟墓里，放在床上，其床堆满各样馨香的香料，就是按做香的作法调和的香料，又为他烧了许多的物件。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 17, 1, '亚撒的儿子约沙法接续他作王，奋勇自强，防备以色列人，'),
('CUV', '历代志下', 14, 17, 2, '安置军兵在犹大一切坚固城里，又安置防兵在犹大地和他父亚撒所得以法莲的城邑中。'),
('CUV', '历代志下', 14, 17, 3, '耶和华与约沙法同在；因为他行他祖大卫初行的道，不寻求巴力，'),
('CUV', '历代志下', 14, 17, 4, '只寻求他父亲的神，遵行他的诫命，不效法以色列人的行为。'),
('CUV', '历代志下', 14, 17, 5, '所以耶和华坚定他的国，犹大众人给他进贡；约沙法大有尊荣资财。'),
('CUV', '历代志下', 14, 17, 6, '他高兴遵行耶和华的道，并且从犹大除掉一切邱坛和木偶。'),
('CUV', '历代志下', 14, 17, 7, '他作王第三年，就差遣臣子便亥伊勒、俄巴底、撒迦利雅、拿坦业、米该亚往犹大各城去教训百姓。'),
('CUV', '历代志下', 14, 17, 8, '同著他们有利未人示玛雅、尼探雅、西巴第雅、亚撒黑、示米拉末、约拿单、亚多尼雅、多比雅、驼巴多尼雅，又有祭司以利沙玛、约兰同著他们。'),
('CUV', '历代志下', 14, 17, 9, '他们带著耶和华的律法书，走遍犹大各城教训百姓。'),
('CUV', '历代志下', 14, 17, 10, '耶和华使犹大四围的列国都甚恐惧，不敢与约沙法争战。'),
('CUV', '历代志下', 14, 17, 11, '有些非利士人与约沙法送礼物，纳贡银。亚拉伯人也送他公绵羊七千七百只，公山羊七千七百只。'),
('CUV', '历代志下', 14, 17, 12, '约沙法日渐强大，在犹大建造营寨和积货城。'),
('CUV', '历代志下', 14, 17, 13, '他在犹大城邑中有许多工程，又在耶路撒冷有战士，就是大能的勇士。'),
('CUV', '历代志下', 14, 17, 14, '他们的数目，按著宗族，记在下面：犹大族的，千夫长押拿为首率领大能的勇士─三十万；'),
('CUV', '历代志下', 14, 17, 15, '其次是，千夫长约哈难率领大能的勇士─二十八万；'),
('CUV', '历代志下', 14, 17, 16, '其次是，细基利的儿子亚玛斯雅〈他为耶和华牺牲自己〉率领大能的勇士─二十万。'),
('CUV', '历代志下', 14, 17, 17, '便雅悯族，是大能的勇士以利雅大率领，拿弓箭和盾牌的─二十万；'),
('CUV', '历代志下', 14, 17, 18, '其次是，约萨拔率领预备打仗的─十八万。'),
('CUV', '历代志下', 14, 17, 19, '这都是伺候王的，还有王在犹大全地坚固城所安置的不在其内。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 18, 1, '约沙法大有尊荣资财，就与亚哈结亲。'),
('CUV', '历代志下', 14, 18, 2, '过了几年，他下到撒玛利亚去见亚哈；亚哈为他和跟从他的人宰了许多牛羊，劝他与自己同去攻取基列的拉末。'),
('CUV', '历代志下', 14, 18, 3, '以色列王亚哈问犹大王约沙法说：你肯同我去攻取基列的拉末么？他回答说：你我不分彼此，我的民与你的民一样，必与你同去争战。'),
('CUV', '历代志下', 14, 18, 4, '约沙法对以色列王说：请你先求问耶和华。'),
('CUV', '历代志下', 14, 18, 5, '于是以色列王招聚先知四百人，问他们说：我们上去攻取基列的拉末可以不可以？他们说：可以上去，因为神必将那城交在王的手里。'),
('CUV', '历代志下', 14, 18, 6, '约沙法说：这里不是还有耶和华的先知，我们可以求问他么？'),
('CUV', '历代志下', 14, 18, 7, '以色列王对约沙法说：还有一个人，是音拉的儿子米该雅。我们可以托他求问耶和华，只是我恨他；因为他指著我所说的预言，不说吉语，常说凶言。约沙法说：王不必这样说。'),
('CUV', '历代志下', 14, 18, 8, '以色列王就召了一个太监来，说：你快去将音拉的儿子米该雅召来。'),
('CUV', '历代志下', 14, 18, 9, '以色列王和犹大王约沙法在撒玛利亚城门前的空场上，各穿朝服坐在位上，所有的先知都在他们面前说预言。'),
('CUV', '历代志下', 14, 18, 10, '基拿拿的儿子西底家造了两个铁角，说：耶和华如此说：你要用这角抵触亚兰人，直到将他们灭尽。'),
('CUV', '历代志下', 14, 18, 11, '所有的先知也都这样预言说：可以上基列的拉末去，必然得胜，因为耶和华必将那城交在王的手中。'),
('CUV', '历代志下', 14, 18, 12, '那去召米该雅的使者对米该雅说：众先知一口同音地都向王说吉言，你不如与他们说一样的话，也说吉言。'),
('CUV', '历代志下', 14, 18, 13, '米该雅说：我指著永生的耶和华起誓，我的神说甚么，我就说甚么。'),
('CUV', '历代志下', 14, 18, 14, '米该雅到王面前，王问他说：米该雅啊，我们上去攻取基列的拉末可以不可以？他说：可以上去，必然得胜，敌人必交在你们手里。'),
('CUV', '历代志下', 14, 18, 15, '王对他说：我当嘱咐你几次，你才奉耶和华的名向我说实话呢？'),
('CUV', '历代志下', 14, 18, 16, '米该雅说：我看见以色列众民散在山上，如同没有牧人的羊群一般。耶和华说：这民没有主人，他们可以平平安安地各归各家去。'),
('CUV', '历代志下', 14, 18, 17, '以色列王对约沙法说：我岂没有告诉你，这人指著我所说的预言，不说吉语，单说凶言么？'),
('CUV', '历代志下', 14, 18, 18, '米该雅说：你们要听耶和华的话。我看见耶和华坐在宝座上，天上的万军侍立在他左右。'),
('CUV', '历代志下', 14, 18, 19, '耶和华说：谁去引诱以色列王亚哈上基列的拉末去阵亡呢？这个就这样说，那个就那样说。'),
('CUV', '历代志下', 14, 18, 20, '随后，有一个神灵出来，站在耶和华面前说：我去引诱他。耶和华问他说：你用何法呢？'),
('CUV', '历代志下', 14, 18, 21, '他说：我去，要在他众先知口中作谎言的灵。耶和华说：这样，你必能引诱他，你去如此行罢！'),
('CUV', '历代志下', 14, 18, 22, '现在耶和华使谎言的灵入了你这些先知的口，并且耶和华已经命定降祸与你。'),
('CUV', '历代志下', 14, 18, 23, '基拿拿的儿子西底家前来打米该雅的脸，说：耶和华的灵从哪里离开我与你说话呢？'),
('CUV', '历代志下', 14, 18, 24, '米该雅说：你进严密的屋子藏躲的那日，就必看见了。'),
('CUV', '历代志下', 14, 18, 25, '以色列王说：将米该雅带回，交给邑宰亚们和王的儿子约阿施，说：'),
('CUV', '历代志下', 14, 18, 26, '王如此说：把这个人下在监里，使他受苦，吃不饱喝不足，等候我平平安安地回来。'),
('CUV', '历代志下', 14, 18, 27, '米该雅说：你若能平安回来，那就是耶和华没有藉我说这话了；又说：众民哪，你们都要听！'),
('CUV', '历代志下', 14, 18, 28, '以色列王和犹大王约沙法上基列的拉末去了。'),
('CUV', '历代志下', 14, 18, 29, '以色列王对约沙法说：我要改装上阵，你可以仍穿王服。于是以色列王改装，他们就上阵去了。'),
('CUV', '历代志下', 14, 18, 30, '先是亚兰王吩咐车兵长说：他们的兵将，无论大小，你们都不可与他们争战，只要与以色列王争战。'),
('CUV', '历代志下', 14, 18, 31, '车兵长看见约沙法便说，这必是以色列王，就转过去与他争战。约沙法一呼喊，耶和华就帮助他，神又感动他们离开他。'),
('CUV', '历代志下', 14, 18, 32, '车兵长见不是以色列王，就转去不追他了。'),
('CUV', '历代志下', 14, 18, 33, '有一人随便开弓，恰巧射入以色列王的甲缝里。王对赶车的说：我受了重伤，你转过车来，拉我出阵罢！'),
('CUV', '历代志下', 14, 18, 34, '那日阵势越战越猛，以色列王勉强站在车上抵挡亚兰人，直到晚上。约在日落的时候，王就死了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 19, 1, '犹大王约沙法平平安安地回耶路撒冷，到宫里去了。'),
('CUV', '历代志下', 14, 19, 2, '先见哈拿尼的儿子耶户出来迎接约沙法王，对他说：你岂当帮助恶人，爱那恨恶耶和华的人呢？因此耶和华的忿怒临到你。'),
('CUV', '历代志下', 14, 19, 3, '然而你还有善行，因你从国中除掉木偶，立定心意寻求神。'),
('CUV', '历代志下', 14, 19, 4, '约沙法住在耶路撒冷，以后又出巡民间，从别是巴直到以法莲山地，引导民归向耶和华─他们列祖的神；'),
('CUV', '历代志下', 14, 19, 5, '又在犹大国中遍地的坚固城里设立审判官，'),
('CUV', '历代志下', 14, 19, 6, '对他们说：你们办事应当谨慎；因为你们判断不是为人，乃是为耶和华。判断的时候，他必与你们同在。'),
('CUV', '历代志下', 14, 19, 7, '现在你们应当敬畏耶和华，谨慎办事；因为耶和华─我们的神没有不义，不偏待人，也不受贿赂。'),
('CUV', '历代志下', 14, 19, 8, '约沙法从利未人和祭司，并以色列族长中派定人，在耶路撒冷为耶和华判断，听民间的争讼，就回耶路撒冷去了。'),
('CUV', '历代志下', 14, 19, 9, '约沙法嘱咐他们说：你们当敬畏耶和华，忠心诚实办事。'),
('CUV', '历代志下', 14, 19, 10, '住在各城里你们的弟兄，若有争讼的事来到你们这里，或为流血，或犯律法、诫命、律例、典章，你们要警戒他们，免得他们得罪耶和华，以致他的忿怒临到你们和你们的弟兄；这样行，你们就没有罪了。'),
('CUV', '历代志下', 14, 19, 11, '凡属耶和华的事，有大祭司亚玛利雅管理你们；凡属王的事，有犹大支派的族长以实玛利的儿子西巴第雅管理你们；在你们面前有利未人作官长。你们应当壮胆办事，愿耶和华与善人同在。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 20, 1, '此后，摩押人和亚扪人，又有米乌尼人，一同来攻击约沙法。'),
('CUV', '历代志下', 14, 20, 2, '有人来报告约沙法说：从海外亚兰(又作以东)那边有大军来攻击你，如今他们在哈洗逊他玛，就是隐基底。'),
('CUV', '历代志下', 14, 20, 3, '约沙法便惧怕，定意寻求耶和华，在犹大全地宣告禁食。'),
('CUV', '历代志下', 14, 20, 4, '于是犹大人聚会，求耶和华帮助。犹大各城都有人出来寻求耶和华。'),
('CUV', '历代志下', 14, 20, 5, '约沙法就在犹大和耶路撒冷的会中，站在耶和华殿的新院前，'),
('CUV', '历代志下', 14, 20, 6, '说：耶和华─我们列祖的神啊，你不是天上的神么？你不是万邦万国的主宰么？在你手中有大能大力，无人能抵挡你。'),
('CUV', '历代志下', 14, 20, 7, '我们的神啊，你不是曾在你民以色列人面前驱逐这地的居民，将这地赐给你朋友亚伯拉罕的后裔永远为业么？'),
('CUV', '历代志下', 14, 20, 8, '他们住在这地，又为你的名建造圣所，说：'),
('CUV', '历代志下', 14, 20, 9, '倘有祸患临到我们，或刀兵灾殃，或瘟疫饥荒，我们在急难的时候，站在这殿前向你呼求，你必垂听而拯救，因为你的名在这殿里。'),
('CUV', '历代志下', 14, 20, 10, '从前以色列人出埃及地的时候，你不容以色列人侵犯亚扪人、摩押人，和西珥山人，以色列人就离开他们，不灭绝他们。'),
('CUV', '历代志下', 14, 20, 11, '看哪，他们怎样报复我们，要来驱逐我们出离你的地，就是你赐给我们为业之地。'),
('CUV', '历代志下', 14, 20, 12, '我们的神啊，你不惩罚他们么？因为我们无力抵挡这来攻击我们的大军，我们也不知道怎样行，我们的眼目单仰望你。'),
('CUV', '历代志下', 14, 20, 13, '犹大众人和他们的婴孩、妻子、儿女都站在耶和华面前。'),
('CUV', '历代志下', 14, 20, 14, '那时，耶和华的灵在会中临到利未人亚萨的后裔─玛探雅的玄孙，耶利的曾孙，比拿雅的孙子，撒迦利雅的儿子雅哈悉。'),
('CUV', '历代志下', 14, 20, 15, '他说：犹大众人、耶路撒冷的居民，和约沙法王，你们请听。耶和华对你们如此说：不要因这大军恐惧惊惶；因为胜败不在乎你们，乃在乎神。'),
('CUV', '历代志下', 14, 20, 16, '明日你们要下去迎敌，他们是从洗斯坡上来，你们必在耶鲁伊勒旷野前的谷口遇见他们。'),
('CUV', '历代志下', 14, 20, 17, '犹大和耶路撒冷人哪，这次你们不要争战，要摆阵站著，看耶和华为你们施行拯救。不要恐惧，也不要惊惶。明日当出去迎敌，因为耶和华与你们同在。'),
('CUV', '历代志下', 14, 20, 18, '约沙法就面伏于地，犹大众人和耶路撒冷的居民也俯伏在耶和华面前，叩拜耶和华。'),
('CUV', '历代志下', 14, 20, 19, '哥辖族和可拉族的利未人都起来，用极大的声音赞美耶和华以色列的神。'),
('CUV', '历代志下', 14, 20, 20, '次日清早，众人起来往提哥亚的旷野去。出去的时候，约沙法站著说：犹大人和耶路撒冷的居民哪，要听我说：信耶和华─你们的神就必立稳；信他的先知就必亨通。'),
('CUV', '历代志下', 14, 20, 21, '约沙法既与民商议了，就设立歌唱的人，颂赞耶和华，使他们穿上圣洁的礼服，走在军前赞美耶和华说：当称谢耶和华，因他的慈爱永远长存！'),
('CUV', '历代志下', 14, 20, 22, '众人方唱歌赞美的时候，耶和华就派伏兵击杀那来攻击犹大人的亚扪人、摩押人，和西珥山人，他们就被打败了。'),
('CUV', '历代志下', 14, 20, 23, '因为亚扪人和摩押人起来，击杀住西珥山的人，将他们灭尽；灭尽住西珥山的人之后，他们又彼此自相击杀。'),
('CUV', '历代志下', 14, 20, 24, '犹大人来到旷野的望楼，向那大军观看，见尸横遍地，没有一个逃脱的。'),
('CUV', '历代志下', 14, 20, 25, '约沙法和他的百姓就来收取敌人的财物，在尸首中见了许多财物、珍宝，他们剥脱下来的多得不可携带；因为甚多，直收取了三日。'),
('CUV', '历代志下', 14, 20, 26, '第四日众人聚集在比拉迦谷(就是称颂的意思)，在那里称颂耶和华。因此那地方名叫比拉迦谷，直到今日。'),
('CUV', '历代志下', 14, 20, 27, '犹大人和耶路撒冷人都欢欢喜喜地回耶路撒冷，约沙法率领他们；因为耶和华使他们战胜仇敌，就欢喜快乐。'),
('CUV', '历代志下', 14, 20, 28, '他们弹琴、鼓瑟、吹号来到耶路撒冷，进了耶和华的殿。'),
('CUV', '历代志下', 14, 20, 29, '列邦诸国听见耶和华战败以色列的仇敌，就甚惧怕。'),
('CUV', '历代志下', 14, 20, 30, '这样，约沙法的国得享太平，因为神赐他四境平安。'),
('CUV', '历代志下', 14, 20, 31, '约沙法作犹大王，登基的时候年三十五岁，在耶路撒冷作王二十五年。他母亲名叫阿苏巴，乃示利希的女儿。'),
('CUV', '历代志下', 14, 20, 32, '约沙法效法他父亚撒所行的，不偏左右，行耶和华眼中看为正的事。'),
('CUV', '历代志下', 14, 20, 33, '只是邱坛还没有废去，百姓也没有立定心意归向他们列祖的神。'),
('CUV', '历代志下', 14, 20, 34, '约沙法其余的事，自始至终都写在哈拿尼的儿子耶户的书上，也载入以色列诸王记上。'),
('CUV', '历代志下', 14, 20, 35, '此后，犹大王约沙法与以色列王亚哈谢交好；亚哈谢行恶太甚。'),
('CUV', '历代志下', 14, 20, 36, '二王合伙造船要往他施去，遂在以旬迦别造船。'),
('CUV', '历代志下', 14, 20, 37, '那时玛利沙人、多大瓦的儿子以利以谢向约沙法预言说：因你与亚哈谢交好，耶和华必破坏你所造的。后来那船果然破坏，不能往他施去了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 21, 1, '约沙法与他列祖同睡，葬在大卫城他列祖的坟地里。他儿子约兰接续他作王。'),
('CUV', '历代志下', 14, 21, 2, '约兰有几个兄弟，就是约沙法的儿子亚撒利雅、耶歇、撒迦利雅、亚撒利雅、米迦勒、示法提雅。这都是犹大王约沙法的儿子。'),
('CUV', '历代志下', 14, 21, 3, '他们的父亲将许多金银、财宝，和犹大地的坚固城赐给他们；但将国赐给约兰，因为他是长子。'),
('CUV', '历代志下', 14, 21, 4, '约兰兴起坐他父的位，奋勇自强，就用刀杀了他的众兄弟和以色列的几个首领。'),
('CUV', '历代志下', 14, 21, 5, '约兰登基的时候年三十二岁，在耶路撒冷作王八年。'),
('CUV', '历代志下', 14, 21, 6, '他行以色列诸王的道，与亚哈家一样；因他娶了亚哈的女儿为妻，行耶和华眼中看为恶的事。'),
('CUV', '历代志下', 14, 21, 7, '耶和华却因自己与大卫所立的约，不肯灭大卫的家，照他所应许的，永远赐灯光与大卫和他的子孙。'),
('CUV', '历代志下', 14, 21, 8, '约兰年间，以东人背叛犹大，脱离他的权下，自己立王。'),
('CUV', '历代志下', 14, 21, 9, '约兰就率领军长和所有的战车，夜间起来，攻击围困他的以东人和车兵长。'),
('CUV', '历代志下', 14, 21, 10, '这样，以东人背叛犹大，脱离他的权下，直到今日。那时，立拿人也背叛了，因为约兰离弃耶和华─他列祖的神。'),
('CUV', '历代志下', 14, 21, 11, '他又在犹大诸山建筑邱坛，使耶路撒冷的居民行邪淫，诱惑犹大人。'),
('CUV', '历代志下', 14, 21, 12, '先知以利亚达信与约兰说：耶和华─你祖大卫的神如此说：因为你不行你父约沙法和犹大王亚撒的道，'),
('CUV', '历代志下', 14, 21, 13, '乃行以色列诸王的道，使犹大人和耶路撒冷的居民行邪淫，像亚哈家一样，又杀了你父家比你好的诸兄弟。'),
('CUV', '历代志下', 14, 21, 14, '故此，耶和华降大灾与你的百姓和你的妻子、儿女，并你一切所有的。'),
('CUV', '历代志下', 14, 21, 15, '你的肠子必患病，日加沉重，以致你的肠子坠落下来。'),
('CUV', '历代志下', 14, 21, 16, '以后，耶和华激动非利士人和靠近古实的亚拉伯人来攻击约兰。'),
('CUV', '历代志下', 14, 21, 17, '他们上来攻击犹大，侵入境内，掳掠了王宫里所有的财货和他的妻子、儿女，除了他小儿子约哈斯(又名亚哈谢)之外，没有留下一个儿子。'),
('CUV', '历代志下', 14, 21, 18, '这些事以后，耶和华使约兰的肠子患不能医治的病。'),
('CUV', '历代志下', 14, 21, 19, '他患此病缠绵日久，过了二年，肠子坠落下来，病重而死。他的民没有为他烧甚么物件，像从前为他列祖所烧的一样。'),
('CUV', '历代志下', 14, 21, 20, '约兰登基的时候年三十二岁，在耶路撒冷作王八年。他去世无人思慕，众人葬他在大卫城，只是不在列王的坟墓里。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 22, 1, '耶路撒冷的居民立约兰的小儿子亚哈谢接续他作王；因为跟随亚拉伯人来攻营的军兵曾杀了亚哈谢的众兄长。这样，犹大王约兰的儿子亚哈谢作了王。'),
('CUV', '历代志下', 14, 22, 2, '亚哈谢登基的时候年四十二岁(王下八26作二十二岁)，在耶路撒冷作王一年。他母亲名叫亚他利雅，是暗利的孙女。'),
('CUV', '历代志下', 14, 22, 3, '亚哈谢也行亚哈家的道；因为他母亲给他主谋，使他行恶。'),
('CUV', '历代志下', 14, 22, 4, '他行耶和华眼中看为恶的事，像亚哈家一样；因他父亲死后有亚哈家的人给他主谋，以致败坏。'),
('CUV', '历代志下', 14, 22, 5, '他听从亚哈家的计谋，同以色列王亚哈的儿子约兰往基列的拉末去，与亚兰王哈薛争战；亚兰人打伤了约兰。'),
('CUV', '历代志下', 14, 22, 6, '约兰回到耶斯列，医治在拉末与亚兰王哈薛打仗所受的伤，犹大王约兰的儿子亚撒利雅(即亚哈谢)因为亚哈的儿子约兰病了，就下到耶斯列看望他。'),
('CUV', '历代志下', 14, 22, 7, '亚哈谢去见约兰就被害了，这是出乎神；因为他到了，就同约兰出去攻击宁示的孙子耶户。这耶户是耶和华所膏、使他剪除亚哈家的。'),
('CUV', '历代志下', 14, 22, 8, '耶户讨亚哈家罪的时候，遇见犹大的众首领和亚哈谢的众姪子服事亚哈谢，就把他们都杀了。'),
('CUV', '历代志下', 14, 22, 9, '亚哈谢藏在撒玛利亚，耶户寻找他，众人将他拿住，送到耶户那里，就杀了他，将他葬埋；因他们说，他是那尽心寻求耶和华之约沙法的儿子。这样，亚哈谢的家无力保守国权。'),
('CUV', '历代志下', 14, 22, 10, '亚哈谢的母亲亚他利雅见他儿子死了，就起来剿灭犹大王室。'),
('CUV', '历代志下', 14, 22, 11, '但王的女儿约示巴将亚哈谢的儿子约阿施从那被杀的王子中偷出来，把他和他的乳母都藏在卧房里。约示巴是约兰王的女儿，亚哈谢的妹子，祭司耶何耶大的妻。他收藏约阿施，躲避亚他利雅，免得被杀。'),
('CUV', '历代志下', 14, 22, 12, '约阿施和他们一同藏在神殿里六年；亚他利雅篡了国位。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 23, 1, '第七年，耶何耶大奋勇自强，将百夫长耶罗罕的儿子亚撒利雅，约哈难的儿子以实玛利，俄备得的儿子亚撒利雅，亚大雅的儿子玛西雅，细基利的儿子以利沙法召来，与他们立约。'),
('CUV', '历代志下', 14, 23, 2, '他们走遍犹大，从犹大各城里招聚利未人和以色列的众族长到耶路撒冷来。'),
('CUV', '历代志下', 14, 23, 3, '会众在神殿里与王立约。耶何耶大对他们说：看哪，王的儿子必当作王，正如耶和华指著大卫子孙所应许的话；'),
('CUV', '历代志下', 14, 23, 4, '又说：你们当这样行：祭司和利未人凡安息日进班的，三分之一要把守各门，'),
('CUV', '历代志下', 14, 23, 5, '三分之一要在王宫，三分之一要在基址门；众百姓要在耶和华殿的院内。'),
('CUV', '历代志下', 14, 23, 6, '除了祭司和供职的利未人之外，不准别人进耶和华的殿；惟独他们可以进去，因为他们圣洁。众百姓要遵守耶和华所吩咐的。'),
('CUV', '历代志下', 14, 23, 7, '利未人要手中各拿兵器，四围护卫王；凡擅入殿宇的，必当治死。王出入的时候，你们当跟随他。'),
('CUV', '历代志下', 14, 23, 8, '利未人和犹大众人都照著祭司耶何耶大一切所吩咐的去行，各带所管安息日进班出班的人来，因为祭司耶何耶大不许他们下班。'),
('CUV', '历代志下', 14, 23, 9, '祭司耶何耶大便将神殿里所藏大卫王的枪、盾牌、挡牌交给百夫长，'),
('CUV', '历代志下', 14, 23, 10, '又分派众民手中各拿兵器，在坛和殿那里，从殿右直到殿左，站在王子的四围；'),
('CUV', '历代志下', 14, 23, 11, '于是领王子出来，给他戴上冠冕，将律法书交给他，立他作王。耶何耶大和众子膏他，众人说：愿王万岁！'),
('CUV', '历代志下', 14, 23, 12, '亚他利雅听见民奔走赞美王的声音，就到民那里，进耶和华的殿，'),
('CUV', '历代志下', 14, 23, 13, '看见王站在殿门的柱旁，百夫长和吹号的人侍立在王左右，国民都欢乐吹号，又有歌唱的，用各样的乐器领人歌唱赞美；亚他利雅就撕裂衣服，喊叫说：反了！反了！'),
('CUV', '历代志下', 14, 23, 14, '祭司耶何耶大带管辖军兵的百夫长出来，吩咐他们说：将他赶到班外，凡跟随他的必用刀杀死！因为祭司说：不可在耶和华殿里杀他。'),
('CUV', '历代志下', 14, 23, 15, '众兵就闪开，让他去；他走到王宫的马门，便在那里把他杀了。'),
('CUV', '历代志下', 14, 23, 16, '耶何耶大与众民和王立约，都要作耶和华的民。'),
('CUV', '历代志下', 14, 23, 17, '于是众民都到巴力庙，拆毁了庙，打碎坛和像，又在坛前将巴力的祭司玛坦杀了。'),
('CUV', '历代志下', 14, 23, 18, '耶何耶大派官看守耶和华的殿，是在祭司利未人手下。这祭司利未人是大卫分派在耶和华殿中、照摩西律法上所写的，给耶和华献燔祭，又按大卫所定的例，欢乐歌唱；'),
('CUV', '历代志下', 14, 23, 19, '且设立守门的把守耶和华殿的各门，无论为何事，不洁净的人都不准进去。'),
('CUV', '历代志下', 14, 23, 20, '又率领百夫长和贵胄，与民间的官长，并国中的众民，请王从耶和华殿下来，由上门进入王宫，立王坐在国位上。'),
('CUV', '历代志下', 14, 23, 21, '国民都欢乐，合城都安静。众人已将亚他利雅用刀杀了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 24, 1, '约阿施登基的时候年七岁，在耶路撒冷作王四十年。他母亲名叫西比亚，是别是巴人。'),
('CUV', '历代志下', 14, 24, 2, '祭司耶何耶大在世的时候，约阿施行耶和华眼中看为正的事。'),
('CUV', '历代志下', 14, 24, 3, '耶何耶大为他娶了两个妻，并且生儿养女。'),
('CUV', '历代志下', 14, 24, 4, '此后，约阿施有意重修耶和华的殿，'),
('CUV', '历代志下', 14, 24, 5, '便召聚众祭司和利未人，吩咐他们说：你们要往犹大各城去，使以色列众人捐纳银子，每年可以修理你们神的殿；你们要急速办理这事。只是利未人不急速办理。'),
('CUV', '历代志下', 14, 24, 6, '王召了大祭司耶何耶大来，对他说：从前耶和华的仆人摩西，为法柜的帐幕与以色列会众所定的捐项，你为何不叫利未人照这例从犹大和耶路撒冷带来作殿的费用呢？'),
('CUV', '历代志下', 14, 24, 7, '〈因为那恶妇亚他利雅的众子曾拆毁神的殿，又用耶和华殿中分别为圣的物供奉巴力。〉'),
('CUV', '历代志下', 14, 24, 8, '于是王下令，众人做了一柜，放在耶和华殿的门外，'),
('CUV', '历代志下', 14, 24, 9, '又通告犹大和耶路撒冷的百姓，要将神仆人摩西在旷野所吩咐以色列人的捐项给耶和华送来。'),
('CUV', '历代志下', 14, 24, 10, '众首领和百姓都欢欢喜喜地将银子送来，投入柜中，直到捐完。'),
('CUV', '历代志下', 14, 24, 11, '利未人见银子多了，就把柜抬到王所派的司事面前；王的书记和大祭司的属员来将柜倒空，仍放在原处。日日都是这样，积蓄的银子甚多。'),
('CUV', '历代志下', 14, 24, 12, '王与耶何耶大将银子交给耶和华殿里办事的人，他们就雇了石匠、木匠重修耶和华的殿，又雇了铁匠、铜匠修理耶和华的殿。'),
('CUV', '历代志下', 14, 24, 13, '工人操作，渐渐修成，将神殿修造得与从前一样，而且甚是坚固。'),
('CUV', '历代志下', 14, 24, 14, '工程完了，他们就把其余的银子拿到王与耶何耶大面前，用以制造耶和华殿供奉所用的器皿和调羹，并金银的器皿。耶何耶大在世的时候，众人常在耶和华殿里献燔祭。'),
('CUV', '历代志下', 14, 24, 15, '耶何耶大年纪老迈，日子满足而死。死的时候年一百三十岁，'),
('CUV', '历代志下', 14, 24, 16, '葬在大卫城列王的坟墓里；因为他在以色列人中行善，又事奉神，修理神的殿。'),
('CUV', '历代志下', 14, 24, 17, '耶何耶大死后，犹大的众首领来朝拜王；王就听从他们。'),
('CUV', '历代志下', 14, 24, 18, '他们离弃耶和华─他们列祖神的殿，去事奉亚舍拉和偶像；因他们这罪，就有忿怒临到犹大和耶路撒冷。'),
('CUV', '历代志下', 14, 24, 19, '但神仍遣先知到他们那里，引导他们归向耶和华。这先知警戒他们，他们却不肯听。'),
('CUV', '历代志下', 14, 24, 20, '那时，神的灵感动祭司耶何耶大的儿子撒迦利亚，他就站在上面对民说：神如此说：你们为何干犯耶和华的诫命，以致不得亨通呢？因为你们离弃耶和华，所以他也离弃你们。'),
('CUV', '历代志下', 14, 24, 21, '众民同心谋害撒迦利亚，就照王的吩咐，在耶和华殿的院内用石头打死他。'),
('CUV', '历代志下', 14, 24, 22, '这样，约阿施王不想念撒迦利亚的父亲耶何耶大向自己所施的恩，杀了他的儿子。撒迦利亚临死的时候说：愿耶和华鉴察伸冤！'),
('CUV', '历代志下', 14, 24, 23, '满了一年，亚兰的军兵上来攻击约阿施，来到犹大和耶路撒冷，杀了民中的众首领，将所掠的财货送到大马色王那里。'),
('CUV', '历代志下', 14, 24, 24, '亚兰的军兵虽来了一小队，耶和华却将大队的军兵交在他们手里，是因犹大人离弃耶和华─他们列祖的神，所以藉亚兰人惩罚约阿施。'),
('CUV', '历代志下', 14, 24, 25, '亚兰人离开约阿施的时候，他患重病；臣仆背叛他，要报祭司耶何耶大儿子流血之仇，杀他在床上，葬他在大卫城，只是不葬在列王的坟墓里。'),
('CUV', '历代志下', 14, 24, 26, '背叛他的是亚扪妇人示米押的儿子撒拔和摩押妇人示米利的儿子约萨拔。'),
('CUV', '历代志下', 14, 24, 27, '至于他的众子和他所受的警戒，并他重修神殿的事，都写在列王的传上。他儿子亚玛谢接续他作王。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 25, 1, '亚玛谢登基的时候年二十五岁，在耶路撒冷作王二十九年。他母亲名叫约耶但，是耶路撒冷人。'),
('CUV', '历代志下', 14, 25, 2, '亚玛谢行耶和华眼中看为正的事，只是心不专诚。'),
('CUV', '历代志下', 14, 25, 3, '国一坚定，就把杀他父王的臣仆杀了，'),
('CUV', '历代志下', 14, 25, 4, '却没有治死他们的儿子，是照摩西律法书上耶和华所吩咐的说：不可因子杀父，也不可因父杀子，各人要为本身的罪而死。'),
('CUV', '历代志下', 14, 25, 5, '亚玛谢招聚犹大人，按著犹大和便雅悯的宗族设立千夫长、百夫长，又数点人数，从二十岁以外，能拿枪拿盾牌出去打仗的精兵共有三十万；'),
('CUV', '历代志下', 14, 25, 6, '又用银子一百他连得，从以色列招募了十万大能的勇士。'),
('CUV', '历代志下', 14, 25, 7, '有一个神人来见亚玛谢，对他说：王啊，不要使以色列的军兵与你同去，因为耶和华不与以色列人以法莲的后裔同在。'),
('CUV', '历代志下', 14, 25, 8, '你若一定要去，就奋勇争战罢！但神必使你败在敌人面前；因为神能助人得胜，也能使人倾败。'),
('CUV', '历代志下', 14, 25, 9, '亚玛谢问神人说：我给了以色列军的那一百他连得银子怎么样呢？神人回答说：耶和华能把更多的赐给你。'),
('CUV', '历代志下', 14, 25, 10, '于是亚玛谢将那从以法莲来的军兵分别出来，叫他们回家去。故此，他们甚恼怒犹大人，气忿忿地回家去了。'),
('CUV', '历代志下', 14, 25, 11, '亚玛谢壮起胆来，率领他的民到盐谷，杀了西珥人一万。'),
('CUV', '历代志下', 14, 25, 12, '犹大人又生擒了一万带到山崖上，从那里把他们扔下去，以致他们都摔碎了。'),
('CUV', '历代志下', 14, 25, 13, '但亚玛谢所打发回去、不许一同出征的那些军兵攻打犹大各城，从撒玛利亚直到伯和仑，杀了三千人，抢了许多财物。'),
('CUV', '历代志下', 14, 25, 14, '亚玛谢杀了以东人回来，就把西珥的神像带回，立为自己的神，在他面前叩拜烧香。'),
('CUV', '历代志下', 14, 25, 15, '因此，耶和华的怒气向亚玛谢发作，就差一个先知去见他，说：这些神不能救他的民脱离你的手，你为何寻求他呢？'),
('CUV', '历代志下', 14, 25, 16, '先知与王说话的时候，王对他说：谁立你作王的谋士呢？你住口罢！为何找打呢？先知就止住了，又说：你行这事，不听从我的劝戒，我知道神定意要灭你。'),
('CUV', '历代志下', 14, 25, 17, '犹大王亚玛谢与群臣商议，就差遣使者去见耶户的孙子、约哈斯的儿子、以色列王约阿施，说：你来，我们二人相见于战场。'),
('CUV', '历代志下', 14, 25, 18, '以色列王约阿施差遣使者去见犹大王亚玛谢，说：利巴嫩的蒺藜差遣使者去见利巴嫩的香柏树，说：将你的女儿给我儿子为妻。后来利巴嫩有一个野兽经过，把蒺藜践踏了。'),
('CUV', '历代志下', 14, 25, 19, '你说：看哪，我打败了以东人，你就心高气傲，以致矜夸。你在家里安居就罢了，为何要惹祸使自己和犹大国一同败亡呢？'),
('CUV', '历代志下', 14, 25, 20, '亚玛谢却不肯听从。这是出乎神，好将他们交在敌人手里，因为他们寻求以东的神。'),
('CUV', '历代志下', 14, 25, 21, '于是以色列王约阿施上来，在犹大的伯示麦与犹大王亚玛谢相见于战场。'),
('CUV', '历代志下', 14, 25, 22, '犹大人败在以色列人面前，各自逃回家里去了。'),
('CUV', '历代志下', 14, 25, 23, '以色列王约阿施在伯示麦擒住约哈斯(就是亚哈谢)的孙子、约阿施的儿子、犹大王亚玛谢，将他带到耶路撒冷，又拆毁耶路撒冷的城墙，从以法莲门直到角门，共四百肘；'),
('CUV', '历代志下', 14, 25, 24, '又将俄别以东所看守神殿里的一切金银和器皿，与王宫里的财宝都拿了去，并带人去为质，就回撒玛利亚去了。'),
('CUV', '历代志下', 14, 25, 25, '以色列王约哈斯的儿子约阿施死后，犹大王约阿施的儿子亚玛谢又活了十五年。'),
('CUV', '历代志下', 14, 25, 26, '亚玛谢其余的事，自始至终不都写在犹大和以色列诸王记上么？'),
('CUV', '历代志下', 14, 25, 27, '自从亚玛谢离弃耶和华之后，在耶路撒冷有人背叛他，他就逃到拉吉；叛党却打发人到拉吉，将他杀了。'),
('CUV', '历代志下', 14, 25, 28, '人就用马将他的尸首驮回，葬在犹大京城他列祖的坟地里。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 26, 1, '犹大众民立亚玛谢的儿子乌西雅(又名亚撒利雅)接续他父作王，那时他年十六岁。'),
('CUV', '历代志下', 14, 26, 2, '〈亚玛谢与他列祖同睡之后，乌西雅收回以禄仍归犹大，又重新修理。〉'),
('CUV', '历代志下', 14, 26, 3, '乌西雅登基的时候年十六岁，在耶路撒冷作王五十二年。他母亲名叫耶可利雅，是耶路撒冷人。'),
('CUV', '历代志下', 14, 26, 4, '乌西雅行耶和华眼中看为正的事，效法他父亚玛谢一切所行的；'),
('CUV', '历代志下', 14, 26, 5, '通晓神默示，撒迦利亚在世的时候，乌西雅定意寻求神；他寻求耶和华，神就使他亨通。'),
('CUV', '历代志下', 14, 26, 6, '他出去攻击非利士人，拆毁了迦特城、雅比尼城，和亚实突城；在非利士人中，在亚实突境内，又建筑了些城。'),
('CUV', '历代志下', 14, 26, 7, '神帮助他攻击非利士人和住在姑珥巴力的亚拉伯人，并米乌尼人。'),
('CUV', '历代志下', 14, 26, 8, '亚扪人给乌西雅进贡。他的名声传到埃及，因他甚是强盛。'),
('CUV', '历代志下', 14, 26, 9, '乌西雅在耶路撒冷的角门和谷门，并城墙转弯之处，建筑城楼，且甚坚固；'),
('CUV', '历代志下', 14, 26, 10, '又在旷野与高原和平原，建筑望楼，挖了许多井，因他的牲畜甚多；又在山地和佳美之地，有农夫和修理葡萄园的人，因为他喜悦农事。'),
('CUV', '历代志下', 14, 26, 11, '乌西雅又有军兵，照书记耶利和官长玛西雅所数点的，在王的一个将军哈拿尼雅手下，分队出战。'),
('CUV', '历代志下', 14, 26, 12, '族长、大能勇士的总数共有二千六百人，'),
('CUV', '历代志下', 14, 26, 13, '他们手下的军兵共有三十万七千五百人，都有大能，善于争战，帮助王攻击仇敌。'),
('CUV', '历代志下', 14, 26, 14, '乌西雅为全军预备盾牌、枪、盔、甲、弓，和甩石的机弦，'),
('CUV', '历代志下', 14, 26, 15, '又在耶路撒冷使巧匠做机器，安在城楼和角楼上，用以射箭发石。乌西雅的名声传到远方；因为他得了非常的帮助，甚是强盛。'),
('CUV', '历代志下', 14, 26, 16, '他既强盛，就心高气傲，以致行事邪僻，干犯耶和华─他的神，进耶和华的殿，要在香坛上烧香。'),
('CUV', '历代志下', 14, 26, 17, '祭司亚撒利雅率领耶和华勇敢的祭司八十人，跟随他进去。'),
('CUV', '历代志下', 14, 26, 18, '他们就阻挡乌西雅王，对他说：乌西雅啊，给耶和华烧香不是你的事，乃是亚伦子孙承接圣职祭司的事。你出圣殿罢！因为你犯了罪。你行这事，耶和华神必不使你得荣耀。'),
('CUV', '历代志下', 14, 26, 19, '乌西雅就发怒，手拿香炉要烧香。他向祭司发怒的时候，在耶和华殿中香坛旁众祭司面前，额上忽然发出大痲疯。'),
('CUV', '历代志下', 14, 26, 20, '大祭司亚撒利雅和众祭司观看，见他额上发出大痲疯，就催他出殿；他自己也急速出去，因为耶和华降灾与他。'),
('CUV', '历代志下', 14, 26, 21, '乌西雅王长大痲疯直到死日，因此住在别的宫里，与耶和华的殿隔绝。他儿子约坦管理家事，治理国民。'),
('CUV', '历代志下', 14, 26, 22, '乌西雅其余的事，自始至终都是亚摩斯的儿子先知以赛亚所记的。'),
('CUV', '历代志下', 14, 26, 23, '乌西雅与他列祖同睡，葬在王陵的田间他列祖的坟地里；因为人说，他是长大痲疯的。他儿子约坦接续他作王。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 27, 1, '约坦登基的时候年二十五岁，在耶路撒冷作王十六年，他母亲名叫耶路沙，是撒督的女儿。'),
('CUV', '历代志下', 14, 27, 2, '约坦行耶和华眼中看为正的事，效法他父乌西雅一切所行的，只是不入耶和华的殿。百姓还行邪僻的事。'),
('CUV', '历代志下', 14, 27, 3, '约坦建立耶和华殿的上门，在俄斐勒城上多有建造，'),
('CUV', '历代志下', 14, 27, 4, '又在犹大山地建造城邑，在树林中建筑营寨和高楼。'),
('CUV', '历代志下', 14, 27, 5, '约坦与亚扪人的王打仗胜了他们，当年他们进贡银一百他连得，小麦一万歌珥，大麦一万歌珥；第二年、第三年也是这样。'),
('CUV', '历代志下', 14, 27, 6, '约坦在耶和华─他神面前行正道，以致日渐强盛。'),
('CUV', '历代志下', 14, 27, 7, '约坦其余的事和一切争战，并他的行为，都写在以色列和犹大列王记上。'),
('CUV', '历代志下', 14, 27, 8, '他登基的时候年二十五岁，在耶路撒冷作王十六年。'),
('CUV', '历代志下', 14, 27, 9, '约坦与他列祖同睡，葬在大卫城里。他儿子亚哈斯接续他作王。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 28, 1, '亚哈斯登基的时候年二十岁，在耶路撒冷作王十六年；不像他祖大卫行耶和华眼中看为正的事，'),
('CUV', '历代志下', 14, 28, 2, '却行以色列诸王的道，又铸造巴力的像，'),
('CUV', '历代志下', 14, 28, 3, '并且在欣嫩子谷烧香，用火焚烧他的儿女，行耶和华在以色列人面前所驱逐的外邦人那可憎的事；'),
('CUV', '历代志下', 14, 28, 4, '并在邱坛上、山冈上、各青翠树下献祭烧香。'),
('CUV', '历代志下', 14, 28, 5, '所以，耶和华─他的神将他交在亚兰王手里。亚兰王打败他，掳了他许多的民，带到大马色去。神又将他交在以色列王手里，以色列王向他大行杀戮。'),
('CUV', '历代志下', 14, 28, 6, '利玛利的儿子比加一日杀了犹大人十二万，都是勇士，因为他们离弃了耶和华─他们列祖的神。'),
('CUV', '历代志下', 14, 28, 7, '有一个以法莲中的勇士，名叫细基利，杀了王的儿子玛西雅和管理王宫的押斯利甘，并宰相以利加拿。'),
('CUV', '历代志下', 14, 28, 8, '以色列人掳了他们的弟兄，连妇人带儿女共有二十万，又掠了许多的财物，带到撒玛利亚去了。'),
('CUV', '历代志下', 14, 28, 9, '但那里有耶和华的一个先知，名叫俄德，出来迎接往撒玛利亚去的军兵，对他们说：因为耶和华─你们列祖的神恼怒犹大人，所以将他们交在你们手里，你们竟怒气冲天，大行杀戮。'),
('CUV', '历代志下', 14, 28, 10, '如今你们又有意强逼犹大人和耶路撒冷人作你们的奴婢，你们岂不也有得罪耶和华─你们神的事么？'),
('CUV', '历代志下', 14, 28, 11, '现在你们当听我说，要将掳来的弟兄释放回去，因为耶和华向你们已经大发烈怒。'),
('CUV', '历代志下', 14, 28, 12, '于是，以法莲人的几个族长─就是约哈难的儿子亚撒利雅、米实利末的儿子比利家、沙龙的儿子耶希西家、哈得莱的儿子亚玛撒─起来拦挡出兵回来的人，'),
('CUV', '历代志下', 14, 28, 13, '对他们说：你们不可带进这被掳的人来！你们想要使我们得罪耶和华，加增我们的罪恶过犯？因为我们的罪过甚大，已经有烈怒临到以色列人了。'),
('CUV', '历代志下', 14, 28, 14, '于是带兵器的人将掳来的人口和掠来的财物都留在众首领和会众的面前。'),
('CUV', '历代志下', 14, 28, 15, '以上提名的那些人就站起，使被掳的人前来；其中有赤身的，就从所掠的财物中拿出衣服和鞋来，给他们穿，又给他们吃喝，用膏抹他们；其中有软弱的，就使他们骑驴，送到棕树城耶利哥他们弟兄那里；随后就回撒玛利亚去了。'),
('CUV', '历代志下', 14, 28, 16, '那时，亚哈斯王差遣人去见亚述诸王，求他们帮助；'),
('CUV', '历代志下', 14, 28, 17, '因为以东人又来攻击犹大，掳掠子民。'),
('CUV', '历代志下', 14, 28, 18, '非利士人也来侵占高原和犹大南方的城邑，取了伯示麦、亚雅仑、基低罗，梭哥和属梭哥的乡村，亭纳和属亭纳的乡村，瑾锁和属瑾锁的乡村，就住在那里。'),
('CUV', '历代志下', 14, 28, 19, '因为以色列王亚哈斯在犹大放肆，大大干犯耶和华，所以耶和华使犹大卑微。'),
('CUV', '历代志下', 14, 28, 20, '亚述王提革拉毗尼色上来，却没有帮助他，反倒欺凌他。'),
('CUV', '历代志下', 14, 28, 21, '亚哈斯从耶和华殿里和王宫中，并首领家内所取的财宝给了亚述王，这也无济于事。'),
('CUV', '历代志下', 14, 28, 22, '这亚哈斯王在急难的时候，越发得罪耶和华。'),
('CUV', '历代志下', 14, 28, 23, '他祭祀攻击他的大马色之神，说：因为亚兰王的神帮助他们，我也献祭与他，他好帮助我。但那些神使他和以色列众人败亡了。'),
('CUV', '历代志下', 14, 28, 24, '亚哈斯将神殿里的器皿都聚了来，毁坏了，且封锁耶和华殿的门；在耶路撒冷各处的拐角建筑祭坛，'),
('CUV', '历代志下', 14, 28, 25, '又在犹大各城建立邱坛，与别神烧香，惹动耶和华─他列祖神的怒气。'),
('CUV', '历代志下', 14, 28, 26, '亚哈斯其余的事和他的行为，自始至终都写在犹大和以色列诸王记上。'),
('CUV', '历代志下', 14, 28, 27, '亚哈斯与他列祖同睡，葬在耶路撒冷城里，没有送入以色列诸王的坟墓中。他儿子希西家接续他作王。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 29, 1, '希西家登基的时候年二十五岁，在耶路撒冷作王二十九年。他母亲名叫亚比雅，是撒迦利雅的女儿。'),
('CUV', '历代志下', 14, 29, 2, '希西家行耶和华眼中看为正的事，效法他祖大卫一切所行的。'),
('CUV', '历代志下', 14, 29, 3, '元年正月，开了耶和华殿的门，重新修理。'),
('CUV', '历代志下', 14, 29, 4, '他召众祭司和利未人来，聚集在东边的宽阔处，'),
('CUV', '历代志下', 14, 29, 5, '对他们说：利未人哪，当听我说：现在你们要洁净自己，又洁净耶和华─你们列祖神的殿，从圣所中除去污秽之物。'),
('CUV', '历代志下', 14, 29, 6, '我们列祖犯了罪，行耶和华─我们神眼中看为恶的事，离弃他，转脸背向他的居所，'),
('CUV', '历代志下', 14, 29, 7, '封锁廊门，吹灭灯火，不在圣所中向以色列神烧香，或献燔祭。'),
('CUV', '历代志下', 14, 29, 8, '因此，耶和华的忿怒临到犹大和耶路撒冷，将其中的人抛来抛去，令人惊骇、嗤笑，正如你们亲眼所见的。'),
('CUV', '历代志下', 14, 29, 9, '所以我们的祖宗倒在刀下，我们的妻子儿女也被掳掠。'),
('CUV', '历代志下', 14, 29, 10, '现在我心中有意与耶和华─以色列的神立约，好使他的烈怒转离我们。'),
('CUV', '历代志下', 14, 29, 11, '我的众子啊，现在不要懈怠；因为耶和华拣选你们站在他面前事奉他，与他烧香。'),
('CUV', '历代志下', 14, 29, 12, '于是，利未人哥辖的子孙、亚玛赛的儿子玛哈，亚撒利雅的儿子约珥；米拉利的子孙、亚伯底的儿子基士，耶哈利勒的儿子亚撒利雅；革顺的子孙、薪玛的儿子约亚，约亚的儿子伊甸；'),
('CUV', '历代志下', 14, 29, 13, '以利撒反的子孙申利和耶利；亚萨的子孙撒迦利雅和玛探雅；'),
('CUV', '历代志下', 14, 29, 14, '希幔的子孙耶歇和示每；耶杜顿的子孙示玛雅和乌薛；'),
('CUV', '历代志下', 14, 29, 15, '起来聚集他们的弟兄，洁净自己，照著王的吩咐、耶和华的命令，进去洁净耶和华的殿。'),
('CUV', '历代志下', 14, 29, 16, '祭司进入耶和华的殿要洁净殿，将殿中所有污秽之物搬到耶和华殿的院内，利未人接去，搬到外头汲沦溪边。'),
('CUV', '历代志下', 14, 29, 17, '从正月初一日洁净起，初八日到了耶和华的殿廊，用八日的工夫洁净耶和华的殿，到正月十六日才洁净完了。'),
('CUV', '历代志下', 14, 29, 18, '于是，他们晋见希西家王，说：我们已将耶和华的全殿和燔祭坛，并坛的一切器皿、陈设饼的桌子，与桌子的一切器皿都洁净了；'),
('CUV', '历代志下', 14, 29, 19, '并且亚哈斯王在位犯罪的时候所废弃的器皿，我们预备齐全，且洁净了，现今都在耶和华的坛前。'),
('CUV', '历代志下', 14, 29, 20, '希西家王清早起来，聚集城里的首领都上耶和华的殿；'),
('CUV', '历代志下', 14, 29, 21, '牵了七只公牛，七只公羊，七只羊羔，七只公山羊，要为国、为殿、为犹大人作赎罪祭。王吩咐亚伦的子孙众祭司，献在耶和华的坛上，'),
('CUV', '历代志下', 14, 29, 22, '就宰了公牛，祭司接血洒在坛上，宰了公羊，把血洒在坛上，又宰了羊羔，也把血洒在坛上；'),
('CUV', '历代志下', 14, 29, 23, '把那作赎罪祭的公山羊牵到王和会众面前，他们就按手在其上。'),
('CUV', '历代志下', 14, 29, 24, '祭司宰了羊，将血献在坛上作赎罪祭，为以色列众人赎罪，因为王吩咐将燔祭和赎罪祭为以色列众人献上。'),
('CUV', '历代志下', 14, 29, 25, '王又派利未人在耶和华殿中敲钹，鼓瑟，弹琴，乃照大卫和他先见迦得，并先知拿单所吩咐的，就是耶和华藉先知所吩咐的。'),
('CUV', '历代志下', 14, 29, 26, '利未人拿大卫的乐器，祭司拿号，一同站立。'),
('CUV', '历代志下', 14, 29, 27, '希西家吩咐在坛上献燔祭，燔祭一献，就唱赞美耶和华的歌，用号，并用以色列王大卫的乐器相和。'),
('CUV', '历代志下', 14, 29, 28, '会众都敬拜，歌唱的歌唱，吹号的吹号，如此直到燔祭献完了。'),
('CUV', '历代志下', 14, 29, 29, '献完了祭，王和一切跟随的人都俯伏敬拜。'),
('CUV', '历代志下', 14, 29, 30, '希西家王与众首领又吩咐利未人用大卫和先见亚萨的诗词颂赞耶和华；他们就欢欢喜喜地颂赞耶和华，低头敬拜。'),
('CUV', '历代志下', 14, 29, 31, '希西家说：你们既然归耶和华为圣，就要前来把祭物和感谢祭奉到耶和华殿里。会众就把祭物和感谢祭奉来，凡甘心乐意的也将燔祭奉来。'),
('CUV', '历代志下', 14, 29, 32, '会众所奉的燔祭如下：公牛七十只，公羊一百只，羊羔二百只，这都是作燔祭献给耶和华的；'),
('CUV', '历代志下', 14, 29, 33, '又有分别为圣之物，公牛六百只，绵羊三千只。'),
('CUV', '历代志下', 14, 29, 34, '但祭司太少，不能剥尽燔祭牲的皮，所以他们的弟兄利未人帮助他们，直等燔祭的事完了，又等别的祭司自洁了；因为利未人诚心自洁，胜过祭司。'),
('CUV', '历代志下', 14, 29, 35, '燔祭和平安祭牲的脂油，并燔祭同献的奠祭甚多。这样，耶和华殿中的事务俱都齐备了(或作就整顿了)。'),
('CUV', '历代志下', 14, 29, 36, '这事办的甚速，希西家和众民都喜乐，是因神为众民所预备的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 30, 1, '希西家差遣人去见以色列和犹大众人，又写信给以法莲和玛拿西人，叫他们到耶路撒冷耶和华的殿，向耶和华─以色列的神守逾越节；'),
('CUV', '历代志下', 14, 30, 2, '因为王和众首领，并耶路撒冷全会众已经商议，要在二月内守逾越节。'),
('CUV', '历代志下', 14, 30, 3, '正月(原文作那时)间他们不能守；因为自洁的祭司尚不敷用，百姓也没有聚集在耶路撒冷；'),
('CUV', '历代志下', 14, 30, 4, '王与全会众都以这事为善。'),
('CUV', '历代志下', 14, 30, 5, '于是定了命令，传遍以色列，从别是巴直到但，使他们都来，在耶路撒冷向耶和华─以色列的神守逾越节；因为照所写的例，守这节的不多了(或作因为民许久没有照所写的例守节了)。'),
('CUV', '历代志下', 14, 30, 6, '驿卒就把王和众首领的信，遵著王命传遍以色列和犹大。信内说：以色列人哪，你们当转向耶和华─亚伯拉罕、以撒、以色列的神，好叫他转向你们这脱离亚述王手的余民。'),
('CUV', '历代志下', 14, 30, 7, '你们不要效法你们列祖和你们的弟兄；他们干犯耶和华─他们列祖的神，以致耶和华丢弃他们，使他们败亡(或作令人惊骇)，正如你们所见的。'),
('CUV', '历代志下', 14, 30, 8, '现在不要像你们列祖硬著颈项，只要归顺耶和华，进入他的圣所，就是永远成圣的居所；又要事奉耶和华─你们的神，好使他的烈怒转离你们。'),
('CUV', '历代志下', 14, 30, 9, '你们若转向耶和华，你们的弟兄和儿女必在掳掠他们的人面前蒙怜恤，得以归回这地，因为耶和华─你们的神有恩典、施怜悯。你们若转向他，他必不转脸不顾你们。'),
('CUV', '历代志下', 14, 30, 10, '驿卒就由这城跑到那城，传遍了以法莲、玛拿西，直到西布伦。那里的人却戏笑他们，讥诮他们。'),
('CUV', '历代志下', 14, 30, 11, '然而亚设、玛拿西、西布伦中也有人自卑，来到耶路撒冷。'),
('CUV', '历代志下', 14, 30, 12, '神也感动犹大人，使他们一心遵行王与众首领凭耶和华之言所发的命令。'),
('CUV', '历代志下', 14, 30, 13, '二月，有许多人在耶路撒冷聚集，成为大会，要守除酵节。'),
('CUV', '历代志下', 14, 30, 14, '他们起来，把耶路撒冷的祭坛和烧香的坛尽都除去，抛在汲沦溪中。'),
('CUV', '历代志下', 14, 30, 15, '二月十四日，宰了逾越节的羊羔。祭司与利未人觉得惭愧，就洁净自己，把燔祭奉到耶和华殿中，'),
('CUV', '历代志下', 14, 30, 16, '遵著神人摩西的律法，照例站在自己的地方；祭司从利未人手里接过血来，洒在坛上。'),
('CUV', '历代志下', 14, 30, 17, '会中有许多人尚未自洁，所以利未人为一切不洁之人宰逾越节的羊羔，使他们在耶和华面前成为圣洁。'),
('CUV', '历代志下', 14, 30, 18, '以法莲、玛拿西、以萨迦、西布伦有许多人尚未自洁，他们却也吃逾越节的羔羊，不合所记录的定例。希西家为他们祷告说：凡专心寻求神，就是耶和华─他列祖之神的，虽不照著圣所洁净之礼自洁，求至善的耶和华也饶恕他。'),
('CUV', '历代志下', 14, 30, 19, 'a'),
('CUV', '历代志下', 14, 30, 20, '耶和华垂听希西家的祷告，就饶恕(原文作医治)百姓。'),
('CUV', '历代志下', 14, 30, 21, '在耶路撒冷的以色列人大大喜乐，守除酵节七日。利未人和祭司用响亮的乐器，日日颂赞耶和华。'),
('CUV', '历代志下', 14, 30, 22, '希西家慰劳一切善于事奉耶和华的利未人。于是众人吃节筵七日，又献平安祭，且向耶和华─他们列祖的神认罪。'),
('CUV', '历代志下', 14, 30, 23, '全会众商议，要再守节七日；于是欢欢喜喜地又守节七日。'),
('CUV', '历代志下', 14, 30, 24, '犹大王希西家赐给会众公牛一千只，羊七千只为祭物；众首领也赐给会众公牛一千只，羊一万只，并有许多的祭司洁净自己。'),
('CUV', '历代志下', 14, 30, 25, '犹大全会众、祭司、利未人，并那从以色列地来的会众和寄居的人，以及犹大寄居的人，尽都喜乐。'),
('CUV', '历代志下', 14, 30, 26, '这样，在耶路撒冷大有喜乐，自从以色列王大卫儿子所罗门的时候，在耶路撒冷没有这样的喜乐。'),
('CUV', '历代志下', 14, 30, 27, '那时，祭司、利未人起来，为民祝福。他们的声音蒙神垂听，他们的祷告达到天上的圣所。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 31, 1, '这事既都完毕，在那里的以色列众人就到犹大的城邑，打碎柱像，砍断木偶，又在犹大、便雅悯、以法莲、玛拿西遍地将邱坛和祭坛拆毁净尽。于是以色列众人各回各城，各归各地。'),
('CUV', '历代志下', 14, 31, 2, '希西家派定祭司利未人的班次，各按各职献燔祭和平安祭，又在耶和华殿(原文作营)门内事奉，称谢颂赞耶和华。'),
('CUV', '历代志下', 14, 31, 3, '王又从自己的产业中定出分来为燔祭，就是早晚的燔祭和安息日、月朔，并节期的燔祭，都是按耶和华律法上所载的；'),
('CUV', '历代志下', 14, 31, 4, '又吩咐住耶路撒冷的百姓将祭司、利未人所应得的分给他们，使他们专心遵守耶和华的律法。'),
('CUV', '历代志下', 14, 31, 5, '谕旨一出，以色列人就把初熟的五谷、新酒、油、蜜，和田地的出产多多送来，又把各物的十分之一送来的极多。'),
('CUV', '历代志下', 14, 31, 6, '住犹大各城的以色列人和犹大人也将牛羊的十分之一，并分别为圣归耶和华─他们神之物，就是十分取一之物，尽都送来，积成堆垒；'),
('CUV', '历代志下', 14, 31, 7, '从三月积起，到七月才完。'),
('CUV', '历代志下', 14, 31, 8, '希西家和众首领来，看见堆垒，就称颂耶和华，又为耶和华的民以色列人祝福。'),
('CUV', '历代志下', 14, 31, 9, '希西家向祭司、利未人查问这堆垒。'),
('CUV', '历代志下', 14, 31, 10, '撒督家的大祭司亚撒利雅回答说：自从民将供物送到耶和华殿以来，我们不但吃饱，且剩下的甚多；因为耶和华赐福给他的民，所剩下的才这样丰盛。'),
('CUV', '历代志下', 14, 31, 11, '希西家吩咐在耶和华殿里预备仓房，他们就预备了。'),
('CUV', '历代志下', 14, 31, 12, '他们诚心将供物和十分取一之物，并分别为圣之物，都搬入仓内。利未人歌楠雅掌管这事，他兄弟示每为副管。'),
('CUV', '历代志下', 14, 31, 13, '耶歇、亚撒细雅、拿哈、亚撒黑、耶利末、约撒拔、以列、伊斯玛基雅、玛哈、比拿雅都是督理，在歌楠雅和他兄弟示每的手下，是希西家王和管理神殿的亚撒利雅所派的。'),
('CUV', '历代志下', 14, 31, 14, '守东门的利未人音拿的儿子可利，掌管乐意献与神的礼物，发放献与耶和华的供物和至圣的物。'),
('CUV', '历代志下', 14, 31, 15, '在他手下有伊甸、岷雅岷、耶书亚、示玛雅、亚玛利雅、示迦尼雅，在祭司的各城里供紧要的职任，无论弟兄大小，都按著班次分给他们。'),
('CUV', '历代志下', 14, 31, 16, '按家谱，三岁以外的男丁，凡每日进耶和华殿、按班次供职的，也分给他；'),
('CUV', '历代志下', 14, 31, 17, '又按宗族家谱分给祭司，按班次职任分给二十岁以外的利未人，'),
('CUV', '历代志下', 14, 31, 18, '又按家谱计算，分给他们会中的妻子、儿女；因他们身供要职，自洁成圣。'),
('CUV', '历代志下', 14, 31, 19, '按名派定的人要把应得的分给亚伦子孙，住在各城郊野、祭司所有的男丁和一切载入家谱的利未人。'),
('CUV', '历代志下', 14, 31, 20, '希西家在犹大遍地这样办理，行耶和华─他神眼中看为善为正为忠的事。'),
('CUV', '历代志下', 14, 31, 21, '凡他所行的，无论是办神殿的事，是遵律法守诫命，是寻求他的神，都是尽心去行，无不亨通。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 32, 1, '这虔诚的事以后，亚述王西拿基立来侵入犹大，围困一切坚固城，想要攻破占据。'),
('CUV', '历代志下', 14, 32, 2, '希西家见西拿基立来，定意要攻打耶路撒冷，'),
('CUV', '历代志下', 14, 32, 3, '就与首领和勇士商议，塞住城外的泉源；他们就都帮助他。'),
('CUV', '历代志下', 14, 32, 4, '于是有许多人聚集，塞了一切泉源，并通流国中的小河，说：亚述王来，为何让他得著许多水呢？'),
('CUV', '历代志下', 14, 32, 5, '希西家力图自强，就修筑所有拆毁的城墙，高与城楼相齐；在城外又筑一城，坚固大卫城的米罗，制造了许多军器、盾牌；'),
('CUV', '历代志下', 14, 32, 6, '设立军长管理百姓，将他们招聚在城门的宽阔处，用话勉励他们，说：'),
('CUV', '历代志下', 14, 32, 7, '你们当刚强壮胆，不要因亚述王和跟随他的大军恐惧、惊慌；因为与我们同在的，比与他们同在的更大。'),
('CUV', '历代志下', 14, 32, 8, '与他们同在的是肉臂，与我们同在的是耶和华─我们的神，他必帮助我们，为我们争战。百姓就靠犹大王希西家的话，安然无惧了。'),
('CUV', '历代志下', 14, 32, 9, '此后，亚述王西拿基立和他的全军攻打拉吉，就差遣臣仆到耶路撒冷见犹大王希西家和一切在耶路撒冷的犹大人，说：'),
('CUV', '历代志下', 14, 32, 10, '亚述王西拿基立如此说：你们倚靠甚么，还在耶路撒冷受困呢？'),
('CUV', '历代志下', 14, 32, 11, '希西家对你们说耶和华─我们的神必救我们脱离亚述王的手，这不是诱惑你们，使你们受饥渴而死么？'),
('CUV', '历代志下', 14, 32, 12, '这希西家岂不是废去耶和华的邱坛和祭坛，吩咐犹大与耶路撒冷的人说你们当在一个坛前敬拜，在其上烧香么？'),
('CUV', '历代志下', 14, 32, 13, '我与我列祖向列邦所行的，你们岂不知道么？列邦的神何尝能救自己的国脱离我手呢？'),
('CUV', '历代志下', 14, 32, 14, '我列祖所灭的国，那些神中谁能救自己的民脱离我手呢？难道你们的神能救你们脱离我手么？'),
('CUV', '历代志下', 14, 32, 15, '所以你们不要叫希西家这样欺哄诱惑你们，也不要信他；因为没有一国一邦的神能救自己的民脱离我手和我列祖的手，何况你们的神更不能救你们脱离我的手。'),
('CUV', '历代志下', 14, 32, 16, '西拿基立的臣仆还有别的话毁谤耶和华神和他仆人希西家。'),
('CUV', '历代志下', 14, 32, 17, '西拿基立也写信毁谤耶和华─以色列的神说：列邦的神既不能救他的民脱离我手，希西家的神也不能救他的民脱离我手了。'),
('CUV', '历代志下', 14, 32, 18, '亚述王的臣仆用犹大言语向耶路撒冷城上的民大声呼叫，要惊吓他们，扰乱他们，以便取城。'),
('CUV', '历代志下', 14, 32, 19, '他们论耶路撒冷的神，如同论世上人手所造的神一样。'),
('CUV', '历代志下', 14, 32, 20, '希西家王和亚摩斯的儿子先知以赛亚因此祷告，向天呼求。'),
('CUV', '历代志下', 14, 32, 21, '耶和华就差遣一个使者进入亚述王营中，把所有大能的勇士和官长、将帅尽都灭了。亚述王满面含羞地回到本国，进了他神的庙中，有他亲生的儿子在那里用刀杀了他。'),
('CUV', '历代志下', 14, 32, 22, '这样，耶和华救希西家和耶路撒冷的居民脱离亚述王西拿基立的手，也脱离一切仇敌的手，又赐他们四境平安。'),
('CUV', '历代志下', 14, 32, 23, '有许多人到耶路撒冷，将供物献与耶和华，又将宝物送给犹大王希西家。此后，希西家在列邦人的眼中看为尊大。'),
('CUV', '历代志下', 14, 32, 24, '那时希西家病得要死，就祷告耶和华，耶和华应允他，赐他一个兆头。'),
('CUV', '历代志下', 14, 32, 25, '希西家却没有照他所蒙的恩报答耶和华；因他心里骄傲，所以忿怒要临到他和犹大并耶路撒冷。'),
('CUV', '历代志下', 14, 32, 26, '但希西家和耶路撒冷的居民觉得心里骄傲，就一同自卑，以致耶和华的忿怒在希西家的日子没有临到他们。'),
('CUV', '历代志下', 14, 32, 27, '希西家大有尊荣资财，建造府库，收藏金银、宝石、香料、盾牌，和各样的宝器，'),
('CUV', '历代志下', 14, 32, 28, '又建造仓房，收藏五谷、新酒，和油，又为各类牲畜盖棚立圈；'),
('CUV', '历代志下', 14, 32, 29, '并且建立城邑，还有许多的羊群牛群，因为神赐他极多的财产。'),
('CUV', '历代志下', 14, 32, 30, '这希西家也塞住基训的上源，引水直下，流在大卫城的西边。希西家所行的事尽都亨通。'),
('CUV', '历代志下', 14, 32, 31, '惟有一件事，就是巴比伦王差遣使者来见希西家，访问国中所现的奇事；这件事神离开他，要试验他，好知道他心内如何。'),
('CUV', '历代志下', 14, 32, 32, '希西家其余的事和他的善行都写在亚摩斯的儿子先知以赛亚的默示书上和犹大、以色列的诸王记上。'),
('CUV', '历代志下', 14, 32, 33, '希西家与他列祖同睡，葬在大卫子孙的高陵上。他死的时候，犹大人和耶路撒冷的居民都尊敬他。他儿子玛拿西接续他作王。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 33, 1, '玛拿西登基的时候年十二岁，在耶路撒冷作王五十五年。'),
('CUV', '历代志下', 14, 33, 2, '他行耶和华眼中看为恶的事，效法耶和华在以色列人面前赶出的外邦人那可憎的事，'),
('CUV', '历代志下', 14, 33, 3, '重新建筑他父希西家所拆毁的邱坛，又为巴力筑坛，做木偶，且敬拜事奉天上的万象，'),
('CUV', '历代志下', 14, 33, 4, '在耶和华的殿宇中筑坛─耶和华曾指著这殿说：我的名必永远在耶路撒冷。'),
('CUV', '历代志下', 14, 33, 5, '他在耶和华殿的两院中为天上的万象筑坛，'),
('CUV', '历代志下', 14, 33, 6, '并在欣嫩子谷使他的儿女经火，又观兆，用法术，行邪术，立交鬼的和行巫术的，多行耶和华眼中看为恶的事，惹动他的怒气，'),
('CUV', '历代志下', 14, 33, 7, '又在神殿内立雕刻的偶像。神曾对大卫和他儿子所罗门说：我在以色列各支派中所选择的耶路撒冷和这殿，必立我的名直到永远。'),
('CUV', '历代志下', 14, 33, 8, '以色列人若谨守遵行我藉摩西所吩咐他们的一切法度、律例、典章，我就不再使他们挪移离开我所赐给他们列祖之地。'),
('CUV', '历代志下', 14, 33, 9, '玛拿西引诱犹大和耶路撒冷的居民，以致他们行恶比耶和华在以色列人面前所灭的列国更甚。'),
('CUV', '历代志下', 14, 33, 10, '耶和华警戒玛拿西和他的百姓，他们却是不听。'),
('CUV', '历代志下', 14, 33, 11, '所以耶和华使亚述王的将帅来攻击他们，用铙钩钩住玛拿西，用铜链锁住他，带到巴比伦去。'),
('CUV', '历代志下', 14, 33, 12, '他在急难的时候，就恳求耶和华─他的神，且在他列祖的神面前极其自卑。'),
('CUV', '历代志下', 14, 33, 13, '他祈祷耶和华，耶和华就允准他的祈求，垂听他的祷告，使他归回耶路撒冷，仍坐国位。玛拿西这才知道惟独耶和华是神。'),
('CUV', '历代志下', 14, 33, 14, '此后，玛拿西在大卫城外，从谷内基训西边直到鱼门口，建筑城墙，环绕俄斐勒，这墙筑得甚高；又在犹大各坚固城内设立勇敢的军长；'),
('CUV', '历代志下', 14, 33, 15, '并除掉外邦人的神像与耶和华殿中的偶像，又将他在耶和华殿的山上和耶路撒冷所筑的各坛都拆毁抛在城外；'),
('CUV', '历代志下', 14, 33, 16, '重修耶和华的祭坛，在坛上献平安祭、感谢祭，吩咐犹大人事奉耶和华─以色列的神。'),
('CUV', '历代志下', 14, 33, 17, '百姓却仍在邱坛上献祭，只献给耶和华─他们的神。'),
('CUV', '历代志下', 14, 33, 18, '玛拿西其余的事和祷告他神的话，并先见奉耶和华─以色列神的名警戒他的言语，都写在以色列诸王记上。'),
('CUV', '历代志下', 14, 33, 19, '他的祷告，与神怎样应允他，他未自卑以前的罪愆过犯，并在何处建筑邱坛，设立亚舍拉和雕刻的偶像，都写在何赛的书上。'),
('CUV', '历代志下', 14, 33, 20, '玛拿西与他列祖同睡，葬在自己的宫院里。他儿子亚们接续他作王。'),
('CUV', '历代志下', 14, 33, 21, '亚们登基的时候年二十二岁，在耶路撒冷作王二年。'),
('CUV', '历代志下', 14, 33, 22, '他行耶和华眼中看为恶的事，效法他父玛拿西所行的，祭祀事奉他父玛拿西所雕刻的偶像，'),
('CUV', '历代志下', 14, 33, 23, '不在耶和华面前像他父玛拿西自卑。这亚们所犯的罪越犯越大。'),
('CUV', '历代志下', 14, 33, 24, '他的臣仆背叛，在宫里杀了他。'),
('CUV', '历代志下', 14, 33, 25, '但国民杀了那些背叛亚们王的人，立他儿子约西亚接续他作王。')
on conflict (version, book, chapter, verse) do nothing;
